def _project_documentation(filename: str) -> str:
    return Path(__file__).with_name(filename).read_text(encoding="utf-8")


def _paths_equivalent(a: Path, b: Path) -> bool:
    """True when a and b name the same filesystem location.

    Tolerates Windows 8.3 short-name aliases (RUNNER~1 vs runneradmin) and
    incidental path spelling by comparing filesystem identity for existing
    targets, and canonicalizing the existing parent for non-existent targets.
    """
    pa, pb = Path(a), Path(b)
    try:
        return os.path.samefile(pa, pb)
    except OSError:
        try:
            return os.path.realpath(pa) == os.path.realpath(pb)
        except OSError:
            return os.path.normcase(str(pa)) == os.path.normcase(str(pb))

def _independent_display_datetime(value: str | None) -> str:
    """Derive the local display for a UTC ISO timestamp independently.

    Mirrors velox.format_display_datetime's conversion (parse, astimezone,
    format) without calling that helper, so an assertion can verify the local
    tooltip date against the fixture timestamp on any host timezone.
    """
    raw = str(value or "").strip()
    if not raw:
        return ""
    try:
        normalized = raw.replace("Z", "+00:00")
        dt = datetime.fromisoformat(normalized)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        local = dt.astimezone()
        return f"{local.strftime('%B')} {local.day} {local.year}, {local.strftime('%H:%M')}"
    except Exception:
        return raw

def _create_fixture_symlink(link: Path, target: Path) -> None:
    """Create a fixture symlink, skipping only when native privilege is absent."""
    try:
        link.symlink_to(target)
    except OSError as exc:
        if getattr(exc, "winerror", None) == 1314:
            raise unittest.SkipTest("symlink privilege not held (WinError 1314)")
        raise



class _TestDummyFont:
    """Deterministic font metrics for layout tests."""

    def __init__(self, line_h: int = 20, char_w: int = 8):
        self.line_h = int(line_h)
        self.font_size = int(line_h)
        self.char_w = int(char_w)
        self.baseline_px = max(1, min(self.line_h, int(round(self.line_h * 0.78))))
        self.glyphs: dict[str, Any] = {}
        self.texture = None
        self.font_face = "Dummy"
        self.font_role = "Sans"

    def text_width(self, text: str) -> int:
        return len(str(text or "")) * self.char_w

    def measure_text(self, text: str) -> int:
        return self.text_width(text)


class _DataRootsIsolatedTestMixin:
    """Reset strict data-root state around tests that touch durable storage."""

    def setUp(self) -> None:
        velox.DATA_ROOTS.clear_for_tests()

    def tearDown(self) -> None:
        velox.DATA_ROOTS.clear_for_tests()


class _AppLogDataRootsIsolatedTestMixin(_DataRootsIsolatedTestMixin):
    """Flush queued diagnostics before removing disposable data roots."""

    def tearDown(self) -> None:
        velox.APP_LOG_WRITER.flush(timeout=3.0)
        super().tearDown()


class _WriterDataRootsIsolatedTestMixin(_DataRootsIsolatedTestMixin):
    """Drain both background writers before removing disposable data roots."""

    def tearDown(self) -> None:
        velox.CHAT_STREAM_SNAPSHOT_WRITER.clear_for_tests()
        velox.APP_LOG_WRITER.clear_for_tests()
        super().tearDown()


def _make_test_storage(root: Path) -> velox.Storage:
    storage = velox.Storage(velox.AppPaths(root))
    storage.ensure_first_run_files()
    return storage


def _drain_storage_log_writer(storage: velox.Storage) -> None:
    """Flush and release the app-log writer for this storage's log path.

    Run before a data-root TemporaryDirectory is removed on Windows so an open
    log.jsonl handle cannot make rmtree fail with WinError 32. A path-scoped
    drain is attempted first; only if it times out is a bounded global drain
    used, and its result is checked too. On any failed drain this raises rather
    than silently clearing the data-root registrations.
    """
    try:
        log_path = Path(storage.log_path())
    except Exception:
        log_path = None
    if log_path is not None:
        if not velox.APP_LOG_WRITER.flush((log_path,), timeout=3.0):
            if not velox.APP_LOG_WRITER.flush(timeout=3.0):
                raise RuntimeError(
                    f"app-log writer did not drain {log_path} before teardown"
                )
    velox.DATA_ROOTS.clear_for_tests()


