class PlainAtomicWriteBytesTests(unittest.TestCase):
    """Regression coverage for the preservative atomic byte-write helper."""

    def _assert_no_temp_files(self, target: Path) -> None:
        leftovers = list(Path(target).parent.glob(Path(target).name + ".tmp.*"))
        self.assertEqual(leftovers, [])

    def test_successful_replace_and_first_creation(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            target = root / "state.json"
            target.write_bytes(b"before")
            velox._plain_atomic_write_bytes(target, b"after")
            self.assertEqual(target.read_bytes(), b"after")
            self._assert_no_temp_files(target)

            fresh = root / "fresh.json"
            velox._plain_atomic_write_bytes(fresh, b"seed")
            self.assertEqual(fresh.read_bytes(), b"seed")
            self._assert_no_temp_files(fresh)

    def test_partial_temp_write_then_exception_keeps_prior_target(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            target = root / "state.json"
            target.write_bytes(b"before")

            def partial_write(handle: Any, data: bytes) -> int:
                handle.write(data[:3])
                raise OSError("write failed mid-stream")

            with mock.patch.object(velox, "_write_all_bytes", side_effect=partial_write):
                with self.assertRaises(OSError):
                    velox._plain_atomic_write_bytes(target, b"abcdefgh")
            self.assertEqual(target.read_bytes(), b"before")
            self._assert_no_temp_files(target)

            fresh = root / "fresh.json"
            with mock.patch.object(velox, "_write_all_bytes", side_effect=partial_write):
                with self.assertRaises(OSError):
                    velox._plain_atomic_write_bytes(fresh, b"abcdefgh")
            self.assertFalse(fresh.exists())
            self._assert_no_temp_files(fresh)

    def test_short_write_without_exception_is_rejected(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            target = root / "state.json"
            target.write_bytes(b"before")

            def short_write(handle: Any, data: bytes) -> int:
                handle.write(data[:4])
                return 4

            with mock.patch.object(velox, "_write_all_bytes", side_effect=short_write):
                with self.assertRaises(OSError):
                    velox._plain_atomic_write_bytes(target, b"abcdefgh")
            self.assertEqual(target.read_bytes(), b"before")
            self._assert_no_temp_files(target)

            fresh = root / "fresh.json"
            with mock.patch.object(velox, "_write_all_bytes", side_effect=short_write):
                with self.assertRaises(OSError):
                    velox._plain_atomic_write_bytes(fresh, b"abcdefgh")
            self.assertFalse(fresh.exists())
            self._assert_no_temp_files(fresh)

    def test_write_all_bytes_loops_over_short_underlying_writes(self) -> None:
        class ShortHandle:
            def __init__(self) -> None:
                self.collected = bytearray()

            def write(self, chunk: bytes) -> int:
                part = bytes(chunk[:2])
                self.collected += part
                return len(part)

        handle = ShortHandle()
        payload = b"0123456789abcdef"
        written = velox._write_all_bytes(handle, payload)
        self.assertEqual(written, len(payload))
        self.assertEqual(bytes(handle.collected), payload)

    def test_flush_failure_aborts_before_replace(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            target = root / "state.json"
            target.write_bytes(b"before")
            real_open = Path.open

            class FlushFailHandle:
                def __init__(self, raw: Any) -> None:
                    self._raw = raw

                def __enter__(self) -> "FlushFailHandle":
                    return self

                def __exit__(self, *exc: Any) -> None:
                    self._raw.close()

                def write(self, chunk: bytes) -> int:
                    return self._raw.write(chunk)

                def fileno(self) -> int:
                    return self._raw.fileno()

                def flush(self) -> None:
                    self._raw.flush()
                    raise OSError("flush failed")

            def flush_fail_open(self, mode: str = "r", *args: Any, **kwargs: Any) -> Any:
                raw = real_open(self, mode, *args, **kwargs)
                if mode == "wb":
                    return FlushFailHandle(raw)
                return raw

            with mock.patch.object(Path, "open", flush_fail_open):
                with self.assertRaises(OSError):
                    velox._plain_atomic_write_bytes(target, b"after")
            self.assertEqual(target.read_bytes(), b"before")
            self._assert_no_temp_files(target)

    def test_fsync_failure_aborts_before_replace(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            target = root / "state.json"
            target.write_bytes(b"before")
            with mock.patch("os.fsync", side_effect=OSError("fsync failed")):
                with self.assertRaises(OSError):
                    velox._plain_atomic_write_bytes(target, b"after")
            self.assertEqual(target.read_bytes(), b"before")
            self._assert_no_temp_files(target)

    def test_permanent_replace_failure_propagates_without_fallback(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            target = root / "state.json"
            target.write_bytes(b"before")

            def permanent_failure(src: Any, dst: Any) -> None:
                raise OSError("permanent failure")

            opened: list[tuple[str, str]] = []
            real_open = Path.open

            def recording_open(self, mode: str = "r", *args: Any, **kwargs: Any) -> Any:
                opened.append((str(self), mode))
                return real_open(self, mode, *args, **kwargs)

            with mock.patch("os.replace", side_effect=permanent_failure), \
                 mock.patch.object(Path, "open", recording_open):
                with self.assertRaises(OSError) as cm:
                    velox._plain_atomic_write_bytes(target, b"after")
            self.assertEqual(target.read_bytes(), b"before")
            self.assertIn("permanent failure", str(cm.exception))
            self.assertFalse(any(p == str(target) and m == "wb" for p, m in opened))
            self.assertTrue(any(".tmp." in p and m == "wb" for p, m in opened))
            self._assert_no_temp_files(target)

    def test_transient_replace_failures_then_success(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            target = root / "state.json"
            target.write_bytes(b"before")
            real_replace = os.replace
            calls = {"count": 0}

            def transient_until_success(src: Any, dst: Any) -> None:
                calls["count"] += 1
                if calls["count"] <= 2:
                    error = OSError("sharing violation")
                    error.winerror = 32
                    raise error
                real_replace(src, dst)

            with mock.patch("os.replace", side_effect=transient_until_success), \
                 mock.patch("time.sleep", lambda *a, **k: None):
                velox._plain_atomic_write_bytes(target, b"after")
            self.assertEqual(target.read_bytes(), b"after")
            self.assertEqual(calls["count"], 3)
            self._assert_no_temp_files(target)

    def test_exhausted_transient_retries_leave_prior_target_intact(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            target = root / "state.json"
            target.write_bytes(b"before")

            def always_transient(src: Any, dst: Any) -> None:
                error = OSError("sharing violation")
                error.winerror = 32
                raise error

            opened: list[tuple[str, str]] = []
            real_open = Path.open

            def recording_open(self, mode: str = "r", *args: Any, **kwargs: Any) -> Any:
                opened.append((str(self), mode))
                return real_open(self, mode, *args, **kwargs)

            with mock.patch("os.replace", side_effect=always_transient), \
                 mock.patch("time.sleep", lambda *a, **k: None), \
                 mock.patch.object(Path, "open", recording_open):
                with self.assertRaises(OSError):
                    velox._plain_atomic_write_bytes(target, b"after", retries=3)
            self.assertEqual(target.read_bytes(), b"before")
            self.assertFalse(any(p == str(target) and m == "wb" for p, m in opened))
            self.assertTrue(any(".tmp." in p and m == "wb" for p, m in opened))
            self._assert_no_temp_files(target)

    def test_secondary_temp_cleanup_failure_preserves_primary_error(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            target = root / "state.json"
            target.write_bytes(b"before")

            def permanent_failure(src: Any, dst: Any) -> None:
                raise OSError("primary replace failure")

            real_unlink = Path.unlink

            def failing_unlink(self, *args: Any, **kwargs: Any) -> None:
                if Path(self).name.startswith(Path(target).name + ".tmp."):
                    raise OSError("cleanup failure")
                real_unlink(self, *args, **kwargs)

            with mock.patch("os.replace", side_effect=permanent_failure), \
                 mock.patch.object(Path, "unlink", failing_unlink):
                with self.assertRaises(OSError) as cm:
                    velox._plain_atomic_write_bytes(target, b"after")
            self.assertEqual(target.read_bytes(), b"before")
            self.assertIn("primary replace failure", str(cm.exception))
            self.assertNotIn("cleanup failure", str(cm.exception))


class ApplicationTests(_DataRootsIsolatedTestMixin, unittest.TestCase):
    """Chat, endpoint, Skill, terminal, agent, tool and UI contracts."""


    def _chat(self, root: Path, name: str = "Test Chat") -> tuple[AppPaths, Storage, ChatStore, dict[str, Any]]:
        paths, storage, chats = _make_test_chat_stack(root)
        chat = chats.create_chat(name)
        return paths, storage, chats, chat

    @staticmethod
    def _source() -> str:
        return application_source()


    @staticmethod
    def _method_source(owner: type[Any], name: str) -> str:
        """Return the current method source, falling back to its AST location.

        Refreshing code in a long-lived process can leave inspect's line cache
        stale. Verify the member name before trusting the returned slice."""
        expected = f"def {name}("
        try:
            value = inspect.getsource(getattr(owner, name))
            if expected in value:
                return value
        except (OSError, TypeError):
            pass
        source = application_source()
        tree = ast.parse(source)
        for node in tree.body:
            if not isinstance(node, ast.ClassDef) or node.name != owner.__name__:
                continue
            for member in node.body:
                if isinstance(member, (ast.FunctionDef, ast.AsyncFunctionDef)) and member.name == name:
                    lines = source.splitlines(keepends=True)
                    end_lineno = int(getattr(member, "end_lineno", member.lineno))
                    return "".join(lines[member.lineno - 1:end_lineno])
        raise AttributeError(f"Could not locate source for {owner.__name__}.{name}")

    @staticmethod
    def _write_chat_summary(paths: AppPaths, chat_id: str, text: str, one: str = "") -> None:
        summary = velox.default_chat_summary(chat_id)
        summary.update({
            "updated_at": velox.now_iso(),
            "one_sentence_summary": one or velox.one_sentence_from_summary(text),
            "bullet_summary_markdown": text,
            "summary_markdown": text,
            "stale": False,
        })
        velox.atomic_write_json(paths.chat_summary_json(chat_id), summary)

    @staticmethod
    def _set_chat_updated(paths: AppPaths, chats: ChatStore, chat_id: str, value: str) -> None:
        meta = velox.read_json(paths.chat_json(chat_id), {}) or {}
        meta["updated_at"] = value
        velox.atomic_write_json(paths.chat_json(chat_id), meta)
        chats._invalidate_list_cache()

    def _agent_stack(
        self,
        root: Path,
        llm: Any,
        *,
        monitor: LLMTaskMonitor | None = None,
    ) -> tuple[AppPaths, Storage, ChatStore, dict[str, Any], AgentStore, ToolRegistry, AgentRuntime]:
        paths, storage, chats, chat = self._chat(root)
        agents = velox.AgentStore(storage)
        tools = velox.ToolRegistry(storage)
        runtime = velox.AgentRuntime(
            storage,
            agents,
            chats,
            velox.ContextAssembler(paths),
            llm,
            tools,
            monitor,
        )
        tools.bind_agent_runtime(runtime)
        return paths, storage, chats, chat, agents, tools, runtime

    def test_application_metadata_and_navigation_destinations(self) -> None:
        self.assertEqual(velox.APP_VERSION, "velox.v303")
        self.assertEqual(velox.DATA_FILE_VERSION, "v303")
        self.assertNotIn("SUPPORTED_DATA_FILE_VERSIONS", vars(velox))
        self.assertNotIn("PREVIOUS_DATA_FILE_VERSION", vars(velox))
        self.assertNotIn("PREVIOUS_APP_SCHEMA", vars(velox))
        self.assertEqual(velox.CURRENT_PANEL_NAMES, frozenset({"chat", "calendar", "agents", "context", "vault", "settings"}))
        self.assertEqual(velox.normalize_active_panel("unknown"), "chat")
        self.assertEqual(velox.normalize_active_panel("agents"), "agents")
        self.assertEqual(velox.normalize_active_panel("calendar"), "calendar")
        self.assertEqual(velox.normalize_active_panel("vault"), "vault")
        self.assertEqual(velox.normalize_active_panel("context"), "context")
        self.assertEqual(velox.ROOT_DIR, Path.cwd().resolve())

        config = velox.default_config()
        llm = config["llm"]
        self.assertEqual(
            set(llm),
            {"default_profile_id", "endpoint_profiles", "comfy", "stall_detection_minutes"},
        )
        self.assertEqual(llm["default_profile_id"], velox.DEFAULT_DEEPSEEK_V4_FLASH_VISION_EXP_ENDPOINT_PROFILE_ID)
        self.assertEqual(config["chat"], {"auto_compaction_enabled": True})
        self.assertNotIn("fast_profile_id", llm)
        self.assertNotIn("smart_profile_id", llm)
        self.assertNotIn("accounts", config)
        self.assertEqual(velox.CREDENTIAL_FILE_SCHEMA, "velox_account_credentials.v1")
        self.assertEqual(velox.CREDENTIAL_XOR_BYTE, 0x77)
        agents = config["agents"]
        self.assertEqual(set(agents), {"timeout_minutes", "auto_compaction_enabled", "personal_assistant"})
        self.assertEqual(agents["timeout_minutes"], velox.AGENT_TIMEOUT_MINUTES_DEFAULT)
        self.assertTrue(agents["auto_compaction_enabled"])
        self.assertNotIn("persistence_enabled", agents)
        self.assertNotIn("persistence_max_prompts", agents)
        self.assertNotIn("persistence_enabled", agents["personal_assistant"])

        schemas = (
            velox.APP_SCHEMA, velox.RUNTIME_CONFIG_SCHEMA, velox.APP_STATE_SCHEMA, velox.TOOL_USAGE_STATS_SCHEMA,
            velox.CHAT_SCHEMA, velox.CHAT_SUMMARY_SCHEMA, velox.CHAT_TURN_SCHEMA, velox.AGENT_SCHEMA,
            velox.AGENT_EVENT_SCHEMA, velox.TOOL_CALL_SCHEMA, velox.TERMINAL_SCHEMA, velox.TERMINAL_EVENT_SCHEMA,
            velox.ATTACHMENT_SCHEMA, velox.TURN_STATS_SCHEMA, velox.USER_PROMPT_STATS_SCHEMA,
            velox.CALENDAR_EVENT_SCHEMA, velox.ITEM_SCHEMA, velox.WEEK_CHAT_MAP_SCHEMA, velox.CONTEXT_LINK_SCHEMA,
            velox.GOOGLE_CALENDAR_SYNC_SCHEMA, velox.VAULT_DATA_SOURCE_SCHEMA, velox.VAULT_CONTAINER_SCHEMA,
            velox.VAULT_ITEM_SCHEMA, velox.VAULT_PARTICIPANT_SCHEMA, velox.VAULT_ATTACHMENT_SCHEMA,
            velox.VAULT_SYNC_STATE_SCHEMA, velox.SCHEDULED_TASK_SCHEMA, velox.CONTEXT_DOC_SCHEMA,
            velox.CONTEXT_DOC_REVISION_SCHEMA, velox.EXPERT_MODE_SCHEMA,
        )
        self.assertTrue(all(value.endswith(".v303") for value in schemas))
        self.assertIn("Capabilities", velox.__doc__ or "")
        self.assertIn("Architecture", velox.__doc__ or "")
        for component in (velox.ChatRuntime, velox.AgentRuntime, velox.LLMClient, velox.ToolRegistry, velox.ChecklistStore):
            self.assertIn(component.__name__, velox.__doc__ or "")
        self.assertIn("python velox.py", velox.__doc__ or "")
        readme = _project_documentation("README.md")
        for section in ("## What it does", "## Run it", "## How it works", "## Tests"):
            self.assertIn(section, readme)
        self.assertIn("python test_velox.py", readme)
        self.assertIn("XOR obfuscation, not encryption", _project_documentation("SECURITY.md"))

    def test_chat_statistics_exclude_agents_and_use_one_alias_per_direction(self) -> None:
        turns = [
            {"role": "user", "stats": {"input_tokens": 999_999}},
            {"role": "assistant", "stats": {"input_tokens": 120, "prompt_tokens": 999, "output_tokens": 30, "completion_tokens": 888}},
            {"role": "assistant", "stats": {"prompt_eval_count": 80, "eval_count": 20}},
            {"role": "assistant", "stats": {"_estimated_prompt_tokens": 25, "approx_output_tokens": 7}},
            {"role": "tool", "stats": {"input_tokens": 1_000_000, "output_tokens": 1_000_000}},
        ]
        aggregate = velox.chat_thread_runtime_stats(turns)
        self.assertEqual((aggregate["input_tokens"], aggregate["output_tokens"]), (225, 57))
        header = self._method_source(velox.Panels, "draw_chat_thread_header")
        self.assertNotIn("token_text", header)
        self.assertIn("statistics_tooltip", header)
        self.assertIn("average_prompt_tokens_per_second", header)
        self.assertIn("average_generation_tokens_per_second", header)

    def test_chat_auto_compaction_persists_exact_context_and_gold_card(self) -> None:
        async def scenario(root: Path) -> None:
            class CompactionLLM:
                def __init__(self) -> None:
                    self.requests: list[LLMRequest] = []

                async def chat_completions_stream(self, request: LLMRequest):
                    self.requests.append(copy.deepcopy(request))
                    if request.max_output_tokens is not None:
                        yield velox.LLMChunk(reasoning_text="Select durable facts and preserve the active boundary.")
                        yield velox.LLMChunk(text=(
                            "- Preserve the selected endpoint, exact workspace paths, build commands, and the current "
                            "failure diagnosis. Keep the latest user constraints, successful tool findings, unresolved "
                            "implementation steps, and validation requirements. The current system prompt remains "
                            "authoritative, recent turns stay verbatim, and future work must continue from the newest "
                            "tool boundary without repeating completed work or recreating stale processes."
                        ))
                        yield velox.LLMChunk(
                            done=True, finish_reason="stop",
                            usage={"prompt_tokens": 4200, "completion_tokens": 96},
                        )
                    else:
                        yield velox.LLMChunk(text="Final answer generated from the compacted context.")
                        yield velox.LLMChunk(
                            done=True, finish_reason="stop",
                            usage={"prompt_tokens": 1800, "completion_tokens": 12},
                        )

            paths, storage, chats, chat = self._chat(root)
            cfg = storage.load_config()
            velox.endpoint_profile_ref(cfg, velox.DEFAULT_ENDPOINT_PROFILE_ID)["context_window_tokens"] = 8192
            storage.write_config(cfg)
            self.assertTrue(velox.chat_auto_compaction_enabled_from_config(storage.load_config()))

            for index in range(12):
                chats.append_turn(
                    velox.APP_SCOPE_ID, chat["chat_id"],
                    velox.make_turn(
                        chat["chat_id"], "user",
                        f"Historical user message {index}: " + ("U" * 1200),
                    ),
                )
                chats.append_turn(
                    velox.APP_SCOPE_ID, chat["chat_id"],
                    velox.make_turn(
                        chat["chat_id"], "assistant",
                        f"Historical assistant message {index}: " + ("A" * 1200),
                    ),
                )

            user_text = "Continue using the durable history."
            chats.append_turn(
                velox.APP_SCOPE_ID, chat["chat_id"], velox.make_turn(chat["chat_id"], "user", user_text),
            )
            placeholder = velox.make_turn(
                chat["chat_id"], "assistant", "", endpoint_profile_id="fast",
                endpoint_label="fast", status="streaming",
            )
            chats.append_turn(velox.APP_SCOPE_ID, chat["chat_id"], placeholder, mark_stale=False)
            fake = CompactionLLM()
            runtime = velox.ChatRuntime(
                storage, chats, velox.ContextAssembler(paths), fake, velox.ToolRegistry(storage),
            )
            await runtime._run_assistant_loop(
                velox.APP_SCOPE_ID, chat["chat_id"], placeholder["turn_id"], "fast",
                user_text, "Chat auto-compaction test",
            )

            turns = chats.load_turns(velox.APP_SCOPE_ID, chat["chat_id"])
            compaction = next(turn for turn in turns if turn.get("role") == "compaction")
            self.assertEqual(compaction["status"], "complete")
            self.assertEqual(compaction["compaction_meta"]["state"], "complete")
            self.assertLess(
                compaction["compaction_meta"]["after_tokens"],
                compaction["compaction_meta"]["before_tokens"],
            )
            self.assertNotIn("Select durable facts", compaction["compaction_summary"])
            self.assertIn("Select durable facts", compaction["compaction_details"])
            self.assertIn("EXACT MESSAGES SENT TO THE COMPACTION ENDPOINT", compaction["compaction_details"])
            self.assertIn("==================== EXACT NEXT MAIN LLM CONTEXT ====================", compaction["compaction_details"])
            self.assertEqual(compaction["compaction_messages"][0]["role"], "system")
            self.assertIn(
                compaction["compaction_messages"][0]["content"],
                compaction["compaction_details"],
            )
            self.assertGreater(compaction["stats"]["input_tokens"], 0)
            self.assertGreater(compaction["stats"]["output_tokens"], 0)
            self.assertEqual(len(fake.requests), 2)
            self.assertIsNotNone(fake.requests[0].max_output_tokens)
            self.assertIsNone(fake.requests[1].max_output_tokens)

            panel = velox.Panels.__new__(velox.Panels)
            panel.state = velox.UIState()
            sections = panel._chat_sections([compaction], True)
            self.assertEqual(len(sections), 1)
            self.assertEqual(sections[0]["kind"], "compaction")
            self.assertTrue(sections[0]["collapsed"])
            self.assertIn("Context compacted", sections[0]["text"])
            color_source = self._method_source(velox.Panels, "_section_colors")
            self.assertIn("Color(48, 34, 6)", color_source)
            self.assertIn("Color(255, 205, 96)", color_source)
            runtime.cancel_all()

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_visible_glyph_bounds_center_title_and_token_ink_not_baseline_box(self) -> None:
        glyph = type("GlyphStub", (), {"ah": 10, "y_offset": 4})()
        font = type("FontStub", (), {"line_h": 24, "glyphs": {"A": glyph, "?": glyph}, "fallback_map": {}})()
