    def test_agent_start_result_reinforces_no_poll_contract(self) -> None:
        class IdleLLM:
            async def chat_completions_stream(self, _request: LLMRequest):
                yield velox.LLMChunk(done=True)

        async def scenario(root: Path) -> None:
            _paths, _storage, _chats, chat, _agents, _tools, runtime = self._agent_stack(root, IdleLLM())
            result = await runtime.start_from_tool(
                velox.ToolContext(velox.APP_SCOPE_ID, chat_id=str(chat["chat_id"])),
                {"task": "Wait for a test signal.", "title": "No polling contract", "expert_mode": False},
            )
            self.assertIn("Do not query", result["message"])
            self.assertIn("automatically deliver", result["message"])
            runtime.cancel(str(result["agent_id"]))
            await runtime.shutdown()

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

