    def test_cross_instance_manifest_and_stale_chat_writes_preserve_newer_data(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            paths_a = velox.AppPaths(root)
            storage_a = velox.Storage(paths_a)
            storage_a.ensure_first_run_files()
            paths_b = velox.AppPaths(root)
            storage_b = velox.Storage(paths_b)
            storage_b.ensure_first_run_files()

            # Prime both per-instance caches, then interleave state and settings
            # writes. Each read/modify/write must use the newest disk manifest.
            config_a = storage_a.load_config()
            storage_b.load_config()
            storage_b.write_app_state({
                "active_chat_id": "from-b",
                "active_panel": "agents",
                "file_picker_last_dir": td,
            })
            config_a["history"]["first_message_context_max_chars"] = 23456
            storage_a.write_config(config_a)
            manifest = velox.read_json(paths_a.app_json_path, {})
            self.assertEqual(manifest["state"]["active_chat_id"], "from-b")
            self.assertEqual(manifest["settings"]["history"]["first_message_context_max_chars"], 23456)

            config_b = storage_b.load_config()
            config_b["web"]["default_search_results"] = 17
            storage_b.write_config(config_b)
            storage_a.write_app_state({
                "active_chat_id": "from-a",
                "active_panel": "chat",
                "file_picker_last_dir": td,
            })
            manifest = velox.read_json(paths_a.app_json_path, {})
            self.assertEqual(manifest["settings"]["web"]["default_search_results"], 17)
            self.assertEqual(manifest["state"]["active_chat_id"], "from-a")

            chats = velox.ChatStore(storage_a)
            chat = chats.create_chat("Original")
            stale = chats.load_chat(chat["chat_id"])
            storage_a.record_tool_usage("fs_read", True, chat_id=chat["chat_id"])
            stale["name"] = "Renamed from stale copy"
            chats.write_chat(stale)
            fresh = chats.load_chat(chat["chat_id"])
            self.assertEqual(fresh["name"], "Renamed from stale copy")
            self.assertEqual(fresh["stats"]["tool_calls_total"], 1)
            self.assertEqual(fresh["stats"]["tool_calls_by_type"]["fs_read"]["succeeded"], 1)

    def test_manifest_writes_keep_exact_schema_and_reject_unknown_state_fields(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            paths, storage, _chats = _make_test_chat_stack(Path(td))
            original = storage.load_config()

            extra = copy.deepcopy(original)
            extra["retired_section"] = {}
            with self.assertRaises(velox.UnsupportedDataVersionError):
                storage.write_config(extra)

            missing = copy.deepcopy(original)
            missing.pop("meshy")
            with self.assertRaises(velox.UnsupportedDataVersionError):
                storage.write_config(missing)

            nested_extra = copy.deepcopy(original)
            velox.endpoint_profile_ref(nested_extra, velox.DEFAULT_ENDPOINT_PROFILE_ID)["retired_timeout"] = 123
            with self.assertRaises(velox.UnsupportedDataVersionError):
                storage.write_config(nested_extra)
            nested_missing = copy.deepcopy(original)
            nested_missing["web"].pop("default_search_results")
            with self.assertRaises(velox.UnsupportedDataVersionError):
                storage.write_config(nested_missing)

            # Failed writes must leave a manifest that is still strictly loadable.
            self.assertEqual(storage.load_config(), original)
            with self.assertRaises(ValueError):
                storage.write_app_state({
                    "active_chat_id": "chat-1",
                    "active_panel": "settings",
                    "file_picker_last_dir": td,
                    "retired_workspace_id": "must-not-persist",
                })
            storage.write_app_state({
                "active_chat_id": "chat-1",
                "active_panel": "settings",
                "file_picker_last_dir": td,
            })
            manifest = velox.read_json(paths.app_json_path, {})
            self.assertEqual(set(manifest), set(velox.default_app_manifest()))
            self.assertEqual(set(manifest["state"]), set(velox.default_app_state()))
            self.assertNotIn("retired_workspace_id", manifest["state"])
            velox.Storage._validate_current_manifest(manifest)

    def test_settings_blank_click_commits_focused_numeric_draft(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            _paths, storage, _chats = _make_test_chat_stack(Path(td))
            panel = velox.Panels.__new__(velox.Panels)
            panel.services = type("ServicesStub", (), {"storage": storage})()
            panel.state = velox.UIState()
            persisted = storage.load_config()
            draft = panel._settings_config_to_draft(persisted)
            panel.state.config_draft = draft
            panel.state.settings_last_valid_config = copy.deepcopy(persisted)
            panel.state.settings_last_saved_config_json = json.dumps(persisted, ensure_ascii=False, sort_keys=True)

            draft["web"]["default_search_results"] = "999"
            panel.state.active_widget = "settings.web.default_search_results"
            panel.state.settings_last_active_widget = "settings.web.default_search_results"
            panel.state.text_drag_widget = "settings.web.default_search_results"
            panel.state.input.mouse_x = 50
            panel.state.input.mouse_y = 60
            panel.state.input.mouse_pressed = True
            panel.state.input.mouse_consumed = False
            self.assertTrue(panel._end_settings_text_focus_on_blank_click(velox.Rect(0, 0, 200, 200)))
            self.assertIsNone(panel.state.active_widget)
            self.assertIsNone(panel.state.text_drag_widget)
            self.assertTrue(panel.state.input.mouse_consumed)
            panel._autosave_settings_if_changed(draft)
            self.assertEqual(storage.load_config()["web"]["default_search_results"], 999)

            panel.state.active_widget = "settings.web.default_search_results"
            panel.state.input.mouse_consumed = True
            self.assertFalse(panel._end_settings_text_focus_on_blank_click(velox.Rect(0, 0, 200, 200)))
            self.assertEqual(panel.state.active_widget, "settings.web.default_search_results")
            panel.state.input.mouse_consumed = False
            panel.state.input.mouse_x = 500
            panel.state.input.mouse_y = 500
            self.assertFalse(panel._end_settings_text_focus_on_blank_click(velox.Rect(0, 0, 200, 200)))
            self.assertEqual(panel.state.active_widget, "settings.web.default_search_results")

    def test_store_cache_isolation_stats_preservation_and_atomic_turn_rewrites(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            paths, storage, chats, chat = self._chat(Path(td))
            chat_id = str(chat["chat_id"])

            first = chats.load_chat(chat_id)
            first["features"]["web_tools_enabled"] = False
            first["stats"]["tool_calls_by_type"]["fake"] = {"total": 1, "succeeded": 1, "failed": 0}
            fresh = chats.load_chat(chat_id)
            self.assertTrue(fresh["features"]["web_tools_enabled"])
            self.assertNotIn("fake", fresh["stats"]["tool_calls_by_type"])
            listed = chats.list_chats()
            listed[0]["features"]["web_tools_enabled"] = False
            self.assertTrue(chats.list_chats()[0]["features"]["web_tools_enabled"])

            stale_chat = chats.load_chat(chat_id)
            storage.record_tool_usage("fs_read", True, chat_id=chat_id)
            stale_chat["name"] = "Stale metadata rename"
            chats.write_chat(stale_chat)
            persisted_chat = chats.load_chat(chat_id)
            self.assertEqual(persisted_chat["name"], "Stale metadata rename")
            self.assertEqual(persisted_chat["stats"]["tool_calls_total"], 1)

            turns = [
                velox.make_turn(chat_id, "user", "one"),
                velox.make_turn(chat_id, "assistant", "two"),
                velox.make_turn(chat_id, "user", "three"),
            ]
            for turn in turns:
                chats.append_turn(velox.APP_SCOPE_ID, chat_id, turn, mark_stale=False)
            chats.update_turn(velox.APP_SCOPE_ID, chat_id, turns[1]["turn_id"], {"text": "two edited"})
            chats.delete_turn(velox.APP_SCOPE_ID, chat_id, turns[0]["turn_id"])
            kept = chats.truncate_after_turn(velox.APP_SCOPE_ID, chat_id, turns[1]["turn_id"], include_turn=True)
            self.assertEqual([row["turn_id"] for row in kept], [turns[1]["turn_id"]])
            raw_lines = [line for line in paths.chat_turns_jsonl(chat_id).read_text(encoding="utf-8").splitlines() if line]
            self.assertEqual(len(raw_lines), 1)
            self.assertEqual(json.loads(raw_lines[0])["text"], "two edited")
            self.assertEqual(chats.load_chat(chat_id)["stats"]["tool_calls_total"], 1)

            agents = velox.AgentStore(storage)
            agent = agents.create_agent(chat_id, "Check cache isolation.")
            agent_id = str(agent["agent_id"])
            cached_agent = agents.load_agent(agent_id)
            cached_agent["stats"]["tool_calls_by_type"]["fake"] = {"total": 1, "succeeded": 1, "failed": 0}
            self.assertNotIn("fake", agents.load_agent(agent_id)["stats"]["tool_calls_by_type"])
            listed_agents = agents.list_agents()
            listed_agents[0]["stats"]["tool_calls_by_type"]["fake"] = {"total": 1, "succeeded": 1, "failed": 0}
            self.assertNotIn("fake", agents.list_agents()[0]["stats"]["tool_calls_by_type"])
            stale_agent = agents.load_agent(agent_id)
            storage.record_tool_usage("time_now", True, chat_id=chat_id, agent_id=agent_id)
            stale_agent["title"] = "Stale agent title"
            agents.write_agent(stale_agent)
            persisted_agent = agents.load_agent(agent_id)
            self.assertEqual(persisted_agent["title"], "Stale agent title")
            self.assertEqual(persisted_agent["stats"]["tool_calls_total"], 1)
            self.assertEqual(persisted_agent["stats"]["tool_calls_by_type"]["time_now"]["succeeded"], 1)

    def test_other_schema_roots_are_rejected_without_mutation_and_credentials_remain_portable(self) -> None:
        for old_version in ("v246", "v243", "v141", "v140", "v138", "v137", "v136", "v133", "v130", "v117", "v99"):
            with self.subTest(old_version=old_version), tempfile.TemporaryDirectory() as td:
                root = Path(td)
                old = velox.default_app_manifest()
                old["schema"] = f"velox_app.{old_version}"
                old["data_version"] = old_version
                manifest_path = root / "app.json"
                original = json.dumps(old, ensure_ascii=False, indent=2).encode("utf-8")
                manifest_path.write_bytes(original)
                credential_path = root / "credentials" / "google_calendar.cred"
                credential_path.parent.mkdir(parents=True, exist_ok=True)
                credential_bytes = bytes((index * 17 + 3) % 256 for index in range(97))
                credential_path.write_bytes(credential_bytes)
                velox.DATA_ROOTS.clear_for_tests()
                with self.assertRaises(velox.UnsupportedDataVersionError):
                    velox.Storage(velox.AppPaths(root)).ensure_first_run_files()
                self.assertEqual(manifest_path.read_bytes(), original)
                self.assertEqual(credential_path.read_bytes(), credential_bytes)
                self.assertEqual(list(root.glob("*.bak")), [])
                self.assertEqual(list(root.glob("*.v*.bak")), [])

        production = application_source()
        self.assertNotIn("migrate_v", production)
        self.assertNotIn("PREVIOUS_SCHEMA_TO_CURRENT", production)
        self.assertNotIn("SUPPORTED_DATA_FILE_VERSIONS", production)
        self.assertIn("this build requires exactly", inspect.getsource(velox.DataRootRegistry.assert_supported))
        self.assertIn("persisted schemas", velox.__doc__ or "")
        self.assertEqual(velox.CREDENTIAL_FILE_SCHEMA, "velox_account_credentials.v1")


