    def test_chat_turn_copy_and_branch_round_trip(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            paths, storage, chats, chat = self._chat(root)
            source = root / "blue-folder.txt"
            source.write_text("attachment", encoding="utf-8")
            attachment = velox.AttachmentStore(storage).attach_file(velox.APP_SCOPE_ID, source, "chat", chat["chat_id"])
            user = velox.make_turn(chat["chat_id"], "user", "Remember the blue folder.", attachments=[attachment])
            assistant = velox.make_turn(chat["chat_id"], "assistant", "Noted.")
            (paths.chat_workspace_dir(chat["chat_id"]) / "result.txt").write_text("workspace output", encoding="utf-8")
            chats.append_turn(velox.APP_SCOPE_ID, chat["chat_id"], user)
            chats.append_turn(velox.APP_SCOPE_ID, chat["chat_id"], assistant)
            self.assertEqual([row["text"] for row in chats.load_turns(velox.APP_SCOPE_ID, chat["chat_id"])], ["Remember the blue folder.", "Noted."])
            copy_chat = chats.copy_chat(velox.APP_SCOPE_ID, chat["chat_id"])
            self.assertTrue(paths.chat_json(copy_chat["chat_id"]).exists())
            copied_turns = chats.load_turns(velox.APP_SCOPE_ID, copy_chat["chat_id"])
            self.assertEqual(len(copied_turns), 2)
            self.assertTrue(all(turn.get("chat_id") == copy_chat["chat_id"] for turn in copied_turns))
            copied_attachment = copied_turns[0]["attachments"][0]
            self.assertEqual(copied_attachment["chat_id"], copy_chat["chat_id"])
            copied_attachment_path = paths.chat_dir(copy_chat["chat_id"]) / copied_attachment["path"]
            self.assertTrue(copied_attachment_path.is_file())
            copied_attachment_meta = velox.read_json(copied_attachment_path.with_suffix(copied_attachment_path.suffix + ".meta.json"), {})
            self.assertEqual(copied_attachment_meta.get("chat_id"), copy_chat["chat_id"])
            self.assertEqual((paths.chat_workspace_dir(copy_chat["chat_id"]) / "result.txt").read_text(encoding="utf-8"), "workspace output")
            copied_summary = velox.read_json(paths.chat_summary_json(copy_chat["chat_id"]), {})
            self.assertEqual(copied_summary.get("chat_id"), copy_chat["chat_id"])
            branch = chats.branch_chat(velox.APP_SCOPE_ID, chat["chat_id"], user["turn_id"])
            branch_turns = chats.load_turns(velox.APP_SCOPE_ID, branch["chat_id"])
            self.assertEqual(len(branch_turns), 1)
            self.assertEqual(branch_turns[0]["chat_id"], branch["chat_id"])
            branch_attachment = branch_turns[0]["attachments"][0]
            self.assertEqual(branch_attachment["chat_id"], branch["chat_id"])
            self.assertTrue((paths.chat_dir(branch["chat_id"]) / branch_attachment["path"]).is_file())

