    def test_single_root_log_uses_error_warning_info_severities(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            paths, storage, _chats = _make_test_chat_stack(root)
            storage.append_app_log("test.info", {"message": "all good unique"})
            storage.append_app_log("test.info", {"message": "all good unique"})
            storage.append_app_log("test.warning", {"message": "warning unique"})
            storage.append_app_log("test.failed", {"message": "error unique"})
            records = velox.iter_jsonl(paths.log_jsonl_path)
            self.assertEqual(len(records), 4, "repeated log events must not be discarded")
            self.assertEqual([row.get("severity") for row in records], ["info", "info", "warning", "error"])
            self.assertEqual(velox.infer_log_level("tool.completed", {"status": "complete", "error": None, "errors": []}), velox.LOG_LEVEL_INFO)
            self.assertEqual(velox.infer_log_level("tool.completed", {"status": "complete", "error": "boom"}), velox.LOG_LEVEL_ERROR)
            self.assertEqual(velox.infer_log_level("request.cancelled", {}), velox.LOG_LEVEL_WARNING)
            severities = {row.get("severity") for row in records}
            self.assertTrue({"error", "warning", "info"}.issubset(severities))
            self.assertEqual([path.name for path in root.glob("*.jsonl")], ["log.jsonl"])
            self.assertFalse((root / "logs").exists())
            error_rows = storage.read_log_entries(max_level=velox.LOG_LEVEL_ERROR, limit=200)
            self.assertTrue(error_rows)
            self.assertTrue(all(row["severity"] == "error" for row in error_rows))
            velox.atomic_write_text(paths.log_jsonl_path, (json.dumps(records[0]) + "\n") * 200)
            velox.RecoveryService(storage).compact_logs(max_bytes=4096)
            self.assertEqual([path.name for path in root.glob("log*")], ["log.jsonl"])

    def test_array_icons_are_32_square_with_two_pixel_blank_border(self) -> None:
        self.assertEqual(set(velox.EMBEDDED_ICON_GRAYSCALE_32), {"chat_summary", "expert_history", "checklist_export", "chat_compact", "debug_export", "rename", "statistics", "workspace", "terminal"})
        for name, mask in velox.EMBEDDED_ICON_GRAYSCALE_32.items():
            self.assertEqual(len(mask), 32, name)
            self.assertTrue(all(len(row) == 32 for row in mask), name)
            for index in (0, 1, 30, 31):
                self.assertTrue(all(value == 0 for value in mask[index]), (name, "row", index))
                self.assertTrue(all(row[index] == 0 for row in mask), (name, "column", index))
            self.assertEqual(velox.embedded_icon_native_size(name), 32)
        # Summary and compact use true one-pixel strokes: no filled 2x2 block.
        for name in ("chat_summary", "chat_compact"):
            mask = velox.EMBEDDED_ICON_GRAYSCALE_32[name]
            self.assertFalse(any(
                all(mask[y + dy][x + dx] > 0 for dy in (0, 1) for dx in (0, 1))
                for y in range(31) for x in range(31)
            ), name)
        compact = velox.EMBEDDED_ICON_GRAYSCALE_32["chat_compact"]
        for x, y in ((5, 16), (13, 16), (19, 16), (27, 16), (16, 7), (16, 25), (10, 13), (22, 19)):
            self.assertGreater(compact[y][x], 0, (x, y))
        raw_copy = velox.EMBEDDED_ICON_GRAYSCALE_32["debug_export"]
        for x, y in ((5, 4), (5, 27), (25, 9), (19, 18), (28, 9), (28, 14)):
            self.assertGreater(raw_copy[y][x], 0, (x, y))
        rename = velox.EMBEDDED_ICON_GRAYSCALE_32["rename"]
        for x, y in ((21, 8), (24, 11), (9, 20), (12, 23), (6, 27), (16, 15)):
            self.assertGreater(rename[y][x], 0, (x, y))
        workspace = velox.EMBEDDED_ICON_GRAYSCALE_32["workspace"]
        for x, y in ((4, 9), (13, 9), (16, 12), (27, 12), (4, 26), (27, 26)):
            self.assertGreater(workspace[y][x], 0, (x, y))


