    def test_all_chat_summaries_are_newest_first_and_whole_block_capped(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            paths, _storage, chats = _make_test_chat_stack(Path(td))
            newest = chats.create_chat("Newest")
            middle = chats.create_chat("Middle")
            oldest = chats.create_chat("Oldest")
            self._write_chat_summary(paths, newest["chat_id"], "- NEWEST " + "N" * 120)
            self._write_chat_summary(paths, middle["chat_id"], "- MIDDLE " + "M" * 120)
            self._write_chat_summary(paths, oldest["chat_id"], "- OLDEST " + "O" * 120)
            self._set_chat_updated(paths, chats, newest["chat_id"], "2026-03-03T00:00:00Z")
            self._set_chat_updated(paths, chats, middle["chat_id"], "2026-02-02T00:00:00Z")
            self._set_chat_updated(paths, chats, oldest["chat_id"], "2026-01-01T00:00:00Z")
            rows, full = velox.build_all_chat_summaries(paths, chats)
            self.assertEqual([row["name"] for row in rows], ["Newest", "Middle", "Oldest"])
            self.assertLess(full.index("NEWEST"), full.index("MIDDLE"))
            self.assertLess(full.index("MIDDLE"), full.index("OLDEST"))
            first_end = full.find("\n\n## ")
            self.assertGreater(first_end, 0)
            limited_rows, limited = velox.build_all_chat_summaries(paths, chats, max_chars=first_end)
            self.assertEqual([row["name"] for row in limited_rows], ["Newest"])
            self.assertIn("NEWEST", limited)
            self.assertNotIn("MIDDLE", limited)
            none_rows, none_text = velox.build_all_chat_summaries(paths, chats, max_chars=first_end - 1)
            self.assertEqual(none_rows, [])
            self.assertEqual(none_text, "")

    def test_first_message_history_snapshot_is_chronological_stable_and_capped(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            paths, storage, chats = _make_test_chat_stack(Path(td))
            history_chat = chats.create_chat("History")
            self._write_chat_summary(paths, history_chat["chat_id"], "- Durable prior decision")
            current = chats.create_chat("Current")
            runtime = velox.ChatRuntime(storage, chats, velox.ContextAssembler(paths), velox.LLMClient(storage), velox.ToolRegistry(storage))
            endpoint_id = chats.get_chat_endpoint_profile_id(current["chat_id"])
            context = runtime._prepare_cache_safe_application_context(
                velox.APP_SCOPE_ID, current["chat_id"], endpoint_id, include_history_snapshot=True,
            )
            first = velox.make_turn(current["chat_id"], "user", "Start")
            first["chat_history_context_enabled"] = True
            first["chat_history_context_snapshot"] = context
            chats.append_turn(velox.APP_SCOPE_ID, current["chat_id"], first)
            self._write_chat_summary(paths, current["chat_id"], "- Current chat must not summarize itself")
            turns = chats.load_turns(velox.APP_SCOPE_ID, current["chat_id"])
            self.assertIn("Here's recent chats for context", context)
            self.assertIn("Durable prior decision", context)
            self.assertNotIn("Current chat must not summarize itself", context)
            self.assertLessEqual(len(context), 16384)
            messages = runtime._build_messages(velox.APP_SCOPE_ID, current["chat_id"])
            first_system = str(messages[0]["content"])
            self.assertNotIn("Durable prior decision", first_system)
            self.assertTrue(any(
                "Durable prior decision" in str(message.get("content") or "")
                for message in messages[1:]
            ))
            chats.append_turn(velox.APP_SCOPE_ID, current["chat_id"], velox.make_turn(current["chat_id"], "user", "Second"))
            turns = chats.load_turns(velox.APP_SCOPE_ID, current["chat_id"])
            self.assertEqual(runtime._first_message_history_context(velox.APP_SCOPE_ID, current["chat_id"], turns), context)
            self.assertEqual(runtime._build_messages(velox.APP_SCOPE_ID, current["chat_id"])[0]["content"], first_system)

