    def test_first_send_snapshots_history_and_locks_endpoint_and_tool_categories(self) -> None:
        async def scenario(root: Path) -> None:
            paths, storage, chats = _make_test_chat_stack(root)
            history_chat = chats.create_chat("History")
            self._write_chat_summary(paths, history_chat["chat_id"], "- Snapshot context")
            current = chats.create_chat("Current")
            chat_id = str(current["chat_id"])
            chats.set_chat_feature(velox.APP_SCOPE_ID, chat_id, "file_tools_enabled", True)
            chats.set_chat_feature(velox.APP_SCOPE_ID, chat_id, "system_tools_enabled", False)
            chats.set_chat_feature(velox.APP_SCOPE_ID, chat_id, "web_tools_enabled", True)
            chats.set_chat_feature(velox.APP_SCOPE_ID, chat_id, "agent_tools_enabled", False)
            chats.set_chat_feature(velox.APP_SCOPE_ID, chat_id, "chat_history_enabled", True)
            locked_endpoint = chats.get_chat_endpoint_profile_id(chat_id)
            runtime = velox.ChatRuntime(storage, chats, velox.ContextAssembler(paths), velox.LLMClient(storage), velox.ToolRegistry(storage))

            async def no_run(_scope_id: str, _chat_id: str, _text: str, _route: str, _attachments: list[dict[str, Any]]) -> None:
                return None

            runtime._run_chat = no_run  # type: ignore[method-assign]
            runtime.send_from_ui(velox.APP_SCOPE_ID, chat_id, "First", locked_endpoint, [])
            await asyncio.sleep(0)
            turns = chats.load_turns(velox.APP_SCOPE_ID, chat_id)
            user_turns = [
                turn for turn in turns
                if str(turn.get("role") or "").lower() == "user"
                and not velox.is_chat_application_injected_prompt_turn(turn)
            ]
            self.assertEqual(len(user_turns), 1)
            self.assertTrue(user_turns[0]["chat_history_context_enabled"])
            self.assertIn("Snapshot context", str(user_turns[0].get("chat_history_context_snapshot") or ""))
            self.assertTrue(any(
                str(turn.get("application_context_kind") or "") == velox.CHAT_APP_CONTEXT_HISTORY_KIND
                for turn in turns
            ))
            self.assertTrue(chats.is_chat_endpoint_locked(chat_id))
            self.assertEqual(chats.get_chat_tool_features(chat_id), {
                "file_tools_enabled": True,
                "system_tools_enabled": False,
                "web_tools_enabled": True,
                "agent_tools_enabled": False,
                "chat_history_enabled": True,
                "checklists_enabled": True,
            })
            with self.assertRaisesRegex(ValueError, "locked"):
                chats.set_chat_feature(velox.APP_SCOPE_ID, chat_id, "chat_history_enabled", False)
            with self.assertRaisesRegex(ValueError, "locked"):
                chats.set_chat_endpoint_profile_id(chat_id, velox.DEFAULT_QWEN_3_6_ENDPOINT_PROFILE_ID)
            self.assertIn("Snapshot context", runtime._first_message_history_context(velox.APP_SCOPE_ID, chat_id, turns))
            runtime.send_from_ui(velox.APP_SCOPE_ID, chat_id, "Second", locked_endpoint, [])
            await asyncio.sleep(0)
            turns = chats.load_turns(velox.APP_SCOPE_ID, chat_id)
            user_turns = [
                turn for turn in turns
                if str(turn.get("role") or "").lower() == "user"
                and not velox.is_chat_application_injected_prompt_turn(turn)
            ]
            self.assertEqual(len(user_turns), 2)
            self.assertNotIn("chat_history_context_enabled", user_turns[1])
            self.assertIn("Snapshot context", runtime._first_message_history_context(velox.APP_SCOPE_ID, chat_id, turns))

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

