    def test_file_tools_use_general_paths_and_absolute_chat_workspace_defaults(self) -> None:
        async def scenario(root: Path) -> None:
            paths, storage, _chats, chat = self._chat(root)
            tools = velox.FileTools(storage)
            ctx = velox.ToolContext(velox.APP_SCOPE_ID, chat_id=chat["chat_id"])

            relative = await tools.write_file(ctx, {"path": "deliverable.txt", "content": "app root"})
            self.assertTrue(_paths_equivalent(Path(relative["path"]), root / "deliverable.txt"))
            self.assertFalse(_paths_equivalent(Path(relative["path"]), root / "not-the-written-file.txt"))
            self.assertEqual((root / "deliverable.txt").read_text(encoding="utf-8"), "app root")

            workspace_target = paths.chat_workspace_dir(chat["chat_id"]) / "deliverable.txt"
            inside = await tools.write_file(ctx, {"path": str(workspace_target), "content": "inside"})
            self.assertTrue(_paths_equivalent(Path(inside["path"]), workspace_target))
            self.assertEqual(workspace_target.read_text(encoding="utf-8"), "inside")

            external = root.parent / f"velox-explicit-{velox.uuid_v4()}.txt"
            try:
                await tools.write_file(ctx, {"path": str(external), "content": "outside"})
                self.assertEqual(external.read_text(encoding="utf-8"), "outside")
                read_back = await tools.read_file(ctx, {"path": str(external)})
                self.assertEqual(read_back["text"], "outside")
            finally:
                external.unlink(missing_ok=True)

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_relative_shell_and_python_cwds_are_chat_local(self) -> None:
        async def scenario(root: Path) -> None:
            paths, storage, _chats, chat = self._chat(root)
            ctx = velox.ToolContext(velox.APP_SCOPE_ID, chat_id=chat["chat_id"])
            seen_cwds: list[Path] = []

            async def fake_run(
                _ctx: velox.ToolContext, command: Any, *, cwd: Path, timeout_seconds: float, shell: bool,
                env: dict[str, str] | None = None,
            ) -> subprocess.CompletedProcess[str]:
                del _ctx, timeout_seconds, shell
                seen_cwds.append(Path(cwd).resolve())
                return subprocess.CompletedProcess(args=command, returncode=0, stdout="", stderr="")

            with mock.patch.object(velox, "run_cancellable_subprocess", side_effect=fake_run):
                await velox.ShellTools(storage).exec(ctx, {"command": "noop", "timeout_minutes": 1})
                await velox.PythonTools(storage).run(ctx, {"script": "print('ok')", "timeout_minutes": 1})

            workspace = paths.chat_workspace_dir(chat["chat_id"]).resolve()
            self.assertEqual(seen_cwds, [workspace, workspace])

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

