    def test_markdown_images_autolinks_preview_and_shared_comfy_path(self) -> None:
        def png_bytes(width: int = 2, height: int = 3) -> bytes:
            def chunk(kind: bytes, payload: bytes) -> bytes:
                checksum = zlib.crc32(kind + payload) & 0xFFFFFFFF
                return struct.pack(">I", len(payload)) + kind + payload + struct.pack(">I", checksum)
            ihdr = struct.pack(">IIBBBBB", width, height, 8, 6, 0, 0, 0)
            row = bytes((24, 96, 180, 255)) * width
            pixels = b"".join(b"\x00" + row for _ in range(height))
            return b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", ihdr) + chunk(b"IDAT", zlib.compress(pixels)) + chunk(b"IEND", b"")

        velox.MARKDOWN_IMAGE_CACHE.clear_for_tests()
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            image_path = root / "local image.png"
            image_path.write_bytes(png_bytes())
            source = image_path.as_uri()
            engine = velox.MarkdownLayoutEngine(_TestDummyFont())
            blocks = engine.parse_markdown(f"Before image.\n\n![Local preview]({source})\n\nVisit <https://example.com/view?id=7>.")
            self.assertEqual([block for block in blocks if block.get("type") == "image"][0]["url"], source)
            links = [span.get("href") for span in engine.parse_inline("Open <https://example.com/a?b=1> now") if span.get("href")]
            self.assertEqual(links, ["https://example.com/a?b=1"])
            paths, _storage, _chats, chat = self._chat(root / "app")
            system_prompt = velox.ContextAssembler(paths).assemble_chat_context(velox.APP_SCOPE_ID, chat["chat_id"])[0]["content"]
            self.assertIn('![alt text](path-or-URL)', system_prompt)
            self.assertIn('web URLs are clickable', system_prompt)
            self.assertIn('result.png resolves from workspace', system_prompt)

            chat_id = str(chat["chat_id"])
            workspace = paths.chat_workspace_dir(chat_id)
            workspace.mkdir(parents=True, exist_ok=True)
            relative_image = workspace / "relative-proof.png"
            relative_image.write_bytes(png_bytes(4, 5))
            nested_image = workspace / "screenshots" / "nested-proof.png"
            nested_image.parent.mkdir(parents=True, exist_ok=True)
            nested_image.write_bytes(png_bytes(6, 7))

            for relative_source, expected in (
                ("relative-proof.png", relative_image),
                ("workspace/relative-proof.png", relative_image),
                ("screenshots/nested-proof.png", nested_image),
            ):
                candidates = velox._local_markdown_path_candidates(paths, chat_id, relative_source)
                self.assertTrue(candidates)
                self.assertEqual(candidates[0].resolve(), expected.resolve())
                record = velox.MARKDOWN_IMAGE_CACHE.get(relative_source, candidates)
                self.assertEqual(record["status"], "ready")
                self.assertEqual(Path(record["path"]).resolve(), expected.resolve())

            relative_links = [
                span.get("href") for span in engine.parse_inline(
                    "Open relative-proof.png, workspace/relative-proof.png, and `screenshots/nested-proof.png`."
                ) if span.get("href")
            ]
            self.assertEqual(
                relative_links,
                ["relative-proof.png", "workspace/relative-proof.png", "screenshots/nested-proof.png"],
            )
            explicit = [
                span.get("href") for span in engine.parse_inline(
                    "[proof](workspace/relative-proof.png)"
                ) if span.get("href")
            ]
            self.assertEqual(explicit, ["workspace/relative-proof.png"])

            renderer = velox.MarkdownRenderer.__new__(velox.MarkdownRenderer)
            renderer.widgets = SimpleNamespace(
                state=SimpleNamespace(add_toast=lambda *_args, **_kwargs: None),
                markdown_local_candidates=lambda _source: (relative_image,),
            )
            with mock.patch(velox.__name__ + ".open_local_path_parent") as open_parent:
                renderer._open_link("relative-proof.png")
            open_parent.assert_called_once_with(relative_image)

        self.assertIn("MARKDOWN_IMAGE_THUMBNAIL_MAX_PX", self._method_source(velox.MarkdownRenderer, "_draw_image_row"))
        self.assertIn("webbrowser.open", self._method_source(velox.MarkdownRenderer, "_open_link"))
        self.assertIn("markdown_local_candidates(source)", self._method_source(velox.Panels, "_draw_inline_media_grid"))

    def test_agent_terminal_result_is_durably_delivered_to_source_chat(self) -> None:
        class DualLLM:
            def __init__(self) -> None:
                self.agent_calls = 0
                self.chat_messages: list[list[dict[str, Any]]] = []

            async def chat_completions_once_full(self, request: LLMRequest) -> dict[str, Any]:
                self.agent_calls += 1
                return {
                    "text": '$$AGENT_PROGRESS: {"message":"Saved the requested report at /tmp/report.txt.","percent":100}',
                    "usage": {}, "model": "agent-result-test", "endpoint": request.endpoint_profile_id, "raw": {},
                }

            async def chat_completions_stream(self, request: LLMRequest):
                self.chat_messages.append(copy.deepcopy(request.messages))
                yield velox.LLMChunk(
                    text="The background agent finished and saved the report at `/tmp/report.txt`.",
                    usage={"prompt_tokens": 20, "completion_tokens": 12},
                    done=True,
                )

        async def scenario(root: Path) -> None:
            paths, storage, chats, chat = self._chat(root)
            fake = DualLLM()
            tools = velox.ToolRegistry(storage)
            chat_runtime = velox.ChatRuntime(storage, chats, velox.ContextAssembler(paths), fake, tools)
            agents = velox.AgentStore(storage)
            agent_runtime = velox.AgentRuntime(storage, agents, chats, velox.ContextAssembler(paths), fake, tools, chat_runtime=chat_runtime)
            tools.bind_agent_runtime(agent_runtime)
            started = await agent_runtime.start_from_tool(
                velox.ToolContext(velox.APP_SCOPE_ID, chat_id=chat["chat_id"]),
                {"task": "Create a report."},
            )
            agent_id = str(started["agent_id"])
            final = await asyncio.wait_for(agent_runtime.wait_for_agent(agent_id), timeout=2.0)
            self.assertEqual(final["status"], "succeeded")
            self.assertTrue(final.get("terminal_reported_at"))

            turns: list[dict[str, Any]] = []
            for _ in range(200):
                turns = chats.load_turns(velox.APP_SCOPE_ID, chat["chat_id"])
                report_id = f"{agent_id}:terminal:1"
                if any(str(turn.get("agent_report_response_for") or "") == report_id for turn in turns):
                    response = next(turn for turn in turns if str(turn.get("agent_report_response_for") or "") == report_id)
                    if str(response.get("status") or "") == "complete":
                        break
                await asyncio.sleep(0.01)
            report_id = f"{agent_id}:terminal:1"
            hidden = next(turn for turn in turns if str(turn.get("agent_report_id") or "") == report_id)
            visible = next(turn for turn in turns if str(turn.get("agent_report_response_for") or "") == report_id)
            self.assertTrue(hidden["hidden_from_ui"])
            self.assertEqual(hidden["role"], "system")
            self.assertTrue(str(hidden["text"]).startswith("Here's the result from your agent task."))
            self.assertEqual(visible["role"], "assistant")
            self.assertEqual(visible["status"], "complete")
            self.assertIn("saved the report", visible["text"])
            self.assertTrue(fake.chat_messages)
            self.assertTrue(any(
                message.get("role") == "user" and "Here's the result from your agent task" in str(message.get("content") or "")
                for message in fake.chat_messages[-1]
            ))
            summary_text = chat_runtime._chat_thread_text_for_summary(velox.APP_SCOPE_ID, chat["chat_id"])
            self.assertNotIn("hidden orchestration instruction", summary_text)
            self.assertIn("saved the report", summary_text)
            await agent_runtime.shutdown()
            chat_runtime.cancel_all()

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_agent_timeout_pauses_reports_and_resume_doubles_budget(self) -> None:
        class TimeoutLLM:
            def __init__(self) -> None:
                self.agent_calls = 0
                self.report_instructions: list[str] = []

            async def chat_completions_once_full(self, request: LLMRequest) -> dict[str, Any]:
                self.agent_calls += 1
                return {
                    "text": '$$AGENT_PROGRESS: {"message":"Completed after the timeout pause was resumed.","percent":100}',
                    "usage": {}, "model": "timeout", "endpoint": request.endpoint_profile_id, "raw": {},
                }

            async def chat_completions_stream(self, request: LLMRequest):
                self.report_instructions.append("\n".join(str(message.get("content") or "") for message in request.messages))
                yield velox.LLMChunk(text="The agent was paused at its time limit and must be resumed to continue.", usage={}, done=True)

        async def scenario(root: Path) -> None:
            paths, storage, chats, chat = self._chat(root)
            fake = TimeoutLLM()
            tools = velox.ToolRegistry(storage)
            chat_runtime = velox.ChatRuntime(storage, chats, velox.ContextAssembler(paths), fake, tools)
            agents = velox.AgentStore(storage)
            runtime = velox.AgentRuntime(storage, agents, chats, velox.ContextAssembler(paths), fake, tools, chat_runtime=chat_runtime)
            tools.bind_agent_runtime(runtime)
            agent = agents.create_agent(
                chat["chat_id"], "Run beyond the time budget.", timeout_minutes=1,
            )
            agent_id = str(agent["agent_id"])
            agents.update_agent(agent_id, {"active_seconds": 61.0})
            runtime.start_agent(agent_id)
            paused = await asyncio.wait_for(runtime.wait_for_agent(agent_id), timeout=2.0)
            self.assertEqual(paused["status"], "paused")
            self.assertTrue(paused["paused_due_to_timeout"])
            self.assertEqual(paused["progress_message"], "Paused — time limit reached")
            self.assertEqual(paused["failure_message"], "")
            self.assertEqual(paused["timeout_pause_count"], 1)
            self.assertEqual(fake.agent_calls, 0)
            timeout_event = next(event for event in reversed(agents.load_transcript(agent_id)) if event.get("kind") == "timeout_paused")
            self.assertIn("paused, not failed", timeout_event["data"]["message"] )
            timeout_report_id = f"{agent_id}:timeout:1"
            response = None
            for _ in range(200):
                turns = chats.load_turns(velox.APP_SCOPE_ID, chat["chat_id"])
                response = next((turn for turn in turns if str(turn.get("agent_report_response_for") or "") == timeout_report_id), None)
                if response and response.get("status") == "complete":
                    break
                await asyncio.sleep(0.01)
            self.assertIsNotNone(response)
            self.assertIn("paused", str(response.get("text") or "").lower())
            self.assertTrue(any("must resume" in text.lower() for text in fake.report_instructions))

            self.assertTrue(runtime.resume(agent_id))
            final = await asyncio.wait_for(runtime.wait_for_agent(agent_id), timeout=2.0)
            self.assertEqual(final["status"], "succeeded")
            self.assertFalse(final["paused_due_to_timeout"])
            self.assertEqual(final["timeout_minutes"], 2)
            self.assertEqual(final["timeout_extension_count"], 1)
            self.assertTrue(final.get("terminal_reported_at"))
            self.assertEqual(fake.agent_calls, 1)
            await runtime.shutdown()
            chat_runtime.cancel_all()

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_agent_store_layout_filtering_counts_and_restart_recovery(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            paths, storage, chats = _make_test_chat_stack(root)
            chat_a = chats.create_chat("Agent source A")
            chat_b = chats.create_chat("Agent source B")
            agents = velox.AgentStore(storage)

            first = agents.create_agent(
                chat_a["chat_id"],
                "Inspect the source tree and report findings.",
                title="Source audit",
                endpoint_profile_id=velox.DEFAULT_ENDPOINT_PROFILE_ID,
                context="Focus on persistence.",
            )
            second = agents.create_agent(chat_b["chat_id"], "Produce a concise result.")
            first_id = str(first["agent_id"])
            second_id = str(second["agent_id"])

            self.assertTrue(paths.agent_json(first_id).is_file())
            self.assertTrue(paths.agent_transcript_jsonl(first_id).is_file())
            self.assertEqual(velox.read_json(paths.agent_json(first_id), {})["schema"], "agent.v303")
            created_events = agents.load_transcript(first_id)
            self.assertEqual([event.get("kind") for event in created_events], ["created"])
            self.assertEqual(created_events[0]["data"]["source_chat_id"], chat_a["chat_id"])
            self.assertEqual([row["agent_id"] for row in agents.list_agents(chat_a["chat_id"])], [first_id])
            self.assertEqual([row["agent_id"] for row in agents.list_agents(chat_b["chat_id"])], [second_id])

            agents.update_agent(first_id, {
                "status": "running",
                "progress_message": "Reviewing files",
                "progress_percent": 35,
            })
            agents.update_agent(second_id, {
                "status": "succeeded",
                "progress_message": "Completed",
                "progress_percent": 100,
                "final_message": "Done.",
            })
            agents.append_event(second_id, "succeeded", {"message": "Done."})
            counts = agents.status_counts()
            self.assertEqual(counts["running"], 1)
            self.assertEqual(counts["succeeded"], 1)
            self.assertEqual(counts["completed"], 1)
            self.assertEqual(counts["total"], 2)

            self.assertEqual(agents.recover_interrupted(), 1)
            recovered = agents.load_agent(first_id)
            self.assertEqual(recovered["status"], "failed")
            self.assertIn("stopped before", recovered["failure_message"])
            self.assertEqual(agents.load_agent(second_id)["status"], "succeeded")
            failed_event = agents.load_transcript(first_id)[-1]
            self.assertEqual(failed_event["kind"], "failed")
            self.assertTrue(failed_event["data"]["recovered_after_restart"])


    def test_agents_start_tool_returns_while_agent_tasks_asynchronously(self) -> None:
        class BlockingLLM:
            def __init__(self) -> None:
                self.started = asyncio.Event()
                self.release = asyncio.Event()

            async def chat_completions_once_full(self, request: LLMRequest) -> dict[str, Any]:
                self.started.set()
                await self.release.wait()
                return {
                    "text": '$$AGENT_PROGRESS: {"message":"Background result complete.","percent":100}',
                    "usage": {"total_tokens": 7},
                    "model": "blocking-test-model",
                    "endpoint": request.endpoint_profile_id,
                    "raw": {"test": "blocking"},
                }

        async def scenario(root: Path) -> None:
            fake = BlockingLLM()
            paths, _storage, chats, chat, agents, tools, runtime = self._agent_stack(root, fake)
            task = "Use the chat workspace and complete a background check."
            chats.set_chat_feature(velox.APP_SCOPE_ID, chat["chat_id"], "agent_tools_enabled", False)
            blocked = await tools.execute_tool_call(
                velox.APP_SCOPE_ID,
                {"name": "agents_start", "arguments": {"task": task}},
                chat_id=chat["chat_id"],
            )
            self.assertFalse(blocked["ok"])
            self.assertIn("PermissionError", blocked["error"])
            self.assertEqual(agents.list_agents(chat["chat_id"]), [])
            chats.set_chat_feature(velox.APP_SCOPE_ID, chat["chat_id"], "agent_tools_enabled", True)
            result = await tools.execute_tool_call(
                velox.APP_SCOPE_ID,
                {"name": "agents_start", "arguments": {"task": task}},
                chat_id=chat["chat_id"],
            )
            self.assertTrue(result["ok"])
            started = result["result"]
            agent_id = str(started["agent_id"])
            self.assertEqual(started["schema"], "agent_start_result.v5")
            self.assertNotIn("expert_mode", started)
            self.assertNotIn("persistence_enabled", started)
            self.assertNotIn("persistence_max_prompts", started)
            self.assertIn("decides whether", started["message"])
            self.assertEqual(started["endpoint_profile_id"], velox.DEFAULT_DEEPSEEK_V4_FLASH_VISION_EXP_ENDPOINT_PROFILE_ID)
            self.assertTrue(paths.agent_json(agent_id).is_file())
            saved = agents.load_agent(agent_id)
            self.assertNotIn("expert_mode", saved)
            self.assertNotIn("persistence_enabled", saved)
            self.assertTrue(saved["tool_features"]["agent_tools_enabled"])
            self.assertIn(saved["status"], {"queued", "running"})
            self.assertTrue(runtime.is_running(agent_id))
            await asyncio.wait_for(fake.started.wait(), timeout=2.0)
            self.assertFalse(fake.release.is_set())
            self.assertNotIn(agents.load_agent(agent_id)["status"], velox.AGENT_TERMINAL_STATUSES)
            fake.release.set()
            final = await asyncio.wait_for(runtime.wait_for_agent(agent_id), timeout=2.0)
            self.assertEqual(final["status"], "succeeded")
            self.assertEqual(final["final_message"], "Background result complete.")
            self.assertFalse(runtime.is_running(agent_id))
            await runtime.shutdown()

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_agent_runtime_persists_failure_diagnostic_and_user_cancellation(self) -> None:
        class FailureLLM:
            async def chat_completions_once_full(self, request: LLMRequest) -> dict[str, Any]:
                return {
                    "text": '$$AGENT_PROGRESS: {"message":"dependency checkout failed after two attempts","failed":true}',
                    "usage": {},
                    "model": "failure-test-model",
                    "endpoint": request.endpoint_profile_id,
                    "raw": {"failed": True},
                }

        class BlockingLLM:
            def __init__(self) -> None:
                self.started = asyncio.Event()

            async def chat_completions_once_full(self, request: LLMRequest) -> dict[str, Any]:
                self.started.set()
                await asyncio.Event().wait()
                return {"text": "", "usage": {}, "model": "never", "endpoint": request.endpoint_profile_id, "raw": {}}

        async def scenario(failure_root: Path, cancel_root: Path) -> None:
            failure_llm = FailureLLM()
            _p1, _s1, _c1, failure_chat, failure_agents, _t1, failure_runtime = self._agent_stack(failure_root, failure_llm)
            started_failure = await failure_runtime.start_from_tool(
                velox.ToolContext(velox.APP_SCOPE_ID, chat_id=failure_chat["chat_id"]),
                {"task": "Attempt the dependency checkout.", "title": "Expected failure", "expert_mode": False},
            )
            failure_id = str(started_failure["agent_id"])
            failed = await asyncio.wait_for(failure_runtime.wait_for_agent(failure_id), timeout=2.0)
            self.assertEqual(failed["status"], "failed")
            self.assertEqual(failed["failure_message"], "dependency checkout failed after two attempts")
            self.assertEqual(failure_agents.load_transcript(failure_id)[-1]["kind"], "failed")
            await failure_runtime.shutdown()

            blocking = BlockingLLM()
            _p2, _s2, _c2, cancel_chat, cancel_agents, _t2, cancel_tasktime = self._agent_stack(cancel_root, blocking)
            started_cancel = await cancel_tasktime.start_from_tool(
                velox.ToolContext(velox.APP_SCOPE_ID, chat_id=cancel_chat["chat_id"]),
                {"task": "Wait until cancelled.", "title": "Cancellation test", "expert_mode": False},
            )
            cancel_id = str(started_cancel["agent_id"])
            await asyncio.wait_for(blocking.started.wait(), timeout=2.0)
            self.assertTrue(cancel_tasktime.cancel(cancel_id))
            cancelled = await asyncio.wait_for(cancel_tasktime.wait_for_agent(cancel_id), timeout=2.0)
            self.assertEqual(cancelled["status"], "cancelled")
            self.assertEqual(cancelled["progress_message"], "Cancelled")
            self.assertIn("Cancelled by the user", cancelled["failure_message"])
            self.assertEqual(cancel_agents.load_transcript(cancel_id)[-1]["kind"], "cancelled")
            self.assertFalse(cancel_tasktime.cancel(cancel_id))
            await cancel_tasktime.shutdown()

        with tempfile.TemporaryDirectory() as failure_td, tempfile.TemporaryDirectory() as cancel_td:
            asyncio.run(scenario(Path(failure_td), Path(cancel_td)))


    def test_inline_code_backgrounds_render_before_all_row_text(self) -> None:
        class RecordingRenderer:
            def __init__(self) -> None:
                self.events: list[tuple[str, Any]] = []
                self.host = None

            def draw_round_rect(self, rect: Rect, radius: int, color: Color, **_kwargs: Any) -> None:
                self.events.append(("background", rect))

            def draw_text_cached(self, text: str, *_args: Any, **_kwargs: Any) -> None:
                self.events.append(("text", text))

            def draw_text_cached_font(self, _font: Any, text: str, *_args: Any, **_kwargs: Any) -> None:
                self.events.append(("text", text))

            def draw_text_run(self, text: str, *_args: Any, **_kwargs: Any) -> None:
                self.events.append(("text", text))

            def draw_line(self, *_args: Any, **_kwargs: Any) -> None:
                self.events.append(("line", None))

            def push_clip(self, *_args: Any, **_kwargs: Any) -> None:
                pass

            def pop_clip(self, *_args: Any, **_kwargs: Any) -> None:
                pass

        renderer = RecordingRenderer()
        state = velox.UIState()
        font = _TestDummyFont(line_h=20, char_w=8)
        code_font = _TestDummyFont(line_h=20, char_w=8)
        widgets = velox.Widgets(renderer, font, state, None, code_font=code_font)
        markdown = velox.MarkdownRenderer(widgets)
        row = velox.LayoutRow(
            text="first then second",
            x=0,
            y=0,
            h=26,
            kind="paragraph",
            draw_mode="rich",
            baseline_y=16,
            spans=[
                {"text": "first", "x": 0, "w": 40, "start": 0, "code": True, "line_h": 20},
                {"text": " then ", "x": 40, "w": 48, "start": 5, "line_h": 20},
                {"text": "second", "x": 88, "w": 48, "start": 11, "code": True, "line_h": 20},
            ],
        )
        markdown._draw_row_text_only(row, 0, 0)
        background_indices = [index for index, event in enumerate(renderer.events) if event[0] == "background"]
        text_indices = [index for index, event in enumerate(renderer.events) if event[0] == "text"]
        self.assertEqual(len(background_indices), 2)
        self.assertTrue(text_indices)
        self.assertLess(max(background_indices), min(text_indices), renderer.events)

    def test_chat_debug_report_export_is_readable_and_has_dedicated_header_action(self) -> None:
        class ClipboardHost:
            def __init__(self) -> None:
                self.text = ""

            def set_clipboard_text(self, text: str) -> None:
                self.text = text

        class PanelRenderer:
            def __init__(self, host: ClipboardHost) -> None:
                self.host = host

        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            paths = velox.AppPaths(root)
            storage = velox.Storage(paths)
            storage.ensure_first_run_files()
            chats = velox.ChatStore(storage)
            chat = chats.create_chat("Debug copy")
            turns = [
                velox.make_turn(chat["chat_id"], "user", "hello"),
                velox.make_turn(chat["chat_id"], "assistant", "done", status="complete"),
            ]
            for turn in turns:
                chats.append_turn(velox.APP_SCOPE_ID, chat["chat_id"], turn)
            host = ClipboardHost()
            panels = velox.Panels.__new__(velox.Panels)
            panels.widgets = type("PanelWidgets", (), {"renderer": PanelRenderer(host)})()
            panels.state = velox.UIState()
            panels.state.active_chat_id = str(chat["chat_id"])
            panels.services = type("PanelServices", (), {"storage": storage, "chats": chats})()
            velox.Panels._request_chat_debug_export(panels)
            self.assertEqual(host.text, "")
            self.assertTrue(panels.state.file_picker_save)
            self.assertEqual(panels.state.file_picker_save_context["identity"], chat["chat_id"])
            destination = root / "debug.txt"
            velox.write_debug_report_atomic(destination, panels._build_debug_export_lines(panels.state.file_picker_save_context))
            report = destination.read_text(encoding="utf-8")
            self.assertTrue(report.startswith("VELOX CHAT DEBUG REPORT"))
            self.assertIn("COMPLETE CORRESPONDENCE AND TURN METADATA", report)
            self.assertIn(str(turns[0]["turn_id"]), report)
            self.assertFalse(report.lstrip().startswith("{"))
        header = self._method_source(velox.Panels, "draw_chat_thread_header")
        self.assertIn('icon="debug_export"', header)
        self.assertIn("_request_chat_debug_export", header)
        self.assertIn("_debug_export_tooltip", header)
        self.assertIn("Export chat debug report", inspect.getsource(velox.Panels._debug_export_tooltip))
        self.assertLess(header.index('icon="copy"'), header.index('icon="debug_export"'))

