    def test_tooltip_motion_resets_delay_and_enforces_equal_cooldown(self) -> None:
        state = velox.UIState()
        state.input.mouse_x = 5
        state.input.mouse_y = 5
        widgets = velox.Widgets.__new__(velox.Widgets)
        widgets.state = state
        rect = velox.Rect(0, 0, 20, 20)

        state.tooltip = {"text": "Tip"}
        state.input.mouse_moved = True
        velox.Widgets._queue_tooltip(widgets, "tip", rect, "Tip")
        self.assertIsNone(state.tooltip)
        self.assertEqual(state.tooltip_hover_key, "tip")

        state.input.mouse_moved = False
        state.tooltip_cooldown_until = time.monotonic() + velox.TOOLTIP_HOVER_DELAY_SECONDS
        state.tooltip_hover_started_at = time.monotonic() - velox.TOOLTIP_HOVER_DELAY_SECONDS * 2
        velox.Widgets._queue_tooltip(widgets, "tip", rect, "Tip")
        self.assertIsNone(state.tooltip)

        state.tooltip_cooldown_until = 0.0
        state.tooltip_hover_started_at = time.monotonic() - velox.TOOLTIP_HOVER_DELAY_SECONDS * 2
        velox.Widgets._queue_tooltip(widgets, "tip", rect, "Tip")
        self.assertEqual(state.tooltip["text"], "Tip")
        # Live statistics may change while the pointer remains still. Content
        # updates must not reset the hover identity or delay.
        prior_started = state.tooltip_hover_started_at
        velox.Widgets._queue_tooltip(widgets, "tip", rect, "Updated live statistics")
        self.assertEqual(state.tooltip_hover_key, "tip")
        self.assertEqual(state.tooltip_hover_started_at, prior_started)
        self.assertEqual(state.tooltip["text"], "Updated live statistics")
        frame = self._method_source(velox.VeloxApp, "draw_frame")
        self.assertIn("tooltip_cooldown_until = tooltip_now + TOOLTIP_HOVER_DELAY_SECONDS", frame)

    def test_configured_web_search_provider_defaults_and_rate_window(self) -> None:
        async def scenario(root: Path) -> None:
            _paths, storage, _chats = _make_test_chat_stack(root)
            config = storage.load_config()
            config["web"].update({
                "search_provider": "bing",
                "search_requests_per_minute": 600,
                "default_search_results": 7,
            })
            storage.write_config(config)
            web = velox.WebTools(storage)
            seen: dict[str, Any] = {}

            async def fake_bing(_ctx: velox.ToolContext, args: dict[str, Any]) -> dict[str, Any]:
                seen.update(args)
                return {"provider": "bing", "query": args.get("query"), "results": [{"title": "ok"}]}

            web._bing_search = fake_bing  # type: ignore[method-assign]
            result = await web.search(velox.ToolContext(velox.APP_SCOPE_ID), {"query": "velox"})
            self.assertEqual(result["provider"], "bing")
            self.assertEqual(seen["max_results"], 7)
            self.assertEqual(len(web._search_request_timestamps), 1)
            web._search_request_timestamps = [time.monotonic() - 61.0]
            await web._respect_search_rate_limit()
            self.assertEqual(len(web._search_request_timestamps), 1)
            self.assertLess(time.monotonic() - web._search_request_timestamps[0], 1.0)

            config = storage.load_config()
            config["web"]["search_provider"] = "duckduckgo"
            storage.write_config(config)
            web._search_request_timestamps = []

            async def empty_duckduckgo(_ctx: velox.ToolContext, args: dict[str, Any]) -> dict[str, Any]:
                return {"provider": "duckduckgo", "query": args.get("query"), "status": "no_results_parsed", "results": []}

            web._duckduckgo_search = empty_duckduckgo  # type: ignore[method-assign]
            await web.search(velox.ToolContext(velox.APP_SCOPE_ID), {"query": "fallback"})
            self.assertEqual(len(web._search_request_timestamps), 2)

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))


