    def test_default_endpoints_font_and_chunked_file_terminal_helpers(self) -> None:
        cfg = velox.default_config()
        self.assertEqual(velox.endpoint_profile_ref(cfg, velox.DEFAULT_ENDPOINT_PROFILE_ID)["base_url"], "http://127.0.0.1:8090/v1/chat/completions")
        self.assertEqual(velox.endpoint_profile_ref(cfg, velox.DEFAULT_ENDPOINT_PROFILE_ID)["base_url"], "http://127.0.0.1:8090/v1/chat/completions")
        self.assertEqual(velox.endpoint_profile_ref(cfg, velox.DEFAULT_ENDPOINT_PROFILE_ID)["base_url"], "http://127.0.0.1:8090/v1/chat/completions")
        self.assertEqual(cfg["ui"]["font_weight"], "heavy")
        self.assertEqual(velox.normalize_font_weight(None), "heavy")

        async def scenario(root: Path) -> None:
            _paths, storage, _chats, chat = self._chat(root)
            registry = velox.ToolRegistry(storage)
            ctx = velox.ToolContext(velox.APP_SCOPE_ID, chat_id=str(chat["chat_id"]))
            target = root / "chunked.cpp"

            first_content = 'line one\nline "two"\n'
            first = await registry.file_tools.write_file(ctx, {
                "path": str(target), "content": first_content,
            })
            self.assertEqual(first["bytes"], len(first_content.encode("utf-8")))
            await registry.file_tools.append_file(ctx, {
                "path": str(target), "content": "line three\n",
            })
            await registry.file_tools.append_file(ctx, {
                "path": str(target), "content": "line four\nline five",
            })
            self.assertEqual(
                target.read_text(encoding="utf-8"),
                'line one\nline "two"\nline three\nline four\nline five',
            )
            empty = root / "empty.txt"
            await registry.file_tools.write_file(ctx, {"path": str(empty), "content": ""})
            self.assertEqual(empty.read_text(encoding="utf-8"), "")

            written: list[str] = []
            def fake_write(_ctx: velox.ToolContext, terminal_id: str, text: str, **_kwargs: Any) -> dict[str, Any]:
                written.append(text)
                return {"terminal_id": terminal_id, "bytes_written": len(text.encode("utf-8"))}

            registry.terminal_runtime.write_owned = fake_write  # type: ignore[method-assign]
            line_result = await registry.tool_terminal_write_line(ctx, {
                "terminal_id": "terminal-1",
                "text": "call C:/UE_5.5/Engine/Build/BatchFiles/Build.bat\r\n\n",
            })
            self.assertEqual(written, ["call C:/UE_5.5/Engine/Build/BatchFiles/Build.bat\r"])
            self.assertEqual(line_result["line_text"], "call C:/UE_5.5/Engine/Build/BatchFiles/Build.bat")
            with self.assertRaisesRegex(ValueError, "unknown tool"):
                registry._normalize_tool_call({"name": "terminal.send_line", "arguments": {}})
            with self.assertRaisesRegex(ValueError, "unknown tool"):
                registry._normalize_tool_call({"name": "fs.append", "arguments": {}})
            self.assertEqual(
                registry._normalize_tool_call({
                    "name": "terminal_write_line",
                    "arguments": {"terminal_id": "t", "text": "x"},
                })[0],
                "terminal_write_line",
            )
            self.assertEqual(set(registry.tools["fs_write"].parameters["properties"]), {"path", "content"})

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))


