            panel.state = velox.UIState()

            persisted = storage.load_config()
            persisted["ui"]["font_size"] = 23
            persisted["ui"]["window_width"] = 1111
            storage.write_config(persisted)
            persisted = storage.load_config()
            draft = panel._settings_config_to_draft(persisted)
            panel.state.config_draft = draft
            panel.state.settings_last_valid_config = copy.deepcopy(persisted)
            panel.state.settings_last_saved_config_json = json.dumps(persisted, ensure_ascii=False, sort_keys=True)

            draft["ui"]["_ui_font_size"] = "999"
            panel.state.active_widget = "settings.font.size"
            panel._autosave_settings_if_changed(draft)
            self.assertEqual(storage.load_config()["ui"]["font_size"], 23)
            self.assertEqual(draft["ui"]["_ui_font_size"], "999")

            panel.state.active_widget = None
            panel._autosave_settings_if_changed(draft)
            self.assertEqual(storage.load_config()["ui"]["font_size"], 40)

            draft = panel.state.config_draft
            draft["history"]["chat_summary_prompt"] = "Typed prompt retained across an external geometry write."
            panel.state.active_widget = "settings.history.chat_summary_prompt"
            panel._autosave_settings_if_changed(draft)
            storage.update_config(lambda cfg: cfg["ui"].update({
                "window_width": 1777,
                "window_height": 999,
                "window_x": 41,
                "window_y": 73,
            }))
            self.assertEqual(
                draft["history"]["chat_summary_prompt"],
                "Typed prompt retained across an external geometry write.",
            )
            panel.state.active_widget = None
            panel._autosave_settings_if_changed(draft)
            final = storage.load_config()
            self.assertEqual(
                final["history"]["chat_summary_prompt"],
                "Typed prompt retained across an external geometry write.",
            )
            self.assertEqual(
                {key: final["ui"][key] for key in ("window_width", "window_height", "window_x", "window_y")},
                {"window_width": 1777, "window_height": 999, "window_x": 41, "window_y": 73},
            )

            credentials = velox.CredentialStore(storage.paths)
            credentials.save_github("octocat", "github_pat_test")
            panel.state.active_widget = None
            panel._autosave_settings_if_changed(panel.state.config_draft)
            self.assertEqual(
                velox.CredentialStore(storage.paths).load_github(),
                {"username": "octocat", "pat": "github_pat_test"},
            )
            self.assertNotIn("accounts", storage.load_config())

