    def test_agent_auto_compaction_preserves_task_latest_tool_and_restart_checkpoint(self) -> None:
        class CompactionLLM:
            def __init__(self) -> None:
                self.calls = 0
            async def chat_completions_once_full(self, request: LLMRequest) -> dict[str, Any]:
                self.calls += 1
                return {
                    "text": "Earlier inspection found /tmp/input.bin and retained all durable decisions, constraints, errors, test outcomes, paths, and the exact next action so execution can continue safely without losing required context.",
                    "usage": {"prompt_tokens": 7200, "completion_tokens": 48},
                    "model": "compaction-test", "endpoint": request.endpoint_profile_id, "raw": {},
                }

        async def scenario(root: Path) -> None:
            paths, storage, chats, chat = self._chat(root)
            fake = CompactionLLM()
            agents = velox.AgentStore(storage)
            runtime = velox.AgentRuntime(storage, agents, chats, velox.ContextAssembler(paths), fake, velox.ToolRegistry(storage))
            agent = agents.create_agent(
                chat["chat_id"], "Inspect and finish the exact assigned task.",
                context_window_tokens=8192, max_output_tokens=1024,
                auto_compaction_enabled=True,
            )
            agent_id = str(agent["agent_id"])
            system_message = {"role": "system", "content": "SYSTEM PROTOCOL — KEEP VERBATIM"}
            task_message = {"role": "user", "content": "# Assigned task\nInspect and finish the exact assigned task."}
            latest_assistant = {"role": "assistant", "content": "<think>NEWEST THINKING MUST SURVIVE</think>\nContinuing."}
            agents.append_event(agent_id, "started", {"system_prompt": system_message["content"], "user_prompt": task_message["content"]})
            messages = [system_message, task_message]
            for index in range(18):
                messages.append({"role": "assistant", "content": f"Earlier thinking {index}: " + ("x" * 1100)})
                messages.append({"role": "user", "content": f"Earlier result {index}: " + ("y" * 1100)})
            messages.append(latest_assistant)
            before = runtime._estimate_messages_tokens(messages)
            self.assertTrue(await runtime._maybe_compact_agent_context(agent_id, messages, force=True))
            after = runtime._estimate_messages_tokens(messages)
            self.assertEqual(fake.calls, 1)
            self.assertEqual(messages[0], system_message)
            self.assertEqual(messages[1], task_message)
            self.assertEqual(messages[-1], latest_assistant)
            self.assertLess(after, before)
            event = next(row for row in reversed(agents.load_transcript(agent_id)) if row.get("kind") == "context_compacted")
            self.assertTrue(event["data"]["fits_effective_context"])
            self.assertLessEqual(event["data"]["complete_after_tokens"], event["data"]["prompt_capacity_tokens"])
            self.assertNotIn("trigger_percent", event["data"])
            self.assertGreaterEqual(event["data"]["passes_used"], 1)
            rebuilt, _iteration = runtime._conversation_from_transcript(agents.load_agent(agent_id))
            self.assertEqual(rebuilt, messages)

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

