    def test_widget_calls_match_widget_signatures_and_toggle_accepts_tooltips(self) -> None:
        signature = inspect.signature(velox.Widgets.toggle)
        self.assertIn("tooltip", signature.parameters)
        settings_source = self._method_source(velox.Panels, "_draw_agents_settings_content")
        self.assertIn("tooltip=", settings_source)

        # Parse the 3 MiB production source in a short-lived child process. Keeping its
        # roughly 440,000 AST nodes alive in this process previously made the later
        # 50,000-row Vault test thrash or hang under constrained memory.
        probe = application_source_structure()
        widget_methods = probe["widget_methods"]
        problems: list[str] = []
        for call in probe["widget_calls"]:
            signature_row = widget_methods.get(call["method"])
            if signature_row is None:
                continue
            names = set(signature_row["names"])
            required = int(signature_row["required"])
            maximum = signature_row["maximum"]
            if call["nargs"] < required or (maximum is not None and call["nargs"] > int(maximum)):
                problems.append(f"line {call['line']}: {call['method']} positional argument count")
            if not signature_row["has_var_keyword"]:
                for keyword in call["keywords"]:
                    if keyword is not None and keyword not in names:
                        problems.append(f"line {call['line']}: {call['method']} unexpected {keyword}")
        self.assertEqual(problems, [])

