    def test_agent_request_timeouts_retry_pause_report_and_resume(self) -> None:
        class TimeoutThenSuccessLLM(velox.LLMClient):
            def __init__(self, storage: Storage) -> None:
                super().__init__(storage)
                self.fail_agent_requests = True
                self.agent_calls = 0
                self.report_instructions: list[str] = []

            async def _chat_completions_stream_unqueued(self, request: LLMRequest):
                if request.task_kind == "agent":
                    self.agent_calls += 1
                    if self.fail_agent_requests:
                        yield velox.LLMChunk(error="LLMRequestTimeoutError: timed out", done=True)
                    else:
                        yield velox.LLMChunk(text='$$AGENT_PROGRESS: {"message":"Recovered after endpoint timeout pause.","percent":100}', done=True, finish_reason="stop")
                else:
                    self.report_instructions.append("\n".join(str(message.get("content") or "") for message in request.messages))
                    yield velox.LLMChunk(text="The agent was paused after repeated endpoint request timeouts. Resume it to continue.", done=True, finish_reason="stop")

        async def scenario(root: Path) -> None:
            paths, storage, chats, chat = self._chat(root)
            storage.update_config(lambda cfg: velox.endpoint_profile_ref(cfg, velox.DEFAULT_ENDPOINT_PROFILE_ID).update(
                error_recovery_attempts=2, error_recovery_delay_seconds=0))
            fake = TimeoutThenSuccessLLM(storage)
            tools = velox.ToolRegistry(storage)
            chat_runtime = velox.ChatRuntime(storage, chats, velox.ContextAssembler(paths), fake, tools)
            agents = velox.AgentStore(storage)
            runtime = velox.AgentRuntime(
                storage,
                agents,
                chats,
                velox.ContextAssembler(paths),
                fake,
                tools,
                chat_runtime=chat_runtime,
            )
            tools.bind_agent_runtime(runtime)
            started = await runtime.start_from_tool(
                velox.ToolContext(velox.APP_SCOPE_ID, chat_id=chat["chat_id"]),
                {"task": "Survive endpoint request timeouts."},
            )
            agent_id = str(started["agent_id"])
            paused = await asyncio.wait_for(runtime.wait_for_agent(agent_id), timeout=3.0)
            self.assertEqual(paused["status"], "paused")
            self.assertTrue(paused["paused_due_to_llm_timeout"])
            self.assertFalse(paused["paused_due_to_timeout"])
            self.assertEqual(paused["failure_message"], "")
            self.assertEqual(paused["llm_request_timeout_count"], 3)
            self.assertEqual(paused["llm_timeout_pause_count"], 1)
            self.assertEqual(fake.agent_calls, 3)
            events = agents.load_transcript(agent_id)
            self.assertEqual(sum(event.get("kind") == "llm_request_timeout" for event in events), 1)
            self.assertTrue(any(event.get("kind") == "llm_timeout_paused" for event in events))
            self.assertFalse(any(event.get("kind") == "failed" for event in events))

            report_id = f"{agent_id}:request_timeout:1"
            visible = None
            for _ in range(250):
                turns = chats.load_turns(velox.APP_SCOPE_ID, chat["chat_id"])
                visible = next((turn for turn in turns if str(turn.get("agent_report_response_for") or "") == report_id), None)
                if visible and visible.get("status") == "complete":
                    break
                await asyncio.sleep(0.01)
            self.assertIsNotNone(visible)
            self.assertIn("paused", str(visible.get("text") or "").lower())
            self.assertTrue(any("repeated endpoint request timeouts" in text.lower() for text in fake.report_instructions))

            fake.fail_agent_requests = False
            self.assertTrue(runtime.resume(agent_id))
            final = await asyncio.wait_for(runtime.wait_for_agent(agent_id), timeout=3.0)
            self.assertEqual(final["status"], "succeeded")
            self.assertFalse(final["paused_due_to_llm_timeout"])
            self.assertEqual(final["consecutive_llm_request_timeouts"], 0)
            self.assertEqual(fake.agent_calls, 3 + 1)
            await runtime.shutdown()
            pending_chat_tasks = [
                task for task in list(chat_runtime.running.values()) + list(chat_runtime._agent_report_workers.values())
                if task is not None and not task.done()
            ]
            chat_runtime.cancel_all()
            if pending_chat_tasks:
                await asyncio.gather(*pending_chat_tasks, return_exceptions=True)

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_streaming_errors_remain_errors_and_agent_reports_use_durable_fallback(self) -> None:
        class ErrorStreamLLM:
            async def chat_completions_stream(self, _request: LLMRequest):
                yield velox.LLMChunk(text="Partial response before the endpoint stopped.")
                yield velox.LLMChunk(
                    error=f"LLMRequestTimeoutError: smart LLM request timed out after {velox.LONG_ENDPOINT_TIMEOUT_SECONDS_DEFAULT} seconds",
                    done=True,
                )

        async def scenario(root: Path) -> None:
            paths, storage, chats, chat = self._chat(root)
            fake = ErrorStreamLLM()
            tools = velox.ToolRegistry(storage)
            runtime = velox.ChatRuntime(storage, chats, velox.ContextAssembler(paths), fake, tools)

            chats.append_turn(
                velox.APP_SCOPE_ID,
                chat["chat_id"],
                velox.make_turn(chat["chat_id"], "user", "Trigger a streaming timeout."),
            )
            assistant = velox.make_turn(
                chat["chat_id"], "assistant", "",
                endpoint_profile_id="smart", endpoint_label="smart", status="streaming",
            )
            chats.append_turn(velox.APP_SCOPE_ID, chat["chat_id"], assistant, mark_stale=False)
            await runtime._run_assistant_loop(
                velox.APP_SCOPE_ID,
                chat["chat_id"],
                assistant["turn_id"],
                "smart",
                "Trigger a streaming timeout.",
                "Streaming timeout regression",
            )
            stored = next(
                turn for turn in chats.load_turns(velox.APP_SCOPE_ID, chat["chat_id"])
                if turn.get("turn_id") == assistant["turn_id"]
            )
            self.assertEqual(stored["status"], "error")
            self.assertIn("Partial response", stored["text"])
            self.assertIn(f"timed out after {velox.LONG_ENDPOINT_TIMEOUT_SECONDS_DEFAULT} seconds", stored["text"])

            agents = velox.AgentStore(storage)
            agent = agents.create_agent(chat["chat_id"], "Produce a durable result.", title="Fallback report")
            agent = agents.update_agent(str(agent["agent_id"]), {
                "status": "succeeded",
                "progress_message": "Completed",
                "progress_percent": 100,
                "final_message": "Saved the durable result at C:/tmp/result.md.",
            })
            worker = runtime.enqueue_agent_report(agent, report_kind="terminal")
            self.assertIsNotNone(worker)
            await asyncio.wait_for(worker, timeout=2.0)
            report_id = f"{agent['agent_id']}:terminal:1"
            response = next(
                turn for turn in chats.load_turns(velox.APP_SCOPE_ID, chat["chat_id"])
                if str(turn.get("agent_report_response_for") or "") == report_id
            )
            self.assertEqual(response["status"], "complete")
            self.assertEqual(
                response["text"],
                "Agent **Fallback report** — Succeeded\n\nSaved the durable result at C:/tmp/result.md.",
            )
            self.assertNotIn("[error]", response["text"])
            runtime.cancel_all()

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_normal_shutdown_pauses_running_agent_and_restart_can_resume_it(self) -> None:
        class BlockingLLM:
            def __init__(self) -> None:
                self.started = asyncio.Event()
                self.never = asyncio.Event()

            async def chat_completions_once_full(self, _request: LLMRequest) -> dict[str, Any]:
                self.started.set()
                await self.never.wait()
                raise AssertionError("unreachable")

        class SuccessLLM:
            async def chat_completions_once_full(self, request: LLMRequest) -> dict[str, Any]:
                return {
                    "text": '$$AGENT_PROGRESS: {"message":"Resumed successfully after restart.","percent":100}',
                    "usage": {},
                    "model": "restart-test",
                    "endpoint": request.endpoint_profile_id,
                    "raw": {},
                }

        async def scenario(root: Path) -> None:
            paths, storage, chats, chat = self._chat(root)
            agents = velox.AgentStore(storage)
            tools = velox.ToolRegistry(storage)
            blocking = BlockingLLM()
            runtime = velox.AgentRuntime(storage, agents, chats, velox.ContextAssembler(paths), blocking, tools)
            started = await runtime.start_from_tool(
                velox.ToolContext(velox.APP_SCOPE_ID, chat_id=chat["chat_id"]),
                {"task": "Remain resumable while Velox closes."},
            )
            agent_id = str(started["agent_id"])
            await asyncio.wait_for(blocking.started.wait(), timeout=2.0)
            await runtime.shutdown()

            paused = agents.load_agent(agent_id)
            self.assertEqual(paused["status"], "paused")
            self.assertEqual(paused["failure_message"], "")
            self.assertIn("Velox closed", paused["progress_message"])
            shutdown_events = [
                event for event in agents.load_transcript(agent_id)
                if event.get("kind") == "paused" and bool((event.get("data") or {}).get("shutdown"))
            ]
            self.assertEqual(len(shutdown_events), 1)
            self.assertEqual(agents.recover_interrupted(), 0)

            resumed_runtime = velox.AgentRuntime(
                storage, agents, chats, velox.ContextAssembler(paths), SuccessLLM(), tools
            )
            self.assertTrue(resumed_runtime.resume(agent_id))
            final = await asyncio.wait_for(resumed_runtime.wait_for_agent(agent_id), timeout=2.0)
            self.assertEqual(final["status"], "succeeded")
            self.assertIn("Resumed successfully", final["final_message"])
            await resumed_runtime.shutdown()

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_invalid_numeric_settings_keep_last_valid_custom_values(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            _paths, storage, _chats = _make_test_chat_stack(Path(td))
            config = storage.load_config()
            config["llm"]["comfy"]["timeout_seconds"] = 3600
            config["agents"]["timeout_minutes"] = 777
            config["web"]["default_search_results"] = 17
            config["tools"]["malformed_tool_call_retry_limit"] = 9
            storage.write_config(config)

            panel = velox.Panels.__new__(velox.Panels)
            panel.services = type("ServicesStub", (), {"storage": storage})()
            panel.state = velox.UIState()
            persisted = storage.load_config()
            panel.state.config_draft = panel._settings_config_to_draft(persisted)
            panel.state.settings_last_valid_config = copy.deepcopy(persisted)
            panel.state.settings_last_saved_config_json = json.dumps(persisted, ensure_ascii=False, sort_keys=True)

            cases = [
                ("settings.comfy.timeout", ("llm", "comfy", "_ui_timeout_minutes"), "not-a-number"),
                ("settings.agents.timeout_minutes", ("agents", "timeout_minutes"), ""),
                ("settings.web.default_search_results", ("web", "default_search_results"), "1e2"),
                ("settings.tools.malformed_tool_call_retry_limit", ("tools", "malformed_tool_call_retry_limit"), "NaN"),
            ]
            for widget_id, draft_path, bad_value in cases:
                draft = panel.state.config_draft
                self.assertIsInstance(draft, dict)
                panel._settings_path_set(draft, draft_path, bad_value)
                panel.state.active_widget = widget_id
                panel.state.settings_last_active_widget = widget_id
                panel._autosave_settings_if_changed(draft)
                panel.state.active_widget = None
                panel._autosave_settings_if_changed(panel.state.config_draft)

            saved = storage.load_config()
            self.assertEqual(saved["llm"]["comfy"]["timeout_seconds"], 3600)
            self.assertEqual(saved["agents"]["timeout_minutes"], 777)
            self.assertEqual(saved["web"]["default_search_results"], 17)
            self.assertEqual(saved["tools"]["malformed_tool_call_retry_limit"], 9)

            panel.state.config_draft["web"]["default_search_results"] = "999"
            panel.state.active_widget = "settings.web.default_search_results"
            panel.state.settings_last_active_widget = "settings.web.default_search_results"
            panel.state.active_widget = None
            panel._autosave_settings_if_changed(panel.state.config_draft)
            self.assertEqual(storage.load_config()["web"]["default_search_results"], 999)

    def test_manifest_types_registry_lock_and_jsonl_read_lock_are_robust(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            paths, storage, _chats = _make_test_chat_stack(root)
            original_text = paths.app_json_path.read_text(encoding="utf-8")

            wrong_mapping = storage.load_config()
            wrong_mapping["history"] = []
            with self.assertRaises(velox.UnsupportedDataVersionError):
                storage.write_config(wrong_mapping)
            self.assertEqual(paths.app_json_path.read_text(encoding="utf-8"), original_text)

            wrong_scalar = storage.load_config()
            wrong_scalar["web"]["search_requests_per_minute"] = "thirty"
            with self.assertRaises(velox.UnsupportedDataVersionError):
                storage.write_config(wrong_scalar)
            self.assertEqual(paths.app_json_path.read_text(encoding="utf-8"), original_text)

            storage_a = velox.Storage(velox.AppPaths(root))
            storage_b = velox.Storage(velox.AppPaths(root))
            storage_a.ensure_first_run_files()
            storage_b.ensure_first_run_files()
            config_a = storage_a.load_config()
            config_a["ui"]["font_size"] = 21
            barrier = threading.Barrier(3)
            errors: list[BaseException] = []

            def write_settings() -> None:
                try:
                    barrier.wait(timeout=2.0)
                    storage_a.write_config(config_a)
                except BaseException as exc:  # pragma: no cover
                    errors.append(exc)

            def write_state() -> None:
                try:
                    barrier.wait(timeout=2.0)
                    storage_b.write_app_state({
                        "active_chat_id": "concurrent-chat",
                        "active_panel": "agents",
                        "file_picker_last_dir": td,
                    })
                except BaseException as exc:  # pragma: no cover
                    errors.append(exc)

            workers = [threading.Thread(target=write_settings), threading.Thread(target=write_state)]
            for worker in workers:
                worker.start()
            barrier.wait(timeout=2.0)
            for worker in workers:
                worker.join(timeout=5.0)
            self.assertFalse(any(worker.is_alive() for worker in workers))
            self.assertEqual(errors, [])
            manifest = velox.read_json(paths.app_json_path, {})
            self.assertEqual(manifest["settings"]["ui"]["font_size"], 21)
            self.assertEqual(manifest["state"]["active_chat_id"], "concurrent-chat")

            registry = velox.DataRootRegistry()
            lock_ids: list[int] = []
            register_barrier = threading.Barrier(5)

            def register_root() -> None:
                register_barrier.wait(timeout=2.0)
                registry.register(root)
                lock_ids.append(id(registry.lock_for_path(paths.app_json_path)))

            register_threads = [threading.Thread(target=register_root) for _ in range(4)]
            for worker in register_threads:
                worker.start()
            register_barrier.wait(timeout=2.0)
            for worker in register_threads:
                worker.join(timeout=5.0)
            self.assertEqual(len(lock_ids), 4)
            self.assertEqual(len(set(lock_ids)), 1)

            jsonl_path = root / "locking-test.jsonl"
            jsonl_path.write_text("", encoding="utf-8")
            half_written = threading.Event()
            allow_finish = threading.Event()
            reader_started = threading.Event()
            reader_done = threading.Event()
            reader_rows: list[dict[str, Any]] = []

            def slow_append() -> None:
                with velox.DATA_ROOTS.lock_for_path(jsonl_path):
                    with jsonl_path.open("a", encoding="utf-8", newline="") as handle:
                        handle.write('{"value":')
                        handle.flush()
                        half_written.set()
                        allow_finish.wait(timeout=2.0)
                        handle.write('42}\n')
                        handle.flush()

            def read_during_append() -> None:
                reader_started.set()
                reader_rows.extend(velox.iter_jsonl(jsonl_path))
                reader_done.set()

            writer = threading.Thread(target=slow_append)
            writer.start()
            self.assertTrue(half_written.wait(timeout=2.0))
            reader = threading.Thread(target=read_during_append)
            reader.start()
            self.assertTrue(reader_started.wait(timeout=2.0))
            time.sleep(0.05)
            self.assertFalse(reader_done.is_set())
            allow_finish.set()
            writer.join(timeout=5.0)
            reader.join(timeout=5.0)
            self.assertEqual(reader_rows, [{"value": 42}])
            # The production logger is intentionally asynchronous. Drain this
            # temporary root before TemporaryDirectory removes it so the daemon
            # cannot race the test harness by recreating log.jsonl during rmtree.
            self.assertTrue(velox.APP_LOG_WRITER.flush((paths.log_jsonl_path,), timeout=3.0))

    def test_agent_expert_mode_continuation_injects_one_normal_user_message_without_private_inference(self) -> None:
        async def scenario(root: Path) -> None:
            class DummyLLM:
                async def chat_completions_once_full(self, _request: LLMRequest) -> dict[str, Any]:
                    raise AssertionError("Checklist continuation must not create a private endpoint request")

            paths = velox.AppPaths(root)
            storage = velox.Storage(paths)
            storage.ensure_first_run_files()
            monitor = velox.LLMTaskMonitor(storage)
            _paths, _storage, _chats, chat, agents, _tools, runtime = self._agent_stack(
                root, DummyLLM(), monitor=monitor,
            )
            agent = agents.create_agent(str(chat["chat_id"]), "Verify ordinary Checklist continuation.")
            agent_id = str(agent["agent_id"])
            store = velox.ExpertModeStore.for_agent(storage, agent)
            velox.ChecklistStore(storage).create(velox._agent_checklist_owner(agent), name="Assigned acceptance", items=["Create the requested output", "Run validation"])
            messages = [
                {"role": "system", "content": "System"},
                {"role": "user", "content": "Complete the task."},
                {"role": "assistant", "content": "Candidate output."},
            ]
            before_tasks = monitor.list_records()
            action, diagnostic = await runtime._handle_agent_expert_mode_stop(
                agent_id,
                str(agent["endpoint_profile_id"]),
                messages,
                "Candidate output.",
                "Candidate output.",
                iteration=1,
                request_id=None,
                reason="test ordinary follow-up",
            )
            self.assertEqual((action, diagnostic), ("continue", ""))
            self.assertEqual(messages[-1]["role"], "user")
            self.assertIn("CHECKLISTS - CONTINUE", messages[-1]["content"])
            self.assertIn("C1", messages[-1]["content"])
            self.assertEqual(monitor.list_records(), before_tasks)

            duplicate_action, duplicate_diagnostic = await runtime._handle_agent_expert_mode_stop(
                agent_id,
                str(agent["endpoint_profile_id"]),
                messages[:-1],
                "Candidate output.",
                "Candidate output.",
                iteration=1,
                request_id=None,
                reason="test ordinary follow-up",
            )
            self.assertEqual((duplicate_action, duplicate_diagnostic), ("duplicate", ""))
            state = store.load()
            self.assertEqual(state["continuation_count"], 1)
            events = agents.load_transcript(agent_id)
            self.assertEqual(sum(event.get("kind") == "expert_mode_continuation" for event in events), 1)
            self.assertTrue(any(
                event.get("kind") == "conversation_message"
                and (event.get("data") or {}).get("role") == "user"
                and "CHECKLISTS - CONTINUE" in str((event.get("data") or {}).get("content") or "")
                for event in events
            ))
            transcript = velox.agent_transcript_markdown(agents.load_agent(agent_id), events)
            self.assertIn("CHECKLISTS - CONTINUE", transcript)
            self.assertNotIn("MESSAGE SENT TO THE LLM (EXACT)", transcript)
            await runtime.shutdown()

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_jsonl_torn_tail_is_ignored_and_repaired_before_append(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            velox.DATA_ROOTS.register(root)
            path = root / "events.jsonl"
            path.write_bytes(
                b'{"index":1}\n{"index":2}\n{"index":3}\n{"index":4}\n{"index":5}\n{"torn":'
            )

            self.assertEqual(velox.iter_jsonl(path), [{"index": i} for i in range(1, 6)])
            self.assertEqual(velox.iter_jsonl_tail(path, 3), [{"index": 3}, {"index": 4}, {"index": 5}])
            velox.append_jsonl(path, {"index": 6})
            self.assertEqual(velox.iter_jsonl(path), [{"index": i} for i in range(1, 7)])
            self.assertEqual(
                path.read_bytes(),
                b'{"index":1}\n{"index":2}\n{"index":3}\n{"index":4}\n{"index":5}\n{"index":6}\n',
            )

            # A complete final object without a newline is valid and must be
            # separated rather than discarded when another row is appended.
            valid_tail = root / "valid-tail.jsonl"
            valid_tail.write_bytes(b'{"index":4}')
            velox.append_jsonl(valid_tail, {"index": 5})
            self.assertEqual(velox.iter_jsonl(valid_tail), [{"index": 4}, {"index": 5}])

            # Newline-terminated interior corruption is not a crash-torn tail;
            # preserve its diagnostic so strict record readers still reject it.
            corrupt = root / "corrupt.jsonl"
            corrupt.write_bytes(b'{"index":6}\nnot-json\n{"index":7}\n')
            rows = velox.iter_jsonl(corrupt)
            self.assertEqual(rows[0], {"index": 6})
            self.assertEqual(rows[1]["schema"], "corrupt_jsonl_line.v1")
            self.assertEqual(rows[2], {"index": 7})


    def test_configured_tool_timeouts_are_hard_caps_and_compound_budgets_are_safe(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            _paths, storage, _chats, _chat = self._chat(root)
            config = storage.load_config()
            config["tools"].update({"shell_timeout_minutes": 2.0, "python_timeout_minutes": 3.0})
            config["web"]["fetch_timeout_seconds"] = 50
            config["llm"]["comfy"]["timeout_seconds"] = 60
            config["meshy"]["timeout_seconds"] = 70
            storage.write_config(config)
            self.assertEqual(velox.bounded_timeout_seconds(9999, 20), 20.0)
            registry = velox.ToolRegistry(storage)
            with self.assertRaisesRegex(ValueError, "timeout_minutes is required"):
                registry._timeout_for_tool("shell_exec", {})
            with self.assertRaisesRegex(ValueError, "timeout_minutes is required"):
                registry._timeout_for_tool("python_exec", {})
            self.assertEqual(registry._timeout_for_tool("shell_exec", {"timeout_minutes": 7}), 125.0)
            self.assertEqual(registry._timeout_for_tool("python_exec", {"timeout_minutes": 8.5}), 185.0)
            with self.assertRaisesRegex(ValueError, "positive finite"):
                registry._timeout_for_tool("shell_exec", {"timeout_minutes": 0})
            with self.assertRaisesRegex(ValueError, "positive finite"):
                registry._timeout_for_tool("python_exec", {"timeout_minutes": True})
            self.assertNotIn("git.exec", registry.tools)
            self.assertEqual(velox.WebTools(storage)._timeout({"timeout_seconds": 5000}), 50)
            self.assertEqual(velox.ComfyTools(storage)._timeout({"timeout_seconds": 5000}), 60)
            self.assertEqual(velox.MeshyTools(storage)._timeout({"timeout_seconds": 5000}), 70)

    def test_chat_turn_edits_touch_metadata_only_when_a_turn_changes(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            paths, _storage, chats, chat = self._chat(Path(td))
            chat_id = chat["chat_id"]
            user_turn = velox.make_turn(chat_id, "user", "original user text")
            assistant_turn = velox.make_turn(chat_id, "assistant", "original answer")
            chats.append_turn(velox.APP_SCOPE_ID, chat_id, user_turn)
            chats.append_turn(velox.APP_SCOPE_ID, chat_id, assistant_turn)
            self._write_chat_summary(paths, chat_id, "- current", "current")

            old_timestamp = "2000-01-01T00:00:00.000000Z"
            self._set_chat_updated(paths, chats, chat_id, old_timestamp)
            chats.edit_user_turn(velox.APP_SCOPE_ID, chat_id, user_turn["turn_id"], "edited user text")
            self.assertNotEqual(chats.load_chat(chat_id)["updated_at"], old_timestamp)
            turns = chats.load_turns(velox.APP_SCOPE_ID, chat_id)
            edited = next(turn for turn in turns if turn["turn_id"] == user_turn["turn_id"])
            self.assertEqual(edited["text"], "edited user text")
            self.assertEqual(edited["edit_history"][-1]["old_text"], "original user text")
            self.assertTrue(velox.read_json(paths.chat_summary_json(chat_id), {})["stale"])

            # A stale UI action that references a missing turn must not rewrite
            # history, move the chat to the top, or invalidate its summary.
            unchanged_timestamp = "2001-01-01T00:00:00.000000Z"
            self._set_chat_updated(paths, chats, chat_id, unchanged_timestamp)
            self._write_chat_summary(paths, chat_id, "- still current", "still current")
            before_bytes = paths.chat_turns_jsonl(chat_id).read_bytes()
            chats.edit_assistant_turn(velox.APP_SCOPE_ID, chat_id, velox.uuid_v4(), "not present")
            self.assertEqual(chats.load_chat(chat_id)["updated_at"], unchanged_timestamp)
            self.assertEqual(paths.chat_turns_jsonl(chat_id).read_bytes(), before_bytes)
            self.assertFalse(velox.read_json(paths.chat_summary_json(chat_id), {})["stale"])

    def test_large_file_read_copy_and_attachment_paths_do_not_require_full_memory_reads(self) -> None:
        async def scenario(root: Path) -> None:
            paths, storage, _chats, chat = self._chat(root)
            chat_id = chat["chat_id"]
            source = root / "large-source.txt"
            body = "0123456789abcdef\n" * 8192
            source.write_bytes(body.encode("utf-8"))
            ctx = velox.ToolContext(scope_id=velox.APP_SCOPE_ID, chat_id=chat_id)
            file_tools = velox.FileTools(storage)

            config = storage.load_config()
            config["tools"]["file_read_max_chars"] = 25
            storage.write_config(config)
            with self.assertRaisesRegex(ValueError, "configured 25 text characters"):
                await file_tools.read_file(ctx, {"path": str(source)})

            config = storage.load_config()
            config["tools"]["file_read_max_chars"] = len(body)
            storage.write_config(config)
            complete = await file_tools.read_file(ctx, {"path": str(source)})
            self.assertEqual(complete["text"], body)
            self.assertEqual(complete["characters"], len(body))
            registry = velox.ToolRegistry(storage)
            self.assertNotIn("fs_copy_to_workspace", registry.tools)
            self.assertFalse(hasattr(file_tools, "copy_to_workspace"))

            original_reader = vars(velox)["file_read_bytes"]
            def forbidden_full_read(path: Path) -> bytes:
                if Path(path).resolve() == source.resolve():
                    raise AssertionError("large source was read into memory through file_read_bytes")
                return original_reader(path)

            vars(velox)["file_read_bytes"] = forbidden_full_read
            try:
                attached = velox.AttachmentStore(storage).attach_file(velox.APP_SCOPE_ID, source, "chat", chat_id)
                panel = velox.Panels.__new__(velox.Panels)
                panel.services = type("ServicesStub", (), {"storage": storage, "chats": _chats})()
                panel.state = velox.UIState()
                panel.state.active_scope_id = velox.APP_SCOPE_ID
                panel.state.active_chat_id = chat_id
                panel.attach_files_by_paths([source])
                self.assertEqual(len(panel.state.queued_attachments), 1)
            finally:
                vars(velox)["file_read_bytes"] = original_reader

            attachment_path = paths.chat_dir(chat_id) / attached["path"]
            self.assertEqual(attachment_path.read_text(encoding="utf-8"), body)
            self.assertEqual(attached["bytes"], source.stat().st_size)
            self.assertEqual(attached["sha256"], velox.sha256_file(source))

            def forbid_attachment_binary_read(path: Path) -> bytes:
                if Path(path).resolve() == attachment_path.resolve():
                    raise AssertionError("attachment preview read the complete file as bytes")
                return original_reader(path)

            vars(velox)["file_read_bytes"] = forbid_attachment_binary_read
            try:
                preview = velox.AttachmentStore(storage).attachment_text_for_prompt(
                    velox.APP_SCOPE_ID, attached, max_chars=37,
                )
            finally:
                vars(velox)["file_read_bytes"] = original_reader
            self.assertEqual(preview.split("\n\n[VELOX ATTACHMENT PREVIEW TRUNCATED:", 1)[0], body[:37])
            self.assertIn("first 37 text characters only", preview)

            oversized = root / "oversized-meshy.bin"
            with oversized.open("wb") as handle:
                handle.truncate(100 * 1024 * 1024 + 1)
            vars(velox)["file_read_bytes"] = lambda _path: (_ for _ in ()).throw(
                AssertionError("oversized Meshy input was read before the size check")
            )
            try:
                with self.assertRaisesRegex(RuntimeError, "configured max bytes=104857600"):
                    velox.MeshyTools(storage)._data_uri(oversized)
            finally:
                vars(velox)["file_read_bytes"] = original_reader

            panel_source = self._method_source(velox.Panels, "attach_files_by_paths")
            self.assertIn("store.attach_file", panel_source)
            self.assertNotIn("path.read_bytes", panel_source)

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_compaction_uses_reported_context_preserves_latest_boundaries_and_reconciles_counts(self) -> None:
        class CompactLLM:
            async def chat_completions_once_full(self, request: LLMRequest) -> dict[str, Any]:
                return {
                    "text": "- Durable earlier fact.\n- Continue from the preserved boundary.",
                    "usage": {"prompt_tokens": 1000, "completion_tokens": 20},
                    "model": "compact-test", "endpoint": request.endpoint_profile_id, "raw": {},
                }

        async def scenario(root: Path) -> None:
            paths, storage, chats, chat = self._chat(root)
            agents = velox.AgentStore(storage)
            tools = velox.ToolRegistry(storage)
            runtime = velox.AgentRuntime(storage, agents, chats, velox.ContextAssembler(paths), CompactLLM(), tools)
            agent = agents.create_agent(
                chat["chat_id"], "Preserve every critical boundary.",
                context_window_tokens=8192, max_output_tokens=1024,
            )
            agent_id = str(agent["agent_id"])
            system = "IMMUTABLE SYSTEM AND TOOL PROTOCOL"
            task = "# Assigned task\nPreserve every critical boundary."
            agents.append_event(agent_id, "started", {"system_prompt": system, "user_prompt": task})
            agents.update_agent(agent_id, {"last_context_tokens": 6000})
            latest_tool = '$$TOOLCALL: {"toolcall":{"toolname":"fs_read","param":{"path":"a.txt"}}}'
            latest_result = '$$TOOL RESULT: {"ok":true,"text":"important"}'
            latest_thinking = "<think>NEWEST THINKING BLOCK</think>\nContinuing carefully."
            messages = [
                {"role": "system", "content": "corrupted replacement"},
                {"role": "user", "content": "corrupted task"},
                {"role": "assistant", "content": "old content " + ("x" * 300)},
                {"role": "user", "content": "old result " + ("y" * 300)},
                {"role": "assistant", "content": latest_tool},
                {"role": "user", "content": latest_result},
                {"role": "assistant", "content": latest_thinking},
            ]
            compacted = await runtime._maybe_compact_agent_context(agent_id, messages, force=True)
            self.assertTrue(compacted)
            self.assertEqual(messages[0], {"role": "system", "content": system})
            self.assertEqual(messages[1], {"role": "user", "content": task})
            self.assertEqual(messages[-3:], [
                {"role": "assistant", "content": latest_tool},
                {"role": "user", "content": latest_result},
                {"role": "assistant", "content": latest_thinking},
            ])
            event = next(
                event for event in reversed(agents.load_transcript(agent_id))
                if event.get("kind") == "context_compacted"
            )
            self.assertEqual(event["data"]["reported_before_tokens"], 6000)
            self.assertEqual(event["data"]["complete_before_tokens"], 6000)
            self.assertEqual(event["data"]["before_tokens"], event["data"]["estimated_before_tokens"])
            self.assertLess(event["data"]["estimated_before_tokens"], 6000)
            self.assertEqual(
                event["data"]["system_prompt_sha256"],
                velox.sha256_bytes(system.encode("utf-8")),
            )
            self.assertEqual(
                event["data"]["task_prompt_sha256"],
                velox.sha256_bytes(task.encode("utf-8")),
            )

            # Simulate a crash after the durable checkpoint append but before
            # the metadata counter update. Dashboard/detail statistics must use
            # the transcript checkpoint count rather than silently undercount.
            agents.append_event(agent_id, "context_compacted", {
                "compaction_count": 2, "before_tokens": 5000, "after_tokens": 800,
                "context_window_tokens": 8192, "max_output_tokens": 1024,
                "compaction_input_tokens": 500, "compaction_output_tokens": 20,
                "summary": "Second durable checkpoint.", "messages": messages,
            })
            self.assertEqual(agents.load_agent(agent_id)["compaction_count"], 1)
            stats = agents.statistics()
            self.assertEqual(stats["compaction_events"], 2)
            self.assertEqual(stats["average_compaction_events"], 2.0)
            transcript = agents.load_transcript(agent_id)
            markdown = velox.agent_transcript_markdown(agents.load_agent(agent_id), transcript)
            self.assertIn("Context compactions:** 2", markdown)
            compacted_text = velox.agent_compaction_results_text(transcript)
            self.assertIn("====== Compaction Event #1 ======", compacted_text)
            self.assertIn("====== Compaction Event #2 ======", compacted_text)
            self.assertIn("LITERAL NEW CONTEXT", compacted_text)
            self.assertIn(system, compacted_text)
            self.assertIn(task, compacted_text)
            self.assertIn("NEWEST THINKING BLOCK", compacted_text)

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))


