    def test_file_and_system_toggles_exhaustively_control_their_tool_groups(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            _paths, storage, chats, chat = self._chat(Path(td))
            registry = velox.ToolRegistry(storage)
            for name in registry.tools:
                expected = (
                    "checklists_enabled" if name in velox.EXPERT_MODE_TOOL_NAMES or name in velox.CHECKLIST_TOOL_NAMES
                    else "file_tools_enabled" if name.startswith(velox.FILE_TOOL_PREFIXES)
                    else "web_tools_enabled" if name.startswith(("web_", "browser_"))
                    else "chat_history_enabled" if name.startswith("chats_")
                    else "agent_tools_enabled" if name.startswith("agents_") or name in {
                        "terminal_get_agent_terminals", "terminal_get_agent_terminal_output",
                    }
                    else "system_tools_enabled"
                )
                self.assertEqual(registry._tool_group_for_name(name), expected, name)

            chat_id = str(chat["chat_id"])
            chats.set_chat_feature(velox.APP_SCOPE_ID, chat_id, "file_tools_enabled", True)
            chats.set_chat_feature(velox.APP_SCOPE_ID, chat_id, "system_tools_enabled", False)
            chats.set_chat_feature(velox.APP_SCOPE_ID, chat_id, "web_tools_enabled", True)
            chats.set_chat_feature(velox.APP_SCOPE_ID, chat_id, "agent_tools_enabled", False)
            chats.set_chat_feature(velox.APP_SCOPE_ID, chat_id, "chat_history_enabled", True)
            enabled = {row["name"] for row in registry.tool_definitions_for_context(velox.APP_SCOPE_ID, chat_id)}
            self.assertIn("fs_list", enabled)
            self.assertIn("doc_import", enabled)
            self.assertIn("web_search", enabled)
            self.assertIn("chats_search", enabled)
            self.assertTrue(set(velox.CHECKLIST_TOOL_NAMES).issubset(enabled))
            self.assertFalse(set(velox._INTERNAL_EXPERT_TOOL_NAMES).intersection(enabled))
            for name in ("time_now", "agents_start", "comfy_text_to_image", "meshy_text_to_3d"):
                self.assertNotIn(name, enabled)
                with self.assertRaises(PermissionError):
                    registry._reject_disabled_tool(velox.APP_SCOPE_ID, name, chat_id)

            chats.set_chat_feature(velox.APP_SCOPE_ID, chat_id, "file_tools_enabled", False)
            enabled = {row["name"] for row in registry.tool_definitions_for_context(velox.APP_SCOPE_ID, chat_id)}
            for name in ("fs_list", "doc_import"):
                self.assertNotIn(name, enabled)
                with self.assertRaises(PermissionError):
                    registry._reject_disabled_tool(velox.APP_SCOPE_ID, name, chat_id)

            for key in velox.CHAT_TOOL_FEATURE_KEYS:
                chats.set_chat_feature(velox.APP_SCOPE_ID, chat_id, key, False)
            no_optional_names = {row["name"] for row in registry.tool_definitions_for_context(velox.APP_SCOPE_ID, chat_id)}
            self.assertEqual(no_optional_names, set())
            chats.set_chat_feature(velox.APP_SCOPE_ID, chat_id, "checklists_enabled", True)
            self.assertEqual({row["name"] for row in registry.tool_definitions_for_context(velox.APP_SCOPE_ID, chat_id)}, set(velox.CHECKLIST_TOOL_NAMES))
            chats.set_chat_feature(velox.APP_SCOPE_ID, chat_id, "agent_tools_enabled", True)
            agent_names = {row["name"] for row in registry.tool_definitions_for_context(velox.APP_SCOPE_ID, chat_id)}
            for name in (
                "agents_start", "agents_list", "agents_pause", "agents_resume", "agents_stop",
                "terminal_get_agent_terminals", "terminal_get_agent_terminal_output",
            ):
                self.assertIn(name, agent_names)
                registry._reject_disabled_tool(velox.APP_SCOPE_ID, name, chat_id)
            self.assertNotIn("python_exec", agent_names)
            self.assertNotIn("fs_read", agent_names)
            self.assertNotIn("web_search", agent_names)
            self.assertNotIn("chats_search", agent_names)

            setup = self._method_source(velox.Panels, "_draw_new_chat_task_settings")
            sidebar = self._method_source(velox.Panels, "draw_chat_chats_panel")
            defaults = self._method_source(velox.Panels, "_draw_tool_defaults_card")
            self.assertIn("Local file and document read", setup)
            self.assertIn("Shell and Python execution", setup)
            self.assertIn("Start, list, pause, resume, stop", setup)
            self.assertNotIn("file_tools_enabled", sidebar)
            self.assertNotIn("system_tools_enabled", sidebar)
            self.assertIn("fs_ and doc_", defaults)

    def test_general_file_path_guidance_and_explicit_workspace_destination(self) -> None:
        async def scenario(root: Path) -> None:
            paths, storage, _chats, chat = self._chat(root)
            chat_id = str(chat["chat_id"])
            ctx = velox.ToolContext(velox.APP_SCOPE_ID, chat_id=chat_id)
            file_tools = velox.FileTools(storage)
            app_relative_directory = root / "workspace"
            app_relative_directory.mkdir(parents=True)
            listed = await file_tools.list_files(ctx, {"path": "workspace"})
            self.assertTrue(_paths_equivalent(Path(listed["path"]), app_relative_directory.resolve()))
            await file_tools.write_file(ctx, {"path": "workspace/report.txt", "content": "app relative"})
            workspace_target = paths.chat_workspace_dir(chat_id) / "final-report.txt"
            await file_tools.write_file(ctx, {"path": str(workspace_target), "content": "durable output"})
            self.assertEqual(workspace_target.read_text(encoding="utf-8"), "durable output")
            context_prompt = velox.ContextAssembler(paths).assemble_chat_context(velox.APP_SCOPE_ID, chat_id)[0]["content"]
            agent_store = velox.AgentStore(storage)
            agent = agent_store.create_agent(chat_id, "Path guidance")
            agent_prompt = velox.AgentRuntime(storage, agent_store, velox.ChatStore(storage), velox.ContextAssembler(paths), object(), velox.ToolRegistry(storage)).build_standard_system_prompt(agent)
            self.assertIn(str(paths.root_dir).replace("\\", "/"), context_prompt)
            self.assertIn(str(paths.chat_workspace_dir(chat_id)).replace("\\", "/"), context_prompt)
            self.assertIn(str(paths.root_dir), agent_prompt)
            self.assertIn(str(paths.chat_workspace_dir(chat_id)), agent_prompt)
            self.assertIn('Relative file paths resolve from the Velox application root', context_prompt)
            self.assertIn('Store final work in workspace', context_prompt)
            self.assertIn("Use the exact absolute workspace path above", agent_prompt)

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_compaction_rejects_tiny_output_and_displays_literal_new_context(self) -> None:
        class TinyCompactionLLM:
            async def chat_completions_once_full(self, request: LLMRequest) -> dict[str, Any]:
                self.last_request = copy.deepcopy(request)
                return {
                    "text": "<think>Reasoning consumed the completion without visible memory.</think>",
                    "usage": {"prompt_tokens": 5_000, "completion_tokens": 18},
                    "model": "tiny-compactor", "endpoint": request.endpoint_profile_id, "raw": {},
                    "finish_reason": "length", "stop_reason": "",
                }

        async def scenario(root: Path) -> None:
            paths, storage, chats, chat = self._chat(root)
            agents = velox.AgentStore(storage)
            tiny_llm = TinyCompactionLLM()
            runtime = velox.AgentRuntime(
                storage, agents, chats, velox.ContextAssembler(paths), tiny_llm, velox.ToolRegistry(storage),
            )
            agent = agents.create_agent(
                chat["chat_id"], "Produce a durable report.",
                context_window_tokens=8192, max_output_tokens=1024,
            )
            agent_id = str(agent["agent_id"])
            system = "ORIGINAL SYSTEM AND TOOL INSTRUCTIONS"
            task = "# Assigned task\nProduce a durable report exactly as requested."
            agents.append_event(agent_id, "started", {"system_prompt": system, "user_prompt": task})
            messages: list[dict[str, Any]] = [
                {"role": "system", "content": "corrupted"},
                {"role": "user", "content": "corrupted"},
            ]
            for index in range(8):
                messages.append({"role": "assistant", "content": f"Intermediate analysis {index}: " + ("a" * 900)})
                messages.append({"role": "user", "content": f"Intermediate result {index}: " + ("b" * 900)})
            recent = [
                {"role": "assistant", "content": "Most recent reasoning block."},
                {"role": "assistant", "content": '$$TOOLCALL: {"toolcall":{"toolname":"fs_list","param":{"path":"."}}}'},
                {"role": "user", "content": '$$TOOL RESULT: {"ok":true,"entries":[]}'},
            ]
            messages.extend(copy.deepcopy(recent))
            compacted = await runtime._maybe_compact_agent_context(agent_id, messages, force=True)
            self.assertTrue(compacted)
            self.assertEqual(messages[0], {"role": "system", "content": system})
            self.assertEqual(messages[1], {"role": "user", "content": task})
            self.assertEqual(messages[-velox.AGENT_COMPACTION_RECENT_MESSAGES:], recent)
            self.assertIn("## Execution facts", messages[2]["content"])
            self.assertNotIn("Reasoning consumed the completion", messages[2]["content"])
            self.assertGreaterEqual(int(tiny_llm.last_request.max_output_tokens or 0), 8_192)
            self.assertEqual(tiny_llm.last_request.reasoning_effort_override, "minimal")

            event = next(
                row for row in reversed(agents.load_transcript(agent_id))
                if row.get("kind") == "context_compacted"
            )
            self.assertIn("unusable compaction response", event["data"]["fallback_error"])
            self.assertEqual(event["data"]["summary_strategy"], "structured_operational_ledger")
            self.assertGreaterEqual(event["data"]["summary_budget_tokens"], 2_048)
            self.assertGreaterEqual(event["data"]["model_output_budget_tokens"], 8_192)
            self.assertEqual(event["data"]["semantic_finish_reason"], "length")
            self.assertEqual(event["data"]["messages"], messages)
            self.assertEqual(event["data"]["preserved_recent_message_count"], velox.AGENT_COMPACTION_RECENT_MESSAGES)
            literal = velox.agent_compaction_results_text([event])
            self.assertIn("LITERAL NEW CONTEXT", literal)
            self.assertIn("----- Message 1 of", literal)
            self.assertIn(system, literal)
            self.assertIn(task, literal)
            self.assertIn("Most recent reasoning block", literal)
            self.assertIn("fs_list", literal)

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))


    def test_new_chat_receives_all_prior_one_line_summaries_newest_first(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            paths, storage, chats = _make_test_chat_stack(Path(td))
            oldest = chats.create_chat("Oldest")
            missing = chats.create_chat("No Summary Yet")
            newest = chats.create_chat("Newest")
            current = chats.create_chat("Current")
            self._write_chat_summary(
                paths,
                oldest["chat_id"],
                "- Older detailed bullet that should not be injected",
                one="Older one-line summary",
            )
            self._write_chat_summary(
                paths,
                newest["chat_id"],
                "- Newest detailed bullet that should not be injected",
                one="Newest one-line summary",
            )
            self._set_chat_updated(paths, chats, newest["chat_id"], "2026-04-04T00:00:00Z")
            self._set_chat_updated(paths, chats, missing["chat_id"], "2026-03-03T00:00:00Z")
            self._set_chat_updated(paths, chats, oldest["chat_id"], "2026-01-01T00:00:00Z")
            first = velox.make_turn(current["chat_id"], "user", "Start a new task")
            first["chat_history_context_enabled"] = True
            chats.append_turn(velox.APP_SCOPE_ID, current["chat_id"], first)

            runtime = velox.ChatRuntime(storage, chats, velox.ContextAssembler(paths), velox.LLMClient(storage), velox.ToolRegistry(storage))
            context = runtime._first_message_history_context(
                velox.APP_SCOPE_ID,
                current["chat_id"],
                chats.load_turns(velox.APP_SCOPE_ID, current["chat_id"]),
            )
            self.assertTrue(context.startswith("Here's recent chats for context (newest first):"))
            self.assertIn(str(newest["chat_id"]), context)
            self.assertIn(str(missing["chat_id"]), context)
            self.assertIn(str(oldest["chat_id"]), context)
            self.assertNotIn(str(current["chat_id"]), context)
            self.assertLess(context.index("Newest one-line summary"), context.index("No stored summary yet."))
            self.assertLess(context.index("No stored summary yet."), context.index("Older one-line summary"))
            self.assertNotIn("Newest detailed bullet", context)
            self.assertNotIn("Older detailed bullet", context)

            agent_store = velox.AgentStore(storage)
            agent = agent_store.create_agent(
                current["chat_id"], "Independent agent task",
            )
            agent_prompt = velox.AgentRuntime(
                storage,
                agent_store,
                chats,
                velox.ContextAssembler(paths),
                object(),
                velox.ToolRegistry(storage),
            ).build_standard_system_prompt(agent)
            self.assertNotIn("Here's recent chats for context", agent_prompt)

    def test_deletion_cascades_linked_agents_and_restricts_direct_agent_delete(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            paths, storage, chats = _make_test_chat_stack(Path(td))
            source = chats.create_chat("Source")
            other = chats.create_chat("Other")
            agents = velox.AgentStore(storage)
            llm = velox.LLMClient(storage)
            monitor = velox.LLMTaskMonitor(storage)
            context = velox.ContextAssembler(paths)
            tools = velox.ToolRegistry(storage)
            chat_runtime = velox.ChatRuntime(storage, chats, context, llm, tools, monitor)
            agent_runtime = velox.AgentRuntime(storage, agents, chats, context, llm, tools, monitor, chat_runtime)
            tools.bind_agent_runtime(agent_runtime)
            services = velox.Services(
                storage=storage,
                chats=chats,
                agents=agents,
                llm=llm,
                context=context,
                tools=tools,
                summaries=velox.SummaryService(storage, chats, llm, monitor),
                chat=chat_runtime,
                agent_runtime=agent_runtime,
                monitor=monitor,
            )

            directly_deletable = agents.create_agent(other["chat_id"], "Paused run", title="Paused")
            directly_deletable = agents.update_agent(directly_deletable["agent_id"], {"status": "paused"})
            services.delete_agent(directly_deletable["agent_id"])
            self.assertFalse(paths.agent_dir(directly_deletable["agent_id"]).exists())
            self.assertNotIn(directly_deletable["agent_id"], agent_runtime._preserve_on_shutdown)

            protected = agents.create_agent(other["chat_id"], "Running run", title="Running")
            agents.update_agent(protected["agent_id"], {"status": "running"})
            with self.assertRaises(ValueError):
                services.delete_agent(protected["agent_id"])
            self.assertTrue(paths.agent_dir(protected["agent_id"]).is_dir())

            linked_ids: list[str] = []
            for status in ("queued", "running", "paused", "succeeded", "failed", "cancelled"):
                row = agents.create_agent(source["chat_id"], f"Linked {status}", title=f"Linked {status}")
                if status != "queued":
                    row = agents.update_agent(row["agent_id"], {"status": status})
                linked_ids.append(str(row["agent_id"]))
            result = services.delete_chat(source["chat_id"])
            self.assertEqual(set(result["deleted_agent_ids"]), set(linked_ids))
            self.assertFalse(paths.chat_dir(source["chat_id"]).exists())
            for agent_id in linked_ids:
                self.assertFalse(paths.agent_dir(agent_id).exists())
                self.assertNotIn(agent_id, agent_runtime._preserve_on_shutdown)
                self.assertNotIn(agent_id, agents._compaction_count_cache)
            self.assertTrue(paths.chat_dir(other["chat_id"]).is_dir())
            self.assertTrue(paths.agent_dir(protected["agent_id"]).is_dir())

    def test_deleting_chat_cancels_a_live_linked_agent_without_recreating_records(self) -> None:
        class BlockingLLM:
            def __init__(self) -> None:
                self.started = asyncio.Event()
                self.never = asyncio.Event()

            async def chat_completions_once_full(self, request: LLMRequest) -> dict[str, Any]:
                self.started.set()
                await self.never.wait()
                raise AssertionError("unreachable")

        async def scenario(root: Path) -> None:
            paths, storage, chats = _make_test_chat_stack(root)
            chat = chats.create_chat("Delete with live agent")
            agents = velox.AgentStore(storage)
            fake = BlockingLLM()
            monitor = velox.LLMTaskMonitor(storage)
            context = velox.ContextAssembler(paths)
            tools = velox.ToolRegistry(storage)
            chat_runtime = velox.ChatRuntime(storage, chats, context, fake, tools, monitor)
            agent_runtime = velox.AgentRuntime(storage, agents, chats, context, fake, tools, monitor, chat_runtime)
            tools.bind_agent_runtime(agent_runtime)
            services = velox.Services(
                storage=storage,
                chats=chats,
                agents=agents,
                llm=fake,
                context=context,
                tools=tools,
                summaries=velox.SummaryService(storage, chats, fake, monitor),
                chat=chat_runtime,
                agent_runtime=agent_runtime,
                monitor=monitor,
            )
            started = await agent_runtime.start_from_tool(
                velox.ToolContext(velox.APP_SCOPE_ID, chat_id=chat["chat_id"]),
                {"task": "Remain blocked until the source chat is deleted.", "title": "Live deletion", "expert_mode": False},
            )
            agent_id = str(started["agent_id"])
            await asyncio.wait_for(fake.started.wait(), timeout=2.0)
            task = agent_runtime.running[agent_id]
            result = services.delete_chat(chat["chat_id"])
            self.assertEqual(result["deleted_agent_ids"], [agent_id])
            await asyncio.gather(task, return_exceptions=True)
            await asyncio.sleep(0)
            self.assertFalse(paths.chat_dir(chat["chat_id"]).exists())
            self.assertFalse(paths.agent_dir(agent_id).exists())
            self.assertNotIn(agent_id, agent_runtime.running)
            self.assertNotIn(agent_id, agent_runtime._preserve_on_shutdown)
            self.assertEqual(agents.list_agents(chat["chat_id"]), [])
            await agent_runtime.shutdown()

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_failed_chat_delete_restores_background_summary_eligibility(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            paths, storage, chats = _make_test_chat_stack(Path(td))
            chat = chats.create_chat("Deletion failure")
            chat_id = str(chat["chat_id"])
            agents = velox.AgentStore(storage)
            llm = velox.LLMClient(storage)
            monitor = velox.LLMTaskMonitor(storage)
            context = velox.ContextAssembler(paths)
            tools = velox.ToolRegistry(storage)
            summaries = velox.SummaryService(storage, chats, llm, monitor)
            chat_runtime = velox.ChatRuntime(storage, chats, context, llm, tools, monitor)
            agent_runtime = velox.AgentRuntime(storage, agents, chats, context, llm, tools, monitor, chat_runtime)
            tools.bind_agent_runtime(agent_runtime)
            services = velox.Services(
                storage=storage,
                chats=chats,
                agents=agents,
                llm=llm,
                context=context,
                tools=tools,
                summaries=summaries,
                chat=chat_runtime,
                agent_runtime=agent_runtime,
                monitor=monitor,
            )

            def fail_agent_delete(_chat_id: str) -> list[str]:
                raise OSError("simulated agent deletion failure")

            agent_runtime.delete_agents_for_chat = fail_agent_delete  # type: ignore[method-assign]
            with self.assertRaisesRegex(OSError, "simulated agent deletion failure"):
                services.delete_chat(chat_id)
            self.assertTrue(paths.chat_json(chat_id).is_file())
            self.assertNotIn(chat_id, summaries._discarded_chat_ids)

    def test_deleting_chat_cannot_be_reversed_by_late_background_summary(self) -> None:
        class BlockingSummaryLLM:
            def __init__(self) -> None:
                self.started = asyncio.Event()
                self.release = asyncio.Event()

            async def chat_completions_once_full(self, request: LLMRequest) -> dict[str, Any]:
                return {"text": await self.chat_completions_once(request), "finish_reason": "stop"}

            async def chat_completions_once(self, _request: LLMRequest) -> str:
                self.started.set()
                await self.release.wait()
                return json.dumps({
                    "one_sentence_summary": "Late summary that must not be written.",
                    "bullet_summary_markdown": "- Late summary that must not be written.",
                })

        async def scenario(root: Path) -> None:
            paths, storage, chats = _make_test_chat_stack(root)
            chat = chats.create_chat("Delete during background summary")
            chat_id = str(chat["chat_id"])
            chats.append_turn(velox.APP_SCOPE_ID, chat_id, velox.make_turn(chat_id, "user", "Generate a delayed summary."))

            fake = BlockingSummaryLLM()
            monitor = velox.LLMTaskMonitor(storage)
            context = velox.ContextAssembler(paths)
            agents = velox.AgentStore(storage)
            tools = velox.ToolRegistry(storage)
            summaries = velox.SummaryService(storage, chats, fake, monitor)
            chat_runtime = velox.ChatRuntime(storage, chats, context, fake, tools, monitor)
            agent_runtime = velox.AgentRuntime(storage, agents, chats, context, fake, tools, monitor, chat_runtime)
            tools.bind_agent_runtime(agent_runtime)
            services = velox.Services(
                storage=storage,
                chats=chats,
                agents=agents,
                llm=fake,
                context=context,
                tools=tools,
                summaries=summaries,
                chat=chat_runtime,
                agent_runtime=agent_runtime,
                monitor=monitor,
            )

            refresh = asyncio.create_task(summaries.refresh_chat_summary(velox.APP_SCOPE_ID, chat_id))
            await asyncio.wait_for(fake.started.wait(), timeout=2.0)
            services.delete_chat(chat_id)
            fake.release.set()
            result = await asyncio.gather(refresh, return_exceptions=True)
            self.assertEqual(len(result), 1)
            self.assertIsInstance(result[0], FileNotFoundError)
            self.assertFalse(paths.chat_dir(chat_id).exists())
            self.assertFalse(paths.chat_summary_json(chat_id).exists())
            self.assertFalse(paths.chat_json(chat_id).exists())
            await agent_runtime.shutdown()

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

