    def test_terminal_runtime_is_owner_isolated_incremental_and_durable(self) -> None:
        class FakeStdin:
            def __init__(self, process: "FakeCmdProcess") -> None:
                self.process = process

            def write(self, data: Any) -> int:
                raw = data if isinstance(data, bytes) else str(data).encode("utf-8")
                self.process.inputs.append(bytes(raw))
                if self.process.output_fd is not None:
                    os.write(
                        self.process.output_fd,
                        b"\r\nPROCESS RECEIVED: " + raw.replace(b"\r", b"").replace(b"\n", b"")
                        + b"\r\nCOMMAND COMPLETE\r\n"
                        + self.process.prompt_token.encode("utf-8") + b">",
                    )
                return len(raw)

            def flush(self) -> None:
                return None

        class FakeCmdProcess:
            next_pid = 41000

            def __init__(self, argv: list[str], **_kwargs: Any) -> None:
                FakeCmdProcess.next_pid += 1
                self.pid = FakeCmdProcess.next_pid
                self.returncode: int | None = None
                self.inputs: list[bytes] = []
                prompt_arg = str(argv[-1])
                self.prompt_token = prompt_arg.removeprefix("prompt ").removesuffix("$P$G")
                read_fd, write_fd = os.pipe()
                self.output_fd: int | None = write_fd
                self.stdout = os.fdopen(read_fd, "rb", buffering=0)
                self.stdin = FakeStdin(self)
                os.write(write_fd, b"Microsoft Windows [Version test]\r\n" + self.prompt_token.encode("utf-8") + b">")

            def poll(self) -> int | None:
                return self.returncode

            def terminate(self) -> None:
                if self.returncode is None:
                    # Windows task-tree termination commonly reports a nonzero
                    # process exit code; terminal_end must still record Closed.
                    self.returncode = -15
                    if self.output_fd is not None:
                        os.close(self.output_fd)
                        self.output_fd = None

            def kill(self) -> None:
                self.terminate()

            def wait(self, timeout: float | None = None) -> int:
                if self.returncode is None:
                    raise subprocess.TimeoutExpired("fake-cmd", timeout or 0)
                return self.returncode

        with tempfile.TemporaryDirectory() as td:
            paths, storage, chats = _make_test_chat_stack(Path(td))
            chat_a = chats.create_chat("Terminal owner A")
            chat_b = chats.create_chat("Terminal owner B")
            agents = velox.AgentStore(storage)
            agent = agents.create_agent(chat_a["chat_id"], "Use a private terminal.", title="Terminal agent")
            runtime = velox.TerminalRuntime(
                storage,
                process_factory=lambda argv, **kwargs: FakeCmdProcess(list(argv), **kwargs),
                platform_name="win32",
            )
            marker = "__VELOX_READY_SPLIT_TEST__"
            self.assertEqual(runtime._prompt_prefix_hold(marker, marker), len(marker))
            self.assertEqual(runtime._prompt_prefix_hold("prefix" + marker[:9], marker), 9)
            chat_ctx = velox.ToolContext(velox.APP_SCOPE_ID, chat_id=chat_a["chat_id"])
            other_chat_ctx = velox.ToolContext(velox.APP_SCOPE_ID, chat_id=chat_b["chat_id"])
            agent_ctx = velox.ToolContext(velox.APP_SCOPE_ID, chat_id=chat_a["chat_id"], agent_id=agent["agent_id"])

            chat_terminal = runtime.start_owned(chat_ctx, {"title": "Build server"})
            chat_terminal_id = str(chat_terminal["terminal_id"])
            initial = runtime.read_owned(chat_ctx, chat_terminal_id, wait_seconds=1.0)
            self.assertIn("Microsoft Windows", initial["output"])
            self.assertTrue(initial["ready_for_input"])
            written = runtime.write_owned(chat_ctx, chat_terminal_id, "echo hello\r\n")
            self.assertEqual(written["chars_written"], len("echo hello\r\n"))
            output = runtime.read_owned(chat_ctx, chat_terminal_id, wait_seconds=1.0)
            self.assertIn("PROCESS RECEIVED: echo hello", output["output"])
            self.assertIn("COMMAND COMPLETE", output["output"])
            self.assertTrue(output["ready_for_input"])
            self.assertEqual(runtime.read_owned(chat_ctx, chat_terminal_id)["output"], "")
            # Incremental byte offsets must never split or skip multibyte UTF-8
            # output when the caller requests a very small character window.
            runtime._append_output(chat_terminal_id, "αβγ")
            first_unicode = runtime.read_owned(chat_ctx, chat_terminal_id, max_chars=1)
            second_unicode = runtime.read_owned(chat_ctx, chat_terminal_id, max_chars=2)
            self.assertEqual(first_unicode["output"], "α")
            self.assertEqual(second_unicode["output"], "βγ")
            self.assertEqual(len(runtime.list_owned(chat_ctx)), 1)
            self.assertEqual(runtime.list_owned(other_chat_ctx), [])
            with self.assertRaises((FileNotFoundError, PermissionError)):
                runtime.status_owned(other_chat_ctx, chat_terminal_id)
            with self.assertRaises(ValueError):
                runtime.status_owned(chat_ctx, "..\\..\\other")

            agent_terminal = runtime.start_owned(agent_ctx, {"title": "Agent tests", "command": "pytest"})
            agent_terminal_id = str(agent_terminal["terminal_id"])
            self.assertTrue(any(b"pytest" in item for item in runtime._live[agent_terminal_id].process.inputs))
            discovered = runtime.list_agent_terminals_for_chat(chat_a["chat_id"])
            self.assertEqual([row["terminal_id"] for row in discovered], [agent_terminal_id])
            self.assertEqual(runtime.list_agent_terminals_for_chat(chat_b["chat_id"]), [])
            read_only = runtime.read_agent_terminal_for_chat(
                chat_a["chat_id"], agent["agent_id"], agent_terminal_id, since_offset=0,
            )
            self.assertIn("Microsoft Windows", read_only["output"])
            with self.assertRaises(PermissionError):
                runtime.read_agent_terminal_for_chat(
                    chat_b["chat_id"], agent["agent_id"], agent_terminal_id,
                )

            runtime.end_owned(chat_ctx, chat_terminal_id, reason="Test complete.")
            runtime.end_owned(agent_ctx, agent_terminal_id, reason="Agent test complete.")
            self.assertEqual(runtime.status_owned(chat_ctx, chat_terminal_id)["status"], "closed")
            transcript, truncated = runtime.transcript_text("chat", chat_a["chat_id"], chat_terminal_id)
            self.assertFalse(truncated)
            self.assertIn("## Terminal input", transcript)
            self.assertIn("echo hello", transcript)
            self.assertIn("## Process output", transcript)
            self.assertTrue(paths.chat_terminal_dir(chat_a["chat_id"], chat_terminal_id).is_dir())
            self.assertTrue(paths.agent_terminal_dir(agent["agent_id"], agent_terminal_id).is_dir())
            event_kinds = [str(row.get("kind") or "") for row in runtime.transcript_events("chat", chat_a["chat_id"], chat_terminal_id)]
            input_index = event_kinds.index("input")
            self.assertIn("output", event_kinds[input_index + 1:])

            # One damaged historical record must not hide healthy sessions from
            # the owner list or repeatedly crash the terminal viewer.
            damaged_id = velox.uuid_v4()
            damaged_dir = paths.chat_terminal_dir(chat_a["chat_id"], damaged_id)
            damaged_dir.mkdir(parents=True)
            velox.atomic_write_json(damaged_dir / "terminal.json", {"schema": "damaged"})
            self.assertTrue(runtime.list_owned(chat_ctx))
            self.assertEqual(len(runtime._corrupt_record_warnings), 1)
            runtime.list_owned(chat_ctx)
            self.assertEqual(len(runtime._corrupt_record_warnings), 1)

            interrupted_id = velox.uuid_v4()
            interrupted_dir = paths.chat_terminal_dir(chat_a["chat_id"], interrupted_id)
            interrupted_dir.mkdir(parents=True)
            velox.atomic_write_text(interrupted_dir / "transcript.jsonl", "")
            velox.atomic_write_text(interrupted_dir / "output.txt", "")
            interrupted = runtime._new_record(
                terminal_id=interrupted_id,
                owner_type="chat",
                owner_id=chat_a["chat_id"],
                parent_chat_id=chat_a["chat_id"],
                title="Interrupted",
                working_directory=paths.chat_workspace_dir(chat_a["chat_id"]),
                prompt_token="__TEST_PROMPT__",
                pid=999,
                status="running",
            )
            runtime._save_record(interrupted)
            recovered = velox.TerminalRuntime(storage, platform_name="linux")
            self.assertEqual(recovered.status_owned(chat_ctx, interrupted_id)["status"], "interrupted")
            events = recovered.transcript_events("chat", chat_a["chat_id"], interrupted_id)
            self.assertTrue(any(row.get("kind") == "system" and "restarted" in str(row.get("text")) for row in events))

