    def test_substantive_answer_wins_over_inconsistent_tool_finish_reason(self) -> None:
        class InconsistentFinishStream:
            def __init__(self) -> None:
                self.calls = 0

            async def chat_completions_stream(self, _request: LLMRequest):
                self.calls += 1
                if self.calls > 1:
                    raise AssertionError("inconsistent finish_reason caused a destructive retry")
                yield velox.LLMChunk(text="The requested analysis is complete and no further tool is needed.")
                yield velox.LLMChunk(done=True, finish_reason="tool_calls")

        async def scenario(root: Path) -> None:
            paths, storage, chats, chat = self._chat(root)
            fake = InconsistentFinishStream()
            runtime = velox.ChatRuntime(
                storage,
                chats,
                velox.ContextAssembler(paths),
                fake,
                velox.ToolRegistry(storage),
            )
            user_text = "Summarize the supplied information."
            chats.append_turn(velox.APP_SCOPE_ID, chat["chat_id"], velox.make_turn(chat["chat_id"], "user", user_text))
            assistant = velox.make_turn(
                chat["chat_id"], "assistant", "", endpoint_profile_id="fast",
                endpoint_label="fast", status="streaming",
            )
            chats.append_turn(velox.APP_SCOPE_ID, chat["chat_id"], assistant, mark_stale=False)
            await runtime._run_assistant_loop(
                velox.APP_SCOPE_ID, chat["chat_id"], assistant["turn_id"], "fast",
                user_text, "Finish-reason mismatch regression",
            )
            saved = next(
                turn for turn in chats.load_turns(velox.APP_SCOPE_ID, chat["chat_id"])
                if turn.get("turn_id") == assistant["turn_id"]
            )
            self.assertEqual(fake.calls, 1)
            self.assertEqual(saved["status"], "complete")
            self.assertIn("analysis is complete", saved["text"])
            log_text = "\n".join(str(row.get("log msg") or "") for row in velox.iter_jsonl(paths.log_jsonl_path))
            self.assertIn("chat.model_termination_mismatch_ignored", log_text)
            runtime.cancel_all()

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

