    def test_task_monitor_and_agent_store_keep_first_terminal_state(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            paths, storage, chats, chat = self._chat(Path(td))
            monitor = velox.LLMTaskMonitor(storage)
            request_id = monitor.start(velox.APP_SCOPE_ID, "Race test", task_kind="chat")
            callback_count = 0

            def cancelled() -> None:
                nonlocal callback_count
                callback_count += 1

            monitor.register_cancel_callback(request_id, cancelled)
            self.assertTrue(monitor.cancel_task(request_id))
            monitor.complete(request_id)
            monitor.fail(request_id, "late failure")
            record = next(row for row in monitor.list_records() if row["task_id"] == request_id)
            self.assertEqual(record["state"], "cancelled")
            self.assertEqual(callback_count, 1)

            agents = velox.AgentStore(storage)
            agent = agents.create_agent(chat["chat_id"], "Finish once.", title="Terminal race")
            agent_id = str(agent["agent_id"])
            completed = agents.update_agent(agent_id, {
                "status": "succeeded",
                "final_message": "authoritative result",
            })
            self.assertEqual(completed["status"], "succeeded")
            late = agents.update_agent(agent_id, {
                "status": "running",
                "final_message": "late worker overwrite",
            })
            self.assertEqual(late["status"], "succeeded")
            self.assertEqual(late["final_message"], "authoritative result")
            log_text = "\n".join(str(row.get("log msg") or "") for row in velox.iter_jsonl(paths.log_jsonl_path))
            self.assertIn("agent.stale_transition_ignored", log_text)

