    def test_agent_empty_completion_fails_and_reports_to_source_chat(self) -> None:
        class EmptyAgentLLM:
            def __init__(self) -> None:
                self.calls = 0

            async def chat_completions_once_full(self, request: LLMRequest) -> dict[str, Any]:
                self.calls += 1
                if self.calls > 1:
                    raise AssertionError("Agent Tasktime must not retry empty endpoint output")
                return {
                    "text": "",
                    "usage": {"prompt_tokens": 100, "completion_tokens": 0},
                    "model": "empty-test", "endpoint": request.endpoint_profile_id,
                    "finish_reason": "stop",
                    "raw": {"choices": [{"finish_reason": "stop", "message": {"content": ""}}]},
                }

        class ReportSink:
            def __init__(self) -> None:
                self.reports: list[tuple[str, str]] = []

            def enqueue_agent_report(self, agent: dict[str, Any], report_kind: str = "terminal") -> None:
                self.reports.append((str(agent.get("agent_id") or ""), report_kind))

        async def scenario(root: Path) -> None:
            fake = EmptyAgentLLM()
            paths, storage, chats, chat = self._chat(root)
            agents = velox.AgentStore(storage)
            tools = velox.ToolRegistry(storage)
            sink = ReportSink()
            runtime = velox.AgentRuntime(
                storage, agents, chats, velox.ContextAssembler(paths), fake, tools,
                chat_runtime=sink,  # type: ignore[arg-type]
            )
            tools.bind_agent_runtime(runtime)
            started = await runtime.start_from_tool(
                velox.ToolContext(velox.APP_SCOPE_ID, chat_id=chat["chat_id"]),
                {"task": "Attempt the task and report endpoint failure."},
            )
            agent_id = str(started["agent_id"])
            final = await asyncio.wait_for(runtime.wait_for_agent(agent_id), timeout=3.0)
            self.assertEqual(fake.calls, 1)
            self.assertEqual(final["status"], "failed")
            self.assertIn("no usable agent content", final["failure_message"].lower())
            self.assertEqual(sink.reports, [(agent_id, "terminal")])
            events = agents.load_transcript(agent_id)
            self.assertTrue(any(event.get("kind") == "failed" for event in events))
            self.assertFalse(any(event.get("kind") == "llm_continuation_recovery" for event in events))
            await runtime.shutdown()

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

