    def test_streaming_autoscroll_reenable_disable_and_cooldown(self) -> None:
        cooldown = velox.CHAT_AUTOSCROLL_TOGGLE_COOLDOWN_SECONDS
        self.assertEqual(cooldown, 1.0)
        # Passive layout growth at the bottom must never re-enable follow mode.
        self.assertFalse(velox.chat_autoscroll_state_after_manual_input(
            False,
            at_bottom=True,
            manual_scroll_started=False,
            manual_scroll_active=False,
            seconds_since_change=cooldown + 0.01,
        ))
        # A direct downward wheel/scrollbar gesture that reaches the bottom does.
        self.assertTrue(velox.chat_autoscroll_state_after_manual_input(
            False,
            at_bottom=True,
            manual_scroll_started=True,
            manual_scroll_active=True,
            seconds_since_change=0.0,
            manual_scroll_toward_bottom=True,
        ))
        # The cooldown does not negate an already enabled state without an
        # unambiguous upward/away gesture.
        self.assertTrue(velox.chat_autoscroll_state_after_manual_input(
            True,
            at_bottom=True,
            manual_scroll_started=True,
            manual_scroll_active=True,
            seconds_since_change=cooldown - 0.01,
        ))
        # Moving away from the bottom disables following immediately.
        self.assertFalse(velox.chat_autoscroll_state_after_manual_input(
            True,
            at_bottom=False,
            manual_scroll_started=True,
            manual_scroll_active=True,
            seconds_since_change=0.0,
        ))
        # Use the immutable production source rather than inspect.getsource on
        # this very large method. Some isolated shard interpreters populate
        # linecache after the production probe and can otherwise return a
        # neighboring one-line method even though the runtime method is intact.
        thread_source = application_source()
        self.assertIn("chat_autoscroll_state_after_manual_input", thread_source)
        self.assertIn("CHAT_AUTOSCROLL_BOTTOM_TOLERANCE_PX", thread_source)
        self.assertIn("chat_autoscroll_changed_at", thread_source)
        self.assertIn("manual_scroll_toward_bottom", thread_source)
        self.assertNotIn("chat_autoscroll_reenable_armed", thread_source)
        self.assertIn("if autoscroll_enabled and not manual_scroll_active", thread_source)

