    def test_model_type_presets_fill_editor_but_allow_overrides(self) -> None:
        draft = velox.new_endpoint_profile("Editable")
        draft.update({
            "base_url": "https://example.invalid/v1/chat/completions",
            "api_key": "secret",
            "timeout_seconds": 123,
            "user_agent_mode": "custom",
            "custom_user_agent": "Endpoint-Test/1.0",
            "_ui_timeout_minutes": "2.05",
            "_ui_stop_sequences": "[]",
        })
        velox.Panels._apply_endpoint_model_type_to_editor_draft(draft, velox.ENDPOINT_MODEL_TYPE_KIMI_K3)
        self.assertEqual(draft["base_url"], "https://example.invalid/v1/chat/completions")
        self.assertEqual(draft["api_key"], "secret")
        self.assertEqual(draft["model"], "moonshotai/kimi-k3")
        self.assertEqual(draft["reasoning_effort"], "max")
        self.assertEqual(draft["temperature"], "")
        self.assertTrue(draft["preserve_thinking"])

        # Presets are initial values, not hidden runtime rules. The user can edit
        # a supported optional value and it survives normalization.
        draft["temperature"] = "0.72"
        panel = velox.Panels.__new__(velox.Panels)
        profile = panel._endpoint_profile_from_editor_draft(draft)
        self.assertEqual(profile["temperature"], 0.72)
        self.assertEqual(profile["timeout_seconds"], 123)
        self.assertEqual(profile["custom_user_agent"], "Endpoint-Test/1.0")

        qwen = copy.deepcopy(draft)
        velox.Panels._apply_endpoint_model_type_to_editor_draft(qwen, velox.ENDPOINT_MODEL_TYPE_QWEN_3_6)
        self.assertEqual(qwen["temperature"], "1.0")
        self.assertEqual(qwen["top_p"], "0.95")
        self.assertEqual(qwen["top_k"], "20")
        self.assertEqual(qwen["min_p"], "0.0")

    def test_powershell_terminal_has_persistent_text_io(self) -> None:
        class FakeStdin:
            def __init__(self, process: "FakePowerShellProcess") -> None:
                self.process = process

            def write(self, data: Any) -> int:
                raw = data if isinstance(data, bytes) else str(data).encode("utf-8")
                self.process.inputs.append(bytes(raw))
                if self.process.output_fd is not None:
                    command = raw.replace(b"\r", b"").replace(b"\n", b"")
                    os.write(
                        self.process.output_fd,
                        b"\r\nPOWERSHELL RECEIVED: " + command + b"\r\n"
                        + self.process.prompt_token.encode("utf-8") + b">",
                    )
                return len(raw)

            def flush(self) -> None:
                return None

        class FakePowerShellProcess:
            next_pid = 52000
            instances: list["FakePowerShellProcess"] = []

            def __init__(self, argv: list[str], **_kwargs: Any) -> None:
                FakePowerShellProcess.next_pid += 1
                self.pid = FakePowerShellProcess.next_pid
                self.argv = list(argv)
                self.returncode: int | None = None
                self.inputs: list[bytes] = []
                match = re.search(r"'([^']+)'\s*\+", str(argv[-1]))
                if not match:
                    raise AssertionError(f"PowerShell prompt token missing from argv: {argv!r}")
                self.prompt_token = match.group(1)
                read_fd, write_fd = os.pipe()
                self.output_fd: int | None = write_fd
                self.stdout = os.fdopen(read_fd, "rb", buffering=0)
                self.stdin = FakeStdin(self)
                os.write(write_fd, b"Windows PowerShell test\r\n" + self.prompt_token.encode("utf-8") + b">")
                FakePowerShellProcess.instances.append(self)

            def poll(self) -> int | None:
                return self.returncode

            def terminate(self) -> None:
                if self.returncode is None:
                    self.returncode = -15
                    if self.output_fd is not None:
                        os.close(self.output_fd)
                        self.output_fd = None

            def kill(self) -> None:
                self.terminate()

            def wait(self, timeout: float | None = None) -> int:
                if self.returncode is None:
                    raise subprocess.TimeoutExpired("fake-powershell", timeout or 0)
                return self.returncode

        with tempfile.TemporaryDirectory() as td:
            _paths, storage, chats = _make_test_chat_stack(Path(td))
            chat = chats.create_chat("PowerShell terminal")
            runtime = velox.TerminalRuntime(
                storage,
                process_factory=lambda argv, **kwargs: FakePowerShellProcess(list(argv), **kwargs),
                platform_name="win32",
            )
            ctx = velox.ToolContext(velox.APP_SCOPE_ID, chat_id=chat["chat_id"])
            started = runtime.start_owned(ctx, {
                "shell": "powershell",
                "title": "Build shell",
                "command": "Write-Output hello",
            })
            terminal_id = str(started["terminal_id"])
            self.assertEqual(started["shell"], velox.TERMINAL_SHELL_POWERSHELL)
            process = FakePowerShellProcess.instances[-1]
            self.assertEqual(process.argv[:5], [
                "powershell.exe", "-NoLogo", "-NoProfile", "-NoExit", "-ExecutionPolicy",
            ])
            self.assertIn("Bypass", process.argv)
            first = runtime.read_owned(ctx, terminal_id, wait_seconds=1.0)
            self.assertIn("Windows PowerShell test", first["output"])
            # The startup command goes through the same persistent stdin pipe.
            second = runtime.read_owned(ctx, terminal_id, wait_seconds=1.0)
            combined = first["output"] + second["output"]
            self.assertIn("POWERSHELL RECEIVED: Write-Output hello", combined)
            runtime.write_owned(ctx, terminal_id, "Get-Location\r\n")
            output = runtime.read_owned(ctx, terminal_id, wait_seconds=1.0)
            self.assertIn("POWERSHELL RECEIVED: Get-Location", output["output"])
            runtime.end_owned(ctx, terminal_id, reason="PowerShell test complete.")
            self.assertEqual(runtime.status_owned(ctx, terminal_id)["status"], "closed")

    def test_conpty_terminal_control_reconnect_resize_redaction_and_pwsh(self) -> None:
        class FakeTerminalStdin:
            def __init__(self, process: "FakeConPTYProcess") -> None:
                self.process = process

            def write(self, data: Any) -> int:
                raw = data if isinstance(data, bytes) else str(data).encode("utf-8")
                self.process.inputs.append(bytes(raw))
                if self.process.output_fd is not None and b"super-secret" not in raw:
                    os.write(self.process.output_fd, b"\r\nECHO: " + raw + b"\r\n")
                return len(raw)

            def flush(self) -> None:
                return None

            def close(self) -> None:
                return None

        class FakeConPTYProcess:
            next_pid = 61000
            instances: list["FakeConPTYProcess"] = []

            def __init__(self, argv: list[str], **kwargs: Any) -> None:
                FakeConPTYProcess.next_pid += 1
                self.pid = FakeConPTYProcess.next_pid
                self.argv = list(argv)
                self.returncode: int | None = None
                self.inputs: list[bytes] = []
                self.resize_calls: list[tuple[int, int]] = []
                self.columns = int(kwargs.get("columns") or velox.TERMINAL_DEFAULT_COLUMNS)
                self.rows = int(kwargs.get("rows") or velox.TERMINAL_DEFAULT_ROWS)
                command = str(argv[-1])
                if str(argv[0]).lower().endswith("cmd.exe"):
                    self.prompt_token = command.removeprefix("prompt ").removesuffix("$P$G")
                else:
                    match = re.search(r"'([^']+)'\s*\+", command)
                    if not match:
                        raise AssertionError(f"PowerShell prompt token missing from argv: {argv!r}")
                    self.prompt_token = match.group(1)
                read_fd, write_fd = os.pipe()
                self.output_fd: int | None = write_fd
                self.stdout = os.fdopen(read_fd, "rb", buffering=0)
                self.stdin = FakeTerminalStdin(self)
                os.write(
                    write_fd,
                    b"\x1b[2JInteractive terminal ready\r\n"
                    + self.prompt_token.encode("utf-8") + b"C:/work> ",
                )
                FakeConPTYProcess.instances.append(self)

            def poll(self) -> int | None:
                return self.returncode

            def resize(self, columns: int, rows: int) -> None:
                self.columns = int(columns)
                self.rows = int(rows)
                self.resize_calls.append((self.columns, self.rows))

            def close_pseudoconsole(self) -> None:
                self.terminate()

            def terminate(self) -> None:
                if self.returncode is None:
                    self.returncode = 0
                    if self.output_fd is not None:
                        os.close(self.output_fd)
                        self.output_fd = None

            def kill(self) -> None:
                self.terminate()

            def wait(self, timeout: float | None = None) -> int:
                if self.returncode is None:
                    raise subprocess.TimeoutExpired("fake-conpty", timeout or 0)
                return self.returncode

            def close(self) -> None:
                self.terminate()

        with tempfile.TemporaryDirectory() as td:
            paths, storage, chats = _make_test_chat_stack(Path(td))
            chat = chats.create_chat("Interactive terminal")
            runtime = velox.TerminalRuntime(
                storage,
                process_factory=lambda argv, **kwargs: FakeConPTYProcess(list(argv), **kwargs),
                platform_name="win32",
            )
            ctx = velox.ToolContext(velox.APP_SCOPE_ID, chat_id=chat["chat_id"])
            started = runtime.start_owned(ctx, {
                "shell": "cmd", "columns": 132, "rows": 41, "title": "SSH session",
            })
            terminal_id = str(started["terminal_id"])
            self.assertEqual(started["backend"], velox.TERMINAL_BACKEND_CONPTY)
            self.assertEqual((started["columns"], started["rows"]), (132, 41))
            self.assertTrue(started["attached"])
            self.assertTrue(started["can_reconnect"])

            runtime.read_owned(
                ctx, terminal_id, since_offset=0, wait_seconds=1.0, include_screen=True,
            )
            connected = runtime.reconnect_owned(ctx, terminal_id, since_offset=0)
            self.assertIn("Interactive terminal ready", connected["output"])
            self.assertIn("Interactive terminal ready", connected["screen"])
            self.assertNotIn("\x1b", connected["output"])
            self.assertNotIn("\r", connected["output"])

            process = FakeConPTYProcess.instances[-1]
            runtime.send_key_owned(ctx, terminal_id, "up")
            self.assertEqual(process.inputs[-1], b"\x1b[A")
            runtime.interrupt_owned(ctx, terminal_id)
            self.assertEqual(process.inputs[-1], b"\x03")
            runtime.write_owned(
                ctx, terminal_id, "super-secret\r", sensitive=True, source="user",
            )
            runtime.resize_owned(ctx, terminal_id, 160, 48)
            self.assertEqual(process.resize_calls[-1], (160, 48))
            self.assertEqual(
                (runtime.status_owned(ctx, terminal_id)["columns"],
                 runtime.status_owned(ctx, terminal_id)["rows"]),
                (160, 48),
            )
            transcript, _truncated = runtime.transcript_text(
                "chat", chat["chat_id"], terminal_id,
            )
            self.assertIn("[Sensitive terminal input redacted]", transcript)
            self.assertNotIn("super-secret", transcript)
            raw_path = paths.chat_terminal_dir(chat["chat_id"], terminal_id) / "raw_output.bin"
            self.assertIn(b"\x1b[2J", raw_path.read_bytes())
            runtime.end_owned(ctx, terminal_id, reason="Interactive test complete.")

            with mock.patch.object(
                shutil, "which",
                side_effect=lambda name: "C:/Program Files/PowerShell/7/pwsh.exe"
                if name in {"pwsh.exe", "pwsh"} else None,
            ):
                pwsh = runtime.start_owned(ctx, {"shell": "pwsh", "title": "PS7"})
            pwsh_id = str(pwsh["terminal_id"])
            pwsh_process = FakeConPTYProcess.instances[-1]
            self.assertEqual(
                pwsh_process.argv[0], "C:/Program Files/PowerShell/7/pwsh.exe",
            )
            self.assertIn("-NoExit", pwsh_process.argv)
            runtime.end_owned(ctx, pwsh_id, reason="PowerShell 7 test complete.")

        native_source = inspect.getsource(velox._WindowsConPTYProcess)
        for required in (
            "CreatePseudoConsole", "PROC_THREAD_ATTRIBUTE_PSEUDOCONSOLE",
            "EXTENDED_STARTUPINFO_PRESENT", "ResizePseudoConsole", "ClosePseudoConsole",
        ):
            self.assertIn(required, native_source)
        runtime_source = inspect.getsource(velox.TerminalRuntime)
        self.assertIn("return self.conpty_factory", runtime_source)
        self.assertNotIn("subprocess.Popen(", runtime_source)
        terminate_source = inspect.getsource(velox.TerminalRuntime._terminate_process_tree)
        self.assertIn('["taskkill", "/PID", str(pid), "/T", "/F"]', terminate_source)
        self.assertNotIn("self.process_factory is not None", terminate_source)
        screen = velox._TerminalScreen(20, 4)
        plain, response = screen.feed("hello\r\nworld\x1b[6n")
        self.assertIn("hello", plain)
        self.assertTrue(response.startswith(b"\x1b["))
        self.assertIn("world", screen.snapshot())
        self.assertEqual(screen.key_sequence("ctrl_c"), b"\x03")

    def test_terminal_prompt_tool_has_only_terminal_id_and_text(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            _paths, storage, chats = _make_test_chat_stack(Path(td))
            chat = chats.create_chat("Simple terminal prompt tool")
            registry = velox.ToolRegistry(storage)

            async def fake_respond(_ctx: ToolContext, args: dict[str, Any]) -> dict[str, Any]:
                self.assertEqual(args, {"terminal_id": terminal_id, "text": "yes"})
                return {"status": "sent"}

            terminal_id = velox.uuid_v4()
            registry.tools["terminal_respond"].handler = fake_respond
            call = {
                "name": "terminal_respond",
                "arguments": {"terminal_id": terminal_id, "text": "yes"},
            }
            result = asyncio.run(registry.execute_tool_call(velox.APP_SCOPE_ID, call, chat_id=chat["chat_id"]))
            self.assertTrue(result["ok"])
            self.assertEqual(result["input"], {"terminal_id": terminal_id, "text": "yes"})
            self.assertEqual(
                list(registry.tools["terminal_respond"].parameters["properties"]),
                ["terminal_id", "text"],
            )
            schemas = registry.build_openai_chat_completion_tools(
                velox.APP_SCOPE_ID, chat["chat_id"], excluded_names=set(),
            )
            terminal_schema = next(
                row["function"] for row in schemas
                if row.get("function", {}).get("name") == "terminal_respond"
            )
            self.assertEqual(
                list(terminal_schema["parameters"]["properties"]),
                ["terminal_id", "text"],
            )
            converted = registry.convert_openai_tool_call(
                {
                    "id": "terminal_respond_test",
                    "type": "function",
                    "function": {
                        "name": "terminal_respond",
                        "arguments": json.dumps(call["arguments"]),
                    },
                },
                allowed_names={"terminal_respond"},
            )
            self.assertEqual(converted["arguments"], call["arguments"])
            self.assertNotIn("sensitive", converted["arguments"])
            self.assertNotIn("press_enter", converted["arguments"])

