    def test_simplified_web_tools_fetch_visible_download_and_label_links(self) -> None:
        async def scenario(root: Path) -> None:
            paths, storage, _chats, chat = self._chat(root)
            chat_id = str(chat["chat_id"])
            page = (
                "<!doctype html><html><head><title>Velox Test</title></head>"
                "<body><h1>Readable heading</h1><p>Human readable body.</p>"
                "<a href='/next?x=1'>Next page</a></body></html>"
            ).encode("utf-8")

            class Handler(http.server.BaseHTTPRequestHandler):
                def do_GET(self) -> None:  # noqa: N802 - stdlib callback name
                    self.send_response(200)
                    self.send_header("Content-Type", "text/html; charset=utf-8")
                    self.send_header("Content-Length", str(len(page)))
                    self.end_headers()
                    self.wfile.write(page)

                def log_message(self, _format: str, *_args: Any) -> None:
                    return

            server = http.server.ThreadingHTTPServer(("127.0.0.1", 0), Handler)
            thread = threading.Thread(target=server.serve_forever, daemon=True)
            thread.start()
            try:
                url = f"http://127.0.0.1:{server.server_port}/index.html"
                web = velox.WebTools(storage)
                ctx = velox.ToolContext(velox.APP_SCOPE_ID, chat_id=chat_id)
                fetched = await web.fetch(ctx, {"url": url})
                self.assertEqual(fetched["content"], page.decode("utf-8"))
                visible = await web.fetch_visible_content(ctx, {"url": url})
                self.assertIn("Readable heading", visible["text"])
                self.assertIn("Human readable body.", visible["text"])
                self.assertNotIn("<h1>", visible["text"])
                links = await web.page_links(ctx, {"url": url})
                self.assertEqual(links["count"], 1)
                self.assertEqual(links["links"][0]["description"], "Next page")
                self.assertEqual(
                    links["text"],
                    f"http://127.0.0.1:{server.server_port}/next?x=1 Next page",
                )
                destination = paths.chat_workspace_dir(chat_id) / "downloaded.html"
                downloaded = await web.download_to_path(ctx, {
                    "url": url,
                    "filepath": str(destination).replace("\\", "/"),
                })
                self.assertEqual(destination.read_bytes(), page)
                self.assertEqual(downloaded["path"], str(destination.resolve()))
            finally:
                server.shutdown()
                server.server_close()
                thread.join(timeout=5.0)

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

