    def test_chat_turn_terminal_state_is_monotonic_against_stale_stream_writes(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            _paths, _storage, chats, chat = self._chat(Path(td))
            turn = velox.make_turn(
                chat["chat_id"], "assistant", "partial", status="streaming",
                endpoint_profile_id="fast", endpoint_label="fast",
            )
            chats.append_turn(velox.APP_SCOPE_ID, chat["chat_id"], turn, mark_stale=False)
            self.assertTrue(chats.update_turn(
                velox.APP_SCOPE_ID, chat["chat_id"], turn["turn_id"],
                {"text": "final answer", "status": "complete"},
            ))
            self.assertFalse(chats.update_turn(
                velox.APP_SCOPE_ID, chat["chat_id"], turn["turn_id"],
                {"text": "late partial", "status": "streaming"},
            ))
            loaded = next(
                row for row in chats.load_turns(velox.APP_SCOPE_ID, chat["chat_id"])
                if row["turn_id"] == turn["turn_id"]
            )
            self.assertEqual(loaded["status"], "complete")
            self.assertEqual(loaded["text"], "final answer")

            cancelled = velox.make_turn(
                chat["chat_id"], "assistant", "working", status="streaming",
                endpoint_profile_id="fast", endpoint_label="fast",
            )
            chats.append_turn(velox.APP_SCOPE_ID, chat["chat_id"], cancelled, mark_stale=False)
            chats.update_turn(
                velox.APP_SCOPE_ID, chat["chat_id"], cancelled["turn_id"],
                {"text": "stopped", "status": "cancelled"},
            )
            self.assertFalse(chats.update_turn(
                velox.APP_SCOPE_ID, chat["chat_id"], cancelled["turn_id"],
                {"text": "late completion", "status": "complete"},
            ))
            loaded_cancelled = next(
                row for row in chats.load_turns(velox.APP_SCOPE_ID, chat["chat_id"])
                if row["turn_id"] == cancelled["turn_id"]
            )
            self.assertEqual(loaded_cancelled["status"], "cancelled")
            self.assertEqual(loaded_cancelled["text"], "stopped")

    def test_task_monitor_first_terminal_transition_wins(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            _paths, storage, _chats = _make_test_chat_stack(Path(td))
            monitor = velox.LLMTaskMonitor(storage)
            cancelled_id = monitor.start(velox.APP_SCOPE_ID, "cancel race")
            monitor.register_cancel_callback(cancelled_id, lambda: True)
            self.assertTrue(monitor.cancel_task(cancelled_id))
            monitor.complete(cancelled_id)
            monitor.fail(cancelled_id, "late failure")
            cancelled = next(
                row for row in monitor.list_records() if row["task_id"] == cancelled_id
            )
            self.assertEqual(cancelled["state"], "cancelled")

            completed_id = monitor.start(velox.APP_SCOPE_ID, "complete race")
            monitor.complete(completed_id)
            self.assertFalse(monitor.cancel_task(completed_id))
            monitor.cancel(completed_id)
            completed = next(
                row for row in monitor.list_records() if row["task_id"] == completed_id
            )
            self.assertEqual(completed["state"], "completed")

    def test_agent_terminal_state_cannot_be_reopened_by_stale_worker(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            _paths, storage, _chats, chat = self._chat(Path(td))
            agents = velox.AgentStore(storage)
            agent = agents.create_agent(chat["chat_id"], "Do one task.")
            cancelled = agents.update_agent(agent["agent_id"], {
                "status": "cancelled", "progress_message": "Cancelled by user",
            })
            stale = agents.update_agent(agent["agent_id"], {
                "status": "running", "progress_message": "Stale worker resumed",
            })
            self.assertEqual(stale["status"], "cancelled")
            self.assertEqual(stale["progress_message"], "Cancelled by user")
            reported = agents.update_agent(agent["agent_id"], {
                "terminal_reported_at": velox.now_iso(),
            })
            self.assertEqual(reported["status"], "cancelled")
            self.assertTrue(reported["terminal_reported_at"])
            self.assertEqual(cancelled["completed_at"], stale["completed_at"])

    def test_streaming_final_message_snapshot_does_not_duplicate_output(self) -> None:
        async def scenario(root: Path) -> None:
            _paths, storage, _chats = _make_test_chat_stack(root)
            client = velox.LLMClient(storage)
            events = b"".join([
                b'data: {"choices":[{"delta":{"reasoning_content":"Think once."}}]}\n\n',
                b'data: {"choices":[{"delta":{"content":"Final answer."}}]}\n\n',
                b'data: {"choices":[{"delta":{},"message":{"reasoning_content":"Think once.","content":"Final answer."},"finish_reason":"stop"}],"usage":{"prompt_tokens":10,"completion_tokens":5}}\n\n',
                b'data: [DONE]\n\n',
            ])

            class FakeResponse:
                status = 200
                headers: dict[str, str] = {}

                def __init__(self, payload: bytes) -> None:
                    import io
                    self._stream = io.BytesIO(payload)

                def __enter__(self) -> "FakeResponse":
                    return self

                def __exit__(self, *_args: Any) -> None:
                    return None

                def readline(self, limit: int = -1) -> bytes:
                    return self._stream.readline(limit)

                def getcode(self) -> int:
                    return 200

                def geturl(self) -> str:
                    return "http://local.test/v1/chat/completions"

            chunks: list[LLMChunk] = []
            with mock.patch.object(
                urllib.request, "urlopen", return_value=FakeResponse(events),
            ):
                async for chunk in client.chat_completions_stream(velox.LLMRequest(
                    scope_id=velox.APP_SCOPE_ID,
                    endpoint_profile_id=velox.DEFAULT_ENDPOINT_PROFILE_ID,
                    messages=[{"role": "user", "content": "test"}],
                    stream=True,
                )):
                    chunks.append(chunk)
            display = "".join(chunk.text for chunk in chunks)
            self.assertEqual(display, "<think>\nThink once.\n</think>\nFinal answer.")
            self.assertEqual(display.count("Think once."), 1)
            self.assertEqual(display.count("Final answer."), 1)
            self.assertEqual(chunks[-1].finish_reason, "stop")

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_compaction_does_not_duplicate_reasoning_metadata_and_display_text(self) -> None:
        async def scenario(root: Path) -> None:
            class CompactionLLM:
                async def chat_completions_stream(self, _request: LLMRequest):
                    yield velox.LLMChunk(text="<think>\n")
                    yield velox.LLMChunk(
                        text="Reason exactly once.",
                        reasoning_text="Reason exactly once.",
                    )
                    yield velox.LLMChunk(text="\n</think>\n")
                    yield velox.LLMChunk(text=(
                        "- Preserve the current endpoint, exact paths, latest constraints, completed tool results, "
                        "remaining implementation work, validation requirements, and the newest execution boundary. "
                        "Continue from the preserved state without repeating completed work or inventing evidence."
                    ))
                    yield velox.LLMChunk(done=True, finish_reason="stop")

            paths, storage, chats, chat = self._chat(root)
            runtime = velox.ChatRuntime(
                storage, chats, velox.ContextAssembler(paths), CompactionLLM(), velox.ToolRegistry(storage),
            )
            for index in range(8):
                chats.append_turn(
                    velox.APP_SCOPE_ID, chat["chat_id"],
                    velox.make_turn(chat["chat_id"], "user", f"Old user {index}: " + "U" * 400),
                )
                chats.append_turn(
                    velox.APP_SCOPE_ID, chat["chat_id"],
                    velox.make_turn(chat["chat_id"], "assistant", f"Old assistant {index}: " + "A" * 400),
                )
            placeholder = velox.make_turn(
                chat["chat_id"], "assistant", "", endpoint_profile_id="fast",
                endpoint_label="fast", status="streaming",
            )
            chats.append_turn(velox.APP_SCOPE_ID, chat["chat_id"], placeholder, mark_stale=False)
            messages = runtime._build_messages(velox.APP_SCOPE_ID, chat["chat_id"], endpoint_profile_id=velox.DEFAULT_ENDPOINT_PROFILE_ID)
            _compacted, _next_id, did_compact = await runtime._maybe_compact_chat_context(
                velox.APP_SCOPE_ID, chat["chat_id"], "fast", messages,
                placeholder["turn_id"], force=True,
            )
            self.assertTrue(did_compact)
            card = next(
                row for row in chats.load_turns(velox.APP_SCOPE_ID, chat["chat_id"])
                if row["turn_id"] == placeholder["turn_id"]
            )
            self.assertEqual(card["role"], "compaction")
            self.assertNotIn("Reason exactly once.", card["compaction_summary"])
            self.assertEqual(card["compaction_details"].count("Reason exactly once."), 1)

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_chat_task_cleanup_does_not_remove_a_newer_owner(self) -> None:
        async def scenario() -> None:
            runtime = object.__new__(velox.ChatRuntime)
            runtime.running = {}
            old = asyncio.create_task(asyncio.sleep(0))
            await old
            newer = asyncio.create_task(asyncio.sleep(0.01))
            runtime.running["chat"] = newer
            runtime._chat_task_done("chat", old)
            self.assertIs(runtime.running.get("chat"), newer)
            await newer
            runtime._chat_task_done("chat", newer)
            self.assertNotIn("chat", runtime.running)

        asyncio.run(scenario())

