    def test_calendar_app_state_date_navigation_persists_without_backlog_pin(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            _paths, storage, _chats, _calendar, panel, _services = self._panel_stack(root)
            self.assertEqual(panel.state.calendar_selected_date, "2026-07-30")
            panel._calendar_shift_selected_date(1)
            self.assertEqual(panel.state.calendar_selected_date, "2026-07-31")
            panel._calendar_shift_selected_date(-2)
            self.assertEqual(panel.state.calendar_selected_date, "2026-07-29")
            panel._calendar_set_selected_date("2026-08-01")
            self.assertEqual(panel.state.calendar_selected_date, "2026-08-01")
            self.assertEqual(velox.calendar_shift_iso_date("2026-08-01", 1), "2026-08-02")

            app_state = storage.load_app_state()
            app_state["calendar_selected_date"] = panel.state.calendar_selected_date
            self.assertNotIn("calendar_backlog_pinned", app_state)
            app_state["active_panel"] = "calendar"
            storage.write_app_state(app_state)
            velox.DATA_ROOTS.clear_for_tests()
            reloaded = velox.Storage(velox.AppPaths(root))
            reloaded.ensure_first_run_files()
            saved = reloaded.load_app_state()
            self.assertEqual(saved["calendar_selected_date"], "2026-08-01")
            self.assertNotIn("calendar_backlog_pinned", saved)
            self.assertEqual(saved["active_panel"], "calendar")
            with self.assertRaisesRegex(ValueError, "unsupported app state fields"):
                storage.write_app_state({**saved, "calendar_backlog_pinned": True})

    def test_item_editor_create_edit_schedule_and_backlog_round_trip(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            _paths, _storage, _chats, calendar, panel, _services = self._panel_stack(root)
            event = calendar.upsert_event(self._event_payload("editor-event"))
            future_payload = self._event_payload("future-editor-event", title="Future linked meeting")
            future_payload["start"] = "2026-08-15T13:00:00-04:00"
            future_payload["end"] = "2026-08-15T14:00:00-04:00"
            future_event = calendar.upsert_event(future_payload)
            _options, _display_to_id, id_to_display = panel._calendar_event_option_map(
                day_value="2026-07-30",
            )
            self.assertIn(future_event["event_id"], id_to_display)
            self.assertIn("2026-08-15 13:00", id_to_display[future_event["event_id"]])
            panel._open_item_editor(linked_event_id=event["event_id"], title="Prepare review")
            modal = panel.state.modal
            self.assertIsInstance(modal, dict)
            draft = modal["draft"]
            draft.update({
                "description": "Create the review draft.",
                "status": "Agent WIP",
                "priority": "P1",
                "backlog": False,
                "scheduled_date": "2026-07-30",
                "scheduled_start_time": "09:15",
                "duration_minutes": "75",
                "context_links_text": "slack | Source thread | https://slack.example/thread | key excerpt | thread-7",
                "attachments_text": str(root / "draft.docx") + "\n" + str(root / "notes.txt"),
            })
            saved = panel._save_item_editor(modal)
            self.assertEqual(saved["title"], "Prepare review")
            self.assertEqual(saved["status"], "Agent WIP")
            self.assertEqual(saved["priority"], "P1")
            self.assertEqual(saved["scheduled_date"], "2026-07-30")
            self.assertEqual(saved["scheduled_start_time"], "09:15")
            self.assertEqual(saved["duration_minutes"], 75)
            self.assertEqual(saved["linked_event_id"], event["event_id"])
            self.assertEqual(saved["context_links"][0]["external_source_id"], "thread-7")
            self.assertEqual(len(saved["attachments"]), 2)
            self.assertEqual(panel.state.calendar_selected_id, saved["item_id"])

            panel._open_item_editor(saved)
            edit_modal = panel.state.modal
            edit_modal["draft"]["title"] = "Prepare revised review"
            edit_modal["draft"]["status"] = "Review"
            edit_modal["draft"]["backlog"] = True
            unscheduled = panel._save_item_editor(edit_modal)
            self.assertEqual(unscheduled["title"], "Prepare revised review")
            self.assertEqual(unscheduled["status"], "Review")
            self.assertIsNone(unscheduled["scheduled_date"])
            self.assertIsNone(unscheduled["scheduled_start_time"])
            self.assertIsNone(unscheduled["duration_minutes"])
            self.assertEqual(unscheduled["linked_event_id"], event["event_id"])
            self.assertEqual(len(unscheduled["context_links"]), 1)
            self.assertEqual(len(unscheduled["attachments"]), 2)

