    def test_calendar_refresh_callback_guard_success_and_failure_states(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            _paths, _storage, _chats, _calendar, panel, services = self._panel_stack(Path(td))
            calls: list[str] = []

            def success() -> dict[str, Any]:
                calls.append("success")
                return {
                    "last_successful_sync_at": "2026-07-30T14:45:00Z",
                    "message": "Three calendars refreshed",
                }

            services.refresh_calendar = success
            self.assertTrue(panel._begin_calendar_refresh())
            self.assertEqual(calls, ["success"])
            self.assertFalse(panel.state.calendar_refresh_in_progress)
            self.assertEqual(panel.state.calendar_last_successful_sync_at, "2026-07-30T14:45:00Z")
            self.assertEqual(panel.state.calendar_refresh_status, "Three calendars refreshed")
            self.assertEqual(panel.state.calendar_refresh_error, "")

            panel.state.calendar_refresh_in_progress = True
            self.assertFalse(panel._begin_calendar_refresh())
            self.assertEqual(calls, ["success"])
            panel.state.calendar_refresh_in_progress = False

            def fail() -> Any:
                raise RuntimeError("calendar network unavailable")

            services.refresh_calendar = fail
            self.assertFalse(panel._begin_calendar_refresh())
            self.assertFalse(panel.state.calendar_refresh_in_progress)
            self.assertIn("calendar network unavailable", panel.state.calendar_refresh_error)
            self.assertEqual(panel.state.calendar_refresh_status, "")
            self.assertIn('else "Refresh"', inspect.getsource(velox.Panels._draw_calendar_week_header))

