    def test_calendar_draw_orchestration_uses_week_and_stacked_right_rail(self) -> None:
        class RecordingRenderer:
            def __init__(self) -> None:
                self.rects: list[Rect] = []
            def draw_rect(self, rect: Rect, *_args: Any, **_kwargs: Any) -> None:
                self.rects.append(rect)

        with tempfile.TemporaryDirectory() as td:
            _paths, _storage, _chats, _calendar, panel, _services = self._panel_stack(Path(td))
            renderer = RecordingRenderer()
            panel.widgets.renderer = renderer
            calls: list[tuple[str, velox.Rect, Any]] = []
            panel._draw_calendar_backlog_rail = lambda rect, rows: calls.append(("rail", rect, len(rows)))
            panel._draw_calendar_backlog_panel = lambda rect, rows, **kwargs: calls.append(("backlog", rect, kwargs))
            panel._draw_calendar_week = lambda rect, events, items: calls.append(("week", rect, (events, items)))
            panel._draw_calendar_week_chat = lambda rect: calls.append(("chat", rect, None))
            panel._draw_calendar_agent_tasks = lambda rect: calls.append(("agents", rect, None))
            panel._calendar_update_item_drag = lambda: calls.append(("drop", velox.Rect(0, 0, 0, 0), None))
            panel._draw_calendar_drag_overlay = lambda: calls.append(("drag", velox.Rect(0, 0, 0, 0), None))
            panel.state.calendar_week_chat_bound_date = panel.state.calendar_selected_date
            panel.state.calendar_backlog_expanded = False
            panel.draw_calendar_panel(velox.Rect(0, 0, 2560, 900))
            names = [row[0] for row in calls]
            self.assertEqual(names[:4], ["rail", "week", "chat", "agents"])
            week_rect = next(row[1] for row in calls if row[0] == "week")
            chat_rect = next(row[1] for row in calls if row[0] == "chat")
            agents_rect = next(row[1] for row in calls if row[0] == "agents")
            self.assertGreater(week_rect.w, chat_rect.w)
            self.assertEqual(chat_rect.x, agents_rect.x)
            self.assertLess(chat_rect.y, agents_rect.y)
            self.assertEqual(panel.state.top_input_capture, [])

