    def test_event_sync_http_410_full_resync_preserves_items_and_identity(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            _paths, _storage, _chats, calendar, integration = self._stack(Path(td))
            self._seed_one_calendar(integration)
            original = calendar.list_all_events()[0]
            item = calendar.create_item("Review resynced event", linked_event_id=original["event_id"])

            def calendars(kwargs: dict[str, Any], _index: int) -> dict[str, Any]:
                return {"items": [], "nextSyncToken": "calendar-list-token-2"}

            def events(kwargs: dict[str, Any], index: int) -> Any:
                if index == 0:
                    self.assertEqual(kwargs.get("syncToken"), "event-token-1")
                    return _FakeGoogleHttpError(410, "expired event token")
                self.assertNotIn("syncToken", kwargs)
                return {
                    "items": [self._timed_event(summary="Fresh full copy")],
                    "nextSyncToken": "event-token-after-410",
                }

            service = _FakeGoogleService(calendars, events)
            result = integration._refresh_locked(service)
            self.assertEqual(result["calendars_failed"], 0)
            refreshed = calendar.list_all_events()
            self.assertEqual(len(refreshed), 1)
            self.assertEqual(refreshed[0]["event_id"], original["event_id"])
            self.assertEqual(refreshed[0]["title"], "Fresh full copy")
            self.assertEqual(calendar.get_item(item["item_id"])["linked_event_id"], original["event_id"])
            self.assertEqual(calendar.get_google_sync_state()["calendars"][0]["sync_token"], "event-token-after-410")
            self.assertEqual(len(service.events_resource.calls), 2)

