            service = _FakeGoogleService(
                lambda kwargs, _index: {"items": [], "nextSyncToken": "calendar-list-token-2"},
                lambda kwargs, _index: {
                    "items": [self._timed_event("event-1", summary="Still present")],
                    "nextSyncToken": "event-token-full-2",
                },
            )
            integration._refresh_locked(service)
            disappeared = calendar.get_event(missing["event_id"])
            self.assertEqual(disappeared["status"], "cancelled")
            self.assertEqual(calendar.get_item(item["item_id"])["linked_event_id"], missing["event_id"])
            self.assertEqual(len(calendar.list_all_events()), 2)

