            credential_store = velox.CredentialStore(paths)
            credential_store.save_google_oauth_client(
                "client-id.apps.googleusercontent.com", "CLIENTSECRET",
            )
            captures: dict[str, Any] = {}

            class FakeCredentials:
                valid = True
                expired = False
                refresh_token = "REFRESHSECRET"

                def to_json(self) -> str:
                    return json.dumps({
                        "token": "TOPSECRET",
                        "refresh_token": "REFRESHSECRET",
                        "scopes": list(velox.GOOGLE_CALENDAR_SCOPES),
                    })

            class FakeCredentialsType:
                @classmethod
                def from_authorized_user_info(cls, info: dict[str, Any], scopes: list[str]) -> Any:
                    captures["loaded_token_info"] = copy.deepcopy(info)
                    captures["loaded_scopes"] = list(scopes)
                    return FakeCredentials()

            class FakeFlow:
                def run_local_server(self, **kwargs: Any) -> Any:
                    captures["run_local_server"] = copy.deepcopy(kwargs)
                    return FakeCredentials()

            class FakeFlowType:
                @classmethod
                def from_client_config(cls, client_config: dict[str, Any], scopes: list[str]) -> Any:
                    captures["client_config"] = copy.deepcopy(client_config)
                    captures["oauth_scopes"] = list(scopes)
                    return FakeFlow()

            dependencies = velox.GoogleCalendarDependencies(
                request_type=lambda: object(),
                credentials_type=FakeCredentialsType,
                installed_app_flow_type=FakeFlowType,
                build=lambda *_args, **_kwargs: None,
                http_error_type=_FakeGoogleHttpError,
                http_type=object,
                authorized_http_type=object,
            )
            service = _FakeGoogleService(
                lambda kwargs, _index: {
                    "items": [self._calendar_resource()],
                    "nextSyncToken": "calendar-list-token-connect",
                },
                lambda kwargs, _index: {
                    "items": [self._timed_event("connect-event")],
                    "nextSyncToken": "event-token-connect",
                },
            )
            integration = velox.GoogleCalendarIntegration(
                storage,
                calendar,
                dependencies_loader=lambda: dependencies,
                service_factory=lambda _credentials, _deps: service,
            )
            result = asyncio.run(integration.connect())
            self.assertTrue(result["connected"])
            self.assertIn("choose Calendars", result["message"])
            self.assertEqual(calendar.list_all_events(), [])
            self.assertFalse(calendar.get_google_sync_state()["calendars"][0]["enabled"])
            integration.set_calendar_enabled("mike@example.com", True)
            refreshed = asyncio.run(integration.refresh())
            self.assertEqual(refreshed["events_upserted"], 1)
            self.assertEqual(captures["oauth_scopes"], list(velox.GOOGLE_CALENDAR_SCOPES))
            self.assertEqual(captures["client_config"]["installed"]["client_id"], "client-id.apps.googleusercontent.com")
            self.assertEqual(captures["client_config"]["installed"]["client_secret"], "CLIENTSECRET")
            self.assertEqual(captures["run_local_server"]["port"], 0)
            self.assertTrue(captures["run_local_server"]["open_browser"])
            google_credentials = velox.CredentialStore(paths).load_google_calendar()
            self.assertEqual(google_credentials["token"]["token"], "TOPSECRET")
            self.assertEqual(google_credentials["client_id"], "client-id.apps.googleusercontent.com")
            self.assertEqual(google_credentials["client_secret"], "CLIENTSECRET")
            self.assertNotIn("accounts", storage.load_config())
            status = integration.status()
            self.assertTrue(status["connected"])
            self.assertTrue(status["oauth_client_configured"])
            self.assertEqual(status["oauth_client_source"], "credentials")

            raw_credentials = paths.google_calendar_credentials_file().read_bytes()
