    def test_missing_dependencies_direct_oauth_configuration_and_concurrency_fail_cleanly(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            _paths, storage, _chats, calendar, _unused = self._stack(Path(td))

            def missing() -> GoogleCalendarDependencies:
                raise velox.GoogleCalendarDependencyError("install Google libraries")

            integration = velox.GoogleCalendarIntegration(storage, calendar, dependencies_loader=missing)
            status = integration.status()
            self.assertFalse(status["dependencies"]["available"])
            self.assertFalse(status["connected"])
            self.assertFalse(status["oauth_client_configured"])
            with self.assertRaises(velox.GoogleCalendarDependencyError):
                asyncio.run(integration.refresh())
            with self.assertRaises(velox.GoogleCalendarAuthorizationError):
                asyncio.run(integration.connect())

            integration._operation_lock.acquire()
            try:
                self.assertTrue(integration.status()["operation_in_progress"])
                with self.assertRaises(RuntimeError):
                    integration._disconnect_blocking()
            finally:
                integration._operation_lock.release()

            valid = velox.google_oauth_client_config("client.apps.googleusercontent.com", "GOCSPX-secret")
            self.assertEqual(valid["installed"]["client_id"], "client.apps.googleusercontent.com")
            self.assertEqual(valid["installed"]["client_secret"], "GOCSPX-secret")
            self.assertEqual(valid["installed"]["redirect_uris"], ["http://localhost"])
            with self.assertRaises(velox.GoogleCalendarAuthorizationError):
                velox.google_oauth_client_config("", "")
            with self.assertRaises(velox.GoogleCalendarAuthorizationError):
                velox.google_oauth_client_config("bad id", "secret")

            with mock.patch.dict(
                os.environ,
                {velox.GOOGLE_OAUTH_CLIENT_ID_ENV: "env-client", velox.GOOGLE_OAUTH_CLIENT_SECRET_ENV: "env-secret"},
                clear=False,
            ):
                env_integration = velox.GoogleCalendarIntegration(storage, calendar, dependencies_loader=missing)
                self.assertEqual(env_integration._configured_oauth_client(), ("env-client", "env-secret", "environment"))

