            class Credentials:
                valid = True
                expired = False
                refresh_token = "refresh"

                def to_json(self) -> str:
                    return json.dumps({"token": "token", "refresh_token": "refresh"})

            class Flow:
                def run_local_server(self, **_kwargs: Any) -> Any:
                    return Credentials()

            class FlowType:
                @classmethod
                def from_client_config(cls, _config: dict[str, Any], _scopes: list[str]) -> Any:
                    return Flow()

            dependencies = velox.GoogleCalendarDependencies(
                request_type=lambda: object(),
                credentials_type=object,
                installed_app_flow_type=FlowType,
                build=lambda *_args, **_kwargs: None,
                http_error_type=_FakeGoogleHttpError,
                http_type=object,
                authorized_http_type=object,
            )

            def loader() -> velox.GoogleCalendarDependencies:
                state["load_calls"] += 1
                if not state["installed"]:
                    raise velox.GoogleCalendarDependencyError("missing")
                return dependencies

            def installer() -> None:
                state["install_calls"] += 1
                state["installed"] = True

            service = _FakeGoogleService(
                lambda _kwargs, _index: {"items": [self._calendar_resource()], "nextSyncToken": "list-token"},
                lambda _kwargs, _index: {"items": [], "nextSyncToken": "event-token"},
            )
            integration = velox.GoogleCalendarIntegration(
                storage, calendar, dependencies_loader=loader, dependency_installer=installer,
                service_factory=lambda _credentials, _deps: service,
            )
            result = asyncio.run(integration.connect())
            self.assertTrue(result["connected"])
            self.assertEqual(state["install_calls"], 1)
            self.assertGreaterEqual(state["load_calls"], 2)
            self.assertEqual(velox.CredentialStore(paths).load_google_calendar()["token"]["token"], "token")

