class ConnectorTests(_DataRootsIsolatedTestMixin, unittest.TestCase):
    """Read-only Drive, Gmail and Slack synchronization."""


    @staticmethod
    def _gmail_message(subject: str, body: str, *, html_only: bool = False, attachment: bool = False) -> bytes:
        header_date = format_datetime(datetime.now(timezone.utc) - timedelta(days=1))
        if html_only:
            return (
                f"From: =?UTF-8?Q?Jos=C3=A9?= <jose@example.com>\r\n"
                f"To: Mike <mike@example.com>\r\n"
                f"Subject: {subject}\r\n"
                "Message-ID: <message@example.com>\r\n"
                f"Date: {header_date}\r\n"
                "Content-Type: text/html; charset=utf-8\r\n\r\n"
                f"<html><body><p>{body}</p><img src='https://tracker.invalid/pixel'></body></html>"
            ).encode("utf-8")
        if attachment:
            return (
                f"From: Sender <sender@example.com>\r\nTo: Mike <mike@example.com>\r\nSubject: {subject}\r\n"
                f"Message-ID: <attachment@example.com>\r\nDate: {header_date}\r\n"
                "MIME-Version: 1.0\r\nContent-Type: multipart/mixed; boundary=velox\r\n\r\n"
                "--velox\r\nContent-Type: text/plain; charset=utf-8\r\n\r\n"
                f"{body}\r\n--velox\r\nContent-Type: application/pdf\r\n"
                "Content-Disposition: attachment; filename=report.pdf\r\nContent-Transfer-Encoding: base64\r\n\r\n"
                "UERG\r\n--velox--\r\n"
            ).encode("utf-8")
        return (
            f"From: Sender <sender@example.com>\r\nTo: Mike <mike@example.com>\r\nSubject: {subject}\r\n"
            f"Message-ID: <plain@example.com>\r\nDate: {header_date}\r\n"
            "Content-Type: text/plain; charset=utf-8\r\n\r\n" + body
        ).encode("utf-8")

    class _FakeIMAP:
        def __init__(self, messages: dict[int, dict[str, Any]], *, uidvalidity: str = "777", login_error: bool = False):
            self.messages = messages
            self.uidvalidity = uidvalidity
            self.login_error = login_error
            self.fetch_specs: list[str] = []
            self.search_calls: list[tuple[str, ...]] = []
            self.list_calls: list[tuple[str, str]] = []
            self.selected: list[tuple[str, bool]] = []
            self.logged_out = False
            self.id_calls = 0
            self.default_internaldate = (datetime.now(timezone.utc) - timedelta(days=1)).strftime("%d-%b-%Y %H:%M:%S +0000")

        def login(self, username: str, password: str) -> tuple[str, list[bytes]]:
            if self.login_error:
                raise imaplib.IMAP4.error("AUTHENTICATIONFAILED")
            self.username = username
            self.password = password
            return "OK", [b"logged in"]

        def capability(self) -> tuple[str, list[bytes]]:
            return "OK", [b"IMAP4rev1 SPECIAL-USE X-GM-EXT-1 ID"]

        def _simple_command(self, command: str, payload: str) -> tuple[str, list[bytes]]:
            self.id_calls += 1
            return "OK", [b"ID accepted"]

        def list(self, _reference: str, _pattern: str) -> tuple[str, list[bytes]]:
            self.list_calls.append((_reference, _pattern))
            return "OK", [
                b'(\\HasNoChildren \\Inbox) "/" "INBOX"',
                b'(\\HasNoChildren \\All) "/" "[Gmail]/All Mail"',
                b'(\\HasNoChildren \\Trash) "/" "[Gmail]/Trash"',
            ]

        def select(self, mailbox: str, readonly: bool = False) -> tuple[str, list[bytes]]:
            self.selected.append((mailbox, readonly))
            return "OK", [str(len(self.messages)).encode("ascii")]

        def response(self, name: str) -> tuple[str, list[bytes]]:
            self.assert_name = name
            return "OK", [self.uidvalidity.encode("ascii")]

        def uid(self, command: str, *args: Any) -> tuple[str, list[Any]]:
            if command.lower() == "search":
                criteria = tuple(str(value or "") for value in args if value is not None)
                self.search_calls.append(criteria)
                criterion = " ".join(criteria)
                minimum = 1
                match = re.search(r"UID\s+(\d+):\*", criterion, flags=re.I)
                if match:
                    minimum = int(match.group(1))
                after_match = re.search(r"after:(\d+)", criterion, flags=re.I)
                cutoff = int(after_match.group(1)) if after_match else 0
                uids: list[int] = []
                for uid in sorted(self.messages):
                    if uid < minimum:
                        continue
                    row = self.messages[uid]
                    internal = str(row.get("internaldate") or self.default_internaldate)
                    try:
                        stamp = int(parsedate_to_datetime(internal).timestamp())
                    except Exception:
                        stamp = 0
                    if cutoff and stamp <= cutoff:
                        continue
                    uids.append(uid)
                return "OK", [" ".join(str(uid) for uid in uids).encode("ascii")]
            if command.lower() != "fetch":
                return "BAD", []
            uid_text = str(args[0] or "")
            spec = str(args[1] or "")
            self.fetch_specs.append(spec)
            rows: list[Any] = []
            for token in uid_text.split(","):
                if not token.strip():
                    continue
                uid = int(token)
                row = self.messages.get(uid)
                if row is None:
                    continue
                raw = bytes(row["raw"])
                labels = " ".join(f'"{label}"' for label in row.get("labels", ["\\Inbox"]))
                flags = " ".join(row.get("flags", []))
                metadata = (
                    f'{uid} (X-GM-MSGID {row.get("msgid", 1000 + uid)} '
                    f'X-GM-THRID {row.get("thrid", 2000 + uid)} X-GM-LABELS ({labels}) '
                    f'UID {uid} FLAGS ({flags}) INTERNALDATE "{row.get("internaldate", self.default_internaldate)}" '
                    f'RFC822.SIZE {len(raw)} BODY[] {{{len(raw)}}}'
                ).encode("utf-8")
                rows.append((metadata, raw))
                rows.append(b")")
            return "OK", rows

        def logout(self) -> tuple[str, list[bytes]]:
            self.logged_out = True
            return "BYE", [b"logout"]

    class _HTTPResponse:
        def __init__(self, payload: dict[str, Any], *, status: int = 200, headers: dict[str, str] | None = None):
            self.payload = payload
            self.status = status
            self.headers = headers or {}

        def read(self) -> bytes:
            return json.dumps(self.payload).encode("utf-8")

        def __enter__(self) -> "ConnectorTests._HTTPResponse":
            return self

        def __exit__(self, *_args: Any) -> None:
            return None

    class _FakeSlackClient:
        def __init__(self):
            now = time.time()
            self.parent_ts = f"{now - 120:.6f}"
            self.reply_ts = f"{now - 60:.6f}"
            self.parent_text = "Hello <@U2>; read <https://example.com/report|the report>"
            self.include_reply = True
            self.fail_channels: set[str] = set()
            self.calls: list[tuple[str, dict[str, Any]]] = []

        def call(self, method: str, params: dict[str, Any] | None = None) -> dict[str, Any]:
            params = dict(params or {})
            self.calls.append((method, params))
            if method == "auth.test":
                return {"ok": True, "team_id": "T1", "team": "Example Workspace", "user_id": "U1"}
            if method == "users.list":
                if not params.get("cursor"):
                    return {
                        "ok": True,
                        "members": [{"id": "U1", "real_name": "Mike", "profile": {"display_name": "Mike"}}],
                        "response_metadata": {"next_cursor": "users-2"},
                    }
                return {
                    "ok": True,
                    "members": [{"id": "U2", "real_name": "Riley", "profile": {"display_name": "Riley"}}],
                    "response_metadata": {"next_cursor": ""},
                }
            if method == "conversations.list":
                return {
                    "ok": True,
                    "channels": [
                        {"id": "C1", "name": "leadership", "name_normalized": "leadership", "is_private": False, "is_archived": False},
                        {"id": "G1", "name": "private", "is_private": True, "is_archived": False},
                        {"id": "D1", "is_im": True, "user": "U2", "is_archived": False},
                        {"id": "M1", "is_mpim": True, "members": ["U1", "U2"], "is_archived": False},
                    ],
                    "response_metadata": {"next_cursor": ""},
                }
            if method == "conversations.history":
                channel = str(params.get("channel") or "")
                if channel in self.fail_channels:
                    raise velox.SlackAPIError("not_in_channel")
                if channel != "C1":
                    return {"ok": True, "messages": [], "response_metadata": {"next_cursor": ""}}
                parent = {
                    "type": "message", "ts": self.parent_ts, "user": "U2", "text": self.parent_text,
                    "reply_count": 1 if self.include_reply else 0,
                    "edited": {"ts": f"{float(self.parent_ts) + 1:.6f}"},
                    "reactions": [{"name": "thumbsup", "count": 2, "users": ["U1", "U2"]}],
                    "files": [{"id": "F1", "name": "numbers.csv", "title": "Numbers", "mimetype": "text/csv", "size": 42, "permalink": "https://slack.example/files/F1"}],
                }
                return {"ok": True, "messages": [parent], "response_metadata": {"next_cursor": ""}}
            if method == "conversations.replies":
                messages = [{"type": "message", "ts": self.parent_ts, "user": "U2", "text": self.parent_text}]
                if self.include_reply:
                    messages.append({"type": "message", "ts": self.reply_ts, "thread_ts": self.parent_ts, "user": "U1", "text": "Agreed"})
                return {"ok": True, "messages": messages, "response_metadata": {"next_cursor": ""}}
            raise AssertionError(f"unexpected Slack method: {method}")

