class ConfigurationAndConnectorConcurrencyTests(_DataRootsIsolatedTestMixin, unittest.TestCase):
    """Endpoint defaults, credential locking and connector lifecycle."""


    @staticmethod
    def _enable_drive(storage: Storage, *, include_shared: bool) -> None:
        config = storage.load_config()
        config["vault"]["google_drive"]["enabled"] = True
        config["vault"]["google_drive"]["include_shared_drives"] = bool(include_shared)
        storage.write_config(config)

    @staticmethod
    def _drive_file(
        file_id: str,
        name: str,
        *,
        mime_type: str = "text/plain",
        modified: str = "2026-08-01T12:00:00Z",
        created: str = "2026-08-01T10:00:00Z",
        drive_id: str = "",
        can_download: bool = True,
        trashed: bool = False,
    ) -> dict[str, Any]:
        payload: dict[str, Any] = {
            "id": file_id,
            "name": name,
            "mimeType": mime_type,
            "description": f"Description for {name}",
            "modifiedTime": modified,
            "createdTime": created,
            "parents": ["root"],
            "trashed": trashed,
            "owners": [{
                "displayName": "Mike",
                "emailAddress": "mike@example.com",
                "permissionId": "owner-1",
            }],
            "capabilities": {"canDownload": bool(can_download)},
            "webViewLink": f"https://drive.google.com/file/d/{file_id}/view",
            "size": "42",
        }
        if drive_id:
            payload["driveId"] = drive_id
        return payload

    class _DriveRequest:
        def __init__(self, service: "ConfigurationAndConnectorConcurrencyTests._DriveService", kind: str, kwargs: dict[str, Any]):
            self.service = service
            self.kind = kind
            self.kwargs = copy.deepcopy(kwargs)

        def execute(self) -> Any:
            self.service.calls.append((self.kind, copy.deepcopy(self.kwargs)))
            value = self.service.resolve(self.kind, self.kwargs)
            if isinstance(value, BaseException):
                raise value
            return copy.deepcopy(value)

    class _DriveResource:
        def __init__(self, service: "ConfigurationAndConnectorConcurrencyTests._DriveService", prefix: str):
            self.service = service
            self.prefix = prefix

        def _request(self, method: str, **kwargs: Any) -> "ConfigurationAndConnectorConcurrencyTests._DriveRequest":
            return ConfigurationAndConnectorConcurrencyTests._DriveRequest(
                self.service, f"{self.prefix}.{method}", kwargs,
            )

        def get(self, **kwargs: Any) -> "ConfigurationAndConnectorConcurrencyTests._DriveRequest":
            return self._request("get", **kwargs)

        def list(self, **kwargs: Any) -> "ConfigurationAndConnectorConcurrencyTests._DriveRequest":
            return self._request("list", **kwargs)

        def getStartPageToken(self, **kwargs: Any) -> "ConfigurationAndConnectorConcurrencyTests._DriveRequest":
            return self._request("getStartPageToken", **kwargs)

        def get_media(self, **kwargs: Any) -> "ConfigurationAndConnectorConcurrencyTests._DriveRequest":
            return self._request("get_media", **kwargs)

        def export_media(self, **kwargs: Any) -> "ConfigurationAndConnectorConcurrencyTests._DriveRequest":
            return self._request("export_media", **kwargs)

    class _DriveService:
        def __init__(
            self,
            *,
            file_pages: dict[tuple[str, str, str], Any] | None = None,
            change_pages: dict[str, Any] | None = None,
            start_tokens: Iterable[str] = ("start-1",),
            shared_drive_pages: dict[str, Any] | None = None,
            media: dict[str, Any] | None = None,
            exports: dict[tuple[str, str], Any] | None = None,
        ):
            self.file_pages = dict(file_pages or {})
            self.change_pages = dict(change_pages or {})
            self.start_tokens = list(start_tokens)
            self.shared_drive_pages = dict(shared_drive_pages or {})
            self.media = dict(media or {})
            self.exports = dict(exports or {})
            self.calls: list[tuple[str, dict[str, Any]]] = []
            self.about_payload = {
                "user": {
                    "displayName": "Mike",
                    "emailAddress": "mike@example.com",
                    "permissionId": "permission-1",
                },
                "storageQuota": {"limit": "1000", "usage": "100"},
            }

        def about(self) -> "ConfigurationAndConnectorConcurrencyTests._DriveResource":
            return ConfigurationAndConnectorConcurrencyTests._DriveResource(self, "about")

        def files(self) -> "ConfigurationAndConnectorConcurrencyTests._DriveResource":
            return ConfigurationAndConnectorConcurrencyTests._DriveResource(self, "files")

        def changes(self) -> "ConfigurationAndConnectorConcurrencyTests._DriveResource":
            return ConfigurationAndConnectorConcurrencyTests._DriveResource(self, "changes")

        def drives(self) -> "ConfigurationAndConnectorConcurrencyTests._DriveResource":
            return ConfigurationAndConnectorConcurrencyTests._DriveResource(self, "drives")

        def resolve(self, kind: str, kwargs: dict[str, Any]) -> Any:
            if kind == "about.get":
                return self.about_payload
            if kind == "changes.getStartPageToken":
                token = self.start_tokens.pop(0) if len(self.start_tokens) > 1 else self.start_tokens[0]
                return {"startPageToken": token}
            if kind == "files.list":
                key = (
                    str(kwargs.get("corpora") or "user"),
                    str(kwargs.get("driveId") or ""),
                    str(kwargs.get("pageToken") or ""),
                )
                return self.file_pages.get(key, {"files": []})
            if kind == "changes.list":
                return self.change_pages.get(str(kwargs.get("pageToken") or ""), {
                    "changes": [], "newStartPageToken": "next-default",
                })
            if kind == "drives.list":
                return self.shared_drive_pages.get(str(kwargs.get("pageToken") or ""), {
                    "drives": [],
                })
            if kind == "files.get_media":
                return self.media[str(kwargs.get("fileId") or "")]
            if kind == "files.export_media":
                key = (str(kwargs.get("fileId") or ""), str(kwargs.get("mimeType") or ""))
                return self.exports[key]
            raise AssertionError(f"Unexpected fake Google Drive request: {kind} {kwargs}")


