    def test_connector_manager_consumes_finished_task_before_replacement_and_shutdown(self) -> None:
        class ImmediateConnector(velox.VaultConnectorContract):
            def __init__(self, source_type: str, *, fail_first: bool = False):
                self.source_type = source_type
                self.fail_first = fail_first
                self.sync_calls = 0

            def get_connector_type(self) -> str:
                return self.source_type

            def validate_configuration(self) -> dict[str, Any]:
                return {"configured": True, "token_present": True}

            async def test_connection(self) -> dict[str, Any]:
                return {"ok": True}

            async def connect_or_authorize(self) -> dict[str, Any]:
                return {"ok": True}

            async def sync(self) -> dict[str, Any]:
                self.sync_calls += 1
                if self.fail_first and self.sync_calls == 1:
                    raise RuntimeError(f"{self.source_type} first sync failed")
                return {"ok": True, "processed": self.sync_calls}

            def cancel_sync(self) -> None:
                return None

            async def disconnect(self) -> dict[str, Any]:
                return {"ok": True}

            def get_status(self) -> dict[str, Any]:
                return {"operation_in_progress": False}

        async def scenario(root: Path) -> None:
            paths, storage, _vault, _credentials, _query = _make_test_connector_stack(root)
            drive = ImmediateConnector(velox.GOOGLE_DRIVE_SOURCE_TYPE)
            gmail = ImmediateConnector(velox.GMAIL_SOURCE_TYPE, fail_first=True)
            slack = ImmediateConnector(velox.SLACK_SOURCE_TYPE, fail_first=True)
            manager = velox.VaultConnectorManager(storage, drive, gmail, slack)

            first = manager.start(velox.GMAIL_SOURCE_TYPE, "sync")
            while not first.done():
                await asyncio.sleep(0)
            # Starting again before tick() must retrieve and log the failed
            # result rather than overwriting the only task reference.
            second = manager.start(velox.GMAIL_SOURCE_TYPE, "sync")
            self.assertEqual((await second)["processed"], 2)
            self.assertTrue(velox.APP_LOG_WRITER.flush((paths.log_jsonl_path,), timeout=3.0))
            log_text = paths.log_jsonl_path.read_text(encoding="utf-8")
            self.assertIn("gmail.background_sync_failed", log_text)
            self.assertIn("gmail first sync failed", log_text)

            # A task that finishes immediately before shutdown is gathered even
            # when the periodic scheduler has not consumed it yet.
            shutdown_task = manager.start(velox.SLACK_SOURCE_TYPE, "sync")
            while not shutdown_task.done():
                await asyncio.sleep(0)
            await manager.shutdown()
            self.assertEqual(manager.tasks, {})

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))


