    def test_credential_lock_order_prevents_direct_save_mutation_deadlock(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            paths, _storage, _vault, credentials, _query = _make_test_connector_stack(Path(td))
            credentials.save_github("initial", "pat")
            credentials.save_google_drive_oauth_client("client", "secret")
            entered_validation = threading.Event()
            release_validation = threading.Event()
            errors: list[BaseException] = []
            original_validate = credentials._validate_values

            def gated_validate(account: str, values: Any) -> dict[str, Any]:
                if (
                    account == velox.GITHUB_CREDENTIAL_ACCOUNT
                    and threading.current_thread().name == "credential-direct-save"
                ):
                    entered_validation.set()
                    if not release_validation.wait(timeout=5):
                        raise TimeoutError("credential lock-order test gate timed out")
                return original_validate(account, values)

            def direct_save() -> None:
                try:
                    credentials.save_github("updated", "new-pat")
                except BaseException as exc:
                    errors.append(exc)

            def token_mutation() -> None:
                try:
                    credentials.save_google_drive_token({"token": "updated-token"})
                except BaseException as exc:
                    errors.append(exc)

            with mock.patch.object(credentials, "_validate_values", side_effect=gated_validate):
                direct_thread = threading.Thread(
                    target=direct_save, name="credential-direct-save", daemon=True,
                )
                mutate_thread = threading.Thread(
                    target=token_mutation, name="credential-token-mutate", daemon=True,
                )
                direct_thread.start()
                self.assertTrue(entered_validation.wait(timeout=2))
                mutate_thread.start()
                time.sleep(0.05)
                release_validation.set()
                direct_thread.join(timeout=5)
                mutate_thread.join(timeout=5)

            self.assertFalse(direct_thread.is_alive())
            self.assertFalse(mutate_thread.is_alive())
            self.assertEqual(errors, [])
            self.assertEqual(credentials.load_github(), {"username": "updated", "pat": "new-pat"})
            self.assertEqual(
                credentials.load_google_drive()["token"], {"token": "updated-token"},
            )

    def test_credential_read_modify_write_is_thread_safe_and_keeps_xor_payload_valid(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            paths, _storage, _vault, credentials, _query = _make_test_connector_stack(Path(td))
            client_store = credentials
            token_store = velox.CredentialStore(paths)
            client_store.save_google_drive_oauth_client("initial", "secret")
            errors: list[BaseException] = []

            def write_clients() -> None:
                try:
                    for index in range(40):
                        client_store.save_google_drive_oauth_client(f"client-{index}", f"secret-{index}")
                except BaseException as exc:
                    errors.append(exc)

            def write_tokens() -> None:
                try:
                    for index in range(40):
                        token_store.save_google_drive_token({"token": f"token-{index}", "refresh_token": "refresh"})
                except BaseException as exc:
                    errors.append(exc)

            threads = [threading.Thread(target=write_clients), threading.Thread(target=write_tokens)]
            for thread in threads:
                thread.start()
            for thread in threads:
                thread.join(timeout=10)
            self.assertFalse(errors)
            self.assertTrue(all(not thread.is_alive() for thread in threads))
            values = velox.CredentialStore(paths).load_google_drive()
            self.assertIn("DATA_ROOTS.lock_for_path", inspect.getsource(velox.CredentialStore._mutate))
            self.assertTrue(values["client_id"].startswith("client-"))
            self.assertTrue(values["client_secret"].startswith("secret-"))
            self.assertTrue(str(values["token"]["token"]).startswith("token-"))
            raw = paths.google_drive_credentials_file().read_bytes()
            self.assertNotIn(b"client-", raw)
            decoded = json.loads(velox.xor_credential_bytes(raw).decode("utf-8"))
            self.assertEqual(decoded["schema"], velox.CREDENTIAL_FILE_SCHEMA)
            self.assertEqual(decoded["account"], velox.GOOGLE_DRIVE_CREDENTIAL_ACCOUNT)


