    def test_agent_concurrency_limit_releases_each_request_and_grants_fifo(self) -> None:
        async def scenario(root: Path) -> None:
            storage = velox.Storage(velox.AppPaths(root)); storage.ensure_first_run_files()
            profile = velox.default_endpoint_profile(
                "queue-endpoint", "Queue endpoint", timeout_seconds=60,
                provider=velox.ENDPOINT_PROVIDER_VLLM, max_concurrent_requests=1,
            )
            monitor = velox.LLMTaskMonitor(storage)
            scheduler = velox.EndpointInferenceScheduler(storage, lambda _pid: profile, monitor)
            first_id = monitor.start(velox.APP_SCOPE_ID, "first", task_kind="chat", metadata={"task_type": "Chat"})
            old_id = monitor.start(velox.APP_SCOPE_ID, "old", task_kind="chat", metadata={"task_type": "Chat"})
            new_id = monitor.start(velox.APP_SCOPE_ID, "new", task_kind="chat", metadata={"task_type": "Chat"})
            first = await scheduler.acquire(velox.LLMRequest(
                velox.APP_SCOPE_ID, "queue-endpoint", [], monitor_task_id=first_id, task_kind="chat",
            ))
            old_task = asyncio.create_task(scheduler.acquire(velox.LLMRequest(
                velox.APP_SCOPE_ID, "queue-endpoint", [], monitor_task_id=old_id, task_kind="chat",
            )))
            await asyncio.sleep(0.02)
            new_task = asyncio.create_task(scheduler.acquire(velox.LLMRequest(
                velox.APP_SCOPE_ID, "queue-endpoint", [], monitor_task_id=new_id, task_kind="chat",
            )))
            await asyncio.sleep(0.02)
            self.assertFalse(old_task.done()); self.assertFalse(new_task.done())
            await first.release()
            old_lease = await asyncio.wait_for(old_task, 1.0)
            self.assertFalse(new_task.done())
            snap = scheduler.snapshot()["queue-endpoint"]
            self.assertEqual(snap["active_task_ids"], [old_id])
            self.assertTrue(snap["slot_invariant_ok"])
            self.assertEqual(snap["slots_consumed"], snap["inference_requests"])
            await old_lease.release()
            new_lease = await asyncio.wait_for(new_task, 1.0)
            await new_lease.release()
            monitor.complete(first_id); monitor.complete(old_id); monitor.complete(new_id)
            self.assertEqual(scheduler.snapshot()["queue-endpoint"]["active"], [])
            await scheduler.close()
        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_tool_phase_releases_capacity_and_next_provider_round_requeues(self) -> None:
        async def scenario(root: Path) -> None:
            storage = velox.Storage(velox.AppPaths(root)); storage.ensure_first_run_files()
            profile = velox.default_endpoint_profile(
                "request-scoped", "Request scoped", timeout_seconds=60,
                provider=velox.ENDPOINT_PROVIDER_VLLM, max_concurrent_requests=1,
            )
            monitor = velox.LLMTaskMonitor(storage)
            scheduler = velox.EndpointInferenceScheduler(storage, lambda _pid: profile, monitor)
            active_id = monitor.start(velox.APP_SCOPE_ID, "active chat", task_kind="chat", metadata={"task_type": "Chat"})
            waiting_id = monitor.start(velox.APP_SCOPE_ID, "waiting chat", task_kind="chat", metadata={"task_type": "Chat"})
            first = await scheduler.acquire(velox.LLMRequest(
                velox.APP_SCOPE_ID, "request-scoped", [], monitor_task_id=active_id, task_kind="chat",
            ))
            waiting = asyncio.create_task(scheduler.acquire(velox.LLMRequest(
                velox.APP_SCOPE_ID, "request-scoped", [], monitor_task_id=waiting_id, task_kind="chat",
            )))
            monitor.set_phase(active_id, "tool")
            await first.release()
            waiting_lease = await asyncio.wait_for(waiting, 1.0)
            self.assertEqual(scheduler.snapshot()["request-scoped"]["active_task_ids"], [waiting_id])

            second_round = asyncio.create_task(scheduler.acquire(velox.LLMRequest(
                velox.APP_SCOPE_ID, "request-scoped", [], monitor_task_id=active_id, task_kind="chat",
            )))
            await asyncio.sleep(0.03)
            self.assertFalse(second_round.done())
            await waiting_lease.release()
            second = await asyncio.wait_for(second_round, 1.0)
            self.assertEqual(scheduler.snapshot()["request-scoped"]["active_task_ids"], [active_id])
            await second.release()
            monitor.complete(active_id); monitor.complete(waiting_id)
            await scheduler.close()
        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_cancelling_a_queued_agent_cannot_leave_a_stale_fifo_head(self) -> None:
        async def scenario(root: Path) -> None:
            storage = velox.Storage(velox.AppPaths(root)); storage.ensure_first_run_files()
            profile = velox.default_endpoint_profile("queue-endpoint", "Queue endpoint", timeout_seconds=60, provider=velox.ENDPOINT_PROVIDER_VLLM, max_concurrent_requests=1)
            scheduler = velox.EndpointInferenceScheduler(storage, lambda _pid: profile)
            first = await scheduler.acquire(velox.LLMRequest(velox.APP_SCOPE_ID, "queue-endpoint", [], task_kind="agent"))
            cancelled_event = threading.Event()
            waiting = asyncio.create_task(scheduler.acquire(velox.LLMRequest(velox.APP_SCOPE_ID, "queue-endpoint", [], task_kind="agent", cancel_event=cancelled_event)))
            await asyncio.sleep(0.03)
            cancelled_event.set()
            with self.assertRaises(velox.LLMRequestCancelledError):
                await asyncio.wait_for(waiting, 1.0)
            await first.release()
            third = await asyncio.wait_for(scheduler.acquire(velox.LLMRequest(velox.APP_SCOPE_ID, "queue-endpoint", [], task_kind="agent")), 1.0)
            await third.release()
            snap = scheduler.snapshot().get("queue-endpoint", {})
            self.assertFalse(snap.get("active"))
            self.assertFalse(snap.get("queued"))
            await scheduler.close()
        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_pausing_a_queued_agent_removes_it_from_runnable_fifo_until_resume(self) -> None:
        async def scenario(root: Path) -> None:
            storage = velox.Storage(velox.AppPaths(root)); storage.ensure_first_run_files()
            profile = velox.default_endpoint_profile(
                "queue-endpoint", "Queue endpoint", timeout_seconds=60,
                provider=velox.ENDPOINT_PROVIDER_VLLM, max_concurrent_requests=1,
            )
            monitor = velox.LLMTaskMonitor(storage)
            scheduler = velox.EndpointInferenceScheduler(storage, lambda _pid: profile, monitor)
            holder_id = monitor.start(velox.APP_SCOPE_ID, "holder", task_kind="chat")
            paused_id = monitor.start(velox.APP_SCOPE_ID, "paused", task_kind="agent")
            next_id = monitor.start(velox.APP_SCOPE_ID, "next", task_kind="agent")
            monitor.register_pause_callback(paused_id, lambda: True)
            monitor.register_resume_callback(paused_id, lambda: True)
            holder = await scheduler.acquire(velox.LLMRequest(
                velox.APP_SCOPE_ID, "queue-endpoint", [], monitor_task_id=holder_id, task_kind="chat",
            ))
            paused_task = asyncio.create_task(scheduler.acquire(velox.LLMRequest(
                velox.APP_SCOPE_ID, "queue-endpoint", [], monitor_task_id=paused_id, task_kind="agent",
            )))
            await asyncio.sleep(0.03)
            self.assertTrue(monitor.pause_task(paused_id))
            next_task = asyncio.create_task(scheduler.acquire(velox.LLMRequest(
                velox.APP_SCOPE_ID, "queue-endpoint", [], monitor_task_id=next_id, task_kind="agent",
            )))
            await asyncio.sleep(0.05)
            self.assertEqual(len(scheduler.snapshot()["queue-endpoint"]["paused"]), 1)
            await holder.release()
            next_lease = await asyncio.wait_for(next_task, 1.0)
            self.assertFalse(paused_task.done())
            await next_lease.release()
            self.assertTrue(monitor.resume_task(paused_id))
            paused_lease = await asyncio.wait_for(paused_task, 1.0)
            await paused_lease.release()
            monitor.complete(holder_id); monitor.complete(next_id); monitor.complete(paused_id)
            await scheduler.close()
        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_paused_task_cannot_reacquire_after_tool_boundary_until_resume(self) -> None:
        async def scenario(root: Path) -> None:
            storage = velox.Storage(velox.AppPaths(root)); storage.ensure_first_run_files()
            profile = velox.default_endpoint_profile(
                "queue-endpoint", "Queue endpoint", timeout_seconds=60,
                provider=velox.ENDPOINT_PROVIDER_VLLM, max_concurrent_requests=1,
            )
            monitor = velox.LLMTaskMonitor(storage)
            scheduler = velox.EndpointInferenceScheduler(storage, lambda _pid: profile, monitor)
            agent_id = monitor.start(velox.APP_SCOPE_ID, "agent", task_kind="agent")
            chat_id = monitor.start(velox.APP_SCOPE_ID, "chat", task_kind="chat")
            first = await scheduler.acquire(velox.LLMRequest(
                velox.APP_SCOPE_ID, "queue-endpoint", [], monitor_task_id=agent_id, task_kind="agent",
            ))
            monitor.set_phase(agent_id, "tool")
            await first.release()
            chat_lease = await asyncio.wait_for(scheduler.acquire(velox.LLMRequest(
                velox.APP_SCOPE_ID, "queue-endpoint", [], monitor_task_id=chat_id, task_kind="chat",
            )), 1.0)
            monitor.set_phase(agent_id, "paused")
            resumed_waiter = asyncio.create_task(scheduler.acquire(velox.LLMRequest(
                velox.APP_SCOPE_ID, "queue-endpoint", [], monitor_task_id=agent_id, task_kind="agent",
            )))
            await asyncio.sleep(0.03)
            self.assertFalse(resumed_waiter.done())
            await chat_lease.release()
            await asyncio.sleep(0.03)
            self.assertFalse(resumed_waiter.done())
            monitor.set_phase(agent_id, "ready")
            resumed = await asyncio.wait_for(resumed_waiter, 1.0)
            await resumed.release()
            monitor.complete(chat_id); monitor.complete(agent_id)
            await scheduler.close()
        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_personal_assistant_scheduler_failure_is_logged_without_crashing_the_app_tick(self) -> None:
        class FailingScheduler:
            async def tick(self) -> None:
                raise RuntimeError("synthetic PA scheduling failure")

        class LogStorage:
            def __init__(self) -> None:
                self.events: list[tuple[str, dict[str, Any]]] = []

            def append_app_log(self, event: str, data: dict[str, Any]) -> None:
                self.events.append((event, copy.deepcopy(data)))

        async def scenario() -> None:
            app = object.__new__(velox.VeloxApp)
            app.pa_scheduler = FailingScheduler()  # type: ignore[assignment]
            app.storage = LogStorage()  # type: ignore[assignment]
            self.assertIsNone(await app._run_personal_assistant_tick())
            self.assertEqual(app.storage.events[0][0], "personal_assistant.scheduler_failed")
            self.assertIn("synthetic PA scheduling failure", app.storage.events[0][1]["error"])

        asyncio.run(scenario())

    def test_personal_assistant_scheduler_respects_time_active_tasks_interval_and_report_continuity(self) -> None:
        async def scenario(root: Path) -> None:
            _paths, storage, chats = _make_test_chat_stack(root)
            config = storage.load_config()
            pa_cfg = config["agents"]["personal_assistant"]
            pa_cfg.update({"enabled": True, "start_time": "00:00", "check_interval_minutes": 60, "report_days_back": 10})
            storage.write_config(config)
            agents = velox.AgentStore(storage)
            calendar = velox.CalendarStore(storage)

            class FakeRuntime:
                def __init__(self) -> None:
                    self.started: list[str] = []
                def load_recent_pa_reports(self, _day: str, _days: int) -> str:
                    return "# Prior PA report\nKept continuity."
                def start_agent(self, agent_id: str) -> None:
                    self.started.append(agent_id)

            fake = FakeRuntime()
            scheduler = velox.PersonalAssistantScheduler(storage, agents, calendar, fake)  # type: ignore[arg-type]
            local_tz = datetime.now().astimezone().tzinfo or timezone.utc
            now = datetime(2026, 8, 6, 9, 0, 0, tzinfo=local_tz)
            simulated_now_iso = now.astimezone(timezone.utc).isoformat().replace("+00:00", "Z")
            with mock.patch.object(velox, "now_iso", return_value=simulated_now_iso):
                first = await scheduler.tick(now)
            self.assertIsNotNone(first)
            self.assertEqual(first["agent_kind"], velox.AGENT_KIND_PERSONAL_ASSISTANT)
            self.assertIn("Prior PA report", first["context"])
            self.assertEqual(fake.started, [first["agent_id"]])
            self.assertIsNone(await scheduler.tick(now + timedelta(minutes=5)))
            agents.update_agent(first["agent_id"], {"status": "succeeded", "final_message": "Daily report"})
            self.assertIsNone(await scheduler.tick(now + timedelta(minutes=30)))
            second = await scheduler.tick(now + timedelta(minutes=61))
            self.assertIsNotNone(second)
            self.assertNotEqual(first["agent_id"], second["agent_id"])
            self.assertEqual(len(fake.started), 2)
            self.assertTrue(chats.list_chats(velox.APP_SCOPE_ID))

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_personal_assistant_terminal_output_is_saved_as_daily_report_and_loaded_for_later_days(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            paths, storage, chats = _make_test_chat_stack(Path(td))
