    def test_google_drive_is_live_ad_hoc_only_and_never_scheduled_or_vault_indexed(self) -> None:
        class Request:
            def __init__(self, value: Any): self.value = value
            def execute(self) -> Any: return copy.deepcopy(self.value)
        class Files:
            def list(self, **_kwargs: Any) -> Request:
                return Request({"files": [{
                    "id": "doc-1", "name": "Roadmap", "mimeType": "text/plain",
                    "modifiedTime": "2026-08-02T10:00:00Z", "webViewLink": "https://drive.example/doc-1",
                    "capabilities": {"canDownload": True},
                }]})
            def get(self, **_kwargs: Any) -> Request:
                return Request({
                    "id": "doc-1", "name": "Roadmap", "mimeType": "text/plain",
                    "modifiedTime": "2026-08-02T10:00:00Z", "webViewLink": "https://drive.example/doc-1",
                    "capabilities": {"canDownload": True},
                })
            def get_media(self, **_kwargs: Any) -> Request: return Request(b"roadmap body")
            def export_media(self, **_kwargs: Any) -> Request: return Request(b"exported body")
        class Service:
            def files(self) -> Files: return Files()

        async def scenario(root: Path) -> None:
            _paths, storage, _chats = _make_test_chat_stack(root)
            vault = velox.VaultStore(storage)
            credentials = velox.CredentialStore(storage.paths)
            connector = velox.GoogleDriveConnector(storage, vault, credentials)
            connector._service_from_saved_credentials = lambda: (Service(), None, None)  # type: ignore[method-assign]
            with self.assertRaisesRegex(RuntimeError, "ad-hoc only"):
                await connector.sync()
            search = await connector.search_files("roadmap")
            self.assertEqual(search["files"][0]["file_id"], "doc-1")
            self.assertEqual((await connector.get_file("doc-1"))["name"], "Roadmap")
            self.assertEqual((await connector.read_file("doc-1", 100))["content"], "roadmap body")

            class NoopConnector:
                async def sync(self): return {"ok": True}
                async def connect_or_authorize(self): return {"ok": True}
                async def disconnect(self): return {"ok": True}
                async def test_connection(self): return {"ok": True}
                def cancel_sync(self): return None
                def get_status(self): return {}
                def validate_configuration(self): return {"configured": False}
            manager = velox.VaultConnectorManager(storage, connector, NoopConnector(), NoopConnector())  # type: ignore[arg-type]
            self.assertNotIn(velox.GOOGLE_DRIVE_SOURCE_TYPE, manager.next_due)
            with self.assertRaisesRegex(RuntimeError, "ad-hoc only"):
                manager.start(velox.GOOGLE_DRIVE_SOURCE_TYPE, "sync")
            self.assertFalse(any(row["source_type"] == velox.GOOGLE_DRIVE_SOURCE_TYPE for row in vault.list_data_sources()))

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_drive_download_writes_binary_and_workspace_exports_without_indexing_vault(self) -> None:
        class Request:
            def __init__(self, value: Any): self.value = value
            def execute(self) -> Any: return copy.deepcopy(self.value)
        class Files:
            def get(self, **kwargs: Any) -> Request:
                file_id = kwargs.get("fileId")
                if file_id == "doc":
                    return Request({
                        "id": "doc", "name": "Strategy",
                        "mimeType": "application/vnd.google-apps.document",
                        "capabilities": {"canDownload": True},
                    })
                return Request({
                    "id": "pdf", "name": "Brief.pdf", "mimeType": "application/pdf",
                    "capabilities": {"canDownload": True},
                })
            def get_media(self, **_kwargs: Any) -> Request: return Request(b"%PDF-binary")
            def export_media(self, **kwargs: Any) -> Request:
                self.export_mime = kwargs.get("mimeType")
                return Request(b"docx-binary")
        class Service:
            def __init__(self) -> None: self.files_api = Files()
            def files(self) -> Files: return self.files_api

        async def scenario(root: Path) -> None:
            paths, storage, chats = _make_test_chat_stack(root)
            chat = chats.create_chat("Drive download")
            connector = velox.GoogleDriveConnector(storage, velox.VaultStore(storage), velox.CredentialStore(paths))
            service = Service()
            connector._service_from_saved_credentials = lambda: (service, None, None)  # type: ignore[method-assign]
            with self.assertRaisesRegex(ValueError, "file ID is required"):
                await connector.read_file("", 1024)
            with self.assertRaisesRegex(ValueError, "file ID is required"):
                await connector.download_file("", paths.chat_workspace_dir(chat["chat_id"]), 1024)
            exported = await connector.download_file("doc", paths.chat_workspace_dir(chat["chat_id"]), 1024)
            self.assertTrue(exported["path"].endswith("Strategy.docx"))
            self.assertEqual(Path(exported["path"]).read_bytes(), b"docx-binary")
            self.assertEqual(
                service.files_api.export_mime,
                "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
            )
            downloaded = await connector.download_file("pdf", paths.chat_workspace_dir(chat["chat_id"]), 1024)
            self.assertEqual(Path(downloaded["path"]).read_bytes(), b"%PDF-binary")
            tools = velox.ToolRegistry(storage)
            tools.bind_google_drive_connector(connector)
            via_tool = await tools.tool_drive_download(
                velox.ToolContext(velox.APP_SCOPE_ID, chat_id=chat["chat_id"]), {"file_id": "pdf"},
            )
            self.assertTrue(Path(via_tool["path"]).is_file())
            self.assertFalse(any(
                row.get("source_type") == velox.GOOGLE_DRIVE_SOURCE_TYPE
                for row in velox.VaultStore(storage).list_data_sources()
            ))

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

