        rows = velox.vault_source_option_rows([])
        self.assertEqual([row["source_type"] for row in rows], list(velox.VAULT_SOURCE_ORDER))
        self.assertEqual([row["label"].split(" [", 1)[0] for row in rows], ["GCalendar", "GDrive", "GMail", "Slack"])
