    def test_large_layout_reuses_finalized_rows_for_append_only_growth(self) -> None:
        font = _TestDummyFont(20, 8)
        markdown = velox.MarkdownLayoutEngine(font, font, font, font, font)
        cache = velox.LayoutCache(markdown)
        text = self._large_markdown()
        self.assertGreater(len(text), velox.CHAT_LARGE_TEXT_INCREMENTAL_THRESHOLD_CHARS)
        with mock.patch.object(
            markdown,
            "layout_incremental_markdown_line",
            wraps=markdown.layout_incremental_markdown_line,
        ) as layout_line:
            layout = cache.get("large.card", text, 640, incremental_large=True)
            initial_calls = layout_line.call_count
            retained_ids = [id(row) for row in layout.rows[:40]]
            old_rows = len(layout.rows)
            updated = cache.get(
                "large.card",
                text + "\n## Newly appended section\n- first\n- second",
                640,
                incremental_large=True,
            )
            append_calls = layout_line.call_count - initial_calls
        self.assertIs(updated, layout)
        self.assertEqual([id(row) for row in updated.rows[:40]], retained_ids)
        self.assertGreater(len(updated.rows), old_rows)
        # The old implementation parsed every one of the prior 1,800 lines on
        # each publication. The append path may rebuild the prior unfinished
        # tail, then only the three newly completed lines.
        self.assertLessEqual(append_calls, 5)
        self.assertEqual(cache.incremental_rebuilds, 1)
        self.assertEqual(cache.incremental_appends, 1)
        self.assertGreater(updated.revision, 1)

    def test_large_layout_rebuilds_for_non_prefix_edit_or_width_change(self) -> None:
        font = _TestDummyFont(20, 8)
        markdown = velox.MarkdownLayoutEngine(font, font, font, font, font)
        cache = velox.LayoutCache(markdown)
        text = self._large_markdown()
        first = cache.get("large.edit", text, 640, incremental_large=True)
        edited = "Changed first line\n" + text.split("\n", 1)[1]
        second = cache.get("large.edit", edited, 640, incremental_large=True)
        self.assertIsNot(second, first)
        third = cache.get("large.edit", edited + "\nmore", 520, incremental_large=True)
        self.assertIsNot(third, second)
        self.assertEqual(cache.incremental_rebuilds, 3)
        self.assertEqual(cache.incremental_appends, 0)

    def test_newline_free_stream_keeps_only_a_bounded_disposable_tail(self) -> None:
        font = _TestDummyFont(20, 8)
        markdown = velox.MarkdownLayoutEngine(font, font, font, font, font)
        cache = velox.LayoutCache(markdown)
        text = "x" * (velox.CHAT_LARGE_TEXT_CHUNK_MAX_CHARS * 3 + 321)
        layout = cache.get("large.single.line", text, 640, incremental_large=True)
        state = cache.large_cache["large.single.line"]
        self.assertLessEqual(len(text) - state.processed_chars, velox.CHAT_LARGE_TEXT_CHUNK_MAX_CHARS)
        self.assertGreater(state.finalized_row_count, 0)
        first_row = layout.rows[0]

        text += "y" * (velox.CHAT_LARGE_TEXT_CHUNK_MAX_CHARS + 777)
        updated = cache.get("large.single.line", text, 640, incremental_large=True)
        state = cache.large_cache["large.single.line"]
        self.assertIs(updated, layout)
        self.assertIs(updated.rows[0], first_row)
        self.assertLessEqual(len(text) - state.processed_chars, velox.CHAT_LARGE_TEXT_CHUNK_MAX_CHARS)
        self.assertTrue(state.line_continuation)

    def test_large_layout_preserves_common_markdown_and_virtualizes_visible_rows(self) -> None:
        font = _TestDummyFont(20, 8)
        markdown = velox.MarkdownLayoutEngine(font, font, font, font, font)
        cache = velox.LayoutCache(markdown)
        prefix = "\n".join([
            "# Heading",
            "> Quoted context",
            "- list entry",
            "[source](https://example.com/source)",
            "![preview](local/image.png)",
            "```python",
            "print('hello')",
            "```",
        ])
        text = prefix + "\n" + "\n".join(f"filler line {i}" for i in range(3000))
        layout = cache.get("large.markdown", text, 640, incremental_large=True)
        kinds = {row.kind for row in layout.rows}
