    def test_large_section_measurement_builds_one_incremental_layout_not_an_estimate_copy(self) -> None:
        class NullRenderer:
            host = None

            def __getattr__(self, name: str) -> Callable[..., Any]:
                if name.startswith("draw_") or name in {"push_clip", "pop_clip"}:
                    return lambda *_args, **_kwargs: None
                raise AttributeError(name)

