        text = self._large_markdown()
        section = {
            "kind": "assistant",
            "text": text,
            "attachments": [],
            "inline_tools": [],
            "inline_media": [],
            "turn": {"turn_id": "large-measure", "updated_at": "1"},
        }
        blocks = panel._chat_body_blocks_for_section(section)
        estimate = panel._estimate_chat_section_height(
            section, 620, 636, 660, body_blocks=blocks,
        )
        self.assertGreater(estimate, 0)
        self.assertEqual(cache.large_cache, {})
        measured, _key = panel._measure_chat_section_height(
            section, 620, 636, 660, prefer_estimate=False, body_blocks=blocks,
        )
        self.assertGreater(measured, 0)
        self.assertEqual(len(cache.large_cache), 1)
        self.assertTrue(all("estimate" not in key for key in cache.large_cache))

