    def test_virtualized_giant_card_geometry_is_bounded_and_preserves_caps(self) -> None:
        card = velox.Rect(20, 100, 900, 500_000)
        radius = 16

        middle_clip = velox.Rect(0, 200_000, 1000, 900)
        middle_fill, middle_border = velox.virtualized_rounded_rect_geometry(card, middle_clip, radius)
        self.assertEqual(len(middle_fill), 1)
        self.assertLessEqual(len(middle_border), 2)
        self.assertTrue(all(rect.h <= middle_clip.h for rect in middle_fill + middle_border))

        top_clip = velox.Rect(0, 80, 1000, 90)
        top_fill, top_border = velox.virtualized_rounded_rect_geometry(card, top_clip, radius)
        self.assertLessEqual(len(top_fill), radius + 1)
        self.assertLessEqual(len(top_border), radius * 2 + 3)
        self.assertTrue(any(rect.y == card.y and rect.w < card.w for rect in top_fill))

        bottom_clip = velox.Rect(0, card.y + card.h - 70, 1000, 90)
        bottom_fill, bottom_border = velox.virtualized_rounded_rect_geometry(card, bottom_clip, radius)
        self.assertLessEqual(len(bottom_fill), radius + 1)
        self.assertLessEqual(len(bottom_border), radius * 2 + 3)
        self.assertTrue(any(rect.y == card.y + card.h - 1 and rect.w < card.w for rect in bottom_fill))

        for clip, rects in (
            (middle_clip, middle_fill + middle_border),
            (top_clip, top_fill + top_border),
            (bottom_clip, bottom_fill + bottom_border),
        ):
            self.assertTrue(all(velox.rect_intersection(rect, clip) == rect for rect in rects))

    def test_endpoint_delta_accumulator_avoids_per_token_materialization(self) -> None:
        accumulator = velox.AppendOnlyTextAccumulator()
        pieces = [f"token-{index};" for index in range(20_000)]
        for piece in pieces:
            self.assertEqual(accumulator.append_delta(piece), piece)
        self.assertEqual(accumulator.materialization_count, 0)
        self.assertEqual(accumulator.total_chars, sum(map(len, pieces)))
        prior = accumulator.materialize()
        self.assertEqual(accumulator.materialization_count, 1)
        self.assertEqual(prior, "".join(pieces))
        self.assertEqual(accumulator.accept_snapshot(prior + "final"), "final")
        self.assertEqual(accumulator.materialize(), prior + "final")
        self.assertEqual(accumulator.accept_snapshot("conflicting provider rewrite"), "")
        self.assertEqual(accumulator.materialize(), prior + "final")

    def test_coalescing_snapshot_writer_is_nonblocking_and_keeps_latest_payload(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            path = Path(td) / "streaming_turn.json"
            started = threading.Event()
            release = threading.Event()
            writes: list[int] = []

            def slow_write(target: Path, payload: Any) -> None:
                started.set()
                if not release.wait(3.0):
                    raise TimeoutError("test writer was not released")
                writes.append(int(payload["value"]))
                target.write_text(json.dumps(payload), encoding="utf-8")

            writer = velox.CoalescingAtomicJSONWriter(slow_write)
            writer.submit(path, {"value": 1})
            self.assertTrue(started.wait(1.0))
            before = time.perf_counter()
            writer.submit(path, {"value": 2})
            writer.submit(path, {"value": 3})
            self.assertLess(time.perf_counter() - before, 0.1)
            release.set()
            self.assertTrue(writer.flush((path,), timeout=3.0))
            self.assertEqual(writes, [1, 3])
            self.assertEqual(json.loads(path.read_text(encoding="utf-8"))["value"], 3)
            writer.clear_for_tests()

    def test_large_chat_checkpoint_runs_serialization_off_the_update_thread(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            paths, _storage, chats, chat = self._stack(Path(td))
            chat_id = str(chat["chat_id"])
            turn = velox.make_turn(chat_id, "assistant", "", status="streaming")
            chats.append_turn(velox.APP_SCOPE_ID, chat_id, turn, mark_stale=False)
            writer = velox.CHAT_STREAM_SNAPSHOT_WRITER
            writer.clear_for_tests()
            original_write = writer._write_json
            started = threading.Event()
            release = threading.Event()

            def slow_write(target: Path, payload: Any) -> None:
                started.set()
                if not release.wait(3.0):
                    raise TimeoutError("test checkpoint was not released")
                original_write(target, payload)

            writer._write_json = slow_write
            try:
                huge = "x" * 72_000
                before = time.perf_counter()
                self.assertTrue(chats.update_turn(
                    velox.APP_SCOPE_ID, chat_id, str(turn["turn_id"]), {"text": huge},
                    expected_statuses={"streaming"},
                ))
                elapsed = time.perf_counter() - before
                self.assertLess(elapsed, 0.5)
                self.assertTrue(started.wait(1.0))
                self.assertFalse(paths.chat_stream_snapshot_json(chat_id).exists())
                release.set()
                self.assertTrue(writer.flush((paths.chat_stream_snapshot_json(chat_id),), timeout=3.0))
                self.assertTrue(paths.chat_stream_snapshot_json(chat_id).is_file())
            finally:
                release.set()
                writer.flush(timeout=3.0)
                writer._write_json = original_write
                writer.clear_for_tests()

    def test_warm_streaming_update_does_not_poll_filesystem_signatures(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            paths, _storage, chats, chat = self._stack(Path(td))
            chat_id = str(chat["chat_id"])
            snapshot_path = paths.chat_stream_snapshot_json(chat_id)
            turn = velox.make_turn(chat_id, "assistant", "", status="streaming")
            chats.append_turn(velox.APP_SCOPE_ID, chat_id, turn, mark_stale=False)
            chats.load_turns_view(velox.APP_SCOPE_ID, chat_id)
            try:
                with mock.patch.object(
                    chats, "_path_signature", side_effect=AssertionError("hot stream update statted disk"),
                ):
                    self.assertTrue(chats.update_turn(
                        velox.APP_SCOPE_ID, chat_id, str(turn["turn_id"]),
                        {"text": "x" * 16_384},
                        expected_statuses={"streaming"},
                    ))
            finally:
                # This test deliberately schedules the production asynchronous
                # snapshot writer. Drain/cancel it before TemporaryDirectory
                # removal so a late atomic rename cannot recreate the directory
                # while shutil is deleting it.
                velox.CHAT_STREAM_SNAPSHOT_WRITER.cancel(snapshot_path, wait=True)
                velox.CHAT_STREAM_SNAPSHOT_WRITER.clear_for_tests()

    def test_incremental_layout_cache_enforces_shared_giant_text_budget(self) -> None:
        font = _TestDummyFont(20, 8)
