    def test_global_chat_compaction_off_short_circuits_every_chat(self) -> None:
        async def scenario(root: Path) -> None:
            storage = velox.Storage(velox.AppPaths(root))
            storage.ensure_first_run_files()
            config = storage.load_config()
            config["chat"]["auto_compaction_enabled"] = False
            storage.write_config(config)
            runtime = velox.ChatRuntime.__new__(velox.ChatRuntime)
            runtime.storage = storage
            runtime._monitor_task_ids = {}
            messages = [
                {"role": "system", "content": "SYSTEM"},
                {"role": "user", "content": "old " * 10_000},
                {"role": "assistant", "content": "answer " * 10_000},
                {"role": "user", "content": "current task"},
            ]
            original = copy.deepcopy(messages)
            result_messages, placeholder_id, compacted = await runtime._maybe_compact_chat_context(
                velox.APP_SCOPE_ID,
                "chat-global-off",
                velox.DEFAULT_ENDPOINT_PROFILE_ID,
                messages,
                "assistant-placeholder",
                force=False,
            )
            self.assertFalse(compacted)
            self.assertEqual(placeholder_id, "assistant-placeholder")
            self.assertIs(result_messages, messages)
            self.assertEqual(result_messages, original)

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_agent_progress_control_requires_final_100_percent_or_failed_action(self) -> None:
        successful = velox.parse_agent_control_events(
            'Work completed and checked.\n'
            '$$AGENT_PROGRESS: {"message":"All requested output is verified.","percent":100}'
        )
        self.assertEqual(successful[-1]["kind"], "succeeded")
        self.assertTrue(successful[-1]["is_last_action"])

        followed_by_prose = velox.parse_agent_control_events(
            '$$AGENT_PROGRESS: {"message":"Premature success.","percent":100}\n'
            'I am still writing.'
        )
        self.assertEqual(followed_by_prose[-1]["kind"], "succeeded")
        self.assertFalse(followed_by_prose[-1]["is_last_action"])

        failed = velox.parse_agent_control_events(
            '$$AGENT_PROGRESS: {"message":"Required repository access is unavailable.","failed":true}'
        )
        self.assertEqual(failed[-1]["kind"], "failed")
        self.assertTrue(failed[-1]["is_last_action"])

        runtime = object.__new__(velox.AgentRuntime)
        self.assertIs(runtime._terminal_event(successful), successful[-1])
        self.assertIsNone(runtime._terminal_event(followed_by_prose))
        self.assertIs(runtime._terminal_event(failed), failed[-1])
        agents = velox.default_config()["agents"]
        self.assertNotIn("persistence_enabled", agents)
        self.assertNotIn("persistence_max_prompts", agents)
        self.assertNotIn("persistence_enabled", agents["personal_assistant"])

    def test_chat_and_calendar_splitter_geometry_is_responsive_and_persisted(self) -> None:
        self.assertEqual(velox.CHAT_LIST_WIDTH_DEFAULT, 830)
        self.assertEqual(velox.CHAT_LIST_WIDTH_DEFAULT, round(624 * 1.33))
        default_columns = velox.chat_layout_for_rect(velox.Rect(0, 0, 1400, 800))
        self.assertEqual(default_columns.chats.w, (1400 - velox.CHAT_COLUMN_GAP_PX) // 2)
        rect = velox.Rect(10, 20, 1200, 800)
        columns = velox.chat_layout_for_rect(rect, chat_list_width=420)
        self.assertEqual(columns.chats.w, 420)
        self.assertEqual(columns.chats.x, rect.x)
        self.assertEqual(columns.main.x, columns.divider.x + columns.divider.w)
        self.assertEqual(columns.main.x + columns.main.w, rect.x + rect.w)

        narrow = velox.chat_layout_for_rect(velox.Rect(0, 0, 300, 500), chat_list_width=9999)
        self.assertGreaterEqual(narrow.main.w, 120)
        self.assertLessEqual(narrow.chats.w, narrow.main.w)

        short_composer = velox.chat_stack_layout_for_rect(
            rect, header_height=60, composer_height=200,
        )
        tall_composer = velox.chat_stack_layout_for_rect(
            rect, header_height=60, composer_height=300,
        )
        self.assertEqual(tall_composer.composer.h - short_composer.composer.h, 100)
        self.assertEqual(short_composer.output.h - tall_composer.output.h, 100)
        for layout in (short_composer, tall_composer):
            self.assertEqual(layout.header.y, rect.y)
            self.assertEqual(layout.composer.y + layout.composer.h, rect.y + rect.h)
            self.assertEqual(layout.output.y + layout.output.h, layout.divider.y)
            self.assertEqual(layout.divider.y + layout.divider.h, layout.composer.y)

        frame_source = inspect.getsource(velox.VeloxApp.draw_frame)
        calendar_source = inspect.getsource(velox.Panels._draw_calendar_week_chat)
        self.assertIn("handle_chat_column_divider", frame_source)
        self.assertIn('handle_composer_divider("chat"', frame_source)
        self.assertIn('handle_composer_divider("calendar"', calendar_source)
        divider_source = inspect.getsource(velox.Panels.handle_chat_column_divider)
        poll_source = inspect.getsource(velox.SDLHost.poll_events)
        self.assertIn('requested_cursor = "resize_x"', divider_source)
        self.assertIn('inp.mouse_down or inp.mouse_released', divider_source)
        self.assertIn('inp.mouse_release_x', divider_source)
        self.assertIn('input_state.mouse_press_x = event_x', poll_source)
        self.assertIn('input_state.mouse_release_x = event_x', poll_source)
        self.assertIn('requested_cursor = "resize_y"', inspect.getsource(velox.Panels.handle_composer_divider))

        # A long rendered transcript can coalesce down/motion/up into one SDL poll.
        # The divider must use the original press hit and final release position,
        # consume the gesture, and still commit the new width in that one frame.
        panel = velox.Panels.__new__(velox.Panels)
        panel.state = velox.UIState()
        panel.widgets = SimpleNamespace(
            renderer=SimpleNamespace(draw_rect=lambda *_args, **_kwargs: None),
        )
        panel.state.chat_list_width = 624
        divider_rect = velox.Rect(0, 0, 1400, 800)
        divider_layout = velox.chat_layout_for_rect(
            divider_rect, chat_list_width=panel.state.chat_list_width,
        )
        hit = panel._chat_column_divider_hit_rect(divider_layout.divider)
        panel.state.input.mouse_pressed = True
        panel.state.input.mouse_released = True
        panel.state.input.mouse_down = False
        panel.state.input.mouse_press_x = hit.x + hit.w // 2
        panel.state.input.mouse_press_y = hit.y + 40
        panel.state.input.mouse_release_x = 760
        panel.state.input.mouse_release_y = hit.y + 40
        panel.state.input.mouse_x = 760
        panel.state.input.mouse_y = hit.y + 40
        expected_width = velox.chat_layout_for_rect(
            divider_rect,
            chat_list_width=760 - divider_rect.x - velox.CHAT_COLUMN_GAP_PX // 2,
        ).chats.w
        self.assertTrue(panel.handle_chat_column_divider(divider_rect, divider_layout))
        self.assertEqual(panel.state.chat_list_width, expected_width)
        self.assertTrue(panel.state.input.mouse_consumed)
        self.assertFalse(panel.state.chat_column_divider_dragging)

        edge_input = velox.UIInput(
            mouse_press_x=10, mouse_press_y=11,
            mouse_release_x=20, mouse_release_y=21,
        )
        edge_input.begin_frame()
        self.assertEqual(
            (edge_input.mouse_press_x, edge_input.mouse_press_y,
             edge_input.mouse_release_x, edge_input.mouse_release_y),
            (-1, -1, -1, -1),
        )

        with tempfile.TemporaryDirectory() as td:
            storage = velox.Storage(velox.AppPaths(Path(td)))
            storage.ensure_first_run_files()
            state = storage.load_app_state()
            for field in (
                "chat_list_width", "chat_composer_height", "calendar_chat_composer_height",
            ):
                self.assertIn(field, state)
            state["chat_list_width"] = 444
            state["chat_composer_height"] = 222
            state["calendar_chat_composer_height"] = 188
            storage.write_app_state_and_geometry(state)
            loaded = storage.load_app_state()
            self.assertEqual(loaded["chat_list_width"], 444)
            self.assertEqual(loaded["chat_composer_height"], 222)
            self.assertEqual(loaded["calendar_chat_composer_height"], 188)


