    def test_windows_browser_and_visual_studio_detection_use_multiple_reliable_paths(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            program_files = root / "Program Files"
            local_app_data = root / "User" / "AppData" / "Local"
            chrome = program_files / "Google" / "Chrome" / "Application" / "chrome.exe"
            chrome.parent.mkdir(parents=True, exist_ok=True)
            chrome.write_bytes(b"browser")
            # Isolate every external discovery input: the system drive/install roots, App
            # Paths registry, PATH/where.exe/PowerShell output, vswhere discovery, and the
            # Visual Studio registry so the runner's real Chrome/Edge/VS/CMake are never used.
            with (
                mock.patch.object(velox, "_windows_system_drive_root", lambda environment: root),
                mock.patch.object(velox, "_windows_app_path_registry_candidates", lambda names: []),
                mock.patch.object(velox, "_windows_command_output_paths", lambda command, **kwargs: []),
                mock.patch.object(velox, "_find_vswhere_executable", lambda environment: ""),
                mock.patch.object(velox, "_run_vswhere_records", lambda vswhere_path: []),
                mock.patch.object(velox, "_windows_visual_studio_registry_records", lambda: []),
                mock.patch.object(velox, "_cmake_candidate_paths", lambda *args, **kwargs: []),
                mock.patch.object(shutil, "which", return_value=None),
            ):
                detected = velox.detect_chrome_executable(
                    "win32",
                    {"PROGRAMFILES": str(program_files), "localappdata": str(local_app_data)},
                )
                self.assertEqual(detected, os.path.abspath(str(chrome)))

                chrome.unlink()
                edge = local_app_data / "Microsoft" / "Edge" / "Application" / "msedge.exe"
                edge.parent.mkdir(parents=True, exist_ok=True)
                edge.write_bytes(b"edge")
                detected_edge = velox.detect_chrome_executable(
                    "win32",
                    {"PROGRAMFILES": str(program_files), "LOCALAPPDATA": str(local_app_data)},
                )
                self.assertEqual(detected_edge, os.path.abspath(str(edge)))

                vs_base = program_files / "Microsoft Visual Studio"

                def create_install(year: str, edition: str, toolset: str) -> Path:
                    install = vs_base / year / edition
                    (install / "Common7" / "Tools").mkdir(parents=True, exist_ok=True)
                    (install / "Common7" / "Tools" / "VsDevCmd.bat").write_text("", encoding="utf-8")
                    (install / "Common7" / "IDE").mkdir(parents=True, exist_ok=True)
                    (install / "Common7" / "IDE" / "devenv.com").write_text("", encoding="utf-8")
                    auxiliary = install / "VC" / "Auxiliary" / "Build"
                    auxiliary.mkdir(parents=True, exist_ok=True)
                    (auxiliary / "vcvars64.bat").write_text("", encoding="utf-8")
                    (auxiliary / "Microsoft.VCToolsVersion.default.txt").write_text(toolset, encoding="utf-8")
                    bin_dir = install / "VC" / "Tools" / "MSVC" / toolset / "bin" / "Hostx64" / "x64"
                    bin_dir.mkdir(parents=True, exist_ok=True)
                    (bin_dir / "cl.exe").write_text("", encoding="utf-8")
                    (bin_dir / "link.exe").write_text("", encoding="utf-8")
                    msbuild = install / "MSBuild" / "Current" / "Bin" / "amd64"
                    msbuild.mkdir(parents=True, exist_ok=True)
                    (msbuild / "MSBuild.exe").write_text("", encoding="utf-8")
                    return install

                install_2019 = create_install("2019", "Community", "14.29.30133")
                install_2022 = create_install("2022", "Community", "14.44.35207")
                self.assertTrue(install_2019.is_dir())
                detected_vs = velox.detect_visual_studio_environment(
                    "win32", {"PROGRAMFILES": str(program_files)}
                )
                self.assertEqual(detected_vs["installationPath"], os.path.abspath(str(install_2022)))
                self.assertTrue(detected_vs["cl"].endswith("cl.exe"))
                self.assertTrue(detected_vs["link"].endswith("link.exe"))
                self.assertTrue(detected_vs["msbuild"].endswith("MSBuild.exe"))
                self.assertTrue(detected_vs["vsDevCmd"].endswith("VsDevCmd.bat"))
                self.assertEqual(detected_vs["toolsetVersion"], "14.44.35207")

    def test_image_tool_execution_uses_separate_context_on_current_endpoint(self) -> None:
        async def scenario(root: Path) -> None:
            paths = velox.AppPaths(root)
            storage = velox.Storage(paths)
            storage.ensure_first_run_files()
            chats = velox.ChatStore(storage)
            chat = chats.create_chat("Vision routing")
            chat_id = str(chat["chat_id"])
            image_path = paths.chat_workspace_dir(chat_id) / "pixel.png"
            image_path.parent.mkdir(parents=True, exist_ok=True)
            image_path.write_bytes(base64.b64decode(
                "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAusB9Y9ZV7sAAAAASUVORK5CYII="
            ))

            class FakeLLM:
                def __init__(self) -> None:
                    self.requests: list[LLMRequest] = []

                @staticmethod
                def resolve_endpoint(profile_id: str) -> dict[str, Any]:
                    if profile_id == velox.DEFAULT_ENDPOINT_PROFILE_ID:
                        return {"profile_id": profile_id, "profile_label": "Image", "vision": "enabled", "image_analysis_context": "separate", "max_output_tokens": 16384}
                    return {"profile_id": profile_id, "profile_label": "Vision caller", "vision": "enabled", "image_analysis_context": "separate"}

                async def chat_completions_stream(self, request: LLMRequest):
                    self.requests.append(request)
                    yield velox.LLMChunk(text="<think>checked pixel</think>pixel verified")
                    yield velox.LLMChunk(done=True, finish_reason="stop")

            fake = FakeLLM()
            tools = velox.ImageTools(storage, fake)
            vision_ctx = velox.ToolContext(
                scope_id=velox.APP_SCOPE_ID,
                chat_id=chat_id,
                endpoint_profile_id=velox.DEFAULT_ENDPOINT_PROFILE_ID,
            )
            result = await tools.analyze(
                vision_ctx,
                {"path": str(image_path), "prompt": "Describe and transcribe this image."},
            )
            self.assertEqual(result["analysis"], "pixel verified")
            self.assertEqual(len(fake.requests), 1)
            request = fake.requests[0]
            self.assertEqual(request.messages[0]["content"], velox.IMAGE_ANALYSIS_ENDPOINT_SYSTEM_PROMPT)
            self.assertIsInstance(request.messages[1]["content"], list)
            self.assertTrue(any(
                isinstance(part, dict) and part.get("type") == "image_url"
                for part in request.messages[1]["content"]
            ))
            self.assertFalse(request.native_tools)

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_tool_rows_show_live_and_terminal_execution_seconds(self) -> None:
        current = datetime(2026, 8, 5, 7, 0, 3, 600000, tzinfo=timezone.utc)
        running = {
            "status": "running",
            "ok": None,
            "started_at": "2026-08-05T07:00:00Z",
            "elapsed_seconds": 0.0,
        }
        self.assertAlmostEqual(
            velox.tool_call_elapsed_seconds(running, current_time=current), 3.6, places=6,
        )
        current_epoch = current.timestamp()
        self.assertEqual(velox._comparable_datetime(current_epoch), current)
        with self.assertRaises(TypeError):
            velox._comparable_datetime(object())
        self.assertAlmostEqual(
            velox.tool_call_elapsed_seconds(running, current_time=current_epoch), 3.6, places=6,
        )
        # This exact numeric-epoch path previously raised AttributeError from the
        # frame-render statistics tooltip and made the crash recur on restart.
        aggregate = velox.chat_thread_runtime_stats([{
            "role": "assistant", "status": "streaming",
            "created_at": "2026-08-05T07:00:00Z",
            "stats": {"started_at": "2026-08-05T07:00:00Z"},
            "tool_calls": [running],
        }], current_time=current_epoch)
        self.assertAlmostEqual(aggregate["tool_runtime_seconds"], 3.6, places=6)
        malformed = dict(running, started_at=object())
        self.assertEqual(velox.tool_call_elapsed_seconds(malformed, current_time=current_epoch), 0.0)
        self.assertEqual(velox.chat_thread_runtime_stats([], current_time="not-a-time")["total_runtime_seconds"], 0.0)
        terminal = {
            "status": "complete",
            "ok": True,
            "started_at": "2026-08-05T07:00:00Z",
            "ended_at": "2026-08-05T07:00:02.345Z",
            "elapsed_seconds": 2.345,
        }
        much_later = datetime(2026, 8, 6, tzinfo=timezone.utc)
        self.assertEqual(velox.tool_call_elapsed_seconds(terminal, current_time=much_later), 2.345)

        panel = object.__new__(velox.Panels)
        self.assertEqual(panel._tool_elapsed_label(terminal), "2.3 s")
        draw_source = inspect.getsource(velox.Panels._draw_inline_tool_row)
        self.assertIn("elapsed_label = self._tool_elapsed_label(tool_call)", draw_source)
        self.assertIn("accent", draw_source)
        self.assertIn('align="right"', draw_source)
        self.assertIn("Tool execution time", draw_source)

    def test_effective_prompt_capacity_and_vllm_overflow_detection(self) -> None:
        config = velox.default_config()
        profile = velox.endpoint_profile_ref(
            config, velox.DEFAULT_DEEPSEEK_V4_FLASH_0731_ENDPOINT_PROFILE_ID,
        )
        self.assertEqual(profile["context_window_tokens"], 524_288)
        self.assertEqual(profile["max_output_tokens"], 131_072)
        self.assertEqual(velox.endpoint_prompt_capacity_tokens(profile), 393_216)
        self.assertEqual(
            velox.endpoint_prompt_capacity_tokens_from_config(
                config, velox.DEFAULT_DEEPSEEK_V4_FLASH_0731_ENDPOINT_PROFILE_ID,
            ),
            393_216,
        )
        exhibit = (
            "HTTP 400 Bad Request\n"
            "This model's maximum context length is 524288 tokens. However, you requested "
            "393216 output tokens and your prompt contains at least 131073 input tokens, "
            "for a total of at least 524289 tokens. Please reduce the length of the input "
            "prompt or the number of requested output tokens. "
            "(parameter=input_tokens, value=131073)"
        )
        details = velox.llm_context_overflow_details(exhibit)
        self.assertIsNotNone(details)
        self.assertEqual(details["context_window_tokens"], 524_288)
        self.assertEqual(details["max_output_tokens"], 393_216)
        self.assertEqual(details["input_tokens"], 131_073)
        self.assertEqual(details["total_tokens"], 524_289)
        self.assertIsNone(velox.llm_context_overflow_details("HTTP 400 Bad Request: invalid temperature"))

        chat_compaction_source = inspect.getsource(velox.ChatRuntime._maybe_compact_chat_context)
        agent_compaction_source = inspect.getsource(velox.AgentRuntime._maybe_compact_agent_context)
        self.assertIn("prepared_request_capacity_snapshot", chat_compaction_source)
        self.assertIn("raw_prompt_capacity_tokens", chat_compaction_source)
        self.assertIn("context_safety_tokens", chat_compaction_source)
        self.assertIn("prepared_request_capacity_snapshot", agent_compaction_source)
        self.assertIn("reported_exceeds_capacity", agent_compaction_source)
        self.assertIn("force=True", inspect.getsource(velox.ChatRuntime._run_assistant_loop))
        self.assertIn("force=True", inspect.getsource(velox.AgentRuntime._request_agent_completion))

    def test_structural_token_estimate_and_provider_overflow_calibration(self) -> None:
        structured = (
            '{"path":"C:/studio/tool.py","arguments":[1,2,3],'
            '"result":{"ok":true,"rows":["a","b","c"]}}\n'
        ) * 12_000
        old_four_chars_per_token = (len(structured) + 3) // 4
        estimated = velox._estimated_text_tokens(structured)
        self.assertGreaterEqual(estimated, old_four_chars_per_token)
        self.assertLess(estimated, int(old_four_chars_per_token * 1.10))

        messages = [{"role": "user", "content": structured}]
        tools = [{
            "type": "function",
            "function": {
                "name": "write_record",
                "description": "Write one exact structured record.",
                "parameters": {
                    "type": "object",
                    "properties": {"payload": {"type": "object"}},
                    "required": ["payload"],
                    "additionalProperties": False,
                },
            },
        }]
        message_tokens = velox.estimate_request_messages_tokens(messages)
        tool_tokens = velox.estimate_native_tool_schema_tokens(tools)
        self.assertGreater(message_tokens, old_four_chars_per_token)
        self.assertGreater(tool_tokens, 16)

        body = '{\n"error": {\n"message": "This model\'s maximum context length is 1048576 tokens. However, you requested 262144 output tokens and your prompt contains at least 786433 input tokens, for a total of at least 1048577 tokens. Please reduce the length of the input prompt or the number of requested output tokens. (parameter=input_tokens, value=786433)",\n"type": "BadRequestError",\n"param": "input_tokens",\n"code": 400\n}\n}'
        error = velox.LLMEndpointError(
            "LLM endpoint request failed.", status_code=400, response_body=body,
        )
        details = velox.llm_context_overflow_details(error)
        self.assertIsNotNone(details)
        assert details is not None
        self.assertEqual(details["context_window_tokens"], 1_048_576)
        self.assertEqual(details["max_output_tokens"], 262_144)
        self.assertEqual(details["input_tokens"], 786_433)
        recovery = velox.provider_overflow_recovery_capacity(
            {"context_window_tokens": 1_000_000, "max_output_tokens": 262_144},
            details,
            estimated_complete_tokens=700_000,
            message_count=400,
            native_tool_count=80,
        )
        self.assertEqual(recovery["effective_context_window_tokens"], 1_000_000)
        self.assertEqual(recovery["provider_reported_input_tokens"], 786_433)
        self.assertGreater(recovery["measured_estimate_ratio"], 1.12)
        self.assertGreater(recovery["estimate_multiplier"], recovery["measured_estimate_ratio"])
        self.assertLess(
            recovery["estimated_prompt_capacity_tokens"],
            recovery["provider_safe_prompt_tokens"],
        )
        second_recovery = velox.provider_overflow_recovery_capacity(
            {"context_window_tokens": 1_000_000, "max_output_tokens": 262_144},
            details,
            estimated_complete_tokens=700_000,
            message_count=400,
            native_tool_count=80,
            recovery_attempt=2,
        )
        self.assertGreater(second_recovery["estimate_margin"], recovery["estimate_margin"])
        self.assertLess(
            second_recovery["estimated_prompt_capacity_tokens"],
            recovery["estimated_prompt_capacity_tokens"],
        )
        self.assertIsNone(velox.llm_context_overflow_details(
            velox.LLMEndpointError("HTTP 400 Bad Request: invalid temperature", status_code=400),
        ))

    def test_context_overflow_forces_compaction_and_reuses_parent_task_slot(self) -> None:
        overflow_error = (
            "LLM endpoint request failed. HTTP 400 Bad Request. "
            "This model's maximum context length is 524288 tokens. However, you requested "
            "262144 output tokens and your prompt contains at least 262145 input tokens, "
            "for a total of at least 524289 tokens. Please reduce the length of the input "
            "prompt or the number of requested output tokens. "
            "(parameter=input_tokens, value=262145)"
        )

        class OverflowThenCompactionThenAnswer:
            def __init__(self) -> None:
                self.calls = 0
                self.requests: list[LLMRequest] = []

            @staticmethod
            def resolve_endpoint(_profile_id: str) -> dict[str, Any]:
                return {
                    "context_window_tokens": 524_288,
                    "max_output_tokens": 262_144,
                    "vision": "disabled",
                }

            async def chat_completions_stream(self, request: LLMRequest):
                self.calls += 1
                self.requests.append(copy.deepcopy(request))
                if self.calls == 1:
                    yield velox.LLMChunk(error=overflow_error)
                    return
                if self.calls == 2:
                    self_assert = request.max_output_tokens is not None
                    if not self_assert:
                        raise AssertionError("compaction request must set a bounded output budget")
                    yield velox.LLMChunk(text=(
                        "Operational memory: preserve the user's requested implementation, exact file paths, "
                        "the completed tool results, current constraints, and the remaining verification work. "
                        "The newest user request remains authoritative. " * 8
                    ))
                    yield velox.LLMChunk(
                        done=True,
                        finish_reason="stop",
                        usage={"prompt_tokens": 4000, "completion_tokens": 320},
                    )
                    return
                if self.calls == 3:
                    yield velox.LLMChunk(text="Recovered after forced compaction and completed the response.")
                    yield velox.LLMChunk(
                        done=True,
                        finish_reason="stop",
                        usage={"prompt_tokens": 5000, "completion_tokens": 12},
                    )
                    return
                raise AssertionError("unexpected extra context-overflow recovery request")

        async def scenario(root: Path) -> None:
            paths = velox.AppPaths(root)
            storage = velox.Storage(paths)
            storage.ensure_first_run_files()
            chats = velox.ChatStore(storage)
            chat = chats.create_chat("Overflow recovery")
            chat_id = str(chat["chat_id"])
            config = storage.load_config()
            config["chat"]["auto_compaction_enabled"] = False
            storage.write_config(config)
            for index in range(12):
                chats.append_turn(
                    velox.APP_SCOPE_ID,
                    chat_id,
                    velox.make_turn(chat_id, "user", f"Historical request {index}: " + "u" * 300),
                )
                chats.append_turn(
                    velox.APP_SCOPE_ID,
                    chat_id,
                    velox.make_turn(chat_id, "assistant", f"Historical answer {index}: " + "a" * 300),
                )
            user_text = (
                "Finish the current task after recovering from provider context overflow. "
                "Preserve this literal user text exactly: <think>not assistant reasoning</think> "
                '{"required":"byte-for-byte user request"}'
            )
            chats.append_turn(velox.APP_SCOPE_ID, chat_id, velox.make_turn(chat_id, "user", user_text))
            assistant = velox.make_turn(
                chat_id,
                "assistant",
                "",
                endpoint_profile_id=velox.DEFAULT_DEEPSEEK_V4_FLASH_0731_ENDPOINT_PROFILE_ID,
                endpoint_label="Deepseek",
                status="streaming",
            )
            chats.append_turn(velox.APP_SCOPE_ID, chat_id, assistant, mark_stale=False)
            fake = OverflowThenCompactionThenAnswer()
            runtime = velox.ChatRuntime(
                storage, chats, velox.ContextAssembler(paths), fake, velox.ToolRegistry(storage),
            )
            runtime._monitor_task_ids[chat_id] = "chat-parent-overflow-task"
            await runtime._run_assistant_loop(
                velox.APP_SCOPE_ID,
                chat_id,
                assistant["turn_id"],
                velox.DEFAULT_DEEPSEEK_V4_FLASH_0731_ENDPOINT_PROFILE_ID,
                user_text,
                "vLLM overflow recovery",
            )
            turns = chats.load_turns(velox.APP_SCOPE_ID, chat_id)
            self.assertEqual(fake.calls, 3)
            self.assertEqual(
                fake.requests[1].monitor_task_id, "chat-parent-overflow-task",
            )
            initial_user = next(
                message for message in fake.requests[0].messages
                if message.get("role") == "user" and message.get("content") == user_text
            )
            retry_user = next(
                message for message in fake.requests[2].messages
                if message.get("role") == "user" and message.get("content") == user_text
            )
            self.assertEqual(retry_user, initial_user)
            self.assertEqual(str(retry_user.get("content") or ""), user_text)
            compactions = [
                turn for turn in turns
                if str((turn.get("compaction_meta") or {}).get("kind") or "")
                == "chat_context_compaction"
            ]
            self.assertEqual(len(compactions), 1)
            self.assertTrue(compactions[0]["compaction_meta"]["forced"])
            compaction_meta = compactions[0]["compaction_meta"]
            self.assertEqual(compaction_meta["raw_prompt_capacity_tokens"], 262_144)
            self.assertGreater(compaction_meta["context_safety_tokens"], 0)
            self.assertTrue(compaction_meta["provider_overflow_recovery"])
            self.assertEqual(compaction_meta["provider_reported_input_tokens"], 262_145)
            self.assertLessEqual(
                compaction_meta["prompt_capacity_tokens"],
                compaction_meta["raw_prompt_capacity_tokens"]
                - compaction_meta["context_safety_tokens"],
            )
            self.assertGreater(compaction_meta["estimate_multiplier"], 1.0)
            final = turns[-1]
            self.assertEqual(final["status"], "complete")
            self.assertIn("Recovered after forced compaction", final["text"])
            log_text = "\n".join(
                str(row.get("log msg") or "") for row in velox.iter_jsonl(paths.log_jsonl_path)
            )
            self.assertIn("chat.context_overflow_recovered", log_text)
            runtime.cancel_all()

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_agent_overflow_compacts_and_preserves_latest_user_exactly(self) -> None:
        overflow_body = (
            "This model's maximum context length is 524288 tokens. However, you requested "
            "262144 output tokens and your prompt contains at least 262145 input tokens, "
            "for a total of at least 524289 tokens. Please reduce the length of the input "
            "prompt or the number of requested output tokens. "
            "(parameter=input_tokens, value=262145)"
        )

        class AgentOverflowThenSummaryThenAnswer:
            def __init__(self) -> None:
                self.calls = 0
                self.requests: list[LLMRequest] = []

            @staticmethod
            def resolve_endpoint(_profile_id: str) -> dict[str, Any]:
                return {
                    "context_window_tokens": 524_288,
                    "max_output_tokens": 262_144,
                    "vision": "disabled",
                }

            async def chat_completions_once_full(self, request: LLMRequest) -> dict[str, Any]:
                self.calls += 1
                self.requests.append(copy.deepcopy(request))
                if self.calls == 1:
                    raise velox.LLMEndpointError(
                        "LLM endpoint request failed.",
                        status_code=400,
                        response_body=overflow_body,
                    )
                if self.calls == 2:
                    return {
                        "text": (
                            "Operational memory preserves exact requirements, decisions, paths, completed "
                            "checks, failures, remaining actions, and the newest user request. " * 12
                        ),
                        "usage": {"prompt_tokens": 4000, "completion_tokens": 360},
                        "finish_reason": "stop",
                        "stop_reason": "",
                        "tool_calls": [],
                        "raw": {},
                    }
                if self.calls == 3:
                    return {
                        "text": "Agent recovered after forced overflow compaction.",
                        "usage": {"prompt_tokens": 5000, "completion_tokens": 10},
                        "finish_reason": "stop",
                        "stop_reason": "",
                        "tool_calls": [],
                        "raw": {},
                    }
                raise AssertionError("unexpected extra Agent context-overflow recovery request")

        async def scenario(root: Path) -> None:
            storage = velox.Storage(velox.AppPaths(root))
            storage.ensure_first_run_files()
            chats = velox.ChatStore(storage)
            chat_id = str(chats.create_chat("Agent overflow source")["chat_id"])
            agents = velox.AgentStore(storage)
            task_text = "Complete the exact delegated task."
            agent = agents.create_agent(
                chat_id,
                task_text,
                endpoint_profile_id=velox.DEFAULT_DEEPSEEK_V4_FLASH_0731_ENDPOINT_PROFILE_ID,
                context_window_tokens=524_288,
                max_output_tokens=262_144,
                auto_compaction_enabled=False,
                tool_features={key: False for key in velox.CHAT_TOOL_FEATURE_KEYS},
            )
            agent_id = str(agent["agent_id"])
            system_text = "SYSTEM AGENT CONTRACT"
            agents.append_event(agent_id, "started", {
                "system_prompt": system_text,
                "user_prompt": task_text,
            })
            latest_user_text = (
                "Continue and preserve this literal input exactly: "
                "<think>user-authored literal tag</think> "
                '{"agent_requirement":"unchanged"}'
            )
            messages: list[dict[str, Any]] = [
                {"role": "system", "content": system_text},
                {"role": "user", "content": task_text},
            ]
            for index in range(14):
                messages.append({
                    "role": "assistant",
                    "content": f"Historical agent output {index}: " + ("a" * 700),
                })
                messages.append({
                    "role": "user",
                    "content": f"Historical agent observation {index}: " + ("u" * 700),
                })
            latest_user_object = {"role": "user", "content": latest_user_text}
            messages.append(copy.deepcopy(latest_user_object))

            fake = AgentOverflowThenSummaryThenAnswer()
            runtime = velox.AgentRuntime(
                storage,
                agents,
                chats,
                velox.ContextAssembler(storage.paths),
                fake,
                velox.ToolRegistry(storage),
            )
            response = await runtime._request_agent_completion(
                agent_id,
                velox.DEFAULT_DEEPSEEK_V4_FLASH_0731_ENDPOINT_PROFILE_ID,
                messages,
                iteration=1,
                request_id="agent-parent-overflow-task",
            )
            self.assertEqual(fake.calls, 3)
            self.assertEqual(
                fake.requests[1].monitor_task_id, "agent-parent-overflow-task",
            )
            self.assertIn("Agent recovered", response["text"])
            initial_user = next(
                message for message in fake.requests[0].messages
                if message.get("content") == latest_user_text
            )
            retry_user = next(
                message for message in fake.requests[2].messages
                if message.get("content") == latest_user_text
            )
            self.assertEqual(initial_user, latest_user_object)
            self.assertEqual(retry_user, latest_user_object)
            self.assertEqual(messages[-1], latest_user_object)

            transcript = agents.load_transcript(agent_id)
            compaction = next(
                event for event in transcript if event.get("kind") == "context_compacted"
            )
            self.assertTrue(compaction["data"]["provider_overflow_recovery"])
            self.assertEqual(
                compaction["data"]["provider_reported_input_tokens"], 262_145,
            )
            recoveries = [
                event for event in transcript
                if event.get("kind") == "context_overflow_recovered"
            ]
            self.assertEqual(len(recoveries), 1)
            await runtime.shutdown()

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_initial_chat_input_is_never_compacted_and_retries_with_smaller_output(self) -> None:
        class TwoOverflowsThenAnswer:
            def __init__(self) -> None:
                self.requests: list[LLMRequest] = []

            @staticmethod
            def resolve_endpoint(_profile_id: str) -> dict[str, Any]:
                return {
                    "provider": velox.ENDPOINT_PROVIDER_VLLM,
                    "context_window_tokens": 500_000,
                    "max_output_tokens": 262_144,
                    "vision": "disabled",
                }

            async def chat_completions_stream(self, request: LLMRequest):
                self.requests.append(copy.deepcopy(request))
                call_number = len(self.requests)
                if call_number <= 2:
                    requested_output = int(request.max_output_tokens or 262_144)
                    reported_input = (
                        395_477
                        if call_number == 1
                        else 500_000 - requested_output + 1
                    )
                    total = reported_input + requested_output
                    yield velox.LLMChunk(
                        error=(
                            "LLM endpoint request failed. HTTP 400 Bad Request. "
                            "This model's maximum context length is 500000 tokens. "
                            f"However, you requested {requested_output} output tokens and your "
                            f"prompt contains at least {reported_input} input tokens, for a total "
                            f"of at least {total} tokens. Please reduce the length of the input "
                            "prompt or the number of requested output tokens. "
                            f"(parameter=input_tokens, value={reported_input})"
                        ),
                        done=True,
                    )
                    return
                if call_number == 3:
                    yield velox.LLMChunk(
                        text="Completed with the initial user message preserved exactly.",
                        usage={"prompt_tokens": 396_000, "completion_tokens": 12},
                        done=True,
                        finish_reason="stop",
                    )
                    return
                raise AssertionError("automatic context recovery exceeded the bounded test sequence")

        async def scenario(root: Path) -> None:
            paths = velox.AppPaths(root)
            storage = velox.Storage(paths)
            storage.ensure_first_run_files()
            chats = velox.ChatStore(storage)
            chat_id = str(chats.create_chat("Initial exact overflow recovery")["chat_id"])
            config = storage.load_config()
            config["chat"]["auto_compaction_enabled"] = False
            storage.write_config(config)
            user_text = (
                "Preserve this initial request byte-for-byte, including literal markup "
                "<think>user text, not reasoning</think> and JSON "
                '{"deliverable":"unchanged","lines":["one","two"]}'
            )
            chats.append_turn(velox.APP_SCOPE_ID, chat_id, velox.make_turn(chat_id, "user", user_text))
            assistant = velox.make_turn(
                chat_id, "assistant", "",
                endpoint_profile_id=velox.DEFAULT_DEEPSEEK_V4_FLASH_0731_ENDPOINT_PROFILE_ID,
                endpoint_label="DeepSeek", status="streaming",
            )
            chats.append_turn(velox.APP_SCOPE_ID, chat_id, assistant, mark_stale=False)
            fake = TwoOverflowsThenAnswer()
            runtime = velox.ChatRuntime(
                storage, chats, velox.ContextAssembler(paths), fake, velox.ToolRegistry(storage),
            )
            await runtime._run_assistant_loop(
                velox.APP_SCOPE_ID, chat_id, str(assistant["turn_id"]),
                velox.DEFAULT_DEEPSEEK_V4_FLASH_0731_ENDPOINT_PROFILE_ID,
                user_text, "Initial exact-input overflow recovery",
            )
            self.assertEqual(len(fake.requests), 3)
            self.assertIsNone(fake.requests[0].max_output_tokens)
            self.assertIsNotNone(fake.requests[1].max_output_tokens)
            self.assertIsNotNone(fake.requests[2].max_output_tokens)
            self.assertLess(
                int(fake.requests[1].max_output_tokens or 0), 262_144,
            )
            self.assertLess(
                int(fake.requests[2].max_output_tokens or 0),
                int(fake.requests[1].max_output_tokens or 0),
            )
            exact_messages = [
                message for request in fake.requests for message in request.messages
                if message.get("role") == "user" and message.get("content") == user_text
            ]
            self.assertEqual(len(exact_messages), 3)
            self.assertTrue(all(message == exact_messages[0] for message in exact_messages))
            turns = chats.load_turns(velox.APP_SCOPE_ID, chat_id)
            self.assertFalse(any(
                str((turn.get("compaction_meta") or {}).get("kind") or "")
                == "chat_context_compaction"
                for turn in turns
            ))
            self.assertEqual(turns[-1]["status"], "complete")
            self.assertIn("preserved exactly", turns[-1]["text"])
            log_text = "\n".join(
                str(row.get("log msg") or "") for row in velox.iter_jsonl(paths.log_jsonl_path)
            )
            self.assertGreaterEqual(log_text.count("chat.context_overflow_output_reduced"), 2)
            runtime.cancel_all()

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_nested_chat_compaction_reuses_retained_scheduler_slot_without_deadlock(self) -> None:
        overflow_error = (
            "LLM endpoint request failed. HTTP 400 Bad Request. "
            "This model's maximum context length is 524288 tokens. However, you requested "
            "262144 output tokens and your prompt contains at least 262145 input tokens, "
            "for a total of at least 524289 tokens. Please reduce the length of the input "
            "prompt or the number of requested output tokens. "
            "(parameter=input_tokens, value=262145)"
        )

        async def scenario(root: Path) -> None:
            paths = velox.AppPaths(root)
            storage = velox.Storage(paths)
            storage.ensure_first_run_files()
            monitor = velox.LLMTaskMonitor(storage)
            client = velox.LLMClient(storage)
            endpoint_id = velox.DEFAULT_DEEPSEEK_V4_FLASH_0731_ENDPOINT_PROFILE_ID
            profile = velox.endpoint_profile_for_id(storage.load_config(), endpoint_id)
            profile.update({
                "provider": velox.ENDPOINT_PROVIDER_VLLM,
                "context_window_tokens": 524_288,
                "max_output_tokens": 262_144,
                "max_concurrent_requests": 1,
            })
            client.resolve_endpoint = lambda _profile_id: copy.deepcopy(profile)  # type: ignore[method-assign]
            scheduler = velox.EndpointInferenceScheduler(
                storage, client.resolve_endpoint, monitor,
            )
            client.bind_request_scheduler(scheduler, monitor)
            requests: list[LLMRequest] = []

            async def fake_stream(request: LLMRequest):
                requests.append(copy.deepcopy(request))
                call_number = len(requests)
                if call_number == 1:
                    yield velox.LLMChunk(error=overflow_error, done=True)
                    return
                if request.task_title == "Chat context compaction":
                    yield velox.LLMChunk(text=(
                        "Operational memory preserves exact requirements, paths, decisions, completed "
                        "checks, failures, and remaining work. The newest user request is unchanged. " * 10
                    ))
                    yield velox.LLMChunk(
                        done=True, finish_reason="stop",
                        usage={"prompt_tokens": 4_000, "completion_tokens": 320},
                    )
                    return
                yield velox.LLMChunk(
                    text="Recovered without queueing the nested compactor behind its own parent Task.",
                    done=True, finish_reason="stop",
                    usage={"prompt_tokens": 5_000, "completion_tokens": 14},
                )

            client._chat_completions_stream_unqueued = fake_stream  # type: ignore[method-assign]
            chats = velox.ChatStore(storage)
            chat_id = str(chats.create_chat("Compaction scheduler reuse")["chat_id"])
            config = storage.load_config()
            config["chat"]["auto_compaction_enabled"] = False
            storage.write_config(config)
            for index in range(12):
                chats.append_turn(
                    velox.APP_SCOPE_ID, chat_id,
                    velox.make_turn(chat_id, "user", f"Historical request {index}: " + "u" * 600),
                )
                chats.append_turn(
                    velox.APP_SCOPE_ID, chat_id,
                    velox.make_turn(chat_id, "assistant", f"Historical response {index}: " + "a" * 600),
                )
            user_text = "Complete the current request after safe context recovery."
            chats.append_turn(velox.APP_SCOPE_ID, chat_id, velox.make_turn(chat_id, "user", user_text))
            assistant = velox.make_turn(
                chat_id, "assistant", "", endpoint_profile_id=endpoint_id,
                endpoint_label="DeepSeek", status="streaming",
            )
            chats.append_turn(velox.APP_SCOPE_ID, chat_id, assistant, mark_stale=False)
            runtime = velox.ChatRuntime(
                storage, chats, velox.ContextAssembler(paths), client, velox.ToolRegistry(storage), monitor,
            )
            await asyncio.wait_for(
                runtime._run_assistant_loop(
                    velox.APP_SCOPE_ID, chat_id, str(assistant["turn_id"]), endpoint_id,
                    user_text, "Nested compaction scheduler test",
                ),
                timeout=2.0,
            )
            self.assertEqual(len(requests), 3)
            parent_task_id = requests[0].monitor_task_id
            self.assertTrue(parent_task_id)
            self.assertEqual(requests[1].task_title, "Chat context compaction")
            self.assertEqual(requests[1].monitor_task_id, parent_task_id)
            self.assertEqual(requests[2].monitor_task_id, parent_task_id)
            self.assertEqual(chats.load_turns(velox.APP_SCOPE_ID, chat_id)[-1]["status"], "complete")
            snapshot = scheduler.snapshot().get(endpoint_id, {})
            self.assertEqual(snapshot.get("queued", []), [])
            self.assertEqual(snapshot.get("active", []), [])
            runtime.cancel_all()
            await scheduler.close()

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_thinking_and_ai_stats_are_separate_and_header_metadata_is_tooltip_only(self) -> None:
        runtime = object.__new__(velox.ChatRuntime)
        text = "<think>considering alternatives carefully</think>The checked answer is complete."
        usage = {
            "prompt_tokens": 1000,
            "completion_tokens": 300,
            "prompt_seconds": 2.0,
            "generation_seconds": 4.0,
            "completion_tokens_details": {"reasoning_tokens": 120},
            "_stream_output_chars": len(text),
            "_inference_completed_at": 106.0,
            "_model_rounds": 1,
            "_section_timing": [
                {"kind": "thinking", "first_at": 102.0, "last_at": 104.0, "end_at": 104.0, "chars": 34},
                {"kind": "assistant", "first_at": 104.0, "last_at": 106.0, "end_at": 106.0, "chars": 31},
            ],
        }
        with mock.patch.object(time, "time", return_value=108.0):
            stats = runtime._make_stats(
                100.0,
                102.0,
                text,
                [{"elapsed_seconds": 1.5, "status": "complete", "ok": True}],
                usage,
            )
        rows = {row["kind"]: row for row in stats["section_stats"]}
        self.assertEqual(set(rows), {"thinking", "assistant"})
        self.assertEqual(rows["thinking"]["output_tokens"], 120)
        self.assertEqual(rows["assistant"]["output_tokens"], 180)
        self.assertAlmostEqual(rows["thinking"]["generation_seconds"], 2.0, places=3)
        self.assertAlmostEqual(rows["assistant"]["generation_seconds"], 2.0, places=3)
        self.assertEqual(rows["thinking"]["tool_call_count"], 0)
        self.assertEqual(rows["assistant"]["tool_call_count"], 1)
        self.assertAlmostEqual(rows["assistant"]["tool_seconds"], 1.5, places=3)

        panel = object.__new__(velox.Panels)
        turn = {
            "created_at": "2026-08-05T07:07:00Z",
            "status": "complete",
            "stats": stats,
        }
        thinking_tip = panel._chat_section_stats_tooltip({"kind": "thinking", "turn": turn})
        assistant_tip = panel._chat_section_stats_tooltip({"kind": "assistant", "turn": turn})
        local_date = _independent_display_datetime("2026-08-05T07:07:00Z")
        for tooltip in (thinking_tip, assistant_tip):
            self.assertIn(local_date, tooltip)
            self.assertIn("Total", tooltip)
            self.assertIn("Input", tooltip)
            self.assertIn("Gen", tooltip)
            self.assertIn("Output", tooltip)
            self.assertIn("t/s", tooltip)
            self.assertIn("Tools", tooltip)
        self.assertIn("Output 120", thinking_tip)
        self.assertIn("Output 180", assistant_tip)

        draw_source = inspect.getsource(velox.Panels._draw_chat_section)
        self.assertNotIn("time_text", draw_source)
        self.assertIn("self._cached_chat_section_stats_tooltip(section)", draw_source)
        self.assertIn('tooltip_id=widget_id + ".stats"', draw_source)
        self.assertIn("header_h = self._chat_card_header_height()", draw_source)
        section_source = inspect.getsource(velox.Panels._chat_sections)
        self.assertNotIn('section["tooltip"] =', section_source)

    def test_format_display_datetime_timezone_and_dst(self) -> None:
        if not hasattr(time, "tzset"):
            self.skipTest("TZ control requires time.tzset (POSIX)")
        saved_tz = os.environ.get("TZ")
        try:
            cases = [
                ("UTC", "2026-08-05T07:07:00Z", "August 5 2026, 07:07"),
                ("America/Toronto", "2026-08-05T07:07:00Z", "August 5 2026, 03:07"),
                ("America/Toronto", "2026-01-05T07:07:00Z", "January 5 2026, 02:07"),
                ("America/Toronto", "2026-03-08T06:59:00Z", "March 8 2026, 01:59"),
                ("America/Toronto", "2026-03-08T07:01:00Z", "March 8 2026, 03:01"),
            ]
            for tz, timestamp, expected in cases:
                with self.subTest(tz=tz, timestamp=timestamp):
                    os.environ["TZ"] = tz
                    time.tzset()
                    self.assertEqual(velox.format_display_datetime(timestamp), expected)
        finally:
            if saved_tz is None:
                os.environ.pop("TZ", None)
            else:
                os.environ["TZ"] = saved_tz
            if hasattr(time, "tzset"):
                time.tzset()

