    def test_delegated_image_analysis_streams_reasoning_and_output(self) -> None:
        async def scenario(root: Path) -> None:
            paths = velox.AppPaths(root)
            storage = velox.Storage(paths)
            storage.ensure_first_run_files()
            chats = velox.ChatStore(storage)
            chat_id = str(chats.create_chat("Streaming image analysis")["chat_id"])
            image_path = paths.chat_workspace_dir(chat_id) / "pixel.png"
            image_path.parent.mkdir(parents=True, exist_ok=True)
            image_path.write_bytes(base64.b64decode(
                "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAusB9Y9ZV7sAAAAASUVORK5CYII="
            ))

            class FakeLLM:
                def __init__(self, reasoning_only: bool = False) -> None:
                    self.requests: list[LLMRequest] = []
                    self.reasoning_only = reasoning_only

                def resolve_endpoint(self, profile_id: str) -> dict[str, Any]:
                    return velox.endpoint_profile_for_id(storage.load_config(), profile_id)

                async def chat_completions_stream(self, request: LLMRequest):
                    self.requests.append(request)
                    yield velox.LLMChunk(reasoning_text="Inspecting exact pixels and labels.")
                    if not self.reasoning_only:
                        yield velox.LLMChunk(text="The visible result is complete.", usage={"completion_tokens": 12})
                    yield velox.LLMChunk(done=True, finish_reason="stop")

            config = storage.load_config()
            current_profile = velox.endpoint_profile_ref(config, velox.DEFAULT_ENDPOINT_PROFILE_ID)
            current_profile["image_analysis_context"] = "separate"
            storage.write_config(config)

            progress: list[dict[str, Any]] = []
            fake = FakeLLM()
            ctx = velox.ToolContext(
                scope_id=velox.APP_SCOPE_ID,
                chat_id=chat_id,
                endpoint_profile_id=velox.DEFAULT_ENDPOINT_PROFILE_ID,
                cancel_event=threading.Event(),
                progress_callback=lambda fields: progress.append(copy.deepcopy(fields)),
            )
            result = await velox.ImageTools(storage, fake).analyze(ctx, {
                "path": str(image_path), "prompt": "Describe the image and transcribe all text.",
            })
            self.assertEqual(result["mode"], "separate_context_streaming")
            self.assertEqual(result["analysis"], "The visible result is complete.")
            self.assertIn("Inspecting exact pixels and labels.", result["reasoning"])
            self.assertIn("<think>", result["raw_response"])
            self.assertIn("The visible result is complete.", result["raw_response"])
            self.assertTrue(any("Inspecting exact pixels" in str(row.get("endpoint_stream_text") or "") for row in progress))
            self.assertTrue(any(row.get("endpoint_complete") for row in progress))
            self.assertEqual(len(fake.requests), 1)
            self.assertTrue(fake.requests[0].stream)
            self.assertEqual(fake.requests[0].max_output_tokens, velox.IMAGE_ANALYSIS_DELEGATED_MAX_OUTPUT_TOKENS)
            self.assertIs(fake.requests[0].cancel_event, ctx.cancel_event)

            fallback_fake = FakeLLM(reasoning_only=True)
            fallback = await velox.ImageTools(storage, fallback_fake).analyze(ctx, {
                "path": str(image_path), "prompt": "Inspect the image.",
            })
            self.assertTrue(fallback["reasoning_fallback"])
            self.assertEqual(fallback["analysis"], "Inspecting exact pixels and labels.")

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

