    def test_user_cancelled_tool_returns_elapsed_result_and_llm_notice(self) -> None:
        async def scenario(root: Path) -> None:
            storage = velox.Storage(velox.AppPaths(root))
            storage.ensure_first_run_files()
            chat_id = str(velox.ChatStore(storage).create_chat("Cancel tool")["chat_id"])
            registry = velox.ToolRegistry(storage)
            call = {"name": "time_sleep", "arguments": {"minutes": 1.0, "message": "resume"}}
            live = velox.make_tool_call_record("time_sleep", call["arguments"], chat_id=chat_id)
            task = asyncio.create_task(registry.execute_tool_call(
                velox.APP_SCOPE_ID, call, chat_id=chat_id, live_record=live,
            ))
            for _ in range(100):
                if registry.tool_execution_snapshot(str(live["tool_call_id"])):
                    break
                await asyncio.sleep(0.01)
            self.assertTrue(registry.cancel_tool_call(
                str(live["tool_call_id"]),
                reason="The user cancelled this tool call from the chat interface.",
                cancelled_by_user=True,
            ))
            result = await asyncio.wait_for(task, timeout=2.0)
            self.assertEqual(result["status"], "cancelled")
            self.assertTrue(result["cancelled"])
            self.assertTrue(result["cancelled_by_user"])
            self.assertGreaterEqual(float(result["elapsed_seconds"]), 0.0)
            self.assertIn("Elapsed before cancellation:", result["error"])
            snapshot = registry.tool_execution_snapshot(str(live["tool_call_id"]))
            self.assertEqual(snapshot["status"], "cancelled")
            runtime = velox.ChatRuntime.__new__(velox.ChatRuntime)
            runtime.storage = storage
            payload = runtime._tool_result_payload_text(result)
            self.assertIn("CANCELLED_BY_USER", payload)
            self.assertIn("The user cancelled this tool call", payload)
            self.assertIn("Elapsed before cancellation", payload)

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_stopping_chat_cancels_all_owned_tool_operations(self) -> None:
        async def scenario(root: Path) -> None:
            storage = velox.Storage(velox.AppPaths(root))
            storage.ensure_first_run_files()
            chat_id = str(velox.ChatStore(storage).create_chat("Stop chat tools")["chat_id"])
            registry = velox.ToolRegistry(storage)
            call = {"name": "time_sleep", "arguments": {"minutes": 1.0, "message": "resume"}}
            live = velox.make_tool_call_record("time_sleep", call["arguments"], chat_id=chat_id)
            tool_task = asyncio.create_task(registry.execute_tool_call(
                velox.APP_SCOPE_ID, call, chat_id=chat_id, live_record=live,
            ))
            for _ in range(100):
                if registry.tool_execution_snapshot(str(live["tool_call_id"])):
                    break
                await asyncio.sleep(0.01)
            chat_task = asyncio.create_task(asyncio.sleep(60))
            runtime = velox.ChatRuntime.__new__(velox.ChatRuntime)
            runtime.storage = storage
            runtime.tools = registry
            runtime.running = {chat_id: chat_task}
            runtime._agent_report_workers = {}
            runtime.chats = velox.ChatStore(storage)
            runtime.cancel(chat_id)
            try:
                tool_result = await tool_task
            except asyncio.CancelledError:
                tool_result = None
            if tool_result is not None:
                self.assertEqual(tool_result["status"], "cancelled")
                self.assertFalse(tool_result.get("cancelled_by_user"))
            with self.assertRaises(asyncio.CancelledError):
                await chat_task
            await asyncio.wait_for(asyncio.gather(*runtime._checklist_stop_tasks.values()), 2.0)
            await asyncio.sleep(0)  # Drain the durable Stop completion callback.
            snapshot = registry.tool_execution_snapshot(str(live["tool_call_id"]))
            self.assertEqual(snapshot["status"], "cancelled")
            self.assertIn("stopped this conversation", str(snapshot.get("error") or ""))
            self.assertTrue(runtime.chats.load_chat(chat_id)["agent_reports_suspended"])

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_llm_stream_cancel_closes_active_endpoint_response(self) -> None:
        async def scenario(root: Path) -> None:
            storage = velox.Storage(velox.AppPaths(root))
            storage.ensure_first_run_files()
            client = velox.LLMClient(storage)

            class BlockingResponse:
                status = 200
                headers: dict[str, str] = {}

                def __init__(self) -> None:
                    self.started = threading.Event()
                    self.released = threading.Event()
                    self.close_called = False

                def __enter__(self):
                    self.started.set()
                    return self

                def __exit__(self, _type: Any, _value: Any, _trace: Any) -> None:
                    self.close()

                def getcode(self) -> int:
                    return 200

                def geturl(self) -> str:
                    return "http://local.test/v1/chat/completions"

                def readline(self, _limit: int = -1) -> bytes:
                    self.released.wait(5.0)
                    return b""

                def close(self) -> None:
                    self.close_called = True
                    self.released.set()

            response = BlockingResponse()
            cancel_event = threading.Event()
            request = velox.LLMRequest(
                scope_id=velox.APP_SCOPE_ID,
                endpoint_profile_id=velox.DEFAULT_ENDPOINT_PROFILE_ID,
                messages=[{"role": "user", "content": "wait"}],
                stream=True,
                cancel_event=cancel_event,
            )

            async def consume() -> list[LLMChunk]:
                return [chunk async for chunk in client.chat_completions_stream(request)]

            with mock.patch.object(urllib.request, "urlopen", return_value=response):
                task = asyncio.create_task(consume())
                started = await asyncio.to_thread(response.started.wait, 1.0)
                self.assertTrue(started)
                cancel_event.set()
                with self.assertRaises(asyncio.CancelledError):
                    await asyncio.wait_for(task, timeout=3.0)
            self.assertTrue(response.close_called)

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

