    def test_model_specific_reasoning_dropdowns_and_vllm_payloads(self) -> None:
        self.assertEqual(
            velox.endpoint_reasoning_level_options(velox.ENDPOINT_MODEL_TYPE_QWEN_3_6),
            (("on", "On"), ("off", "Off")),
        )
        self.assertEqual(
            velox.endpoint_reasoning_level_options(velox.ENDPOINT_MODEL_TYPE_DEEPSEEK_V4),
            (("max", "Max"), ("high", "High"), ("low", "Low")),
        )
        self.assertEqual(
            velox.endpoint_reasoning_level_options(velox.ENDPOINT_MODEL_TYPE_GEMMA_4),
            (("on", "On"), ("off", "Off")),
        )
        self.assertEqual(
            velox.endpoint_reasoning_level_options(velox.ENDPOINT_MODEL_TYPE_KIMI_K2_6),
            (("on", "On"),),
        )
        self.assertEqual(
            velox.endpoint_reasoning_level_options(velox.ENDPOINT_MODEL_TYPE_KIMI_K3),
            (("max", "Max"),),
        )
        self.assertEqual(velox.endpoint_reasoning_level_default(velox.ENDPOINT_MODEL_TYPE_QWEN_3_6), "off")
        self.assertEqual(velox.endpoint_reasoning_level_default(velox.ENDPOINT_MODEL_TYPE_GEMMA_4), "off")
        self.assertEqual(velox.endpoint_reasoning_level_default(velox.ENDPOINT_MODEL_TYPE_DEEPSEEK_V4), "max")
        self.assertEqual(velox.normalize_endpoint_reasoning_level(velox.ENDPOINT_MODEL_TYPE_KIMI_K2_6, "off"), "on")
        self.assertEqual(velox.normalize_endpoint_reasoning_level(velox.ENDPOINT_MODEL_TYPE_KIMI_K3, "low"), "max")

        with tempfile.TemporaryDirectory() as td:
            storage = velox.Storage(velox.AppPaths(Path(td)))
            storage.ensure_first_run_files()
            request_messages = [
                {"role": "assistant", "content": "prior", "reasoning_content": "private prior thought"},
                {"role": "user", "content": "continue"},
            ]

            client = velox.LLMClient(storage)
            qwen_request = velox.LLMRequest(
                scope_id=velox.APP_SCOPE_ID,
                endpoint_profile_id=velox.DEFAULT_QWEN_3_6_ENDPOINT_PROFILE_ID,
                messages=request_messages,
            )
            _endpoint, _url, _body, _headers, _timeout, qwen_payload = client._payload_and_headers(
                qwen_request, stream=False,
            )
            self.assertEqual(qwen_payload["chat_template_kwargs"], {"enable_thinking": False})
            self.assertTrue(all("reasoning_content" not in row for row in qwen_payload["messages"]))

            config = storage.load_config()
            qwen = velox.endpoint_profile_ref(config, velox.DEFAULT_QWEN_3_6_ENDPOINT_PROFILE_ID)
            qwen["reasoning_effort"] = "on"
            qwen["preserve_thinking"] = True
            deepseek = velox.endpoint_profile_ref(config, velox.DEFAULT_DEEPSEEK_V4_FLASH_0731_ENDPOINT_PROFILE_ID)
            deepseek["reasoning_effort"] = "high"
            kimi2 = velox.default_endpoint_profile(
                "endpoint-test-kimi-k2-6", "Custom Kimi K2.6", timeout_seconds=60,
                model_type=velox.ENDPOINT_MODEL_TYPE_KIMI_K2_6,
            )
            config["llm"]["endpoint_profiles"].append(kimi2)
            storage.write_config(config)

            client = velox.LLMClient(storage)
            _endpoint, _url, _body, _headers, _timeout, qwen_on_payload = client._payload_and_headers(
                qwen_request, stream=False,
            )
            self.assertEqual(qwen_on_payload["chat_template_kwargs"], {"enable_thinking": True})
            self.assertEqual(qwen_on_payload["messages"][0]["reasoning_content"], "private prior thought")

            deepseek_request = dataclasses.replace(
                qwen_request,
                endpoint_profile_id=velox.DEFAULT_DEEPSEEK_V4_FLASH_0731_ENDPOINT_PROFILE_ID,
            )
            _endpoint, _url, _body, _headers, _timeout, deepseek_payload = client._payload_and_headers(
                deepseek_request, stream=False,
            )
            self.assertEqual(deepseek_payload["reasoning_effort"], "high")
            self.assertEqual(
                deepseek_payload["chat_template_kwargs"],
                {"thinking": True, "reasoning_effort": "high"},
            )
            self.assertEqual(deepseek_payload["messages"][0]["reasoning_content"], "private prior thought")

            kimi2_request = dataclasses.replace(
                qwen_request,
                endpoint_profile_id=kimi2["id"],
            )
            _endpoint, _url, _body, _headers, _timeout, kimi2_payload = client._payload_and_headers(
                kimi2_request, stream=False,
            )
            self.assertEqual(
                kimi2_payload["chat_template_kwargs"],
                {"thinking": True, "preserve_thinking": True},
            )

            kimi3_request = dataclasses.replace(
                qwen_request,
                endpoint_profile_id=velox.DEFAULT_KIMI_K3_ENDPOINT_PROFILE_ID,
            )
            _endpoint, _url, _body, _headers, _timeout, kimi3_payload = client._payload_and_headers(
                kimi3_request, stream=False,
            )
            self.assertEqual(kimi3_payload["reasoning_effort"], "max")
            kimi3_assistant = next(row for row in kimi3_payload["messages"] if row.get("role") == "assistant")
            self.assertEqual(kimi3_assistant["reasoning_content"], "private prior thought")
            self.assertNotIn("response_format", kimi3_payload)
            self.assertNotIn("modalities", kimi3_payload)
            self.assertNotIn("tools", kimi3_payload)

        editor = inspect.getsource(velox.Panels.draw_modals)
        self.assertIn('"Reasoning level"', editor)
        self.assertIn("endpoint_reasoning_level_options", editor)
        self.assertIn('"Max image inputs"', editor)

    def test_endpoint_image_budget_and_output_ceiling_are_enforced(self) -> None:
        config = velox.default_config()
        vision_profiles = [
            profile for profile in velox.endpoint_profiles_from_config(config)
            if velox.endpoint_supports_vision(profile)
        ]
        self.assertTrue(vision_profiles)
        image_budgets = {
            str(profile.get("id") or profile.get("profile_id") or ""):
            int(profile["max_image_inputs_per_prompt"])
            for profile in vision_profiles
        }
        self.assertEqual(image_budgets[velox.DEFAULT_QWEN_3_8_ENDPOINT_PROFILE_ID], 32)
        self.assertEqual(image_budgets[velox.DEFAULT_QWEN_3_8_FLASH_NEXT_ENDPOINT_PROFILE_ID], 32)
        self.assertEqual(image_budgets[velox.DEFAULT_QWEN_3_8_FLASH_NEXT_NOVITA_ENDPOINT_PROFILE_ID], 32)
        self.assertEqual(
            image_budgets[velox.DEFAULT_DEEPSEEK_V4_FLASH_VISION_EXP_ENDPOINT_PROFILE_ID], 256,
        )
        self.assertTrue(all(
            budget == 5
            for profile_id, budget in image_budgets.items()
            if profile_id not in {
                velox.DEFAULT_QWEN_3_8_ENDPOINT_PROFILE_ID,
                velox.DEFAULT_QWEN_3_8_FLASH_NEXT_ENDPOINT_PROFILE_ID,
                velox.DEFAULT_QWEN_3_8_FLASH_NEXT_NOVITA_ENDPOINT_PROFILE_ID,
                velox.DEFAULT_DEEPSEEK_V4_FLASH_VISION_EXP_ENDPOINT_PROFILE_ID,
            }
        ))

        with tempfile.TemporaryDirectory() as td:
            storage = velox.Storage(velox.AppPaths(Path(td)))
            storage.ensure_first_run_files()
            client = velox.LLMClient(storage)

            five_images = [
                {"type": "image_url", "image_url": {"url": f"data:image/png;base64,{index}"}}
                for index in range(5)
            ]
            request = velox.LLMRequest(
                scope_id=velox.APP_SCOPE_ID,
                endpoint_profile_id=velox.DEFAULT_QWEN_3_6_ENDPOINT_PROFILE_ID,
                messages=[{"role": "user", "content": [{"type": "text", "text": "compare"}, *five_images]}],
                max_output_tokens=velox.IMAGE_ANALYSIS_DELEGATED_MAX_OUTPUT_TOKENS,
            )
            _endpoint, _url, _body, _headers, _timeout, payload = client._payload_and_headers(
                request, stream=False,
            )
            self.assertEqual(velox.message_image_input_count(payload["messages"]), 5)
            self.assertEqual(payload["max_tokens"], 16_384)

            too_many = copy.deepcopy(request.messages)
            too_many[0]["content"].append({
                "type": "image_url", "image_url": {"url": "data:image/png;base64,overflow"},
            })
            with self.assertRaisesRegex(ValueError, "at most 5 image input"):
                client._payload_and_headers(dataclasses.replace(request, messages=too_many), stream=False)

            config = storage.load_config()
            qwen = velox.endpoint_profile_ref(config, velox.DEFAULT_QWEN_3_6_ENDPOINT_PROFILE_ID)
            qwen["max_image_inputs_per_prompt"] = 2
            storage.write_config(config)
            client = velox.LLMClient(storage)
            with self.assertRaisesRegex(ValueError, "at most 2 image input"):
                client._payload_and_headers(request, stream=False)

        build_messages = inspect.getsource(velox.ChatRuntime._build_messages)
        self.assertIn("message_image_input_count(messages)", build_messages)
        self.assertIn("remaining_image_inputs", build_messages)
        self.assertFalse(hasattr(velox.ImageTools, "analyze_many"))
        self.assertNotIn("images_analyze", velox.ToolRegistry(storage).tools)

