class IOAndChatTests(_DataRootsIsolatedTestMixin, unittest.TestCase):
    """Regression coverage for hidden streaming, worker I/O, and ordinary chat completion."""


    @staticmethod
    def _stack(root: Path) -> tuple[AppPaths, Storage, ChatStore, dict[str, Any]]:
        paths = velox.AppPaths(root)
        storage = velox.Storage(paths)
        storage.ensure_first_run_files()
        chats = velox.ChatStore(storage)
        chat = chats.create_chat("Streaming I/O")
        return paths, storage, chats, chat

    def test_stream_bridge_coalesces_wakeups_preserves_order_and_yields_fairly(self) -> None:
        async def scenario() -> None:
            loop = asyncio.get_running_loop()
            bridge = velox.LLMStreamChunkBridge(loop, flush_seconds=0.004)
            pieces = [f"{index:05d};" for index in range(12_000)]
            producer_done = threading.Event()

            def produce() -> None:
                for piece in pieces:
                    bridge.publish(velox.LLMChunk(text=piece))
                bridge.publish(velox.LLMChunk(
                    usage={"completion_tokens": len(pieces)},
                    done=True,
                    finish_reason="stop",
                ))
                bridge.close()
                producer_done.set()

            heartbeat = 0
            stop_heartbeat = False

            async def beat() -> None:
                nonlocal heartbeat
                while not stop_heartbeat:
                    heartbeat += 1
                    await asyncio.sleep(0)

            beat_task = asyncio.create_task(beat())
            thread = threading.Thread(target=produce, daemon=True)
            thread.start()
            chunks: list[LLMChunk] = []
            while True:
                chunk = await asyncio.wait_for(bridge.queue.get(), timeout=3.0)
                if chunk is None:
                    break
                chunks.append(chunk)
                await asyncio.sleep(0)
            stop_heartbeat = True
            await beat_task
            thread.join(timeout=1.0)
            self.assertTrue(producer_done.is_set())
            self.assertEqual("".join(chunk.text for chunk in chunks), "".join(pieces))
            self.assertTrue(any(chunk.done for chunk in chunks))
            self.assertEqual(chunks[-1].finish_reason, "stop")
            self.assertLess(bridge.cross_thread_wakeups, 100)
            self.assertLess(bridge.delivered_batches, 100)
            # The exact number of cooperative turns depends on host scheduling
            # and on how aggressively the bridge coalesces. Requiring progress,
            # rather than an arbitrary count, catches event-loop starvation
            # without making the regression test timing-sensitive.
            self.assertGreater(heartbeat, 0)

        asyncio.run(scenario())

    def test_hidden_chat_publication_is_slower_without_delaying_network_ingestion(self) -> None:
        self.assertEqual(velox.chat_stream_ui_interval_seconds(1_000, visible=True), velox.CHAT_STREAM_UI_INTERVAL_SMALL_SECONDS)
        self.assertGreaterEqual(
            velox.chat_stream_ui_interval_seconds(1_000, visible=False),
            velox.CHAT_STREAM_UI_BACKGROUND_MIN_SECONDS,
        )
        self.assertGreaterEqual(
            velox.chat_stream_ui_interval_seconds(velox.CHAT_STREAM_UI_HUGE_CHARS, visible=False),
            velox.CHAT_STREAM_UI_BACKGROUND_HUGE_SECONDS,
        )
        production = application_source()
        self.assertIn("class LLMStreamChunkBridge", production)
        self.assertIn("await asyncio.sleep(0)", production)
        self.assertIn("await lease.release()", production)
        self.assertIn("chat_visible = self._is_chat_visible(chat_id)", production)
        self.assertIn("visible=chat_visible", production)

    def test_batched_jsonl_writer_is_nonblocking_and_preserves_submission_order(self) -> None:
        started = threading.Event()
        release = threading.Event()
        batches: list[list[int]] = []

        def slow_batch(_path: Path, rows: list[Any]) -> None:
            started.set()
            if not release.wait(3.0):
                raise TimeoutError("test JSONL writer was not released")
            batches.append([int(row["value"]) for row in rows])

        writer = velox.BatchedJSONLWriter(
            batch_delay_seconds=0.0,
            max_batch_rows=64,
            write_batch=slow_batch,
        )
        path = Path(tempfile.gettempdir()) / f"velox-jsonl-{uuid.uuid4()}.jsonl"
        try:
            writer.submit(path, {"value": 0})
            self.assertTrue(started.wait(1.0))
            before = time.perf_counter()
            for value in range(1, 257):
                writer.submit(path, {"value": value})
            self.assertLess(time.perf_counter() - before, 0.15)
            release.set()
            self.assertTrue(writer.flush((path,), timeout=3.0))
            flattened = [value for batch in batches for value in batch]
            self.assertEqual(flattened, list(range(257)))
            self.assertLessEqual(len(batches), 6)
        finally:
            release.set()
            writer.flush(timeout=3.0)
            writer.clear_for_tests()
            path.unlink(missing_ok=True)

    def test_delayed_log_batch_never_recreates_a_removed_data_root(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            root = Path(td) / "ephemeral-root"
            root.mkdir(parents=True)
            path = root / velox.LOG_FILE_NAME
            path.write_text("", encoding="utf-8")
            writer = velox.BatchedJSONLWriter(batch_delay_seconds=0.25)
            writer.submit(path, {"value": 1})
            shutil.rmtree(root)
            self.assertTrue(writer.flush((path,), timeout=2.0))
            self.assertFalse(root.exists())
            self.assertEqual(writer.last_error(path), "")
            writer.clear_for_tests()

    def test_small_stream_checkpoints_also_use_the_snapshot_worker(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            paths, _storage, chats, chat = self._stack(Path(td))
            chat_id = str(chat["chat_id"])
            turn = velox.make_turn(chat_id, "assistant", "", status="streaming")
            chats.append_turn(velox.APP_SCOPE_ID, chat_id, turn, mark_stale=False)
            writer = velox.CHAT_STREAM_SNAPSHOT_WRITER
            writer.clear_for_tests()
            original_write = writer._write_json
            started = threading.Event()
            release = threading.Event()

            def slow_write(target: Path, payload: Any) -> None:
                started.set()
                if not release.wait(3.0):
                    raise TimeoutError("test checkpoint writer was not released")
                original_write(target, payload)

            writer._write_json = slow_write
            try:
                before = time.perf_counter()
                self.assertTrue(chats.update_turn(
                    velox.APP_SCOPE_ID,
                    chat_id,
                    str(turn["turn_id"]),
                    {"text": "small live response"},
                    expected_statuses={"streaming"},
                ))
                self.assertLess(time.perf_counter() - before, 0.25)
                self.assertTrue(started.wait(1.0))
                self.assertFalse(paths.chat_stream_snapshot_json(chat_id).exists())
                release.set()
                self.assertTrue(writer.flush((paths.chat_stream_snapshot_json(chat_id),), timeout=3.0))
                self.assertTrue(paths.chat_stream_snapshot_json(chat_id).is_file())
            finally:
                release.set()
                writer.flush(timeout=3.0)
                writer._write_json = original_write
                writer.clear_for_tests()

    def test_app_state_persistence_is_single_flight_deduplicated_and_off_loop(self) -> None:
        async def scenario() -> None:
            app = velox.VeloxApp.__new__(velox.VeloxApp)
            app.app_state_persist_task = None
            app._scheduled_app_state_signature = ""
            app._last_persisted_app_state_signature = ""
            app.storage = mock.Mock()
            started = threading.Event()
            release = threading.Event()
            writes: list[tuple[dict[str, Any], dict[str, Any]]] = []

            def slow_write(state: dict[str, Any], geometry: dict[str, Any]) -> None:
                started.set()
                if not release.wait(3.0):
                    raise TimeoutError("test app-state writer was not released")
                writes.append((copy.deepcopy(state), copy.deepcopy(geometry)))

            app._write_app_state_payload = slow_write
            state = velox.default_app_state()
            geometry = {"window_width": 1400, "window_height": 900}
            self.assertTrue(app._schedule_app_state_persist(state, geometry))
            self.assertFalse(app._schedule_app_state_persist(state, geometry))
            self.assertTrue(await asyncio.to_thread(started.wait, 1.0))
            heartbeat = 0
            for _ in range(50):
                heartbeat += 1
                await asyncio.sleep(0)
            self.assertEqual(heartbeat, 50)
            release.set()
            task = app.app_state_persist_task
            self.assertIsNotNone(task)
            await task
            app._consume_app_state_persist_task(task)
            app.app_state_persist_task = None
            self.assertEqual(len(writes), 1)
            self.assertFalse(app._schedule_app_state_persist(state, geometry))

        asyncio.run(scenario())

    def test_combined_state_and_geometry_commit_uses_one_manifest_replacement(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            paths, storage, _chats, _chat = self._stack(Path(td))
            state = velox.default_app_state()
            state["active_panel"] = "settings"
            geometry = {
                "window_width": 1777,
                "window_height": 999,
                "window_x": 22,
                "window_y": 33,
            }
            with mock.patch.object(
                paths, "_write_app_manifest_plain", wraps=paths._write_app_manifest_plain,
            ) as write_manifest:
                storage.write_app_state_and_geometry(state, geometry)
            self.assertEqual(write_manifest.call_count, 1)
            self.assertEqual(storage.load_app_state()["active_panel"], "settings")
            ui = storage.load_config()["ui"]
            for key, value in geometry.items():
                self.assertEqual(ui[key], value)

    @staticmethod
    def _chat_runtime(
        root: Path,
        stream_texts: list[str],
    ) -> tuple[Storage, ChatStore, dict[str, Any], ChatRuntime, Any]:
        paths = velox.AppPaths(root)
        storage = velox.Storage(paths)
        storage.ensure_first_run_files()
        chats = velox.ChatStore(storage)
        chat = chats.create_chat("Ordinary completion test")
        profile_id = chats.get_endpoint_profile_id()
        endpoint = velox.endpoint_profile_ref(storage.load_config(), profile_id)

        class FakeLLM:
            def __init__(self) -> None:
                self.stream_texts = list(stream_texts)
                self.stream_requests: list[list[dict[str, Any]]] = []
                self.once_full_calls = 0

            def resolve_endpoint(self, _profile_id: str) -> dict[str, Any]:
                return copy.deepcopy(endpoint)

            async def chat_completions_stream(self, request: LLMRequest):
                self.stream_requests.append(copy.deepcopy(request.messages))
                if not self.stream_texts:
                    raise AssertionError("unexpected visible completion request")
                response_text = self.stream_texts.pop(0)
                yield velox.LLMChunk(text=response_text)
                yield velox.LLMChunk(
                    usage={"prompt_tokens": 10, "completion_tokens": max(1, len(response_text) // 4)},
                    done=True,
                    finish_reason="stop",
                )

            async def chat_completions_once_full(self, request: LLMRequest) -> dict[str, Any]:
                del request
                self.once_full_calls += 1
                raise AssertionError("Chat must not issue a hidden completion-verification request")

        fake = FakeLLM()
        runtime = velox.ChatRuntime(
            storage,
            chats,
            velox.ContextAssembler(paths),
            fake,
            velox.ToolRegistry(storage),
        )
        runtime.set_visibility_provider(lambda _chat_id: False)
        return storage, chats, chat, runtime, fake

    def test_chat_completion_stops_after_one_visible_response_without_hidden_persistence(self) -> None:
        async def run_case(root: Path) -> tuple[list[dict[str, Any]], Any]:
            _storage, chats, chat, runtime, fake = self._chat_runtime(root, ["Complete answer."])
            chat_id = str(chat["chat_id"])
            user = velox.make_turn(chat_id, "user", "Answer fully.")
            assistant = velox.make_turn(chat_id, "assistant", "", status="streaming")
            chats.append_turn(velox.APP_SCOPE_ID, chat_id, user)
            chats.append_turn(velox.APP_SCOPE_ID, chat_id, assistant, mark_stale=False)
            await runtime._run_assistant_loop(
                velox.APP_SCOPE_ID, chat_id, str(assistant["turn_id"]),
                chats.get_endpoint_profile_id(), "Answer fully.", "ordinary completion regression",
            )
            return chats.load_turns(velox.APP_SCOPE_ID, chat_id), fake

        with tempfile.TemporaryDirectory() as td:
            turns, fake = asyncio.run(run_case(Path(td)))
            assistants = [turn for turn in turns if turn.get("role") == "assistant"]
            self.assertEqual(len(assistants), 1)
            self.assertEqual(assistants[0]["status"], "complete")
            self.assertEqual(assistants[0]["text"], "Complete answer.")
            self.assertEqual(len(fake.stream_requests), 1)
            self.assertEqual(fake.once_full_calls, 0)

    def test_io_hot_paths_use_workers_and_no_legacy_model_support_remains(self) -> None:
        background_source = inspect.getsource(velox.VeloxApp.run_background_ticks)
        perf_source = inspect.getsource(velox.VeloxApp.perf_overlay_enabled)
        developer_source = inspect.getsource(velox.VeloxApp.developer_mode_enabled)
        production = application_source()
        self.assertIn("timeout_seconds, handler = await asyncio.to_thread", production)
        self.assertIn("self._prepare_tool_execution,", production)
        self.assertIn("endpoint_profile_id=endpoint_profile_id", production)
        self.assertIn("_schedule_app_state_persist", background_source)
        self.assertIn("velox-background-config-read", background_source)
        self.assertNotIn("load_config", perf_source)
        self.assertNotIn("load_config", developer_source)
        self.assertNotIn("migrate_v", production)
        self.assertNotIn("PREVIOUS_", production)
        self.assertNotIn("SUPPORTED_DATA_FILE_VERSIONS", production)


class CompletionVerificationTests(_DataRootsIsolatedTestMixin, unittest.TestCase):
    """Compaction, completion and delivery checks."""


    @staticmethod
    def _stack(root: Path) -> tuple[AppPaths, Storage, ChatStore, dict[str, Any]]:
        paths = velox.AppPaths(root)
        storage = velox.Storage(paths)
        storage.ensure_first_run_files()
        chats = velox.ChatStore(storage)
        chat = chats.create_chat("Completion verification")
        return paths, storage, chats, chat

    def test_chat_and_agent_compaction_escalate_and_condense_truncated_reasoning(self) -> None:
        condensed, count, removed = velox.compact_oversized_reasoning_message(
            {"role": "assistant", "content": "<think>" + "x" * 4000},
            prompt_capacity_tokens=8192,
        )
        self.assertEqual(count, 1)
        self.assertGreater(removed, 0)
        self.assertIn("</think>", condensed["content"])

        async def scenario(root: Path) -> None:
            paths, storage, chats, chat = self._stack(root)
            chat_id = str(chat["chat_id"])
            endpoint = velox.endpoint_profile_ref(storage.load_config(), velox.DEFAULT_ENDPOINT_PROFILE_ID)
            endpoint["context_window_tokens"] = 24000
            endpoint["max_output_tokens"] = 4000

            class ChatCompactor:
                def resolve_endpoint(self, _profile_id: str) -> dict[str, Any]:
                    return copy.deepcopy(endpoint)

                async def chat_completions_stream(self, request: LLMRequest):
                    self_assert = request.max_output_tokens is not None
                    if not self_assert:
                        raise AssertionError("expected a compaction request")
                    self.assertGreaterEqual(int(request.max_output_tokens or 0), 8_192)
                    self.assertEqual(request.reasoning_effort_override, "minimal")
                    yield velox.LLMChunk(text=(
                        "Operational memory retains exact paths, completed changes, current failures, user "
                        "constraints, and the next verification actions. Repetition and private deliberation "
                        "are removed while the current system instructions and newest request stay authoritative."
                    ))
                    yield velox.LLMChunk(done=True, finish_reason="stop", usage={"prompt_tokens": 8000, "completion_tokens": 60})

            chat_runtime = velox.ChatRuntime(
                storage, chats, velox.ContextAssembler(paths), ChatCompactor(), velox.ToolRegistry(storage),
            )
            chat_messages: list[dict[str, Any]] = [
                {"role": "system", "content": "SYSTEM"},
                {"role": "assistant", "content": "<think>" + "r" * 24000},
            ]
            for index in range(8):
                chat_messages.append({"role": "user" if index % 2 == 0 else "assistant", "content": f"middle {index} " + "m" * 1200})
            for index in range(8):
                chat_messages.append({"role": "user" if index % 2 == 0 else "assistant", "content": f"recent {index} " + "z" * 5000})
            placeholder = velox.make_turn(
                chat_id, "assistant", "", endpoint_profile_id=velox.DEFAULT_ENDPOINT_PROFILE_ID,
                endpoint_label="Deepseek", status="streaming",
            )
            chats.append_turn(velox.APP_SCOPE_ID, chat_id, placeholder, mark_stale=False)
            compacted, _next_id, did_compact = await chat_runtime._maybe_compact_chat_context(
                velox.APP_SCOPE_ID, chat_id, velox.DEFAULT_ENDPOINT_PROFILE_ID,
                chat_messages, placeholder["turn_id"], force=True, append_response_turn=False,
            )
            self.assertTrue(did_compact)
            chat_card = next(row for row in chats.load_turns(velox.APP_SCOPE_ID, chat_id) if row.get("role") == "compaction")
            chat_meta = chat_card["compaction_meta"]
            self.assertTrue(chat_meta["fits_effective_context"])
            self.assertGreaterEqual(chat_meta["passes_used"], 1)
            self.assertGreaterEqual(chat_meta["oversized_reasoning_blocks_summarized"], 1)
            self.assertLessEqual(chat_meta["after_tokens"], chat_meta["prompt_capacity_tokens"])
            self.assertNotIn("r" * 1000, json.dumps(compacted))
            self.assertEqual(len(chat_meta["compaction_passes"]), chat_meta["passes_used"])

            class AgentCompactor:
                async def chat_completions_once_full(self, request: LLMRequest) -> dict[str, Any]:
                    self_assert = request.max_output_tokens is not None
                    if not self_assert:
                        raise AssertionError("expected an agent compaction request")
                    self.assertGreaterEqual(int(request.max_output_tokens or 0), 8_192)
                    self.assertEqual(request.reasoning_effort_override, "minimal")
                    return {
                        "text": (
                            "Operational memory retains completed actions, exact paths, constraints, failures, "
                            "and the next autonomous verification step while removing repeated deliberation."
                        ),
                        "usage": {"prompt_tokens": 7000, "completion_tokens": 45},
                        "raw": {},
                    }

            agents = velox.AgentStore(storage)
            tools = velox.ToolRegistry(storage)
            agent_runtime = velox.AgentRuntime(
                storage, agents, chats, velox.ContextAssembler(paths), AgentCompactor(), tools,
            )
            agent = agents.create_agent(
                chat_id, "Finish the verification task.",
                context_window_tokens=24000, max_output_tokens=4000,
                auto_compaction_enabled=True,
            )
            agent_id = str(agent["agent_id"])
            system = "AGENT SYSTEM"
            task = "# Assigned task\nFinish the verification task."
            agents.append_event(agent_id, "started", {"system_prompt": system, "user_prompt": task})
            agent_messages: list[dict[str, Any]] = [
                {"role": "system", "content": system},
                {"role": "user", "content": task},
                {"role": "assistant", "reasoning_content": "q" * 24000, "content": "Early answer."},
            ]
            for index in range(7):
                agent_messages.append({"role": "user" if index % 2 == 0 else "assistant", "content": f"older {index} " + "o" * 1200})
            for index in range(3):
                agent_messages.append({"role": "assistant" if index % 2 == 0 else "user", "content": f"recent {index} " + "p" * 12000})
            self.assertTrue(await agent_runtime._maybe_compact_agent_context(
                agent_id, agent_messages, force=True,
            ))
            event = next(
                row for row in reversed(agents.load_transcript(agent_id))
                if row.get("kind") == "context_compacted"
            )
            agent_meta = event["data"]
            self.assertTrue(agent_meta["fits_effective_context"])
            self.assertGreaterEqual(agent_meta["passes_used"], 1)
            self.assertGreaterEqual(agent_meta["oversized_reasoning_blocks_summarized"], 1)
            self.assertLessEqual(agent_meta["after_tokens"], agent_meta["prompt_capacity_tokens"])
            self.assertNotIn("q" * 1000, json.dumps(agent_messages))
            self.assertEqual(len(agent_meta["compaction_passes"]), agent_meta["passes_used"])

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_irreducible_chat_and_agent_compaction_preserve_original_messages(self) -> None:
        async def scenario(root: Path) -> None:
            paths, storage, chats, chat = self._stack(root)
            chat_id = str(chat["chat_id"])

            class ChatCompactor:
                def __init__(self) -> None:
                    self.calls = 0

                def resolve_endpoint(self, profile_id: str) -> dict[str, Any]:
                    return velox.endpoint_profile_ref(storage.load_config(), profile_id)

                async def chat_completions_stream(self, _request: LLMRequest):
                    self.calls += 1
                    raise AssertionError("irreducible Chat context must not call the compactor")
                    yield  # pragma: no cover

            chat_compactor = ChatCompactor()
            chat_runtime = velox.ChatRuntime(
                storage, chats, velox.ContextAssembler(paths), chat_compactor, velox.ToolRegistry(storage),
            )
            messages = [
                {"role": "system", "content": "S" * 40000},
                {"role": "assistant", "content": "tiny"},
                {"role": "user", "content": "U" * 40000},
            ]
            original = copy.deepcopy(messages)
            placeholder = velox.make_turn(
                chat_id, "assistant", "", endpoint_profile_id=velox.DEFAULT_ENDPOINT_PROFILE_ID,
                endpoint_label="Deepseek", status="streaming",
            )
            chats.append_turn(velox.APP_SCOPE_ID, chat_id, placeholder, mark_stale=False)
            returned, _turn_id, handled = await chat_runtime._maybe_compact_chat_context(
                velox.APP_SCOPE_ID, chat_id, velox.DEFAULT_ENDPOINT_PROFILE_ID,
                messages, placeholder["turn_id"], force=True, append_response_turn=False,
            )
            self.assertFalse(handled)
            self.assertEqual(returned, original)
            self.assertEqual(chat_compactor.calls, 0)
            self.assertFalse(any(
                row.get("role") == "compaction"
                for row in chats.load_turns(velox.APP_SCOPE_ID, chat_id)
            ))

            class AgentCompactor:
                def __init__(self) -> None:
                    self.calls = 0

                async def chat_completions_once_full(self, _request: LLMRequest) -> dict[str, Any]:
                    self.calls += 1
                    raise AssertionError("irreducible Agent context must not call the compactor")

            agent_compactor = AgentCompactor()
            agents = velox.AgentStore(storage)
            tools = velox.ToolRegistry(storage)
            agent_runtime = velox.AgentRuntime(
                storage, agents, chats, velox.ContextAssembler(paths), agent_compactor, tools,
            )
            agent = agents.create_agent(
                chat_id, "T" * 40000,
                context_window_tokens=200000, max_output_tokens=10000,
            )
            agent_id = str(agent["agent_id"])
            system = "S" * 40000
            task = "T" * 40000
            agents.append_event(agent_id, "started", {"system_prompt": system, "user_prompt": task})
            agent_messages = [
                {"role": "system", "content": system},
                {"role": "user", "content": task},
                {"role": "assistant", "content": "tiny"},
            ]
            agent_original = copy.deepcopy(agent_messages)
            self.assertFalse(await agent_runtime._maybe_compact_agent_context(
                agent_id, agent_messages, force=True,
            ))
            self.assertEqual(agent_messages, agent_original)
            self.assertEqual(agent_compactor.calls, 0)
            self.assertFalse(any(
                row.get("kind") in {"context_compacted", "context_compaction_ineffective"}
                for row in agents.load_transcript(agent_id)
            ))

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_orphaned_chat_tasks_terminalize_error_and_cancellation(self) -> None:
        async def scenario(root: Path) -> None:
            paths, storage, chats, chat = self._stack(root)
            runtime = velox.ChatRuntime(
                storage, chats, velox.ContextAssembler(paths), object(), velox.ToolRegistry(storage),
            )
            chat_id = str(chat["chat_id"])
            streaming = velox.make_turn(chat_id, "assistant", "partial", status="streaming")
            chats.append_turn(velox.APP_SCOPE_ID, chat_id, streaming, mark_stale=False)

            async def boom() -> None:
                raise RuntimeError("pre-loop exploded")

            failed_task = asyncio.create_task(boom())
            await asyncio.gather(failed_task, return_exceptions=True)
            runtime.running[chat_id] = failed_task
            runtime._chat_task_done(chat_id, failed_task)
            pending = tuple(runtime._orphan_cleanup_tasks)
            if pending:
                await asyncio.gather(*pending)
            failed_turn = next(
                row for row in chats.load_turns(velox.APP_SCOPE_ID, chat_id)
                if row.get("turn_id") == streaming["turn_id"]
            )
            self.assertEqual(failed_turn["status"], "error")
            self.assertIn("pre-loop exploded", failed_turn["text"])
            self.assertNotIn(chat_id, runtime.running)

            chat2 = chats.create_chat("Cancellation")
            chat2_id = str(chat2["chat_id"])
            streaming2 = velox.make_turn(chat2_id, "assistant", "partial", status="streaming")
            chats.append_turn(velox.APP_SCOPE_ID, chat2_id, streaming2, mark_stale=False)
            cancelled_task = asyncio.create_task(asyncio.sleep(60))
            cancelled_task.cancel()
            await asyncio.gather(cancelled_task, return_exceptions=True)
            runtime.running[chat2_id] = cancelled_task
            runtime._chat_task_done(chat2_id, cancelled_task)
            pending = tuple(runtime._orphan_cleanup_tasks)
            if pending:
                await asyncio.gather(*pending)
            cancelled_turn = next(
                row for row in chats.load_turns(velox.APP_SCOPE_ID, chat2_id)
                if row.get("turn_id") == streaming2["turn_id"]
            )
            self.assertEqual(cancelled_turn["status"], "cancelled")
            self.assertIn("[cancelled]", cancelled_turn["text"])
            self.assertNotIn(chat2_id, runtime.running)

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_background_writer_shutdown_flushes_and_joins_workers(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            json_path = root / "snapshot.json"
            coalesced = velox.CoalescingAtomicJSONWriter()
            coalesced.submit(json_path, {"value": 1})
            coalesced.submit(json_path, {"value": 2})
            self.assertTrue(coalesced.shutdown(timeout=3.0))
            self.assertEqual(velox.read_json(json_path), {"value": 2})
            self.assertTrue(coalesced._thread is None or not coalesced._thread.is_alive())

            jsonl_path = root / "events.jsonl"
            jsonl_path.write_text("", encoding="utf-8")
            batched = velox.BatchedJSONLWriter(batch_delay_seconds=10.0)
            batched.submit(jsonl_path, {"n": 1})
            batched.submit(jsonl_path, {"n": 2})
            self.assertTrue(batched.shutdown(timeout=3.0))
            rows = [json.loads(line) for line in jsonl_path.read_text(encoding="utf-8").splitlines()]
            self.assertEqual(rows, [{"n": 1}, {"n": 2}])
            self.assertTrue(batched._thread is None or not batched._thread.is_alive())

