    def test_compaction_details_end_with_exact_next_context_and_raw_json(self) -> None:
        runtime = velox.ChatRuntime.__new__(velox.ChatRuntime)
        messages = [
            {"role": "system", "content": "SYSTEM EXACT\nsecond line"},
            {"role": "user", "content": "CURRENT REQUEST"},
            {"role": "assistant", "content": "VISIBLE", "reasoning_content": "THINK"},
        ]
        details = runtime._chat_compaction_details_text(
            endpoint_profile_id="endpoint",
            request_messages=[{"role": "system", "content": "COMPACTOR"}],
            raw_output="summary raw",
            summary="durable summary",
            compacted_messages=messages,
            metadata={"state": "complete"},
        )
        separator = "==================== EXACT NEXT MAIN LLM CONTEXT ===================="
        self.assertIn(separator, details)
        self.assertIn("EXACT MESSAGE CONTENTS IN SEND ORDER", details)
        self.assertIn("SYSTEM EXACT\nsecond line", details)
        self.assertIn("===== EXACT RAW JSON MESSAGE ARRAY =====", details)
        raw_json = details.split("===== EXACT RAW JSON MESSAGE ARRAY =====", 1)[1].strip()
        self.assertEqual(json.loads(raw_json), messages)
        self.assertGreater(details.index(separator), details.index("COMPACTION SUMMARY USED AS MEMORY"))

