    def test_browser_playback_wall_clock_delays_and_post_action_waits(self) -> None:
        class FakeWebSocket:
            def __init__(self) -> None:
                self.calls: list[tuple[str, float, dict[str, Any]]] = []

            def command(
                self,
                method: str,
                params: dict[str, Any] | None = None,
                timeout_seconds: float = 0.0,
            ) -> dict[str, Any]:
                del timeout_seconds
                self.calls.append((method, time.monotonic(), dict(params or {})))
                return {}

        with tempfile.TemporaryDirectory() as td:
            paths = velox.AppPaths(Path(td))
            storage = velox.Storage(paths)
            storage.ensure_first_run_files()
            chats = velox.ChatStore(storage)
            chat_id = str(chats.create_chat("Playback timing")["chat_id"])
            tool = velox.BrowserTools(storage)
            events = velox.BrowserTools._normalize_playback_events([
                {"type": "delay", "durationMs": 24, "waitAfterMs": 8},
                {"type": "key", "key": "a", "pressMs": 20, "waitAfterMs": 7},
                {"type": "mouseMotion", "dx": 12, "dy": -6, "durationMs": 36, "steps": 3, "waitAfterMs": 5},
            ])
            fake = FakeWebSocket()
            started = time.monotonic()
            report = tool._execute_playback_events(
                fake, chat_id, events, 1280, 720, time.monotonic() + 3.0,
            )
            elapsed_ms = (time.monotonic() - started) * 1000.0
            self.assertEqual(report["clock"], "monotonic_wall_clock")
            self.assertEqual(report["requestedTimelineMs"], 100)
            self.assertTrue(report["minimumDurationsMet"])
            self.assertGreaterEqual(report["wallClockElapsedMs"], 98.0)
            self.assertGreaterEqual(elapsed_ms, 98.0)
            self.assertEqual([row["waitAfterMs"] for row in report["events"]], [8, 7, 5])
            self.assertTrue(all(row["minimumDurationMet"] for row in report["events"]))
            self.assertTrue(all(row["timingShortfallMs"] <= 2.0 for row in report["events"]))
            self.assertLessEqual(
                report["events"][0]["timelineEndMs"],
                report["events"][1]["timelineStartMs"] + 2.0,
            )
            key_down = next(row for row in fake.calls if row[0] == "Input.dispatchKeyEvent" and row[2].get("type") == "keyDown")
            key_up = next(row for row in fake.calls if row[0] == "Input.dispatchKeyEvent" and row[2].get("type") == "keyUp")
            self.assertGreaterEqual((key_up[1] - key_down[1]) * 1000.0, 18.0)
            motion_calls = [row for row in fake.calls if row[0] == "Input.dispatchMouseEvent" and "deltaX" in row[2]]
            self.assertEqual(len(motion_calls), 3)
            self.assertAlmostEqual(sum(float(row[2]["deltaX"]) for row in motion_calls), 12.0, places=5)
            self.assertAlmostEqual(sum(float(row[2]["deltaY"]) for row in motion_calls), -6.0, places=5)

            captured_timeout: dict[str, int] = {}

            def fake_run_sync(**kwargs: Any) -> dict[str, Any]:
                captured_timeout["seconds"] = int(kwargs["timeout_seconds"])
                return {
                    "schema": "browser_demo_playback.v303",
                    "success": True,
                    "playback": {},
                    "artifacts": {},
                }

            async def fake_augment(
                _ctx: ToolContext, result: dict[str, Any],
            ) -> dict[str, Any]:
                return result

            tool._run_sync = fake_run_sync  # type: ignore[method-assign]
            tool._augment_visual_evidence = fake_augment  # type: ignore[method-assign]

            async def undersized_timeout_is_corrected() -> dict[str, Any]:
                return await tool.run_demo_playback(
                    velox.ToolContext(scope_id=velox.APP_SCOPE_ID, chat_id=chat_id),
                    {
                        "target": "about:blank",
                        "viewportWidth": 1280,
                        "viewportHeight": 720,
                        "events": [{"type": "delay", "durationMs": 6000}],
                        "timeoutSeconds": 5,
                    },
                )

            adjusted = asyncio.run(undersized_timeout_is_corrected())
            adjusted_meta = adjusted["playback"]
            self.assertEqual(adjusted_meta["requestedTimeoutSeconds"], 5)
