            self.assertIn("raised from 5 to 48", adjusted["warning"])
            web = velox.build_web_programming_skill_markdown(
                host_os="Windows",
                chrome_path=r"C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe",
                node_path="",
            )
