class ResponsesAndTaskInspectionTests(_DataRootsIsolatedTestMixin, unittest.TestCase):
    """Responses transport, streamed tool construction and task inspection."""


    @staticmethod
    def _fake_response(data: bytes, url: str):
        class FakeResponse:
            status = 200
            headers: dict[str, str] = {}
            def __init__(self) -> None:
                self._stream = io.BytesIO(data)
            def __enter__(self) -> "FakeResponse": return self
            def __exit__(self, *_args: Any) -> None: return None
            def read(self, limit: int = -1) -> bytes: return self._stream.read(limit)
            def readline(self, limit: int = -1) -> bytes: return self._stream.readline(limit)
            def getcode(self) -> int: return 200
            def geturl(self) -> str: return url
            def close(self) -> None: return None
        return FakeResponse()

    def test_gpt_sol_uses_responses_and_other_endpoints_keep_chat_completions(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            _paths, storage, _chats = _make_test_chat_stack(Path(td))
            client = velox.LLMClient(storage)
            config = storage.load_config()
            gpt = velox.endpoint_profile_ref(config, velox.DEFAULT_GPT_5_6_SOL_ENDPOINT_PROFILE_ID)
            deepseek = velox.endpoint_profile_ref(config, velox.DEFAULT_DEEPSEEK_V4_FLASH_0731_ENDPOINT_PROFILE_ID)
            self.assertEqual(gpt["base_url"], "https://api.openai.com/v1/responses")
            self.assertTrue(client._uses_openai_responses(gpt))
            self.assertFalse(client._uses_openai_responses(deepseek))
            request = velox.LLMRequest(
                scope_id=velox.APP_SCOPE_ID,
                endpoint_profile_id=velox.DEFAULT_DEEPSEEK_V4_FLASH_0731_ENDPOINT_PROFILE_ID,
                messages=[{"role": "user", "content": "hello"}],
                native_tools=[{"type": "function", "function": {
                    "name": "time_now", "description": "time", "parameters": {"type": "object", "properties": {}},
                }}],
            )
            _endpoint, url, _body, _headers, _timeout, payload = client._payload_and_headers(request, stream=True)
            self.assertTrue(url.endswith("/v1/chat/completions"))
            self.assertIn("messages", payload)
            self.assertNotIn("input", payload)
            self.assertIn("tools", payload)
            self.assertIn("function", payload["tools"][0])

