    def test_responses_stream_emits_partial_and_final_function_state(self) -> None:
        async def scenario(root: Path) -> None:
            _paths, storage, _chats = _make_test_chat_stack(root)
            client = velox.LLMClient(storage)
            def event(obj: dict[str, Any]) -> bytes:
                return b"data: " + json.dumps(obj).encode() + b"\n\n"
            final_output = [
                {"id": "rs_1", "type": "reasoning", "encrypted_content": "opaque", "summary": [
                    {"type": "summary_text", "text": "Use the tool."},
                ]},
                {"id": "fc_1", "type": "function_call", "call_id": "call_1", "name": "time_now", "arguments": "{}"},
            ]
            body = b"".join([
                event({"type": "response.created", "response": {"id": "resp_1", "status": "in_progress"}}),
                event({"type": "response.reasoning_summary_text.delta", "delta": "Use the tool."}),
                event({"type": "response.output_item.added", "output_index": 1, "item": {
                    "id": "fc_1", "type": "function_call", "call_id": "call_1", "name": "time_now", "arguments": "",
                }}),
                event({"type": "response.function_call_arguments.delta", "output_index": 1, "item_id": "fc_1", "delta": "{"}),
                event({"type": "response.function_call_arguments.delta", "output_index": 1, "item_id": "fc_1", "delta": "}"}),
                event({"type": "response.completed", "response": {
                    "id": "resp_1", "model": "gpt-5.6-sol", "status": "completed", "output": final_output,
                    "usage": {"input_tokens": 5, "output_tokens": 7, "total_tokens": 12},
                }}),
                b"data: [DONE]\n\n",
            ])
            response = self._fake_response(body, "https://api.openai.com/v1/responses")
            chunks: list[LLMChunk] = []
            with mock.patch.object(urllib.request, "urlopen", return_value=response):
                async for chunk in client.chat_completions_stream(velox.LLMRequest(
                    scope_id=velox.APP_SCOPE_ID,
                    endpoint_profile_id=velox.DEFAULT_GPT_5_6_SOL_ENDPOINT_PROFILE_ID,
                    messages=[{"role": "user", "content": "time?"}],
                    native_tools=[{"type": "function", "function": {
                        "name": "time_now", "description": "time", "parameters": {"type": "object", "properties": {}},
                    }}],
                )):
                    chunks.append(chunk)
            call_chunks = [chunk for chunk in chunks if chunk.native_tool_calls]
            self.assertGreaterEqual(len(call_chunks), 1)
            self.assertEqual(call_chunks[0].native_tool_calls[0]["function"]["name"], "time_now")
            terminal = chunks[-1]
            self.assertTrue(terminal.done)
            self.assertEqual(terminal.native_tool_calls[0]["function"]["arguments"], "{}")
            self.assertEqual(terminal.response_output_items, final_output)
            self.assertEqual(terminal.finish_reason, "tool_calls")
        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

