    def test_turn_schema_and_bridge_preserve_responses_output_items(self) -> None:
        turn = velox.make_turn(velox.uuid_v4(), "assistant", "text")
        self.assertEqual(turn["response_output_items"], [])
        velox.validate_chat_turn_record(turn, turn["chat_id"])
        async def scenario() -> None:
            bridge = velox.LLMStreamChunkBridge(asyncio.get_running_loop(), flush_seconds=0.0)
            items = [{"id": "rs_1", "type": "reasoning", "encrypted_content": "opaque"}]
            bridge.publish(velox.LLMChunk(response_output_items=items))
            bridge.close()
            chunk = await bridge.queue.get()
            self.assertEqual(chunk.response_output_items, items)
        asyncio.run(scenario())
        response_heavy_message = {
            "role": "assistant",
            "content": "",
            "response_output_items": [{
                "type": "reasoning",
                "encrypted_content": "opaque-" * 200,
            }],
        }
        self.assertGreater(
            velox.AgentRuntime._estimate_messages_tokens([response_heavy_message]), 4,
        )
        chat_runtime = velox.ChatRuntime.__new__(velox.ChatRuntime)
        self.assertGreater(
            velox.ChatRuntime._estimate_messages_tokens(chat_runtime, [response_heavy_message]), 4,
        )


