    def test_browser_viewport_defaults_and_bounds(self) -> None:
        self.assertEqual((velox.BrowserTools.VIEWPORT_RECOMMENDED_WIDTH, velox.BrowserTools.VIEWPORT_RECOMMENDED_HEIGHT), (1920, 1080))
        self.assertEqual((velox.BrowserTools.VIEWPORT_MIN_WIDTH, velox.BrowserTools.VIEWPORT_MIN_HEIGHT), (1280, 720))
        self.assertEqual((velox.BrowserTools.VIEWPORT_MAX_WIDTH, velox.BrowserTools.VIEWPORT_MAX_HEIGHT), (3820, 2160))
        self.assertEqual(velox.BrowserTools._bounded_integer(1920, "viewportWidth", 1280, 3820), 1920)
        for value, name, low, high in (
            (1279, "viewportWidth", 1280, 3820),
            (3821, "viewportWidth", 1280, 3820),
            (719, "viewportHeight", 720, 2160),
            (2161, "viewportHeight", 720, 2160),
        ):
            with self.assertRaises(ValueError):
                velox.BrowserTools._bounded_integer(value, name, low, high)
        with tempfile.TemporaryDirectory() as td:
            _paths, storage, _chats = _make_test_chat_stack(Path(td))
            tools = velox.ToolRegistry(storage)
            for tool_name in ("browser_run_headless", "browser_demo_playback"):
                props = tools.tools[tool_name].parameters["properties"]
                self.assertEqual((props["viewportWidth"]["minimum"], props["viewportWidth"]["maximum"]), (1280, 3820))
                self.assertEqual((props["viewportHeight"]["minimum"], props["viewportHeight"]["maximum"]), (720, 2160))
                self.assertIn("1920x1080", tools.tools[tool_name].description)
        self.assertIn("1920x1080", velox.ContextAssembler.BROWSER_VERIFICATION_GUIDANCE)
        web_skill = velox.build_web_programming_skill_markdown(host_os="TestOS", chrome_path="", node_path="")
        self.assertIn("1280x720", web_skill)
        self.assertIn("3820x2160", web_skill)

    def test_chat_list_order_is_created_at_stable_not_updated_at(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            paths, storage, chats = _make_test_chat_stack(Path(td))
            older = chats.create_chat("Older")
            newer = chats.create_chat("Newer")
            older["created_at"] = "2026-01-01T00:00:00Z"
            older["updated_at"] = "2026-12-31T00:00:00Z"
            newer["created_at"] = "2026-02-01T00:00:00Z"
            newer["updated_at"] = "2026-02-01T00:00:00Z"
            velox.atomic_write_json(paths.chat_json(older["chat_id"]), older)
            velox.atomic_write_json(paths.chat_json(newer["chat_id"]), newer)
            store = velox.ChatStore(storage)
            self.assertEqual(
                [row["chat_id"] for row in store.list_chats(velox.APP_SCOPE_ID)],
                [newer["chat_id"], older["chat_id"]],
            )
            store.rename_chat(velox.APP_SCOPE_ID, older["chat_id"], "Older renamed later")
            self.assertEqual(
                [row["chat_id"] for row in store.list_chats(velox.APP_SCOPE_ID)],
                [newer["chat_id"], older["chat_id"]],
            )

    def test_active_chat_list_pulse_covers_inference_and_tools(self) -> None:
        self.assertAlmostEqual(velox.Panels._chat_activity_pulse(0.0), 0.5, places=6)
        self.assertAlmostEqual(velox.Panels._chat_activity_pulse(1.95 / 4.0), 1.0, places=6)
        self.assertAlmostEqual(velox.Panels._chat_activity_pulse(1.95 * 3.0 / 4.0), 0.0, places=6)
        self.assertAlmostEqual(1.95, 2.6 * 0.75, places=6)
        panel = velox.Panels.__new__(velox.Panels)
        panel.services = SimpleNamespace(
            chat=SimpleNamespace(is_running=lambda chat_id: chat_id == "inference"),
            tools=SimpleNamespace(has_active_chat_tool_calls=lambda chat_id: chat_id == "tool"),
        )
        self.assertTrue(panel._chat_list_is_working("inference"))
        self.assertTrue(panel._chat_list_is_working("tool"))
        self.assertFalse(panel._chat_list_is_working("idle"))
        source = inspect.getsource(velox.Panels.draw_chat_list)
        color_source = inspect.getsource(velox.Panels._chat_activity_colors)
        self.assertIn("Palette.selected", color_source)
        self.assertIn("Palette.primary_hover", color_source)
        self.assertIn("Palette.panel", color_source)
        self.assertIn("Palette.hover", color_source)
        self.assertIn("glow_color", source)
        self.assertEqual(velox.CHAT_ACTIVITY_GLOW_RANGE_MULTIPLIER, 1.20)
        active_low = velox.Panels._chat_activity_colors(True, 0.0)
        active_high = velox.Panels._chat_activity_colors(True, 1.0)
        idle_low = velox.Panels._chat_activity_colors(False, 0.0)
        idle_high = velox.Panels._chat_activity_colors(False, 1.0)
        self.assertEqual(active_high[1].a - active_low[1].a, round(33 * 1.20))
        self.assertEqual(active_high[2].a - active_low[2].a, round(88 * 1.20))
        self.assertEqual(idle_high[1].a - idle_low[1].a, round(19 * 1.20))
        self.assertEqual(idle_high[2].a - idle_low[2].a, round(45 * 1.20))
        self.assertIn("_chat_activity_colors(active, pulse)", source)


