    def test_cdp_screenshot_capture_has_no_bound_extra_argument(self) -> None:
        payload = b"not-a-real-png-but-exact-cdp-bytes"
        class FakeWebSocket:
            def command(self, method: str, params: dict[str, Any], **kwargs: Any) -> dict[str, Any]:
                self.method = method
                self.params = params
                self.kwargs = kwargs
                return {"data": base64.b64encode(payload).decode("ascii")}
        with tempfile.TemporaryDirectory() as td:
            output = Path(td) / "capture.png"
            websocket = FakeWebSocket()
            # Calling through the class reproduced the previous classmethod binding
            # failure: the descriptor injected an extra positional argument.
            size = velox.BrowserTools._capture_cdp_screenshot(
                websocket, output, time.monotonic() + 10.0,
            )
            self.assertEqual(size, len(payload))
            self.assertEqual(output.read_bytes(), payload)
            self.assertEqual(websocket.method, "Page.captureScreenshot")
            self.assertTrue(websocket.params["fromSurface"])
        descriptor = inspect.getattr_static(velox.BrowserTools, "_capture_cdp_screenshot")
        self.assertIsInstance(descriptor, staticmethod)

    def test_image_debug_tools_are_registered_and_operational(self) -> None:
        try:
            from PIL import Image, ImageDraw  # type: ignore
        except Exception as exc:  # pragma: no cover - Pillow is a Velox dependency
            self.skipTest(f"Pillow unavailable: {exc}")
        with tempfile.TemporaryDirectory() as td:
            paths, storage, chats = _make_test_chat_stack(Path(td))
            chat = chats.create_chat("Image probes")
            chat_id = str(chat["chat_id"])
            first_path = paths.chat_workspace_dir(chat_id) / "first.png"
            second_path = paths.chat_workspace_dir(chat_id) / "second.png"
            first = Image.new("RGBA", (64, 48), (0, 0, 0, 255))
            draw = ImageDraw.Draw(first)
            draw.rectangle((16, 12, 47, 35), fill=(255, 0, 0, 255))
            first.save(first_path)
            second = first.copy()
            draw2 = ImageDraw.Draw(second)
            draw2.rectangle((32, 16, 55, 39), fill=(0, 255, 0, 255))
            second.save(second_path)
            tools = velox.ImageTools(storage)
            ctx = velox.ToolContext(velox.APP_SCOPE_ID, chat_id=chat_id)
            point = tools.pixel_probe(ctx, {
                "path": str(first_path), "x": 20, "y": 20, "radius": 1,
            })
            self.assertEqual(point["point"]["rgba"], [255, 0, 0, 255])
            region = tools.region_stats(ctx, {
                "path": str(first_path), "x": 0, "y": 0, "width": 64, "height": 48,
            })
            self.assertGreater(region["stddev_rgba"][0], 0)
            compared = tools.compare_images(ctx, {
                "path1": str(first_path), "path2": str(second_path), "output_path": "",
            })
            self.assertGreater(compared["changed_pixels"], 0)
            self.assertTrue(Path(compared["heatmap_path"]).is_file())
            edges = tools.edge_map(ctx, {
                "path": str(first_path), "output_path": "", "threshold": 16,
            })
            self.assertGreater(edges["edge_pixels"], 0)
            self.assertTrue(Path(edges["output_path"]).is_file())
            blank = tools.blank_region_scan(ctx, {
                "path": str(first_path), "tile_size": 16, "tolerance": 0,
            })
            self.assertGreaterEqual(blank["uniform_edge_bands"]["top"], 5)
            self.assertGreater(blank["blank_tile_count"], 0)
            registry = velox.ToolRegistry(storage)
            for name in (
                "image_pixel_probe", "image_region_stats", "image_compare",
                "image_edge_map", "image_blank_region_scan",
            ):
                self.assertIn(name, registry.tools)
                self.assertIn(name, velox.TOOL_POSITIONAL_SIGNATURES)

    def test_completed_tool_snapshot_retains_exact_raw_result(self) -> None:
        async def scenario(root: Path) -> None:
            paths, storage, chats = _make_test_chat_stack(root)
            chat = chats.create_chat("Tool result details")
            chat_id = str(chat["chat_id"])
            source = paths.chat_workspace_dir(chat_id) / "lines.txt"
            source.write_text("alpha\nbeta\n", encoding="utf-8")
            registry = velox.ToolRegistry(storage)
            result = await registry.execute_tool_call(
                velox.APP_SCOPE_ID,
                {"name": "fs_read_lines", "arguments": {
                    "filepath": str(source), "startLine": 0, "numLines": 1,
                }},
                chat_id=chat_id,
            )
            self.assertTrue(result["ok"], result)
            snapshot = registry.tool_execution_snapshot(str(result["tool_call_id"]))
            self.assertIsInstance(snapshot.get("result"), dict)
            self.assertIn("alpha", str(snapshot["result"].get("text") or ""))
            panel = velox.Panels.__new__(velox.Panels)
            detail_text = panel._tool_raw_result_text(snapshot)
            self.assertIn("alpha", detail_text)
            self.assertNotEqual(detail_text.strip(), "null")
            old_snapshot_text = panel._tool_raw_result_text({
                "ok": True, "status": "complete", "result": None,
                "output_excerpt": "legacy concise snapshot",
            })
            self.assertIn("result_unavailable_in_snapshot", old_snapshot_text)
            self.assertNotEqual(old_snapshot_text.strip(), "null")
        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_streaming_chat_reuses_unchanged_sections(self) -> None:
        panel = velox.Panels.__new__(velox.Panels)
        panel.state = velox.UIState()
        chat_id = velox.uuid_v4()
        first_turn = velox.make_turn(chat_id, "user", "first stable turn")
        second_turn = velox.make_turn(chat_id, "assistant", "stream one", status="streaming")
        turns = [first_turn, second_turn]
        first_sections = panel._chat_sections(turns, True)
        stable = next(section for section in first_sections if section.get("turn") is first_turn)
        changing = next(section for section in first_sections if section.get("turn") is second_turn)
        second_turn["text"] = "stream two with more text"
        second_turn["updated_at"] = velox.now_iso()
        second_sections = panel._chat_sections(turns, True)
        stable_after = next(section for section in second_sections if section.get("turn") is first_turn)
        changing_after = next(section for section in second_sections if section.get("turn") is second_turn)
        self.assertIs(stable_after, stable)
        self.assertIsNot(changing_after, changing)
        renderer_init = inspect.getsource(velox.Renderer.__init__)
        renderer_text = inspect.getsource(velox.Renderer._render_cached_text)
        self.assertIn("collections.deque", renderer_init)
        self.assertIn("_text_texture_admission_counts", renderer_init)
        self.assertIn("if seen < 2", renderer_text)
        self.assertIn("order.popleft()", renderer_text)
        self.assertNotIn("order.pop(0)", renderer_text)


    def test_agent_metrics_duration_tooltip_and_debug_report(self) -> None:
        agent = {
            "agent_id": "agent-1", "title": "Build report", "status": "succeeded",
            "created_at": "2026-08-12T00:00:00Z", "started_at": "2026-08-12T00:00:10Z",
            "completed_at": "2026-08-12T01:02:13Z", "active_seconds": 3732.6,
            "input_tokens": 1200, "output_tokens": 300, "llm_turn_count": 2,
            "stats": {
                "schema": velox.TOOL_USAGE_STATS_SCHEMA,
                "tool_calls_total": 4, "tool_calls_succeeded": 3, "tool_calls_failed": 1,
                "tool_calls_by_type": {
                    "fs_read": {"total": 2, "succeeded": 2, "failed": 0},
                    "fs_write": {"total": 2, "succeeded": 1, "failed": 1},
                },
            },
        }
        events = [
            {"kind": "llm_output", "data": {
                "input_tokens": 1200, "output_tokens": 300,
                "usage": {"prompt_seconds": 2.0, "generation_seconds": 3.0},
            }},
            {"kind": "context_compacted", "data": {}},
        ]
        metrics = velox.agent_task_statistics(agent, events)
        self.assertEqual(metrics["duration_hms"], "01:02:13")
        self.assertEqual(metrics["tool_call_success_rate"], 75.0)
        self.assertEqual(metrics["average_prompt_tokens_per_second"], 600.0)
        self.assertEqual(metrics["average_generation_tokens_per_second"], 100.0)
        tooltip = velox.agent_statistics_tooltip(agent, events)
        for phrase in ("Duration: 01:02:13", "Input: 600.00 t/s", "Generated: 100.00 t/s", "Tool success: 75.0% (3/4)"):
            self.assertIn(phrase, tooltip)
        report = velox.format_agent_debug_report(agent, events, endpoint={"label": "Example"}, source_chat={"chat_id": "chat-1"}, data_root="C:/velox")
        self.assertIn("VELOX AGENT DEBUG REPORT", report)
        self.assertIn("Build report", report)
        self.assertIn("01:02:13", report)
        rows = velox.agent_tool_statistics_rows(agent)
        self.assertEqual([row["tool"] for row in rows], ["fs_read", "fs_write"])

    def test_agent_context_menu_has_shared_actions_and_agents_exception(self) -> None:
        panel = velox.Panels.__new__(velox.Panels)
        base_agent = {
            "agent_id": "agent-1", "status": "running", "pause_requested": False,
            "source_chat_id": "chat-1",
        }
        chat_items = panel._agent_row_context_items(base_agent)
        agent_items = panel._agent_row_context_items(base_agent, include_source_chat=True)
        chat_actions = [row["action"] for row in chat_items]
        agent_actions = [row["action"] for row in agent_items]
        for action in ("view", "terminals", "statistics", "export_debug", "pause", "cancel", "delete"):
            self.assertIn(action, chat_actions)
            self.assertIn(action, agent_actions)
        self.assertNotIn("open_source_chat", chat_actions)
        self.assertIn("open_source_chat", agent_actions)
        paused = panel._agent_row_context_items({**base_agent, "status": "paused"})
        self.assertIn("resume", [row["action"] for row in paused])
        terminal = panel._agent_row_context_items({**base_agent, "status": "succeeded"})
        terminal_map = {row["action"]: row for row in terminal}
        self.assertFalse(terminal_map["cancel"]["enabled"])
        self.assertTrue(terminal_map["delete"]["enabled"])


