class CalendarLayoutAndStartupTests(_DataRootsIsolatedTestMixin, unittest.TestCase):
    """Calendar layout, connector controls and startup."""


    @staticmethod
    def _stack(root: Path) -> tuple[AppPaths, Storage, ChatStore, CalendarStore, GoogleCalendarIntegration]:
        paths = velox.AppPaths(root)
        storage = velox.Storage(paths)
        storage.ensure_first_run_files()
        chats = velox.ChatStore(storage)
        calendar = velox.CalendarStore(storage)
        return paths, storage, chats, calendar, velox.GoogleCalendarIntegration(storage, calendar)

    def test_calendar_right_cards_resize_vertically_and_persist(self) -> None:
        low = velox.calendar_layout_for_rect(
            velox.Rect(0, 0, 1920, 900), backlog_expanded=False,
            right_split_fraction=0.30,
        )
        high = velox.calendar_layout_for_rect(
            velox.Rect(0, 0, 1920, 900), backlog_expanded=False,
            right_split_fraction=0.78,
        )
        self.assertLess(low.week_chat.h, high.week_chat.h)
        self.assertGreater(low.agent_tasks.h, high.agent_tasks.h)
        self.assertEqual(low.week_chat.y + low.week_chat.h, low.right_stack_divider.y)
        self.assertEqual(
            low.right_stack_divider.y + low.right_stack_divider.h,
            low.agent_tasks.y,
        )
        source = inspect.getsource(velox.Panels._calendar_handle_dividers)
        for token in (
            'calendar_divider_dragging == "right_stack"',
            'requested_cursor = "resize_y"',
            'calendar_right_split_fraction',
            'CALENDAR_RIGHT_SPLIT_MIN',
            'CALENDAR_RIGHT_SPLIT_MAX',
        ):
            self.assertIn(token, source)
        with tempfile.TemporaryDirectory() as td:
            _paths, storage, _chats, _calendar, _integration = self._stack(Path(td))
            state = storage.load_app_state()
            state["calendar_right_split_fraction"] = 0.41
            storage.write_app_state(state)
            self.assertAlmostEqual(storage.load_app_state()["calendar_right_split_fraction"], 0.41)

    def test_backlog_rail_is_a_bidirectional_toggle(self) -> None:
        class FakeRenderer:
            def draw_card(self, *_args: Any, **_kwargs: Any) -> None: pass
        class FakeWidgets:
            def __init__(self) -> None:
                self.labels: list[str] = []
                self.tooltips: list[str] = []
            def _can_receive_pointer(self, _widget_id: str) -> bool: return True
            def _queue_tooltip(self, _widget_id: str, _rect: Rect, text: str) -> None: self.tooltips.append(text)
            def clipped_text(self, _rect: Rect, text: str, *_args: Any, **_kwargs: Any) -> None: self.labels.append(text)
        panel = velox.Panels.__new__(velox.Panels)
        panel.state = velox.UIState()
        panel.widgets = FakeWidgets()
        panel.widgets.renderer = FakeRenderer()
        panel.widgets.font = SimpleNamespace(line_h=20)
        rect = velox.Rect(0, 0, velox.CALENDAR_BACKLOG_RAIL_W, 500)
        panel.state.input.mouse_x = 10
        panel.state.input.mouse_y = 10
        panel.state.input.mouse_pressed = True
        panel._draw_calendar_backlog_rail(rect, [])
        self.assertTrue(panel.state.calendar_backlog_expanded)
        self.assertIn(">", panel.widgets.labels)
        panel.state.input.mouse_consumed = False
        panel.state.input.mouse_pressed = True
        panel.widgets.labels.clear()
        panel._draw_calendar_backlog_rail(rect, [])
        self.assertFalse(panel.state.calendar_backlog_expanded)
        self.assertIn("<", panel.widgets.labels)
        source = inspect.getsource(velox.Panels._draw_calendar_backlog_rail)
        self.assertIn("self.state.calendar_backlog_expanded = not expanded", source)

    def test_calendar_sync_window_and_missing_sync_token_fallback(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            _paths, storage, _chats, calendar, integration = self._stack(Path(td))
            config = storage.load_config()
            config["vault"]["google_calendar"]["sync_window_days"] = 180
            storage.write_config(config)
            window_start, window_end, days = velox.google_calendar_sync_window(
                storage.load_config(), today=date(2026, 8, 12),
            )
            self.assertEqual(days, 180)
            self.assertEqual(window_start, "2026-05-14T00:00:00Z")
            self.assertEqual(window_end, "2026-11-10T00:00:00Z")
            calendar_row = GoogleCalendarTests._calendar_resource()
            event = GoogleCalendarTests._timed_event(
                "bounded-event", start="2026-08-12T10:00:00-04:00", end="2026-08-12T11:00:00-04:00",
            )
            service = _FakeGoogleService(
                lambda _kwargs, _index: {"items": [calendar_row], "nextSyncToken": "list-token"},
                lambda _kwargs, _index: {"items": [event]},
            )
            integration._refresh_locked(service)
            integration.set_calendar_enabled("mike@example.com", True)
            result = integration._refresh_locked(service)
            self.assertEqual(result["calendars_succeeded"], 1)
            self.assertEqual(len(calendar.list_events_for_date("2026-08-12")), 1)
            event_call = service.events_resource.calls[-1]
            self.assertIn("timeMin", event_call)
            self.assertIn("timeMax", event_call)
            self.assertNotIn("orderBy", event_call)
            self.assertNotIn("syncToken", event_call)
            row = calendar.get_google_sync_state()["calendars"][0]
            self.assertEqual(row["sync_token"], "")
            self.assertIn("did not return a nextSyncToken", row["last_error"])
            self.assertTrue(result["warnings"])

