class CalendarGridAndGoogleSyncTests(_DataRootsIsolatedTestMixin, unittest.TestCase):
    """Calendar hour-grid geometry and Google event synchronization."""


    @staticmethod
    def _stack(root: Path) -> tuple[AppPaths, Storage, VaultStore, CredentialStore]:
        paths = velox.AppPaths(root)
        storage = velox.Storage(paths)
        storage.ensure_first_run_files()
        return paths, storage, velox.VaultStore(storage), velox.CredentialStore(paths)

    def test_week_uses_24_hour_grid_and_overlap_lanes(self) -> None:
        self.assertEqual(velox.calendar_hour_label(0), "0000")
        self.assertEqual(velox.calendar_hour_label(1), "0100")
        self.assertEqual(velox.calendar_hour_label(13), "1300")
        self.assertEqual(velox.calendar_hour_label(23), "2300")
        blocks = velox.calendar_timeline_lane_assignments([
            ("event", "anchor", 0, 100),
            ("event", "early", 0, 30),
            ("event", "short", 0, 20),
            ("event", "middle", 20, 80),
            ("event", "bridge", 30, 60),
            ("event", "expand", 80, 100),
        ])
        by_id = {row.object_id: row for row in blocks}
        self.assertEqual(by_id["anchor"].lane, 0)
        self.assertEqual(by_id["early"].lane, 1)
        self.assertEqual(by_id["short"].lane, 2)
        self.assertEqual(by_id["expand"].lane, 1)
        self.assertEqual(by_id["expand"].lane_count, 3)
        self.assertEqual(by_id["expand"].lane_span, 2)
        anchor = velox.calendar_timeline_lane_rect(velox.Rect(0, 0, 300, 300), by_id["anchor"], top=0, height=60)
        one = velox.calendar_timeline_lane_rect(velox.Rect(0, 0, 300, 300), by_id["early"], top=0, height=60)
        short = velox.calendar_timeline_lane_rect(velox.Rect(0, 0, 300, 300), by_id["short"], top=0, height=60)
        expanded = velox.calendar_timeline_lane_rect(velox.Rect(0, 0, 300, 300), by_id["expand"], top=0, height=60)
        self.assertEqual(anchor.x, 0)
        self.assertEqual(anchor.w, 300)
        self.assertGreater(one.x, anchor.x)
        self.assertGreater(short.x, one.x)
        self.assertGreater(anchor.x + anchor.w, one.x)  # horizontal overlap, not equal columns
        self.assertEqual(anchor.x + anchor.w, one.x + one.w)
        self.assertEqual(one.x + one.w, short.x + short.w)
        self.assertEqual(expanded.w, one.w)
        timeline = inspect.getsource(velox.Panels._draw_calendar_timeline)
        for token in (
            "for hour in range(25)", "calendar_hour_label(hour)",
            "draw_dashed", "calendar_timeline_lane_assignments",
            'scroll_id = "calendar.week.timeline"',
        ):
            self.assertIn(token, timeline)
        week_day = inspect.getsource(velox.Panels._draw_calendar_week_day)
        self.assertIn("_draw_calendar_timeline", week_day)
        self.assertIn("timed_events", week_day)
        self.assertNotIn("entries.sort", week_day)

