    def test_gmail_history_window_filters_and_prunes_existing_messages(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            _paths, storage, vault, credentials = self._stack(Path(td))
            credentials.save_gmail("mike@example.com", "app password")
            config = storage.load_config()
            config["vault"]["gmail"]["enabled"] = True
            config["vault"]["gmail"]["initial_history_days"] = 365
            storage.write_config(config)
            old_raw = ConnectorTests._gmail_message("Old", "old body")
            recent_raw = ConnectorTests._gmail_message("Recent", "recent body")
            fake = ConnectorTests._FakeIMAP({
                1: {"msgid": "10001", "raw": old_raw, "internaldate": "01-May-2026 12:00:00 +0000"},
                2: {"msgid": "10002", "raw": recent_raw, "internaldate": "05-Aug-2026 12:00:00 +0000"},
            })
            fixed_now = lambda: datetime(2026, 8, 12, 12, 0, tzinfo=timezone.utc)
            connector = velox.GmailConnector(
                storage, vault, credentials,
                imap_factory=lambda *_args, **_kwargs: fake,
                now=fixed_now,
            )
            first = asyncio.run(connector.sync())
            self.assertEqual(first["processed"], 2)
            source = next(row for row in vault.list_data_sources() if row["source_type"] == "gmail")
            self.assertEqual(len(vault.list_items(source_id=source["id"])), 2)

            config = storage.load_config()
            config["vault"]["gmail"]["initial_history_days"] = 30
            storage.write_config(config)
            second = asyncio.run(connector.sync())
            visible = vault.list_items(source_id=source["id"], include_deleted=False)
            self.assertEqual([row["external_id"] for row in visible], ["10002"])
            self.assertGreaterEqual(second["history_pruned"] + second["tombstoned"], 1)
            self.assertTrue(any("X-GM-RAW" in " ".join(call) for call in fake.search_calls))

