    def test_calendar_cascade_keeps_base_broad_and_layers_later_cards(self) -> None:
        blocks = velox.calendar_timeline_lane_assignments([
            ("event", "long", 9 * 60, 16 * 60),
            ("event", "short", 10 * 60, 11 * 60),
            ("event", "third", 10 * 60 + 15, 10 * 60 + 45),
        ])
        by_id = {row.object_id: row for row in blocks}
        content = velox.Rect(100, 0, 320, 900)
        base = velox.calendar_timeline_lane_rect(content, by_id["long"], top=0, height=400)
        short = velox.calendar_timeline_lane_rect(content, by_id["short"], top=80, height=80)
        third = velox.calendar_timeline_lane_rect(content, by_id["third"], top=100, height=40)
        self.assertEqual((base.x, base.w), (content.x, content.w))
        self.assertGreater(short.x, base.x)
        self.assertGreater(third.x, short.x)
        self.assertEqual(short.x + short.w, content.x + content.w)
        self.assertEqual(third.x + third.w, content.x + content.w)
        self.assertLess(short.w, base.w)
        two = velox.calendar_timeline_lane_assignments([
            ("event", "base", 9 * 60, 16 * 60),
            ("event", "overlay", 10 * 60, 11 * 60),
        ])
        two_by_id = {row.object_id: row for row in two}
        overlay = velox.calendar_timeline_lane_rect(content, two_by_id["overlay"], top=80, height=80)
        self.assertEqual(overlay.x, content.x + int(round(content.w * 0.20)))
        self.assertEqual(overlay.x + overlay.w, content.x + content.w)
        source = inspect.getsource(velox.Panels._draw_calendar_timeline)
        self.assertIn("render_rows.sort", source)
        self.assertIn("int(row[\"block\"].lane)", source)
        self.assertIn("for row in reversed(render_rows)", source)

