    def test_stall_detection_setting_and_general_card_tooltips(self) -> None:
        config = velox.default_config()
        self.assertEqual(
            config["llm"]["stall_detection_minutes"],
            velox.LLM_ACTIVITY_STALL_WARNING_MINUTES_DEFAULT,
        )
        self.assertEqual(velox.llm_activity_stall_warning_seconds(config), 15 * 60.0)

        panel = velox.Panels.__new__(velox.Panels)
        panel.state = velox.UIState()
        draft = copy.deepcopy(config)
        draft["llm"]["stall_detection_minutes"] = "22.5"
        sanitized = panel._sanitized_settings_config(draft)
        self.assertEqual(sanitized["llm"]["stall_detection_minutes"], 22.5)

        with tempfile.TemporaryDirectory() as td:
            storage = velox.Storage(velox.AppPaths(Path(td)))
            storage.ensure_first_run_files()
            monitor = velox.LLMTaskMonitor(storage)
            self.assertEqual(monitor.activity_stall_warning_seconds(), 15 * 60.0)
            updated = storage.load_config()
            updated["llm"]["stall_detection_minutes"] = 20.0
            storage.write_config(updated)
            self.assertEqual(monitor.activity_stall_warning_seconds(), 20 * 60.0)
            with mock.patch.object(time, "monotonic", return_value=100.0):
                task_id = monitor.start(velox.APP_SCOPE_ID, "threshold", task_kind="chat")
                monitor.set_phase(task_id, "inference")
                monitor.set_activity(task_id, "prompt", restart_timer=True)
            with mock.patch.object(time, "monotonic", return_value=100.0 + 15 * 60.0 + 1.0):
                self.assertFalse(monitor.record_snapshot(task_id)["activity_stalled"])
            with mock.patch.object(time, "monotonic", return_value=100.0 + 20 * 60.0 + 1.0):
                self.assertTrue(monitor.record_snapshot(task_id)["activity_stalled"])

            invalid = storage.load_config()
            invalid["llm"]["stall_detection_minutes"] = 0.5
            with self.assertRaisesRegex(velox.UnsupportedDataVersionError, "stall_detection_minutes"):
                storage.write_config(invalid)

        one_control_h = panel._settings_card_height_for_content(velox.SETTINGS_CONTROL_H)
        heights = panel._general_settings_card_heights(1200)
        self.assertEqual(heights[2:7], (one_control_h,) * 5)
        self.assertTrue(hasattr(velox.Panels, "_draw_chat_compaction_settings_card"))
        general_source = inspect.getsource(velox.Panels._draw_general_settings_content)
        self.assertIn("_draw_chat_compaction_settings_card", general_source)
        self.assertIn("_draw_inference_diagnostics_card", general_source)

        deletion_source = inspect.getsource(velox.Panels._draw_deletion_settings_card)
        document_source = inspect.getsource(velox.Panels._draw_document_handling_card)
        timezone_source = inspect.getsource(velox.Panels._draw_timezone_settings_card)
        self.assertNotIn("self.widgets.clipped_text", deletion_source)
        self.assertNotIn("self.widgets.clipped_text", document_source)
        self.assertEqual(timezone_source.count("self.widgets.clipped_text("), 1)
        self.assertGreaterEqual(timezone_source.count("tooltip=tooltip"), 2)
        self.assertIn("tooltip=tooltip", deletion_source)
        self.assertIn("tooltip=tooltip", document_source)

