    def test_accounts_columns_are_compact_and_shifted_left(self) -> None:
        inner = velox.Rect(100, 50, 1600, 700)
        layout = velox.settings_account_action_layout(inner, 120, heading_h=24, compact=True)
        former_w = (inner.w - 24) // 2
        expected_button_w = max(180, int(round(former_w * 0.25)))
        former_right_x = inner.x + former_w + 24
        self.assertEqual(layout.setup.w, expected_button_w)
        self.assertEqual(layout.actions.w, expected_button_w)
        self.assertEqual(layout.actions.x, inner.x + expected_button_w + 200)
        self.assertLess(layout.actions.x, former_right_x)
        self.assertGreaterEqual(layout.actions.x, layout.setup.x + layout.setup.w + 24)

        narrow = velox.settings_account_action_layout(velox.Rect(10, 20, 380, 300), 40, heading_h=24, compact=True)
        self.assertGreaterEqual(narrow.actions.x, narrow.setup.x + narrow.setup.w)
        self.assertLessEqual(narrow.actions.x + narrow.actions.w, 390)

        left, right = velox.settings_compact_two_column_rects(
            inner, left_preferred_w=430, right_preferred_w=430, gap=48,
        )
        self.assertEqual((left.x, left.w), (inner.x, 430))
        self.assertEqual((right.x, right.w), (inner.x + 430 + 48, 430))
        self.assertLess(right.x + right.w, inner.x + inner.w)
        narrow_left, narrow_right = velox.settings_compact_two_column_rects(
            velox.Rect(10, 20, 380, 300), left_preferred_w=430, right_preferred_w=430, gap=48,
        )
