    def test_stable_large_text_reuses_compiled_geometry_without_character_walk(self) -> None:
        class FakePoint(ctypes.Structure):
            _fields_ = [("x", ctypes.c_float), ("y", ctypes.c_float)]

        class FakeColor(ctypes.Structure):
            _fields_ = [
                ("r", ctypes.c_float), ("g", ctypes.c_float),
                ("b", ctypes.c_float), ("a", ctypes.c_float),
            ]

        class FakeVertex(ctypes.Structure):
            _fields_ = [
                ("position", FakePoint), ("color", FakeColor),
                ("tex_coord", FakePoint),
            ]

        class FakeSDL:
            SDL_Vertex = FakeVertex
            calls: list[tuple[Any, int, int]] = []

            @staticmethod
            def SDL_RenderGeometry(_renderer: Any, _texture: Any, vertices: Any, vertex_count: int, _indices: Any, index_count: int) -> None:
                FakeSDL.calls.append((vertices, int(vertex_count), int(index_count)))

        class CountingPlanCache(dict[str, tuple[tuple[Any, ...], ...]]):
            def __init__(self) -> None:
                super().__init__()
                self.get_count = 0

            def get(self, key: str, default: Any = None) -> Any:
                self.get_count += 1
                return super().get(key, default)

        plan_cache = CountingPlanCache()
        font = SimpleNamespace(
            texture=object(), font_weight="regular", _atlas_revision=1,
            glyphs={
                "A": velox.Glyph("A", 0, 0, 8, 12, 8),
                "?": velox.Glyph("?", 8, 0, 8, 12, 8),
            },
            atlas_w=32, atlas_h=32, char_w=8, line_h=18,
            fallback_map={}, forced_fallback_map={},
            _glyph_geometry_plan_cache=plan_cache,
        )
        renderer = velox.Renderer(SimpleNamespace(renderer=object()))
        renderer.font = font
        runs = [("A" * 512, 10, 20, velox.Palette.text, None, None)]
        module = velox
        with mock.patch.object(module, "sdl", FakeSDL):
            renderer._render_text_runs_geometry(runs)
            self.assertEqual(len(renderer._text_geometry_cache), 0)
            renderer._render_text_runs_geometry(runs)
            self.assertEqual(len(renderer._text_geometry_cache), 1)
            plan_gets_after_compile = plan_cache.get_count
            renderer._render_text_runs_geometry(runs)

        self.assertEqual(plan_cache.get_count, plan_gets_after_compile)
        self.assertEqual(renderer.last_text_geometry_cache_misses, 2)
        self.assertEqual(renderer.last_text_geometry_cache_hits, 1)
        self.assertEqual(len(FakeSDL.calls), 3)
        self.assertEqual(FakeSDL.calls[-1][1:], (512 * 4, 512 * 6))
        self.assertIsNot(FakeSDL.calls[-1][0], renderer._geom_vertices)
        self.assertGreater(renderer._text_geometry_cache_bytes, 0)
        self.assertLessEqual(renderer._text_geometry_cache_bytes, velox.TEXT_GEOMETRY_CACHE_MAX_BYTES)

