    def test_chat_pause_resume_uses_exact_safe_boundary_gate(self) -> None:
        async def scenario(root: Path) -> None:
            storage = velox.Storage(velox.AppPaths(root))
            storage.ensure_first_run_files()
            chats = velox.ChatStore(storage)
            chat_id = str(chats.create_chat("Pause boundary")["chat_id"])
            runtime = velox.ChatRuntime(
                storage, chats, velox.ContextAssembler(storage.paths),
                SimpleNamespace(), SimpleNamespace(),
            )
            ready = asyncio.Event()
            enter_boundary = asyncio.Event()
            resumed = asyncio.Event()

            async def owner() -> None:
                runtime.running[chat_id] = asyncio.current_task()  # type: ignore[assignment]
                ready.set()
                await enter_boundary.wait()
                await runtime._wait_if_chat_paused(chat_id, "after tool call")
                resumed.set()

            task = asyncio.create_task(owner())
            await ready.wait()
            self.assertTrue(runtime.pause(chat_id))
            self.assertTrue(runtime.is_pause_requested(chat_id))
            enter_boundary.set()
            for _ in range(100):
                if runtime.is_paused(chat_id):
                    break
                await asyncio.sleep(0.001)
            self.assertTrue(runtime.is_paused(chat_id))
            self.assertFalse(resumed.is_set())
            self.assertTrue(runtime.resume(chat_id))
            await asyncio.wait_for(task, timeout=1.0)
            self.assertTrue(resumed.is_set())
            self.assertFalse(runtime.is_pause_requested(chat_id))
            self.assertFalse(runtime.is_paused(chat_id))

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

        loop_source = inspect.getsource(velox.ChatRuntime._run_assistant_loop)
        before_tool = loop_source.index('"before tool call"')
        execute_tool = loop_source.index("self._execute_recovered_tool_call")
        after_tool = loop_source.index('"after tool call"')
        self.assertLess(before_tool, execute_tool)
        self.assertLess(execute_tool, after_tool)
        self.assertIn('"before model inference"', loop_source)
        composer = inspect.getsource(velox.Panels.draw_message_composer)
        self.assertIn('"composer.pause_resume"', composer)
        self.assertIn('pause_label = "Resume" if pause_mode else "Pause"', composer)
        self.assertIn("self.services.chat.resume", composer)
        self.assertIn("self.services.chat.pause", composer)
        self.assertIn("success=pause_mode", composer)
        button_source = inspect.getsource(velox.Widgets.button)
        self.assertIn("elif success:", button_source)
        self.assertIn("Palette.ok", button_source)

    def test_stop_request_never_waits_for_contended_tool_progress_lock(self) -> None:
        async def scenario(root: Path) -> None:
            storage = velox.Storage(velox.AppPaths(root))
            storage.ensure_first_run_files()
            registry = velox.ToolRegistry(storage)
            chat_id = "chat-heavy"
            tool_id = "tool-heavy"
            blocker = asyncio.Event()

            async def running_tool() -> None:
                await blocker.wait()

            tool_task = asyncio.create_task(running_tool())
            active = velox.ActiveToolExecution(
                tool_call_id=tool_id, tool_name="fs_edit", chat_id=chat_id,
                agent_id=None, started_mono=time.monotonic(),
                cancel_event=threading.Event(), loop=asyncio.get_running_loop(),
                live_record={
                    "tool_call_id": tool_id, "status": "running",
                    "endpoint_stream_text": "x" * 2_000_000,
                },
                task=tool_task,
            )
            with registry._active_tool_lock:
                registry._active_tool_executions[tool_id] = active

            lock_held = threading.Event()
            release_lock = threading.Event()

            def hold_progress_lock() -> None:
                with registry._active_tool_lock:
                    lock_held.set()
                    release_lock.wait(2.0)

            holder = threading.Thread(target=hold_progress_lock, daemon=True)
            holder.start()
            self.assertTrue(lock_held.wait(1.0))
            started = time.perf_counter()
            accepted = registry.request_cancel_chat_tool_calls(
                chat_id, reason="stop under load", cancelled_by_user=False,
            )
            elapsed = time.perf_counter() - started
            self.assertEqual(accepted, 1)
            self.assertLess(elapsed, 0.20)
            release_lock.set()
            holder.join(timeout=1.0)
            for _ in range(200):
                if active.cancel_event.is_set():
                    break
                await asyncio.sleep(0.005)
            self.assertTrue(active.cancel_event.is_set())
            try:
                await asyncio.wait_for(tool_task, timeout=1.0)
            except asyncio.CancelledError:
                pass
            with registry._active_tool_lock:
                registry._active_tool_executions.pop(tool_id, None)

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

        progress_source = inspect.getsource(velox.ToolRegistry.execute_tool_call)
        self.assertIn("notification = self._tool_progress_notification(record)", progress_source)
        self.assertNotIn("snapshot = copy.deepcopy(snapshot_shallow)", progress_source)
        self.assertLess(
            progress_source.index("record.update(patch)"),
            progress_source.index("notification = self._tool_progress_notification(record)"),
        )
        cancel_source = inspect.getsource(velox.ChatRuntime.cancel)
        self.assertIn("request_cancel_chat_tool_calls", cancel_source)

    def test_long_chat_cpu_path_is_revision_cached_and_block_virtualized(self) -> None:
        class TrackedToolList(list[dict[str, Any]]):
            def __init__(self, values: Iterable[dict[str, Any]]) -> None:
                super().__init__(values)
                self.iterations = 0

            def __iter__(self):
                self.iterations += 1
                return super().__iter__()

        class FakeLayoutCache:
            def __init__(self) -> None:
                self.calls = 0

            def get(self, _key: str, text: str, width: int, **_kwargs: Any) -> TextLayout:
                self.calls += 1
                rows = max(1, math.ceil(len(text) / 100))
                return velox.TextLayout([], width, rows * 18, [])

        panel = velox.Panels.__new__(velox.Panels)
        fake_layout = FakeLayoutCache()
        panel.widgets = SimpleNamespace(
            font=SimpleNamespace(line_h=18, char_w=9),
            layout_cache=fake_layout,
        )
        panel.state = velox.UIState()
        panel.state.active_chat_id = "huge"
        running_state = {"value": True}
        panel.services = SimpleNamespace(
            chat=SimpleNamespace(is_running=lambda _chat_id: running_state["value"]),
        )

        tool_count = 2_000
        tools = TrackedToolList({
            "tool_call_id": f"tool-{index}", "tool_name": "fs_edit",
            "status": "complete", "ok": True, "elapsed_seconds": 1.0,
        } for index in range(tool_count))
        raw_text = "".join(
            f"block {index} " + ("x" * 1_000) + f"\n[[VELOX_TOOL_ROW:{index}]]\n"
            for index in range(tool_count)
        )
        self.assertGreater(len(raw_text), 2_000_000)
        section = {
            "kind": "assistant", "text": raw_text, "inline_tools": tools,
            "turn": {"turn_id": "huge-turn", "status": "complete"},
        }
        blocks = panel._chat_body_blocks_for_section(section)
        first_iterations = tools.iterations
        self.assertEqual(len(blocks), tool_count * 2)
        self.assertIs(panel._chat_body_blocks_for_section(section), blocks)
        self.assertEqual(tools.iterations, first_iterations)

        geometry = panel._chat_body_geometry_for_section(
            section, blocks, "huge.measure", 900, 916,
        )
        layout_calls = fake_layout.calls
        self.assertEqual(layout_calls, tool_count)
        self.assertIs(
            panel._chat_body_geometry_for_section(
                section, blocks, "huge.measure", 900, 916,
            ),
            geometry,
        )
        self.assertEqual(fake_layout.calls, layout_calls)
        visible_top = int(geometry["total_height"]) - 900
        first, end = panel._visible_chat_body_block_range(
            geometry["tops"], geometry["heights"], visible_top, visible_top + 800,
        )
        self.assertGreater(first, len(blocks) - 32)
        self.assertLessEqual(end - first, 16)

        for _ in range(500):
            cached_blocks = panel._chat_body_blocks_for_section(section)
            cached_geometry = panel._chat_body_geometry_for_section(
                section, cached_blocks, "huge.measure", 900, 916,
            )
            start, stop = panel._visible_chat_body_block_range(
                cached_geometry["tops"], cached_geometry["heights"],
                visible_top, visible_top + 800,
            )
            self.assertLessEqual(stop - start, 16)
        self.assertEqual(fake_layout.calls, layout_calls)
        self.assertEqual(tools.iterations, first_iterations)

        turns = [{
            "role": "assistant", "status": "complete", "text": "x" * 1_000,
            "tool_calls": [{
                "tool_call_id": f"call-{index}", "status": "complete",
                "ok": True, "elapsed_seconds": 1.0,
            }],
            "stats": {
                "execution_seconds": 2.0, "prompt_seconds": 0.5,
                "generation_seconds": 0.5, "input_tokens": 1000,
                "output_tokens": 100, "model_rounds": 1,
            },
        } for index in range(2_000)]
        panel.state.chat_turn_cache = turns
        panel.state.chat_turn_cache_key = ("huge", "revision-1")
        module = velox
        with mock.patch.object(
            module, "chat_thread_runtime_stats", wraps=velox.chat_thread_runtime_stats,
        ) as aggregate:
            with mock.patch.object(time, "monotonic", return_value=100.25):
                first_stats = panel._chat_runtime_stats_cached(turns)
                panel.state.chat_turn_cache_key = ("huge", "revision-2")
                turns[-1]["stats"]["output_tokens"] = 101
                second_stats = panel._chat_runtime_stats_cached(turns)
            self.assertIs(first_stats, second_stats)
            self.assertEqual(aggregate.call_count, 1)
            with mock.patch.object(time, "monotonic", return_value=101.25):
                sampled_stats = panel._chat_runtime_stats_cached(turns)
            self.assertEqual(aggregate.call_count, 2)
            self.assertEqual(sampled_stats["output_tokens"], first_stats["output_tokens"] + 1)
            running_state["value"] = False
            panel.state.chat_turn_cache_key = ("huge", "revision-3")
            terminal_stats = panel._chat_runtime_stats_cached(turns)
            self.assertEqual(aggregate.call_count, 3)
        self.assertEqual(terminal_stats["tool_call_count"], 2_000)

    def test_streaming_revision_reuses_historical_sections_by_source_identity(self) -> None:
        panel = velox.Panels.__new__(velox.Panels)
        panel.state = velox.UIState()
        panel.services = SimpleNamespace()
        turns = [{
            "turn_id": f"turn-{index}",
            "role": "assistant",
            "status": "complete",
            "created_at": "2026-08-15T00:00:00Z",
            "updated_at": f"2026-08-15T00:{index % 60:02d}:00Z",
            "text": f"section {index}\n" + ("x" * 4_000),
            "attachments": [],
            "tool_calls": [],
        } for index in range(600)]
        self.assertGreater(sum(len(str(turn["text"])) for turn in turns), 2_000_000)
        panel.state.chat_turn_cache = turns
        panel.state.chat_turn_cache_key = ("huge", "revision-1")
        first = panel._chat_sections(turns, True)
        self.assertEqual(len(first), 600)
        first_list = first
        first_start = first[0]
        first_penultimate = first[-2]
        first_tail = first[-1]

        original = panel._assistant_ordered_sections
        calls = [0]

        def counted(*args: Any, **kwargs: Any) -> list[dict[str, Any]]:
            calls[0] += 1
            return original(*args, **kwargs)

        panel._assistant_ordered_sections = counted  # type: ignore[method-assign]
        changed = dict(turns[-1])
        changed["updated_at"] = "2026-08-15T01:00:00Z"
        changed["text"] = str(changed["text"]) + "\nstreamed tail"
        turns[-1] = changed
        panel.state.chat_turn_changed_from_index = len(turns) - 1
        panel.state.chat_turn_cache_key = ("huge", "revision-2")
        with mock.patch.object(
            panel, "_chat_turn_reuse_stamp", wraps=panel._chat_turn_reuse_stamp,
        ) as reuse_stamp:
            second = panel._chat_sections(turns, True)
        self.assertIs(second, first_list)
        self.assertEqual(calls[0], 1)
        self.assertLessEqual(reuse_stamp.call_count, 3)
        self.assertIs(second[0], first_start)
        self.assertIs(second[-2], first_penultimate)
        self.assertIsNot(second[-1], first_tail)
        self.assertEqual(panel.state.chat_sections_changed_from_index, 599)

        draw_source = inspect.getsource(velox.Panels.draw_chat_view)
        self.assertIn('section.get("_chat_row_layout_cache")', draw_source)
        self.assertIn('cached_exact or still_far', draw_source)
        self.assertIn("del rows[incremental_start:]", draw_source)
        self.assertIn("chat_rows_cache_sections is sections", draw_source)

    def test_streaming_context_toolbar_uses_request_boundary_snapshot(self) -> None:
        panel = velox.Panels.__new__(velox.Panels)
        panel.state = velox.UIState()
        panel.state.active_scope_id = velox.APP_SCOPE_ID
        panel.state.active_chat_id = "long-chat"
        running = {"value": True}

        class FakeChatRuntime:
            def __init__(self) -> None:
                self.build_calls = 0

            def is_running(self, _chat_id: str) -> bool:
                return running["value"]

            def _build_messages(
                self, _scope_id: str, _chat_id: str, *, endpoint_profile_id: str,
            ) -> list[dict[str, Any]]:
                _ = endpoint_profile_id
                self.build_calls += 1
                return [{
                    "role": "user",
                    "content": "x" * (100_000 * self.build_calls),
                }]

            @staticmethod
            def _estimate_messages_tokens(messages: list[dict[str, Any]]) -> int:
                return velox.estimate_request_messages_tokens(messages)

        fake_chat = FakeChatRuntime()
        panel.services = SimpleNamespace(
            chat=fake_chat,
            chats=SimpleNamespace(
                get_chat_endpoint_profile_id=lambda _chat_id: velox.DEFAULT_ENDPOINT_PROFILE_ID,
            ),
            storage=SimpleNamespace(load_config=velox.default_config),
        )
        turns = [{
            "turn_id": "streaming-tail",
            "role": "assistant",
            "status": "streaming",
            "created_at": "2026-08-19T00:00:00Z",
            "updated_at": "2026-08-19T00:00:00Z",
            "text": "first token",
        }]
        panel.state.chat_turn_cache = turns
        panel.state.chat_turn_cache_key = ("long-chat", "revision-1")
        first = panel._chat_context_usage_line(turns)
        turns[-1] = dict(
            turns[-1], text="first token plus a very long streamed suffix",
            updated_at="2026-08-19T00:00:01Z",
        )
        panel.state.chat_turn_cache_key = ("long-chat", "revision-2")
        second = panel._chat_context_usage_line(turns)
        self.assertEqual(fake_chat.build_calls, 1)
        self.assertEqual(second, first)

        running["value"] = False
        panel.state.chat_turn_cache_key = ("long-chat", "revision-3")
        terminal = panel._chat_context_usage_line(turns)
        self.assertEqual(fake_chat.build_calls, 2)
        self.assertNotEqual(terminal, first)

    def test_chat_store_reports_earliest_changed_turn_for_streaming_suffix(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            storage = velox.Storage(velox.AppPaths(Path(td)))
            storage.ensure_first_run_files()
            chats = velox.ChatStore(storage)
            chat_id = str(chats.create_chat("Changed suffix")["chat_id"])
            first = velox.make_turn(chat_id, "user", "first")
            second = velox.make_turn(chat_id, "assistant", "second", status="streaming")
            chats.append_turn(velox.APP_SCOPE_ID, chat_id, first)
            chats.append_turn(velox.APP_SCOPE_ID, chat_id, second, mark_stale=False)
            before_append = chats.turn_revision(velox.APP_SCOPE_ID, chat_id)
            third = velox.make_turn(chat_id, "user", "third")
            chats.append_turn(velox.APP_SCOPE_ID, chat_id, third)
            self.assertEqual(
                chats.turn_change_from_index(velox.APP_SCOPE_ID, chat_id, before_append), 2,
            )
            after_append = chats.turn_revision(velox.APP_SCOPE_ID, chat_id)
            chats.update_turn(
                velox.APP_SCOPE_ID,
                chat_id,
                second["turn_id"],
                {"text": "second streamed suffix", "status": "streaming"},
                expected_statuses={"streaming"},
            )
            self.assertEqual(
                chats.turn_change_from_index(velox.APP_SCOPE_ID, chat_id, after_append), 1,
            )
            self.assertEqual(
                chats.turn_change_from_index(velox.APP_SCOPE_ID, chat_id, before_append), 1,
            )
            # A streaming update queues a crash-recovery sidecar on the dedicated
            # writer. Drain and remove that exact sidecar before TemporaryDirectory
            # teardown so the worker cannot recreate the chat directory mid-rmtree.
            chats._clear_stream_snapshot(chat_id, str(second["turn_id"]))

    def test_large_tool_terminalization_is_off_loop_and_logs_are_bounded(self) -> None:
        class CountingList(list[Any]):
            def __init__(self, size: int) -> None:
                super().__init__(range(size))
                self.yielded = 0

            def __iter__(self):
                for row in super().__iter__():
                    self.yielded += 1
                    yield row

        rows = CountingList(100_000)
        message = velox.compact_log_message("tool.cancelled", {
            "status": "cancelled",
            "endpoint_stream_text": "x" * 5_000_000,
            "rows": rows,
        })
        self.assertLessEqual(len(message), 4_000)
        self.assertIn("chars omitted", message)
        self.assertIn("items omitted", message)
        self.assertLessEqual(rows.yielded, velox.LOG_COMPACT_MAX_CONTAINER_ITEMS)

        execute_source = inspect.getsource(velox.ToolRegistry.execute_tool_call)
        self.assertRegex(execute_source, r"await asyncio\.to_thread\(\s+self\._build_recent_tool_record_snapshot")
        self.assertIn("self._terminal_tool_log_record(record)", execute_source)
        remember_source = inspect.getsource(velox.ToolRegistry._remember_tool_record)
        self.assertNotIn("copy.deepcopy", remember_source)
        log_source = inspect.getsource(velox.Storage.append_app_log)
        self.assertIn("compact_log_payload", log_source)

    def test_stop_wakes_a_paused_chat_and_remains_terminal(self) -> None:
        async def scenario(root: Path) -> None:
            storage = velox.Storage(velox.AppPaths(root))
            storage.ensure_first_run_files()
            chats = velox.ChatStore(storage)
            chat_id = str(chats.create_chat("Paused stop") ["chat_id"])
            cancel_requests: list[str] = []

            class FakeTools:
                def request_cancel_chat_tool_calls(self, target: str, **_kwargs: Any) -> int:
                    cancel_requests.append(target)
                    return 0

            runtime = velox.ChatRuntime(
                storage, chats, velox.ContextAssembler(storage.paths),
                SimpleNamespace(), FakeTools(),
            )
            entered = asyncio.Event()
            enter_boundary = asyncio.Event()

            async def owner() -> None:
                runtime.running[chat_id] = asyncio.current_task()  # type: ignore[assignment]
                entered.set()
                await enter_boundary.wait()
                await runtime._wait_if_chat_paused(chat_id, "before tool call")
                raise AssertionError("Stop must not resume ordinary execution")

            task = asyncio.create_task(owner())
            await entered.wait()
            self.assertTrue(runtime.pause(chat_id))
            enter_boundary.set()
            for _ in range(100):
                if runtime.is_paused(chat_id):
                    break
                await asyncio.sleep(0.001)
            self.assertTrue(runtime.is_paused(chat_id))
            runtime.cancel(chat_id)
            with self.assertRaises(asyncio.CancelledError):
                await task
            self.assertEqual(cancel_requests, [chat_id])
            self.assertFalse(runtime.is_paused(chat_id))
            self.assertFalse(runtime.is_pause_requested(chat_id))

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

