    def test_cpu_hot_paths_reuse_validated_views_cached_counts_and_wrapped_rows(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            storage = velox.Storage(velox.AppPaths(Path(td)))
            storage.ensure_first_run_files()
            with mock.patch.object(
                storage, "_validate_current_manifest", wraps=storage._validate_current_manifest,
            ) as validate:
                first_config = storage.load_config_view(external_poll_seconds=999.0)
                second_config = storage.load_config_view(external_poll_seconds=999.0)
                self.assertIs(first_config, second_config)
                self.assertLessEqual(validate.call_count, 1)
                isolated = storage.load_config()
                self.assertIsNot(isolated, first_config)
                isolated["features"]["force_pdf_images"] = not bool(
                    first_config["features"]["force_pdf_images"]
                )
                self.assertNotEqual(
                    isolated["features"]["force_pdf_images"],
                    first_config["features"]["force_pdf_images"],
                )

            old_value = bool(first_config["features"]["force_pdf_images"])
            storage.update_config(
                lambda cfg: cfg["features"].__setitem__(
                    "force_pdf_images", not old_value,
                )
            )
            third_config = storage.load_config_view(external_poll_seconds=999.0)
            self.assertIsNot(third_config, first_config)
            self.assertEqual(third_config["features"]["force_pdf_images"], not old_value)

            chats = velox.ChatStore(storage)
            chat_id = str(chats.create_chat("Hot path") ["chat_id"])
            first_list = chats.list_chats_view(velox.APP_SCOPE_ID, external_poll_seconds=999.0)
            second_list = chats.list_chats_view(velox.APP_SCOPE_ID, external_poll_seconds=999.0)
            self.assertIs(first_list, second_list)
            isolated_list = chats.list_chats(velox.APP_SCOPE_ID)
            self.assertIsNot(isolated_list, first_list)
            self.assertIsNot(isolated_list[0], first_list[0])

            with mock.patch.object(velox.DATA_ROOTS, "register", wraps=velox.DATA_ROOTS.register) as register:
                storage.load_config_view(external_poll_seconds=999.0)
                self.assertEqual(register.call_count, 0)

            turns = [
                velox.make_turn(chat_id, "user" if index % 2 == 0 else "assistant", f"turn {index}")
                for index in range(2_000)
            ]
            chats._write_all_turns(velox.APP_SCOPE_ID, chat_id, turns)
            cached = chats._load_turn_cache(chat_id)

            class TrackedTurns(list[dict[str, Any]]):
                def __init__(self, values: Iterable[dict[str, Any]]) -> None:
                    super().__init__(values)
                    self.iterations = 0

                def __iter__(self):
                    self.iterations += 1
                    return super().__iter__()

            tracked = TrackedTurns(cached["turns"])
            cached["turns"] = tracked
            for _ in range(100):
                self.assertTrue(chats.is_chat_endpoint_locked(chat_id))
            self.assertEqual(tracked.iterations, 0)
            first_chat = chats.load_chat_view(chat_id, external_poll_seconds=999.0)
            second_chat = chats.load_chat_view(chat_id, external_poll_seconds=999.0)
            self.assertIs(first_chat, second_chat)
            self.assertIsNot(chats.load_chat(chat_id), first_chat)

        widgets = velox.Widgets.__new__(velox.Widgets)
        widgets.font = SimpleNamespace(font_size=18)
        widgets._wrap_cache = {}
        widgets._font_char_advance = lambda _font, _ch: 8
        first_rows = widgets._wrap_display_rows("pooled wrapped rows", 80)
        second_rows = widgets._wrap_display_rows("pooled wrapped rows", 80)
        self.assertIs(first_rows, second_rows)
        self.assertIsInstance(first_rows, tuple)

        chat_list = inspect.getsource(velox.Panels.draw_chat_list)
        self.assertIn("list_chats_view", chat_list)
        self.assertIn("rows = all_convs", chat_list)
        self.assertNotIn("rows = [dict(conv) for conv in all_convs]", chat_list)


