            panel.state.text_cursors["composer.text"] = 7
            panel.state.text_selections["composer.text"] = 2
            panel.state.text_scroll_y["composer.text"] = 31
            panel.state.text_undo_stacks["composer.text"] = ["draft", "private draft A"]
            panel.state.text_redo_stacks["composer.text"] = ["redo A"]

            panel._switch_active_chat(chat_b)
