            self.assertEqual(panel.state.queued_attachments, [])
            self.assertEqual(panel.state.text_cursors["composer.text"], 0)
            self.assertEqual(panel.state.text_undo_stacks.get("composer.text"), None)

            panel.state.composer_text = "private draft B"
            panel.state.queued_attachments = [{"filename": "b.png", "path": "attachments/b.png"}]
