    def test_orphan_terminalization_never_runs_disk_io_in_done_callback(self) -> None:
        async def scenario() -> None:
            load_started = threading.Event()

            class SlowChats:
                def load_turns(self, *_args: Any, **_kwargs: Any) -> list[dict[str, Any]]:
                    load_started.set()
                    time.sleep(0.20)
                    return []

            runtime = velox.ChatRuntime.__new__(velox.ChatRuntime)
            runtime.chats = SlowChats()
            runtime.storage = SimpleNamespace(append_app_log=lambda *_args, **_kwargs: None)
            runtime._orphan_cleanup_tasks = set()
            task = asyncio.create_task(asyncio.sleep(30))
            task.cancel()
            with self.assertRaises(asyncio.CancelledError):
                await task
            started = time.perf_counter()
            runtime._consume_running_task_exception("chat-id", task)
            elapsed = time.perf_counter() - started
            self.assertLess(elapsed, 0.10)
            for _ in range(200):
                if load_started.is_set():
                    break
                await asyncio.sleep(0.005)
            self.assertTrue(load_started.is_set())
            pending = tuple(runtime._orphan_cleanup_tasks)
            if pending:
                await asyncio.gather(*pending)

        asyncio.run(scenario())

    def test_cancelled_tool_snapshot_and_progress_notification_are_bounded(self) -> None:
        class CountingRows(list[Any]):
            def __init__(self, count: int) -> None:
                super().__init__(range(count))
                self.yielded = 0

            def __iter__(self):
                for value in super().__iter__():
                    self.yielded += 1
                    yield value

        rows = CountingRows(100_000)
        record = {
            "schema": velox.TOOL_CALL_SCHEMA,
            "tool_call_id": velox.uuid_v4(),
            "chat_id": velox.uuid_v4(),
            "tool_name": "image_analyze",
            "status": "cancelled",
            "endpoint_stream_text": "x" * 5_000_000,
            "provider_tool_call": {"rows": rows},
            "input": {"path": "image.png", "prompt": "inspect"},
        }
        final = {
            "ok": False, "status": "cancelled", "cancelled": True,
            "error": "Stopped", "input": record["input"],
        }
        snapshot = velox.ToolRegistry._build_recent_tool_record_snapshot(record, final)
        self.assertTrue(snapshot["payload_bounded_after_failure"])
        self.assertLess(len(snapshot["endpoint_stream_text"]), 2_000)
        self.assertLessEqual(rows.yielded, velox.LOG_COMPACT_MAX_CONTAINER_ITEMS)

        notification = velox.ToolRegistry._tool_progress_notification(record)
        self.assertLessEqual(len(notification["endpoint_stream_text"]), 4_000)
        self.assertNotIn("provider_tool_call", notification)
        publish_source = inspect.getsource(velox.ToolRegistry.execute_tool_call)
        self.assertIn("_tool_progress_notification(record)", publish_source)
        self.assertNotIn("copy.deepcopy(snapshot_shallow)", publish_source)

    def test_live_and_cancelled_stats_never_rescan_giant_output(self) -> None:
        runtime = velox.ChatRuntime.__new__(velox.ChatRuntime)
        huge = "<think>reasoning</think>" + ("x" * 3_000_000)
        base = {
            "schema": velox.TURN_STATS_SCHEMA,
            "output_chars": 0,
            "visible_output_chars": 0,
            "approx_output_tokens": 0,
        }
        with mock.patch.object(runtime, "_make_stats", return_value=base.copy()) as make_stats:
            live = runtime._make_streaming_stats(1.0, None, huge, [], {})
            cancelled = runtime._make_cancelled_stats(1.0, None, huge, [], {})
        self.assertEqual(make_stats.call_count, 2)
        self.assertTrue(all(call.args[2] == "" for call in make_stats.call_args_list))
        self.assertEqual(live["output_chars"], len(huge))
        self.assertEqual(cancelled["visible_output_chars"], len(huge))
        update_source = inspect.getsource(velox.ChatRuntime._update_assistant_stream)
        self.assertIn("self._make_streaming_stats", update_source)
        self.assertNotIn('"stats": self._make_stats', update_source)

    def test_streaming_turn_updates_do_not_deepcopy_unchanged_giant_turn(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            storage = velox.Storage(velox.AppPaths(Path(td)))
            storage.ensure_first_run_files()
            chats = velox.ChatStore(storage)
            chat_id = str(chats.create_chat("Streaming copy guard")["chat_id"])
            turn = velox.make_turn(
                chat_id, "assistant", "x" * 2_000_000,
                status="streaming",
            )
            chats.append_turn(velox.APP_SCOPE_ID, chat_id, turn, mark_stale=False)
            current = chats.load_turns_view(velox.APP_SCOPE_ID, chat_id)[0]
            original_deepcopy = copy.deepcopy

            def guarded_deepcopy(value: Any, *args: Any, **kwargs: Any) -> Any:
                if value is current:
                    raise AssertionError("streaming update deep-copied the complete current turn")
                return original_deepcopy(value, *args, **kwargs)

            with mock.patch.object(copy, "deepcopy", side_effect=guarded_deepcopy), mock.patch.object(
                velox.CHAT_STREAM_SNAPSHOT_WRITER, "submit", return_value=1,
            ):
                changed = chats.update_turn(
                    velox.APP_SCOPE_ID,
                    chat_id,
                    str(turn["turn_id"]),
                    {
                        "text": str(current["text"]) + "tail",
                        "status": "streaming",
                        "tool_calls": [],
                        "stats": {"output_chars": 2_000_004},
                    },
                    expected_statuses={"streaming"},
                )
            self.assertTrue(changed)
            updated = chats.load_turns_view(velox.APP_SCOPE_ID, chat_id)[0]
            self.assertIsNot(updated, current)
            self.assertTrue(str(updated["text"]).endswith("tail"))
            self.assertEqual(current["text"], "x" * 2_000_000)
            source = inspect.getsource(velox.ChatStore.update_turn)
            self.assertIn("updated = dict(current)", source)
            self.assertIn("_detach_streaming_turn_patch", source)


    def test_scheduler_close_wakes_waiters_and_cancels_auto_records(self) -> None:
        async def scenario(root: Path) -> None:
            storage = velox.Storage(velox.AppPaths(root))
            storage.ensure_first_run_files()
            monitor = velox.LLMTaskMonitor(storage)
            endpoint_id = velox.DEFAULT_DEEPSEEK_V4_FLASH_0731_ENDPOINT_PROFILE_ID
            profile = velox.endpoint_profile_for_id(storage.load_config(), endpoint_id)
            profile["max_concurrent_requests"] = 1
            scheduler = velox.EndpointInferenceScheduler(
                storage, lambda _endpoint_id: dict(profile), monitor,
            )
            holder = await scheduler.acquire(velox.LLMRequest(
                velox.APP_SCOPE_ID, endpoint_id, [{"role": "user", "content": "hold"}],
                task_kind="chat", task_title="holder",
            ))
            waiter = asyncio.create_task(scheduler.acquire(velox.LLMRequest(
                velox.APP_SCOPE_ID, endpoint_id, [{"role": "user", "content": "wait"}],
                task_kind="chat", task_title="waiter",
            )))
            for _ in range(100):
                snapshot = scheduler.snapshot().get(endpoint_id, {})
                if snapshot.get("queued"):
                    break
                await asyncio.sleep(0.005)
            self.assertEqual(len(scheduler.snapshot()[endpoint_id]["active"]), 1)
            self.assertEqual(len(scheduler.snapshot()[endpoint_id]["queued"]), 1)
            await scheduler.close()
            with self.assertRaisesRegex(RuntimeError, "scheduler is closed"):
                await asyncio.wait_for(waiter, timeout=1.0)
            await holder.release()
            self.assertEqual(scheduler.snapshot(), {})
            rows = monitor.list_records(None, 10)
            self.assertEqual(len(rows), 2)
            self.assertEqual({str(row["state"]) for row in rows}, {"cancelled"})

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_terminal_monitor_state_does_not_release_live_inference_slot(self) -> None:
        async def scenario(root: Path) -> None:
            storage = velox.Storage(velox.AppPaths(root))
            storage.ensure_first_run_files()
            monitor = velox.LLMTaskMonitor(storage)
            endpoint_id = velox.DEFAULT_DEEPSEEK_V4_FLASH_0731_ENDPOINT_PROFILE_ID
            profile = velox.endpoint_profile_for_id(storage.load_config(), endpoint_id)
            profile["max_concurrent_requests"] = 1
            scheduler = velox.EndpointInferenceScheduler(
                storage, lambda _endpoint_id: dict(profile), monitor,
            )
            first_id = monitor.start(velox.APP_SCOPE_ID, "first", task_kind="chat")
            second_id = monitor.start(velox.APP_SCOPE_ID, "second", task_kind="chat")
            first = await scheduler.acquire(velox.LLMRequest(
                velox.APP_SCOPE_ID, endpoint_id, [{"role": "user", "content": "first"}],
                monitor_task_id=first_id, task_kind="chat", task_title="first",
            ))
            second_task = asyncio.create_task(scheduler.acquire(velox.LLMRequest(
                velox.APP_SCOPE_ID, endpoint_id, [{"role": "user", "content": "second"}],
                monitor_task_id=second_id, task_kind="chat", task_title="second",
            )))
            for _ in range(100):
                if scheduler.snapshot().get(endpoint_id, {}).get("queued"):
                    break
                await asyncio.sleep(0.005)
            # Dashboard state may become terminal before the HTTP/provider coroutine
            # has unwound. The explicit lease must remain the source of capacity.
            monitor.complete(first_id)
            await asyncio.sleep(0.05)
            self.assertFalse(second_task.done())
            self.assertEqual(len(scheduler.snapshot()[endpoint_id]["active"]), 1)
            await first.release()
            second = await asyncio.wait_for(second_task, timeout=1.0)
            self.assertEqual(len(scheduler.snapshot()[endpoint_id]["active"]), 1)
            await second.release()
            monitor.complete(second_id)
            await scheduler.close()

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_dashboard_and_statistics_never_truncate_operational_records(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            storage = velox.Storage(velox.AppPaths(Path(td)))
            storage.ensure_first_run_files()
            monitor = velox.LLMTaskMonitor(storage)
            active_id = monitor.start(
                velox.APP_SCOPE_ID, "older active chat", task_kind="chat",
                metadata={
                    "endpoint_label": "Endpoint A", "queue_priority": 1,
                    "phase": "queued", "task_type": "Chat",
                },
            )
            cancelled: list[str] = []
            monitor.register_cancel_callback(active_id, lambda: cancelled.append(active_id) or True)
            # More than the former operational limit ensures neither Dashboard
            # selection, totals, nor cancellation can silently omit old work.
            for index in range(1_005):
                request_id = monitor.start(
                    velox.APP_SCOPE_ID, f"terminal {index}", task_kind="system",
                    metadata={"endpoint_label": "Endpoint A", "task_type": "System"},
                )
                monitor.complete(request_id)
            dashboard = monitor.dashboard_records(5)
            self.assertIn(active_id, {str(row.get("task_id") or "") for row in dashboard})
            self.assertEqual(len(monitor.dashboard_records(None)), 1_006)
            stats = monitor.statistics()
            self.assertEqual(stats["total_tasks"], 1_006)
            self.assertEqual(stats["terminal_tasks"], 1_005)
            monitor.cancel_all()
            self.assertEqual(cancelled, [active_id])
            self.assertEqual(monitor.record_state(active_id), "cancelled")

    def test_coalesced_stream_uses_worker_delta_generation_timing(self) -> None:
        async def scenario(root: Path) -> None:
            storage = velox.Storage(velox.AppPaths(root))
            storage.ensure_first_run_files()
            monitor = velox.LLMTaskMonitor(storage)
            client = velox.LLMClient(storage)
            scheduler = velox.EndpointInferenceScheduler(storage, client.resolve_endpoint, monitor)
            client.bind_request_scheduler(scheduler, monitor)
            endpoint_id = velox.DEFAULT_DEEPSEEK_V4_FLASH_0731_ENDPOINT_PROFILE_ID

            async def fake_stream(_request: velox.LLMRequest):
                first_delta = time.monotonic()
                await asyncio.sleep(0.055)
                last_delta = time.monotonic()
                yield velox.LLMChunk(
                    text="complete coalesced response", done=True,
                    usage={
                        "prompt_tokens": 120,
                        "completion_tokens": 24,
                        "_velox_stream_first_delta_monotonic": first_delta,
                        "_velox_stream_last_delta_monotonic": last_delta,
                    },
                )

            client._chat_completions_stream_unqueued = fake_stream  # type: ignore[method-assign]
            request_id = monitor.start(
                velox.APP_SCOPE_ID, "timed stream", task_kind="chat",
                metadata={"endpoint_label": "DeepSeek", "task_type": "Chat"},
            )
            terminal: LLMChunk | None = None
            async for chunk in client.chat_completions_stream(velox.LLMRequest(
                velox.APP_SCOPE_ID, endpoint_id, [{"role": "user", "content": "test"}],
                monitor_task_id=request_id, task_kind="chat", task_title="timed stream",
            )):
                terminal = chunk
            self.assertIsNotNone(terminal)
            self.assertTrue(bool(terminal and terminal.done))
            self.assertNotIn("_velox_stream_first_delta_monotonic", (terminal.usage or {}))
            self.assertNotIn("_velox_stream_last_delta_monotonic", (terminal.usage or {}))
            metadata = monitor.record_metadata(request_id)
            self.assertGreaterEqual(float(metadata["generation_seconds"]), 0.045)
            self.assertLess(float(metadata["generation_seconds"]), 0.5)
            self.assertEqual(int(metadata["generation_measured_output_tokens"]), 24)
            row = next(row for row in monitor.dashboard_records(10) if row["task_id"] == request_id)
            self.assertGreater(float(row["generation_tokens_per_second"]), 0.0)
            monitor.complete(request_id)
            await scheduler.close()

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_agent_compaction_rejects_provider_inflated_expansion(self) -> None:
        class ExpandingCompactor:
            async def chat_completions_once_full(self, _request: LLMRequest) -> dict[str, Any]:
                return {
                    "text": "expanded operational memory " * 500,
                    "usage": {"prompt_tokens": 7_000, "completion_tokens": 1_500},
                    "finish_reason": "stop", "stop_reason": "",
                }

        async def scenario(root: Path) -> None:
            paths = velox.AppPaths(root)
            storage = velox.Storage(paths)
            storage.ensure_first_run_files()
            chats = velox.ChatStore(storage)
            chat_id = str(chats.create_chat("Compaction expansion guard")["chat_id"])
            agents = velox.AgentStore(storage)
            agent = agents.create_agent(
                chat_id, "Keep the original task", title="Compaction guard",
                context_window_tokens=8_192, max_output_tokens=1_024,
            )
            agent_id = str(agent["agent_id"])
            agents.append_event(agent_id, "started", {
                "system_prompt": "immutable system", "user_prompt": "immutable task",
            })
            agents.update_agent(agent_id, {"last_context_tokens": 7_000})
            runtime = velox.AgentRuntime(
                storage, agents, chats, velox.ContextAssembler(paths),
                ExpandingCompactor(), velox.ToolRegistry(storage),
            )
            messages = [
                {"role": "system", "content": "immutable system"},
                {"role": "user", "content": "immutable task"},
                {"role": "assistant", "content": "old result"},
                {"role": "user", "content": "old follow up"},
                {"role": "assistant", "content": "recent result"},
                {"role": "user", "content": "recent follow up"},
                {"role": "assistant", "content": "latest answer"},
            ]
            original = copy.deepcopy(messages)
            compacted = await runtime._maybe_compact_agent_context(
                agent_id, messages, force=True, native_tools=[],
            )
            self.assertFalse(compacted)
            self.assertEqual(messages, original)
            event = agents.load_transcript(agent_id)[-1]
            self.assertEqual(event["kind"], "context_compaction_ineffective")
            data = event["data"]
            self.assertGreaterEqual(
                int(data["candidate_after_tokens"]),
                runtime._estimate_messages_tokens(original),
            )
            self.assertEqual(data["state"], "ineffective")

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_four_chat_streams_complete_with_two_endpoint_slots(self) -> None:
        async def scenario(root: Path) -> None:
            storage = velox.Storage(velox.AppPaths(root))
            storage.ensure_first_run_files()
            monitor = velox.LLMTaskMonitor(storage)
            client = velox.LLMClient(storage)
            endpoint_id = velox.DEFAULT_DEEPSEEK_V4_FLASH_0731_ENDPOINT_PROFILE_ID
            profile = velox.endpoint_profile_for_id(storage.load_config(), endpoint_id)
            profile["max_concurrent_requests"] = 2
            scheduler = velox.EndpointInferenceScheduler(
                storage, lambda _endpoint_id: dict(profile), monitor,
            )
            client.bind_request_scheduler(scheduler, monitor)
            active = 0
            maximum_active = 0
            active_lock = asyncio.Lock()

            async def fake_stream(request: LLMRequest):
                nonlocal active, maximum_active
                async with active_lock:
                    active += 1
                    maximum_active = max(maximum_active, active)
                first_delta = time.monotonic()
                try:
                    await asyncio.sleep(0.04)
                    last_delta = time.monotonic()
                finally:
                    async with active_lock:
                        active -= 1
                yield velox.LLMChunk(
                    text=f"done {request.task_title}", done=True,
                    usage={
                        "prompt_tokens": 20, "completion_tokens": 5,
                        "_velox_stream_first_delta_monotonic": first_delta,
                        "_velox_stream_last_delta_monotonic": last_delta,
                    },
                )

            client._chat_completions_stream_unqueued = fake_stream  # type: ignore[method-assign]

            async def run_chat(index: int) -> str:
                text = ""
                async for chunk in client.chat_completions_stream(velox.LLMRequest(
                    velox.APP_SCOPE_ID, endpoint_id,
                    [{"role": "user", "content": f"request {index}"}],
                    task_kind="chat", task_title=f"Chat {index}",
                )):
                    text += str(chunk.text or "")
                return text

            results = await asyncio.wait_for(
                asyncio.gather(*(run_chat(index) for index in range(4))),
                timeout=3.0,
            )
            self.assertEqual(len(results), 4)
            self.assertTrue(all(result.startswith("done Chat") for result in results))
            self.assertEqual(maximum_active, 2)
            snapshot = scheduler.snapshot().get(endpoint_id, {})
            self.assertEqual(snapshot.get("active", []), [])
            self.assertEqual(snapshot.get("queued", []), [])
            self.assertEqual(snapshot.get("paused", []), [])
            rows = monitor.dashboard_records(10)
            self.assertEqual(sum(row["state"] == "completed" for row in rows), 4)
            await scheduler.close()

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))


