class SchedulingAndTaskMetricsTests(_AppLogDataRootsIsolatedTestMixin, unittest.TestCase):
    """Behavioral regressions for current compaction, queue, Dashboard, and metrics."""


    def test_four_chat_streams_share_two_slots_and_leave_no_scheduler_state(self) -> None:
        async def scenario(root: Path) -> None:
            storage = _make_test_storage(root)
            profile = velox.default_endpoint_profile(
                "shared", "Shared vLLM", timeout_seconds=60,
                provider=velox.ENDPOINT_PROVIDER_VLLM, max_concurrent_requests=2,
            )
            monitor = velox.LLMTaskMonitor(storage)
            scheduler = velox.EndpointInferenceScheduler(storage, lambda _pid: profile, monitor)
            client = velox.LLMClient(storage)
            client.resolve_endpoint = lambda _pid: profile
            client.bind_request_scheduler(scheduler, monitor)
            active = 0
            maximum_active = 0
            started: list[str] = []

            async def fake_unqueued(request: LLMRequest):
                nonlocal active, maximum_active
                active += 1
                released = False
                maximum_active = max(maximum_active, active)
                started.append(str(request.task_title))
                try:
                    await asyncio.sleep(0.025)
                    yield velox.LLMChunk(text=f"reply:{request.task_title}")
                    await asyncio.sleep(0.025)
                    active -= 1
                    released = True
                    yield velox.LLMChunk(
                        done=True, finish_reason="stop",
                        usage={"prompt_tokens": 10, "completion_tokens": 2},
                    )
                finally:
                    if not released:
                        active = max(0, active - 1)

            client._chat_completions_stream_unqueued = fake_unqueued  # type: ignore[method-assign]

            async def consume(index: int) -> str:
                request_id = monitor.start(velox.APP_SCOPE_ID, f"chat-{index}", task_kind="chat")
                pieces: list[str] = []
                async for chunk in client.chat_completions_stream(velox.LLMRequest(
                    velox.APP_SCOPE_ID, "shared", [{"role": "user", "content": str(index)}],
                    monitor_task_id=request_id, task_kind="chat",
                    task_title=f"chat-{index}",
                )):
                    pieces.append(str(chunk.text or ""))
                monitor.complete(request_id)
                return "".join(pieces)

            results = await asyncio.wait_for(
                asyncio.gather(*(consume(index) for index in range(4))), timeout=3.0,
            )
            self.assertEqual(results, [f"reply:chat-{index}" for index in range(4)])
            self.assertEqual(maximum_active, 2)
            self.assertEqual(len(started), 4)
            snapshot = scheduler.snapshot().get("shared", {})
            self.assertFalse(snapshot.get("active"))
            self.assertFalse(snapshot.get("queued"))
            self.assertFalse(snapshot.get("paused"))
            await scheduler.close()

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_task_metrics_exclude_queue_and_pause_and_use_measured_windows(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            storage = _make_test_storage(Path(td))
            monitor = velox.LLMTaskMonitor(storage)
            clock = [0.0]
            with mock.patch(f"{velox.__name__}.time.monotonic", side_effect=lambda: clock[0]):
                request_id = monitor.start(velox.APP_SCOPE_ID, "timed", task_kind="chat")
                clock[0] = 10.0
                monitor.set_phase(request_id, "queued")
                clock[0] = 100.0
                monitor.set_phase(request_id, "inference")
                clock[0] = 104.0
                monitor.set_phase(request_id, "paused")
                clock[0] = 500.0
                monitor.set_phase(request_id, "tool")
                clock[0] = 505.0
                monitor.set_phase(request_id, "ready")
                monitor.add_inference_metrics(
                    request_id, input_tokens=1_000, output_tokens=200,
                    prefill_seconds=2.0, generation_seconds=4.0,
                )
                row = next(row for row in monitor.list_records() if row["task_id"] == request_id)
                stats = monitor.statistics()
            self.assertAlmostEqual(float(row["duration_seconds"]), 9.0, places=6)
            self.assertAlmostEqual(float(row["prefill_tokens_per_second"]), 500.0, places=6)
            self.assertAlmostEqual(float(row["generation_tokens_per_second"]), 50.0, places=6)
            self.assertAlmostEqual(float(stats["active_seconds"]), 9.0, places=6)
            self.assertAlmostEqual(float(stats["prefill_tokens_per_second"]), 500.0, places=6)
            self.assertAlmostEqual(float(stats["generation_tokens_per_second"]), 50.0, places=6)

