    def test_cancelled_release_preserves_terminal_metadata_until_slot_cleanup(self) -> None:
        async def scenario(root: Path) -> None:
            storage = _make_test_storage(root)
            try:
                monitor = velox.LLMTaskMonitor(storage)
                profile = velox.default_endpoint_profile(
                    "shared", "Shared endpoint", timeout_seconds=60,
                    provider=velox.ENDPOINT_PROVIDER_VLLM, max_concurrent_requests=1,
                )
                scheduler = velox.EndpointInferenceScheduler(storage, lambda _pid: profile, monitor)
                first_id = monitor.start(velox.APP_SCOPE_ID, "first", task_kind="chat")
                monitor.register_cancel_callback(first_id, lambda: True)
                first = await scheduler.acquire(velox.LLMRequest(
                    velox.APP_SCOPE_ID, "shared", [], monitor_task_id=first_id,
                    task_kind="chat", task_title="first",
                ))
                self.assertTrue(monitor.cancel_task(first_id))
                self.assertEqual(monitor.record_state(first_id), "cancelled")
                self.assertEqual(monitor.record_metadata(first_id)["queue_state"], "cancelled")

                second_id = monitor.start(velox.APP_SCOPE_ID, "second", task_kind="chat")
                second_task = asyncio.create_task(scheduler.acquire(velox.LLMRequest(
                    velox.APP_SCOPE_ID, "shared", [], monitor_task_id=second_id,
                    task_kind="chat", task_title="second",
                )))
                await asyncio.sleep(0.03)
                self.assertFalse(second_task.done())
                # Priority refreshes while the cancelled provider still owns its lease
                # must not resurrect its terminal row as inference/queued.
                self.assertEqual(monitor.record_metadata(first_id)["queue_state"], "cancelled")
                await first.release()
                self.assertEqual(monitor.record_state(first_id), "cancelled")
                self.assertEqual(monitor.record_metadata(first_id)["queue_state"], "cancelled")
                second = await asyncio.wait_for(second_task, timeout=1.0)
                await second.release()
                monitor.complete(second_id)
                await scheduler.close()
            finally:
                _drain_storage_log_writer(storage)

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_resume_before_safe_pause_boundary_keeps_inference_clock_open(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            storage = _make_test_storage(Path(td))
            monitor = velox.LLMTaskMonitor(storage)
            clock = [0.0]
            with mock.patch(f"{velox.__name__}.time.monotonic", side_effect=lambda: clock[0]):
                request_id = monitor.start(velox.APP_SCOPE_ID, "chat", task_kind="chat")
                monitor.register_pause_callback(request_id, lambda: True)
                monitor.register_resume_callback(request_id, lambda: True)
                clock[0] = 10.0
                monitor.set_phase(request_id, "inference")
                clock[0] = 12.0
                self.assertTrue(monitor.pause_task(request_id))
                self.assertEqual(monitor.record_metadata(request_id)["phase"], "inference")
                clock[0] = 13.0
                self.assertTrue(monitor.resume_task(request_id))
                metadata = monitor.record_metadata(request_id)
                self.assertEqual(metadata["phase"], "inference")
                self.assertEqual(metadata["phase_started_monotonic"], 10.0)
                self.assertFalse(metadata["pause_requested"])
                clock[0] = 20.0
                monitor.set_phase(request_id, "ready")
                self.assertAlmostEqual(monitor.active_duration_seconds(request_id), 10.0, places=6)

    def test_cancelled_release_caller_cannot_strand_endpoint_capacity(self) -> None:
        async def scenario(root: Path) -> None:
            storage = _make_test_storage(root)
            profile = velox.default_endpoint_profile(
                "shared", "Shared endpoint", timeout_seconds=60,
                provider=velox.ENDPOINT_PROVIDER_VLLM, max_concurrent_requests=1,
            )
            scheduler = velox.EndpointInferenceScheduler(storage, lambda _pid: profile)
            lease = await scheduler.acquire(velox.LLMRequest(velox.APP_SCOPE_ID, "shared", [], task_kind="chat"))
            original_release = scheduler.finish_request
            entered = asyncio.Event()
            proceed = asyncio.Event()

            async def delayed_release(ticket: EndpointQueueTicket) -> None:
                entered.set()
                await proceed.wait()
                await original_release(ticket)

            scheduler.finish_request = delayed_release  # type: ignore[method-assign]
            caller = asyncio.create_task(lease.release())
            await asyncio.wait_for(entered.wait(), timeout=1.0)
            caller.cancel()
            with self.assertRaises(asyncio.CancelledError):
                await caller
            self.assertEqual(len(scheduler.snapshot()["shared"]["active"]), 1)
            proceed.set()
            for _ in range(100):
                if not scheduler.snapshot().get("shared", {}).get("active"):
                    break
                await asyncio.sleep(0.005)
            self.assertFalse(scheduler.snapshot().get("shared", {}).get("active"))
            next_lease = await asyncio.wait_for(
                scheduler.acquire(velox.LLMRequest(velox.APP_SCOPE_ID, "shared", [], task_kind="chat")),
                timeout=1.0,
            )
            await next_lease.release()
            await scheduler.close()

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_cancel_callback_rejection_or_failure_keeps_request_live(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            storage = _make_test_storage(Path(td))
            monitor = velox.LLMTaskMonitor(storage)
            request_id = monitor.start(velox.APP_SCOPE_ID, "cancel control", task_kind="chat")
            monitor.register_cancel_callback(request_id, lambda: False)
            self.assertFalse(monitor.cancel_task(request_id))
            self.assertEqual(monitor.record_state(request_id), "running")
            self.assertTrue(monitor.can_cancel_task(request_id))
            self.assertIn("rejected", str(monitor.record_metadata(request_id).get("control_error") or "").lower())

            def raises() -> bool:
                raise RuntimeError("owner busy")

            monitor.register_cancel_callback(request_id, raises)
            self.assertFalse(monitor.cancel_task(request_id))
            self.assertEqual(monitor.record_state(request_id), "running")
            self.assertIn("owner busy", str(monitor.record_metadata(request_id).get("control_error") or ""))
            monitor.register_cancel_callback(request_id, lambda: True)
            self.assertTrue(monitor.cancel_task(request_id))
            self.assertEqual(monitor.record_state(request_id), "cancelled")

    def test_queue_priority_is_single_pin_then_chat_fifo_agent_and_system(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            storage = _make_test_storage(Path(td))
            monitor = velox.LLMTaskMonitor(storage)
            scheduler = velox.EndpointInferenceScheduler(storage, lambda _pid: {}, monitor)
            chat_a_id = monitor.start(velox.APP_SCOPE_ID, "chat A", task_kind="chat")
            chat_b_id = monitor.start(velox.APP_SCOPE_ID, "chat B", task_kind="chat")
            agent_id = monitor.start(velox.APP_SCOPE_ID, "agent", task_kind="agent")
            system_id = monitor.start(velox.APP_SCOPE_ID, "system", task_kind="system")
            image_id = monitor.start(
                velox.APP_SCOPE_ID, "image", task_kind="image", metadata={"chat_id": "chat-source"},
            )
            tickets = {
                "chat-a": velox.EndpointQueueTicket("chat-a", "e", "E", chat_a_id, "chat", 100.0, 1),
                "chat-b": velox.EndpointQueueTicket("chat-b", "e", "E", chat_b_id, "chat", 101.0, 2),
                "agent": velox.EndpointQueueTicket("agent", "e", "E", agent_id, "agent", 102.0, 3),
                "system": velox.EndpointQueueTicket("system", "e", "E", system_id, "system", 103.0, 4),
                "image": velox.EndpointQueueTicket("image", "e", "E", image_id, "image", 104.0, 5),
            }
            with mock.patch(f"{velox.__name__}.time.monotonic", return_value=105.0):
                ordered = sorted(tickets, key=lambda name: scheduler._priority_key(tickets[name]))
            self.assertEqual(ordered, ["chat-a", "chat-b", "image", "agent", "system"])

            self.assertTrue(scheduler.prioritize_task(agent_id))
            with mock.patch(f"{velox.__name__}.time.monotonic", return_value=105.0):
                pinned_agent = sorted(tickets, key=lambda name: scheduler._priority_key(tickets[name]))
            self.assertEqual(pinned_agent[0], "agent")
            self.assertEqual(monitor.prioritized_task_id(), agent_id)
            self.assertTrue(monitor.record_snapshot(agent_id)["prioritized"])

            self.assertTrue(scheduler.prioritize_task(chat_a_id))
            self.assertEqual(monitor.prioritized_task_id(), chat_a_id)
            self.assertFalse(monitor.record_snapshot(agent_id)["prioritized"])
            with mock.patch(f"{velox.__name__}.time.monotonic", return_value=105.0):
                first_name = sorted(tickets, key=lambda name: scheduler._priority_key(tickets[name]))[0]
            self.assertEqual(first_name, "chat-a")
            self.assertFalse(scheduler.prioritize_task(system_id))
            self.assertTrue(scheduler.deprioritize_task(chat_a_id))
            self.assertIsNone(monitor.prioritized_task_id())

    def test_agent_context_provider_count_does_not_double_count_tool_schemas(self) -> None:
        class NeverCompact:
            def __init__(self) -> None:
                self.calls = 0
            async def chat_completions_once_full(self, _request: LLMRequest) -> dict[str, Any]:
                self.calls += 1
                raise AssertionError("context already fits and must not compact")

        async def scenario(root: Path) -> None:
            paths = velox.AppPaths(root)
            storage = velox.Storage(paths)
            storage.ensure_first_run_files()
            chats = velox.ChatStore(storage)
            chat_id = str(chats.create_chat("No double count")["chat_id"])
            agents = velox.AgentStore(storage)
            agent = agents.create_agent(
                chat_id, "Keep context", context_window_tokens=8_192,
                max_output_tokens=1_024, auto_compaction_enabled=True,
            )
            agent_id = str(agent["agent_id"])
            agents.append_event(agent_id, "started", {
                "system_prompt": "system", "user_prompt": "task",
            })
            # This is a provider prompt count and therefore already includes the
            # function schemas. It fits the 7,168-token effective capacity.
            agents.update_agent(agent_id, {"last_context_tokens": 7_000})
            fake = NeverCompact()
            runtime = velox.AgentRuntime(
                storage, agents, chats, velox.ContextAssembler(paths), fake, velox.ToolRegistry(storage),
            )
            messages = [
                {"role": "system", "content": "system"},
                {"role": "user", "content": "task"},
                {"role": "assistant", "content": "older"},
                {"role": "user", "content": "recent"},
            ]
            native_tools = [{
                "type": "function",
                "function": {
                    "name": "large_tool", "description": "x" * 2_000,
                    "parameters": {"type": "object", "properties": {}},
                },
            }]
            self.assertFalse(await runtime._maybe_compact_agent_context(
                agent_id, messages, force=False, native_tools=native_tools,
            ))
            self.assertEqual(fake.calls, 0)
            self.assertEqual(agents.load_agent(agent_id)["last_context_tokens"], 7_000)

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_stale_paused_release_callback_cannot_cancel_reacquired_request(self) -> None:
        async def scenario(root: Path) -> None:
            storage = _make_test_storage(root)
            profile = velox.default_endpoint_profile(
                "shared", "Shared endpoint", timeout_seconds=60,
                provider=velox.ENDPOINT_PROVIDER_VLLM, max_concurrent_requests=1,
            )
            monitor = velox.LLMTaskMonitor(storage)
            scheduler = velox.EndpointInferenceScheduler(storage, lambda _pid: profile, monitor)
            first_id = monitor.start(velox.APP_SCOPE_ID, "first", task_kind="chat")
            first = await scheduler.acquire(velox.LLMRequest(
                velox.APP_SCOPE_ID, "shared", [], monitor_task_id=first_id, task_kind="chat",
            ))
            await first.release()
            monitor.set_phase(first_id, "paused")
            # Resume before the scheduled lifecycle release coroutine runs, then
            # reacquire. release_task rechecks the current phase before touching it.
            monitor.set_phase(first_id, "ready")
            reacquired = await asyncio.wait_for(scheduler.acquire(velox.LLMRequest(
                velox.APP_SCOPE_ID, "shared", [], monitor_task_id=first_id, task_kind="chat",
            )), 1.0)
            await asyncio.sleep(0.05)
            snap = scheduler.snapshot()["shared"]
            self.assertEqual(snap["active_task_ids"], [first_id])
            self.assertTrue(snap["slot_invariant_ok"])
            await reacquired.release()
            monitor.complete(first_id)
            await scheduler.close()
        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_stream_bridge_timing_is_private_and_provider_usage_is_exact(self) -> None:
        loop = asyncio.new_event_loop()
        try:
            bridge = velox.LLMStreamChunkBridge(loop, flush_seconds=0.0)
            clock = iter((10.0, 10.125, 10.125))
            with mock.patch(f"{velox.__name__}.time.monotonic", side_effect=lambda: next(clock)):
                with bridge._lock:
                    bridge._append_pending_locked(velox.LLMChunk(text="A"))
                    bridge._append_pending_locked(velox.LLMChunk(
                        text="B", done=True,
                        usage={"prompt_tokens": 9, "completion_tokens": 2},
                    ))
                    batch = bridge._take_pending_locked()
            self.assertIsNotNone(batch)
            chunk = bridge._materialize_batch(batch)  # type: ignore[arg-type]
            self.assertEqual(chunk.usage, {"prompt_tokens": 9, "completion_tokens": 2})
            self.assertEqual(getattr(chunk, "_velox_stream_first_delta_monotonic"), 10.0)
            self.assertEqual(getattr(chunk, "_velox_stream_last_delta_monotonic"), 10.125)
            self.assertEqual(getattr(chunk, "_velox_stream_terminal_monotonic"), 10.125)
        finally:
            loop.close()


    def test_inline_media_grid_uses_one_measurement_contract_and_never_escapes_card_body(self) -> None:
        panel = velox.Panels.__new__(velox.Panels)
        media = [{"path": f"image-{index}.png", "kind": "image"} for index in range(9)]
        metrics = panel._inline_media_grid_metrics(len(media), 380)
