    def test_tool_phases_release_two_slots_and_queued_third_starts_immediately(self) -> None:
        async def scenario(root: Path) -> None:
            storage = _make_test_storage(root)
            profile = velox.default_endpoint_profile(
                "shared", "Shared endpoint", timeout_seconds=60,
                provider=velox.ENDPOINT_PROVIDER_VLLM, max_concurrent_requests=2,
            )
            monitor = velox.LLMTaskMonitor(storage)
            scheduler = velox.EndpointInferenceScheduler(storage, lambda _pid: profile, monitor)
            ids = [monitor.start(velox.APP_SCOPE_ID, f"chat {index}", task_kind="chat") for index in range(3)]
            first = await scheduler.acquire(velox.LLMRequest(
                velox.APP_SCOPE_ID, "shared", [], monitor_task_id=ids[0], task_kind="chat",
            ))
            second = await scheduler.acquire(velox.LLMRequest(
                velox.APP_SCOPE_ID, "shared", [], monitor_task_id=ids[1], task_kind="chat",
            ))
            third_waiter = asyncio.create_task(scheduler.acquire(velox.LLMRequest(
                velox.APP_SCOPE_ID, "shared", [], monitor_task_id=ids[2], task_kind="chat",
            )))
            monitor.set_phase(ids[0], "tool"); monitor.set_phase(ids[1], "tool")
            await first.release(); await second.release()
            third = await asyncio.wait_for(third_waiter, 1.0)
            snapshot = scheduler.snapshot()["shared"]
            self.assertEqual(snapshot["active_task_ids"], [ids[2]])
            self.assertEqual(snapshot["slots_consumed"], 1)
            self.assertEqual(snapshot["inference_requests"], 1)
            self.assertTrue(snapshot["slot_invariant_ok"])
            await third.release()
            for task_id in ids: monitor.complete(task_id)
            await scheduler.close()
        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

