    def test_dashboard_context_menu_has_exact_order_and_workspace_rules(self) -> None:
        class FakeAgents:
            @staticmethod
            def load_agent(_agent_id: str) -> dict[str, Any]:
                return {"source_chat_id": "source-chat"}

        panel = velox.Panels.__new__(velox.Panels)
