    def test_chat_task_view_uses_only_the_durable_turn_span_for_that_task(self) -> None:
        chat_id = velox.uuid_v4()
        first_user = velox.make_turn(chat_id, "user", "FIRST USER")
        first_assistant = velox.make_turn(chat_id, "assistant", "FIRST ANSWER")
        second_user = velox.make_turn(chat_id, "user", "SECOND USER")
        second_assistant = velox.make_turn(chat_id, "assistant", "SECOND ANSWER")
        expert_prompt = velox.make_turn(
            chat_id, "user",
            "Checklist remains active because the previous response stopped before Checklist exited.",
        )
        expert_prompt["stats"] = {
            "schema": velox.USER_PROMPT_STATS_SCHEMA,
            "expert_mode_prompt": True,
            "expert_mode_prompt_index": 1,
            "estimated": True,
            "updated_at": velox.now_iso(),
        }
        continuation_answer = velox.make_turn(chat_id, "assistant", "Completed remaining work.")
        third_user = velox.make_turn(chat_id, "user", "THIRD USER")
        record = {
            "created_at": second_user["created_at"],
            "metadata": {"assistant_turn_id": continuation_answer["turn_id"]},
        }
        all_turns = [
            first_user, first_assistant, second_user, second_assistant,
            expert_prompt, continuation_answer, third_user,
        ]
        selected = velox.Panels._dashboard_chat_task_turn_slice(record, all_turns)
        self.assertEqual(
            [turn["turn_id"] for turn in selected],
            [
                second_user["turn_id"], second_assistant["turn_id"],
                expert_prompt["turn_id"], continuation_answer["turn_id"],
            ],
        )
        self.assertTrue(velox.is_chat_expert_mode_prompt_turn(expert_prompt))
        fallback = velox.Panels._dashboard_chat_task_turn_slice(
            {"created_at": second_user["created_at"], "metadata": {}},
            [first_user, first_assistant, second_user],
        )
        self.assertEqual(fallback[-1]["turn_id"], second_user["turn_id"])


