class ScheduledAndContextTests(_AppLogDataRootsIsolatedTestMixin, unittest.TestCase):
    """Scheduled tasks, Context Docs and task identity."""


    def test_chat_identity_reuses_one_dashboard_task_and_accumulates_metrics(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            storage = _make_test_storage(Path(td))
            monitor = velox.LLMTaskMonitor(storage)
            chat_id = velox.uuid_v4()
            first = monitor.start(
                chat_id, "First turn", task_kind="chat",
                metadata={"task_type": "Chat", "title": "Identity test"},
                identity_key=f"chat:{chat_id}",
            )
            self.assertTrue(monitor.add_inference_metrics(
                first, input_tokens=120, output_tokens=20,
                prefill_seconds=0.5, generation_seconds=0.25,
            ))
            monitor.complete(first)
            second = monitor.start(
                chat_id, "Second turn", task_kind="chat",
                metadata={"task_type": "Chat", "title": "Identity test"},
                identity_key=f"chat:{chat_id}",
            )
            self.assertEqual(first, second)
            self.assertTrue(monitor.add_inference_metrics(
                second, input_tokens=80, output_tokens=10,
                prefill_seconds=0.25, generation_seconds=0.1,
            ))
            monitor.complete(second)
            rows = [row for row in monitor.dashboard_records() if row.get("task_type") == "Chat"]
            self.assertEqual(len(rows), 1)
            row = rows[0]
            self.assertEqual((row["input_tokens"], row["output_tokens"]), (200, 30))
            self.assertEqual(int((row.get("metadata") or {}).get("inference_count") or 0), 2)
            self.assertEqual(int((row.get("metadata") or {}).get("session_count") or 0), 2)
            self.assertEqual(monitor.statistics()["task_types"].get("Chat"), 1)

