    def test_context_revision_uses_capture_day_not_stale_document_update_day(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            storage = _make_test_storage(Path(td))
            docs = velox.ContextDocStore(storage)
            created = docs.create_doc("Capture day", "Retain one fact.", 2000)
            doc_id = str(created["context_doc_id"])
            docs.save_content(doc_id, "old current content", source_summary="first")
            path = storage.paths.context_doc_json(doc_id)
            stale = velox.read_json(path)
            stale["updated_at"] = "2020-01-02T03:04:05Z"
            velox.validate_context_doc_record(stale)
            velox.atomic_write_json(path, stale)
            docs._invalidate()
            fixed_now = "2026-08-17T12:34:56Z"
            with mock.patch.object(velox, "now_iso", return_value=fixed_now):
                docs.save_content(doc_id, "new current content", source_summary="second")
            revisions = docs.list_revisions(doc_id)
            self.assertEqual(len(revisions), 1)
            self.assertEqual(revisions[0].get("revision_date"), "2026-08-17")
            self.assertEqual((revisions[0].get("doc") or {}).get("content"), "old current content")

    def test_context_autosave_flush_never_overtakes_an_inflight_older_snapshot(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            storage = _make_test_storage(Path(td))
            docs = velox.ContextDocStore(storage)
            created = docs.create_doc("Serialized autosave", "Keep edits ordered.", 2000)
            doc_id = str(created["context_doc_id"])
            snapshot = {
                "context_doc_id": doc_id,
                "revision_key": "current",
                "goal": "Keep edits ordered.",
                "content": "newest queued content",
            }
            panel = velox.Panels.__new__(velox.Panels)
            panel.services = SimpleNamespace(context_docs=docs)
            panel.state = SimpleNamespace(
                context_autosave_task=SimpleNamespace(done=lambda: False),
                context_autosave_queued=copy.deepcopy(snapshot),
                context_autosave_error="",
                context_revisions_cache_key=None,
            )
            panel._refresh_context_docs_cache = lambda force=False: None
