    def test_scheduled_and_context_tool_schemas_are_strict_and_crud_works(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            storage = _make_test_storage(Path(td))
            chats = velox.ChatStore(storage)
            chat = chats.create_chat("Schedule tool source")
            registry = velox.ToolRegistry(storage)
            once = registry.tools["scheduled_task_create_once"].parameters
            recurring = registry.tools["scheduled_task_create_recurring"].parameters
            self.assertEqual(
                once.get("required"),
                ["title", "task", "year", "month", "day", "hour", "minute", "second"],
            )
            self.assertEqual(recurring.get("required"), ["title", "task", "every_minutes"])
            self.assertIn("list_context_docs", registry.tools)
            self.assertIn("get_context_doc", registry.tools)
            self.assertEqual(
                registry.tools["create_context_doc"].parameters.get("required"),
                ["name", "goal", "character_limit", "update_frequency"],
            )
            self.assertEqual(
                registry.tools["delete_context_doc"].parameters.get("required"),
                ["context_doc_id"],
            )
            self.assertEqual(
                registry.tools["update_context_doc"].parameters.get("required"),
                ["context_doc_id", "content"],
            )
            self.assertEqual(
                registry.tools["shell_exec"].parameters.get("required"),
                ["command", "timeout_minutes"],
            )
            self.assertEqual(
                registry.tools["python_exec"].parameters.get("required"),
                ["script", "timeout_minutes"],
            )

            store = registry.scheduled_task_store
            created = store.create_recurring(
                "Weekly update", "Prepare a source-supported update.",
                every_minutes=7 * 24 * 60, source_chat_id=str(chat["chat_id"]),
            )
            task_id = str(created["scheduled_task_id"])
            self.assertEqual(store.get_task(task_id).get("interval_minutes"), 10080)
            self.assertTrue(any(str(row.get("scheduled_task_id") or "") == task_id for row in store.list_tasks()))
            self.assertTrue(store.delete_task(task_id))
            self.assertFalse(storage.paths.scheduled_task_json(task_id).exists())

            async def context_crud() -> None:
                ctx = velox.ToolContext(velox.APP_SCOPE_ID, chat_id=str(chat["chat_id"]))
                created_result = await registry.tool_create_context_doc(ctx, {
                    "name": "Tool-created context",
                    "goal": "Maintain the exact tool-created facts.",
                    "character_limit": 2000,
                    "update_frequency": "hourly",
                })
                context_doc = created_result["context_doc"]
                context_doc_id = str(context_doc["context_doc_id"])
                managed = created_result["scheduled_task"]
                self.assertEqual(managed.get("context_doc_id"), context_doc_id)
                self.assertEqual(managed.get("interval_minutes"), 60)

                first = await registry.tool_update_context_doc(ctx, {
                    "context_doc_id": context_doc_id,
                    "content": "first tool revision",
                })
                self.assertTrue(first.get("new_revision_created"))
                self.assertEqual(first.get("revision_count"), 2)
                second = await registry.tool_update_context_doc(ctx, {
                    "context_doc_id": context_doc_id,
                    "content": "second tool revision",
                })
                self.assertTrue(second.get("new_revision_created"))
                self.assertEqual(second.get("revision_count"), 3)
                revisions = registry.context_doc_store.list_revisions(context_doc_id)
                self.assertEqual(len(revisions), 2)
                self.assertEqual(
                    [(row.get("doc") or {}).get("content") for row in revisions],
                    ["first tool revision", ""],
                )
                listed = await registry.tool_list_context_docs(ctx, {})
                listed_doc = next(row for row in listed["context_docs"] if row["context_doc_id"] == context_doc_id)
                self.assertEqual(listed_doc.get("scheduled_task_id"), managed.get("scheduled_task_id"))

                with self.assertRaises(PermissionError):
                    await registry.tool_scheduled_task_delete(ctx, {
                        "scheduled_task_id": str(managed["scheduled_task_id"]),
                    })
                deleted = await registry.tool_delete_context_doc(ctx, {"context_doc_id": context_doc_id})
                self.assertTrue(deleted.get("deleted"))
                self.assertFalse(storage.paths.context_doc_json(context_doc_id).exists())
                self.assertIsNone(store.context_task_for_doc(context_doc_id))

            asyncio.run(context_crud())

    def test_context_scheduler_runs_only_the_due_document_task(self) -> None:
        async def scenario(root: Path) -> None:
            storage = _make_test_storage(root)
            schedules = velox.ScheduledTaskStore(storage)
            docs = velox.ContextDocStore(storage, schedules)
            due_doc = docs.create_doc("Due", "Refresh the due doc.", 2000, "hourly")
            later_doc = docs.create_doc("Later", "Refresh the later doc.", 2000, "daily")
            due_task = schedules.context_task_for_doc(str(due_doc["context_doc_id"]))
            later_task = schedules.context_task_for_doc(str(later_doc["context_doc_id"]))
            schedules.update_task(str(due_task["scheduled_task_id"]), {
                "next_run_at": (datetime.now(timezone.utc) - timedelta(seconds=1)).isoformat(timespec="seconds"),
            })
            schedules.update_task(str(later_task["scheduled_task_id"]), {
                "next_run_at": (datetime.now(timezone.utc) + timedelta(hours=12)).isoformat(timespec="seconds"),
            })

            started: list[str] = []
            completed = asyncio.get_running_loop().create_future()

            class ContextService:
                def __init__(self) -> None:
                    self.docs = docs

                def start_refresh(self, context_doc_id: str) -> asyncio.Task[Any]:
                    started.append(context_doc_id)
                    async def finish() -> dict[str, Any]:
                        return docs.get_doc(context_doc_id)
                    task = asyncio.create_task(finish())
                    task.add_done_callback(lambda _done: completed.done() or completed.set_result(True))
                    return task

            scheduler = velox.ScheduledTaskScheduler(
                storage, schedules, velox.ChatStore(storage), velox.AgentStore(storage),
                SimpleNamespace(), ContextService(),
            )
            scheduler._last_tick = 0.0
            await scheduler.tick()
            await asyncio.wait_for(completed, timeout=2.0)
            await asyncio.sleep(0)
            self.assertEqual(started, [str(due_doc["context_doc_id"])])
            refreshed_task = schedules.get_task(str(due_task["scheduled_task_id"]))
            self.assertEqual(refreshed_task.get("run_count"), 1)
            self.assertGreater(
                datetime.fromisoformat(str(refreshed_task["next_run_at"])).timestamp(),
                datetime.now(timezone.utc).timestamp(),
            )
            untouched = schedules.get_task(str(later_task["scheduled_task_id"]))
            self.assertEqual(untouched.get("run_count"), 0)

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_due_one_off_inherits_chat_policy_and_resume_does_not_duplicate_trigger(self) -> None:
        async def scenario(root: Path) -> None:
            storage = _make_test_storage(root)
            chats = velox.ChatStore(storage)
            chat = chats.create_chat("Scheduled source")
            chat_id = str(chat["chat_id"])
            chats.set_chat_feature(velox.APP_SCOPE_ID, chat_id, "system_tools_enabled", False)
            chats.set_chat_feature(velox.APP_SCOPE_ID, chat_id, "web_tools_enabled", True)
            chats.set_chat_feature(velox.APP_SCOPE_ID, chat_id, "chat_history_enabled", False)
            agents = velox.AgentStore(storage)

            class Runtime:
                def __init__(self) -> None:
                    self.started: list[str] = []

                def start_agent(self, agent_id: str) -> bool:
                    self.started.append(agent_id)
                    agents.update_agent(agent_id, {"status": "running", "pause_requested": False})
                    return True

                def pause(self, agent_id: str) -> bool:
                    agents.update_agent(agent_id, {"status": "paused", "pause_requested": True})
                    return True

                def resume(self, agent_id: str) -> bool:
                    agents.update_agent(agent_id, {"status": "running", "pause_requested": False})
                    return True

                def cancel(self, agent_id: str) -> bool:
                    agents.update_agent(agent_id, {"status": "cancelled", "pause_requested": False})
                    return True

            runtime = Runtime()
            store = velox.ScheduledTaskStore(storage)
            scheduler = velox.ScheduledTaskScheduler(
                storage, store, chats, agents, runtime, SimpleNamespace(start_refresh=lambda: None),
            )
            due = store.create_once(
                "One-off inherited task", "Do the inherited-policy work.",
                run_at=(datetime.now(timezone.utc) - timedelta(seconds=2)).isoformat(timespec="seconds"),
                source_chat_id=chat_id,
            )
            scheduler._last_tick = 0.0
            await scheduler.tick()
            scheduled_id = str(due["scheduled_task_id"])
            active = store.get_task(scheduled_id)
            agent_id = str(active.get("active_agent_id") or "")
            self.assertTrue(velox.is_uuid_v4(agent_id))
            self.assertEqual(runtime.started, [agent_id])
            agent = agents.load_agent(agent_id)
            self.assertEqual(agent.get("endpoint_profile_id"), chats.get_chat_endpoint_profile_id(chat_id))
            self.assertEqual(agent.get("tool_features"), chats.get_chat_tool_features(chat_id))
            self.assertFalse(active.get("enabled"))
            self.assertEqual(active.get("next_run_at"), "")

            self.assertTrue(scheduler.pause(scheduled_id))
            paused_row = next(row for row in scheduler.rows() if row.get("scheduled_task_id") == scheduled_id)
            self.assertEqual(paused_row.get("agent_status"), "paused")
            self.assertTrue(scheduler.resume(scheduled_id))
            resumed = store.get_task(scheduled_id)
            self.assertFalse(resumed.get("enabled"))
            self.assertEqual(resumed.get("next_run_at"), "")
            self.assertEqual(agents.load_agent(agent_id).get("status"), "running")

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))


