    def test_context_doc_revisions_edit_restore_delete_and_lock_contract(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            storage = _make_test_storage(Path(td))
            docs = velox.ContextDocStore(storage)
            created = docs.create_doc("Editable", "Preserve durable facts.", 2000)
            doc_id = str(created["context_doc_id"])
            self.assertEqual(created.get("update_frequency"), "daily")
            self.assertFalse(created.get("locked"))

            docs.save_content(doc_id, "first version", source_summary="first")
            docs.save_content(doc_id, "second version", source_summary="second")
            rows = docs.revision_rows(doc_id)
            self.assertEqual(len(rows), 2)
            self.assertTrue(rows[0].get("is_current"))
            self.assertEqual(rows[0].get("revision_number"), 2)
            self.assertEqual((rows[0].get("doc") or {}).get("content"), "second version")
            history = rows[1]
            history_key = str(history.get("revision_key") or "")
            self.assertTrue(history_key.startswith("history:"))
            self.assertEqual((history.get("doc") or {}).get("content"), "first version")

            docs.update_revision_content(doc_id, history_key, "edited historical version")
            revised = next(row for row in docs.revision_rows(doc_id) if row.get("revision_key") == history_key)
            self.assertEqual((revised.get("doc") or {}).get("content"), "edited historical version")
            restored = docs.set_revision_as_current(doc_id, history_key)
            self.assertEqual(restored.get("content"), "edited historical version")

            docs.set_locked(doc_id, True)
            with self.assertRaises(PermissionError):
                docs.save_current_edits(doc_id, content="blocked")
            with self.assertRaises(PermissionError):
                docs.update_doc(doc_id, {"update_frequency": "hourly"})
            with self.assertRaises(PermissionError):
                docs.delete_revision(doc_id, history_key)
            docs.set_locked(doc_id, False)
            hourly = docs.update_doc(doc_id, {"update_frequency": "hourly"})
            self.assertEqual(hourly.get("update_frequency"), "hourly")
            refreshed = datetime.fromisoformat(str(hourly.get("last_refreshed_at")).replace("Z", "+00:00"))
            self.assertFalse(docs.refresh_due(hourly, now_utc=refreshed + timedelta(minutes=59)))
            self.assertTrue(docs.refresh_due(hourly, now_utc=refreshed + timedelta(minutes=61)))
            self.assertTrue(docs.delete_revision(doc_id, history_key))
            self.assertEqual(len(docs.revision_rows(doc_id)), 1)
            self.assertTrue(docs.revision_rows(doc_id)[0].get("is_current"))

