    def test_context_automatic_refresh_obeys_frequency_and_lock(self) -> None:
        async def scenario(root: Path) -> None:
            storage = _make_test_storage(root)
            docs = velox.ContextDocStore(storage)
            current = datetime.now(timezone.utc)
            daily = docs.create_doc("Daily", "Daily facts.", 2000)
            hourly = docs.create_doc("Hourly", "Hourly facts.", 2000)
            locked = docs.create_doc("Locked", "Locked facts.", 2000)
            docs.update_doc(str(daily["context_doc_id"]), {
                "last_refreshed_at": (current - timedelta(hours=2)).isoformat(timespec="seconds"),
                "update_frequency": "daily",
            })
            docs.update_doc(str(hourly["context_doc_id"]), {
                "last_refreshed_at": (current - timedelta(hours=2)).isoformat(timespec="seconds"),
                "update_frequency": "hourly",
            })
            docs.update_doc(str(locked["context_doc_id"]), {
                "last_refreshed_at": (current - timedelta(days=2)).isoformat(timespec="seconds"),
                "update_frequency": "daily",
            })
            docs.set_locked(str(locked["context_doc_id"]), True)
            service = velox.ContextDocService(
                storage, docs, velox.ChatStore(storage), velox.VaultStore(storage), velox.CalendarStore(storage),
                SimpleNamespace(), None,
            )
            refreshed_ids: list[str] = []

            async def fake_refresh(doc_id: str) -> dict[str, Any]:
                refreshed_ids.append(doc_id)
                return docs.get_doc(doc_id)

            service.refresh_doc = fake_refresh  # type: ignore[method-assign]
            results = await service.refresh_all(due_only=True)
            self.assertEqual(len(results), 1)
            self.assertEqual(refreshed_ids, [str(hourly["context_doc_id"])])

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_manual_and_due_context_refreshes_share_one_document_inference(self) -> None:
        class FakeLLM:
            def __init__(self) -> None:
                self.calls = 0
                self.started = asyncio.Event()
                self.release = asyncio.Event()

            async def chat_completions_once_full(self, request: LLMRequest) -> dict[str, Any]:
                return {"text": await self.chat_completions_once(request), "finish_reason": "stop"}

            async def chat_completions_once(self, request: LLMRequest) -> str:
                _ = request
                self.calls += 1
                self.started.set()
                await self.release.wait()
                return "deduplicated content"

        async def scenario(root: Path) -> None:
            storage = _make_test_storage(root)
            docs = velox.ContextDocStore(storage)
            doc = docs.create_doc("Concurrent", "Keep one fact.", 2000)
            fake = FakeLLM()
            service = velox.ContextDocService(
                storage, docs, velox.ChatStore(storage), velox.VaultStore(storage), velox.CalendarStore(storage), fake, None,
            )
            all_task = service.start_refresh(due_only=True)
            await fake.started.wait()
            same_doc_task = service.start_refresh(str(doc["context_doc_id"]))
            self.assertIs(same_doc_task, service.start_refresh(str(doc["context_doc_id"])))
            fake.release.set()
            await asyncio.gather(all_task, same_doc_task)
            self.assertEqual(fake.calls, 1)
            self.assertEqual(docs.get_doc(str(doc["context_doc_id"])).get("content"), "deduplicated content")

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

