class PerformanceTests(_WriterDataRootsIsolatedTestMixin, unittest.TestCase):
    """Long-chat layout and I/O cache behavior."""


    @staticmethod
    def _stores(root: Path) -> tuple[Storage, ScheduledTaskStore, ContextDocStore]:
        storage = velox.Storage(velox.AppPaths(root))
        storage.ensure_first_run_files()
        tasks = velox.ScheduledTaskStore(storage)
        docs = velox.ContextDocStore(storage, tasks)
        docs.ensure_layout(seed_defaults=False)
        return storage, tasks, docs

    def test_context_and_schedule_hot_views_reuse_validated_objects_without_io(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            _storage, tasks, docs = self._stores(Path(td))
            for index in range(4):
                created = docs.create_doc(f"Doc {index}", f"Goal {index}", 20_000)
                docs.save_content(str(created["context_doc_id"]), "x" * 8_000, source_summary="profile fixture")
            doc_view = docs.list_docs_view(external_poll_seconds=999.0)
            task_view = tasks.list_tasks_view(external_poll_seconds=999.0)
            prompt = docs.prompt_context(max_chars=25_000)
            with mock.patch.object(
                velox, "read_json",
                side_effect=AssertionError("hot cached view reparsed JSON"),
            ):
                for _ in range(50):
                    self.assertIs(docs.list_docs_view(external_poll_seconds=999.0), doc_view)
                    self.assertIs(tasks.list_tasks_view(external_poll_seconds=999.0), task_view)
                    self.assertIs(docs.prompt_context(max_chars=25_000), prompt)
            self.assertIsNot(docs.list_docs(), doc_view)
            self.assertIsNot(tasks.list_tasks(), task_view)

    def test_context_schedule_reconciliation_reads_one_task_snapshot(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            _storage, tasks, docs = self._stores(Path(td))
            for index in range(8):
                docs.create_doc(f"Doc {index}", f"Goal {index}", 12_000)
            rows = docs.list_docs_view(external_poll_seconds=999.0)
            with mock.patch.object(
                tasks, "list_tasks_view", wraps=tasks.list_tasks_view,
            ) as list_view:
                tasks.sync_context_docs(rows)
            self.assertEqual(list_view.call_count, 1)
            self.assertEqual(len(tasks.list_tasks_view()), len(rows))

    def test_json_reads_bytes_and_large_writes_are_compact(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            path = Path(td) / "large.json"
            payload = {"name": "context", "content": "z" * 250_000, "rows": list(range(100))}
            velox.atomic_write_json(path, payload)
            encoded = path.read_bytes()
            self.assertNotIn(b'\n  "', encoded)
            self.assertLess(len(encoded), len(json.dumps(payload, ensure_ascii=False, indent=2).encode("utf-8")))
            with mock.patch.object(
                velox, "file_read_text",
                side_effect=AssertionError("read_json decoded an intermediate text string"),
            ):
                self.assertEqual(velox.read_json(path), payload)
            self.assertIn("file_read_bytes(path)", inspect.getsource(velox.read_json))

    def test_owned_log_submission_avoids_deepcopy_and_double_compaction(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            writer = velox.BatchedJSONLWriter(batch_delay_seconds=10.0, write_batch=lambda _path, _rows: None)
            target = Path(td) / "log.jsonl"
            row = {"severity": "info", "level": 2, "datetime": velox.now_iso(), "log msg": "bounded"}
            with mock.patch.object(copy, "deepcopy", side_effect=AssertionError("owned log row was copied")):
                writer.submit_owned(target, row)
            writer.clear_for_tests()
        self.assertIn("submit_owned", inspect.getsource(velox.append_simple_log))
        storage_source = inspect.getsource(velox.Storage.append_app_log)
        self.assertIn("_compact_log_message_from_bounded", storage_source)
        self.assertEqual(storage_source.count("compact_log_payload("), 1)

    def test_streaming_layout_threshold_enters_incremental_path_immediately(self) -> None:
        font = _TestDummyFont(20, 8)
        markdown = velox.MarkdownLayoutEngine(font, font, font, font, font)
        cache = velox.LayoutCache(markdown)
        text = ("streaming line with **markdown**\n" * 90)
        self.assertGreaterEqual(len(text), velox.CHAT_STREAMING_INCREMENTAL_LAYOUT_MIN_CHARS)
        self.assertLess(len(text), velox.CHAT_LARGE_TEXT_INCREMENTAL_THRESHOLD_CHARS)
        with mock.patch.object(
            markdown, "layout_text_view",
            side_effect=AssertionError("streaming text waited for the completed-card threshold"),
        ):
            first = cache.get("streaming.medium", text, 640, incremental_large=True)
            second = cache.get("streaming.medium", text + "tail\n", 640, incremental_large=True)
        self.assertIs(first, second)
        self.assertEqual(cache.incremental_rebuilds, 1)
        self.assertEqual(cache.incremental_appends, 1)

    def test_incremental_cache_tracks_character_budget_without_resumming_entries(self) -> None:
        font = _TestDummyFont(20, 8)
        markdown = velox.MarkdownLayoutEngine(font, font, font, font, font)
        cache = velox.LayoutCache(markdown)
        for index in range(3):
            text = (f"card {index}\n" + ("x" * 72 + "\n") * 700)
            cache.get(f"budget.{index}", text, 640, incremental_large=True)
        self.assertEqual(cache.large_cache_chars, sum(len(state.text) for state in cache.large_cache.values()))
        trim_source = inspect.getsource(velox.LayoutCache._trim_large_cache)
        self.assertNotIn("sum(len(state.text)", trim_source)
        self.assertIn("large_cache_chars", trim_source)

    def test_terminal_chat_persistence_uses_worker_io_boundaries(self) -> None:
        report_source = inspect.getsource(velox.ChatRuntime._drain_agent_report_queue)
        compact_source = inspect.getsource(velox.ChatRuntime._maybe_compact_chat_context)
        manual_source = inspect.getsource(velox.ChatRuntime.compact_chat_now)
        self.assertIn("await self._append_turn_io", report_source)
        self.assertIn("await self._update_turn_io", report_source)
        self.assertGreaterEqual(compact_source.count("await self._update_turn_io"), 3)
        self.assertIn("await self._append_turn_io", compact_source)
        self.assertIn("await self._append_turn_io", manual_source)
        self.assertIn("await self._update_turn_io", manual_source)

    def test_performance_architecture_documents_profiled_hot_paths(self) -> None:
        self.assertIn("external_poll_seconds", inspect.signature(velox.ScheduledTaskStore.list_tasks_view).parameters)
        self.assertIn("external_poll_seconds", inspect.signature(velox.ContextDocStore.list_docs_view).parameters)
        self.assertTrue(callable(velox.iter_jsonl_tail))
        production = Path(velox.__file__).read_text(encoding="utf-8").split(
            "class ApplicationTests", 1,
        )[0]
        self.assertIn("list_tasks_view", production)
        self.assertIn("list_docs_view", production)
        self.assertNotIn("migrate_v", production)


class ContextCapacityAndIdleWorkTests(unittest.TestCase):
    """Request budgets, idle work and composer layout."""


    def test_final_payload_guard_clamps_output_and_rejects_zero_space(self) -> None:
        endpoint = {
            "context_window_tokens": 1_048_576,
            "max_output_tokens": 262_144,
            "model_type": velox.ENDPOINT_MODEL_TYPE_DEEPSEEK_V4,
        }
        messages = [{"role": "user", "content": "capacity edge"}]
        estimated_prompt = 786_433
        with mock.patch(
            velox.__name__ + ".estimate_request_messages_tokens",
            return_value=estimated_prompt,
        ):
            effective, capacity = velox.bounded_request_output_tokens(
                endpoint,
                messages=messages,
                native_tools=[],
                requested_output_tokens=262_144,
            )
        self.assertGreater(int(capacity["context_safety_tokens"]), 0)
        self.assertLess(effective, 262_144)
        self.assertEqual(
            effective,
            1_048_576 - int(capacity["context_safety_tokens"]) - estimated_prompt,
        )
        self.assertLessEqual(
            estimated_prompt + effective + int(capacity["context_safety_tokens"]),
            1_048_576,
        )

        with mock.patch(
            velox.__name__ + ".estimate_request_messages_tokens",
            return_value=1_048_576,
        ):
            with self.assertRaisesRegex(velox.LLMEndpointError, "cannot fit|exceeds"):
                velox.bounded_request_output_tokens(
                    endpoint,
                    messages=messages,
                    native_tools=[],
                    requested_output_tokens=1,
                )
            local_endpoint = dict(endpoint, provider=velox.ENDPOINT_PROVIDER_VLLM)
            delegated_output, delegated_capacity = velox.bounded_request_output_tokens(
                local_endpoint,
                messages=messages,
                native_tools=[],
                requested_output_tokens=262_144,
            )
        self.assertEqual(delegated_output, 262_144)
        self.assertTrue(delegated_capacity["local_estimate_exceeds_context"])
        self.assertTrue(delegated_capacity["provider_authoritative_overflow_check"])

    def test_chat_and_agent_recheck_capacity_after_every_tool_result(self) -> None:
        chat_source = inspect.getsource(velox.ChatRuntime._run_assistant_loop)
        tool_loop = chat_source.index("for call_group in execution_groups:")
        provisional = chat_source.index("provisional_assistant =", tool_loop)
        capacity_check = chat_source.index("prepared_request_capacity_snapshot(", provisional)
        counted = chat_source.index("tool_boundary_capacity_checks += 1", capacity_check)
        post_tool_pause = chat_source.index('"after tool call"', counted)
        append_results = chat_source.index("messages.extend(batch_protocol_results)", post_tool_pause)
        compact_before_next = chat_source.index(
            "_did_round_compact = await self._maybe_compact_chat_context(", append_results,
        )
        next_round = chat_source.index("continue", compact_before_next)
        self.assertLess(tool_loop, provisional)
        self.assertLess(provisional, capacity_check)
        self.assertLess(capacity_check, counted)
        self.assertLess(counted, post_tool_pause)
        self.assertLess(append_results, compact_before_next)
        self.assertLess(compact_before_next, next_round)
        self.assertIn("native_tools=native_tool_schemas", chat_source[capacity_check:next_round])
        # Tool batches, malformed protocol correction, broken-image correction,
        # and persistence continuations all pass through the same compactor.
        self.assertGreaterEqual(chat_source.count("_maybe_compact_chat_context("), 5)

        agent_source = inspect.getsource(velox.AgentRuntime._execute_pending_tool)
        append_agent_result = agent_source.index("openai_tool_result_message(")
        post_agent_tool = agent_source.index(
            "await self._maybe_compact_agent_context(", append_agent_result,
        )
        agent_return = agent_source.rindex("return True")
        self.assertLess(append_agent_result, post_agent_tool)
        self.assertLess(post_agent_tool, agent_return)
        self.assertIn("native_tools=self._native_tools_for_agent", agent_source[post_agent_tool:])

    def test_background_summaries_require_fifteen_seconds_of_true_idle(self) -> None:
        active = {"task": False, "tool": False}
        app = velox.VeloxApp.__new__(velox.VeloxApp)
        app.cached_idle_summary_seconds = 0.0
        app.ui_state = SimpleNamespace(is_user_idle=lambda _seconds: True)
        app.monitor = SimpleNamespace(
            has_active_tasks=lambda exclude_task_kinds=None: bool(active["task"]),
        )
        app.tools = SimpleNamespace(has_active_tool_calls=lambda: bool(active["tool"]))
        app.chat = SimpleNamespace(running={})
        app.agent_runtime = SimpleNamespace(running={})
        app._summary_true_idle_since_monotonic = None

        self.assertEqual(velox.BACKGROUND_SUMMARY_TRUE_IDLE_SECONDS, 15.0)
        self.assertFalse(app._background_summary_idle_ready(100.0))
        self.assertFalse(app._background_summary_idle_ready(114.999))
        self.assertTrue(app._background_summary_idle_ready(115.0))

        active["tool"] = True
        self.assertFalse(app._background_summary_idle_ready(116.0))
        self.assertIsNone(app._summary_true_idle_since_monotonic)
        active["tool"] = False
        self.assertFalse(app._background_summary_idle_ready(200.0))
        active["task"] = True
        self.assertFalse(app._background_summary_idle_ready(214.0))
        active["task"] = False
        self.assertFalse(app._background_summary_idle_ready(300.0))
        self.assertTrue(app._background_summary_idle_ready(315.0))

        idle_tick_source = inspect.getsource(velox.SummaryService.idle_tick)
        self.assertGreaterEqual(idle_tick_source.count("idle_guard"), 4)
        background_source = inspect.getsource(velox.VeloxApp.run_background_ticks)
        self.assertIn("self.summary_task.cancel()", background_source)
        self.assertIn("idle_guard=lambda: self._background_summary_idle_ready()", background_source)

