    def test_image_analysis_uses_dedicated_fallback_when_current_route_is_disabled(self) -> None:
        async def scenario(root: Path) -> None:
            storage, _chats, chat = self._storage(root)
            chat_id = str(chat["chat_id"])
            image_path = storage.paths.chat_workspace_dir(chat_id) / "isolated-route.png"
            image_path.parent.mkdir(parents=True, exist_ok=True)
            image_path.write_bytes(base64.b64decode(
                "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAusB9Y9ZV7sAAAAASUVORK5CYII="
            ))

            class FakeLLM:
                def __init__(self) -> None:
                    self.requests: list[LLMRequest] = []

                def resolve_endpoint(self, profile_id: str) -> dict[str, Any]:
                    return velox.endpoint_profile_for_id(storage.load_config(), profile_id)

                async def chat_completions_stream(self, request: LLMRequest):
                    self.requests.append(request)
                    yield velox.LLMChunk(
                        text="Isolated visual analysis complete.",
                        usage={"prompt_tokens": 30, "completion_tokens": 5},
                        done=True,
                        finish_reason="stop",
                    )

            config = storage.load_config()
            velox.endpoint_profile_ref(config, velox.DEFAULT_QWEN_3_8_ENDPOINT_PROFILE_ID)["image_analysis_context"] = "separate"
            storage.write_config(config)
            fake = FakeLLM()
            ctx = velox.ToolContext(
                scope_id=velox.APP_SCOPE_ID,
                chat_id=chat_id,
                endpoint_profile_id=velox.DEFAULT_QWEN_3_8_ENDPOINT_PROFILE_ID,
                monitor_task_id="task-main-chat",
                task_kind="chat",
                cancel_event=threading.Event(),
            )
            result = await velox.ImageTools(storage, fake).analyze(
                ctx,
                {"path": str(image_path), "prompt": "Read every visible label."},
            )
            self.assertEqual(result["mode"], "separate_context_streaming")
            self.assertEqual(result["endpoint_profile_id"], velox.DEFAULT_QWEN_3_8_ENDPOINT_PROFILE_ID)
            self.assertNotIn("native_" + "task_context", result)
            self.assertEqual(len(fake.requests), 1)
            request = fake.requests[0]
            self.assertEqual(request.endpoint_profile_id, velox.DEFAULT_QWEN_3_8_ENDPOINT_PROFILE_ID)
            self.assertIsNone(request.monitor_task_id)
            self.assertEqual(request.task_kind, "image")
            self.assertEqual(request.native_tools, None)
            self.assertEqual(len(request.messages), 2)
            self.assertEqual(velox.message_image_input_count(request.messages), 1)
            self.assertEqual(request.messages[0]["role"], "system")
            request_json = json.dumps(request.messages[1], ensure_ascii=False)
            self.assertIn("Read every visible label.", request_json)
            self.assertIn("data:image/png;base64,", request_json)
            self.assertNotIn("task-main-chat", json.dumps(request.task_metadata or {}))

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_terminal_dashboard_task_delete_clears_monitor_and_scheduler_slot(self) -> None:
        async def scenario(root: Path) -> None:
            storage = velox.Storage(velox.AppPaths(root))
            storage.ensure_first_run_files()
            monitor = velox.LLMTaskMonitor(storage)
            profile = velox.endpoint_profile_for_id(
                storage.load_config(), velox.DEFAULT_QWEN_3_8_ENDPOINT_PROFILE_ID,
            )
            scheduler = velox.EndpointInferenceScheduler(
                storage,
                lambda _profile_id: copy.deepcopy(profile),
                monitor=monitor,
            )
            task_id = monitor.start(
                velox.APP_SCOPE_ID,
                "Terminal deletion race",
                task_kind="chat",
                identity_key="chat:terminal-delete-race",
                metadata={
                    "chat_id": "chat-terminal-delete-race",
                    "endpoint_profile_id": velox.DEFAULT_QWEN_3_8_ENDPOINT_PROFILE_ID,
                    "endpoint_label": "Qwen 3.8 (vLLM)",
                },
            )
            request = velox.LLMRequest(
                scope_id=velox.APP_SCOPE_ID,
                endpoint_profile_id=velox.DEFAULT_QWEN_3_8_ENDPOINT_PROFILE_ID,
                messages=[{"role": "user", "content": "hello"}],
                monitor_task_id=task_id,
                task_kind="chat",
                task_title="Terminal deletion race",
            )
            lease = await scheduler.acquire(request)
            await lease.release()
            # Provider-request capacity is released immediately even though the
            # logical Chat Task remains running until its owner terminalizes.
            snap = scheduler.snapshot()[velox.DEFAULT_QWEN_3_8_ENDPOINT_PROFILE_ID]
            self.assertEqual(len(snap["active"]), 0)
            self.assertEqual(snap["slots_consumed"], 0)
            self.assertTrue(snap["slot_invariant_ok"])
            self.assertFalse(monitor.delete_task(task_id))
            monitor.complete(task_id)
            self.assertTrue(monitor.can_delete_task(task_id))
            self.assertTrue(monitor.delete_task(task_id))
            self.assertFalse(monitor.can_delete_task(task_id))
            self.assertEqual(monitor.record_state(task_id), "")
            self.assertEqual(monitor.task_view_snapshot(task_id), {})
            self.assertFalse(any(row.get("task_id") == task_id for row in monitor.dashboard_records(None)))
            for _ in range(20):
                await asyncio.sleep(0)
                active = scheduler.snapshot().get(
                    velox.DEFAULT_QWEN_3_8_ENDPOINT_PROFILE_ID, {},
                ).get("active", [])
                if not active:
                    break
            self.assertEqual(
                scheduler.snapshot().get(velox.DEFAULT_QWEN_3_8_ENDPOINT_PROFILE_ID, {}).get("active", []),
                [],
            )
            await scheduler.close()

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_five_way_tool_categories_filter_native_schemas(self) -> None:
        self.assertEqual(
            velox.CHAT_TOOL_CATEGORY_LABELS,
            (
                ("file_tools_enabled", "File"),
                ("system_tools_enabled", "System"),
                ("web_tools_enabled", "Web"),
                ("agent_tools_enabled", "Agent"),
                ("chat_history_enabled", "Chat"),
                ("checklists_enabled", "Checklists"),
            ),
        )
        self.assertEqual(velox.CHAT_TOOL_FEATURE_KEYS, tuple(key for key, _label in velox.CHAT_TOOL_CATEGORY_LABELS))
        with tempfile.TemporaryDirectory() as td:
            storage, chats, chat = self._storage(Path(td))
            chat_id = str(chat["chat_id"])
            registry = velox.ToolRegistry(storage)
            for key in velox.CHAT_TOOL_FEATURE_KEYS:
                chats.set_chat_feature(velox.APP_SCOPE_ID, chat_id, key, False)

            chats.set_chat_feature(velox.APP_SCOPE_ID, chat_id, "file_tools_enabled", True)
            file_names = {
                row["function"]["name"]
                for row in registry.build_openai_chat_completion_tools(velox.APP_SCOPE_ID, chat_id)
            }
            self.assertIn("fs_read", file_names)
            self.assertIn("doc_read", file_names)
            self.assertNotIn("python_exec", file_names)
            self.assertNotIn("web_search", file_names)
            self.assertNotIn("agents_start", file_names)
            self.assertNotIn("chats_search", file_names)

            chats.set_chat_feature(velox.APP_SCOPE_ID, chat_id, "file_tools_enabled", False)
            chats.set_chat_feature(velox.APP_SCOPE_ID, chat_id, "system_tools_enabled", True)
            system_names = {
                row["function"]["name"]
                for row in registry.build_openai_chat_completion_tools(velox.APP_SCOPE_ID, chat_id)
            }
            self.assertIn("python_exec", system_names)
            self.assertIn("image_analyze", system_names)
            self.assertNotIn("agents_start", system_names)
            self.assertNotIn("fs_read", system_names)
            self.assertNotIn("doc_read", system_names)
            self.assertEqual(registry._tool_group_for_name("fs_write"), "file_tools_enabled")
            self.assertEqual(registry._tool_group_for_name("doc_pdf_images"), "file_tools_enabled")
            self.assertEqual(registry._tool_group_for_name("shell_exec"), "system_tools_enabled")
            self.assertEqual(registry._tool_group_for_name("web_fetch"), "web_tools_enabled")
            self.assertEqual(registry._tool_group_for_name("agents_start"), "agent_tools_enabled")
            self.assertEqual(registry._tool_group_for_name("terminal_get_agent_terminals"), "agent_tools_enabled")
            self.assertEqual(registry._tool_group_for_name("chats_search"), "chat_history_enabled")

            chats.set_chat_feature(velox.APP_SCOPE_ID, chat_id, "system_tools_enabled", False)
            chats.set_chat_feature(velox.APP_SCOPE_ID, chat_id, "agent_tools_enabled", True)
            agent_names = {
                row["function"]["name"]
                for row in registry.build_openai_chat_completion_tools(velox.APP_SCOPE_ID, chat_id)
            }
            self.assertIn("agents_start", agent_names)
            self.assertIn("agents_list", agent_names)
            self.assertIn("terminal_get_agent_terminals", agent_names)
            self.assertNotIn("python_exec", agent_names)
            agent_only_prompt = str(
                velox.ContextAssembler(storage.paths).assemble_chat_context(velox.APP_SCOPE_ID, chat_id)[0]["content"]
            )
            self.assertIn("Enabled categories: Agent.", agent_only_prompt)
            self.assertIn("BACKGROUND AGENTS", agent_only_prompt)
            self.assertNotIn("INTERACTIVE TERMINALS", agent_only_prompt)
            chats.set_chat_feature(velox.APP_SCOPE_ID, chat_id, "agent_tools_enabled", False)
            self.assertNotIn(
                "agents_start",
                {row["function"]["name"] for row in registry.build_openai_chat_completion_tools(velox.APP_SCOPE_ID, chat_id)},
            )
            chats.set_chat_feature(velox.APP_SCOPE_ID, chat_id, "system_tools_enabled", True)
            with self.assertRaisesRegex(PermissionError, "agent tools"):
                registry._reject_disabled_tool(velox.APP_SCOPE_ID, "agents_start", chat_id)

