    def test_consecutive_image_groups_preserve_boundaries_and_order(self) -> None:
        calls = [
            {"name": "image_analyze", "id": 1},
            {"name": "image_analyze_ui", "id": 2},
            {"name": "fs_read", "id": 3},
            {"name": "image_analyze_3D_scene", "id": 4},
            {"name": "image_analyze", "id": 5},
            {"name": "web_search", "id": 6},
        ]
        groups = velox.consecutive_image_tool_groups(calls)
        self.assertEqual([[row["id"] for row in group] for group in groups], [[1, 2], [3], [4, 5], [6]])
        self.assertIs(groups[0][0], calls[0])
        self.assertIs(groups[2][1], calls[4])

    def test_chat_executes_adjacent_image_calls_concurrently_and_replays_in_order(self) -> None:
        async def scenario(root: Path) -> None:
            storage, chats, chat = self._storage(root)
            chat_id = str(chat["chat_id"])
            endpoint_profile_id = chats.get_endpoint_profile_id()
            endpoint = copy.deepcopy(velox.endpoint_profile_ref(storage.load_config(), endpoint_profile_id))
            provider_calls = [
                {
                    "id": f"call-{index}",
                    "type": "function",
                    "function": {
                        "name": "image_analyze",
                        "arguments": json.dumps({"path": f"image-{index}.png", "prompt": f"Inspect {index}"}),
                    },
                }
                for index in range(3)
            ]

            class FakeLLM:
                def __init__(self) -> None:
                    self.round = 0

                def resolve_endpoint(self, _profile_id: str) -> dict[str, Any]:
                    return copy.deepcopy(endpoint)

                async def chat_completions_stream(self, _request: LLMRequest):
                    self.round += 1
                    if self.round == 1:
                        yield velox.LLMChunk(
                            native_tool_calls=copy.deepcopy(provider_calls),
                            usage={"prompt_tokens": 100, "completion_tokens": 10},
                            done=True,
                            finish_reason="tool_calls",
                        )
                    else:
                        yield velox.LLMChunk(text="Parallel image evidence received.")
                        yield velox.LLMChunk(
                            usage={"prompt_tokens": 120, "completion_tokens": 8},
                            done=True,
                            finish_reason="stop",
                        )

            registry = velox.ToolRegistry(storage)
            active = 0
            max_active = 0
            completion_order: list[str] = []
            delays = {"image-0.png": 0.06, "image-1.png": 0.01, "image-2.png": 0.03}

            async def fake_execute(
                _scope_id: str, call: dict[str, Any], **kwargs: Any,
            ) -> dict[str, Any]:
                nonlocal active, max_active
                name, args = registry._normalize_tool_call(call)
                path = str(args["path"])
                active += 1
                max_active = max(max_active, active)
                try:
                    await asyncio.sleep(delays[path])
                    completion_order.append(path)
                finally:
                    active -= 1
                return {
                    "ok": True,
                    "status": "complete",
                    "tool_name": name,
                    "arguments": copy.deepcopy(args),
                    "result": {"path": path},
                    "tool_call_id": str(kwargs.get("tool_call_id") or velox.uuid_v4()),
                    "started_at": velox.now_iso(),
                    "ended_at": velox.now_iso(),
                    "elapsed_seconds": delays[path],
                }

            registry.execute_tool_call = fake_execute  # type: ignore[method-assign]
            runtime = velox.ChatRuntime(
                storage, chats, velox.ContextAssembler(storage.paths), FakeLLM(), registry,
            )
            runtime.set_visibility_provider(lambda _chat_id: False)
            chats.append_turn(velox.APP_SCOPE_ID, chat_id, velox.make_turn(chat_id, "user", "Inspect all images."))
            assistant = velox.make_turn(
                chat_id, "assistant", "", endpoint_profile_id=endpoint_profile_id,
                endpoint_label="Endpoint", status="streaming",
            )
            chats.append_turn(velox.APP_SCOPE_ID, chat_id, assistant, mark_stale=False)
            await runtime._run_assistant_loop(
                velox.APP_SCOPE_ID, chat_id, str(assistant["turn_id"]), endpoint_profile_id,
                "Inspect all images.", "parallel image-analysis test",
            )
            turns = chats.load_turns(velox.APP_SCOPE_ID, chat_id)
            tool_turn = next(
                row for row in turns
                if row.get("role") == "assistant" and row.get("tool_calls")
            )
            replayed = [
                str(((row.get("arguments") or {}).get("path") or ""))
                for row in tool_turn["tool_calls"]
            ]
            self.assertGreaterEqual(max_active, 2)
            self.assertNotEqual(completion_order, ["image-0.png", "image-1.png", "image-2.png"])
            self.assertEqual(replayed, ["image-0.png", "image-1.png", "image-2.png"])
            self.assertIn("Parallel image evidence received.", str(turns[-1].get("text") or ""))
            runtime.cancel_all()

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_image_endpoint_scheduler_bounds_parallel_calls_to_profile_capacity(self) -> None:
        async def scenario(root: Path) -> None:
            storage = velox.Storage(velox.AppPaths(root))
            storage.ensure_first_run_files()
            config = storage.load_config()
            image_profile_id = velox.endpoint_profile_id_from_config(config)
            profile = copy.deepcopy(velox.endpoint_profile_ref(config, image_profile_id))
            profile["max_concurrent_requests"] = 2
            scheduler = velox.EndpointInferenceScheduler(
                storage, lambda _profile_id: copy.deepcopy(profile), monitor=None,
            )
            active = 0
            max_active = 0

            async def one(index: int) -> None:
                nonlocal active, max_active
                lease = await scheduler.acquire(velox.LLMRequest(
                    scope_id=velox.APP_SCOPE_ID,
                    endpoint_profile_id=image_profile_id,
                    messages=[{"role": "user", "content": f"image {index}"}],
                    task_kind="image",
                    task_title=f"Image {index}",
                ))
                active += 1
                max_active = max(max_active, active)
                try:
                    await asyncio.sleep(0.025)
                finally:
                    active -= 1
                    await lease.release()

            await asyncio.gather(*(one(index) for index in range(6)))
            self.assertEqual(max_active, 2)
            snapshot = scheduler.snapshot().get(image_profile_id, {})
            self.assertEqual(snapshot.get("active", []), [])
            self.assertEqual(snapshot.get("queued", []), [])
            await scheduler.close()

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

