    def test_upward_wheel_disengages_autoscroll_even_inside_cooldown(self) -> None:
        self.assertFalse(velox.chat_autoscroll_state_after_manual_input(
            True,
            at_bottom=True,
            manual_scroll_started=True,
            manual_scroll_active=True,
            seconds_since_change=0.0,
            manual_scroll_away_from_bottom=True,
        ))
        self.assertTrue(velox.chat_autoscroll_state_after_manual_input(
            True,
            at_bottom=True,
            manual_scroll_started=True,
            manual_scroll_active=True,
            seconds_since_change=0.0,
            manual_scroll_away_from_bottom=False,
        ))
        self.assertFalse(velox.chat_autoscroll_state_after_manual_input(
            True,
            at_bottom=True,
            manual_scroll_started=True,
            manual_scroll_active=True,
            seconds_since_change=0.0,
            manual_scroll_grabbed=True,
        ))
        self.assertFalse(velox.chat_autoscroll_state_after_manual_input(
            True,
            at_bottom=False,
            manual_scroll_started=False,
            manual_scroll_active=True,
            seconds_since_change=0.0,
        ))
        self.assertFalse(velox.chat_autoscroll_state_after_manual_input(
            False,
            at_bottom=True,
            manual_scroll_started=False,
            manual_scroll_active=False,
            seconds_since_change=velox.CHAT_AUTOSCROLL_TOGGLE_COOLDOWN_SECONDS + 0.1,
        ))
        self.assertTrue(velox.chat_autoscroll_state_after_manual_input(
            False,
            at_bottom=True,
            manual_scroll_started=True,
            manual_scroll_active=True,
            seconds_since_change=0.0,
            manual_scroll_toward_bottom=True,
        ))
        source = inspect.getsource(velox.Panels.draw_chat_view)
        self.assertIn("wheel_away_from_bottom = wheel_delta > 0", source)
        self.assertIn("self.state.input.mouse_consumed = True", source)
        self.assertIn("scrollbar_drag_started", source)
        self.assertIn("manual_scroll_grabbed=scrollbar_drag_started", source)
        self.assertIn("if autoscroll_enabled and not manual_scroll_active", source)
        self.assertIn("manual_scroll_away_from_bottom=wheel_away_from_bottom", source)

