    def test_dashboard_round_metrics_publish_estimates_then_reconcile_exact_usage(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            storage = velox.Storage(velox.AppPaths(Path(td)))
            storage.ensure_first_run_files()
            monitor = velox.LLMTaskMonitor(storage)
            task_id = monitor.start(velox.APP_SCOPE_ID, "metric reconciliation", task_kind="chat")
            self.assertTrue(monitor.set_inference_round_metrics(
                task_id, "round-1",
                input_tokens=600, output_tokens=20,
                prefill_seconds=1.0, generation_seconds=0.5,
                estimated=True,
            ))
            live = monitor.record_metadata(task_id)
            self.assertEqual((live["input_tokens"], live["output_tokens"]), (600, 20))
            self.assertEqual(live["inference_count"], 1)
            self.assertTrue(live["current_inference_tokens_estimated"])

            self.assertTrue(monitor.set_inference_round_metrics(
                task_id, "round-1",
                input_tokens=395, output_tokens=25,
                prefill_seconds=0.8, generation_seconds=0.6,
                estimated=False, final=True,
            ))
            exact = monitor.record_metadata(task_id)
            self.assertEqual((exact["input_tokens"], exact["output_tokens"]), (395, 25))
            self.assertEqual(exact["inference_count"], 1)
            self.assertFalse(exact["current_inference_tokens_estimated"])
            self.assertFalse(exact["last_inference_tokens_estimated"])

            self.assertTrue(monitor.set_inference_round_metrics(
                task_id, "round-2",
                input_tokens=100, output_tokens=10,
                estimated=True, final=True,
            ))
            cumulative = monitor.record_metadata(task_id)
            self.assertEqual((cumulative["input_tokens"], cumulative["output_tokens"]), (495, 35))
            self.assertEqual(cumulative["inference_count"], 2)

    def test_prompt_progress_parser_and_bridge_preserve_latest_snapshot(self) -> None:
        self.assertEqual(
            velox.llm_prompt_progress_snapshot({
                "metrics": {"prompt_tokens_processed": 425, "prompt_tokens_total": 1000},
            }),
            (42.5, 425, 1000),
        )
        self.assertEqual(
            velox.llm_prompt_progress_snapshot({"usage": {"prefill_progress": 0.625}}),
            (62.5, None, None),
        )
        self.assertEqual(
            velox.llm_prompt_progress_snapshot({"prompt_progress_percent": 87.0}),
            (87.0, None, None),
        )
        self.assertEqual(
            velox.llm_prompt_progress_snapshot({"usage": {"prompt_tokens": 12345}}),
            (None, None, None),
        )

        loop = asyncio.new_event_loop()
        try:
            bridge = velox.LLMStreamChunkBridge(loop)
            with bridge._lock:
                bridge._append_pending_locked(velox.LLMChunk(
                    prompt_progress_percent=20.0,
                    prompt_tokens_processed=200,
                    prompt_tokens_total=1000,
                ))
                bridge._append_pending_locked(velox.LLMChunk(
                    prompt_progress_percent=55.0,
                    prompt_tokens_processed=550,
                    prompt_tokens_total=1000,
                ))
                batch = bridge._take_pending_locked()
            self.assertIsNotNone(batch)
            chunk = bridge._materialize_batch(batch or ())
            self.assertEqual(chunk.prompt_progress_percent, 55.0)
            self.assertEqual(chunk.prompt_tokens_processed, 550)
            self.assertEqual(chunk.prompt_tokens_total, 1000)
        finally:
            loop.close()

    def test_request_activity_advances_without_per_token_monitor_churn(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            storage = velox.Storage(velox.AppPaths(Path(td)))
            storage.ensure_first_run_files()
            monitor = velox.LLMTaskMonitor(storage)
            client = velox.LLMClient(storage)
            client.request_monitor = monitor
            task_id = monitor.start(
                velox.APP_SCOPE_ID, "activity test", task_kind="chat",
                metadata={"endpoint_label": "Endpoint", "task_type": "Chat"},
            )
            monitor.set_phase(task_id, "inference")
            client._set_request_activity(task_id, "prompt")
            first_revision = monitor.revision
            client._set_request_activity(task_id, "prompt")
            self.assertEqual(monitor.revision, first_revision)

            client._update_request_activity_from_chunk(task_id, velox.LLMChunk(
                prompt_progress_percent=33.0,
                prompt_tokens_processed=330,
                prompt_tokens_total=1000,
            ))
            prompt = monitor.record_metadata(task_id)
            self.assertEqual(prompt["activity"], "prompt")
            self.assertEqual(prompt["prompt_progress_percent"], 33.0)
            progress_revision = monitor.revision
            client._update_request_activity_from_chunk(task_id, velox.LLMChunk(
                prompt_progress_percent=33.0,
                prompt_tokens_processed=330,
                prompt_tokens_total=1000,
            ))
            self.assertEqual(monitor.revision, progress_revision)

            client._update_request_activity_from_chunk(
                task_id, velox.LLMChunk(reasoning_text="Inspecting the failure."),
            )
            self.assertEqual(monitor.record_metadata(task_id)["activity"], "thinking")
            client._update_request_activity_from_chunk(
                task_id, velox.LLMChunk(text="Here is the answer."),
            )
