    def test_stream_without_provider_usage_keeps_live_and_terminal_dashboard_estimates(self) -> None:
        async def scenario(root: Path) -> None:
            storage = velox.Storage(velox.AppPaths(root))
            storage.ensure_first_run_files()
            monitor = velox.LLMTaskMonitor(storage)
            client = velox.LLMClient(storage)
            scheduler = velox.EndpointInferenceScheduler(storage, client.resolve_endpoint, monitor)
            client.bind_request_scheduler(scheduler, monitor)

            async def fake_stream(_request: velox.LLMRequest):
                await asyncio.sleep(0.28)
                yield velox.LLMChunk(text="estimated output " * 80)
                await asyncio.sleep(0.01)
                yield velox.LLMChunk(done=True, usage={}, finish_reason="stop")

            client._chat_completions_stream_unqueued = fake_stream  # type: ignore[method-assign]
            task_id = monitor.start(
                velox.APP_SCOPE_ID, "usage omitted", task_kind="chat",
                metadata={"endpoint_label": "DeepSeek", "task_type": "Chat"},
            )
            terminal: LLMChunk | None = None
            saw_live_output = False
            async for chunk in client.chat_completions_stream(velox.LLMRequest(
                velox.APP_SCOPE_ID,
                velox.DEFAULT_DEEPSEEK_V4_FLASH_0731_ENDPOINT_PROFILE_ID,
                [{"role": "user", "content": "Count this request even without provider usage."}],
                monitor_task_id=task_id,
                task_kind="chat",
                task_title="usage omitted",
            )):
                terminal = chunk
                if not chunk.done:
                    metadata = monitor.record_metadata(task_id)
                    saw_live_output = int(metadata.get("output_tokens") or 0) > 0
            self.assertTrue(saw_live_output)
            self.assertIsNotNone(terminal)
            terminal_usage = dict((terminal.usage if terminal else {}) or {})
            self.assertGreater(int(terminal_usage.get("prompt_tokens") or 0), 0)
            self.assertGreater(int(terminal_usage.get("completion_tokens") or 0), 0)
            self.assertTrue(bool(terminal_usage.get("_velox_token_counts_estimated")))
            metadata = monitor.record_metadata(task_id)
            self.assertEqual(int(metadata["input_tokens"]), int(terminal_usage["prompt_tokens"]))
            self.assertEqual(int(metadata["output_tokens"]), int(terminal_usage["completion_tokens"]))
            self.assertEqual(int(metadata["inference_count"]), 1)
            monitor.complete(task_id)
            await scheduler.close()

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

