    def test_chat_stop_signals_request_before_task_cancel(self) -> None:
        async def scenario(root: Path) -> None:
            storage, chats, chat = self._storage(root)
            chat_id = str(chat["chat_id"])

            class DummyTools:
                def __init__(self) -> None:
                    self.cancelled: list[str] = []

                def request_cancel_chat_tool_calls(self, target: str, **_kwargs: Any) -> bool:
                    self.cancelled.append(target)
                    return True

                def cancel_chat_tool_calls(self, target: str, **_kwargs: Any) -> bool:
                    self.cancelled.append(target)
                    return True

                def cancel_all_tool_calls(self, **_kwargs: Any) -> None:
                    return None

            tools = DummyTools()
            runtime = velox.ChatRuntime(
                storage, chats, velox.ContextAssembler(storage.paths), SimpleNamespace(), tools,  # type: ignore[arg-type]
            )
            event = runtime._begin_chat_cancel_scope(chat_id)
            task = asyncio.create_task(asyncio.sleep(30.0))
            runtime.running[chat_id] = task
            runtime.cancel(chat_id)
            self.assertTrue(event.is_set())
            self.assertEqual(tools.cancelled, [chat_id])
            self.assertTrue(task.cancelled() or task.cancelling())
            with self.assertRaises(asyncio.CancelledError):
                await task

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_endpoint_response_close_is_dispatched_off_the_ui_loop(self) -> None:
        async def scenario(root: Path) -> None:
            storage = velox.Storage(velox.AppPaths(root))
            storage.ensure_first_run_files()
            client = velox.LLMClient(storage)
            cancel_event = threading.Event()

            class SlowCloseResponse:
                status = 200
                headers: dict[str, str] = {}

                def __init__(self) -> None:
                    self.readline_started = threading.Event()
                    self.unblock = threading.Event()
                    self.close_started = threading.Event()
                    self.close_finished = threading.Event()

                def __enter__(self) -> "SlowCloseResponse":
                    return self

                def __exit__(self, _exc_type: Any, _exc: Any, _tb: Any) -> bool:
                    return False

                def getcode(self) -> int:
                    return 200

                def geturl(self) -> str:
                    return "http://127.0.0.1/fake"

                def readline(self, _limit: int = -1) -> bytes:
                    self.readline_started.set()
                    self.unblock.wait(5.0)
                    return b""

                def close(self) -> None:
                    self.close_started.set()
                    time.sleep(0.5)
                    self.unblock.set()
                    self.close_finished.set()

            response = SlowCloseResponse()

            async def consume() -> None:
                async for _chunk in client._chat_completions_stream_unqueued(velox.LLMRequest(
                    velox.APP_SCOPE_ID,
                    velox.DEFAULT_DEEPSEEK_V4_FLASH_0731_ENDPOINT_PROFILE_ID,
                    [{"role": "user", "content": "cancel the blocked stream"}],
                    cancel_event=cancel_event,
                )):
                    pass

            with mock.patch.object(urllib.request, "urlopen", return_value=response):
                task = asyncio.create_task(consume())
                self.assertTrue(await asyncio.to_thread(response.readline_started.wait, 1.0))
                started = time.monotonic()
                cancel_event.set()
                task.cancel()
                with self.assertRaises(asyncio.CancelledError):
                    await task
                elapsed = time.monotonic() - started
                self.assertLess(elapsed, 0.25)
                self.assertTrue(await asyncio.to_thread(response.close_started.wait, 0.5))
                self.assertTrue(await asyncio.to_thread(response.close_finished.wait, 2.0))

            for method in (velox.LLMClient._chat_completions_stream_unqueued, velox.LLMClient._responses_stream):
                source = inspect.getsource(method)
                self.assertIn("close_dispatched = threading.Event()", source)
                self.assertIn("daemon=True", source)
                self.assertIn("dispatch_close_active_response()", source)
                self.assertNotIn("finally:\n            close_active_response()", source)

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

