        class FakeWebSocket:
            def __init__(self) -> None:
                self.calls = 0

            def command(self, method: str, _params: Any = None, **_kwargs: Any) -> dict[str, Any]:
                self.assert_method = method
                self.calls += 1
                if self.calls == 1:
                    value = {"readyState": "loading", "href": "about:blank"}
