def _raw_test_status_write(value: Any, *, fd: int = 1) -> None:
    """Emit one test-runner status line without buffered stream locks."""
    stream = _RawFDTestStream(fd)
    stream.write(str(value or "") + "\n")


def _publish_test_result(result: unittest.TestResult, expected_count: int) -> None:
    """Publish only a completed successful suite, bound to this process/count."""
    marker = str(os.environ.get("VELOX_TEST_SUCCESS_MARKER") or "").strip()
    if not marker or not result.wasSuccessful() or result.testsRun != expected_count:
        return
    payload = {
        "schema": f"velox_test_result.v{velox.SOURCE_REVISION}",
        "pid": os.getpid(), "tests": result.testsRun,
        "failures": len(result.failures), "errors": len(result.errors),
        "skipped": len(result.skipped), "successful": True,
    }
    destination = Path(marker)
    temporary = destination.with_name(destination.name + f".{os.getpid()}.tmp")
    try:
        with open(temporary, "wb") as handle:
            handle.write(json.dumps(payload, separators=(",", ":")).encode("utf-8"))
            handle.flush()
        os.replace(temporary, destination)
    except OSError:
        # Publication is the only evidence the parent accepts. If it fails, the
        # parent rejects the missing acknowledgement and fails the group.
        pass
    finally:
        try:
            temporary.unlink(missing_ok=True)
        except OSError:
            pass


def _test_result_matches(path: Path, pid: int, expected_count: int) -> bool:
    try:
        with open(path, "rb") as handle:
            raw = handle.read(4097)
        if len(raw) > 4096:
            return False
        value = json.loads(raw)
        return (isinstance(value, dict)
                and value.get("schema") == f"velox_test_result.v{velox.SOURCE_REVISION}"
                and type(value.get("pid")) is int and value["pid"] == pid
                and type(value.get("tests")) is int and value["tests"] == expected_count
                and type(value.get("failures")) is int and value["failures"] == 0
                and type(value.get("errors")) is int and value["errors"] == 0
                and type(value.get("skipped")) is int and 0 <= value["skipped"] <= expected_count
                and value.get("successful") is True)
    except (OSError, ValueError, TypeError):
        return False


def _child_identity_path(marker: Path) -> Path:
    """Path where the launched test interpreter records its real PID."""
    return Path(marker).with_name(Path(marker).name + ".identity")


def _write_child_identity(token: str, count: int) -> None:
    """Bind the running test interpreter to this launch before tests execute."""
    marker = str(os.environ.get("VELOX_TEST_SUCCESS_MARKER") or "").strip()
    if not marker or not token:
        return
    payload = {"token": token, "pid": os.getpid(), "count": count}
    path = _child_identity_path(Path(marker))
    try:
        with open(path, "wb") as handle:
            handle.write(json.dumps(payload, separators=(",", ":")).encode("utf-8"))
            handle.flush()
    except OSError:
        pass


def _read_child_identity(marker: Path, token: str) -> int:
    """Return the launched interpreter PID, or -1 when not yet/badly bound."""
    path = _child_identity_path(marker)
    try:
        with open(path, "rb") as handle:
            raw = handle.read(4097)
        if len(raw) > 4096:
            return -1
        value = json.loads(raw)
        if (
            isinstance(value, dict)
            and value.get("token") == token
            and type(value.get("pid")) is int
            and value["pid"] > 0
        ):
            return int(value["pid"])
    except (OSError, ValueError, TypeError):
        pass
    return -1


def run_test_class(class_name: str) -> NoReturn:
    """Run selected TestCase classes in this disposable child process.

    Comma-separated selectors may include ClassName@start:end ranges over sorted
    method names. Complete results and exit status are reported to the parent."""
    resolved_specs = [part.strip() for part in str(class_name or "").split(",") if part.strip()]
    if not resolved_specs:
        _fail_test_selection("No test class was supplied.")
    # Some source-contract tests need a production AST probe. Build it before any
    # fixture can start background workers; forking a probe after thread-heavy tests
    # can leave inherited pipe handles open on POSIX and make an otherwise completed
    # shard appear hung. The cache keeps later probe users in this process cheap.
    if any(
        spec.split("@", 1)[0] in {"ApplicationTests", "ConfigurationAndConnectorConcurrencyTests"}
        for spec in resolved_specs
    ):
        application_source_structure()

    suite = unittest.TestSuite()
    for resolved_spec in resolved_specs:
        resolved = resolved_spec
        start = 0
        end: int | None = None
        if "@" in resolved_spec:
            resolved, shard = resolved_spec.rsplit("@", 1)
            try:
                start_text, end_text = shard.split(":", 1)
                start = max(0, int(start_text or 0))
                end = max(start, int(end_text)) if end_text else None
            except Exception:
                _fail_test_selection(f"Invalid test shard: {resolved_spec}")
        test_class = globals().get(resolved)
        if not isinstance(test_class, type) or not issubclass(test_class, unittest.TestCase):
            _fail_test_selection(f"Unknown test class: {resolved}")
        names = unittest.defaultTestLoader.getTestCaseNames(test_class)
        selected_names = names[start:end]
        if not selected_names:
            _fail_test_selection(f"Test shard selected no tests: {resolved_spec}")
        suite.addTests(test_class(name) for name in selected_names)
    _count = suite.countTestCases()
    # Bind this launched interpreter (which may differ from the launcher PID on
    # a Windows virtual-environment redirector) before the suite runs so the
    # parent can validate the completed result against the real interpreter.
    _write_child_identity(str(os.environ.get("VELOX_TEST_RUN_TOKEN") or "").strip(), _count)
    result = unittest.TextTestRunner(stream=_RawFDTestStream(2), verbosity=2).run(suite)
    _publish_test_result(result, _count)
    # This command runs in a disposable shard process. Exit at the exact point
    # unittest has emitted its definitive result. Returning through the module's
    # fixture-heavy main/finally path can wait on unrelated native/background
    # finalizers even though every test has already finished.
    os._exit(0 if result.wasSuccessful() else 1)


def run_test_suite() -> int:
    """Discover the full suite and run each class in a disposable process.

    Native code, background writers and async fixtures need process isolation.
    Retain bounded execution and exact child-result checks so a hung fixture
    cannot be reported as a passing class."""
    module_suite = unittest.defaultTestLoader.loadTestsFromModule(sys.modules[__name__])
    class_rows: list[tuple[str, int]] = []
    for class_suite in module_suite:
        tests = list(class_suite)
        if tests:
            class_rows.append((tests[0].__class__.__name__, len(tests)))

    groups = [
        {
            "label": class_name,
            "argument": class_name,
            "count": count,
        }
        for class_name, count in class_rows
    ]

    velox.CoalescingAtomicJSONWriter.shutdown_all(timeout=3.0)
    velox.BatchedJSONLWriter.shutdown_all(timeout=3.0)

    def terminate_process_tree(process: subprocess.Popen[Any]) -> None:
        if process.poll() is not None:
            return
        if os.name == "nt":
            try:
                subprocess.run(
                    ["taskkill", "/PID", str(process.pid), "/T", "/F"],
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                    timeout=10,
                    check=False,
                )
                return
            except Exception:
                pass
        else:
            try:
                os.killpg(process.pid, signal.SIGTERM)
            except Exception:
                try:
                    process.terminate()
                except Exception:
                    pass
            try:
                process.wait(timeout=3)
                return
            except Exception:
                try:
                    os.killpg(process.pid, signal.SIGKILL)
                except Exception:
                    pass
        try:
            process.kill()
        except Exception:
            pass

    started = time.monotonic()
    total_count = 0
    total_confirmed = 0
    failed: list[tuple[str, int, str]] = []
    source_path = str(Path(__file__).resolve())
    trace_runner = bool(str(os.environ.get("VELOX_TEST_RUNNER_TRACE") or "").strip())
    if trace_runner and hasattr(signal, "SIGUSR1"):
        try:
            import faulthandler
            faulthandler.register(signal.SIGUSR1, file=sys.stderr, all_threads=True)
        except Exception:
            pass
    for row in groups:
        label = str(row["label"])
        argument = str(row["argument"])
        count = int(row["count"])
        total_count += count
        _raw_test_status_write(f"\n===== {label} ({count} tests) =====")
        kwargs: dict[str, Any] = {}
        if os.name == "nt":
            kwargs["creationflags"] = int(getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0))
        else:
            kwargs["start_new_session"] = True
        success_marker = Path(tempfile.gettempdir()) / (
            f"velox-v{velox.SOURCE_REVISION}-test-{os.getpid()}-{uuid.uuid4().hex}.ok"
        )
        child_env = os.environ.copy()
        child_env["VELOX_TEST_SUCCESS_MARKER"] = str(success_marker)
        child_token = uuid.uuid4().hex
        child_env["VELOX_TEST_RUN_TOKEN"] = child_token
        process = subprocess.Popen(
            [sys.executable, source_path, "--test-class", argument],
            stdout=None,
            stderr=None,
            env=child_env,
            **kwargs,
        )
        if trace_runner:
            _raw_test_status_write(f"[runner] started {label} pid={process.pid} marker={success_marker}", fd=2)
        timed_out = False
        success_marked = False
        finalizer_stall = False
        return_code = 1
        child_pid = process.pid
        identity_bound = False
        deadline = time.monotonic() + 1800.0
        while True:
            if not identity_bound:
                resolved_pid = _read_child_identity(success_marker, child_token)
                if resolved_pid > 0:
                    child_pid = resolved_pid
                    identity_bound = True
            polled = process.poll()
            if polled is not None:
                # A fast virtual-environment child may have completed and written
                # its identity before this loop observed the exit; bind it now so
                # the result is validated against the real interpreter.
                if not identity_bound:
                    resolved_pid = _read_child_identity(success_marker, child_token)
                    if resolved_pid > 0:
                        child_pid = resolved_pid
                        identity_bound = True
                return_code = int(polled or 0)
                success_marked = _test_result_matches(success_marker, child_pid, count)
                if trace_runner:
                    _raw_test_status_write(f"[runner] exited {label} rc={return_code} marker={success_marked}", fd=2)
                break
            if _test_result_matches(success_marker, child_pid, count):
                # Only this exact child's completed successful TestResult can
                # authorize bounded cleanup of a post-result finalizer stall.
                # Nested subprocess output cannot acknowledge this group.
                success_marked = True
                if trace_runner:
                    _raw_test_status_write(f"[runner] marker seen {label}", fd=2)
                try:
                    return_code = int(process.wait(timeout=5.0) or 0)
                except subprocess.TimeoutExpired:
                    finalizer_stall = True
                    terminate_process_tree(process)
                    try:
                        process.wait(timeout=10)
                    except Exception:
                        pass
                    # This deliberate post-result finalizer cleanup followed a
                    # validated completed success and is distinct from normal
                    # termination; the validated outcome is preserved.
                    return_code = 0
                break
            if time.monotonic() >= deadline:
                timed_out = True
                terminate_process_tree(process)
                try:
                    return_code = int(process.wait(timeout=10) or 1)
                except Exception:
                    return_code = 1
                break
            time.sleep(0.05)
        try:
            success_marker.unlink(missing_ok=True)
        except Exception:
            pass
        if timed_out:
            _raw_test_status_write(f"[error] {label} exceeded the 1800-second process timeout.")
        elif finalizer_stall:
            _raw_test_status_write(f"[runner] {label} validated result; bounded finalizer cleanup ran.")
        if timed_out:
            failed.append((label, count, "timeout"))
        elif return_code != 0:
            failed.append((label, count, f"nonzero exit {return_code}"))
        elif not success_marked:
            failed.append((label, count, "no validated completed-result record"))
        else:
            total_confirmed += count

    elapsed = time.monotonic() - started
    _raw_test_status_write("\n" + "=" * 72)
    if failed:
        _raw_test_status_write(f"Ran {total_confirmed} confirmed tests in {elapsed:.3f}s")
        _raw_test_status_write(
            "FAILED (groups: " + ", ".join(f"{name} [{reason}]" for name, _count, reason in failed) + ")"
        )
        _raw_test_status_write(
            "Unconfirmed expected counts: "
            + ", ".join(f"{name}={int(count)}" for name, count, _reason in failed)
        )
        return 1
    _raw_test_status_write(f"Ran {total_confirmed} tests in {elapsed:.3f}s")
    _raw_test_status_write("OK")
    return 0

def exit_after_tests(exit_code: int) -> NoReturn:
    """Bypass unsafe finalizers and potentially locked buffered streams.

    Test classes execute in disposable processes. Unittest writes its definitive
    result to stderr before this boundary. A fixture-owned background thread can
    hold a Python stream lock after the result is visible, so attempting one more
    high-level flush can deadlock an otherwise successful shard. Exit immediately;
    individual writer-shutdown behavior has dedicated tests.
    """
    os._exit(int(exit_code))


class ChecklistToolsAndTaskIdentityTests(_DataRootsIsolatedTestMixin, unittest.TestCase):
    """Tool startup, task identity and checklist state transitions."""

    @staticmethod
    def _fixture(root: Path) -> tuple[AppPaths, Storage, ChatStore, dict[str, Any]]:
        paths = velox.AppPaths(root)
        storage = velox.Storage(paths)
        storage.ensure_first_run_files()
        chats = velox.ChatStore(storage)
        return paths, storage, chats, chats.create_chat("Checklist regression")

    @staticmethod
    def _update(
        requirement_id: str,
        status: str,
        progress: str = "",
        next_step: str = "",
    ) -> dict[str, str]:
        return {
            "requirement_id": requirement_id,
            "status": status,
            "progress": progress,
            "next_step": next_step,
        }

    def test_tool_definition_constructor_contract_and_registry_startup(self) -> None:
        instance = velox.ToolDefinition.__new__(velox.ToolDefinition)
        returned = velox.ToolDefinition.__init__(
            instance, "sample", "Sample", {"type": "object"}, lambda _ctx, _args: None,
        )
        self.assertIsNone(returned)
        self.assertEqual(instance.positional_arguments, ())
        with self.assertRaisesRegex(TypeError, "positional_arguments cannot be None"):
            velox.ToolDefinition("bad", "Bad", {}, lambda _ctx, _args: None, None)  # type: ignore[arg-type]
        with tempfile.TemporaryDirectory() as td:
            _paths, storage, _chats, _chat = self._fixture(Path(td))
            registry = velox.ToolRegistry(storage)
            self.assertEqual(len(registry.tools), len(velox.TOOL_POSITIONAL_SIGNATURES))
            self.assertTrue(velox.EXPERT_MODE_TOOL_NAMES.issubset(registry.tools))
            for name, definition in registry.tools.items():
                self.assertIsInstance(definition.positional_arguments, tuple, name)
                self.assertEqual(definition.positional_arguments, velox.TOOL_POSITIONAL_SIGNATURES[name], name)

    def test_chat_send_builds_tool_schema_without_none_positional_arguments(self) -> None:
        async def scenario(root: Path) -> None:
            paths, storage, chats, chat = self._fixture(root)
            chat_id = str(chat["chat_id"])
            endpoint_id = chats.get_chat_endpoint_profile_id(chat_id)

            class FakeLLM:
                def __init__(self) -> None:
                    self.requests: list[LLMRequest] = []
                def resolve_endpoint(self, profile_id: str) -> dict[str, Any]:
                    return copy.deepcopy(velox.endpoint_profile_ref(storage.load_config(), profile_id))
                async def chat_completions_stream(self, request: LLMRequest):
                    self.requests.append(copy.deepcopy(request))
                    yield velox.LLMChunk(text="Chat send completed.")
                    yield velox.LLMChunk(done=True, finish_reason="stop")

            fake = FakeLLM()
            runtime = velox.ChatRuntime(storage, chats, velox.ContextAssembler(paths), fake, velox.ToolRegistry(storage))
            user = velox.make_turn(chat_id, "user", "Say hello", endpoint_profile_id=endpoint_id)
            assistant = velox.make_turn(chat_id, "assistant", "", status="streaming", endpoint_profile_id=endpoint_id)
            chats.append_turn(velox.APP_SCOPE_ID, chat_id, user)
            chats.append_turn(velox.APP_SCOPE_ID, chat_id, assistant, mark_stale=False)
            await runtime._run_assistant_loop(
                velox.APP_SCOPE_ID, chat_id, str(assistant["turn_id"]), endpoint_id,
                str(user["text"]), "ordinary Chat Send regression",
            )
            self.assertEqual(len(fake.requests), 1)
            self.assertTrue(fake.requests[0].native_tools)
            self.assertTrue(any(
                item.get("function", {}).get("name") == "checklist_create"
                for item in fake.requests[0].native_tools or []
            ))
            turns = chats.load_turns(velox.APP_SCOPE_ID, chat_id)
            self.assertEqual(turns[-1]["status"], "complete")
            self.assertIn("Chat send completed", turns[-1]["text"])
            runtime.cancel_all()

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

