class TranscriptScrollingAndToolRowsTests(_DataRootsIsolatedTestMixin, unittest.TestCase):
    """Regression coverage for human-friendly tool scrolling and visual repair escalation."""


    def test_follow_scroll_preserves_bottom_anchor_across_growth_and_shrink(self) -> None:
        self.assertEqual(
            velox.chat_follow_scroll_position(
                600, previous_max_scroll=600, max_scroll=648, line_height=18,
            ),
            648,
        )
        self.assertEqual(
            velox.chat_follow_scroll_position(
                648, previous_max_scroll=648, max_scroll=604, line_height=18,
            ),
            604,
        )
        lagged = velox.chat_follow_scroll_position(
            560, previous_max_scroll=600, max_scroll=648, line_height=18,
        )
        self.assertGreater(lagged, 608)
        self.assertLess(lagged, 648)

    def test_tool_preview_is_replaced_by_one_atomic_pending_batch(self) -> None:
        runtime = velox.ChatRuntime.__new__(velox.ChatRuntime)
        calls = [
            {
                "name": "fs_read",
                "raw_call": '{"path":"a.txt"}',
                "provider_tool_call_id": "call-a",
                "provider_tool_call": {"id": "call-a", "type": "function"},
            },
            {
                "name": "image_analyze_3D_scene",
                "raw_call": '{"path":"frame.png","prompt":"review"}',
                "provider_tool_call_id": "call-b",
                "provider_tool_call": {"id": "call-b", "type": "function"},
            },
        ]
        rows: list[dict[str, Any]] = []
        text, prepared = runtime._prepare_visible_tool_batch("Answer", rows, calls)
        self.assertEqual(len(rows), 2)
        self.assertEqual(len(prepared), 2)
        self.assertTrue(all(row.get("status") == "running" for row in rows))
        self.assertIn("[[VELOX_TOOL_ROW:0]]", text)
        self.assertIn("[[VELOX_TOOL_ROW:1]]", text)

        source = inspect.getsource(velox.ChatRuntime._run_assistant_loop)
        prepare_at = source.index("visible_prepared_calls = self._prepare_visible_tool_batch")
        publish_at = source.index('tool_preview=""', prepare_at)
        execute_at = source.index("for call_group in execution_groups", publish_at)
        self.assertLess(prepare_at, publish_at)
        self.assertLess(publish_at, execute_at)
        transition = source[prepare_at:execute_at]
        self.assertEqual(transition.count("self._update_assistant_stream("), 1)

