class RateLimitEncodingAndDecisionTests(_DataRootsIsolatedTestMixin, unittest.TestCase):
    """Subprocess decoding, request cooldowns and image-analysis output."""


    def test_subprocess_capture_decodes_invalid_bytes_without_reader_thread_failure(self) -> None:
        decoded = velox.decode_captured_subprocess_output(b"prefix\x90suffix")
        self.assertIsInstance(decoded, str)
        self.assertIn("prefix", decoded)
        self.assertIn("suffix", decoded)

        async def scenario(root: Path) -> None:
            script = (
                "import os; "
                "os.write(1, b'out-prefix\\x90out-suffix'); "
                "os.write(2, b'err-prefix\\x81err-suffix')"
            )
            result = await velox.run_cancellable_subprocess(
                velox.ToolContext(velox.APP_SCOPE_ID, cancel_event=threading.Event()),
                [sys.executable, "-c", script],
                cwd=root,
                timeout_seconds=10,
                shell=False,
            )
            self.assertEqual(result.returncode, 0)
            self.assertIn("out-prefix", result.stdout)
            self.assertIn("out-suffix", result.stdout)
            self.assertIn("err-prefix", result.stderr)
            self.assertIn("err-suffix", result.stderr)

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))
        source = inspect.getsource(velox.run_cancellable_subprocess)
        self.assertNotIn("text=True", source)
        self.assertIn("stdout_bytes, stderr_bytes", source)
        self.assertIn("decode_captured_subprocess_output", source)

    def test_endpoint_budget_waits_once_limit_is_reached_and_can_be_disabled(self) -> None:
        async def scenario() -> None:
            enabled = velox.default_endpoint_profile(
                "novita-rate-test", "Novita rate test", timeout_seconds=60,
                provider=velox.ENDPOINT_PROVIDER_NOVITA,
            )
            enabled["rate_limit_requests_per_minute"] = 1
            limiter = velox.EndpointRequestRateLimiter(window_seconds=0.03)
            self.assertEqual(await limiter.acquire(enabled), 0.0)
            started = time.monotonic()
            waited = await limiter.acquire(enabled)
            elapsed = time.monotonic() - started
            self.assertGreaterEqual(waited, 0.02)
            self.assertGreaterEqual(elapsed, 0.02)

            disabled = velox.default_endpoint_profile(
                "openai-rate-test", "OpenAI rate test", timeout_seconds=60,
                provider=velox.ENDPOINT_PROVIDER_OPENAI,
            )
            disabled["rate_limit_requests_per_minute"] = 1
            self.assertFalse(velox.endpoint_rate_limit_enabled(disabled))
            self.assertEqual(await limiter.acquire(disabled), 0.0)

            local = velox.default_endpoint_profile(
                "vllm-rate-test", "vLLM rate test", timeout_seconds=60,
                provider=velox.ENDPOINT_PROVIDER_VLLM,
            )
            self.assertFalse(velox.endpoint_rate_limit_enabled(local))

        asyncio.run(scenario())

    def test_retry_after_and_retryable_overload_statuses_are_preserved(self) -> None:
        details = velox.llm_endpoint_error_recovery_details(velox.LLMEndpointError(
            "HTTP 429 Too Many Requests",
            status_code=429,
            response_body='{"message":"request quota exceeded"}',
            response_headers={"Retry-After": "120"},
        ))
        self.assertIsNotNone(details)
        self.assertEqual(details["status_code"], 429)
        self.assertEqual(details["retry_after_seconds"], 120.0)
        for status in (500, 502, 503, 504, 529):
            self.assertIsNotNone(velox.llm_endpoint_error_recovery_details(velox.LLMEndpointError(
                f"HTTP {status} provider overload", status_code=status,
            )))
        self.assertIsNone(velox.llm_endpoint_error_recovery_details(velox.LLMEndpointError(
            "HTTP 401 Unauthorized", status_code=401,
        )))

    def test_request_paths_stats_and_toolbar_expose_cooldown_time(self) -> None:
        source_stream = inspect.getsource(velox.LLMClient._chat_completions_stream_attempt)
        source_once = inspect.getsource(velox.LLMClient._chat_completions_once_full_attempt)
        self.assertIn("_wait_for_endpoint_request_budget", source_stream)
        self.assertIn("_wait_for_endpoint_request_budget", source_once)
        self.assertIn("endpoint_wait_seconds", source_stream)
        self.assertIn("endpoint_wait_seconds", source_once)

        runtime = velox.ChatRuntime.__new__(velox.ChatRuntime)
        started = time.time() - 20.0
        stats = runtime._make_stats(
            started, started + 2.0, "answer", [],
            {
                "prompt_tokens": 100,
                "completion_tokens": 20,
                "_velox_prefill_seconds": 2.0,
                "_velox_generation_seconds": 3.0,
                "_rate_limit_cooldown_seconds_total": 7.0,
                "_inference_completed_at": started + 5.0,
            },
        )
        self.assertAlmostEqual(stats["endpoint_wait_seconds"], 7.0, places=2)
        self.assertAlmostEqual(stats["inference_seconds"], 5.0, places=2)
        self.assertAlmostEqual(stats["overhead_seconds"], 8.0, delta=0.25)

        class FakeMonitor:
            def record_snapshot(self, _task_id: str) -> dict[str, Any]:
                return {
                    "state": "running",
                    "metadata": {
                        "phase": "inference",
                        "activity": "cooldown",
                        "cooldown_until_monotonic": time.monotonic() + 30.0,
                        "cooldown_reason": "Endpoint request budget reached",
                        "cooldown_attempt": 2,
                        "cooldown_maximum": 10,
                        "endpoint_wait_seconds": 61.0,
                    },
                }

        panel = velox.Panels.__new__(velox.Panels)
        panel.state = SimpleNamespace(active_chat_id="chat-rate")
        panel.services = SimpleNamespace(
            chat=SimpleNamespace(
                monitor=FakeMonitor(),
                _monitor_task_ids={"chat-rate": "task-rate"},
            )
        )
        label, tooltip = panel._chat_toolbar_activity([])
        self.assertTrue(label.startswith("Cooldown "))
        self.assertIn("Retry: 2/10", tooltip)
        self.assertIn("Accumulated endpoint cooldown", tooltip)

    def test_retry_cooldowns_accumulate_across_chat_and_agent_attempts(self) -> None:
        source = inspect.getsource(velox.LLMClient.chat_completions_stream)
