    def test_repeated_reviews_need_no_web_research_or_recovery_payload(self) -> None:
        async def scenario(root: Path) -> None:
            from PIL import Image  # type: ignore
            paths = velox.AppPaths(root)
            storage = velox.Storage(paths)
            storage.ensure_first_run_files()
            chat_id = str(velox.ChatStore(storage).create_chat("Unrestricted visual review")["chat_id"])
            frame = paths.chat_workspace_dir(chat_id) / "camera-frame.png"
            Image.new("RGB", (8, 8), (20, 40, 80)).save(frame, format="PNG")

            class Vision:
                def __init__(self) -> None:
                    self.calls = 0
                def resolve_endpoint(self, profile_id: str) -> dict[str, Any]:
                    return velox.endpoint_profile_ref(storage.load_config(), profile_id)
                async def chat_completions_stream(self, _request: LLMRequest):
                    self.calls += 1
                    yield velox.LLMChunk(text="The camera orientation appears visibly wrong; use a fixed side view to confirm.")
                    yield velox.LLMChunk(done=True, finish_reason="stop")

            storage.update_config(lambda cfg: velox.endpoint_profile_ref(cfg, velox.DEFAULT_ENDPOINT_PROFILE_ID).update(image_analysis_context="separate"))
            fake = Vision()
            tools = velox.ImageTools(storage, fake)  # type: ignore[arg-type]
            ctx = velox.ToolContext(velox.APP_SCOPE_ID, chat_id=chat_id, endpoint_profile_id=velox.DEFAULT_ENDPOINT_PROFILE_ID, cancel_event=threading.Event(), allow_web_search=False)
            for _ in range(4):
                result = await tools.analyze_3d_scene(ctx, {
                    "path": str(frame), "prompt": "Review the fixed camera orientation.",
                })
                self.assertIn("visibly wrong", result["analysis"])
                self.assertNotIn("strategy_reset", json.dumps(result))
            self.assertEqual(fake.calls, 4)
            probe = tools.pixel_probe(ctx, {"path": str(frame), "x": 0, "y": 0, "radius": 0})
            self.assertIn("point", probe)
            self.assertNotIn("image_sha256", probe)
            self.assertNotIn("visual_evidence_context", probe)

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_visual_tool_schema_has_no_mandatory_research_or_recovery_packet(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            storage = velox.Storage(velox.AppPaths(Path(td)))
            storage.ensure_first_run_files()
            registry = velox.ToolRegistry(storage)
            for name in ("image_analyze", "image_analyze_ui", "image_analyze_3D_scene"):
                schema = registry.tools[name].parameters
                self.assertEqual(set(schema["properties"]), {"path", "prompt"})
                self.assertEqual(set(schema["required"]), {"path", "prompt"})
                encoded = json.dumps(schema, sort_keys=True)
                for removed in (
                    "strategy_reset_evidence", "web_search_queries", "reference_sources",
                    "reference_comparison", "minimal_fixture", "fresh_implementation",
                    "diagnostic_capture_plan", "independent_oracle",
                ):
                    self.assertNotIn(removed, encoded)
            self.assertIn("Measure exact RGBA", registry.tools["image_pixel_probe"].description)
            self.assertIn("Measure color, alpha", registry.tools["image_region_stats"].description)

        combined = "\n".join((
            velox.ContextAssembler.BUILD_TEST_VISUAL_GUIDANCE,
            velox.ContextAssembler.WEB_RESEARCH_GUIDANCE,
            velox.DEFAULT_IMAGE_ANALYSIS_SKILL_MARKDOWN,
            velox.DEFAULT_GENERAL_PROGRAMMING_SKILL_MARKDOWN,
            velox.DEFAULT_3D_RENDERING_PROGRAMMING_SKILL_MARKDOWN,
        ))
        for phrase in (
            "Respect the pixels", 'Resolve conflicting image findings', 'stronger evidence',
            'primary API documentation', 'A fresh implementation from the written contract is useful when simpler',
            'Choose diagnostics for the defect',
        ):
            self.assertIn(phrase, combined)
        for removed in ("strategy_reset_required", "strategy_reset_evidence", "acceptanceBlocked"):
            self.assertNotIn(removed, combined)
        self.assertIn('visible observation', velox.IMAGE_ANALYSIS_3D_SCENE_ENDPOINT_SYSTEM_PROMPT.lower())
        self.assertIn('hypothesis', velox.IMAGE_ANALYSIS_3D_SCENE_ENDPOINT_SYSTEM_PROMPT.lower())

