class TextWrappingUsageAndPromptTests(_DataRootsIsolatedTestMixin, unittest.TestCase):
    """Wrapping, token accounting, task times and prompt construction."""


    def test_cached_input_is_a_subset_not_an_extra_input_charge(self) -> None:
        turn = velox.make_turn(velox.uuid_v4(), "assistant", "response")
        usage = {"prompt_tokens": 100, "completion_tokens": 10, "prompt_tokens_details": {"cached_tokens": 40}}
        turn["stats"] = {"input_tokens": 100, "output_tokens": 10, **velox.llm_cache_usage_summary(usage)}
        aggregate = velox.chat_thread_runtime_stats([turn])
        self.assertEqual((aggregate["input_tokens"], aggregate["output_tokens"]), (100, 10))
        self.assertEqual(aggregate["cached_input_tokens"], 40)
        self.assertEqual(aggregate["cache_reported_rounds"], 1)
        self.assertNotIn("normal_input_tokens", aggregate)

    def test_chat_and_monitor_keep_total_input_and_cache_reporting_coverage(self) -> None:
        first = velox.make_turn(velox.uuid_v4(), "assistant", "first")
        first["stats"] = {"input_tokens": 100, "output_tokens": 10,
                          **velox.llm_cache_usage_summary({"prompt_tokens": 100, "prompt_cache_hit_tokens": 40})}
        second = velox.make_turn(first["chat_id"], "assistant", "second")
        second["stats"] = {"input_tokens": 50, "output_tokens": 5}
        aggregate = velox.chat_thread_runtime_stats([first, second])
        self.assertEqual((aggregate["input_tokens"], aggregate["output_tokens"]), (150, 15))
        self.assertEqual(aggregate["cached_input_tokens"], 40)
        self.assertEqual(aggregate["cache_reported_rounds"], 1)
        self.assertEqual(aggregate["cache_total_rounds"], 2)
        with tempfile.TemporaryDirectory() as td:
            storage = _make_test_storage(Path(td)); monitor = velox.LLMTaskMonitor(storage)
            tid = monitor.start(velox.APP_SCOPE_ID, "Cache-aware total tokens", task_kind="chat")
            monitor.set_inference_round_metrics(tid, "r1", input_tokens=100, output_tokens=10, cached_input_tokens=40)
            monitor.set_inference_round_metrics(tid, "r1", input_tokens=120, output_tokens=12, cached_input_tokens=60, final=True)
            monitor.set_inference_round_metrics(tid, "r2", input_tokens=30, output_tokens=3, final=True)
            row = monitor.record_snapshot(tid); totals = monitor.statistics()
            for result in (row, totals):
                self.assertEqual((result["input_tokens"], result["output_tokens"]), (150, 15))
                self.assertEqual(result["cached_input_tokens"], 60)
                self.assertEqual(result["cache_total_rounds"], 2)
                self.assertEqual(result["cache_reported_rounds"], 1)
            self.assertEqual(totals["total_tokens"], 165)

    def test_agent_records_persist_total_input_and_output_only(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            storage = velox.Storage(velox.AppPaths(Path(td)))
            storage.ensure_first_run_files()
            chat = velox.ChatStore(storage).create_chat("Strict total tokens")
            agents = velox.AgentStore(storage)
            agent = agents.create_agent(
                str(chat["chat_id"]), "Count total tokens.",
                endpoint_profile_id=velox.DEFAULT_ENDPOINT_PROFILE_ID,
            )
            validated = velox.validate_agent_record(agent, expected_agent_id=str(agent["agent_id"]))
            self.assertEqual((validated["input_tokens"], validated["output_tokens"]), (0, 0))
            for field in velox.CACHE_USAGE_FIELDS:
                self.assertEqual(validated[field], 0)
            self.assertNotIn("cached_input_tokens_reported", validated)

            old_revision = copy.deepcopy(agent)
            old_revision["data_version"] = "v237"
            with self.assertRaises(velox.UnsupportedDataVersionError):
                velox.validate_agent_record(old_revision, expected_agent_id=str(agent["agent_id"]))

    def test_wrap_table_policy_changes_layout_and_invalidates_outer_chat_geometry(self) -> None:
        class FakeFont:
            line_h = 20
            char_w = 8
            glyphs: dict[str, Any] = {}

            @staticmethod
            def text_width(text: Any) -> int:
                return len(str(text)) * 8

        font = FakeFont()
        markdown = velox.MarkdownLayoutEngine(font, font, font, font, font, table_word_wrap=False)
        text = (
            "| Long heading with words | Other |\n"
            "|---|---|\n"
            "| This long table cell must wrap onto several visible lines at this width | short |"
        )
        unwrapped = markdown.layout_text_view(text, 240)
        self.assertTrue(markdown.set_table_word_wrap(True))
        wrapped = markdown.layout_text_view(text, 240)
        self.assertGreater(wrapped.height, unwrapped.height)
        self.assertLessEqual(wrapped.width, unwrapped.width)

        section = {
            "text": text, "turn": {"turn_id": velox.uuid_v4(), "updated_at": velox.now_iso()},
            "kind": "assistant", "attachments": [], "inline_media": [], "inline_tools": [],
            "_chat_body_geometry_cache": {"old": True},
            "_chat_row_layout_cache": {"old": True},
        }
        panel = velox.Panels.__new__(velox.Panels)
        panel.widgets = SimpleNamespace(
            font=font, layout_cache=SimpleNamespace(md=SimpleNamespace(table_word_wrap=False)),
        )
        first_signature = panel._chat_section_measure_signature(section, 220, 240, 260)
        panel.widgets.layout_cache.md.table_word_wrap = True
        second_signature = panel._chat_section_measure_signature(section, 220, 240, 260)
        self.assertNotEqual(first_signature, second_signature)

        panel.state = SimpleNamespace(
            chat_sections_cache=[section],
            chat_turn_cache_key="turn-key", chat_turn_cache_identity="identity",
            chat_section_measure_cache={"old": 1}, chat_section_estimate_cache={"old": 1},
            chat_sections_cache_key="sections", chat_sections_source_turns=[{}],
            chat_sections_turn_ranges=[(0, 1)], chat_sections_pending_media_after_turn=[[]],
            chat_sections_changed_from_index=1, chat_rows_cache_key="rows",
            chat_rows_cache=[{}], chat_rows_cache_tops=[0], chat_rows_cache_total_h=100,
            chat_rows_cache_base_key="base", chat_rows_cache_sections=[section],
            scroll={"chat.thread": 77},
        )
        panel._assistant_section_stream_cache = {"old": object()}
        panel._reset_chat_ui_cache(reset_scroll=False)
        self.assertNotIn("_chat_body_geometry_cache", section)
        self.assertNotIn("_chat_row_layout_cache", section)
        self.assertEqual(panel.state.scroll["chat.thread"], 77)
        self.assertFalse(panel.state.chat_section_measure_cache)
        self.assertFalse(panel.state.chat_section_estimate_cache)
        appearance_source = inspect.getsource(velox.Panels._draw_appearance_settings_content)
        self.assertIn("self.widgets.layout_cache.clear()", appearance_source)
        self.assertIn("self._reset_chat_ui_cache(reset_scroll=False)", appearance_source)

