    def test_prompt_and_skill_audit_preserves_unrelated_text_and_bounds_targeted_growth(self) -> None:
        baseline_column_sizes = {
            "Image Analysis": 9972,
            "UI and UX": 4495,
            "General Programming": 9975,
            "WebGL Programming": 4535,
            "3D Rendering Programming": 17227,
            "General Agent": 2214,
        }
        current = {
            "Image Analysis": len(velox.DEFAULT_IMAGE_ANALYSIS_SKILL_MARKDOWN),
            "UI and UX": len(velox.DEFAULT_UI_UX_SKILL_MARKDOWN),
            "General Programming": len(velox.DEFAULT_GENERAL_PROGRAMMING_SKILL_MARKDOWN),
            "WebGL Programming": len(velox.DEFAULT_WEBGL_PROGRAMMING_SKILL_MARKDOWN),
            "3D Rendering Programming": len(velox.DEFAULT_3D_RENDERING_PROGRAMMING_SKILL_MARKDOWN),
            "General Agent": len(velox.DEFAULT_GENERAL_AGENT_SKILL_MARKDOWN),
        }
        for name, before in baseline_column_sizes.items():
            self.assertLess(current[name], before, name)
        with tempfile.TemporaryDirectory() as td:
            storage = velox.Storage(velox.AppPaths(Path(td)))
            storage.ensure_first_run_files()
            chat_id = str(velox.ChatStore(storage).create_chat("Prompt audit")["chat_id"])
            prompt = velox.ContextAssembler(storage.paths).assemble_chat_context(velox.APP_SCOPE_ID, chat_id)[0]["content"]
