def _test_visual_studio_records() -> list[dict[str, Any]]:
    return [
        {
            "installationPath": r"C:\Program Files\Microsoft Visual Studio\2022\Professional",
            "installationVersion": "17.12.35527.113",
            "displayName": "Visual Studio Professional 2022",
            "catalog": {"productLineVersion": "2022", "productDisplayVersion": "17.12.4"},
        },
        {
            "installationPath": r"C:\Program Files\Microsoft Visual Studio\2026\Professional",
            "installationVersion": "18.0.10903.156",
            "displayName": "Visual Studio Professional",
            "catalog": {"productLineVersion": "18", "productDisplayVersion": "18.0.0"},
        },
    ]


def _test_vs_installation(
    *, root: str, version: str, display_name: str, product_line: str,
    generator: str, toolset: str,
) -> dict[str, Any]:
    major = velox._version_sort_tuple(version)[0]
    tool_root = root + rf"\VC\Tools\MSVC\{toolset}\bin\Hostx64\x64"
    return {
        "installationPath": root,
        "installationVersion": version,
        "visualStudioMajor": major,
        "displayName": display_name,
        "productLineVersion": product_line,
        "productDisplayVersion": version,
        "catalog": {"productLineVersion": product_line, "productDisplayVersion": version},
        "cmakeGenerator": generator,
        "vsDevCmd": root + r"\Common7\Tools\VsDevCmd.bat",
        "vcvars64": root + r"\VC\Auxiliary\Build\vcvars64.bat",
        "msbuild": root + r"\MSBuild\Current\Bin\amd64\MSBuild.exe",
        "devenv": root + r"\Common7\IDE\devenv.com",
        "defaultToolsetVersion": toolset,
        "toolsetVersion": toolset,
        "cl": tool_root + r"\cl.exe",
        "link": tool_root + r"\link.exe",
        "toolsets": [{
            "version": toolset,
            "cl": tool_root + r"\cl.exe",
            "link": tool_root + r"\link.exe",
            "isDefault": "True",
        }],
    }


def _test_cmake_installation(
    *, path: str, version: str, generators: list[str],
) -> dict[str, Any]:
    return {
        "path": path,
        "version": version,
        "versionTuple": list(velox._version_sort_tuple(version)),
        "supportedVisualStudioGenerators": list(generators),
        "supportsVisualStudioInstanceSelection": velox._version_sort_tuple(version) >= (3, 11),
        "supportsExactMsvcToolsetVersion": velox._version_sort_tuple(version) >= (3, 19, 7),
        "probeOk": True,
        "probeError": "",
    }


def _test_windows_toolchain_environment() -> dict[str, Any]:
    vs2026 = _test_vs_installation(
        root=r"C:\Program Files\Microsoft Visual Studio\2026\Professional",
        version="18.0.10903.156",
        display_name="Visual Studio Professional 2026",
        product_line="18",
        generator="Visual Studio 18 2026",
        toolset="14.50.35717",
    )
    vs2022 = _test_vs_installation(
        root=r"C:\Program Files\Microsoft Visual Studio\2022\Professional",
        version="17.12.35527.113",
        display_name="Visual Studio Professional 2022",
        product_line="2022",
        generator="Visual Studio 17 2022",
        toolset="14.42.34433",
    )
    cmake42 = _test_cmake_installation(
        path=r"C:\Program Files\CMake\bin\cmake.exe",
        version="4.2.1",
        generators=["Visual Studio 18 2026", "Visual Studio 17 2022"],
    )
    cmake330 = _test_cmake_installation(
        path=vs2022["installationPath"] + r"\Common7\IDE\CommonExtensions\Microsoft\CMake\CMake\bin\cmake.exe",
        version="3.30.5",
        generators=["Visual Studio 17 2022"],
    )
    inherited = {
        "VSINSTALLDIR": vs2022["installationPath"] + "\\",
        "VCToolsVersion": "14.38.33130",
        "VCToolsInstallDir": vs2022["installationPath"] + "\\VC\\Tools\\MSVC\\14.38.33130\\",
        "VisualStudioVersion": "17.0",
        "CMAKE_GENERATOR": "Visual Studio 17 2022",
    }
    preferred = velox.select_preferred_windows_toolchain(
        [vs2026, vs2022], [cmake42, cmake330], inherited,
    )
    return {
        "hostOs": "Windows",
        "vswhere": r"C:\Program Files (x86)\Microsoft Visual Studio\Installer\vswhere.exe",
        "installations": [vs2026, vs2022],
        "cmakeInstallations": [cmake42, cmake330],
        "cmakeExecutables": [cmake42["path"], cmake330["path"]],
        "cmake": preferred["cmake"],
        "preferred": preferred,
        "inheritedToolchainEnvironment": inherited,
        "preferenceIssue": "",
        **{
            "installationPath": preferred["visualStudioInstallation"],
            "installationVersion": preferred["visualStudioInstallationVersion"],
            "displayName": preferred["visualStudioDisplayName"],
            "visualStudioMajor": preferred["visualStudioMajor"],
            "toolsetVersion": preferred["msvcToolsetVersion"],
            "cl": preferred["cl"],
            "link": preferred["link"],
            "msbuild": preferred["msbuild"],
            "devenv": preferred["devenv"],
            "vsDevCmd": preferred["vsDevCmd"],
            "vcvars64": preferred["vcvars64"],
            "cmakeGenerator": preferred["cmakeGenerator"],
        },
    }


class ProgrammingHarnessReliabilityTests(_DataRootsIsolatedTestMixin, unittest.TestCase):
    """Native compiler discovery and programming-tool contracts."""

    def test_vs2026_major_sorts_above_vs2022_marketing_year(self) -> None:
        records = _test_visual_studio_records()
        ordered = sorted(records, key=velox._visual_studio_sort_key, reverse=True)
        self.assertEqual(ordered[0]["installationVersion"].split(".", 1)[0], "18")
        self.assertEqual(ordered[0]["catalog"]["productLineVersion"], "18")
        self.assertEqual(ordered[1]["catalog"]["productLineVersion"], "2022")
        self.assertEqual(velox.select_newest_visual_studio_installation(records), ordered[0])
        self.assertEqual(
            velox._visual_studio_cmake_generator({
                "installationVersion": "18.0.1",
                "catalog": {"productLineVersion": "2022"},
            }),
            "Visual Studio 18 2026",
        )
        self.assertEqual(
            velox._visual_studio_cmake_generator({
                "installationVersion": "17.12.1",
                "catalog": {"productLineVersion": "2026"},
            }),
            "Visual Studio 17 2022",
        )

    def test_cmake_discovery_order_does_not_define_preference(self) -> None:
        candidates = [r"C:\old\cmake.exe", r"C:\new\cmake.exe"]
        metadata = {
            candidates[0]: _test_cmake_installation(
                path=candidates[0], version="3.29.1", generators=["Visual Studio 17 2022"],
            ),
            candidates[1]: _test_cmake_installation(
                path=candidates[1], version="4.2.1", generators=["Visual Studio 18 2026"],
            ),
        }
        module = velox
        with mock.patch.object(module, "_cmake_candidate_paths", return_value=candidates), mock.patch.object(
            module, "_probe_cmake_executable", side_effect=lambda value: copy.deepcopy(metadata[str(value)]),
        ):
            rows = velox.detect_cmake_installations("win32", {})
        self.assertEqual([row["path"] for row in rows], [candidates[1], candidates[0]])
        self.assertEqual(velox.detect_cmake_executables.__doc__.splitlines()[0], "Return exact CMake paths ordered by probed version/capability, not discovery order.")

    def test_incompatible_newest_pair_falls_back_to_supported_visual_studio(self) -> None:
        environment = _test_windows_toolchain_environment()
        vs2026, vs2022 = environment["installations"]
        cmake = _test_cmake_installation(
            path=r"C:\CMake\4.1\bin\cmake.exe", version="4.1.3",
            generators=["Visual Studio 17 2022"],
        )
        preferred = velox.select_preferred_windows_toolchain([vs2026, vs2022], [cmake], {})
        self.assertEqual(preferred["visualStudioInstallation"], vs2022["installationPath"])
        self.assertEqual(preferred["msvcToolsetVersion"], vs2022["toolsetVersion"])
        self.assertEqual(preferred["cl"], vs2022["cl"])
        self.assertEqual(preferred["cmake"], cmake["path"])
        self.assertEqual(preferred["cmakeGenerator"], "Visual Studio 17 2022")

    def test_preferred_snapshot_and_canonical_command_describe_one_tuple(self) -> None:
        preferred = _test_windows_toolchain_environment()["preferred"]
        command = preferred["cmakeConfigureCommand"]
        self.assertEqual(preferred["visualStudioMajor"], 18)
        self.assertEqual(preferred["cmakeGeneratorInstance"], preferred["visualStudioInstallation"])
        self.assertEqual(preferred["cmakeGeneratorToolset"], f"host=x64,version={preferred['msvcToolsetVersion']}")
        self.assertIn(preferred["cmake"], command)
        self.assertIn(preferred["cmakeGenerator"], command)
        self.assertIn(preferred["visualStudioInstallation"], command)
        self.assertIn(preferred["msvcToolsetVersion"], command)
        self.assertIn("-A x64", command)
        self.assertIn("CMAKE_GENERATOR_INSTANCE:STRING=", command)
        self.assertEqual(Path(preferred["cl"].replace("\\", "/")).name.lower(), "cl.exe")
        self.assertIn(preferred["msvcToolsetVersion"], preferred["cl"])
        self.assertIn(preferred["msvcToolsetVersion"], preferred["link"])
        self.assertTrue(preferred["msbuild"].lower().endswith("msbuild.exe"))

    def test_conflicting_inherited_environment_is_cleared_before_exact_selection(self) -> None:
        preferred = _test_windows_toolchain_environment()["preferred"]
        self.assertEqual(preferred["inheritedToolchainEnvironment"]["VCToolsVersion"], "14.38.33130")
        command = preferred["cmakeConfigureCommand"]
        for name in (
            "VCToolsVersion", "VCToolsInstallDir", "VSINSTALLDIR", "VCINSTALLDIR",
            "VisualStudioVersion", "CMAKE_GENERATOR", "CMAKE_GENERATOR_INSTANCE",
            "CMAKE_GENERATOR_TOOLSET",
        ):
            self.assertIn(f"--unset={name}", command)
        self.assertIn("version=14.50.35717", command)
        self.assertNotIn("version=14.38.33130", command)
        self.assertTrue(preferred["cl"].endswith(r"14.50.35717\bin\Hostx64\x64\cl.exe"))

    def test_cmake_probe_parses_version_generators_and_is_process_cached(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            executable = Path(td) / "cmake.exe"
            executable.write_bytes(b"fake")
            calls: list[tuple[str, str]] = []

            def fake_run(argv: list[str], **_kwargs: Any) -> Any:
                calls.append((str(argv[0]), str(argv[1])))
                if argv[1] == "--version":
                    return SimpleNamespace(returncode=0, stdout="cmake version 4.2.1\n")
                return SimpleNamespace(
                    returncode=0,
                    stdout=(
                        "Generators\n"
                        "  Visual Studio 18 2026 = Generates Visual Studio 2026 project files.\n"
                        "* Visual Studio 17 2022 = Generates Visual Studio 2022 project files.\n"
                    ),
                )

            with velox._CMAKE_PROBE_CACHE_LOCK:
                velox._CMAKE_PROBE_CACHE.clear()
            with mock.patch.object(subprocess, "run", side_effect=fake_run):
                first = velox._probe_cmake_executable(executable)
                second = velox._probe_cmake_executable(executable)
            self.assertEqual(first, second)
            self.assertEqual(len(calls), 2)
            self.assertEqual(first["version"], "4.2.1")
            self.assertEqual(
                first["supportedVisualStudioGenerators"],
                ["Visual Studio 18 2026", "Visual Studio 17 2022"],
            )
            self.assertTrue(first["supportsExactMsvcToolsetVersion"])

