class ChecklistStoreTests(unittest.TestCase):
    def setUp(self) -> None:
        self.temp = tempfile.TemporaryDirectory()
        root = Path(self.temp.name)
        self.storage = velox.Storage(velox.AppPaths(root))
        self.storage.ensure_first_run_files()
        chat_store = velox.ChatStore(self.storage)
        creator = getattr(chat_store, "create_chat", None)
        if not callable(creator):
            self.fail("ChatStore.create_chat is required by the checklist fixture")
        try:
            created = creator("Checklist test")
        except TypeError:
            created = creator(velox.APP_SCOPE_ID, "Checklist test")
        if isinstance(created, str) and created:
            self.chat_id = created
        elif isinstance(created, dict) and created.get("chat_id"):
            self.chat_id = str(created["chat_id"])
        else:
            self.fail("ChatStore.create_chat did not return a chat identity")
        self.owner = {"owner_kind": "chat", "chat_id": self.chat_id, "agent_id": "", "task_run_id": 0}
        self.store = velox.ChecklistStore(self.storage)

    def tearDown(self) -> None:
        self.temp.cleanup()

    def _create(self, name: str = "Root", items: Optional[list[str]] = None, **kwargs: Any) -> dict[str, Any]:
        return self.store.create(self.owner, name=name, items=items or ["First", "Second"], **kwargs)


    def test_agent_collection_is_owner_and_run_scoped(self) -> None:
        agent = velox.AgentStore(self.storage).create_agent(self.chat_id, "Agent scoped Checklist")
        owner = velox._agent_checklist_owner(agent)
        result = velox.ChecklistStore(self.storage).create(owner, name="Agent work", items=["Inspect", "Report"])
        self.assertEqual(result["name"], "Agent work")
        self.assertIn(f"checklists_{agent['task_run_id']}.json", str(velox.ChecklistStore(self.storage)._collection_path(owner)))


    def test_state_comments_reload_and_implementer_cannot_verify(self) -> None:
        checklist = self._create(items=["Implement renderer"])
        cid = checklist["checklist_id"]
        self.store.update_items(self.owner, cid, [{"item_id":"C1","state":"in_progress","comment":"Device works; connect readback next."}])
        self.store.update_items(self.owner, cid, [{"item_id":"C1","state":"done","comment":"Production render path captured the expected frame."}])
        reloaded = velox.ChecklistStore(self.storage).status(self.owner, cid, include_history=True)
        self.assertEqual(reloaded["items"][0]["state"], velox.CHECKLIST_ITEM_DONE)
        self.assertIn("expected frame", reloaded["items"][0]["latest_comment"])
        self.assertGreaterEqual(len(reloaded["items"][0]["history"]), 3)
        with self.assertRaises(ValueError):
            self.store.update_items(self.owner, cid, [{"item_id":"C1","state":"verified","comment":"No"}])

    def test_done_can_reopen_but_verified_is_implementer_protected(self) -> None:
        checklist = self._create(items=["Visual HUD"])
        cid = checklist["checklist_id"]
        self.store.update_items(self.owner, cid, [{"item_id":"C1","state":"done","comment":"HUD capture appeared successful."}])
        self.store.update_items(self.owner, cid, [{"item_id":"C1","state":"in_progress","comment":"Image review found the HUD absent; inspect composition next."}])
        self.store.update_items(self.owner, cid, [{"item_id":"C1","state":"done","comment":"Focused capture now visibly shows the HUD."}])
        self.store.prepare_verification(self.owner, cid)
        result = self.store.apply_review(self.owner, cid, [{"item_id":"C1","verdict":"pass","comment":"Inspected final pixels; HUD is visible."}])
        self.assertEqual(result["items"][0]["state"], velox.CHECKLIST_ITEM_VERIFIED)
        with self.assertRaises(ValueError):
            self.store.update_items(self.owner, cid, [{"item_id":"C1","state":"in_progress","comment":"Try to overwrite review."}])

    def test_reviewer_fail_reopens_done_and_verified(self) -> None:
        checklist = self._create(items=["A", "B"])
        cid = checklist["checklist_id"]
        self.store.update_items(self.owner, cid, [
            {"item_id":"C1","state":"done","comment":"A observed."},
            {"item_id":"C2","state":"done","comment":"B observed."},
        ])
        self.store.prepare_verification(self.owner, cid)
        mixed = self.store.apply_review(self.owner, cid, [
            {"item_id":"C1","verdict":"pass","comment":"A independently passed."},
            {"item_id":"C2","verdict":"fail","comment":"B output is still the default path; execute the named artifact."},
        ])
        self.assertEqual([item["state"] for item in mixed["items"]], [velox.CHECKLIST_ITEM_VERIFIED, velox.CHECKLIST_ITEM_IN_PROGRESS])
        # Full later review may reopen a formerly verified item.
        self.store.update_items(self.owner, cid, [{"item_id":"C2","state":"done","comment":"B named artifact fixed and inspected."}])
        self.store.prepare_verification(self.owner, cid)
        later = self.store.apply_review(self.owner, cid, [
            {"item_id":"C1","verdict":"fail","comment":"Regression: A now crashes; reproduce and fix startup."},
            {"item_id":"C2","verdict":"pass","comment":"B named artifact independently passed."},
        ])
        self.assertEqual(later["items"][0]["state"], velox.CHECKLIST_ITEM_IN_PROGRESS)
        self.assertEqual(later["items"][1]["state"], velox.CHECKLIST_ITEM_VERIFIED)



    def test_all_done_prompts_verify_not_completion(self) -> None:
        checklist = self._create(items=["One"])
        cid = checklist["checklist_id"]
        self.store.update_items(self.owner, cid, [{"item_id":"C1","state":"done","comment":"Observed one."}])
        prompt = self.store.continuation_prompt(self.owner)
        self.assertIn("verify_checklist", prompt)
        self.assertEqual(self.store.status(self.owner, cid)["lifecycle"], velox.CHECKLIST_LIFECYCLE_OPEN)


    def test_reviewer_application_is_atomic(self) -> None:
        checklist = self._create(items=["A", "B"])
        cid = checklist["checklist_id"]
        self.store.update_items(self.owner, cid, [
            {"item_id":"C1","state":"done","comment":"A done."},
            {"item_id":"C2","state":"done","comment":"B done."},
        ])
        self.store.prepare_verification(self.owner, cid)
        before = self.store.status(self.owner, cid)
        with self.assertRaises(ValueError):
            self.store.apply_review(self.owner, cid, [{"item_id":"C1","verdict":"pass","comment":"A pass."}])
        after = self.store.status(self.owner, cid)
        self.assertEqual([item["state"] for item in before["items"]], [item["state"] for item in after["items"]])

    def test_history_jsonl_contains_actor_state_comment_cycle(self) -> None:
        checklist = self._create(items=["A"])
        cid = checklist["checklist_id"]
        self.store.update_items(self.owner, cid, [{"item_id":"C1","state":"done","comment":"A done with production observation."}])
        self.store.prepare_verification(self.owner, cid)
        self.store.apply_review(self.owner, cid, [{"item_id":"C1","verdict":"pass","comment":"Reviewer observed A."}])
        events = [json.loads(line) for line in self.store._history_path(self.owner).read_text(encoding="utf-8").splitlines() if line.strip()]
        self.assertTrue(any(event["actor"] == "implementer" and event["new_state"] == velox.CHECKLIST_ITEM_DONE for event in events))
        self.assertTrue(any(event["actor"] == "reviewer" and event["new_state"] == velox.CHECKLIST_ITEM_VERIFIED for event in events))
        self.assertTrue(all("timestamp" in event and "comment" in event and "review_cycle" in event for event in events))



    def test_native_checklist_create_accepts_advertised_json_schema(self) -> None:
        registry = velox.ToolRegistry(self.storage)
        raw_call = {
            "id": "call-checklist-create",
            "type": "function",
            "function": {
                "name": "checklist_create",
                "arguments": json.dumps({"name": "test", "items": ["a"]}),
            },
        }
        converted = registry.convert_openai_tool_call(raw_call, allowed_names={"checklist_create"})
        self.assertEqual(converted["name"], "checklist_create")
        self.assertEqual(converted["arguments"], {"name": "test", "items": ["a"]})
        executed = asyncio.run(registry.execute_tool_call(velox.APP_SCOPE_ID, converted, chat_id=self.chat_id))
        self.assertTrue(executed["ok"])
        self.assertEqual(executed["result"]["action"], "created")
        self.assertEqual(executed["result"]["name"], "test")
        self.assertEqual(executed["result"]["items"][0]["text"], "a")
        definition = registry.tools["checklist_create"]
        self.assertEqual(
            tuple(spec.name for spec in definition.positional_arguments),
            ("name", "items"),
        )

