    def test_generic_tools_registered_and_legacy_hidden_from_model_schema(self) -> None:
        registry = velox.ToolRegistry(self.storage)
        for name in velox.CHECKLIST_TOOL_NAMES:
            self.assertIn(name, registry.tools)
        # Exercise every available provider-schema builder and ensure the old names
        # are not model-facing while the generic names are.
        found_generic = False
        for name in ("build_openai_chat_completion_tools", "build_openai_tools", "build_responses_tools"):
            builder = getattr(registry, name, None)
            if not callable(builder):
                continue
            try:
                schema = builder(velox.APP_SCOPE_ID, self.chat_id)
            except TypeError:
                try:
                    schema = builder(velox.APP_SCOPE_ID, self.chat_id, tool_features=velox.normalize_tool_feature_flags(None))
                except Exception:
                    continue
            except Exception:
                continue
            raw = json.dumps(schema)
            found_generic = found_generic or "checklist_create" in raw
            self.assertNotIn("expert_mode_enter", raw)
            self.assertNotIn("expert_mode_requirement_update", raw)
        self.assertTrue(found_generic)

