class NativeToolContractTests(unittest.TestCase):
    """Regression coverage for model-facing JSON schema/native signature parity."""

    class _Paths:
        def __init__(self, root: Path):
            self.root = root
        def agent_dir(self, agent_id: str) -> Path:
            return self.root / "agents" / f"agent_{agent_id}"

    def _registry(self, root: Path) -> ToolRegistry:
        paths = velox.AppPaths(root)
        storage = velox.Storage(paths)
        storage.ensure_first_run_files()
        return velox.ToolRegistry(storage)

    def test_tool_definition_rejects_schema_signature_name_mismatch(self) -> None:
        with self.assertRaisesRegex(TypeError, "JSON schema and native signature disagree"):
            velox.ToolDefinition(
                "bad_schema_contract",
                "bad",
                {"type":"object", "properties":{"name":{"type":"string"}}, "required":["name"]},
                lambda _ctx, _args: None,
                (),
            )
        with self.assertRaisesRegex(TypeError, "schema type"):
            velox.ToolDefinition(
                "bad_type_contract",
                "bad",
                {"type":"object", "properties":{"enabled":{"type":"string"}}, "required":["enabled"]},
                lambda _ctx, _args: None,
                (velox.ToolArgumentSpec("enabled", "boolean"),),
            )

    def test_every_registered_tool_schema_matches_native_signature(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            registry = self._registry(Path(td))
            for name, definition in registry.tools.items():
                properties = (definition.parameters or {}).get("properties") or {}
                signature_names = [argument.name for argument in definition.positional_arguments]
                self.assertEqual(set(signature_names), set(properties), name)
                required = set((definition.parameters or {}).get("required") or [])
                self.assertTrue(required.issubset(properties), name)

    def test_checklist_tools_use_canonical_execution_scope_and_legacy_tools_are_hidden(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            registry = self._registry(Path(td))
            feature_overrides = {
                "file_tools_enabled": False,
                "system_tools_enabled": False,
                "web_tools_enabled": False,
                "agent_tools_enabled": False,
                "chat_history_enabled": False,
            }
            enabled = {
                definition.name
                for definition in registry._enabled_tool_definitions(
                    velox.APP_SCOPE_ID, None, feature_overrides=feature_overrides,
                )
            }
            self.assertTrue(set(velox.CHECKLIST_TOOL_NAMES).issubset(enabled))
            self.assertFalse(set(velox._INTERNAL_EXPERT_TOOL_NAMES).intersection(enabled))
            schemas = registry.build_openai_chat_completion_tools(
                velox.APP_SCOPE_ID, None, feature_overrides=feature_overrides,
            )
            schema_names = {row["function"]["name"] for row in schemas}
            self.assertTrue(set(velox.CHECKLIST_TOOL_NAMES).issubset(schema_names))
            self.assertFalse(set(velox._INTERNAL_EXPERT_TOOL_NAMES).intersection(schema_names))
            excluded = registry.build_openai_chat_completion_tools(
                velox.APP_SCOPE_ID, None,
                excluded_names=set(velox.CHECKLIST_TOOL_NAMES),
                feature_overrides=feature_overrides,
            )
            excluded_names = {row["function"]["name"] for row in excluded}
            self.assertFalse(set(velox.CHECKLIST_TOOL_NAMES).intersection(excluded_names))


