    def test_append_turn_is_idempotent_and_rejects_conflicting_identity(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            storage = velox.Storage(velox.AppPaths(Path(td)))
            storage.ensure_first_run_files()
            chats = velox.ChatStore(storage)
            chat_id = str(chats.create_chat("Turn identity")["chat_id"])
            turn = velox.make_turn(chat_id, "user", "CHECKLISTS - CONTINUE")
            chats.append_turn(velox.APP_SCOPE_ID, chat_id, turn)
            chats.append_turn(velox.APP_SCOPE_ID, chat_id, copy.deepcopy(turn))
            loaded = chats.load_turns(velox.APP_SCOPE_ID, chat_id)
            self.assertEqual(len(loaded), 1)
            conflict = copy.deepcopy(turn)
            conflict["text"] = "different payload with same identity"
            with self.assertRaisesRegex(ValueError, "Duplicate chat turn_id"):
                chats.append_turn(velox.APP_SCOPE_ID, chat_id, conflict)
            self.assertEqual(len(chats.load_turns(velox.APP_SCOPE_ID, chat_id)), 1)

    def test_disk_duplicate_identity_collapses_to_newest_record_for_ui(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            storage = velox.Storage(velox.AppPaths(Path(td)))
            storage.ensure_first_run_files()
            chats = velox.ChatStore(storage)
            chat_id = str(chats.create_chat("Duplicate recovery")["chat_id"])
            first = velox.make_turn(chat_id, "user", "CHECKLISTS - CONTINUE")
            second = copy.deepcopy(first)
            second["text"] = "CHECKLISTS - CONTINUE newest"
            second["updated_at"] = velox.now_iso()
            path = storage.paths.chat_turns_jsonl(chat_id)
            with velox.DATA_ROOTS.lock_for_path(path):
                velox.append_jsonl(path, first)
                velox.append_jsonl(path, second)
            with chats._turn_cache_lock:
                chats._turn_cache.pop(chat_id, None)
            loaded = chats.load_turns(velox.APP_SCOPE_ID, chat_id)
            self.assertEqual(len(loaded), 1)
            self.assertEqual(loaded[0]["text"], second["text"])

