class _ReviewerTestLLM:
    def __init__(self, storage: Any) -> None:
        self.storage = storage
        self.requests: list[Any] = []
        self.mode = "pass"
        self.entered: asyncio.Event | None = None
        self.release: asyncio.Event | None = None

    def resolve_endpoint(self, profile_id: str) -> dict[str, Any]:
        return copy.deepcopy(velox.endpoint_profile_ref(self.storage.load_config(), profile_id))

    async def chat_completions_once_full(self, request: LLMRequest) -> dict[str, Any]:
        self.requests.append(copy.deepcopy(request))
        if self.mode == "gate":
            if self.entered is not None:
                self.entered.set()
            if self.release is not None:
                await self.release.wait()
        user_text = "\n".join(
            str(message.get("content") or "")
            for message in request.messages
            if isinstance(message, dict) and str(message.get("role") or "") == "user"
        )
        ids = re.findall(r"(?m)^(C[1-9][0-9]*(?:\.[1-9][0-9]*)?) \[", user_text)
        if not ids:
            ids = ["C1"]
        if self.mode == "malformed":
            text = 'No structural verdict was produced.\n$$AGENT_PROGRESS: {"message":"Independent Checklist Review complete","percent":100}'
        else:
            rows = []
            for index, item_id in enumerate(ids):
                failed = self.mode == "fail" and index == 0
                rows.append({
                    "requirement_id": item_id,
                    "verdict": "fail" if failed else "pass",
                    "summary": "Observed behavior is missing." if failed else "Reviewer independently reproduced the requested behavior.",
                    "next_step": "Repair the actual behavior and rerun the focused acceptance path." if failed else "",
                })
            text = json.dumps({"verdicts": rows}) + '\n$$AGENT_PROGRESS: {"message":"Independent Checklist Review complete","percent":100}'
        return {
            "text": text, "usage": {}, "model": "review-test",
            "endpoint": request.endpoint_profile_id, "raw": {}, "finish_reason": "stop",
        }


class ReviewerAgentLoopTests(unittest.IsolatedAsyncioTestCase):
    async def asyncSetUp(self) -> None:
        self.temp = tempfile.TemporaryDirectory()
        self.paths = velox.AppPaths(Path(self.temp.name))
        self.storage = velox.Storage(self.paths)
        self.storage.ensure_first_run_files()
        self.chats = velox.ChatStore(self.storage)
        self.chat_id = str(self.chats.create_chat("Reviewer loop")["chat_id"])
        self.agents = velox.AgentStore(self.storage)
        self.registry = velox.ToolRegistry(self.storage)
        self.monitor = velox.LLMTaskMonitor(self.storage)
        self.registry.bind_task_monitor(self.monitor)
        self.llm = _ReviewerTestLLM(self.storage)
        self.runtime = velox.AgentRuntime(
            self.storage, self.agents, self.chats, velox.ContextAssembler(self.paths),
            self.llm, self.registry, monitor=self.monitor,
        )
        self.registry.bind_agent_runtime(self.runtime)
        self.owner = {"owner_kind":"chat", "chat_id":self.chat_id, "agent_id":"", "task_run_id":0}
        self.checklists = velox.ChecklistStore(self.storage)

    async def asyncTearDown(self) -> None:
        await self.runtime.shutdown()
        self.temp.cleanup()

    def _done_checklist(self, count: int = 1) -> str:
        existing = self.checklists.load_collection(self.owner, create=False)["checklists"]
        name = "Acceptance" if not existing else f"Acceptance {len(existing) + 1}"
        created = self.checklists.create(
            self.owner, name=name, items=[f"Requirement {i}" for i in range(1, count + 1)],
        )
        checklist_id = str(created["checklist_id"])
        self.checklists.update_items(self.owner, checklist_id, [
            {"item_id": f"C{i}", "state":"done", "comment":f"Implemented and exercised requirement {i}."}
            for i in range(1, count + 1)
        ])
        return checklist_id

    async def _verify(self, checklist_id: str, *, monitor_task_id: str = "") -> dict[str, Any]:
        call = {"name":"verify_checklist", "arguments":{"checklist_id":checklist_id}}
        result = await self.registry.execute_tool_call(
            velox.APP_SCOPE_ID, call, chat_id=self.chat_id,
            endpoint_profile_id=self.chats.get_chat_endpoint_profile_id(self.chat_id),
            monitor_task_id=monitor_task_id, task_kind="chat",
        )
        self.assertTrue(result["ok"], result)
        return result["result"]

    async def test_verify_spawns_real_reviewer_agent_and_returns_terminal_verdict(self) -> None:
        checklist_id = self._done_checklist(2)
        result = await self._verify(checklist_id)
        self.assertEqual(result["action"], "review_completed")
        self.assertEqual(result["review_result"], "passed")
        self.assertEqual(result["review_cycle"], 1)
        self.assertEqual(result["counts"][velox.CHECKLIST_ITEM_VERIFIED], 2)
        self.assertEqual(result["lifecycle"], velox.CHECKLIST_LIFECYCLE_COMPLETED)
        reviewers = [row for row in self.agents.list_agents(self.chat_id) if velox._is_reviewer_agent(row)]
        self.assertEqual(len(reviewers), 1)
        self.assertEqual(reviewers[0]["status"], "succeeded")
        self.assertEqual(result["review_agent_id"], reviewers[0]["agent_id"])

    async def test_reviewer_has_no_checklist_or_agent_management_tools(self) -> None:
        checklist_id = self._done_checklist()
        result = await self._verify(checklist_id)
        self.assertEqual(len(self.llm.requests), 1)
        names = {row["function"]["name"] for row in self.llm.requests[0].native_tools or []}
        self.assertIn("fs_read", names)
        self.assertIn("shell_exec", names)
        self.assertFalse(any(name.startswith("checklist_") for name in names))
        self.assertNotIn("verify_checklist", names)
        self.assertFalse(any(name.startswith("agents_") for name in names))
        blocked = await self.registry.execute_tool_call(
            velox.APP_SCOPE_ID,
            {"name":"checklist_status", "arguments":{"checklist_id":checklist_id, "include_history":False}},
            chat_id=self.chat_id, agent_id=result["review_agent_id"], task_kind="agent",
        )
        self.assertFalse(blocked["ok"])
        self.assertTrue(blocked["reviewer_read_only"])
        blocked_agents = await self.registry.execute_tool_call(
            velox.APP_SCOPE_ID, {"name":"agents_list", "arguments":{}},
            chat_id=self.chat_id, agent_id=result["review_agent_id"], task_kind="agent",
        )
        self.assertFalse(blocked_agents["ok"])
        self.assertTrue(blocked_agents["reviewer_read_only"])

    async def test_source_chat_is_waiting_inactive_while_reviewer_owns_endpoint_work(self) -> None:
        checklist_id = self._done_checklist()
        self.llm.mode = "gate"
        self.llm.entered = asyncio.Event()
        self.llm.release = asyncio.Event()
        task_id = self.monitor.start(velox.APP_SCOPE_ID, "source chat", task_kind="chat", metadata={"phase":"ready"})
        self.monitor.set_phase(task_id, "tool")
        self.monitor.set_activity(task_id, "tool")
        pending = asyncio.create_task(self._verify(checklist_id, monitor_task_id=task_id))
        await asyncio.wait_for(self.llm.entered.wait(), timeout=2.0)
        rec = self.monitor._records[task_id]
        self.assertEqual(rec.metadata.get("phase"), "waiting")
        self.assertEqual(rec.metadata.get("activity"), "inactive")
        reviewer_id = str(rec.metadata.get("waiting_for_reviewer_agent_id") or "")
        self.assertTrue(reviewer_id)
        self.assertTrue(self.runtime.is_running(reviewer_id))
        self.assertFalse(pending.done())
        self.llm.release.set()
        result = await asyncio.wait_for(pending, timeout=2.0)
        self.assertEqual(result["review_result"], "passed")
        self.assertEqual(self.monitor._records[task_id].metadata.get("phase"), "ready")
        self.assertEqual(self.monitor._records[task_id].metadata.get("activity"), "inactive")

    async def test_duplicate_verify_is_rejected_while_reviewer_is_running(self) -> None:
        checklist_id = self._done_checklist()
        self.llm.mode = "gate"
        self.llm.entered = asyncio.Event()
        self.llm.release = asyncio.Event()
        context = SimpleNamespace(
            chat_id=self.chat_id, agent_id="", agent_task_run_id=0,
            endpoint_profile_id=self.chats.get_chat_endpoint_profile_id(self.chat_id),
            monitor_task_id="",
        )
        first = asyncio.create_task(self.registry.tool_verify_checklist(context, {"checklist_id":checklist_id}))
        await asyncio.wait_for(self.llm.entered.wait(), timeout=2.0)
        with self.assertRaisesRegex(ValueError, "independent Reviewer"):
            await self.registry.tool_verify_checklist(context, {"checklist_id":checklist_id})
        self.llm.release.set()
        await asyncio.wait_for(first, timeout=2.0)
        self.assertEqual(len([a for a in self.agents.list_agents(self.chat_id) if velox._is_reviewer_agent(a)]), 1)

    async def test_failed_acceptance_reopens_item_and_returns_repair_feedback(self) -> None:
        checklist_id = self._done_checklist(2)
        self.llm.mode = "fail"
        result = await self._verify(checklist_id)
        self.assertEqual(result["review_result"], "failed")
        self.assertEqual(result["review_status"], velox.REVIEW_FAILED)
        self.assertEqual(result["items"][0]["state"], velox.CHECKLIST_ITEM_IN_PROGRESS)
        self.assertIn("Next step:", result["items"][0]["latest_comment"])
        self.assertEqual(result["items"][1]["state"], velox.CHECKLIST_ITEM_VERIFIED)
        continuation = self.checklists.continuation_prompt(self.owner)
        self.assertIn("Repair the actual behavior", continuation)

    async def test_malformed_reviewer_result_is_one_agent_attempt_without_auto_retry(self) -> None:
        checklist_id = self._done_checklist()
        self.llm.mode = "malformed"
        result = await self._verify(checklist_id)
        self.assertEqual(result["action"], "review_error")
        self.assertFalse(result["retry_in_same_turn"])
        current = self.checklists.status(self.owner, checklist_id)
        self.assertEqual(current["review_status"], velox.REVIEW_ERROR)
        self.assertEqual(current["items"][0]["state"], velox.CHECKLIST_ITEM_DONE)
        self.assertEqual(self.checklists.continuation_prompt(self.owner), "")
        self.assertEqual(len([a for a in self.agents.list_agents(self.chat_id) if velox._is_reviewer_agent(a)]), 1)

    async def test_cancel_source_review_cancels_reviewer_and_preserves_done_state(self) -> None:
        checklist_id = self._done_checklist()
        self.llm.mode = "gate"
        self.llm.entered = asyncio.Event()
        self.llm.release = asyncio.Event()
        context = SimpleNamespace(
            chat_id=self.chat_id, agent_id="", agent_task_run_id=0,
            endpoint_profile_id=self.chats.get_chat_endpoint_profile_id(self.chat_id),
            monitor_task_id="",
        )
        pending = asyncio.create_task(self.registry.tool_verify_checklist(context, {"checklist_id":checklist_id}))
        await asyncio.wait_for(self.llm.entered.wait(), timeout=2.0)
        pending.cancel()
        with self.assertRaises(asyncio.CancelledError):
            await pending
        current = self.checklists.status(self.owner, checklist_id)
        self.assertEqual(current["review_status"], velox.REVIEW_CANCELLED)
        self.assertEqual(current["items"][0]["state"], velox.CHECKLIST_ITEM_DONE)
