    def test_source_agent_is_inactive_and_active_clock_stops_during_review(self: ReviewerAgentLoopTests) -> None:
        async def run() -> None:
            source = self.agents.create_agent(
                self.chat_id, "Implement assigned checklist",
                endpoint_profile_id=self.chats.get_chat_endpoint_profile_id(self.chat_id),
                tool_features=self.chats.get_chat_tool_features(self.chat_id),
            )
            source_id = str(source["agent_id"])
            self.agents.update_agent(source_id, {
                "status":"running", "started_at":velox.now_iso(), "active_started_at":velox.now_iso(),
                "progress_message":"Implementing", "progress_percent":55,
            })
            owner = {
                "owner_kind":"agent", "chat_id":self.chat_id, "agent_id":source_id,
                "task_run_id":int(source.get("task_run_id") or 0),
            }
            manager = velox.ChecklistStore(self.storage)
            created = manager.create(owner, name="Worker acceptance", items=["Worker result"])
            checklist_id = str(created["checklist_id"])
            manager.update_items(owner, checklist_id, [{"item_id":"C1","state":"done","comment":"Worker exercised the result."}])
            self.llm.mode = "gate"
            self.llm.entered = asyncio.Event()
            self.llm.release = asyncio.Event()
            monitor_id = self.monitor.start(velox.APP_SCOPE_ID, "source implementer", task_kind="agent", metadata={"agent_id":source_id})
            self.monitor.set_phase(monitor_id, "tool")
            self.monitor.set_activity(monitor_id, "tool")
            context = SimpleNamespace(
                chat_id=self.chat_id, agent_id=source_id, agent_task_run_id=int(source.get("task_run_id") or 0),
                endpoint_profile_id=self.chats.get_chat_endpoint_profile_id(self.chat_id), monitor_task_id=monitor_id,
            )
            pending = asyncio.create_task(self.registry.tool_verify_checklist(context, {"checklist_id":checklist_id}))
            await asyncio.wait_for(self.llm.entered.wait(), timeout=2.0)
            during = self.agents.load_agent(source_id)
            self.assertIsNone(during.get("active_started_at"))
            self.assertIn("Inactive", str(during.get("progress_message") or ""))
            rec = self.monitor._records[monitor_id]
            self.assertEqual(rec.metadata.get("phase"), "waiting")
            self.assertEqual(rec.metadata.get("activity"), "inactive")
            self.llm.release.set()
            result = await asyncio.wait_for(pending, timeout=2.0)
            self.assertEqual(result["review_result"], "passed")
            after = self.agents.load_agent(source_id)
            self.assertTrue(after.get("active_started_at"))
            self.assertEqual(after.get("progress_message"), "Implementing")
            self.assertEqual(after.get("progress_percent"), 55)
        asyncio.run(run())


    def test_missing_agent_runtime_does_not_allocate_fake_review_cycle(self: ReviewerAgentLoopTests) -> None:
        async def run() -> None:
            isolated_registry = velox.ToolRegistry(self.storage)
