class ReviewerQualityTests(unittest.TestCase):
    """Artifact inspection and evidence requirements for acceptance review."""

    def test_reviewer_prompt_is_artifact_first_and_defect_seeking(self) -> None:
        prompt = velox.REVIEWER_SYSTEM_PROMPT
        for phrase in (
            'Start from the actual final artifact through its user-facing path',
            "expectation-independent defect sweep",
            "orientation/uprightness",
            'rotation/mirroring',
            "image_analyze_3D_scene",
            "image_analyze_ui",
            'Compare distinct states for animation/input',
            'orientation/uprightness, rotation/mirroring, malformed/missing geometry',
            'fresh post-fix evidence',
            'Require fresh post-fix evidence',
        ):
            self.assertIn(phrase, prompt)
        self.assertIn('Run/open/render it, exercise representative inputs', prompt)
        self.assertIn('Run/open/render it', prompt)
        self.assertIn('investigate discrepancies with a focused capture or measurement', prompt)
        image_skill = velox.DEFAULT_IMAGE_ANALYSIS_SKILL_MARKDOWN
        self.assertIn('expectation-independent defect sweep', image_skill)
        self.assertIn('Presence of an object alone establishes neither quality nor correct behavior', image_skill)
        self.assertIn('recognizable shape and uprightness', image_skill)
        self.assertIn('Presence of an object alone establishes neither quality nor correct behavior', image_skill)

