class ChecklistUiReviewCardTests(_DataRootsIsolatedTestMixin, unittest.TestCase):
    """Checklist selection, result cards and row wrapping."""

    def test_checklist_dropdown_lists_chat_checklists_oldest_to_newest(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            _paths, storage, chats = _make_test_chat_stack(Path(td))
            cid = chats.create_chat('Historical selection')['chat_id']
            owner = velox.Panels._chat_checklist_owner(cid)
            store = velox.ChecklistStore(storage)
            reports = []
            for hour, name in ((10, 'First'), (11, 'Second'), (12, 'Third')):
                with mock.patch.dict(vars(velox), _checklist_utc_now=lambda h=hour: f'2026-09-04T{h:02}:00:00Z'):
                    row = store.create(owner, name=name, items=['Acceptance'])
                    reports.append(row)
                    if name != 'Third':
                        store.cancel_open_by_user(owner)
            panel = velox.Panels.__new__(velox.Panels)
            panel.state = velox.UIState(); panel.state.active_chat_id = cid
            panel.services = SimpleNamespace(storage=storage)
            state, options, mapping, selected, error = panel._load_chat_checklist_selector_for_ui()
            expected = [velox.checklist_display_label(row['name'], row['created_at']) for row in reports]
            self.assertEqual(error, ''); self.assertEqual(options, expected)
            self.assertEqual(selected, expected[-1]); self.assertTrue(state['active'])
            panel.state.chat_selected_checklist_ids[cid] = reports[0]['checklist_id']
            state, options, mapping, selected, error = panel._load_chat_checklist_selector_for_ui()
            self.assertEqual(error, ''); self.assertEqual(selected, expected[0])
            self.assertEqual(mapping[selected], reports[0]['checklist_id'])
            self.assertEqual(state['lifecycle'], 'cancelled_by_user'); self.assertFalse(state['active'])
            self.assertEqual(store.status(owner)['checklist_id'], reports[-1]['checklist_id'])

