    def test_active_tab_seam_erases_body_top_border_and_starts_inside_round_edge(self) -> None:
        class Recorder:
            def __init__(self) -> None:
                self.rects: list[tuple[Rect, Color]] = []
            def draw_rect(self, rect: Rect, color: Color) -> None:
                self.rects.append((rect, color))
        panel = velox.Panels.__new__(velox.Panels)
        panel.widgets = SimpleNamespace(renderer=Recorder())
        body = velox.Rect(0, 40, 500, 300)
        active = velox.Rect(10, 0, 150, 40)
        panel._erase_chat_tab_body_seam(body, active)
        self.assertEqual(len(panel.widgets.renderer.rects), 1)
        seam, color = panel.widgets.renderer.rects[0]
        self.assertEqual(seam, velox.Rect(10, 40, 150, velox.CHAT_SIDEBAR_TAB_SEAM_H_PX))
        self.assertEqual(color, velox.Palette.panel)
        self.assertEqual(active.x - body.x, 10)
        sidebar = inspect.getsource(velox.Panels.draw_chat_chats_panel)
        self.assertIn("active_tab = self._draw_chat_sidebar_tabs(layout.tab_bar)", sidebar)
