class InferenceYieldAndStartupTests(_DataRootsIsolatedTestMixin, unittest.TestCase):
    """Inference-slot yielding, startup and sidebar behavior."""

    def test_waiting_for_reviewer_releases_slot_and_reviewer_runs(self) -> None:
        async def scenario(root: Path) -> None:
            storage = _make_test_storage(root)
            monitor = velox.LLMTaskMonitor(storage)
            profile = velox.default_endpoint_profile(
                "shared", "Shared endpoint", timeout_seconds=60,
                provider=velox.ENDPOINT_PROVIDER_VLLM, max_concurrent_requests=1,
            )
            scheduler = velox.EndpointInferenceScheduler(storage, lambda _pid: profile, monitor)
            source_id = monitor.start(velox.APP_SCOPE_ID, "source chat", task_kind="chat")
            reviewer_id = monitor.start(velox.APP_SCOPE_ID, "reviewer", task_kind="agent")
            source = await scheduler.acquire(velox.LLMRequest(
                velox.APP_SCOPE_ID, "shared", [], monitor_task_id=source_id,
                task_kind="chat", task_title="source chat",
            ))
            monitor.set_phase(source_id, "tool")
            await source.release()
            self.assertEqual(scheduler.snapshot()["shared"]["active_task_ids"], [])

            monitor.update_metadata(source_id, {"waiting_for_reviewer_agent_id": reviewer_id})
            monitor.set_phase(source_id, "waiting")
            reviewer_waiter = asyncio.create_task(scheduler.acquire(velox.LLMRequest(
                velox.APP_SCOPE_ID, "shared", [], monitor_task_id=reviewer_id,
                task_kind="agent", task_title="Checklist Reviewer",
            )))
            for _ in range(100):
                if reviewer_waiter.done():
                    break
                await asyncio.sleep(0.005)
            reviewer = await asyncio.wait_for(reviewer_waiter, timeout=1.0)
            snapshot = scheduler.snapshot()["shared"]
            self.assertEqual(snapshot["active_task_ids"], [reviewer_id])
            self.assertNotIn(source_id, snapshot["active_task_ids"])
            self.assertEqual(monitor.record_metadata(source_id).get("phase"), "waiting")
            self.assertEqual(monitor.record_metadata(source_id).get("queue_priority"), 0)

            monitor.complete(reviewer_id)
            await reviewer.release()
            monitor.update_metadata(source_id, {"waiting_for_reviewer_agent_id": ""})
            monitor.set_phase(source_id, "ready")
            resumed = await asyncio.wait_for(scheduler.acquire(velox.LLMRequest(
                velox.APP_SCOPE_ID, "shared", [], monitor_task_id=source_id,
                task_kind="chat", task_title="source chat",
            )), timeout=1.0)
            self.assertEqual(scheduler.snapshot()["shared"]["active_task_ids"], [source_id])
            monitor.complete(source_id)
            await resumed.release()
            await scheduler.close()

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_time_sleep_yields_slot_then_same_task_can_reacquire(self) -> None:
        async def scenario(root: Path) -> None:
            storage = _make_test_storage(root)
            monitor = velox.LLMTaskMonitor(storage)
            profile = velox.default_endpoint_profile(
                "shared", "Shared endpoint", timeout_seconds=60,
                provider=velox.ENDPOINT_PROVIDER_VLLM, max_concurrent_requests=1,
            )
            scheduler = velox.EndpointInferenceScheduler(storage, lambda _pid: profile, monitor)
            tools = velox.ToolRegistry(storage)
            tools.bind_task_monitor(monitor)
            source_id = monitor.start(velox.APP_SCOPE_ID, "sleeping chat", task_kind="chat")
            source = await scheduler.acquire(velox.LLMRequest(
                velox.APP_SCOPE_ID, "shared", [], monitor_task_id=source_id,
                task_kind="chat", task_title="sleeping chat",
            ))
            monitor.set_phase(source_id, "tool")
            await source.release()
            self.assertEqual(scheduler.snapshot()["shared"]["active_task_ids"], [])

            sleeper = asyncio.create_task(tools.tool_time_sleep(
                velox.ToolContext(velox.APP_SCOPE_ID, monitor_task_id=source_id, task_kind="chat"),
                {"minutes": 0.004, "message": "wait for dependency"},
            ))
            for _ in range(100):
                if str(monitor.record_metadata(source_id).get("phase") or "") == "sleeping":
                    break
                await asyncio.sleep(0.002)
            self.assertEqual(monitor.record_metadata(source_id).get("phase"), "sleeping")
            for _ in range(100):
                active_ids = scheduler.snapshot().get("shared", {}).get("active_task_ids", [])
                if source_id not in active_ids:
                    break
                await asyncio.sleep(0.002)
            self.assertNotIn(source_id, scheduler.snapshot().get("shared", {}).get("active_task_ids", []))

            other_id = monitor.start(velox.APP_SCOPE_ID, "other chat", task_kind="chat")
            other = await asyncio.wait_for(scheduler.acquire(velox.LLMRequest(
                velox.APP_SCOPE_ID, "shared", [], monitor_task_id=other_id,
                task_kind="chat", task_title="other chat",
            )), timeout=1.0)
            self.assertEqual(scheduler.snapshot()["shared"]["active_task_ids"], [other_id])
            monitor.complete(other_id)
            await other.release()

            result = await asyncio.wait_for(sleeper, timeout=1.0)
            self.assertEqual(result["status"], "woke")
            self.assertEqual(monitor.record_metadata(source_id).get("phase"), "ready")
            resumed = await asyncio.wait_for(scheduler.acquire(velox.LLMRequest(
                velox.APP_SCOPE_ID, "shared", [], monitor_task_id=source_id,
                task_kind="chat", task_title="sleeping chat",
            )), timeout=1.0)
            self.assertEqual(scheduler.snapshot()["shared"]["active_task_ids"], [source_id])
            monitor.complete(source_id)
            await resumed.release()
            await scheduler.close()

        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

