class WindowsCommandAndCompactionTests(_DataRootsIsolatedTestMixin, unittest.TestCase):
    """Command syntax and evidence preservation during compaction."""

    def test_windows_cmd_rejects_unquoted_bash_semicolon_separator(self) -> None:
        bad = 'aige_app.exe --version; echo APP_EXIT=%ERRORLEVEL%'
        self.assertTrue(velox.windows_cmd_unquoted_semicolon_positions(bad))
        with self.assertRaisesRegex(ValueError, "not a command separator"):
            velox.validate_shell_command_for_platform(bad, windows=True)
        with self.assertRaisesRegex(ValueError, "returncode"):
            velox.validate_shell_command_for_platform('aige_tests.exe --report tests-out/report.json; echo TEST_EXIT=%ERRORLEVEL%', windows=True)

    def test_windows_cmd_allows_real_cmd_chaining_and_literal_quoted_semicolon(self) -> None:
        for command in ('aige_app.exe --version && echo ok', 'aige_tests.exe --report tests-out/report.json & echo done', 'findstr "a;b" README.md', 'echo a^;b'):
            velox.validate_shell_command_for_platform(command, windows=True)

    def test_shell_guidance_names_exact_separator_trap_and_returncode(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            storage = velox.Storage(velox.AppPaths(Path(td)))
            storage.ensure_first_run_files()
            registry = velox.ToolRegistry(storage)
            description = registry.tools["shell_exec"].description
            block = registry.build_openai_tool_system_block(velox.APP_SCOPE_ID, "", excluded_names=set(registry.tools) - {"shell_exec"})
        for text in (description, block, velox.ContextAssembler.TERMINAL_GUIDANCE):
            self.assertIn("cmd.exe", text)
            self.assertIn("semicolon", text.lower())
            self.assertIn("&&", text)
            self.assertIn("returncode", text)
        self.assertIn("not a command separator", description.lower())

    def test_execution_and_checklist_guidance_rejects_scope_aversion_and_unproven_corruption(self) -> None:
        guidance = velox.ContextAssembler.EXECUTION_PRIORITY_GUIDANCE
        for phrase in ('take the next evidence-producing action', 'use bounded implementation checkpoints to finish it', 'specific hypothesis', 'run a distinguishing test', 'Update the diagnosis from evidence'):
            self.assertIn(phrase, guidance)
        continuation = velox._checklist_continuation_text({"status":"active","requirements":[{"id":"C1","requirement":"Finish the engine","status":"in_progress","state":"in_progress","progress":"Build started","next_step":"Run tests"}]})
        self.assertIn("Do not reassess whether the overall task is too large", continuation)
        self.assertIn("corruption/race/stale-artifact/tool blocker", continuation)
        self.assertIn("clean rerun succeeds", continuation)

    def test_compaction_ledger_does_not_launder_hidden_reasoning_into_facts(self) -> None:
        messages = [
            {"role":"assistant","content":"I will rerun the exact command.","reasoning_content":"Maybe the workspace is corrupt and I should stop working."},
            {"role":"tool","name":"shell_exec","content":json.dumps({"ok":True,"result":{"returncode":0,"stdout":"version ok"}})},
        ]
        ledger, _meta = velox.build_compaction_operational_ledger(messages, prompt_capacity_tokens=100_000, max_tokens=4_000)
        self.assertNotIn("workspace is corrupt", ledger)
        self.assertNotIn("Reasoning outcome", ledger)
        self.assertIn("ASSISTANT CLAIM/PLAN (not independent evidence)", ledger)
        self.assertIn("Tool result shell_exec: succeeded", ledger)

    def test_compaction_prompts_explicitly_keep_speculation_non_authoritative(self) -> None:
        production = application_source()
        for phrase in ("assistant prose is only a claim or plan unless corroborated", "Omit unsupported assistant hypotheses", "workspace/source corruption", "A later clean rerun disproves that explanation"):
            self.assertIn(phrase, production)
        self.assertNotIn('"Reasoning outcome: " + reasoning', production)

    def test_rejects_unsupported_schema_without_migration(self) -> None:
        self.assertEqual(velox.APP_VERSION, "velox.v303")
        self.assertEqual(velox.DATA_FILE_VERSION, "v303")
        self.assertEqual(velox.APP_SCHEMA, "velox_app.v303")
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            paths, _storage, _chats = _make_test_chat_stack(root)
            manifest = velox.read_json(paths.app_json_path)
            manifest["data_version"] = "v271"
            manifest["schema"] = "velox_app.v271"
            velox.atomic_write_json(paths.app_json_path, manifest)
            with self.assertRaisesRegex(velox.UnsupportedDataVersionError, "v271"):
                velox.DATA_ROOTS.assert_supported(root)
        self.assertNotIn("migrate_", application_source())


class ChatDeletionRecoveryTests(_DataRootsIsolatedTestMixin, unittest.TestCase):
    """Recover UI selection after durable chat deletion."""

    @staticmethod
    def _panel(storage: Storage, chats: ChatStore, **service_overrides: Any) -> Panels:
        panel = velox.Panels.__new__(velox.Panels)
        panel.state = velox.UIState()
        panel.state.active_panel = "chat"
        services = {"storage": storage, "chats": chats}
        services.update(service_overrides)
        panel.services = SimpleNamespace(**services)
        panel._assistant_section_stream_cache = {}
        return panel

    def test_committed_chat_delete_recovers_selection_even_when_caller_raises_late(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            paths, storage, chats = _make_test_chat_stack(Path(td))
            remaining = chats.create_chat("Remaining")
            doomed = chats.create_chat("Doomed")

            def delete_then_raise(chat_id: str) -> None:
                chats.delete_chat(velox.APP_SCOPE_ID, chat_id)
                raise OSError("simulated late cleanup failure")

            panel = self._panel(storage, chats, delete_chat=delete_then_raise)
            panel.state.active_chat_id = str(doomed["chat_id"])
            panel.state.composer_text = "doomed draft"
            panel.state.queued_attachments = [{"filename": "doomed.txt"}]
            panel.state.chat_composer_drafts[str(doomed["chat_id"])] = "saved doomed draft"

            self.assertTrue(panel._delete_chat_now(str(doomed["chat_id"])))
            self.assertFalse(paths.chat_json(str(doomed["chat_id"])).exists())
            self.assertEqual(panel.state.active_chat_id, str(remaining["chat_id"]))
            self.assertNotIn(str(doomed["chat_id"]), panel.state.chat_composer_drafts)
            self.assertEqual(
                chats.get_chat_endpoint_profile_id(str(panel.state.active_chat_id)),
                velox.DEFAULT_ENDPOINT_PROFILE_ID,
            )
            self.assertFalse(any(str(row.get("level") or "") == "error" for row in panel.state.toasts))

    def test_failed_chat_delete_keeps_existing_selection_and_reports_failure(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            paths, storage, chats = _make_test_chat_stack(Path(td))
            chat = chats.create_chat("Still here")

            def fail_before_delete(_chat_id: str) -> None:
                raise OSError("simulated pre-delete failure")

            panel = self._panel(storage, chats, delete_chat=fail_before_delete)
            panel.state.active_chat_id = str(chat["chat_id"])
            self.assertFalse(panel._delete_chat_now(str(chat["chat_id"])))
            self.assertTrue(paths.chat_json(str(chat["chat_id"])).is_file())
            self.assertEqual(panel.state.active_chat_id, str(chat["chat_id"]))
            self.assertTrue(any("deletion failed" in str(row.get("message") or "").lower() for row in panel.state.toasts))

    def test_switch_active_chat_validates_destination_before_mutating_state(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            _paths, storage, chats = _make_test_chat_stack(Path(td))
            current = chats.create_chat("Current")
            panel = self._panel(storage, chats)
            panel.state.active_chat_id = str(current["chat_id"])
            panel.state.composer_endpoint_profile_id = chats.get_chat_endpoint_profile_id(str(current["chat_id"]))

            with self.assertRaises(FileNotFoundError):
                panel._switch_active_chat("missing-chat", save_current=False)
            self.assertEqual(panel.state.active_chat_id, str(current["chat_id"]))
            self.assertEqual(
                panel.state.composer_endpoint_profile_id,
                chats.get_chat_endpoint_profile_id(str(current["chat_id"])),
            )

    def test_active_selection_does_not_trust_stale_chat_list_cache_after_delete(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            paths, storage, chats = _make_test_chat_stack(Path(td))
            remaining = chats.create_chat("Remaining")
            doomed = chats.create_chat("Doomed")
            doomed_id = str(doomed["chat_id"])
            # Prime the 350-ms hot-path list cache, then simulate another process
            # removing the selected chat without invalidating this process cache.
            cached = chats.list_chats_view(velox.APP_SCOPE_ID)
            self.assertIn(doomed_id, {str(row.get("chat_id") or "") for row in cached})
            shutil.rmtree(paths.chat_dir(doomed_id))

            panel = self._panel(storage, chats)
            panel.state.active_chat_id = doomed_id
            selected = panel._ensure_active_chat_selection()
            self.assertEqual(selected, str(remaining["chat_id"]))
            self.assertEqual(panel.state.active_chat_id, str(remaining["chat_id"]))

    def test_chat_list_skips_record_deleted_between_scan_and_json_read(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            paths, _storage, chats = _make_test_chat_stack(Path(td))
            survivor = chats.create_chat("Survivor")
            doomed = chats.create_chat("Race")
            doomed_id = str(doomed["chat_id"])
            doomed_json = paths.chat_json(doomed_id)
            original_read_json = velox.read_json
            fired = {"value": False}

            def racing_read(path: Path, default: Any = None) -> Any:
                if Path(path) == doomed_json and not fired["value"]:
                    fired["value"] = True
                    shutil.rmtree(paths.chat_dir(doomed_id))
                    return default
                return original_read_json(path, default)

            chats._invalidate_list_cache()
            with mock.patch(f"{velox.__name__}.read_json", side_effect=racing_read):
                rows = chats.list_chats_view(velox.APP_SCOPE_ID, external_poll_seconds=0.0)
            ids = {str(row.get("chat_id") or "") for row in rows}
            self.assertTrue(fired["value"])
            self.assertIn(str(survivor["chat_id"]), ids)
            self.assertNotIn(doomed_id, ids)

    def test_agent_list_skips_record_deleted_between_scan_and_json_read(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            paths, storage, chats = _make_test_chat_stack(Path(td))
            chat = chats.create_chat("Owner")
            agents = velox.AgentStore(storage)
            survivor = agents.create_agent(str(chat["chat_id"]), "survive", title="Survivor")
            doomed = agents.create_agent(str(chat["chat_id"]), "race", title="Race")
            doomed_id = str(doomed["agent_id"])
            doomed_json = paths.agent_json(doomed_id)
            original_read_json = velox.read_json
            fired = {"value": False}

            def racing_read(path: Path, default: Any = None) -> Any:
                if Path(path) == doomed_json and not fired["value"]:
                    fired["value"] = True
                    shutil.rmtree(paths.agent_dir(doomed_id))
                    return default
                return original_read_json(path, default)

            agents._invalidate()
            with mock.patch(f"{velox.__name__}.read_json", side_effect=racing_read):
                rows = agents.list_agents()
            ids = {str(row.get("agent_id") or "") for row in rows}
            self.assertTrue(fired["value"])
            self.assertIn(str(survivor["agent_id"]), ids)
            self.assertNotIn(doomed_id, ids)

    def test_irreversible_store_deletes_ignore_best_effort_log_failure(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            paths, storage, chats = _make_test_chat_stack(Path(td))
            try:
                chat = chats.create_chat("Delete log")
                chat_id = str(chat["chat_id"])
                with mock.patch.object(storage, "append_app_log", side_effect=OSError("log locked")):
                    chats.delete_chat(velox.APP_SCOPE_ID, chat_id)
                self.assertFalse(paths.chat_dir(chat_id).exists())
            finally:
                _drain_storage_log_writer(storage)

        with tempfile.TemporaryDirectory() as td:
            paths, storage, chats = _make_test_chat_stack(Path(td))
            try:
                chat = chats.create_chat("Agent owner")
                agents = velox.AgentStore(storage)
                agent = agents.create_agent(str(chat["chat_id"]), "done", title="Done")
                agent = agents.update_agent(str(agent["agent_id"]), {"status": "succeeded"})
                agent_id = str(agent["agent_id"])
                with mock.patch.object(storage, "append_app_log", side_effect=OSError("log locked")):
                    agents.delete_agent(agent_id)
                self.assertFalse(paths.agent_dir(agent_id).exists())
            finally:
                _drain_storage_log_writer(storage)

    def test_committed_agent_delete_clears_all_selected_agent_references(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            paths, storage, chats = _make_test_chat_stack(Path(td))
            chat = chats.create_chat("Agent owner")
            agents = velox.AgentStore(storage)
            agent = agents.create_agent(str(chat["chat_id"]), "done", title="Done")
            agent = agents.update_agent(str(agent["agent_id"]), {"status": "succeeded"})
            agent_id = str(agent["agent_id"])

            def delete_then_raise(_agent_id: str) -> None:
                agents.delete_agent(_agent_id)
                raise OSError("late agent cleanup")

            panel = self._panel(storage, chats, delete_agent=delete_then_raise)
            panel.state.selected_agent_id = agent_id
            panel.state.chat_selected_agent_id = agent_id
            panel.state.calendar_selected_agent_id = agent_id
            self.assertTrue(panel._delete_agent_now(agent_id))
            self.assertFalse(paths.agent_json(agent_id).exists())
            self.assertIsNone(panel.state.selected_agent_id)
            self.assertIsNone(panel.state.chat_selected_agent_id)
            self.assertIsNone(panel.state.calendar_selected_agent_id)

    def test_chat_frame_revalidates_after_sidebar_and_view_handles_disappearance(self) -> None:
        frame_source = inspect.getsource(velox.VeloxApp.draw_frame)
        sidebar_index = frame_source.index("draw_chat_chats_panel")
        recheck_index = frame_source.index("_ensure_active_chat_selection()", sidebar_index)
        transcript_index = frame_source.index("_load_active_turns_cached", sidebar_index)
        self.assertLess(sidebar_index, recheck_index)
        self.assertLess(recheck_index, transcript_index)

        class RendererStub:
            def __init__(self) -> None:
                self.text: list[str] = []

            def draw_rect(self, *_args: Any, **_kwargs: Any) -> None:
                return None

            def draw_text(self, text: str, *_args: Any, **_kwargs: Any) -> None:
                self.text.append(str(text))

        renderer = RendererStub()
        panel = velox.Panels.__new__(velox.Panels)
        panel.widgets = SimpleNamespace(renderer=renderer)
        panel.state = velox.UIState()
        panel.state.active_scope_id = velox.APP_SCOPE_ID
        panel.state.active_chat_id = "deleted-chat"
        panel.services = SimpleNamespace(
            chats=SimpleNamespace(
                get_chat_endpoint_profile_id=mock.Mock(side_effect=FileNotFoundError("gone")),
            ),
        )
        panel._assistant_section_stream_cache = {}
        panel.draw_chat_view(velox.Rect(0, 0, 640, 480))
        self.assertIsNone(panel.state.active_chat_id)
        self.assertTrue(any("selected chat was deleted" in text.lower() for text in renderer.text))

    def test_rejects_unsupported_schema_without_migration(self) -> None:
        self.assertEqual(velox.APP_VERSION, "velox.v303")
        self.assertEqual(velox.DATA_FILE_VERSION, "v303")
        self.assertEqual(velox.APP_SCHEMA, "velox_app.v303")
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            paths, _storage, _chats = _make_test_chat_stack(root)
            manifest = velox.read_json(paths.app_json_path)
            manifest["data_version"] = "v272"
            manifest["schema"] = "velox_app.v272"
            velox.atomic_write_json(paths.app_json_path, manifest)
            with self.assertRaisesRegex(velox.UnsupportedDataVersionError, "v272"):
                velox.DATA_ROOTS.assert_supported(root)
        self.assertNotIn("migrate_", application_source())


class ToolRowIdentityTests(_DataRootsIsolatedTestMixin, unittest.TestCase):
    """One execution and one visible row per native tool-call identity."""

    @staticmethod
    def _call(call_id: str = "call-1", name: str = "fs_write") -> dict[str, Any]:
        provider = {
            "id": call_id,
            "type": "function",
            "function": {"name": name, "arguments": '{"path":"report.md","content":"ok"}'},
        }
        return {
            "name": name,
            "raw_call": json.dumps(provider, ensure_ascii=False),
            "provider_tool_call_id": call_id,
            "provider_tool_call": provider,
        }

    @staticmethod
    def _tool_row(name: str = "fs_write") -> dict[str, Any]:
        return {
            "schema": velox.TOOL_CALL_SCHEMA,
            "tool_call_id": "velox-tool-1",
            "provider_tool_call_id": "call-1",
            "tool_name": name,
            "status": "complete",
            "ok": True,
            "result": {"path": "report.md"},
        }

    def test_native_tool_replay_never_leaks_internal_row_placeholders_to_model(self) -> None:
        provider_call = self._call()["provider_tool_call"]
        text = (
            "<think>reason before\n[[VELOX_TOOL_ROW:0]]\nreason after</think>\n"
            "Visible answer\n[[VELOX_TOOL_ROW:0]]"
        )
        message = velox.assistant_message_for_openai_tool_calls(text, [provider_call])
        self.assertNotIn("VELOX_TOOL_ROW", str(message.get("content") or ""))
        self.assertNotIn("VELOX_TOOL_ROW", str(message.get("reasoning_content") or ""))
        self.assertIn("Visible answer", str(message.get("content") or ""))
        self.assertIn("reason before", str(message.get("reasoning_content") or ""))
        self.assertEqual(message["tool_calls"], [provider_call])

    def test_model_echo_plus_canonical_row_reproduces_as_one_marker_only(self) -> None:
        runtime = velox.ChatRuntime.__new__(velox.ChatRuntime)
        leaked = "Both fixes are committed.\n[[VELOX_TOOL_ROW:0]]"
        cleaned = velox.strip_tool_markup_from_text(leaked).strip()
        rows: list[dict[str, Any]] = []
        text, prepared = runtime._prepare_visible_tool_batch(cleaned, rows, [self._call()])
        self.assertEqual(len(prepared), 1)
        self.assertEqual(len(rows), 1)
        self.assertEqual(text.count("[[VELOX_TOOL_ROW:0]]"), 1)

        # Retrying insertion of the same structured index must remain idempotent.
        marker = runtime._format_tool_result_for_visible_chat(rows[0], 0)
        text = runtime._append_tool_marker_to_best_block(text, marker)
        self.assertEqual(text.count("[[VELOX_TOOL_ROW:0]]"), 1)

    def test_renderer_deduplicates_legacy_duplicate_markers_but_keeps_distinct_tools(self) -> None:
        panel = velox.Panels.__new__(velox.Panels)
        first = self._tool_row("fs_write")
        second = copy.deepcopy(first)
        second.update({"tool_call_id": "velox-tool-2", "provider_tool_call_id": "call-2", "tool_name": "fs_read"})
        raw = "Answer\n[[VELOX_TOOL_ROW:0]]\n[[VELOX_TOOL_ROW:0]]\n[[VELOX_TOOL_ROW:1]]\n[[VELOX_TOOL_ROW:1]]"
        blocks = panel._build_chat_body_blocks(raw, [first, second])
        tool_blocks = [block for block in blocks if block.get("type") == "tool"]
        self.assertEqual([block.get("tool_index") for block in tool_blocks], [0, 1])

    def test_ordered_sections_attach_each_tool_index_only_once(self) -> None:
        panel = velox.Panels.__new__(velox.Panels)
        panel._assistant_section_stream_cache = {}
        first = self._tool_row("fs_write")
        second = copy.deepcopy(first)
        second.update({"tool_call_id": "velox-tool-2", "provider_tool_call_id": "call-2", "tool_name": "fs_read"})
        turn = {
            "turn_id": "turn-duplicate-markers",
            "text": "Answer\n[[VELOX_TOOL_ROW:0]]\n[[VELOX_TOOL_ROW:0]]\n[[VELOX_TOOL_ROW:1]]",
            "tool_calls": [first, second],
            "streaming_tool_preview": "",
            "status": "complete",
            "stats": {},
            "attachments": [],
        }
        sections = panel._assistant_ordered_sections(turn, "", "", True)
        attached = [tool for section in sections for tool in (section.get("inline_tools") or [])]
        self.assertEqual(len(attached), 2)
        self.assertEqual([tool.get("tool_name") for tool in attached], ["fs_write", "fs_read"])

    def test_provider_duplicate_call_id_cannot_become_second_execution_identity(self) -> None:
        duplicate = {
            "name": "fs_write",
            "arguments": '{"path":"report.md","content":"ok"}',
            "id": "provider-call-1",
            "type": "function",
        }
        accumulator = {
            "0": copy.deepcopy(duplicate),
            "function_call": copy.deepcopy(duplicate),
        }
        calls = velox.provider_tool_calls_from_accumulator(accumulator)
        self.assertEqual(len(calls), 1)
        self.assertEqual(calls[0]["id"], "provider-call-1")
        self.assertEqual(calls[0]["function"]["name"], "fs_write")

        id_only_then_complete = {
            "0": {"name": "", "arguments": "", "id": "provider-call-2", "type": "function"},
            "function_call": {
                "name": "fs_read", "arguments": '{"path":"a.txt"}',
                "id": "provider-call-2", "type": "function",
            },
        }
        calls = velox.provider_tool_calls_from_accumulator(id_only_then_complete)
        self.assertEqual(len(calls), 1)
        self.assertEqual(calls[0]["id"], "provider-call-2")
        self.assertEqual(calls[0]["function"]["name"], "fs_read")

    def test_fresh_model_output_is_scrubbed_before_chat_tool_rows_are_inserted(self) -> None:
        source = inspect.getsource(velox.ChatRuntime._run_assistant_loop)
        self.assertIn("display_candidate = strip_tool_markup_from_text(raw_candidate).strip()", source)
        self.assertIn("batch_visible = display_candidate", source)
        self.assertIn("current_visible = display_candidate", source)
        self.assertIn("Internal tool-row placeholders are owned exclusively by Velox", source)

    def test_rejects_unsupported_schema_without_migration(self) -> None:
        self.assertEqual(velox.APP_VERSION, "velox.v303")
        self.assertEqual(velox.DATA_FILE_VERSION, "v303")
        self.assertEqual(velox.APP_SCHEMA, "velox_app.v303")
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            paths, _storage, _chats = _make_test_chat_stack(root)
            manifest = velox.read_json(paths.app_json_path)
            manifest["data_version"] = "v273"
            manifest["schema"] = "velox_app.v273"
            velox.atomic_write_json(paths.app_json_path, manifest)
            with self.assertRaisesRegex(velox.UnsupportedDataVersionError, "v273"):
                velox.DATA_ROOTS.assert_supported(root)
        self.assertNotIn("migrate_", application_source())


class _ReviewerProtocolLLM:
    """Deterministic model fixture for review-protocol tests."""

    def __init__(self, storage: Any, mode: str = "pass") -> None:
        self.storage = storage
        self.mode = str(mode)
        self.requests: list[LLMRequest] = []

    def resolve_endpoint(self, profile_id: str) -> dict[str, Any]:
        return copy.deepcopy(velox.endpoint_profile_ref(self.storage.load_config(), profile_id))

    @staticmethod
    def _ids(request: LLMRequest) -> list[str]:
        user_text = "\n".join(
            str(message.get("content") or "")
            for message in request.messages
            if isinstance(message, dict) and str(message.get("role") or "") == "user"
        )
        ids = re.findall(r"(?m)^(C[1-9][0-9]*(?:\.[1-9][0-9]*)?) \[", user_text)
        return ids or ["C1"]

    @staticmethod
    def _verdict_json(ids: list[str], *, fail_first: bool = False) -> str:
        rows: list[dict[str, str]] = []
        for index, item_id in enumerate(ids):
            failed = bool(fail_first and index == 0)
            rows.append({
                "requirement_id": item_id,
                "verdict": "fail" if failed else "pass",
                "summary": (
                    "Observed acceptance gap in the current artifact."
                    if failed else
                    "Reviewer independently observed the required behavior."
                ),
                "next_step": (
                    "Repair the observed artifact defect and rerun the focused acceptance path."
                    if failed else ""
                ),
            })
        return json.dumps({"verdicts": rows}, ensure_ascii=False)

    async def chat_completions_once_full(self, request: LLMRequest) -> dict[str, Any]:
        self.requests.append(copy.deepcopy(request))
        ids = self._ids(request)
        call_index = len(self.requests) - 1
        clean_terminal = '$$AGENT_PROGRESS: {"message":"Independent Checklist Review complete","percent":100}'
        dsml_terminal = clean_terminal + '</｜DSML｜parameter>'
        if self.mode == "dsml":
            text = self._verdict_json(ids) + "\n" + dsml_terminal
        elif self.mode == "mixed":
            text = (
                "Short independent review preamble.\n\n```json\n"
                + self._verdict_json(ids, fail_first=True)
                + "\n```\n\n"
                + clean_terminal
            )
        elif self.mode == "recover":
            text = self._verdict_json(ids) if call_index == 0 else clean_terminal
        elif self.mode == "exhaust":
            text = self._verdict_json(ids)
        elif self.mode == "exhaust_invalid":
            text = "The Reviewer has not produced a complete verdict."
        else:
            text = self._verdict_json(ids) + "\n" + clean_terminal
        return {
            "text": text,
            "usage": {},
            "model": "review-protocol-test",
            "endpoint": request.endpoint_profile_id,
            "raw": {},
            "finish_reason": "stop",
        }


class ReviewerReliabilitySecurityTests(unittest.IsolatedAsyncioTestCase):
    """Reviewer termination, verdict parsing and secret redaction."""

    async def asyncSetUp(self) -> None:
        self.temp = tempfile.TemporaryDirectory()
        self.paths = velox.AppPaths(Path(self.temp.name))
        self.storage = velox.Storage(self.paths)
        self.storage.ensure_first_run_files()
        self.chats = velox.ChatStore(self.storage)
        self.chat_id = str(self.chats.create_chat("Reviewer protocol")['chat_id'])
        self.agents = velox.AgentStore(self.storage)
        self.registry = velox.ToolRegistry(self.storage)
        self.monitor = velox.LLMTaskMonitor(self.storage)
        self.registry.bind_task_monitor(self.monitor)
        self.llm = _ReviewerProtocolLLM(self.storage)
        self.runtime = velox.AgentRuntime(
            self.storage, self.agents, self.chats, velox.ContextAssembler(self.paths),
            self.llm, self.registry, monitor=self.monitor,
        )
        self.registry.bind_agent_runtime(self.runtime)
        self.owner = {"owner_kind":"chat", "chat_id":self.chat_id, "agent_id":"", "task_run_id":0}
        self.checklists = velox.ChecklistStore(self.storage)

    async def asyncTearDown(self) -> None:
        await self.runtime.shutdown()
        self.temp.cleanup()

    def _done_checklist(self, count: int = 1) -> str:
        created = self.checklists.create(
            self.owner, name="Acceptance", items=[f"Requirement {i}" for i in range(1, count + 1)],
        )
        checklist_id = str(created["checklist_id"])
        self.checklists.update_items(self.owner, checklist_id, [
            {"item_id": f"C{i}", "state": "done", "comment": f"Implemented requirement {i}."}
            for i in range(1, count + 1)
        ])
        return checklist_id

    async def _verify(self, checklist_id: str) -> dict[str, Any]:
        result = await self.registry.execute_tool_call(
            velox.APP_SCOPE_ID,
            {"name":"verify_checklist", "arguments":{"checklist_id":checklist_id}},
            chat_id=self.chat_id,
            endpoint_profile_id=self.chats.get_chat_endpoint_profile_id(self.chat_id),
            task_kind="chat",
        )
        self.assertTrue(result["ok"], result)
        return result["result"]

    def test_deepseek_progress_suffix_normalizes_to_terminal_success(self) -> None:
        raw = '$$AGENT_PROGRESS: {"message":"done","percent":100}</｜DSML｜parameter>\n'
        self.assertEqual(
            velox.normalize_known_provider_output_artifacts(raw),
            '$$AGENT_PROGRESS: {"message":"done","percent":100}',
        )
        controls = velox.parse_agent_control_events(raw)
        self.assertEqual(len(controls), 1)
        self.assertTrue(controls[0]["payload_valid"])
        self.assertEqual(controls[0]["kind"], "succeeded")
        self.assertEqual(controls[0]["percent"], 100)
        self.assertTrue(controls[0]["is_last_action"])
        diagnostic = velox.agent_progress_control_diagnostic(raw, controls)
        self.assertEqual(diagnostic["status"], "terminal_success")

    async def test_complete_verdict_with_deepseek_suffix_is_accepted_and_applied(self) -> None:
        self.llm.mode = "dsml"
        checklist_id = self._done_checklist(2)
        result = await self._verify(checklist_id)
        self.assertEqual(result["action"], "review_completed")
        self.assertEqual(result["review_result"], "passed")
        self.assertEqual(result["counts"][velox.CHECKLIST_ITEM_VERIFIED], 2)
        reviewer = self.agents.load_agent(result["review_agent_id"])
        self.assertEqual(reviewer["status"], "succeeded")
        self.assertEqual(len(self.llm.requests), 1)
        transcript_text = json.dumps(self.agents.load_transcript(result["review_agent_id"]), ensure_ascii=False)
        self.assertNotIn("</｜DSML｜parameter>", transcript_text)

    async def test_mixed_acceptance_is_successful_reviewer_execution_not_review_error(self) -> None:
        self.llm.mode = "mixed"
        checklist_id = self._done_checklist(3)
        result = await self._verify(checklist_id)
        self.assertEqual(result["action"], "review_completed")
        self.assertEqual(result["review_result"], "failed")
        self.assertEqual(result["review_status"], velox.REVIEW_FAILED)
        self.assertEqual(result["items"][0]["state"], velox.CHECKLIST_ITEM_IN_PROGRESS)
        self.assertEqual(result["items"][1]["state"], velox.CHECKLIST_ITEM_VERIFIED)
        self.assertEqual(result["items"][2]["state"], velox.CHECKLIST_ITEM_VERIFIED)
        self.assertIn("Repair the observed artifact defect", result["items"][0]["latest_comment"])
        self.assertEqual(self.agents.load_agent(result["review_agent_id"])["status"], "succeeded")
        self.assertNotEqual(result["review_status"], velox.REVIEW_ERROR)

    async def test_all_pass_reviewer_still_completes_normally(self) -> None:
        self.llm.mode = "pass"
        checklist_id = self._done_checklist(2)
        result = await self._verify(checklist_id)
        self.assertEqual(result["review_result"], "passed")
        self.assertEqual(result["lifecycle"], velox.CHECKLIST_LIFECYCLE_COMPLETED)
        self.assertEqual([item["state"] for item in result["items"]], [
            velox.CHECKLIST_ITEM_VERIFIED, velox.CHECKLIST_ITEM_VERIFIED,
        ])

    def test_malformed_progress_json_cannot_produce_false_success(self) -> None:
        malformed = '$$AGENT_PROGRESS: {"message":"done","percent":100'
        controls = velox.parse_agent_control_events(malformed)
        self.assertEqual(len(controls), 1)
        self.assertFalse(controls[0]["payload_valid"])
        self.assertEqual(controls[0]["kind"], "progress")
        self.assertIsNone(velox.AgentRuntime.__new__(velox.AgentRuntime)._terminal_event(controls))
        self.assertEqual(velox.agent_progress_control_diagnostic(malformed, controls)["status"], "malformed")

    def test_progress_diagnostics_distinguish_absent_malformed_nonterminal_and_failed(self) -> None:
        self.assertEqual(velox.agent_progress_control_diagnostic("ordinary reviewer prose")["status"], "absent")
        malformed = '$$AGENT_PROGRESS: {not-json}'
        self.assertEqual(velox.agent_progress_control_diagnostic(malformed)["status"], "malformed")
        nonterminal = '$$AGENT_PROGRESS: {"message":"still checking","percent":65}'
        self.assertEqual(velox.agent_progress_control_diagnostic(nonterminal)["status"], "non_terminal")
        failed = '$$AGENT_PROGRESS: {"message":"review infrastructure failed","percent":0,"failed":true}'
        self.assertEqual(velox.agent_progress_control_diagnostic(failed)["status"], "terminal_failed")

    async def test_genuine_missing_terminal_control_gets_bounded_recovery(self) -> None:
        self.llm.mode = "recover"
        checklist_id = self._done_checklist()
        result = await self._verify(checklist_id)
        self.assertEqual(result["review_result"], "passed")
        self.assertEqual(len(self.llm.requests), 2)
        reviewer_id = result["review_agent_id"]
        events = self.agents.load_transcript(reviewer_id)
        recoveries = [event for event in events if event.get("kind") == "reviewer_terminal_recovery"]
        self.assertEqual(len(recoveries), 1)
        recovery_prompt = "\n".join(
            str(message.get("content") or "")
            for message in self.llm.requests[1].messages
            if isinstance(message, dict) and str(message.get("role") or "") == "user"
        )
        self.assertIn("REVIEWER PROTOCOL RECOVERY 1/2", recovery_prompt)
        self.assertIn("Do not redo inspection", recovery_prompt)

    async def test_recovery_exhaustion_is_infrastructure_error_without_state_mutation(self) -> None:
        self.llm.mode = "exhaust_invalid"
        checklist_id = self._done_checklist(2)
        result = await self._verify(checklist_id)
        self.assertEqual(result["action"], "review_error")
        self.assertEqual(len(self.llm.requests), 1 + velox.REVIEWER_TERMINAL_RECOVERY_LIMIT)
        self.assertIn("protocol recovery exhausted", result["error"].lower())
        self.assertNotIn("Checklist is not active", result["error"])
        current = self.checklists.status(self.owner, checklist_id)
        self.assertEqual(current["review_status"], velox.REVIEW_ERROR)
        self.assertEqual([item["state"] for item in current["items"]], [
            velox.CHECKLIST_ITEM_DONE, velox.CHECKLIST_ITEM_DONE,
        ])
        reviewer = self.agents.load_agent(result["review_agent_id"])
        self.assertEqual(reviewer["status"], "failed")

    def test_multiple_or_conflicting_verdict_objects_are_rejected(self) -> None:
        state = {"requirements": [{"id":"C1"}]}
        one = '{"verdicts":[{"requirement_id":"C1","verdict":"pass","summary":"ok","next_step":""}]}'
        two = '{"verdicts":[{"requirement_id":"C1","verdict":"fail","summary":"bad","next_step":"fix it"}]}'
        with self.assertRaisesRegex(ValueError, "exactly one"):
            velox._parse_reviewer_result("preamble\n```json\n" + one + "\n```\nconflict\n" + two, state)

    def test_missing_duplicate_unknown_and_invalid_verdict_ids_are_rejected(self) -> None:
        state = {"requirements": [{"id":"C1"}, {"id":"C2"}]}
        cases = [
            (
                {"verdicts":[{"requirement_id":"C1","verdict":"pass","summary":"ok","next_step":""}]},
                "omitted requirement IDs",
            ),
            (
                {"verdicts":[
                    {"requirement_id":"C1","verdict":"pass","summary":"ok","next_step":""},
                    {"requirement_id":"C1","verdict":"pass","summary":"again","next_step":""},
                ]},
                "duplicate requirement IDs",
            ),
            (
                {"verdicts":[
                    {"requirement_id":"C1","verdict":"pass","summary":"ok","next_step":""},
                    {"requirement_id":"C9","verdict":"pass","summary":"unknown","next_step":""},
                ]},
                "unknown requirement IDs",
            ),
            (
                {"verdicts":[
                    {"requirement_id":"C1","verdict":"maybe","summary":"unclear","next_step":""},
                    {"requirement_id":"C2","verdict":"pass","summary":"ok","next_step":""},
                ]},
                "Invalid reviewer verdict",
            ),
        ]
        for payload, message in cases:
            with self.subTest(message=message):
                with self.assertRaisesRegex(ValueError, message):
                    velox._parse_reviewer_result(payload, state)

    async def test_reviewer_handoff_context_agent_logs_and_debug_reports_redact_secrets(self) -> None:
        pat = "ghp_ABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890"
        bearer = "Bearer abcdefghijklmnopqrstuvwxyz0123456789"
        api_key = "sk-abcdefghijklmnopqrstuvwx123456"
        password = "password=correct-horse-battery-staple"
        auth_url = f"https://triplenom:{pat}@github.com/triplenom/private-repo.git"
        sha1 = "a02a1bee49482f9509372666f66ef10ee1bf51e4"
        sha256 = "f0ba2fcfe374ac992096a7e070a7f744e8d5eb85ef16db08489144ba5b102dc2"
        secret_text = (
            f"Git PAT: {pat}\nAuthorization: {bearer}\nAPI key: {api_key}\n{password}\n"
            f"clone {auth_url}\nHEAD {sha1}\nartifact sha256 {sha256}"
        )
        self.chats.append_turn(velox.APP_SCOPE_ID, self.chat_id, velox.make_turn(self.chat_id, "user", secret_text))
        checklist_id = self._done_checklist()
        self.checklists.prepare_verification(self.owner, checklist_id)
        collection = self.checklists.load_collection(self.owner)
        checklist = self.checklists._checklist(collection, checklist_id)
        _state, package, context_path = velox._make_checklist_review_package(
            self.registry, self.owner, checklist,
            endpoint_profile_id=self.chats.get_chat_endpoint_profile_id(self.chat_id),
        )
        handoff_text = Path(package["handoff_path"]).read_text(encoding="utf-8")
        context_text = Path(context_path).read_text(encoding="utf-8")

        reviewer = self.agents.create_agent(
            self.chat_id,
            "Review this credential-bearing input:\n" + secret_text,
            title="Secret redaction reviewer",
            endpoint_profile_id=self.chats.get_chat_endpoint_profile_id(self.chat_id),
            context=velox.EXPERT_MODE_REVIEW_AGENT_CONTEXT_MARKER + "\n{}",
        )
        reviewer_id = str(reviewer["agent_id"])
        self.agents.append_event(reviewer_id, "llm_output", {"text": secret_text, "raw_response": {"authorization": bearer}})
        self.agents.update_agent(reviewer_id, {"final_message": secret_text, "last_output_excerpt": secret_text})
        durable_agent_text = self.paths.agent_json(reviewer_id).read_text(encoding="utf-8")
        durable_transcript_text = self.paths.agent_transcript_jsonl(reviewer_id).read_text(encoding="utf-8")
        debug_text = velox.format_chat_debug_report(
            self.chats.load_chat(self.chat_id),
            [velox.make_turn(self.chat_id, "user", secret_text)],
            data_root=str(self.paths.root_dir),
        )
        dashboard_payload = {
            "task_type": "Agent",
            "agent": self.agents.load_agent(reviewer_id),
            "agent_transcript": self.agents.load_transcript(reviewer_id),
        }
        inspector_text = velox.redact_durable_secret_text(velox.redact_endpoint_secrets(velox._task_inspector_json(dashboard_payload)))
        combined = "\n".join((handoff_text, context_text, durable_agent_text, durable_transcript_text, debug_text, inspector_text))
        for secret in (pat, bearer.split(" ", 1)[1], api_key, "correct-horse-battery-staple", auth_url):
            self.assertNotIn(secret, combined)
        self.assertIn("[REDACTED]", combined)
        self.assertIn(sha1, combined)
        self.assertIn(sha256, combined)

    def test_secret_redaction_does_not_overredact_sha1_sha256_orordinary_ids(self) -> None:
        sha1 = "a02a1bee49482f9509372666f66ef10ee1bf51e4"
        sha256 = "f0ba2fcfe374ac992096a7e070a7f744e8d5eb85ef16db08489144ba5b102dc2"
        ordinary_id = "CL-f423c66ad86740b0"
        text = f"HEAD={sha1} sha256={sha256} checklist={ordinary_id}"
        self.assertEqual(velox.redact_durable_secret_text(text), text)
        structured = velox.redact_durable_secrets({"head": sha1, "sha256": sha256, "checklist_id": ordinary_id})
        self.assertEqual(structured["head"], sha1)
        self.assertEqual(structured["sha256"], sha256)
        self.assertEqual(structured["checklist_id"], ordinary_id)

    def test_reviewer_final_contract_is_explicit_and_unsupported_root_is_rejected(self) -> None:
        self.assertIn('FINAL RESPONSE: exactly one unwrapped JSON object', velox.REVIEWER_SYSTEM_PROMPT)
        self.assertIn('Then emit this final non-empty line, with nothing after it:\n$$AGENT_PROGRESS: {"message":"Independent Checklist Review complete","percent":100}', velox.REVIEWER_SYSTEM_PROMPT)
        self.assertIn('final non-empty line, with nothing after it', velox.REVIEWER_SYSTEM_PROMPT)
        self.assertEqual(velox.APP_VERSION, "velox.v303")
        self.assertEqual(velox.DATA_FILE_VERSION, "v303")
        self.assertEqual(velox.APP_SCHEMA, "velox_app.v303")
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            paths, _storage, _chats = _make_test_chat_stack(root)
            manifest = velox.read_json(paths.app_json_path)
            manifest["data_version"] = "v274"
            manifest["schema"] = "velox_app.v274"
            velox.atomic_write_json(paths.app_json_path, manifest)
            with self.assertRaisesRegex(velox.UnsupportedDataVersionError, "v274"):
                velox.DATA_ROOTS.assert_supported(root)
        self.assertNotIn("migrate_", application_source())


class InferenceProtocolHardeningTests(_DataRootsIsolatedTestMixin, unittest.IsolatedAsyncioTestCase):
    """Streaming and nonstreaming provider-protocol boundaries."""

    class _Response:
        def __init__(self, data: bytes, url: str, *, status: int = 200) -> None:
            self._buffer = io.BytesIO(data)
            self.status = status
            self.headers = {"Content-Type": "text/event-stream", "X-Request-ID": "inference-protocol-test"}
            self._url = url
        def __enter__(self): return self
        def __exit__(self, *_args: Any) -> None: return None
        def readline(self, amount: int = -1) -> bytes: return self._buffer.readline(amount)
        def read(self, amount: int = -1) -> bytes: return self._buffer.read(amount)
        def getcode(self) -> int: return self.status
        def geturl(self) -> str: return self._url
        def close(self) -> None: return None

    @staticmethod
    def _sse(obj: Any) -> bytes:
        return b"data: " + json.dumps(obj, ensure_ascii=False).encode("utf-8") + b"\n\n"

    @staticmethod
    async def _collect(client: LLMClient, request: LLMRequest) -> list[LLMChunk]:
        chunks: list[LLMChunk] = []
        async for chunk in client.chat_completions_stream(request):
            chunks.append(chunk)
        return chunks

    @staticmethod
    def _chat_client(root: Path) -> tuple[LLMClient, LLMRequest]:
        _paths, storage, _chats = _make_test_chat_stack(root)
        config = storage.load_config()
        velox.endpoint_profile_ref(config, velox.DEFAULT_ENDPOINT_PROFILE_ID).update({
            "base_url": "http://127.0.0.1:8000/v1",
            "model": "protocol-test-model",
        })
        storage.write_config(config)
        return velox.LLMClient(storage), velox.LLMRequest(
            scope_id=velox.APP_SCOPE_ID,
            endpoint_profile_id=velox.DEFAULT_ENDPOINT_PROFILE_ID,
            messages=[{"role": "user", "content": "test"}],
            stream=True,
        )

    @staticmethod
    def _responses_client(root: Path) -> tuple[LLMClient, LLMRequest]:
        _paths, storage, _chats = _make_test_chat_stack(root)
        return velox.LLMClient(storage), velox.LLMRequest(
            scope_id=velox.APP_SCOPE_ID,
            endpoint_profile_id=velox.DEFAULT_GPT_5_6_SOL_ENDPOINT_PROFILE_ID,
            messages=[{"role": "user", "content": "test"}],
            stream=True,
        )

    async def test_chat_stream_strips_split_terminal_dsml_suffix_before_ui_or_storage(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            client, request = self._chat_client(Path(td))
            artifact = "</｜DSML｜parameter>"
            body = b"".join([
                self._sse({"choices":[{"delta":{"content":"Hello"}}]}),
                self._sse({"choices":[{"delta":{"content":artifact[:8]}}]}),
                self._sse({"choices":[{"delta":{"content":artifact[8:]}}]}),
                b"data: [DONE]\n\n",
            ])
            response = self._Response(body, "http://127.0.0.1:8000/v1/chat/completions")
            with mock.patch.object(urllib.request, "urlopen", return_value=response):
                chunks = await self._collect(client, request)
            self.assertFalse(any(chunk.error for chunk in chunks))
            self.assertEqual("".join(chunk.text for chunk in chunks), "Hello")
            self.assertFalse(any("DSML" in chunk.text for chunk in chunks))

    async def test_responses_snapshot_recovers_missing_delta_suffix_and_normalizes_replay_item(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            client, request = self._responses_client(Path(td))
            artifact = "</｜DSML｜parameter>"
            final_item = {"id":"msg_1","type":"message","role":"assistant","content":[
                {"type":"output_text","text":"Hello" + artifact},
            ]}
            body = b"".join([
                self._sse({"type":"response.output_text.delta","delta":"Hel"}),
                self._sse({"type":"response.completed","response":{
                    "id":"resp_1","status":"completed","output":[final_item],
                }}),
                b"data: [DONE]\n\n",
            ])
            response = self._Response(body, "https://api.openai.com/v1/responses")
            with mock.patch.object(urllib.request, "urlopen", return_value=response):
                chunks = await self._collect(client, request)
            self.assertFalse(any(chunk.error for chunk in chunks))
            self.assertEqual("".join(chunk.text for chunk in chunks), "Hello")
            terminal = chunks[-1]
            self.assertTrue(terminal.done)
            replay = json.dumps(terminal.response_output_items, ensure_ascii=False)
            self.assertNotIn("DSML", replay)
            self.assertIn("Hello", replay)

    async def test_responses_done_snapshot_can_finish_text_without_response_completed(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            client, request = self._responses_client(Path(td))
            body = b"".join([
                self._sse({"type":"response.output_text.delta","delta":"Hel"}),
                self._sse({"type":"response.output_text.done","text":"Hello"}),
                b"data: [DONE]\n\n",
            ])
            response = self._Response(body, "https://api.openai.com/v1/responses")
            with mock.patch.object(urllib.request, "urlopen", return_value=response):
                chunks = await self._collect(client, request)
            self.assertFalse(any(chunk.error for chunk in chunks))
            self.assertEqual("".join(chunk.text for chunk in chunks), "Hello")
            self.assertTrue(chunks[-1].done)

