class SchedulerConcurrencyHardeningTests(_DataRootsIsolatedTestMixin, unittest.TestCase):
    """Area-3 v1.0 hardening regressions for scheduling and lifecycle races."""

    def test_endpoint_slots_equal_only_live_provider_requests(self) -> None:
        async def scenario(root: Path) -> None:
            storage = _make_test_storage(root)
            profile = velox.default_endpoint_profile(
                "shared", "Shared", timeout_seconds=60,
                provider=velox.ENDPOINT_PROVIDER_VLLM, max_concurrent_requests=1,
            )
            monitor = velox.LLMTaskMonitor(storage)
            scheduler = velox.EndpointInferenceScheduler(storage, lambda _pid: profile, monitor)
            first_id = monitor.start(velox.APP_SCOPE_ID, "first", task_kind="chat")
            second_id = monitor.start(velox.APP_SCOPE_ID, "second", task_kind="chat")
            first = await scheduler.acquire(velox.LLMRequest(
                velox.APP_SCOPE_ID, "shared", [], monitor_task_id=first_id, task_kind="chat",
            ))
            snap = scheduler.snapshot()["shared"]
            self.assertEqual((snap["slots_consumed"], snap["inference_requests"]), (1, 1))
            self.assertTrue(snap["slot_invariant_ok"])
            monitor.set_phase(first_id, "tool")
            await first.release()
            snap = scheduler.snapshot()["shared"]
            self.assertEqual((snap["slots_consumed"], snap["inference_requests"]), (0, 0))
            self.assertTrue(snap["slot_invariant_ok"])
            second = await scheduler.acquire(velox.LLMRequest(
                velox.APP_SCOPE_ID, "shared", [], monitor_task_id=second_id, task_kind="chat",
            ))
            await second.release()
            monitor.complete(first_id); monitor.complete(second_id)
            await scheduler.close()
        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_rate_limit_budget_wait_happens_before_endpoint_slot_acquire(self) -> None:
        async def scenario(root: Path) -> None:
            storage = _make_test_storage(root)
            profile = velox.default_endpoint_profile(
                "shared", "Shared", timeout_seconds=60,
                provider=velox.ENDPOINT_PROVIDER_VLLM, max_concurrent_requests=1,
            )
            monitor = velox.LLMTaskMonitor(storage)
            scheduler = velox.EndpointInferenceScheduler(storage, lambda _pid: profile, monitor)
            client = velox.LLMClient(storage)
            client.resolve_endpoint = lambda _pid: profile
            client.bind_request_scheduler(scheduler, monitor)
            budget_entered = asyncio.Event()
            budget_gate = asyncio.Event()

            async def wait_budget(_request: velox.LLMRequest) -> float:
                budget_entered.set()
                await budget_gate.wait()
                return 0.25

            async def unqueued(_request: velox.LLMRequest) -> dict[str, Any]:
                return {"text": "ok", "usage": {"prompt_tokens": 1, "completion_tokens": 1}}

            client._wait_for_endpoint_request_budget = wait_budget  # type: ignore[method-assign]
            client._chat_completions_once_full_unqueued = unqueued  # type: ignore[method-assign]
            first_id = monitor.start(velox.APP_SCOPE_ID, "rate limited", task_kind="chat")
            request_task = asyncio.create_task(client.chat_completions_once_full(velox.LLMRequest(
                velox.APP_SCOPE_ID, "shared", [{"role": "user", "content": "hello"}],
                monitor_task_id=first_id, task_kind="chat",
            )))
            await asyncio.wait_for(budget_entered.wait(), 1.0)
            self.assertFalse(scheduler.snapshot().get("shared", {}).get("active"))
            second_id = monitor.start(velox.APP_SCOPE_ID, "other", task_kind="chat")
            second = await asyncio.wait_for(scheduler.acquire(velox.LLMRequest(
                velox.APP_SCOPE_ID, "shared", [], monitor_task_id=second_id, task_kind="chat",
            )), 1.0)
            budget_gate.set()
            await asyncio.sleep(0.03)
            self.assertFalse(request_task.done())
            await second.release()
            result = await asyncio.wait_for(request_task, 1.0)
            self.assertEqual(result["text"], "ok")
            self.assertEqual(result["usage"]["endpoint_wait_seconds"], 0.25)
            monitor.complete(first_id); monitor.complete(second_id)
            await scheduler.close()
        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_retry_cooldown_finishes_ready_not_fake_inference(self) -> None:
        async def scenario(root: Path) -> None:
            storage = _make_test_storage(root)
            monitor = velox.LLMTaskMonitor(storage)
            task_id = monitor.start(velox.APP_SCOPE_ID, "cooldown", task_kind="chat")
