            waited = await velox.wait_for_endpoint_retry_cooldown(
                0.01, monitor=monitor, task_id=task_id, reason="test cooldown",
            )
            self.assertGreaterEqual(waited, 0.0)
            metadata = monitor.record_metadata(task_id)
