    def test_pause_lifecycle_keeps_queued_acquire_alive_until_resume(self) -> None:
        async def scenario(root: Path) -> None:
            storage = _make_test_storage(root)
            profile = velox.default_endpoint_profile(
                "shared", "Shared", timeout_seconds=60,
                provider=velox.ENDPOINT_PROVIDER_VLLM, max_concurrent_requests=1,
            )
            monitor = velox.LLMTaskMonitor(storage)
            scheduler = velox.EndpointInferenceScheduler(storage, lambda _pid: profile, monitor)
            holder_id = monitor.start(velox.APP_SCOPE_ID, "holder", task_kind="chat")
            paused_id = monitor.start(velox.APP_SCOPE_ID, "paused", task_kind="agent")
            holder = await scheduler.acquire(velox.LLMRequest(
                velox.APP_SCOPE_ID, "shared", [], monitor_task_id=holder_id, task_kind="chat",
            ))
            waiter = asyncio.create_task(scheduler.acquire(velox.LLMRequest(
                velox.APP_SCOPE_ID, "shared", [], monitor_task_id=paused_id, task_kind="agent",
            )))
            await asyncio.sleep(0.02)
            monitor.set_phase(paused_id, "paused")
            await asyncio.sleep(0.04)
            self.assertFalse(waiter.done())
            self.assertEqual(len(scheduler.snapshot()["shared"]["paused"]), 1)
            await holder.release()
            await asyncio.sleep(0.03)
            self.assertFalse(waiter.done())
            monitor.set_phase(paused_id, "ready")
            lease = await asyncio.wait_for(waiter, 1.0)
            await lease.release()
            monitor.complete(holder_id); monitor.complete(paused_id)
            await scheduler.close()
        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_chat_resume_before_safe_boundary_preserves_live_inference_phase(self) -> None:
        async def scenario(root: Path) -> None:
            storage = _make_test_storage(root)
            monitor = velox.LLMTaskMonitor(storage)
            task_id = monitor.start(velox.APP_SCOPE_ID, "chat", task_kind="chat")
            monitor.set_phase(task_id, "inference")
            class FakeScheduler:
                def __init__(self) -> None: self.notified = 0
                def notify_task_state_changed(self) -> None: self.notified += 1
            fake_scheduler = FakeScheduler()
            runtime = velox.ChatRuntime.__new__(velox.ChatRuntime)
            runtime.monitor = monitor
            runtime.storage = storage
            runtime.llm = SimpleNamespace(request_scheduler=fake_scheduler)
            runtime._monitor_task_ids = {"chat": task_id}
            runtime._pause_requests = {"chat"}
            runtime._paused_chats = set()
            event = asyncio.Event(); event.clear()
            runtime._pause_events = {"chat": event}
            self.assertTrue(runtime.resume("chat"))
            self.assertEqual(monitor.record_metadata(task_id)["phase"], "inference")
            self.assertFalse(monitor.record_metadata(task_id)["pause_requested"])
            self.assertEqual(fake_scheduler.notified, 1)
        with tempfile.TemporaryDirectory() as td:
            asyncio.run(scenario(Path(td)))

    def test_direct_agent_pause_and_resume_keep_monitor_scheduler_in_sync(self) -> None:
        async def scenario(root: Path) -> None:
            paths, storage, chats = _make_test_chat_stack(root)
            chat_id = str(chats.create_chat("parent")["chat_id"])
            agents = velox.AgentStore(storage)
