            agent_id = str(agent["agent_id"])
            agents.update_agent(agent_id, {
                "status": "running", "started_at": velox.now_iso(), "pause_requested": False,
            })
            monitor = velox.LLMTaskMonitor(storage)
            task_id = monitor.start(velox.APP_SCOPE_ID, "agent", task_kind="agent", metadata={"agent_id": agent_id})
            monitor.set_phase(task_id, "inference")
            class FakeScheduler:
                def __init__(self) -> None: self.notified = 0
                def notify_task_state_changed(self) -> None: self.notified += 1
            fake_scheduler = FakeScheduler()
            llm = SimpleNamespace(request_scheduler=fake_scheduler)
            runtime = velox.AgentRuntime(storage, agents, chats, velox.ContextAssembler(paths), llm, velox.ToolRegistry(storage), monitor)
            runtime._monitor_task_ids[agent_id] = task_id
