# Owner lifecycle and reviewer failure paths.
class DurableLifecycleTests(_DataRootsIsolatedTestMixin, unittest.TestCase):
    def setUp(self) -> None:
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.paths, self.storage, self.chats = _make_test_chat_stack(Path(self.temp.name))
        self.chat = self.chats.create_chat('Owner')
        self.cid = str(self.chat['chat_id'])
        self.agents = velox.AgentStore(self.storage)
        self.owner = {'owner_kind':'chat', 'chat_id':self.cid, 'agent_id':'', 'task_run_id':0}

    def test_late_chat_record_write_cannot_resurrect_deleted_chat(self) -> None:
        stale = self.chats.load_chat(self.cid)
        self.chats.delete_chat(velox.APP_SCOPE_ID, self.cid)
        with self.assertRaises(FileNotFoundError):
            self.chats.write_chat(stale)
        self.assertFalse(self.paths.chat_dir(self.cid).exists())

    def test_late_agent_record_write_cannot_resurrect_deleted_agent(self) -> None:
        agent = self.agents.create_agent(self.cid, 'Work')
        aid = str(agent['agent_id'])
        self.agents.delete_agent(aid, force=True)
        with self.assertRaises(FileNotFoundError):
            self.agents.write_agent(agent)
        self.assertFalse(self.paths.agent_dir(aid).exists())

    def test_late_agent_event_cannot_resurrect_deleted_agent(self) -> None:
        agent = self.agents.create_agent(self.cid, 'Work')
        aid = str(agent['agent_id'])
        self.agents.delete_agent(aid, force=True)
        with self.assertRaises(FileNotFoundError):
            self.agents.append_event(aid, 'progress', {'message':'late callback'})
        self.assertFalse(self.paths.agent_dir(aid).exists())

    def test_late_chat_turn_cannot_resurrect_deleted_chat(self) -> None:
        self.chats.delete_chat(velox.APP_SCOPE_ID, self.cid)
        with self.assertRaises(FileNotFoundError):
            self.chats.append_turn(velox.APP_SCOPE_ID, self.cid, velox.make_turn(self.cid, 'user', 'late'))
        self.assertFalse(self.paths.chat_dir(self.cid).exists())

    def test_checklist_read_does_not_recreate_deleted_owner(self) -> None:
        self.chats.delete_chat(velox.APP_SCOPE_ID, self.cid)
        with self.assertRaises(FileNotFoundError):
            velox.ChecklistStore(self.storage).load_collection(self.owner)
        self.assertFalse(self.paths.chat_dir(self.cid).exists())

    def test_switch_forces_destination_validation_before_saving_draft(self) -> None:
        destination = self.chats.create_chat('Destination')
        target = str(destination['chat_id'])
        self.chats.get_chat_endpoint_profile_id(target)
        shutil.rmtree(self.paths.chat_dir(target))
        panel = velox.Panels.__new__(velox.Panels)
        panel.state = velox.UIState()
        panel.state.active_panel = 'chat'
        panel.state.active_chat_id = self.cid
        panel.services = SimpleNamespace(chats=self.chats)
        panel._save_chat_composer_draft = mock.Mock()
        panel._load_chat_composer_draft = mock.Mock()
        panel._reset_chat_ui_cache = mock.Mock()
        with self.assertRaises(FileNotFoundError):
            panel._switch_active_chat(target)
        self.assertEqual(panel.state.active_chat_id, self.cid)
        panel._save_chat_composer_draft.assert_not_called()
        panel._load_chat_composer_draft.assert_not_called()

    def test_chat_read_disappearance_is_file_not_found_not_schema_error(self) -> None:
        target = self.paths.chat_json(self.cid)
        read = velox.read_json
        def racing_read(path: Path, default: Any = None) -> Any:
            if Path(path) == target:
                shutil.rmtree(self.paths.chat_dir(self.cid))
                return default
            return read(path, default)
        with mock.patch(f'{velox.__name__}.read_json', side_effect=racing_read):
            with self.assertRaises(FileNotFoundError):
                self.chats.load_chat(self.cid)

    def test_agent_read_disappearance_is_file_not_found_not_schema_error(self) -> None:
        agent = self.agents.create_agent(self.cid, 'Work')
        aid = str(agent['agent_id'])
        target = self.paths.agent_json(aid)
        self.agents._invalidate(aid)
        read = velox.read_json
        def racing_read(path: Path, default: Any = None) -> Any:
            if Path(path) == target:
                shutil.rmtree(self.paths.agent_dir(aid))
                return default
            return read(path, default)
        with mock.patch(f'{velox.__name__}.read_json', side_effect=racing_read):
            with self.assertRaises(FileNotFoundError):
                self.agents.load_agent(aid)

    def test_postcommit_logging_does_not_report_create_or_rename_failure(self) -> None:
        with mock.patch.object(self.storage, 'append_app_log', side_effect=OSError('log unavailable')):
            chat = self.chats.create_chat('New')
            renamed = self.chats.rename_chat(velox.APP_SCOPE_ID, str(chat['chat_id']), 'Renamed')
            agent = self.agents.create_agent(self.cid, 'Work')
        self.assertEqual(renamed['name'], 'Renamed')
        self.assertTrue(self.paths.agent_json(str(agent['agent_id'])).is_file())

    def test_whole_agent_write_cannot_revive_terminal_task(self) -> None:
        stale = self.agents.create_agent(self.cid, 'Work')
        aid = str(stale['agent_id'])
        self.agents.update_agent(aid, {'status':'cancelled'})
        self.agents.write_agent(stale)
        self.assertEqual(self.agents.load_agent(aid)['status'], 'cancelled')

    def test_restart_unlocks_requested_and_running_reviews_without_verifying(self) -> None:
        manager=velox.ChecklistStore(self.storage); cases=[]
        for name in ('requested','running'):
            owner=velox._chat_checklist_owner(self.chats.create_chat(name)['chat_id'])
            cid=manager.create(owner,name=name,items=['Outcome'])['checklist_id']
            manager.update_items(owner,cid,[{'item_id':'C1','state':'done','comment':'Implemented.'}])
            manager.prepare_verification(owner,cid)
            if name=='running': velox._set_checklist_review_state(manager,owner,cid,velox.REVIEW_RUNNING,agent_id='missing-reviewer')
            cases.append((owner,cid))
        self.agents.recover_interrupted()
        for owner,cid in cases:
            status=manager.status(owner,cid)
            self.assertEqual(status['review_status'],velox.REVIEW_ERROR)
            self.assertEqual(status['items'][0]['state'],velox.CHECKLIST_ITEM_DONE)
            manager.update_items(owner,cid,[{'item_id':'C1','state':'in_progress','comment':'Repair after restart.'}])


class ChecklistTransitionTests(_DataRootsIsolatedTestMixin, unittest.TestCase):
    def setUp(self) -> None:
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.paths, self.storage, self.chats = _make_test_chat_stack(Path(self.temp.name))
        self.cid = str(self.chats.create_chat('Checklist owner')['chat_id'])
        self.owner = {'owner_kind':'chat','chat_id':self.cid,'agent_id':'','task_run_id':0}
        self.manager = velox.ChecklistStore(self.storage)
        self.lid = self.manager.create(self.owner, name='Acceptance', items=['One','Two'])['checklist_id']

    def done(self) -> None:
        self.manager.update_items(self.owner, self.lid, [
            {'item_id':f'C{i}', 'state':'done', 'comment':'Executed current output.'} for i in (1,2)])

    def test_arbitrary_actor_cannot_set_verified(self) -> None:
        for actor in ('velox', 'system', '', 'reviewer'):
            with self.subTest(actor=actor):
                with self.assertRaises(ValueError):
                    self.manager.update_items(self.owner, self.lid, [{'item_id':'C1','state':'verified','comment':'untrusted'}], actor=actor)
        self.assertEqual(self.manager.status(self.owner, self.lid)['counts'][velox.CHECKLIST_ITEM_VERIFIED], 0)

    def test_unknown_or_missing_item_state_rejected(self) -> None:
        for state in (None, '', 'typo', 'passed', 'complete'):
            with self.subTest(state=state):
                with self.assertRaises(ValueError):
                    self.manager.update_items(self.owner, self.lid, [{'item_id':'C1','state':state,'comment':'Not a state'}])

    def test_invalid_update_batch_does_not_append_phantom_history(self) -> None:
        history = self.manager._history_path(self.owner)
        before_history = history.read_bytes()
        before = self.manager.status(self.owner, self.lid)
        with self.assertRaises(ValueError):
            self.manager.update_items(self.owner, self.lid, [
                {'item_id':'C1','state':'done','comment':'first'},
                {'item_id':'C99','state':'done','comment':'invalid second'},
            ])
        self.assertEqual(history.read_bytes(), before_history)
        self.assertEqual(self.manager.status(self.owner, self.lid), before)

    def test_done_wording_stays_fixed_but_evidence_can_reopen(self) -> None:
        self.done(); before=self.manager.status(self.owner,self.lid,include_history=True)
        raw=self.manager.load_collection(self.owner); raw['checklists'][0]['items'][0]['text']='Different acceptance outcome'
        with self.assertRaises(ValueError): self.manager._save(self.owner,raw)
        changed=self.manager.update_items(self.owner,self.lid,[{'item_id':'C1','state':'in_progress','comment':'Contrary runtime evidence'}])
        self.assertEqual(changed['items'][0]['text'],before['items'][0]['text'])
        self.assertEqual(changed['items'][0]['state'],velox.CHECKLIST_ITEM_IN_PROGRESS)
        with self.assertRaises(ValueError): self.manager.prepare_verification(self.owner,self.lid)

    def test_stale_execution_projection_cannot_verify_or_overwrite_active_list(self) -> None:
        self.done(); adapter=velox.ExpertModeStore.for_chat(self.storage,self.cid)
        old=adapter.load()
        self.manager.cancel_open_by_user(self.owner)
        new_id=self.manager.create(self.owner,name='New work',items=['Different one','Different two'])['checklist_id']
        for item in old['requirements']: item['state']=item['status']=velox.CHECKLIST_ITEM_VERIFIED
        adapter.path.write_text(json.dumps(old),encoding='utf-8')
        current=adapter.load()
        self.assertEqual(current['checklist_id'],new_id)
        self.assertTrue(all(item['status']=='not_started' for item in current['requirements']))
        self.assertEqual(self.manager.status(self.owner,new_id)['lifecycle'],velox.CHECKLIST_LIFECYCLE_OPEN)

    def test_review_apply_rejects_old_cycle_before_any_mutation(self) -> None:
        self.done()
        self.manager.prepare_verification(self.owner, self.lid)
        before = self.manager.status(self.owner, self.lid)
        with self.assertRaises(ValueError):
            self.manager.apply_review(self.owner, self.lid, [
                {'item_id':f'C{i}','verdict':'pass','comment':'Reviewed.'} for i in (1,2)], review_cycle=99)
        self.assertEqual(self.manager.status(self.owner, self.lid), before)

    def test_parser_rejects_duplicate_json_keys_and_non_string_evidence(self) -> None:
        state = {'requirements':[{'id':'C1'}]}
        row = {'requirement_id':'C1','verdict':'pass','summary':'Observed','next_step':''}
        valid = json.dumps({'verdicts':[row]})
        invalid = [valid.replace('"verdict": "pass"', '"verdict": "fail", "verdict": "pass"'),
                   '{"verdicts":[],"verdicts":' + json.dumps([row]) + '}',
                   json.dumps({'verdicts':[dict(row, summary={'invented':'object'})]}),
                   json.dumps({'verdicts':[dict(row, verdict='fail', next_step=['repair'])]})]
        for payload in invalid:
            with self.subTest(payload=payload):
                with self.assertRaises(ValueError):
                    velox._parse_reviewer_result(payload, state)


class ReviewerFailurePathTests(_DataRootsIsolatedTestMixin, unittest.IsolatedAsyncioTestCase):
    asyncSetUp = ReviewerAgentLoopTests.asyncSetUp
    asyncTearDown = ReviewerAgentLoopTests.asyncTearDown
    _done_checklist = ReviewerAgentLoopTests._done_checklist
    _verify = ReviewerAgentLoopTests._verify

    async def test_handoff_failure_unlocks_checklist_and_preserves_done_items(self) -> None:
        lid = self._done_checklist()
        with mock.patch(f'{velox.__name__}._make_checklist_review_package', side_effect=OSError('handoff disk failure')):
            result = await self._verify(lid)
        self.assertEqual(result['action'], 'review_error')
        self.assertEqual(result['review_status'], velox.REVIEW_ERROR)
        self.assertEqual(result['items'][0]['state'], velox.CHECKLIST_ITEM_DONE)
        self.checklists.update_items(self.owner, lid, [{'item_id':'C1','state':'in_progress','comment':'Repair'}])

    async def test_reviewer_creation_failure_unlocks_checklist(self) -> None:
        lid = self._done_checklist()
        with mock.patch.object(self.agents, 'create_agent', side_effect=OSError('agent disk failure')):
            result = await self._verify(lid)
        self.assertEqual(result['action'], 'review_error')
        self.assertEqual(self.checklists.status(self.owner, lid)['review_status'], velox.REVIEW_ERROR)

    async def test_postcommit_export_failure_does_not_relabel_accepted_review(self) -> None:
        lid = self._done_checklist()
        original = velox._write_expert_state_json
        def fail_result(path: Path, value: Any) -> None:
            if Path(path).name == 'review_result.json':
                raise OSError('result export disk failure')
            original(path, value)
        with mock.patch(f'{velox.__name__}._write_expert_state_json', side_effect=fail_result):
            result = await self._verify(lid)
        self.assertEqual(result['action'], 'review_completed')
        self.assertEqual(result['review_status'], velox.REVIEW_PASSED)
        self.assertEqual(result['items'][0]['state'], velox.CHECKLIST_ITEM_VERIFIED)

    async def test_reviewer_cannot_inherit_pending_implementer_assignment(self) -> None:
        lid = self._done_checklist()
        token = velox._PENDING_AGENT_ROLE.set({'subtype':velox.AGENT_SUBTYPE_IMPLEMENTER,'assigned_checklist_id':lid})
        try:
            result = await self._verify(lid)
        finally:
            velox._PENDING_AGENT_ROLE.reset(token)
        self.assertEqual(result['action'], 'review_completed')
        reviewer = self.agents.load_agent(result['review_agent_id'])
        self.assertNotEqual(velox.AgentRoleStore(self.storage).load(reviewer['agent_id']).get('subtype'), velox.AGENT_SUBTYPE_IMPLEMENTER)

    async def test_valid_verdict_survives_exhausted_progress_only_recovery(self) -> None:
        fake = _ReviewerProtocolLLM(self.storage, mode='exhaust')
        self.runtime.llm = fake
        lid = self._done_checklist(2)
        result = await self._verify(lid)
        self.assertEqual(result['action'], 'review_completed')
        self.assertEqual(result['review_result'], 'passed')
        self.assertEqual(len(fake.requests), 1 + velox.REVIEWER_TERMINAL_RECOVERY_LIMIT)
        self.assertEqual(self.agents.load_agent(result['review_agent_id'])['status'], 'succeeded')
        events = self.agents.load_transcript(result['review_agent_id'])
        self.assertTrue(any(event['kind'] == 'reviewer_terminal_result_recovered' for event in events))
        self.assertFalse(getattr(self.runtime, '_reviewer_protocol_only', set()))

    async def test_malformed_terminal_progress_preserves_valid_mixed_verdict(self) -> None:
        class Endpoint(_ReviewerTestLLM):
            async def chat_completions_once_full(inner, request: LLMRequest) -> dict[str, Any]:
                inner.requests.append(copy.deepcopy(request))
                text = _ReviewerProtocolLLM._verdict_json(['C1','C2'], fail_first=True)
                text += '\n$$AGENT_PROGRESS: {"message":"done","percent":100'
                return {'text':text,'finish_reason':'stop'}
        fake = Endpoint(self.storage)
        self.runtime.llm = fake
        result = await self._verify(self._done_checklist(2))
        self.assertEqual(result['action'], 'review_completed')
        self.assertEqual(result['review_result'], 'failed')
        self.assertEqual([i['state'] for i in result['items']], ['in_progress','verified'])
        self.assertEqual(len(fake.requests), 3)

    async def test_protocol_recovery_cannot_execute_more_review_tools(self) -> None:
        class Endpoint(_ReviewerTestLLM):
            async def chat_completions_once_full(inner, request: LLMRequest) -> dict[str, Any]:
                inner.requests.append(copy.deepcopy(request))
                if len(inner.requests) == 1:
                    return {'text':_ReviewerProtocolLLM._verdict_json(['C1']), 'finish_reason':'stop'}
                if len(inner.requests) == 2:
                    return {'text':'Repeat inspection.', 'finish_reason':'tool_calls', 'tool_calls':[
                        {'id':'forbidden-recovery-tool','type':'function','function':{'name':'fs_list','arguments':json.dumps({'path':str(self.paths.root_dir)})}}]}
                return {'text':_ReviewerProtocolLLM._verdict_json(['C1'])+'\n$$AGENT_PROGRESS: {"message":"done","percent":100}', 'finish_reason':'stop'}
        fake = Endpoint(self.storage)
        self.runtime.llm = fake
        lid = self._done_checklist()
        result = await self._verify(lid)
        self.assertEqual(result['action'], 'review_error')
        self.assertEqual(len(fake.requests), 2)
        self.assertFalse(fake.requests[1].native_tools)
        reviewer = self.agents.load_agent(result['review_agent_id'])
        self.assertEqual(reviewer['tool_call_count'], 0)
        self.assertEqual(result['items'][0]['state'], 'done')

    def test_verdict_extraction_never_reads_prompts_as_review_results(self) -> None:
        record = {'task':_ReviewerProtocolLLM._verdict_json(['C1'])}
        fake = SimpleNamespace(agents=SimpleNamespace(load_transcript=lambda aid: []))
        with self.assertRaises(RuntimeError):
            velox._extract_reviewer_result(fake, 'reviewer', record)

    def test_verdict_extraction_rejects_old_verdict_before_later_tool_work(self) -> None:
        events = [
            {'kind':'llm_output','data':{'text':_ReviewerProtocolLLM._verdict_json(['C1']), 'termination_category':'normal'}},
            {'kind':'reviewer_terminal_recovery','data':{'attempt':1}},
            {'kind':'llm_output','data':{'text':'Rechecking.', 'native_tool_calls':[{'id':'next'}], 'termination_category':'tool'}},
            {'kind':'tool_result','data':{'ok':True}},
            {'kind':'llm_output','data':{'text':'$$AGENT_PROGRESS: {"message":"done","percent":100}', 'termination_category':'normal'}},
        ]
        fake = SimpleNamespace(agents=SimpleNamespace(load_transcript=lambda aid: events))
        with self.assertRaises(RuntimeError):
            velox._extract_reviewer_result(fake, 'reviewer', {})



    async def test_restart_fails_orphan_paused_reviewer_but_preserves_normal_pause(self) -> None:
        reviewer = self.agents.create_agent(self.chat_id, 'Review', context=velox.EXPERT_MODE_REVIEW_AGENT_CONTEXT_MARKER+'\n{}')
        normal = self.agents.create_agent(self.chat_id, 'Ordinary work')
        for row in (reviewer, normal):
            self.agents.update_agent(row['agent_id'], {'status':'paused'})
        self.agents.recover_interrupted()
        self.assertEqual(self.agents.load_agent(reviewer['agent_id'])['status'], 'failed')
        self.assertEqual(self.agents.load_agent(normal['agent_id'])['status'], 'paused')


class AtomicStateTests(_DataRootsIsolatedTestMixin, unittest.TestCase):
    setUp = ChecklistTransitionTests.setUp
    done = ChecklistTransitionTests.done

    def test_failed_snapshot_write_does_not_append_phantom_review_history(self) -> None:
        self.done()
        self.manager.prepare_verification(self.owner, self.lid)
        path = self.manager._collection_path(self.owner)
        before = path.read_bytes()
        history = self.manager._history_path(self.owner)
        before_history = history.read_bytes()
        original = velox._write_checklist_json
        def fail_collection(target: Path, value: Any) -> None:
            if Path(target) == path:
                raise OSError('snapshot unavailable')
            original(target, value)
        with mock.patch(f'{velox.__name__}._write_checklist_json', side_effect=fail_collection):
            with self.assertRaises(OSError):
                self.manager.apply_review(self.owner, self.lid, [{'item_id':f'C{i}','verdict':'pass','comment':'Observed.'} for i in (1,2)])
        self.assertEqual(path.read_bytes(), before)
        self.assertEqual(history.read_bytes(), before_history)

    def test_history_mirror_failure_cannot_undo_committed_review(self) -> None:
        self.done()
        self.manager.prepare_verification(self.owner, self.lid)
        with mock.patch(f'{velox.__name__}._append_checklist_jsonl', side_effect=OSError('history mirror unavailable')):
            result = self.manager.apply_review(self.owner, self.lid, [{'item_id':f'C{i}','verdict':'pass','comment':'Observed final artifact.'} for i in (1,2)])
        self.assertEqual(result['review_status'], velox.REVIEW_PASSED)
        self.assertEqual(result['lifecycle'], velox.CHECKLIST_LIFECYCLE_COMPLETED)
        report = velox.checklist_history_report_markdown('Acceptance', self.manager.history_reports(self.owner))
        self.assertIn('Observed final artifact.', report)

    def test_completed_review_commits_items_and_status_once(self) -> None:
        self.done()
        self.manager.prepare_verification(self.owner, self.lid)
        original = self.manager._save
        commits = []
        def tracked(owner: dict[str, Any], collection: dict[str, Any]) -> None:
            checklist = self.manager._checklist(collection, self.lid)
            commits.append((checklist['lifecycle'],checklist['review_status'],[i['state'] for i in checklist['items']]))
            original(owner, collection)
        with mock.patch.object(self.manager, '_save', side_effect=tracked):
            self.manager.apply_review(self.owner, self.lid, [{'item_id':f'C{i}','verdict':'pass','comment':'Observed.'} for i in (1,2)])
        self.assertTrue(commits)
        self.assertTrue(all(status == velox.REVIEW_PASSED for lifecycle,status,states in commits if lifecycle == velox.CHECKLIST_LIFECYCLE_COMPLETED))


    def test_collection_copied_between_owners_is_rejected(self) -> None:
        other = str(self.chats.create_chat('Other')['chat_id'])
        owner = dict(self.owner, chat_id=other)
        shutil.copyfile(self.manager._collection_path(self.owner), self.manager._collection_path(owner))
        with self.assertRaisesRegex(ValueError, 'owner'):
            self.manager.load_collection(owner)

    def test_review_mutability_guard_and_mutation_share_one_lock(self) -> None:
        original=velox.ChecklistStore._mutable_checklist; observations=[]
        def guard(manager,owner,collection,checklist_id):
            result=original(manager,owner,collection,checklist_id)
            def probe():
                acquired=velox._CHECKLIST_LOCK.acquire(blocking=False); observations.append(acquired)
                if acquired: velox._CHECKLIST_LOCK.release()
            worker=threading.Thread(target=probe); worker.start(); worker.join(2)
            self.assertFalse(worker.is_alive()); return result
        with mock.patch.object(velox.ChecklistStore,'_mutable_checklist',guard):
            self.manager.update_items(self.owner,self.lid,[{'item_id':'C1','state':'in_progress','comment':'Current work.'}])
            self.manager.create_subitems(self.owner,self.lid,'C1',['One immutable step'])
        self.assertEqual(observations,[False,False])

    def test_full_history_export_includes_checklist_review_lifecycle_events(self) -> None:
        self.done()
        self.manager.prepare_verification(self.owner, self.lid)
        velox._set_checklist_review_state(self.manager, self.owner, self.lid, velox.REVIEW_ERROR, error='First attempt crashed', event='review_error')
        self.manager.prepare_verification(self.owner, self.lid)
        self.manager.apply_review(self.owner, self.lid, [{'item_id':f'C{i}','verdict':'pass','comment':'Fresh rerun verified.'} for i in (1,2)])
        reports = self.manager.history_reports(self.owner)
        self.assertTrue(reports[0].get('history'))
        markdown = velox.checklist_history_report_markdown('History', reports)
        self.assertIn('First attempt crashed', markdown)
        self.assertIn('Checklist Events', markdown)
        self.assertIn('First attempt crashed', velox.checklist_history_report_html(markdown, title='History'))

    def test_parser_rejects_nested_or_broken_wrapper_verdict(self) -> None:
        valid = _ReviewerProtocolLLM._verdict_json(['C1'])
        for text in ('{"not_the_verdict":'+valid+'}', '{"broken":'+valid):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    velox._parse_reviewer_result(text, {'requirements':[{'id':'C1'}]})



class DeletionCommitTests(_DataRootsIsolatedTestMixin, unittest.TestCase):
    setUp = DurableLifecycleTests.setUp

    def test_failed_chat_creation_never_publishes_partial_record(self) -> None:
        before = {p.name for p in self.paths.chats_dir().iterdir()}
        with mock.patch(f'{velox.__name__}.atomic_write_text', side_effect=OSError('initial transcript unavailable')):
            with self.assertRaises(OSError):
                self.chats.create_chat('Partial')
        self.assertEqual({p.name for p in self.paths.chats_dir().iterdir()}, before)

    def test_failed_agent_creation_never_publishes_partial_record(self) -> None:
        before = {p.name for p in self.paths.agents_dir().iterdir()}
        with mock.patch(f'{velox.__name__}.atomic_write_text', side_effect=OSError('initial transcript unavailable')):
            with self.assertRaises(OSError):
                self.agents.create_agent(self.cid, 'Partial')
        self.assertEqual({p.name for p in self.paths.agents_dir().iterdir()}, before)

    def test_late_stream_snapshot_does_not_recreate_chat(self) -> None:
        snapshot = velox.chat_stream_snapshot_record(self.cid, velox.make_turn(self.cid,'assistant','late',status='streaming'))
        path = self.paths.chat_stream_snapshot_json(self.cid)
        self.chats.delete_chat(velox.APP_SCOPE_ID, self.cid)
        velox.CHAT_STREAM_SNAPSHOT_WRITER.submit(path, snapshot)
        self.assertTrue(velox.CHAT_STREAM_SNAPSHOT_WRITER.flush([path]))
        self.assertFalse(self.paths.chat_dir(self.cid).exists())

    def test_failed_directory_detach_preserves_entire_live_chat(self) -> None:
        path = self.paths.chat_dir(self.cid)
        before = {str(p.relative_to(path)):p.read_bytes() for p in path.rglob('*') if p.is_file()}
        with mock.patch.object(os, 'replace', side_effect=PermissionError('directory locked')):
            with self.assertRaises(PermissionError):
                self.chats.delete_chat(velox.APP_SCOPE_ID, self.cid)
        after = {str(p.relative_to(path)):p.read_bytes() for p in path.rglob('*') if p.is_file()}
        self.assertEqual(after, before)

    def test_cleanup_failure_after_detach_is_committed_deletion(self) -> None:
        with mock.patch.object(shutil, 'rmtree', side_effect=PermissionError('attachment locked')):
            self.chats.delete_chat(velox.APP_SCOPE_ID, self.cid)
        self.assertFalse(self.paths.chat_json(self.cid).exists())
        self.assertFalse(self.paths.chat_dir(self.cid).exists())
        self.assertNotIn(self.cid, {r['chat_id'] for r in self.chats.list_chats()})
        self.assertNotIn(self.cid, self.chats._turn_cache)

    def test_agent_cleanup_failure_after_detach_is_committed_deletion(self) -> None:
        agent = self.agents.create_agent(self.cid, 'Finished')
        self.agents.update_agent(agent['agent_id'], {'status':'succeeded'})
        with mock.patch.object(shutil, 'rmtree', side_effect=PermissionError('transcript locked')):
            self.agents.delete_agent(agent['agent_id'])
        self.assertFalse(self.paths.agent_dir(agent['agent_id']).exists())
        self.assertNotIn(agent['agent_id'], {r['agent_id'] for r in self.agents.list_agents()})


class ReviewBoundaryTests(unittest.IsolatedAsyncioTestCase):
    asyncSetUp = ReviewerAgentLoopTests.asyncSetUp
    asyncTearDown = ReviewerAgentLoopTests.asyncTearDown
    _done_checklist = ReviewerAgentLoopTests._done_checklist
    _verify = ReviewerAgentLoopTests._verify

    async def test_deleted_owner_during_package_creation_is_not_resurrected(self) -> None:
        lid = self._done_checklist()
        original = velox._collect_message_sequence
        def remove_owner(*args: Any, **kwargs: Any) -> list[dict[str, Any]]:
            messages = original(*args, **kwargs)
            self.chats.delete_chat(velox.APP_SCOPE_ID, self.chat_id)
            return messages
        with mock.patch(f'{velox.__name__}._collect_message_sequence', side_effect=remove_owner):
            result = await self._verify(lid)
        self.assertEqual(result['action'], 'review_error')
        self.assertTrue(result['owner_deleted'])
        self.assertFalse(self.paths.chat_dir(self.chat_id).exists())
        self.assertFalse(self.agents.list_agents(self.chat_id))

    async def test_valid_verdict_cannot_override_explicit_failure_or_truncation(self) -> None:
        for finish, progress in (
            ('stop', '\n$$AGENT_PROGRESS: {"message":"Review could not finish","percent":50,"failed":true}'),
            ('length', '\n$$AGENT_PROGRESS: {"message":"Complete","percent":100}'),
            ('content_filter', '\n$$AGENT_PROGRESS: {"message":"Complete","percent":100}'),
        ):
            with self.subTest(finish=finish):
                class Endpoint(_ReviewerTestLLM):
                    async def chat_completions_once_full(inner, request: LLMRequest) -> dict[str, Any]:
                        inner.requests.append(request)
                        return {'text':_ReviewerProtocolLLM._verdict_json(['C1']) + progress, 'finish_reason':finish}
                endpoint = Endpoint(self.storage)
                self.runtime.llm = endpoint
                result = await self._verify(self._done_checklist())
                self.assertNotEqual(result['action'], 'review_completed')
                self.assertEqual(result['items'][0]['state'], 'done')
                self.assertEqual(len(endpoint.requests), 1)
                self.checklists.cancel_open_by_user(self.owner)

    async def test_mixed_review_rereview_uses_fresh_evidence_and_can_reopen_pass(self) -> None:
        lid = self._done_checklist(2)
        self.llm.mode = 'fail'
        first = await self._verify(lid)
        self.assertEqual([i['state'] for i in first['items']], ['in_progress', 'verified'])
        self.checklists.update_items(self.owner, lid, [
            {'item_id':'C1','state':'done','comment':'FRESH_REPAIR_EVIDENCE_278: rebuilt and reran actual behavior.'},
        ])
        class Endpoint(_ReviewerTestLLM):
            async def chat_completions_once_full(inner, request: LLMRequest) -> dict[str, Any]:
                inner.requests.append(request)
                rows = json.loads(_ReviewerProtocolLLM._verdict_json(['C1','C2']))
                rows['verdicts'][1].update(verdict='fail', summary='New regression found.', next_step='Repair second behavior.')
                return {'text':json.dumps(rows)+'\n$$AGENT_PROGRESS: {"message":"Review finished","percent":100}', 'finish_reason':'stop'}
        self.runtime.llm = endpoint = Endpoint(self.storage)
        second = await self._verify(lid)
        self.assertNotEqual(second['review_agent_id'], first['review_agent_id'])
        self.assertEqual(second['review_cycle'], 2)
        self.assertEqual([i['state'] for i in second['items']], ['verified', 'in_progress'])
        marker = json.loads(self.agents.load_agent(second['review_agent_id'])['context'].split('\n',1)[1])
        self.assertIn('FRESH_REPAIR_EVIDENCE_278', Path(marker['handoff_path']).read_text())
        self.assertEqual(self.agents.load_agent(second['review_agent_id'])['status'], 'succeeded')
        self.assertEqual(second['review_result'], 'failed')

    async def test_parser_failure_preserves_prior_verified_and_current_done(self) -> None:
        lid = self._done_checklist(2)
        self.llm.mode = 'fail'
        await self._verify(lid)
        self.checklists.update_items(self.owner, lid, [{'item_id':'C1','state':'done','comment':'Repaired with new proof.'}])
        self.llm.mode = 'malformed'
        result = await self._verify(lid)
        self.assertEqual(result['action'], 'review_error')
        self.assertEqual([i['state'] for i in result['items']], ['done','verified'])
        self.assertEqual(result['lifecycle'], velox.CHECKLIST_LIFECYCLE_OPEN)

    async def test_deleting_owner_while_reviewer_runs_cannot_revive_parent(self) -> None:
        lid = self._done_checklist()
        self.llm.mode = 'gate'
        self.llm.entered = asyncio.Event()
        self.llm.release = asyncio.Event()
        pending = asyncio.create_task(self._verify(lid))
        await asyncio.wait_for(self.llm.entered.wait(), 2)
        self.chats.delete_chat(velox.APP_SCOPE_ID, self.chat_id)
        self.llm.release.set()
        result = await asyncio.wait_for(pending, 2)
        self.assertEqual(result['action'], 'review_error')
        self.assertTrue(result['owner_deleted'])
        self.assertFalse(self.paths.chat_dir(self.chat_id).exists())


class ReviewCommitAndDeletionRecoveryTests(_DataRootsIsolatedTestMixin, unittest.TestCase):
    setUp = ChecklistTransitionTests.setUp
    done = ChecklistTransitionTests.done

    def test_late_old_cycle_error_cannot_overwrite_new_review(self) -> None:
        self.done()
        self.manager.prepare_verification(self.owner, self.lid)
        velox._set_checklist_review_state(self.manager, self.owner, self.lid, velox.REVIEW_ERROR, review_cycle=1, error='First attempt failed.')
        self.manager.prepare_verification(self.owner, self.lid)
        before = self.manager.status(self.owner, self.lid)
        with self.assertRaises(ValueError):
            velox._set_checklist_review_state(self.manager, self.owner, self.lid, velox.REVIEW_ERROR, review_cycle=1, error='Late error.')
        self.assertEqual(self.manager.status(self.owner, self.lid), before)

    def test_postcommit_error_cannot_relabel_completed_review(self) -> None:
        self.done()
        self.manager.prepare_verification(self.owner, self.lid)
        self.manager.apply_review(self.owner, self.lid, [
            {'item_id':'C1','verdict':'pass','comment':'Independently checked first.'},
            {'item_id':'C2','verdict':'pass','comment':'Independently checked second.'},
        ], review_cycle=1)
        before = self.manager.status(self.owner, self.lid)
        velox._set_checklist_review_state(self.manager, self.owner, self.lid, velox.REVIEW_ERROR, review_cycle=1, error='Late export error.')
        self.assertEqual(self.manager.status(self.owner, self.lid), before)

    def test_temporary_cleanup_failure_does_not_mask_successful_replace(self) -> None:
        target = self.manager._owner_dir(self.owner) / 'atomic_probe.json'
        for writer in (velox._write_checklist_json, velox._write_expert_state_json):
            with self.subTest(writer=writer.__name__):
                with mock.patch.object(Path, 'unlink', side_effect=PermissionError('temporary cleanup denied')):
                    writer(target, {'committed':True})
                self.assertEqual(json.loads(target.read_text()), {'committed':True})

    def test_failed_review_card_never_claims_all_items_passed(self) -> None:
        text = velox.Panels._checklist_review_card_markdown({'name':'Acceptance','review_result':'failed','failed_rows':[]})
        self.assertIn('FAILED', text)
        self.assertNotIn('| All items | Passed |', text)

    def test_startup_skips_record_deleted_after_chat_enumeration(self) -> None:
        doomed = self.chats.create_chat('Doomed')
        doomed_id = str(doomed['chat_id'])
        self.storage.write_app_state({'active_chat_id':doomed_id})
        original = self.chats.list_chats
        def stale_listing(*args: Any, **kwargs: Any) -> list[dict[str, Any]]:
            rows = original(*args, **kwargs)
            shutil.rmtree(self.storage.paths.chat_dir(doomed_id))
            return rows
        app = velox.VeloxApp.__new__(velox.VeloxApp)
        app.storage, app.chats, app.ui_state = self.storage, self.chats, velox.UIState()
        app.google_calendar = SimpleNamespace(status=lambda: {})
        with mock.patch.object(self.chats, 'list_chats', side_effect=stale_listing):
            app.ensure_chat_if_empty()
        self.assertEqual(app.ui_state.active_chat_id, self.cid)

    def test_restart_retries_detached_directory_cleanup(self) -> None:
        with mock.patch.object(shutil, 'rmtree', side_effect=PermissionError('attachment busy')):
            self.chats.delete_chat(velox.APP_SCOPE_ID, self.cid)
        self.assertTrue(list(self.storage.paths.chats_dir().glob('.deleted-*')))
        velox._cleanup_detached_owners(self.storage)
        self.assertFalse(list(self.storage.paths.chats_dir().glob('.deleted-*')))
        self.assertFalse(self.storage.paths.chat_dir(self.cid).exists())


class _ScriptedLLM:
    def __init__(self, storage: Storage, rounds: list[list[LLMChunk]]):
        self.storage, self.rounds = storage, list(rounds)
        self.requests: list[LLMRequest] = []
    def resolve_endpoint(self, profile_id: str) -> dict[str, Any]:
        return copy.deepcopy(velox.endpoint_profile_ref(self.storage.load_config(), profile_id))
    async def chat_completions_stream(self, request: LLMRequest):
        self.requests.append(copy.deepcopy(request))
        if not self.rounds:
            raise AssertionError("Unexpected extra inference")
        for chunk in self.rounds.pop(0):
            yield chunk


class _AsyncRuntimeFixture(_WriterDataRootsIsolatedTestMixin, unittest.IsolatedAsyncioTestCase):
    def setUp(self) -> None:
        super().setUp()
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.paths, self.storage, self.chats = _make_test_chat_stack(Path(self.temp.name))
        self.cid = str(self.chats.create_chat("Runtime behavior")["chat_id"])
        self.eid = self.chats.get_chat_endpoint_profile_id(self.cid)
        self.tools = velox.ToolRegistry(self.storage)
        self.llm = velox.LLMClient(self.storage)
        self.runtime = velox.ChatRuntime(self.storage, self.chats, velox.ContextAssembler(self.paths), self.llm, self.tools)
        self.agents = velox.AgentStore(self.storage)
        self.aruntime = velox.AgentRuntime(self.storage, self.agents, self.chats, velox.ContextAssembler(self.paths), self.llm, self.tools)
    async def asyncTearDown(self) -> None:
        self.runtime.cancel_all()
        await self.aruntime.shutdown()
    def user(self, text: str = "Implement the requested behavior.") -> dict[str, Any]:
        turn = velox.make_turn(self.cid, "user", text, endpoint_profile_id=self.eid)
        self.chats.append_turn(velox.APP_SCOPE_ID, self.cid, turn)
        return turn
    def messages(self) -> list[dict[str, Any]]:
        return self.runtime._build_messages(velox.APP_SCOPE_ID, self.cid)
    def assertPrefix(self, old: list[Any], new: list[Any]) -> None:
        self.assertEqual(new[:len(old)], old)
        encode = lambda obj: json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        self.assertEqual(encode(old), encode(new[:len(old)]))
    def agent(self) -> dict[str, Any]:
        row = self.agents.create_agent(self.cid, "Run the exact assigned task.", endpoint_profile_id=self.eid)
        aid = str(row["agent_id"])
        self.agents.append_event(aid, "started", {"system_prompt": "Immutable system", "user_prompt": "Exact task"})
        return self.agents.load_agent(aid)
    async def run_chat_rounds(self, rounds: list[list[LLMChunk]]) -> _ScriptedLLM:
        fake = _ScriptedLLM(self.storage, rounds)
        self.runtime.llm = fake
        user = self.user("Exercise the requested tool behavior and report.")
        assistant = velox.make_turn(self.cid, "assistant", "", status="streaming", endpoint_profile_id=self.eid)
        self.chats.append_turn(velox.APP_SCOPE_ID, self.cid, assistant, mark_stale=False)
        await self.runtime._run_assistant_loop(velox.APP_SCOPE_ID, self.cid, str(assistant["turn_id"]), self.eid, user["text"], "Runtime replay")
        return fake


class PromptStabilityTests(_AsyncRuntimeFixture):
    def test_established_messages_are_exact_prefix_across_three_turns(self) -> None:
        self.user("First exact request: caf\u00e9 and literal JSON {\"v\": 1}.")
        first = copy.deepcopy(self.messages())
        self.chats.append_turn(velox.APP_SCOPE_ID, self.cid, velox.make_turn(self.cid, "assistant", "First answer."))
        self.user("Second request.")
        second = copy.deepcopy(self.messages())
        self.assertPrefix(first, second)
        self.user("Third request.")
        self.assertPrefix(second, self.messages())

    def test_endpoint_addon_is_frozen_in_both_wire_transports(self) -> None:
        cfg = self.storage.load_config()
        velox.endpoint_profile_ref(cfg, self.eid)["system_prompt_addon"] = "Original endpoint contract."
        self.storage.write_config(cfg)
        self.user("First request")
        old = copy.deepcopy(self.messages())
        request = velox.LLMRequest(velox.APP_SCOPE_ID, self.eid, old, native_tools=self.tools.build_openai_chat_completion_tools(velox.APP_SCOPE_ID, self.cid))
        # Payload is returned as the third item (bytes); parse it instead of relying on tuple labels.
        old_cc = json.loads(self.llm._chat_payload_and_headers(request, stream=False)[2])
        old_rsp = json.loads(self.llm._responses_payload_and_headers(request, stream=False)[2])
        cfg = self.storage.load_config()
        velox.endpoint_profile_ref(cfg, self.eid)["system_prompt_addon"] = "Late endpoint contract MUST NOT REWRITE PREFIX."
        self.storage.write_config(cfg)
        self.user("Second request")
        new = self.messages()
        self.assertPrefix(old, new)
        new_request = velox.LLMRequest(velox.APP_SCOPE_ID, self.eid, new, native_tools=request.native_tools)
        new_cc = json.loads(self.llm._chat_payload_and_headers(new_request, stream=False)[2])
        new_rsp = json.loads(self.llm._responses_payload_and_headers(new_request, stream=False)[2])
        self.assertPrefix(old_cc["messages"], new_cc["messages"])
        self.assertPrefix(old_rsp["input"], new_rsp["input"])
        self.assertEqual(old_rsp.get("instructions"), new_rsp.get("instructions"))
        self.assertEqual(new_cc["messages"][0]["content"].count("Original endpoint contract."), 1)
        self.assertNotIn("Late endpoint contract", json.dumps(new_cc))

    def test_adding_first_endpoint_addon_late_cannot_change_prefix(self) -> None:
        self.user(); old = copy.deepcopy(self.messages())
        cfg = self.storage.load_config(); velox.endpoint_profile_ref(cfg, self.eid)["system_prompt_addon"] = "late addon"
        self.storage.write_config(cfg)
        prepared = velox.prepend_endpoint_system_prompt_addon(old, self.llm.resolve_endpoint(self.eid))
        self.assertEqual(prepared, old)

    def test_failed_initial_snapshot_write_blocks_inference(self) -> None:
        self.user()
        with mock.patch.object(self.chats, "update_turn", side_effect=OSError("snapshot disk full")):
            with self.assertRaisesRegex(OSError, "snapshot disk full"):
                self.messages()
        self.assertFalse(any(row.get("system_prompt_snapshot") for row in self.chats.load_turns(velox.APP_SCOPE_ID, self.cid)))

    def test_missing_initial_turn_commit_is_not_a_successful_freeze(self) -> None:
        self.user()
        with mock.patch.object(self.chats, "update_turn", return_value=False):
            with self.assertRaisesRegex(RuntimeError, "could not be committed"):
                self.messages()

    async def test_concurrent_freezes_use_one_durable_snapshot(self) -> None:
        self.user(); turns = self.chats.load_turns(velox.APP_SCOPE_ID, self.cid)
        first, second = await asyncio.gather(*(
            asyncio.to_thread(self.runtime._stable_chat_system_prompt, velox.APP_SCOPE_ID, self.cid, turns, candidate)
            for candidate in ("Prompt A", "Prompt B")
        ))
        self.assertEqual(first, second)
        self.assertIn(first, {"Prompt A", "Prompt B"})
        self.assertEqual(self.chats.load_turns(velox.APP_SCOPE_ID, self.cid)[0]["system_prompt_snapshot"], first)

    def test_restart_keeps_frozen_prompt_and_user_representation(self) -> None:
        self.user(); old = copy.deepcopy(self.messages())
        fresh_chats = velox.ChatStore(self.storage)
        self.runtime = velox.ChatRuntime(self.storage, fresh_chats, velox.ContextAssembler(self.paths), self.llm, self.tools)
        self.assertEqual(old, self.messages())

    def test_native_tool_order_is_registration_order_independent(self) -> None:
        self.user()
        old = self.tools.build_openai_chat_completion_tools(velox.APP_SCOPE_ID, self.cid)
        self.tools.tools = dict(reversed(list(self.tools.tools.items())))
        new = self.tools.build_openai_chat_completion_tools(velox.APP_SCOPE_ID, self.cid)
        self.assertEqual(json.dumps(old, ensure_ascii=False), json.dumps(new, ensure_ascii=False))

    def test_schema_mapping_order_is_canonical_without_reordering_arrays(self) -> None:
        first = self.tools.build_openai_chat_completion_tools(velox.APP_SCOPE_ID, self.cid)
        definition = self.tools.tools["fs_write"]
        definition.parameters = dict(reversed(list(definition.parameters.items())))
        definition.parameters["properties"] = dict(reversed(list(definition.parameters["properties"].items())))
        second = self.tools.build_openai_chat_completion_tools(velox.APP_SCOPE_ID, self.cid)
        self.assertEqual(json.dumps(first), json.dumps(second))
        self.assertEqual(definition.parameters["required"], ["path", "content"])

    def test_user_preparation_is_frozen_but_explicit_user_edits_are_not_ignored(self) -> None:
        turn = self.user("Original user text")
        with mock.patch.object(self.runtime, "_build_user_content", return_value=[{"type": "text", "text": "Original pixels/text"}]):
            first = self.messages()
        with mock.patch.object(self.runtime, "_build_user_content", side_effect=AssertionError("old attachment was reread")):
            self.assertEqual(first, self.messages())
        self.chats.update_turn(velox.APP_SCOPE_ID, self.cid, turn["turn_id"], {"text": "Revised user text"})
        self.assertIn("Revised user text", json.dumps(self.messages()))

    async def test_live_native_tool_replay_is_exact_after_commit_and_new_turn(self) -> None:
        provider = _make_test_provider_call("fixture-time-call", "time_now", {})
        fake = await self.run_chat_rounds([
            [velox.LLMChunk(text="Inspecting time.", native_tool_calls=[provider], done=True, finish_reason="tool_calls")],
            [velox.LLMChunk(text="Reported the result.", done=True, finish_reason="stop")],
        ])
        self.assertEqual(len(fake.requests), 2)
        self.assertPrefix(fake.requests[0].messages, fake.requests[1].messages)
        self.assertPrefix(fake.requests[1].messages, self.messages())
        self.user("Continue with another task.")
        self.assertPrefix(fake.requests[1].messages, self.messages())
        stored = [row for row in self.chats.load_turns(velox.APP_SCOPE_ID, self.cid) if row.get("model_replay_messages")]
        self.assertEqual(len(stored), 1)
        tool_messages = [row for row in fake.requests[1].messages if row.get("role") == "tool"]
        self.assertEqual([row["tool_call_id"] for row in tool_messages], ["fixture-time-call"])

    async def test_empty_tool_protocol_correction_survives_restart(self) -> None:
        fake = await self.run_chat_rounds([
            [velox.LLMChunk(done=True, finish_reason="tool_calls")],
            [velox.LLMChunk(text="A normal answer.", done=True, finish_reason="stop")],
        ])
        self.assertEqual(len(fake.requests), 2)
