class ToolLifecycleTests(_AsyncRuntimeFixture):
    async def execute(self, name: str = "time_now", args: dict[str, Any] | None = None, **origin: Any) -> dict[str, Any]:
        return await self.tools.execute_tool_call(velox.APP_SCOPE_ID, {"name": name, "arguments": args or {}}, chat_id=self.cid, **origin)
    async def test_duplicate_execution_identity_runs_side_effect_once(self) -> None:
        calls = []
        self.tools.tools["time_now"].handler = lambda ctx, args: calls.append(ctx.tool_call_id) or {"value": 17}
        first = await self.execute(tool_call_id="once-only")
        second = await self.execute(tool_call_id="once-only")
        self.assertEqual(calls, ["once-only"]); self.assertEqual(first, second)
    async def test_inflight_duplicate_cannot_replace_active_execution(self) -> None:
        entered, release = asyncio.Event(), asyncio.Event()
        async def handler(ctx, args):
            entered.set(); await release.wait(); return {"done": True}
        self.tools.tools["time_now"].handler = handler
        first = asyncio.create_task(self.execute(tool_call_id="inflight"))
        await entered.wait()
        active = self.tools._active_tool_executions["inflight"]
        with self.assertRaisesRegex(RuntimeError, "already running"):
            await self.execute(tool_call_id="inflight")
        self.assertIs(self.tools._active_tool_executions["inflight"], active)
        release.set(); self.assertTrue((await first)["ok"])
    async def test_execution_identity_cannot_cross_chat_or_arguments(self) -> None:
        await self.execute(tool_call_id="owner-id")
        other = str(self.chats.create_chat("Other")["chat_id"])
        with self.assertRaises(PermissionError):
            await self.tools.execute_tool_call(velox.APP_SCOPE_ID, {"name": "time_now", "arguments": {}}, chat_id=other, tool_call_id="owner-id")
    async def test_evicted_result_does_not_make_an_identity_executable_again(self) -> None:
        await self.execute(tool_call_id="evicted")
        self.tools._recent_tool_records.clear()
        with self.assertRaisesRegex(RuntimeError, "already finished"):
            await self.execute(tool_call_id="evicted")
    async def test_cancel_during_preparation_never_starts_handler(self) -> None:
        entered, release = threading.Event(), threading.Event()
        started = []
        def prepare(*args):
            entered.set(); release.wait(3); return 10.0, lambda ctx, args: started.append(True)
        with mock.patch.object(self.tools, "_prepare_tool_execution", side_effect=prepare):
            task = asyncio.create_task(self.execute(tool_call_id="preparing"))
            self.assertTrue(await asyncio.to_thread(entered.wait, 2))
            self.assertTrue(self.tools.cancel_tool_call("preparing"))
            release.set()
            result = await asyncio.wait_for(task, 3)
        self.assertEqual(started, []); self.assertTrue(result["cancelled"])
    async def test_inner_timeout_preserves_its_actual_diagnostic(self) -> None:
        async def handler(ctx, args): raise TimeoutError("database socket deadline")
        self.tools.tools["time_now"].handler = handler
        result = await self.execute()
        self.assertIn("database socket deadline", result["error"])
        self.assertNotIn("execution budget", result["error"])
        self.assertTrue(result["timed_out"]); self.assertEqual(result["timeout_kind"], "handler")
