    async def test_dependent_tool_batch_executes_in_provider_order(self) -> None:
        path = self.paths.chat_workspace_dir(self.cid) / "ordered.txt"
        calls = [_make_test_provider_call("write-first", "fs_write", {"path": str(path), "content": "exact bytes"}), _make_test_provider_call("read-second", "fs_read", {"path": str(path)})]
        fake = await self.run_chat_rounds([[velox.LLMChunk(native_tool_calls=calls, done=True, finish_reason="tool_calls")], [velox.LLMChunk(text="Completed.", done=True, finish_reason="stop")]])
        outputs = [message for message in fake.requests[-1].messages if message.get("role") == "tool"]
        self.assertEqual([row["tool_call_id"] for row in outputs], ["write-first", "read-second"])
        self.assertIn("exact bytes", outputs[1]["content"])
