        calls = [{"name": "web_search", "arguments": {}}, {"name": "web_fetch", "arguments": {"url": "https://first.invalid"}}, {"name": "web_fetch", "arguments": {"url": "https://second.invalid"}}, {"name": "fs_read", "arguments": {}}]
        selected, meta = velox.serialize_web_page_result_batch(calls)
        self.assertEqual([row["name"] for row in selected], ["web_search", "web_fetch"])
        self.assertEqual(meta, 2)


