class ProcessAndOwnershipTests(_AsyncRuntimeFixture):
    async def test_cancelled_captured_process_does_not_write_after_cancellation(self) -> None:
        marker = self.paths.chat_workspace_dir(self.cid) / "late.txt"
        ctx = velox.ToolContext(velox.APP_SCOPE_ID, chat_id=self.cid, cancel_event=threading.Event())
        script = f"import time; from pathlib import Path; print('started',flush=True); time.sleep(1); Path({str(marker)!r}).write_text('late')"
        task = asyncio.create_task(velox.run_cancellable_subprocess(ctx, [sys.executable, "-c", script], cwd=marker.parent, timeout_seconds=4, shell=False))
        await asyncio.sleep(0.15); ctx.cancel_event.set()
        with self.assertRaises(velox.ToolCancelledError): await asyncio.wait_for(task, 3)
        await asyncio.sleep(1.1); self.assertFalse(marker.exists())
    async def test_timeout_reaps_child_after_parent_exit(self) -> None:
        if os.name == "nt":
            # Process-group implementation is POSIX-specific; Windows branch is
            # exercised deterministically by the taskkill failure test below.
            self.assertTrue(callable(velox.terminate_subprocess_tree)); return
        pidfile = self.paths.chat_workspace_dir(self.cid) / "child.pid"
        child = f"import signal,time,os; from pathlib import Path; signal.signal(signal.SIGTERM, signal.SIG_IGN); Path({str(pidfile)!r}).write_text(str(os.getpid())); time.sleep(30)"
        parent = f"import subprocess,sys; subprocess.Popen([sys.executable,'-S','-c',{child!r}])"
        ctx = velox.ToolContext(velox.APP_SCOPE_ID, chat_id=self.cid, cancel_event=threading.Event())
        with self.assertRaises(subprocess.TimeoutExpired):
            await asyncio.wait_for(velox.run_cancellable_subprocess(ctx, [sys.executable, "-S", "-c", parent], cwd=pidfile.parent, timeout_seconds=2.0, shell=False), 6)
        pid = int(pidfile.read_text())
        status = Path(f"/proc/{pid}/stat")
        self.assertTrue(not status.exists() or status.read_text().split()[2] == "Z", "surviving grandchild kept the output pipe open")
    def test_windows_taskkill_failure_falls_back_to_direct_kill(self) -> None:
        process = mock.Mock(pid=321)
        with mock.patch(f"{velox.__name__}.os.name", "nt"), mock.patch(f"{velox.__name__}.subprocess.run", return_value=SimpleNamespace(returncode=1)):
            velox.terminate_subprocess_tree(process)
        process.kill.assert_called_once()
    def test_cmd_semicolon_validation_preserves_quoted_or_escaped_literals(self) -> None:
        velox.validate_shell_command_for_platform('echo "a;b" ^; literal', windows=True)
        with self.assertRaisesRegex(ValueError, "cmd.exe"):
            velox.validate_shell_command_for_platform("build; echo $?", windows=True)
    def test_screenshot_suffix_rewrite_cannot_follow_outside_symlink(self) -> None:
        root = self.paths.chat_workspace_dir(self.cid)
        outside = Path(self.temp.name) / "outside.png"; outside.write_bytes(b"not overwritten")
        _create_fixture_symlink(root / "capture.png", outside)
        with self.assertRaises((PermissionError, ValueError)):
            self.tools.browser_tools._playback_capture_path(self.cid, str(root / "capture.jpg"))
        self.assertEqual(outside.read_bytes(), b"not overwritten")

    def test_symlink_capability_guard_skips_only_winerror_1314(self) -> None:
        link = Path(self.temp.name) / "priv.png"
        outside = Path(self.temp.name) / "target.png"
