    def test_huge_error_truncation_keeps_identity_status_and_numeric_exit(self) -> None:
        result = {"ok": False, "status": "failed", "tool_call_id": "stable-execution", "tool_name": "shell_exec",
                  "error": "Very long failure. " * 10000, "input": {"command": "x" * 10000},
                  "result": {"returncode": 19, "stdout": "s" * 100000, "stderr": "Final error. " * 10000}}
        with mock.patch(f"{velox.__name__}.tool_setting_int", return_value=1200):
            text = self.runtime._tool_result_payload_text(result)
        payload = json.loads(text)
        self.assertLessEqual(len(text), 1200)
        self.assertEqual(payload["tool_call_id"], "stable-execution")
        self.assertFalse(payload["ok"])
        self.assertEqual(payload["result"]["returncode"], 19)
        self.assertTrue(payload["truncation"]["truncated"])

    def _handoff_result(self, path: Path, execution_id: str) -> dict[str, Any]:
        return {"ok": True, "tool_call_id": execution_id, "tool_name": "image_analyze", "result": {
            velox.CURRENT_CONTEXT_VISION_RESULT_KEY: {"schema": velox.CURRENT_CONTEXT_VISION_HANDOFF_SCHEMA,
                "absolute_path": str(path), "mime": "image/png", "prompt": "Inspect actual pixels", "tool_name": "image_analyze", "tool_call_id": execution_id}}}

    def test_real_image_handoffs_append_until_budget_and_delivery_is_idempotent(self) -> None:
        endpoint = self.llm.resolve_endpoint(self.eid)
        messages = [{"role": "system", "content": "immutable"}]
        path = self.paths.chat_workspace_dir(self.cid) / "pixels.png"
        path.write_bytes(base64.b64decode("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aD1sAAAAASUVORK5CYII="))
        one = self._handoff_result(path, "vision-one")
        message, _ = velox.build_current_context_vision_message(messages, [one], endpoint)
        self.assertIsNotNone(message); messages.append(message)
        exact = copy.deepcopy(messages)
        path.write_bytes(path.read_bytes() + b"changed-after-first-analysis")
        two = self._handoff_result(path, "vision-two")
        next_message, _ = velox.build_current_context_vision_message(messages, [two], endpoint)
        self.assertIsNotNone(next_message); messages.append(next_message)
        self.assertPrefix(exact, messages)
        self.assertNotEqual(messages[-1]["content"][0], messages[-2]["content"][0])
        path.unlink()
        duplicate, summary = velox.build_current_context_vision_message(messages, [two], endpoint)
        self.assertIsNone(duplicate); self.assertTrue(summary["already_committed"])

    async def test_chat_replay_freezes_actual_image_bytes_after_file_disappears(self) -> None:
        path = self.paths.chat_workspace_dir(self.cid) / "frozen.png"
        path.write_bytes(base64.b64decode("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aD1sAAAAASUVORK5CYII="))
        async def handler(ctx: ToolContext, _args: dict[str, Any]) -> dict[str, Any]:
            return self._handoff_result(path, str(ctx.tool_call_id))["result"]
        native = _make_test_provider_call("image-provider", "image_analyze", {"path": str(path), "prompt": "Inspect"})
        with mock.patch.object(self.tools, "_prepare_tool_execution", return_value=(2.0, handler)):
            fake = await self.run_chat_rounds([[velox.LLMChunk(native_tool_calls=[native], done=True, finish_reason="tool_calls")], [velox.LLMChunk(text="Reviewed pixels.", done=True, finish_reason="stop")]])
        exact = copy.deepcopy(fake.requests[1].messages)
        self.assertEqual(velox.message_image_input_count(exact), 1)
        path.unlink(); self.user("Continue after the original capture was removed.")
        self.assertPrefix(exact, self.messages())

    def _pending(self, name: str = "time_now", identifier: str = "provider-once", args: dict[str, Any] | None = None) -> dict[str, Any]:
        args = args or {}
        call = {"name": name, "arguments": args, "provider_tool_call_id": identifier,
                "provider_tool_call": _make_test_provider_call(identifier, name, args)}
        return self.aruntime._agent_pending_tool_record(call, 1)[0]

    async def test_agent_cancelled_tool_does_not_consume_failure_budget(self) -> None:
        agent = self.agent(); aid = str(agent["agent_id"]); pending = self._pending()
        self.agents.update_agent(aid, {"pending_tool_call": pending, "tool_failure_count": 5})
        messages = [{"role": "system", "content": "Immutable system"}, {"role": "user", "content": "Exact task"},
                    {"role": "assistant", "content": "", "tool_calls": [pending["provider_tool_call"]]}]
        async def cancelled(_ctx: ToolContext, _args: dict[str, Any]) -> dict[str, Any]:
            raise velox.ToolCancelledError("User cancelled this one tool")
        with mock.patch.object(self.tools, "_prepare_tool_execution", return_value=(2.0, cancelled)), mock.patch.object(self.aruntime, "_maybe_compact_agent_context", new=mock.AsyncMock(return_value=False)):
            ok, _ = await self.aruntime._execute_pending_tool(aid, self.agents.load_agent(aid), messages)
        self.assertTrue(ok); saved = self.agents.load_agent(aid)
        self.assertEqual(saved["tool_failure_count"], 5)
        self.assertEqual(saved["tool_call_count"], 1)
        self.assertTrue(json.loads(messages[-1]["content"])["cancelled"])

    async def test_serial_pending_recovery_after_result_event_has_one_result_and_count(self) -> None:
        agent = self.agent(); aid = str(agent["agent_id"]); pending = self._pending()
        self.agents.update_agent(aid, {"pending_tool_call": pending})
        self.agents.append_event(aid, "llm_output", {"text": "", "native_tool_calls": [pending["provider_tool_call"]], "iteration": 1})
        messages, _ = self.aruntime._conversation_from_transcript(self.agents.load_agent(aid))
        original = self.agents.update_agent
        def interrupted(target: str, patch: dict[str, Any]) -> dict[str, Any]:
            if "pending_tool_call" in patch and patch["pending_tool_call"] is None:
                raise OSError("simulated crash at final pending commit")
            return original(target, patch)
        handler = mock.AsyncMock(return_value={"actual": "side effect once"})
        with mock.patch.object(self.tools, "_prepare_tool_execution", return_value=(2.0, handler)), mock.patch.object(self.aruntime, "_maybe_compact_agent_context", new=mock.AsyncMock(return_value=False)):
            with mock.patch.object(self.agents, "update_agent", side_effect=interrupted):
                with self.assertRaisesRegex(OSError, "simulated crash"):
                    await self.aruntime._execute_pending_tool(aid, self.agents.load_agent(aid), messages)
            restored, _ = self.aruntime._conversation_from_transcript(self.agents.load_agent(aid))
            await self.aruntime._execute_pending_tool(aid, self.agents.load_agent(aid), restored)
        self.assertEqual(handler.await_count, 1)
        self.assertEqual(len([m for m in restored if m.get("role") == "tool"]), 1)
        self.assertEqual(len([e for e in self.agents.load_transcript(aid) if e.get("kind") == "tool_result"]), 1)
        self.assertEqual(self.agents.load_agent(aid)["tool_call_count"], 1)

    async def test_parallel_image_recovery_replays_once_and_preserves_all_visual_results(self) -> None:
        agent = self.agent(); aid = str(agent["agent_id"])
        paths = [self.paths.chat_workspace_dir(self.cid) / f"frame-{i}.png" for i in range(2)]
        for path in paths: path.write_bytes(base64.b64decode("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aD1sAAAAASUVORK5CYII="))
        pending = [self._pending("image_analyze", f"image-{i}", {"path": str(path), "prompt": "Inspect"}) for i, path in enumerate(paths)]
        self.agents.update_agent(aid, {"pending_tool_call": {"parallel_image_batch": True, "calls": pending}})
        self.agents.append_event(aid, "llm_output", {"text": "", "native_tool_calls": [p["provider_tool_call"] for p in pending], "iteration": 1})
        messages, _ = self.aruntime._conversation_from_transcript(self.agents.load_agent(aid))
        executed = []
        async def handler(ctx: ToolContext, args: dict[str, Any]) -> dict[str, Any]:
            executed.append(ctx.tool_call_id)
            return self._handoff_result(Path(args["path"]), str(ctx.tool_call_id))["result"]
        checks = 0
        async def interrupt(*_args: Any, **_kwargs: Any) -> bool:
            nonlocal checks
            checks += 1
            if checks == 2: raise OSError("interrupt after first delivered image result")
            return False
        with mock.patch.object(self.tools, "_prepare_tool_execution", return_value=(2.0, handler)):
            with mock.patch.object(self.aruntime, "_maybe_compact_agent_context", side_effect=interrupt):
                with self.assertRaisesRegex(OSError, "interrupt after first"):
                    await self.aruntime._execute_pending_tool(aid, self.agents.load_agent(aid), messages)
            current = self.agents.load_agent(aid)
            self.assertIsInstance(current["pending_tool_call"], dict)
            self.assertEqual(current["tool_call_count"], 0)
            restored, _ = self.aruntime._conversation_from_transcript(current)
            with mock.patch.object(self.aruntime, "_maybe_compact_agent_context", new=mock.AsyncMock(return_value=False)):
                await self.aruntime._execute_pending_tool(aid, current, restored)
        self.assertEqual(len(executed), 2)
        self.assertEqual(len([m for m in restored if m.get("role") == "tool"]), 2)
        self.assertEqual(velox.message_image_input_count(restored), 2)
        current = self.agents.load_agent(aid)
        self.assertEqual(current["tool_call_count"], 2)
        self.assertIsNone(current["pending_tool_call"])

    async def test_agent_endpoint_addon_survives_actual_start_restart_and_settings_change(self) -> None:
        config = self.storage.load_config(); velox.endpoint_profile_ref(config, self.eid)["system_prompt_addon"] = "Immutable Agent addon"
        self.storage.write_config(config)
        agent = self.agents.create_agent(self.cid, "Answer once")
        aid = str(agent["agent_id"])
        fake = SimpleNamespace(chat_completions_once_full=mock.AsyncMock(return_value={"text": 'Done.\n$$AGENT_PROGRESS: {"message":"Done","percent":100}', "usage": {}, "finish_reason": "stop"}))
        self.aruntime.llm = fake
        await self.aruntime._run_agent(aid)
        saved = self.agents.load_agent(aid)
        self.assertEqual(saved["status"], "succeeded")
        first, _ = self.aruntime._conversation_from_transcript(saved)
        config = self.storage.load_config(); velox.endpoint_profile_ref(config, self.eid)["system_prompt_addon"] = "Late replacement forbidden"
        self.storage.write_config(config)
        second, _ = self.aruntime._conversation_from_transcript(saved)
        self.assertEqual(first, second)
        wire = json.loads(self.llm._chat_payload_and_headers(velox.LLMRequest(velox.APP_SCOPE_ID, self.eid, second), stream=False)[2])
        self.assertIn("Immutable Agent addon", wire["messages"][0]["content"])
        self.assertNotIn("Late replacement forbidden", json.dumps(wire))

    def _long_compaction_history(self) -> list[dict[str, Any]]:
        return [{"role": "system", "content": "Immutable system"}, {"role": "user", "content": "Exact task"},
                *[{"role": "assistant", "content": f"Observed intermediate claim {i}. " + "background " * 200} for i in range(24)],
                {"role": "user", "content": "Newest exact task with <think>literal user source</think>"},
                {"role": "assistant", "content": "Newest visible note"}]

    async def test_chat_truncated_or_exceptional_summary_never_commits_partial_claims(self) -> None:
        self.user()
        for finish in ("length", "cancelled", "exception"):
            with self.subTest(finish=finish):
                placeholder = velox.make_turn(self.cid, "assistant", "", status="streaming")
                self.chats.append_turn(velox.APP_SCOPE_ID, self.cid, placeholder, mark_stale=False)
                async def stream(_request: LLMRequest):
                    yield velox.LLMChunk(text="UNCOMMITTED_OUTPUT_SENTINEL observed claim. " * 100)
                    if finish == "exception": raise OSError("stream ended abruptly")
                    yield velox.LLMChunk(done=True, finish_reason=finish)
                self.runtime.llm = SimpleNamespace(resolve_endpoint=self.llm.resolve_endpoint, chat_completions_stream=stream)
                original = self._long_compaction_history()
                compacted, _turn_id, changed = await self.runtime._maybe_compact_chat_context(velox.APP_SCOPE_ID, self.cid, self.eid, original, str(placeholder["turn_id"]), force=True, native_tools=[])
                self.assertTrue(changed)
                self.assertNotIn("UNCOMMITTED_OUTPUT_SENTINEL", json.dumps(compacted))
                self.assertIn(original[-2], compacted)
                self.assertTrue(any(velox.TASK_MEMORY_HEADER in str(row.get("content")) for row in compacted))

    async def test_agent_truncated_or_failed_summary_uses_factual_ledger(self) -> None:
        for finish in ("length", "failed", "cancelled"):
            with self.subTest(finish=finish):
                agent = self.agent(); aid = str(agent["agent_id"])
                self.agents.update_agent(aid, {"context_window_tokens": 8192, "max_output_tokens": 1024})
                self.aruntime.llm = SimpleNamespace(chat_completions_once_full=mock.AsyncMock(return_value={"text": "UNCOMMITTED_AGENT_SENTINEL asserted fact. " * 100, "usage": {}, "finish_reason": finish}))
                messages = self._long_compaction_history(); latest = copy.deepcopy(messages[-2])
                changed = await self.aruntime._maybe_compact_agent_context(aid, messages, force=True, native_tools=[])
                self.assertTrue(changed); self.assertNotIn("UNCOMMITTED_AGENT_SENTINEL", json.dumps(messages))
                self.assertIn(latest, messages)
                events = [e for e in self.agents.load_transcript(aid) if e.get("kind") == "context_compacted"]
                self.assertEqual(events[-1]["data"]["summary_strategy"], "structured_operational_ledger")

    async def test_cancelled_chat_compaction_leaves_original_request_untouched(self) -> None:
        self.user(); placeholder = velox.make_turn(self.cid, "assistant", "", status="streaming")
        self.chats.append_turn(velox.APP_SCOPE_ID, self.cid, placeholder, mark_stale=False)
        async def stream(_request: LLMRequest):
            yield velox.LLMChunk(text="Partial summary must not commit. " * 80)
            raise asyncio.CancelledError()
        self.runtime.llm = SimpleNamespace(resolve_endpoint=self.llm.resolve_endpoint, chat_completions_stream=stream)
        messages = self._long_compaction_history(); exact = copy.deepcopy(messages)
        with self.assertRaises(asyncio.CancelledError):
            await self.runtime._maybe_compact_chat_context(velox.APP_SCOPE_ID, self.cid, self.eid, messages, str(placeholder["turn_id"]), force=True, native_tools=[])
        self.assertEqual(messages, exact)

    async def test_tool_limit_keeps_executed_batch_and_result_for_next_user_turn(self) -> None:
        native = _make_test_provider_call("limited-call", "time_now", {})
        with mock.patch(f"{velox.__name__}.chat_tool_iteration_limit_from_config", return_value=1):
            await self.run_chat_rounds([[velox.LLMChunk(native_tool_calls=[native], done=True, finish_reason="tool_calls")]])
        self.user("Inspect the result without running it again.")
