    async def test_cancellation_rechecked_after_waiting_for_checklist_lock(self) -> None:
        self.create()
        event = threading.Event()
        entered = threading.Event()
        ctx = velox.ToolContext(velox.APP_SCOPE_ID, chat_id=self.cid, cancel_event=event)
        def blocked() -> Any:
            entered.set()
            return self.tools.tool_checklist_create(ctx, {"name": "Late", "items": ["Late"]})
        with velox._CHECKLIST_LOCK:
            job = asyncio.create_task(asyncio.to_thread(blocked))
            self.assertTrue(await asyncio.to_thread(entered.wait, 2.0))
            event.set()
        with self.assertRaises(velox.ToolCancelledError):
            await job
        self.assertEqual(len(self.manager.load_collection(self.owner)["checklists"]), 1)

    async def test_stop_returns_without_waiting_for_checklist_lock(self) -> None:
        self.create()
        entered, release = threading.Event(), threading.Event()
        def hold() -> None:
            with velox._CHECKLIST_LOCK:
                entered.set()
                release.wait(5.0)
        holder = asyncio.create_task(asyncio.to_thread(hold))
        self.assertTrue(await asyncio.to_thread(entered.wait, 2.0))
        try:
            self.assertTrue(self.runtime.cancel(self.cid))
            # Reaching here before release proves no synchronous lock wait.
            self.assertFalse(release.is_set())
            self.assertTrue(self.runtime.is_running(self.cid))
            await asyncio.sleep(0)
            self.assertFalse(self.runtime._checklist_stop_tasks[self.cid].done())
        finally:
            release.set()
            await holder
        await self.runtime.wait_for_user_stops()
        self.assertIsNone(self.manager.active(self.owner))

