    async def test_stop_context_is_chronological_deduplicated_and_preserved(self) -> None:
        cid = self.create()
        self.runtime._prepare_cache_safe_application_context(velox.APP_SCOPE_ID, self.cid, self.eid, include_history_snapshot=True)
        before = copy.deepcopy(self.chats.load_turns(velox.APP_SCOPE_ID, self.cid))
        await self.stop()
        for _ in range(2):
            self.runtime._prepare_cache_safe_application_context(velox.APP_SCOPE_ID, self.cid, self.eid, include_history_snapshot=False)
        after = self.chats.load_turns(velox.APP_SCOPE_ID, self.cid)
        self.assertEqual(after[:len(before)], before)
        notices = [turn for turn in after if turn.get("application_context_kind") == velox.CHAT_APP_CONTEXT_STOP_KIND]
        self.assertEqual(len(notices), 1)
        self.assertIn("cancelled by user", notices[0]["text"])
        self.assertIn("not active work", notices[0]["text"])
        self.assertEqual(self.chats.chat_user_turn_count(velox.APP_SCOPE_ID, self.cid), 0)
        messages = [{"role": "system", "content": "Frozen"},
                    {"role": "user", "content": "Earlier task"},
                    {"role": "system", "content": notices[0]["text"]},
                    *[{"role": "assistant", "content": "Older history " * 100} for _ in range(12)],
                    {"role": "user", "content": "Fresh task"}]
        self.assertFalse(velox.chat_compaction_message_is_substantive_user_request({"role": "user", "content": notices[0]["text"]}))
        for level in (1, 2, 3):
            preserved = self.runtime._chat_compaction_preserved_indices(messages, pass_number=level)
            self.assertIn(2, preserved)
        self.assertStopped(cid)

