    async def test_line_range_large_skipped_line_is_bounded_and_limits_selected_line(self) -> None:
        path=Path(self.temp.name)/'one-big-line.txt'; path.write_bytes(b'x'*400000+b'\nsmall\n')
        seen=[]; original=velox._plain_open_with_retry
        class Reader:
            def __init__(self,fh: Any):self.fh=fh
            def __enter__(self) -> Any:return self
            def __exit__(self,*args: Any) -> None:self.fh.close()
            def read(self,size: int=-1) -> str:
                self_outer.assertGreater(size,0); self_outer.assertLessEqual(size,65536);seen.append(size);return self.fh.read(size)
            def fileno(self) -> int:return self.fh.fileno()
        self_outer=self
        with mock.patch(f'{velox.__name__}._plain_open_with_retry',side_effect=lambda *a,**k:Reader(original(*a,**k))):
            text,returned,total,_=velox.read_utf8_line_range(path,1,1,20)
        self.assertEqual((text,returned,total),('small\n',1,2)); self.assertGreater(len(seen),1)
        with self.assertRaisesRegex(ValueError,'File read chars limit'):velox.read_utf8_line_range(path,0,1,20)
        with self.assertRaisesRegex(ValueError,'beyond'):velox.read_utf8_line_range(path,3,1,20)

