                        method = self.llm.chat_completions_stream_full if stream else self.llm.chat_completions_once_full
                        with self.assertRaises(Exception) as caught:
                            await method(self.request(stream=stream))
                        self.assertTrue(getattr(caught.exception, 'endpoint_recovery_exhausted', False))
                        self.assertEqual(opened.call_count, 2)

