    async def test_cancel_during_retry_handoff_suppresses_next_http_request(self) -> None:
        self.configure()
        self.storage.update_config(lambda cfg: velox.endpoint_profile_ref(cfg, self.eid).update(error_recovery_delay_seconds=60))
        cancel = threading.Event()
        started = asyncio.Event()
        real_wait = self.llm._wait_for_endpoint_recovery
        async def wait(request: LLMRequest, *a: Any) -> None:
            started.set()
            await real_wait(request, *a)
        with mock.patch.object(self.llm, '_wait_for_endpoint_recovery', side_effect=wait), mock.patch.object(urllib.request, 'urlopen', side_effect=TimeoutError('timed out')) as opened:
            pending = asyncio.create_task(self.llm.chat_completions_once_full(self.request(cancel_event=cancel)))
            await asyncio.wait_for(started.wait(), 1)
            cancel.set()
            with self.assertRaises(asyncio.CancelledError):
                await pending
            self.assertEqual(opened.call_count, 1)

