    async def test_provider_heartbeat_does_not_extend_absolute_deadline(self) -> None:
        self.configure(retries=0)
        closed = threading.Event()
        class Trickle:
            headers = {'Content-Type': 'text/event-stream'}; status = 200
            def __enter__(self) -> Any: return self
            def __exit__(self, *a: Any) -> None: closed.set()
            def close(self) -> None: closed.set()
            def readline(self, _size: int) -> bytes:
                if closed.wait(.005): return b''
                return b': heartbeat\n\n'
        with self.fast_deadlines(), mock.patch.object(urllib.request, 'urlopen', return_value=Trickle()) as opened:
            with self.assertRaises(RuntimeError) as caught:
                await asyncio.wait_for(self.llm.chat_completions_stream_full(self.request()), 1)
            self.assertIn('deadline', str(caught.exception))
            self.assertEqual(opened.call_count, 1)
        self.assertTrue(await asyncio.to_thread(closed.wait, 1))

