    async def test_post_sleep_chat_retries_inference_without_executing_sleep_twice(self) -> None:
        cfg = self.storage.load_config()
        velox.endpoint_profile_ref(cfg, self.eid).update(rate_limit_enabled=False, error_recovery_attempts=1, timeout_seconds=900)
        self.storage.write_config(cfg)
        user = self.user('Wait for the external process, then report.')
        assistant = velox.make_turn(self.cid, 'assistant', '', status='streaming', endpoint_profile_id=self.eid)
        self.chats.append_turn(velox.APP_SCOPE_ID, self.cid, assistant, mark_stale=False)
        call = _make_test_provider_call('sleep-once', 'time_sleep', {'minutes': .003, 'message': 'Check the result'})
        first = json.dumps({'choices': [{'index': 0, 'message': {'role': 'assistant', 'content': '', 'tool_calls': [call]}, 'finish_reason': 'tool_calls'}]}).encode()
        final = TransportDeadlineTests.body('chat_completions')
        bodies, sleeps = [], []
        sleep_handler = self.tools.tools['time_sleep'].handler
        async def counted(ctx: ToolContext, args: dict[str, Any]) -> Any:
            sleeps.append(ctx.tool_call_id)
            return await sleep_handler(ctx, args)
        self.tools.tools['time_sleep'].handler = counted
        def opening(request: Any, **kw: Any) -> Any:
            bodies.append(request.data)
            if len(bodies) == 1: return _DeadlineResponse(first)
            if len(bodies) == 2: raise TimeoutError('stalled after sleep')
            if len(bodies) == 3: return _DeadlineResponse(final)
            raise AssertionError('unexpected extra inference')
        original_deadline = velox.LLMRequestDeadline
        with mock.patch(f'{velox.__name__}.LLMRequestDeadline', side_effect=lambda eid, budget: original_deadline(eid, .08)), mock.patch.object(urllib.request, 'urlopen', side_effect=opening):
            await asyncio.wait_for(self.runtime._run_assistant_loop(velox.APP_SCOPE_ID, self.cid, assistant['turn_id'], self.eid, user['text'], 'sleep recovery'), 5)
        self.assertEqual(len(sleeps), 1)
        self.assertEqual(len(bodies), 3)
        self.assertEqual(bodies[1], bodies[2])
        turns = self.chats.load_turns(velox.APP_SCOPE_ID, self.cid)
        self.assertEqual(len([c for t in turns for c in t.get('tool_calls', []) if c.get('tool_name') == 'time_sleep']), 1)
        self.assertIn('Resumed.', turns[-1]['text'])
        self.assertEqual(turns[-1]['status'], 'complete')

