        # The watchdog is allocated when the transport attempt starts, never at
        # task creation or at the beginning of a sleep/tool operation.
        now=[10000.0]
        with mock.patch.object(time,'monotonic',side_effect=lambda:now[0]),mock.patch.object(time,'time',side_effect=lambda:now[0]):
            first=velox.LLMRequestDeadline('first',900);first.observe(velox.LLMChunk(text='complete',done=True))
