# Checklist creation and reviewer integrity.
class _ChecklistRuntimeFixture(_WriterDataRootsIsolatedTestMixin, unittest.TestCase):
    def setUp(self) -> None:
        super().setUp()
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.paths, self.storage, self.chats = _make_test_chat_stack(Path(self.temp.name))
        self.chat_id = str(self.chats.create_chat("Automatic Checklist regressions")["chat_id"])
        self.owner = velox._chat_checklist_owner(self.chat_id)
        self.manager = velox.ChecklistStore(self.storage)
        self.agents = velox.AgentStore(self.storage)
        self.registry = velox.ToolRegistry(self.storage)
        self.context = velox.ToolContext(velox.APP_SCOPE_ID, chat_id=self.chat_id)

    def create(self, name: str = "Root", *, owner: Any = None, items: Any = None) -> dict[str, Any]:
        return self.manager.create(owner or self.owner, name=name, items=items or ["Deliver the tested behavior"])

    def done(self, checklist: dict[str, Any], *, owner: Any = None) -> None:
        self.manager.update_items(owner or self.owner, checklist["checklist_id"], [
            {"item_id": item["id"], "state": "done", "comment": "Built and exercised the current artifact."}
            for item in checklist["items"]
        ])

    def pass_review(self, checklist: dict[str, Any], *, owner: Any = None) -> dict[str, Any]:
        owner = owner or self.owner
        self.done(checklist, owner=owner)
        prepared = self.manager.prepare_verification(owner, checklist["checklist_id"])
        return self.manager.apply_review(owner, checklist["checklist_id"], [
            {"item_id": item["id"], "verdict": "pass", "comment": "Independently observed the intended outcome."}
            for item in checklist["items"]
        ], review_cycle=prepared["review_cycle"])

    def bytes(self) -> tuple[bytes, bytes]:
        paths = (self.manager._collection_path(self.owner), self.manager._history_path(self.owner))
        return tuple(path.read_bytes() if path.exists() else b"" for path in paths)

    def worker(self, subtype: str, *, assigned: str = "") -> tuple[dict[str, Any], dict[str, Any]]:
        metadata = {"subtype": subtype, "assigned_checklist_id": assigned}
        velox._validate_role_assignment(self.storage, (self.context,), {}, metadata)
        token = velox._PENDING_AGENT_ROLE.set(metadata)
        try:
            agent = self.agents.create_agent(self.chat_id, "Work the bounded assignment.")
        finally:
            velox._PENDING_AGENT_ROLE.reset(token)
        return agent, metadata


