class ReviewerIntegrityTests(_ChecklistRuntimeFixture):
    def test_no_unrequested_review_can_set_verified(self) -> None:
        root = self.create()
        self.done(root)
        before = self.bytes()
        with self.assertRaisesRegex(ValueError, "active requested review"):
            self.manager.apply_review(self.owner, root["checklist_id"], [{"item_id": "C1", "verdict": "pass", "comment": "Not requested"}])
        self.assertEqual(self.bytes(), before)

    def test_cancelled_or_errored_cycle_rejects_late_verdict_without_state_change(self) -> None:
        root = self.create()
        self.done(root)
        for status in (velox.REVIEW_CANCELLED, velox.REVIEW_ERROR):
            prepared = self.manager.prepare_verification(self.owner, root["checklist_id"])
            velox._set_checklist_review_state(self.manager, self.owner, root["checklist_id"], status, review_cycle=prepared["review_cycle"], error="Interrupted")
            before = self.bytes()
            with self.subTest(status=status), self.assertRaisesRegex(ValueError, "active requested review"):
                self.manager.apply_review(self.owner, root["checklist_id"], [{"item_id": "C1", "verdict": "pass", "comment": "Late"}], review_cycle=prepared["review_cycle"])
            self.assertEqual(self.bytes(), before)

    def test_terminal_review_cannot_be_restarted_by_status_callback(self) -> None:
        root = self.create()
        self.done(root)
        prepared = self.manager.prepare_verification(self.owner, root["checklist_id"])
        velox._set_checklist_review_state(self.manager, self.owner, root["checklist_id"], velox.REVIEW_CANCELLED, review_cycle=prepared["review_cycle"])
        before = self.bytes()
        velox._set_checklist_review_state(self.manager, self.owner, root["checklist_id"], velox.REVIEW_RUNNING, review_cycle=prepared["review_cycle"])
        self.assertEqual(self.bytes(), before)
        self.assertEqual(self.manager.prepare_verification(self.owner, root["checklist_id"])["review_cycle"], prepared["review_cycle"] + 1)

    def test_reviewing_root_cannot_acquire_new_child(self) -> None:
        root = self.create()
        self.done(root)
        self.manager.prepare_verification(self.owner, root["checklist_id"])
        before = self.bytes()
        with self.assertRaisesRegex(ValueError, "already active"):
            self.create("Too late")
        self.assertEqual(self.bytes(), before)


class ReviewerParsingTests(unittest.TestCase):
    def payload(self, verdict: str = "pass", summary: str = "Observed") -> str:
        return json.dumps({"verdicts": [{"requirement_id": "C1", "verdict": verdict, "summary": summary,
                                       "next_step": "Repair the behavior." if verdict == "fail" else ""}]})

    def parse(self, text: str) -> list[dict[str, str]]:
        return velox._parse_reviewer_result(text, {"requirements": [{"id": "C1"}]})

    def test_thinking_only_verdict_is_not_an_acceptance_result(self) -> None:
        for tag in ("think", "thinking", "reasoning"):
            with self.subTest(tag=tag), self.assertRaises(ValueError):
                self.parse(f"<{tag}>{self.payload()}</{tag}>\n$$AGENT_PROGRESS: {{\"message\":\"done\",\"percent\":100}}")

    def test_draft_pass_does_not_mask_visible_final_failure(self) -> None:
        result = self.parse("<think>Candidate: " + self.payload() + "</think>\n" + self.payload("fail", "Actual behavior missing"))
        self.assertEqual(result[0]["verdict"], "fail")
        self.assertEqual(result[0]["summary"], "Actual behavior missing")

    def test_malformed_reasoning_draft_does_not_invalidate_valid_final_verdict(self) -> None:
        result = self.parse('<think>Draft {"verdicts": invalid}</think>\n' + self.payload())
        self.assertEqual(result[0]["verdict"], "pass")

    def test_unclosed_reasoning_cannot_supply_terminal_verdict(self) -> None:
        with self.assertRaises(ValueError):
            self.parse("<think>Not finalized " + self.payload())

    def test_json_summary_preserves_literal_reasoning_tags(self) -> None:
        summary = 'The page literally renders <think>sample</think> and an unmatched <reasoning> label.'
        self.assertEqual(self.parse(self.payload(summary=summary))[0]["summary"], summary)

    def test_multiple_visible_verdicts_are_still_rejected(self) -> None:
        with self.assertRaisesRegex(ValueError, "exactly one"):
            self.parse("<think>Draft only</think>" + self.payload() + "\n" + self.payload("fail"))

    def test_extraction_requires_current_visible_verdict_not_reasoning(self) -> None:
        events = [{"kind": "llm_output", "data": {"raw_text": "<think>" + self.payload() + "</think>", "termination_category": "normal"}}]
        runtime = SimpleNamespace(agents=SimpleNamespace(load_transcript=lambda _id: events))
        with self.assertRaises(RuntimeError):
            velox._extract_reviewer_result(runtime, "reviewer", {})

    def test_recovery_carries_only_previous_visible_verdict_across_control_only_reply(self) -> None:
        valid = self.payload()
        events = [{"kind": "llm_output", "data": {"raw_text": valid, "termination_category": "normal"}},
                  {"kind": "reviewer_terminal_recovery", "data": {"attempt": 1}},
                  {"kind": "llm_output", "data": {"raw_text": '<think>Repair formatting only.</think>\n$$AGENT_PROGRESS: {"message":"done","percent":100}', "termination_category": "normal"}}]
        runtime = SimpleNamespace(agents=SimpleNamespace(load_transcript=lambda _id: events))
        self.assertEqual(velox._extract_reviewer_result(runtime, "reviewer", {}), valid)


class ReviewerLoopTests(unittest.IsolatedAsyncioTestCase):
    asyncSetUp = ReviewerAgentLoopTests.asyncSetUp
    asyncTearDown = ReviewerAgentLoopTests.asyncTearDown
    _verify = ReviewerAgentLoopTests._verify
    _done_checklist = ReviewerAgentLoopTests._done_checklist

    async def test_live_reviewer_draft_pass_and_final_fail_applies_only_failure(self) -> None:
        payload = ReviewerParsingTests().payload
        class Endpoint(_ReviewerTestLLM):
            async def chat_completions_once_full(inner, request: LLMRequest) -> dict[str, Any]:
                inner.requests.append(request)
                return {"text": '<think>' + payload() + '</think>\n' + payload('fail', 'Fresh artifact lacks required behavior') + '\n$$AGENT_PROGRESS: {"message":"Review completed","percent":100}', "finish_reason": "stop"}
        self.runtime.llm = endpoint = Endpoint(self.storage)
        result = await self._verify(self._done_checklist())
        self.assertEqual(result["action"], "review_completed")
        self.assertEqual(result["review_result"], "failed")
        self.assertEqual(result["items"][0]["state"], "in_progress")
        self.assertEqual(self.agents.load_agent(result["review_agent_id"])["status"], "succeeded")
        self.assertEqual(len(endpoint.requests), 1)

    async def test_live_thinking_only_verdict_fails_without_changing_items(self) -> None:
        payload = ReviewerParsingTests().payload
        class Endpoint(_ReviewerTestLLM):
            async def chat_completions_once_full(inner, request: LLMRequest) -> dict[str, Any]:
                inner.requests.append(request)
                return {"text": '<think>' + payload() + '</think>\n$$AGENT_PROGRESS: {"message":"Review completed","percent":100}', "finish_reason": "stop"}
        self.runtime.llm = endpoint = Endpoint(self.storage)
        result = await self._verify(self._done_checklist())
        self.assertEqual(result["action"], "review_error")
        self.assertEqual(result["items"][0]["state"], "done")
        self.assertEqual(len(endpoint.requests), 1)

    async def test_actual_reviewer_cannot_commit_after_cycle_is_invalidated(self) -> None:
        checklist_id = self._done_checklist()
        self.llm.mode = 'gate'
        self.llm.entered, self.llm.release = asyncio.Event(), asyncio.Event()
        pending = asyncio.create_task(self._verify(checklist_id))
        await asyncio.wait_for(self.llm.entered.wait(), 3)
        velox._set_checklist_review_state(self.checklists, self.owner, checklist_id, velox.REVIEW_CANCELLED, review_cycle=1, error='Review invalidated by owner')
        path = self.checklists._collection_path(self.owner)
        before = path.read_bytes()
        self.llm.release.set()
        result = await asyncio.wait_for(pending, 3)
        self.assertNotEqual(result["action"], "review_completed")
        self.assertEqual(path.read_bytes(), before)
        self.assertEqual(result["items"][0]["state"], "done")

    async def test_sequential_completed_lists_have_independent_cycles_and_reviewers(self) -> None:
        first=self._done_checklist(); first_result=await self._verify(first)
        before=self.checklists.status(self.owner,first,include_history=True)
        second=self._done_checklist(); second_result=await self._verify(second)
        self.assertEqual(first_result['action'],'review_completed'); self.assertEqual(second_result['action'],'review_completed')
        self.assertNotEqual(first_result['review_agent_id'],second_result['review_agent_id'])
        self.assertEqual(second_result['review_cycle'],1)
        self.assertEqual(self.checklists.status(self.owner,first,include_history=True),before)
        self.assertIsNone(self.checklists.active(self.owner))


