        class CancelDuringSummary(_ContextRecoveryLLM):
            async def chat_completions_stream(self, request: LLMRequest):
                if self.is_compaction(request):
                    if request.cancel_event:request.cancel_event.set()
                    raise asyncio.CancelledError('User stopped recovery')
                async for chunk in super().chat_completions_stream(request):yield chunk
        fake=CancelDuringSummary(self.storage);self.runtime.llm=fake
        for i in range(14):
            self.user(f'Old request {i} '+'x'*3000)
