class _ReviewerWaitFixture(_WriterDataRootsIsolatedTestMixin, unittest.IsolatedAsyncioTestCase):
    asyncSetUp = ReviewerAgentLoopTests.asyncSetUp
    asyncTearDown = ReviewerAgentLoopTests.asyncTearDown
    _done_checklist = ReviewerAgentLoopTests._done_checklist
    _verify = ReviewerAgentLoopTests._verify

    def context(self) -> Any:
        return SimpleNamespace(chat_id=self.chat_id, agent_id="", agent_task_run_id=0,
            endpoint_profile_id=self.chats.get_chat_endpoint_profile_id(self.chat_id), monitor_task_id="")

    def status(self, cid: str) -> dict[str, Any]:
        return self.checklists.status(self.owner, cid)

    def raw(self, cid: str) -> dict[str, Any]:
        return self.checklists._checklist(self.checklists.load_collection(self.owner), cid)

    def verdict(self, count: int = 1, *, fail_first: bool = False) -> str:
        rows = [{"requirement_id": f"C{i+1}", "verdict": "fail" if fail_first and i == 0 else "pass",
                 "summary": "Observed missing behavior" if fail_first and i == 0 else "Observed current behavior",
                 "next_step": "Repair the missing behavior" if fail_first and i == 0 else ""} for i in range(count)]
        return json.dumps({"verdicts": rows}) + '\n$$AGENT_PROGRESS: {"message":"Review complete","percent":100}'

    def detached(self, cid: str) -> tuple[str, int]:
        prepared = self.checklists.prepare_verification(self.owner, cid)
        checklist = self.raw(cid)
        state, package, _path = velox._make_checklist_review_package(self.registry, self.owner, checklist,
            endpoint_profile_id=self.context().endpoint_profile_id)
        payload = {"schema": f"checklist_reviewer_context.v{velox.SOURCE_REVISION}", "cycle": prepared["review_cycle"],
            "checklist_id": cid, "owner": self.owner, "requirement_ids": [item["id"] for item in state["requirements"]],
            "snapshot_fingerprint": checklist["review_snapshot_fingerprint"],
            "handoff_path": package["handoff_path"], "context_path": package["context_path"]}
        reviewer = self.agents.create_agent(self.chat_id,
            velox._build_reviewer_user_prompt(state, package, prepared["review_cycle"]),
            title="Detached reviewer", endpoint_profile_id=self.context().endpoint_profile_id,
            context=velox.EXPERT_MODE_REVIEW_AGENT_CONTEXT_MARKER + "\n" + json.dumps(payload))
        aid = reviewer["agent_id"]
        velox._set_checklist_review_state(self.checklists, self.owner, cid, velox.REVIEW_RUNNING,
            review_cycle=prepared["review_cycle"], agent_id=aid, event="review_started")
        return aid, prepared["review_cycle"]

    def terminal(self, aid: str, *, text: str | None = None, status: str = "succeeded", category: str = "normal") -> None:
        if text is not None:
            self.agents.append_event(aid, "llm_output", {"raw_text": text, "text": text, "termination_category": category})
        self.agents.update_agent(aid, {"status": status, "progress_message": "Agent ended",
                                      "failure_message": "Review crashed" if status == "failed" else ""})

    def finish(self, cid: str, aid: str, cycle: int) -> Any:
        return velox._finish_checklist_review(self.storage, self.owner, cid, aid, cycle)

    def event_count(self, cid: str, name: str) -> int:
        return sum(row.get("event") == name for row in self.raw(cid).get("history", []))

    async def gated(self, cid: str, *, via_registry: bool = False) -> asyncio.Task[Any]:
        self.llm.mode = "gate"
        self.llm.entered, self.llm.release = asyncio.Event(), asyncio.Event()
        coro = self._verify(cid) if via_registry else self.registry.tool_verify_checklist(self.context(), {"checklist_id": cid})
        pending = asyncio.create_task(coro)
        await asyncio.wait_for(self.llm.entered.wait(), timeout=5)
        return pending


class ReviewerWaitTests(_ReviewerWaitFixture):
    def test_reviewer_join_has_no_generic_tool_wall_clock_budget(self) -> None:
        self.assertIsNone(self.registry._timeout_for_tool("verify_checklist", {"checklist_id": "CL-test"}))
        self.assertEqual(self.registry._timeout_for_tool("shell_exec", {"timeout_minutes": 60}), 3605)
        self.assertEqual(self.registry._timeout_for_tool("python_exec", {"timeout_minutes": 60}), 3605)
        self.assertIsNotNone(self.registry._timeout_for_tool("fs_read", {}))

    async def test_slow_review_outlives_accelerated_old_outer_timeout(self) -> None:
        cid = self._done_checklist()
        original = self.registry._timeout_for_tool
        def accelerate(name: str, args: Any, **kw: Any) -> Any:
            timeout = original(name, args, **kw)
            return min(timeout, .04) if timeout is not None and name == "verify_checklist" else timeout
        with mock.patch.object(self.registry, "_timeout_for_tool", side_effect=accelerate):
            pending = await self.gated(cid, via_registry=True)
            try:
                await asyncio.sleep(.15)
                self.assertFalse(pending.done(), "The source must keep its Reviewer join, not return timeout and sleep/poll")
            finally:
                self.llm.release.set()
            result = await asyncio.wait_for(pending, 5)
        self.assertEqual(result["action"], "review_completed")
        self.assertEqual(result["review_result"], "passed")
        self.assertEqual(len(self.llm.requests), 1)
        self.assertEqual(self.event_count(cid, "review_completed"), 1)

    async def test_source_cancellation_requires_no_task_cancelling_api(self) -> None:
        # Faithful Python 3.10 Task surface for the cancellation handler only.
        class TaskWithoutCancelling(asyncio.Task):
            @property
            def cancelling(self):
                raise AttributeError("Python 3.10 Task has no cancelling method")
        cid = self._done_checklist()
        self.llm.mode = "gate"; self.llm.entered = asyncio.Event(); self.llm.release = asyncio.Event()
        pending = TaskWithoutCancelling(self.registry.tool_verify_checklist(self.context(), {"checklist_id": cid}))
        await asyncio.wait_for(self.llm.entered.wait(), 5)
        aid = self.status(cid)["review_agent_id"]
        pending.cancel()
        with self.assertRaises(asyncio.CancelledError):
            await pending
        self.assertEqual(self.agents.load_agent(aid)["status"], "cancelled")
        self.assertEqual(self.status(cid)["review_status"], "cancelled")
        self.assertEqual(self.status(cid)["items"][0]["state"], "done")

    async def test_child_task_cancellation_returns_feedback_not_source_cancellation(self) -> None:
        cid = self._done_checklist(); pending = await self.gated(cid)
        aid = self.status(cid)["review_agent_id"]
        self.runtime.running[aid].cancel()
        result = await asyncio.wait_for(pending, 5)
        self.assertEqual(result["action"], "review_cancelled")
        self.assertFalse(pending.cancelled())
        self.assertEqual(self.status(cid)["review_status"], "cancelled")

    async def test_cancel_tool_row_cancels_child_without_user_cancelling_family(self) -> None:
        cid = self._done_checklist()
        self.llm.mode = "gate"; self.llm.entered = asyncio.Event(); self.llm.release = asyncio.Event()
        pending = asyncio.create_task(self.registry.execute_tool_call(velox.APP_SCOPE_ID,
            {"name":"verify_checklist", "arguments":{"checklist_id":cid}}, chat_id=self.chat_id,
            endpoint_profile_id=self.context().endpoint_profile_id, task_kind="chat"))
        await asyncio.wait_for(self.llm.entered.wait(), 5)
        active = [item for item in self.registry._active_tool_executions.values() if item.tool_name == "verify_checklist"]
        self.assertEqual(len(active), 1)
        self.assertTrue(self.registry.cancel_tool_call(active[0].tool_call_id))
        result = await asyncio.wait_for(pending, 5)
        self.assertFalse(result["ok"])
        self.assertEqual(result["status"], "cancelled")
        current = self.status(cid)
        self.assertEqual(current["review_status"], "cancelled")
        self.assertEqual(current["lifecycle"], "open")
        self.assertEqual(current["items"][0]["state"], "done")
        self.assertEqual(self.agents.load_agent(current["review_agent_id"])["status"], "cancelled")

    async def test_explicit_user_stop_cannot_be_overwritten_by_late_completion(self) -> None:
        cid = self._done_checklist(); pending = await self.gated(cid)
        self.checklists.cancel_open_by_user(self.owner)
        self.llm.release.set()
        result = await asyncio.wait_for(pending, 5)
        self.assertNotEqual(result.get("review_result"), "passed")
        current = self.status(cid)
        self.assertEqual(current["lifecycle"], velox.CHECKLIST_LIFECYCLE_CANCELLED_BY_USER)
        self.assertEqual(current["items"][0]["state"], "done")
        self.assertIsNone(self.checklists.active(self.owner))

    async def test_reviewer_active_time_timeout_is_not_removed(self) -> None:
        cid = self._done_checklist()
        async def expired(_request: Any) -> Any:
            raise velox.AgentTimeoutError("Reviewer active budget reached")
        self.llm.chat_completions_once_full = expired
        result = await self._verify(cid)
        self.assertEqual(result["action"], "review_error")
        self.assertNotIn(self.status(cid)["review_status"], velox.REVIEW_ACTIVE)
        self.assertEqual(self.status(cid)["items"][0]["state"], "done")
        self.assertEqual(self.agents.load_agent(result["review_agent_id"])["status"], "cancelled")

    async def test_transient_result_commit_failure_reuses_same_terminal_review(self) -> None:
        cid = self._done_checklist()
        original = velox.ChecklistStore.apply_review
        count = {"n": 0}
        def fail_once(store: Any, *args: Any, **kwargs: Any) -> Any:
            count["n"] += 1
            if count["n"] == 1:
                raise OSError("Injected first result commit failure")
            return original(store, *args, **kwargs)
        with mock.patch.object(velox.ChecklistStore, "apply_review", new=fail_once):
            result = await self._verify(cid)
        self.assertEqual(result["review_result"], "passed")
        self.assertEqual(count["n"], 2)
        self.assertEqual(len(self.llm.requests), 1)
        self.assertEqual(self.event_count(cid, "review_completed"), 1)


