    async def test_mixed_failures_share_one_retry_budget(self) -> None:
        self.configure()
        client = _RecoverySequenceClient(self.storage, [[velox.LLMChunk(done=True, finish_reason='network_error')],
            [velox.LLMChunk(error='HTTP 429 Too Many Requests', done=True)], [velox.LLMChunk(error='TimeoutError: timed out', done=True)], self.ok()])
        chunks = await self.collect(client)
        self.assertEqual(len(client.requests), 3)
        self.assertTrue(chunks[-1].endpoint_recovery_exhausted)
        self.assertIn('2 re-attempt(s) (3 total attempts)', chunks[-1].error)
        recovery = chunks[-1].provider_diagnostics['endpoint_error_recovery']
        self.assertEqual(recovery['retries_used'], 2)
        self.assertEqual([r['attempt'] for r in recovery['attempts']], [1, 2])
        self.assertTrue(all(r.messages == client.requests[0].messages for r in client.requests))

