        for _ in range(2):
            chunks = await self.collect(client)
            self.assertEqual(chunks[-1].provider_diagnostics['endpoint_error_recovery']['retries_used'], 1)
            self.assertEqual(chunks[-1].text, 'Recovered.')
        self.assertEqual(len(client.requests), 4)

