    async def test_cancel_during_recovery_wait_prevents_next_attempt(self) -> None:
        self.configure(error_recovery_delay_seconds=60)
        client = _RecoverySequenceClient(self.storage, [[velox.LLMChunk(error='HTTP 503 unavailable',done=True)], self.ok()])
        cancel = threading.Event(); entered = asyncio.Event()
        real = client._wait_for_endpoint_recovery
        async def wait(*args: Any) -> float:
            entered.set(); return await real(*args)
        with mock.patch.object(client,'_wait_for_endpoint_recovery',side_effect=wait):
            task = asyncio.create_task(self.collect(client,cancel_event=cancel))
            await asyncio.wait_for(entered.wait(), 2); cancel.set()
            with self.assertRaises(asyncio.CancelledError): await asyncio.wait_for(task, 2)
        self.assertEqual(len(client.requests), 1)

