    async def test_recovery_releases_inference_slot_and_shows_dashboard_status(self) -> None:
        self.configure(error_recovery_delay_seconds=60,max_concurrent_requests=1)
        client = _RecoverySequenceClient(self.storage, [[velox.LLMChunk(done=True,finish_reason='network_error')],self.ok()])
        monitor = velox.LLMTaskMonitor(self.storage)
        scheduler = velox.EndpointInferenceScheduler(self.storage,client.resolve_endpoint,monitor)
        client.bind_request_scheduler(scheduler,monitor)
        cancel=threading.Event(); task=asyncio.create_task(self.collect(client,cancel_event=cancel,task_kind='chat'))
        try:
            for _ in range(200):
                rows=monitor.dashboard_records()
                if rows and rows[0].get('display_status')=='endpoint error recovery': break
                await asyncio.sleep(.01)
            self.assertEqual(rows[0]['display_status'],'endpoint error recovery')
            self.assertEqual(scheduler.snapshot()[self.eid]['active_task_ids'],[])
            self.assertEqual(monitor.record_metadata(rows[0]['task_id'])['cooldown_attempt'],1)
            other=_RecoverySequenceClient(self.storage,[self.ok()]);other.bind_request_scheduler(scheduler,monitor)
            result=await asyncio.wait_for(other.chat_completions_stream_full(self.req(task_kind='image')),2)
            self.assertEqual(result['text'],'Recovered.')
            cancel.set()
            with self.assertRaises(asyncio.CancelledError):await asyncio.wait_for(task,2)
            self.assertEqual(scheduler.snapshot()[self.eid]['active_task_ids'],[])
        finally:
            cancel.set();task.cancel();await asyncio.gather(task,return_exceptions=True);await scheduler.close()

