        for provider in velox.ENDPOINT_PROVIDERS:
            for family in (velox.ENDPOINT_MODEL_TYPE_CUSTOM, velox.ENDPOINT_MODEL_TYPE_QWEN_3_8_FLASH_NEXT):
                with self.subTest(provider=provider, family=family):
                    profile = velox.default_endpoint_profile('custom-test', 'Custom test', provider=provider,
                        timeout_seconds=900, model_type=family)
                    self.assertEqual(profile['image_analysis_context'], 'inline' if provider == 'vllm' else 'separate')
