        self.set_default(velox.DEFAULT_QWEN_3_8_FLASH_NEXT_NOVITA_ENDPOINT_PROFILE_ID)
        profile = self.llm.resolve_endpoint(self.chats.get_endpoint_profile_id())
        self.assertEqual(profile['context_window_tokens'], 524288)
