class _ImageCaptureClient(velox.LLMClient):
    """Capture prepared separate-context requests while retaining real strict resolution."""
    def __init__(self, storage: Storage):
        super().__init__(storage)
        self.requests: list[LLMRequest] = []
    async def chat_completions_stream(self, request: LLMRequest):
        self.requests.append(request)
        yield velox.LLMChunk(text='Observed pixels, including the label \u03c4.', done=True, finish_reason='stop')


class CurrentImageRoutingTests(_AsyncRuntimeFixture):
    PNG = VisionEndpointAndRoutingTests._PNG_BYTES
    def setUp(self) -> None:
        super().setUp()
        self.image = self.paths.chat_workspace_dir(self.cid) / 'source image.png'
        self.image.write_bytes(self.PNG)
        self.capture = _ImageCaptureClient(self.storage)
        self.images = velox.ImageTools(self.storage, self.capture)
        self.cancel = threading.Event()
        self.ctx = velox.ToolContext(velox.APP_SCOPE_ID, chat_id=self.cid, endpoint_profile_id=self.eid,
                               tool_call_id='current-image', task_kind='chat', cancel_event=self.cancel)
        self.storage.update_config(lambda cfg: cfg['llm'].update(default_profile_id=velox.DEFAULT_GLM_5_3_FLASH_NOVITA_ENDPOINT_PROFILE_ID))

    def mode(self, mode: str) -> None:
        self.storage.update_config(lambda cfg: velox.endpoint_profile_ref(cfg, self.eid).update(image_analysis_context=mode))

    async def analyze(self, method: str = 'analyze') -> dict[str, Any]:
        return await getattr(self.images, method)(self.ctx, {'path': str(self.image), 'prompt': 'Inspect the exact visible label.'})

    async def test_all_three_inline_tools_handoff_pixels_without_extra_inference(self) -> None:
        self.mode('inline')
        for method in ('analyze', 'analyze_ui', 'analyze_3d_scene'):
            with self.subTest(method=method):
                result = await self.analyze(method)
                self.assertEqual(result['mode'], 'current_endpoint_context_handoff')
                self.assertEqual(result['endpoint_profile_id'], self.eid)
                message, summary = velox.build_current_context_vision_message([], [{'ok': True, 'result': result}], self.capture.resolve_endpoint(self.eid))
                self.assertEqual(summary['included_images'], 1)
                self.assertEqual(base64.b64decode(message['content'][0]['image_url']['url'].split(',', 1)[1]), self.PNG)
        self.assertEqual(self.capture.requests, [])

    async def test_all_three_separate_tools_use_same_endpoint_with_isolated_prompts(self) -> None:
        self.mode('separate')
        methods = [('analyze', velox.IMAGE_ANALYSIS_ENDPOINT_SYSTEM_PROMPT, 'separate_context_streaming'),
                   ('analyze_ui', velox.IMAGE_ANALYSIS_UI_ENDPOINT_SYSTEM_PROMPT, 'separate_ui_context_streaming'),
                   ('analyze_3d_scene', velox.IMAGE_ANALYSIS_3D_SCENE_ENDPOINT_SYSTEM_PROMPT, 'separate_3d_scene_context_streaming')]
        for method, prompt, mode in methods:
            with self.subTest(method=method):
                result = await self.analyze(method)
                request = self.capture.requests[-1]
                self.assertEqual(request.endpoint_profile_id, self.eid)
                self.assertEqual(result['endpoint_profile_id'], self.eid)
                self.assertEqual(result['mode'], mode)
                self.assertNotIn(velox.CURRENT_CONTEXT_VISION_RESULT_KEY, result)
                self.assertEqual(request.messages[0], {'role': 'system', 'content': prompt})
                self.assertEqual(len(request.messages), 2)
                self.assertIsNone(request.native_tools)
                self.assertEqual(request.task_kind, 'image')
                self.assertIsNone(request.monitor_task_id)
                self.assertIs(request.cancel_event, self.cancel)
                self.assertEqual(request.task_metadata['chat_id'], self.cid)
                self.assertEqual(request.task_metadata['tool_call_id'], 'current-image')
                self.assertEqual(velox.message_image_input_count(request.messages), 1)
                data = request.messages[1]['content'][1]['image_url']['url']
                self.assertEqual(base64.b64decode(data.split(',', 1)[1]), self.PNG)
        self.assertEqual(len(self.capture.requests), 3)

    async def test_separate_context_never_contains_requester_history(self) -> None:
        self.mode('separate')
        self.user('PRIVATE_HISTORY_SENTINEL')
        self.chats.append_turn(velox.APP_SCOPE_ID, self.cid, velox.make_turn(self.cid, 'assistant', 'PRIVATE_ANSWER_SENTINEL'))
        await self.analyze()
        sent = json.dumps(self.capture.requests[0].messages)
        self.assertNotIn('PRIVATE_HISTORY_SENTINEL', sent)
        self.assertNotIn('PRIVATE_ANSWER_SENTINEL', sent)
        self.assertIn('Inspect the exact visible label.', sent)

    async def test_separate_output_limit_is_bounded_by_current_endpoint(self) -> None:
        self.mode('separate')
        self.storage.update_config(lambda cfg: velox.endpoint_profile_ref(cfg, self.eid).update(max_output_tokens=512))
        await self.analyze()
        self.assertEqual(self.capture.requests[-1].max_output_tokens, 512)

    async def test_mode_change_affects_next_image_call_not_endpoint_identity(self) -> None:
        first = await self.analyze()
        self.mode('separate')
        second = await self.analyze()
        self.mode('inline')
        third = await self.analyze()
        self.assertEqual([r['mode'] for r in (first, second, third)],
                         ['current_endpoint_context_handoff', 'separate_context_streaming', 'current_endpoint_context_handoff'])
        self.assertTrue(all(r['endpoint_profile_id'] == self.eid for r in (first, second, third)))
        self.assertEqual(len(self.capture.requests), 1)

    async def test_missing_caller_never_uses_vision_capable_default(self) -> None:
        self.ctx.endpoint_profile_id = ''
        with self.assertRaisesRegex(ValueError, 'current endpoint'):
            await self.analyze()
        self.assertEqual(self.capture.requests, [])

    async def test_unknown_caller_never_uses_vision_capable_default(self) -> None:
        self.ctx.endpoint_profile_id = 'deleted-current-endpoint'
        with self.assertRaisesRegex(ValueError, 'Unknown endpoint'):
            await self.analyze()
        self.assertEqual(self.capture.requests, [])

