    async def test_precancelled_inline_and_separate_do_not_prepare_or_send(self) -> None:
        self.cancel.set()
        for mode in ('inline', 'separate'):
            self.mode(mode)
            with self.subTest(mode=mode), mock.patch.object(self.images, '_metadata', side_effect=AssertionError('late image read')):
                with self.assertRaises(velox.ToolCancelledError):
                    await self.analyze()
        self.assertEqual(self.capture.requests, [])

    async def test_cancellation_during_preparation_blocks_handoff_or_send(self) -> None:
        real = self.images._metadata
        def prepare(*args: Any) -> dict[str, Any]:
            result = real(*args); self.cancel.set(); return result
        for mode in ('inline', 'separate'):
            self.cancel.clear(); self.mode(mode)
            with self.subTest(mode=mode), mock.patch.object(self.images, '_metadata', side_effect=prepare):
                with self.assertRaises(velox.ToolCancelledError):
                    await self.analyze()
        self.assertEqual(self.capture.requests, [])

    def test_browser_fanout_uses_only_current_endpoint_limit(self) -> None:
        browser = velox.BrowserTools(self.storage, self.capture, self.images)
        self.storage.update_config(lambda cfg: velox.endpoint_profile_ref(cfg, self.eid).update(max_concurrent_requests=3))
        self.storage.update_config(lambda cfg: velox.endpoint_profile_ref(cfg, cfg['llm']['default_profile_id']).update(max_concurrent_requests=8))
        for mode in ('inline', 'separate'):
            self.mode(mode)
            self.assertEqual(browser._image_review_concurrency(10, self.eid), 3)
