class ImageHTTPIntegrationTests(_AsyncRuntimeFixture):
    """Real HTTP + scheduler + native tool loop, not just direct image-tool mocks."""
    async def run_flow(self, transport: str, mode: str, *, hosted: bool = False,
                       agent: bool = False, recover: bool = False) -> None:
        self.eid = (velox.DEFAULT_QWEN_3_8_FLASH_NEXT_NOVITA_ENDPOINT_PROFILE_ID if hosted
                    else velox.DEFAULT_QWEN_3_8_FLASH_NEXT_ENDPOINT_PROFILE_ID)
        self.chats.set_chat_endpoint_profile_id(self.cid, self.eid)
        image = self.paths.chat_workspace_dir(self.cid) / 'http-frame.png'
        image.write_bytes(VisionEndpointAndRoutingTests._PNG_BYTES)
        call = _make_test_provider_call('image-http-call', 'image_analyze',
                                       {'path': str(image), 'prompt': 'Inspect the visible label \u03c4.'})
        captured: list[dict[str, Any]] = []; errors: list[str] = []
        counts = {'main': 0, 'image': 0}
        monitor = velox.LLMTaskMonitor(self.storage)
        scheduler = velox.EndpointInferenceScheduler(self.storage, self.llm.resolve_endpoint, monitor)
        self.llm.bind_request_scheduler(scheduler, monitor)
        self.tools.bind_llm_client(self.llm)
        self.tools.bind_task_monitor(monitor)
        self.runtime.monitor = monitor; self.aruntime.monitor = monitor
        outer = self
        def response(text: str = '', *, first: bool = False) -> dict[str, Any]:
            if transport == 'responses':
                output = ([{'type': 'function_call', 'id': 'fc_image', 'call_id': call['id'],
                            'name': 'image_analyze', 'arguments': call['function']['arguments'], 'status': 'completed'}]
                          if first else [{'type': 'message', 'id': 'msg_' + str(len(captured)), 'role': 'assistant',
                                          'content': [{'type': 'output_text', 'text': text}], 'status': 'completed'}])
                return {'id': 'response_' + str(len(captured)), 'status': 'completed', 'output': output,
                        'usage': {'input_tokens': 32, 'output_tokens': 12}}
            message: dict[str, Any] = {'role': 'assistant', 'content': text}
            if first: message['tool_calls'] = [call]
            return {'choices': [{'index': 0, 'message': message, 'finish_reason': 'tool_calls' if first else 'stop'}],
                    'usage': {'prompt_tokens': 32, 'completion_tokens': 12}}
        class Handler(http.server.BaseHTTPRequestHandler):
            def log_message(self, *args: Any) -> None: pass
            def do_POST(self) -> None:
                try:
                    raw = self.rfile.read(int(self.headers['Content-Length'])); payload = json.loads(raw)
                    main = bool(payload.get('tools'))
                    kind = 'main' if main else 'image'; counts[kind] += 1
                    captured.append({'path': self.path, 'payload': payload, 'raw': raw, 'kind': kind,
                        'authorization': self.headers.get('Authorization'),
                        'active_count': len(scheduler.snapshot().get(outer.eid, {}).get('active_task_ids', []))})
                    if recover and not main and counts['image'] == 1:
                        status, mime = 503, 'application/json'
                        body = json.dumps({'error': {'code': 'server_overloaded', 'message': 'Try again'}}).encode()
                    else:
                        status, mime = 200, 'text/event-stream'
                        text = ('Image checked.\n' + velox.AGENT_COMPLETION_SUCCESS_EXAMPLE if agent else 'Image checked.') if main else 'Visible label: \u03c4. Image reviewed.'
                        obj = response(text, first=main and counts['main'] == 1)
                        event = {'type': 'response.completed', 'response': obj} if transport == 'responses' else obj
                        body = b'data: ' + json.dumps(event, ensure_ascii=False).encode() + b'\n\ndata: [DONE]\n\n'
                    self.send_response(status); self.send_header('Content-Type', mime)
                    self.send_header('Content-Length', str(len(body))); self.end_headers()
                    self.wfile.write(body); self.wfile.flush()
                except (BrokenPipeError, ConnectionResetError): pass
                except Exception as exc: errors.append(repr(exc))
        server = http.server.ThreadingHTTPServer(('127.0.0.1', 0), Handler); server.daemon_threads = True
        thread = threading.Thread(target=lambda: server.serve_forever(poll_interval=.02), daemon=True); thread.start()
        cfg = self.storage.load_config()
        cfg['llm']['default_profile_id'] = velox.DEFAULT_GLM_5_3_FLASH_NOVITA_ENDPOINT_PROFILE_ID
        profile = velox.endpoint_profile_ref(cfg, self.eid)
        profile.update(base_url=f'http://127.0.0.1:{server.server_port}/v1', api_transport=transport,
            api_key='local-image-test-key', max_concurrent_requests=1, image_analysis_context=mode,
            error_recovery_enabled=True, error_recovery_attempts=1, error_recovery_delay_seconds=0,
            rate_limit_enabled=False, adaptive_token_estimation=False)
        self.storage.write_config(cfg)
        try:
            with mock.patch.object(self.tools, 'execute_tool_call', wraps=self.tools.execute_tool_call) as dispatch:
                if agent:
                    record = self.agents.create_agent(self.cid, 'PRIVATE_REQUESTER_SENTINEL: inspect the image once, then complete.', endpoint_profile_id=self.eid)
                    await asyncio.wait_for(self.aruntime._run_agent(record['agent_id']), 15)
                    saved = self.agents.load_agent(record['agent_id'])
                    self.assertEqual(saved['status'], 'succeeded', saved.get('failure_message'))
                else:
                    user = self.user('PRIVATE_REQUESTER_SENTINEL: inspect the image once, then complete.')
                    turn = velox.make_turn(self.cid, 'assistant', '', status='streaming', endpoint_profile_id=self.eid)
                    self.chats.append_turn(velox.APP_SCOPE_ID, self.cid, turn, mark_stale=False)
                    await asyncio.wait_for(self.runtime._run_assistant_loop(velox.APP_SCOPE_ID, self.cid, turn['turn_id'],
                        self.eid, user['text'], 'Image HTTP integration'), 15)
                    last = self.chats.load_turns(velox.APP_SCOPE_ID, self.cid)[-1]
                    self.assertEqual(last['status'], 'complete', last)
                    self.assertEqual(last['text'], 'Image checked.')
                self.assertEqual(dispatch.call_count, 1, 'Only the original image tool executes, including during recovery')
            self.assertEqual(errors, [])
            self.assertEqual(counts['main'], 2)
            self.assertEqual(counts['image'], (2 if recover else 1) if mode == 'separate' else 0)
            for row in captured:
                self.assertEqual(row['path'], '/v1/responses' if transport == 'responses' else '/v1/chat/completions')
                self.assertEqual(row['authorization'], 'Bearer local-image-test-key')
                self.assertEqual(row['payload']['model'], profile['model'])
                self.assertEqual(row['active_count'], 1, 'Every image/main provider request must own the shared slot')
                self.assertNotIn('image_analysis_context', row['payload'])
            main_rows = [row['payload'] for row in captured if row['kind'] == 'main']
            image_rows = [row for row in captured if row['kind'] == 'image']
            main_second = json.dumps(main_rows[-1], ensure_ascii=False)
            self.assertIn('PRIVATE_REQUESTER_SENTINEL', main_second)
            self.assertIn('image-http-call', main_second)
            if mode == 'inline':
                self.assertIn('data:image/png;base64,', main_second)
                self.assertIn('Analyze the image', main_second)
            else:
                self.assertNotIn('data:image/png;base64,', main_second)
                self.assertIn('Visible label:', main_second)
                for row in image_rows:
                    sent = json.dumps(row['payload'], ensure_ascii=False)
                    self.assertNotIn('PRIVATE_REQUESTER_SENTINEL', sent)
                    self.assertIn('data:image/png;base64,', sent)
                    self.assertNotIn('tools', row['payload'])
                    content = row['payload']['input' if transport == 'responses' else 'messages']
                    self.assertEqual(len(content), 1 if row['payload'].get('instructions') else 2)
                    if row['payload'].get('instructions'):
                        self.assertIn(velox.IMAGE_ANALYSIS_ENDPOINT_SYSTEM_PROMPT, row['payload']['instructions'])
                if recover: self.assertEqual(image_rows[0]['raw'], image_rows[1]['raw'])
            snapshot = scheduler.snapshot().get(self.eid, {})
            self.assertEqual(snapshot.get('active_task_ids', []), [])
            self.assertFalse(snapshot.get('queued'))
            image_records = [r for r in monitor.dashboard_records(100) if str(r.get('task_type', '')).lower() == 'image']
            if mode == 'separate': self.assertTrue(image_records, 'Separate image inference must be visible in the Dashboard')
        finally:
            await scheduler.close()
            await asyncio.to_thread(server.shutdown); server.server_close(); await asyncio.to_thread(thread.join, 2)
            self.assertFalse(thread.is_alive())

