    def test_html_has_balanced_nested_sections_and_no_script_from_evidence(self) -> None:
        self.update('C1.1', comment='<script>alert(1)</script> ![image](https://invalid/x) **literal** `ticks`')
        md, page = self.report()
        self.assertEqual(page.count('<section class="checklist-requirement">'), 2)
        self.assertEqual(page.count('<section class="checklist-step">'), 2)
        self.assertEqual(page.count('</section>'), 4)
        self.assertIn('<h5>Step', page)
        self.assertIn('&lt;script&gt;alert(1)&lt;/script&gt;', page)
        self.assertNotIn('<script>', page); self.assertNotIn('<img ', page); self.assertNotIn('<a ', page)
        self.assertIn('**literal**', page); self.assertIn('`ticks`', page)
        self.assertNotIn('<strong>literal</strong>', page)
        self.assertEqual(page.count('<main>'), 1)

    def test_html_step_sections_are_inside_correct_parent_sections(self) -> None:
        from html.parser import HTMLParser
        class Structure(HTMLParser):
            def __init__(self): super().__init__(); self.stack=[]; self.paths=[]
            def handle_starttag(self, tag, attrs):
                if tag == 'section':
                    self.stack.append(dict(attrs).get('class')); self.paths.append(tuple(self.stack))
            def handle_endtag(self, tag):
                if tag == 'section': self.stack.pop()
        parser = Structure(); parser.feed(self.report()[1])
        self.assertEqual(parser.paths, [('checklist-requirement',), ('checklist-requirement','checklist-step'),
                                      ('checklist-requirement','checklist-step'), ('checklist-requirement',)])
        self.assertEqual(parser.stack, [])

