                w = self.widgets(); p = object.__new__(velox.Panels); p.widgets = w; p.state = w.state
                payload = {'name': 'Acceptance', 'review_result': 'failed' if failed else 'passed',
                           'failed_count': failed, 'verified_count': 3,
                           'failed_rows': [{'item_id': 'C1', 'text': 'Requirement', 'comment': 'Repair needed'},
                                           {'item_id': 'C1.1', 'parent_item_id': 'C1', 'text': 'Step', 'comment': 'Fresh evidence needed'}] if failed else []}
                p._draw_checklist_review_result_card('result', velox.Rect(0, 0, 900, 500), payload, p._checklist_review_card_markdown(payload))
                fills = [args[1] for name, args, _kwargs in w.renderer.drawn if name == 'draw_rect']
                self.assertIn(velox.CHECKLIST_REVIEW_TABLE_STYLE.header, fills)
