class _NestedChecklistFixture(_WriterDataRootsIsolatedTestMixin, unittest.TestCase):
    """Current-model fixtures: use real durable owners, never the retired expert API."""
    def setUp(self) -> None:
        super().setUp()
        self.temp = tempfile.TemporaryDirectory(); self.addCleanup(self.temp.cleanup)
        self.paths, self.storage, self.chats = _make_test_chat_stack(Path(self.temp.name))
        self.chat_id = self.chats.create_chat('Checklist contract')['chat_id']
        self.owner = velox._chat_checklist_owner(self.chat_id)
        self.store = velox.ChecklistStore(self.storage)
        self.registry = velox.ToolRegistry(self.storage)

    def create(self, items: Any = None, name: str = 'Original acceptance') -> str:
        return self.store.create(self.owner, name=name, items=['Observable outcome', 'Independent outcome'] if items is None else items)['checklist_id']

    def status(self, cid: str) -> dict[str, Any]:
        return self.store.status(self.owner, cid, include_history=True)

    def update(self, cid: str, item: str, state: str, comment: str = 'Observed result; next action is recorded.') -> dict[str, Any]:
        return self.store.update_items(self.owner, cid, [{'item_id': item, 'state': state, 'comment': comment}])

    def done(self, cid: str) -> None:
        items = self.store.all_items(self.status(cid))
        updates = [{'item_id': i['id'], 'state': 'done', 'comment': 'Executed the current artifact and observed the expected behavior.'}
                   for i in items if i['state'] != 'verified']
        for offset in range(0, len(updates), 100):
            self.store.update_items(self.owner, cid, updates[offset:offset+100])

    def review(self, cid: str, failures: Any = ()) -> dict[str, Any]:
        prepared = self.store.prepare_verification(self.owner, cid)
        return self.store.apply_review(self.owner, cid, self.verdicts(cid, failures), review_cycle=prepared['review_cycle'])

    def verdicts(self, cid: str, failures: Any = ()) -> list[dict[str, str]]:
        return [{'item_id': i['id'], 'verdict': 'fail' if i['id'] in failures else 'pass',
                 'comment': 'Current artifact failed.' if i['id'] in failures else 'Current artifact independently passed.'}
                for i in self.store.all_items(self.status(cid))]

    def raw(self) -> bytes:
        path = self.store._collection_path(self.owner)
        return path.read_bytes() if path.exists() else b''


class FixedChecklistContractTests(_NestedChecklistFixture):
    def test_original_requirements_start_not_started_with_stable_c_ids(self) -> None:
        cid = self.create(['First result', 'Second result']); rows = self.status(cid)['items']
        self.assertEqual([(i['id'], i['text'], i['state']) for i in rows], [('C1', 'First result', 'not_started'), ('C2', 'Second result', 'not_started')])
        self.assertTrue(all(i['history'] and not i['subitems'] for i in rows))

    def test_single_active_list_cannot_be_replaced_by_different_name(self) -> None:
        cid = self.create(); before = self.raw()
        with self.assertRaisesRegex(ValueError, 'already active'): self.create(name='Replacement')
        self.assertEqual(self.raw(), before); self.assertEqual(self.store.active(self.owner)['id'], cid)

    def test_model_cannot_abandon_add_edit_or_select_another_execution_list(self) -> None:
        for name in ('abandon', 'add_item', 'edit_item', 'select', 'sync_from_legacy'):
            self.assertFalse(hasattr(self.store, name), name)
        for name in ('checklist_abandon', 'checklist_item_add', 'checklist_item_edit', 'expert_mode_enter', 'expert_mode_exit'):
            self.assertNotIn(name, self.registry.tools)

    def test_completed_history_and_new_active_work_coexist(self) -> None:
        first = self.create(); self.done(first); self.review(first)
        before = self.status(first); second = self.create(name='Follow-up repair')
        self.assertEqual(self.status(first), before)
        self.assertEqual(self.store.list_checklists(self.owner)['active_checklist_id'], second)
        self.assertEqual(len(self.store.list_checklists(self.owner, include_completed=True)['checklists']), 2)

    def test_completed_history_remains_unmodifiable(self) -> None:
        cid = self.create(); self.done(cid); self.review(cid); before = self.raw()
        with self.assertRaises(ValueError): self.update(cid, 'C1', 'in_progress')
        with self.assertRaises(ValueError): self.store.create_subitems(self.owner, cid, 'C1', ['Late plan'])
        with self.assertRaises(ValueError): self.store.prepare_verification(self.owner, cid)
        self.assertEqual(self.raw(), before)

    def test_history_names_are_case_and_whitespace_insensitively_reserved(self) -> None:
        cid = self.create(name='Original acceptance'); self.done(cid); self.review(cid)
        for name in ('ORIGINAL ACCEPTANCE', ' Original   acceptance ', 'Original\tacceptance'):
            with self.subTest(name=name), self.assertRaises(ValueError): self.create(name=name)
        self.assertIsNone(self.store.active(self.owner))

    def test_requirement_limit_accepts_100_and_rejects_101(self) -> None:
        for items in ([], ['x']*101, 'not an array', [None], ['  '], [12]):
            with self.subTest(items=str(items)[:30]), self.assertRaises(ValueError): self.create(items)
        cid = self.create([f'Outcome {n}' for n in range(100)])
        self.assertEqual(self.status(cid)['items'][-1]['id'], 'C100')

    def test_original_wording_order_and_membership_cannot_be_rewritten(self) -> None:
        cid = self.create(); original = self.store.load_collection(self.owner); before = self.raw()
        for change in ('wording', 'order', 'remove', 'append', 'name', 'identity'):
            altered = copy.deepcopy(original); row = altered['checklists'][0]
            if change == 'wording': row['items'][0]['text'] = 'Narrowed outcome'
            elif change == 'order': row['items'].reverse()
            elif change == 'remove': row['items'].pop()
            elif change == 'append': row['items'].append(dict(row['items'][0], id='C3'))
            elif change == 'name': row['name'] = 'Replacement name'
            else: row['items'][0]['id'] = 'R1'
            with self.subTest(change=change), self.assertRaises(ValueError): self.store._save(self.owner, altered)
            self.assertEqual(self.raw(), before)

    def test_one_time_subitems_preserve_parent_contract(self) -> None:
        cid = self.create(); before = self.status(cid)['items'][0]
        self.store.create_subitems(self.owner, cid, 'C1', ['Reproduce', 'Implement', 'Exercise'])
        parent = self.status(cid)['items'][0]
        self.assertEqual((parent['id'], parent['text'], parent['state']), (before['id'], before['text'], before['state']))
        self.assertEqual([i['id'] for i in parent['subitems']], ['C1.1','C1.2','C1.3'])
        self.assertTrue(all(i['state']=='not_started' and i['history'] for i in parent['subitems']))

    def test_second_subitem_plan_is_rejected_even_if_identical(self) -> None:
        cid = self.create(); self.store.create_subitems(self.owner, cid, 'C1', ['Step']); before=self.raw()
        for plan in (['Step'], ['Replacement'], ['Step','Extra']):
            with self.subTest(plan=plan), self.assertRaisesRegex(ValueError, 'immutable'): self.store.create_subitems(self.owner, cid, 'C1', plan)
            self.assertEqual(self.raw(), before)

    def test_subitems_never_have_grandchildren(self) -> None:
        cid=self.create(); self.store.create_subitems(self.owner,cid,'C1',['Step']); before=self.raw()
        with self.assertRaisesRegex(ValueError, 'nesting'): self.store.create_subitems(self.owner,cid,'C1.1',['Grandchild'])
        self.assertEqual(self.raw(),before)

    def test_subitem_limits_are_per_parent_not_total(self) -> None:
        cid=self.create()
        for parent in ('C1','C2'):
            for plan in ([],['x']*101,['']):
                with self.assertRaises(ValueError): self.store.create_subitems(self.owner,cid,parent,plan)
            self.store.create_subitems(self.owner,cid,parent,[f'Step {i}' for i in range(100)])
        self.assertEqual(len(self.store.all_items(self.status(cid))),202)
        self.assertEqual(self.status(cid)['items'][1]['subitems'][-1]['id'],'C2.100')

    def test_subitem_structure_and_wording_are_fixed_after_creation(self) -> None:
        cid=self.create(); self.store.create_subitems(self.owner,cid,'C1',['First','Second']); saved=self.store.load_collection(self.owner); before=self.raw()
        for change in ('wording','order','remove','append','empty','grandchild'):
            altered=copy.deepcopy(saved); children=altered['checklists'][0]['items'][0]['subitems']
            if change=='wording': children[0]['text']='Replacement'
            elif change=='order': children.reverse()
            elif change=='remove': children.pop()
            elif change=='append': children.append(dict(children[0],id='C1.3'))
            elif change=='empty': children.clear()
            else: children[0]['subitems']=[]
            with self.subTest(change=change), self.assertRaises(ValueError): self.store._save(self.owner,altered)
            self.assertEqual(self.raw(),before)

    def test_child_progress_starts_parent_but_does_not_finish_it(self) -> None:
        cid=self.create(); self.store.create_subitems(self.owner,cid,'C1',['Step'])
        self.update(cid,'C1.1','done'); parent=self.status(cid)['items'][0]
        self.assertEqual(parent['state'],'in_progress'); self.assertEqual(parent['subitems'][0]['state'],'done')
        self.assertEqual(parent['history'][-1]['actor'],'velox')

    def test_parent_done_is_rejected_until_all_steps_done(self) -> None:
        cid=self.create(); self.store.create_subitems(self.owner,cid,'C1',['First','Second']); self.update(cid,'C1.1','done'); before=self.raw()
        with self.assertRaisesRegex(ValueError,'every sub-item'): self.update(cid,'C1','done')
        self.assertEqual(self.raw(),before)
        self.update(cid,'C1.2','done'); self.update(cid,'C1','done'); self.assertEqual(self.status(cid)['items'][0]['state'],'done')

    def test_batch_parent_first_validates_final_child_states_atomically(self) -> None:
        cid=self.create(); self.store.create_subitems(self.owner,cid,'C1',['Step'])
        self.store.update_items(self.owner,cid,[{'item_id':i,'state':'done','comment':'Observed complete'} for i in ('C1','C1.1')])
        self.assertTrue(all(i['state']=='done' for i in self.store.all_items(self.status(cid))[:2]))

    def test_invalid_later_batch_entry_rolls_back_earlier_valid_update(self) -> None:
        cid=self.create(); before=self.raw()
        with self.assertRaises(ValueError): self.store.update_items(self.owner,cid,[{'item_id':'C1','state':'done','comment':'Observed'}, {'item_id':'C999','state':'done','comment':'Wrong ID'}])
        self.assertEqual(self.raw(),before)

    def test_duplicate_update_id_is_rejected_without_history_changes(self) -> None:
        cid=self.create(); before=self.raw(); row={'item_id':'C1','state':'done','comment':'Observed'}
        with self.assertRaises(ValueError): self.store.update_items(self.owner,cid,[row,row])
        self.assertEqual(self.raw(),before)

    def test_update_schema_does_not_accept_retired_progress_fields(self) -> None:
        cid=self.create(); before=self.raw()
        for update in ({'requirement_id':'R1','status':'done','progress':'Old'}, {'item_id':'C1','state':'done','comment':'Observed','next_step':'Extra'}, {'item_id':'C1','state':'done'}):
            with self.assertRaises(ValueError): self.store.update_items(self.owner,cid,[update])
        self.assertEqual(self.raw(),before)

    def test_empty_comments_and_invalid_states_are_rejected(self) -> None:
        cid=self.create(); before=self.raw()
        for state,comment in (('done',''),('in_progress',' '),('verified','Claim'),('impossible','Give up'),('failed','Give up')):
            with self.subTest(state=state), self.assertRaises(ValueError): self.update(cid,'C1',state,comment)
        self.assertEqual(self.raw(),before)

    def test_same_state_new_comment_appends_factual_history(self) -> None:
        cid=self.create(); self.update(cid,'C1','in_progress','Reproduced defect; inspect parser')
        before=self.status(cid)['items'][0]['history']; self.update(cid,'C1','in_progress','Parser repaired; run negative cases')
        item=self.status(cid)['items'][0]
        self.assertEqual(item['history'][:-1],before); self.assertEqual(item['latest_comment'],'Parser repaired; run negative cases')

    def test_identical_state_and_comment_does_not_duplicate_history(self) -> None:
        cid=self.create(); self.update(cid,'C1','in_progress','Observed'); before=self.status(cid)['items'][0]['history']
        self.update(cid,'C1','in_progress','Observed'); self.assertEqual(self.status(cid)['items'][0]['history'],before)

    def test_done_reopens_with_evidence_without_changing_identity(self) -> None:
        cid=self.create(); self.update(cid,'C1','done'); before=self.status(cid)['items'][0]
        self.update(cid,'C1','in_progress','Fresh frame reveals clipped output')
        after=self.status(cid)['items'][0]; self.assertEqual((after['id'],after['text']),(before['id'],before['text']))
        self.assertEqual(after['state'],'in_progress'); self.assertEqual(after['history'][:-1],before['history'])

    def test_reopening_child_reopens_done_parent(self) -> None:
        cid=self.create(); self.store.create_subitems(self.owner,cid,'C1',['Step']); self.done(cid)
        self.update(cid,'C1.1','in_progress','Regression reproduced')
        self.assertEqual(self.status(cid)['items'][0]['state'],'in_progress')

    def test_progress_cannot_be_reset_to_not_started(self) -> None:
        cid=self.create(); self.update(cid,'C1','in_progress'); before=self.raw()
        with self.assertRaises(ValueError): self.update(cid,'C1','not_started')
        self.assertEqual(self.raw(),before)

    def test_done_parent_must_reopen_before_first_plan(self) -> None:
        cid=self.create(); self.update(cid,'C1','done')
        with self.assertRaises(ValueError): self.store.create_subitems(self.owner,cid,'C1',['Discovered step'])
        self.update(cid,'C1','in_progress','Need additional validation')
        self.store.create_subitems(self.owner,cid,'C1',['Validate']); self.assertEqual(len(self.status(cid)['items'][0]['subitems']),1)

    def test_continuation_includes_full_contract_and_prefers_active_steps(self) -> None:
        cid=self.create(); self.store.create_subitems(self.owner,cid,'C1',['First','Second'])
        self.update(cid,'C1.2','in_progress','Next inspect exact pixel region')
        prompt=self.store.continuation_prompt(self.owner)
        for text in ('C1','C1.1','C1.2','C2','Observable outcome','Independent outcome','Next inspect exact pixel region','Next actionable candidate: C1.2'):
            self.assertIn(text,prompt)

    def test_all_done_continues_to_explicit_independent_review_not_success(self) -> None:
        cid=self.create(); self.done(cid)
        self.assertIn('verify_checklist',self.store.continuation_prompt(self.owner))
        self.assertEqual(self.status(cid)['lifecycle'],'open')

    def test_execution_projection_tracks_canonical_state_without_mirror_file(self) -> None:
        cid=self.create(); adapter=velox.ExpertModeStore.for_chat(self.storage,self.chat_id)
        self.assertFalse(adapter.path.exists()); self.update(cid,'C1','in_progress','Observed canonical progress')
        state=adapter.load(active_only=True)
        self.assertEqual(state['checklist_id'],cid); self.assertEqual(state['requirements'][0]['item_id'],'C1')
        self.assertEqual(state['requirements'][0]['status'],'in_progress'); self.assertFalse(adapter.path.exists())

    def test_execution_continuation_claim_is_durable_and_idempotent(self) -> None:
        cid=self.create(); state, claimed=self.store.claim_execution_continuation(self.owner,'stop-1')
        self.assertTrue(claimed); self.assertEqual(state['continuation_count'],1)
        again,claimed=velox.ChecklistStore(self.storage).claim_execution_continuation(self.owner,'stop-1')
        self.assertFalse(claimed); self.assertEqual(again['continuation_count'],1)
        self.assertEqual(self.status(cid)['lifecycle'],'open')


class NestedReviewContractTests(_NestedChecklistFixture):
    def setUp(self) -> None:
        super().setUp(); self.cid=self.create(); self.store.create_subitems(self.owner,self.cid,'C1',['Implement','Exercise']); self.done(self.cid)

    def test_review_requires_every_parent_and_step_done(self) -> None:
        self.update(self.cid,'C1.2','in_progress','New failure'); before=self.raw()
        with self.assertRaisesRegex(ValueError,'every requirement and sub-item'): self.store.prepare_verification(self.owner,self.cid)
        self.assertEqual(self.raw(),before)

    def test_requested_review_freezes_all_implementer_mutation(self) -> None:
        self.store.prepare_verification(self.owner,self.cid); before=self.raw()
        for op in (lambda:self.update(self.cid,'C1.1','in_progress'),lambda:self.store.create_subitems(self.owner,self.cid,'C2',['Late']),lambda:self.store.prepare_verification(self.owner,self.cid)):
            with self.assertRaisesRegex(ValueError,'Reviewer'): op()
            self.assertEqual(self.raw(),before)

    def test_unrequested_verdict_cannot_verify_any_item(self) -> None:
        before=self.raw()
        with self.assertRaisesRegex(ValueError,'requested review'): self.store.apply_review(self.owner,self.cid,self.verdicts(self.cid))
        self.assertEqual(self.raw(),before)

    def test_missing_extra_duplicate_or_reordered_verdict_rejected_atomically(self) -> None:
        self.store.prepare_verification(self.owner,self.cid); verdicts=self.verdicts(self.cid); before=self.raw()
        variants=(verdicts[:-1],verdicts+[verdicts[0]],list(reversed(verdicts)),[verdicts[0]]*len(verdicts))
        for rows in variants:
            with self.assertRaisesRegex(ValueError,'exactly one verdict'): self.store.apply_review(self.owner,self.cid,rows)
            self.assertEqual(self.raw(),before)

    def test_invalid_verdict_or_empty_evidence_never_partially_commits(self) -> None:
        self.store.prepare_verification(self.owner,self.cid); before=self.raw()
        for field,value in (('verdict','maybe'),('comment',''),('comment',None)):
            rows=self.verdicts(self.cid); rows[-1][field]=value
            with self.assertRaises(ValueError): self.store.apply_review(self.owner,self.cid,rows)
            self.assertEqual(self.raw(),before)

    def test_stale_review_cycle_cannot_commit(self) -> None:
        self.store.prepare_verification(self.owner,self.cid); before=self.raw()
        for cycle in (0,2,True):
            with self.assertRaisesRegex(ValueError,'cycle'): self.store.apply_review(self.owner,self.cid,self.verdicts(self.cid),review_cycle=cycle)
            self.assertEqual(self.raw(),before)

    def test_failing_subitem_withholds_passing_parent(self) -> None:
        result=self.review(self.cid,{'C1.2'})
        self.assertEqual([i['state'] for i in self.store.all_items(result)],['in_progress','verified','in_progress','verified'])
        self.assertIn('acceptance withheld',result['items'][0]['latest_comment'])
        self.assertEqual(result['lifecycle'],'open'); self.assertEqual(result['review_status'],'failed')

    def test_parent_can_fail_even_if_implementation_steps_pass(self) -> None:
        result=self.review(self.cid,{'C1'})
        self.assertEqual(result['items'][0]['state'],'in_progress')
        self.assertTrue(all(i['state']=='verified' for i in result['items'][0]['subitems']))

    def test_all_pass_verifies_complete_tree_and_ends_continuation(self) -> None:
        result=self.review(self.cid)
        self.assertEqual(result['lifecycle'],'completed'); self.assertTrue(all(i['state']=='verified' for i in self.store.all_items(result)))
        self.assertIsNone(self.store.active(self.owner)); self.assertEqual(self.store.continuation_prompt(self.owner),'')

    def test_repair_same_ids_then_full_review_finishes_without_new_plan(self) -> None:
        original=[(i['id'],i['text']) for i in self.store.all_items(self.status(self.cid))]
        self.review(self.cid,{'C1.2'}); self.update(self.cid,'C1.2','done','Fixed and retested'); self.update(self.cid,'C1','done','Whole acceptance rechecked')
        result=self.review(self.cid)
        self.assertEqual(result['review_cycle'],2); self.assertEqual(result['lifecycle'],'completed')
        self.assertEqual([(i['id'],i['text']) for i in self.store.all_items(result)],original)

    def test_verified_step_can_reopen_while_another_requirement_keeps_list_active(self) -> None:
        self.review(self.cid,{'C2'}); self.update(self.cid,'C1.1','in_progress','New contrary evidence')
        parent=self.status(self.cid)['items'][0]
        self.assertEqual(parent['state'],'in_progress'); self.assertEqual(parent['subitems'][0]['state'],'in_progress')

    def test_implementer_cannot_promote_or_relabel_verified_evidence(self) -> None:
        self.review(self.cid,{'C2'}); before=self.raw()
        for state in ('verified','done','not_started'):
            with self.assertRaises(ValueError): self.update(self.cid,'C1.1',state)
            self.assertEqual(self.raw(),before)

    def test_second_review_can_fail_previously_verified_step(self) -> None:
        self.review(self.cid,{'C2'}); self.update(self.cid,'C2','done','Fixed independently')
        result=self.review(self.cid,{'C1.1'})
        self.assertEqual(result['items'][0]['state'],'in_progress'); self.assertEqual(result['items'][0]['subitems'][0]['state'],'in_progress')
        self.assertEqual(result['items'][1]['state'],'verified')

    def test_history_contains_original_proposal_review_failure_and_repair(self) -> None:
        self.review(self.cid,{'C1.2'}); self.update(self.cid,'C1.2','done','Repair capture observed')
        history=self.status(self.cid)['items'][0]['subitems'][1]['history']
        self.assertEqual([e['actor'] for e in history],['implementer','implementer','reviewer','implementer'])
        self.assertEqual(history[-2]['event'],'review_fail'); self.assertEqual(history[-2]['review_cycle'],1)
        self.assertTrue(all(e['timestamp'] and e['comment'] for e in history))

    def test_stop_during_review_preserves_item_evidence_and_fences_late_results(self) -> None:
        self.store.prepare_verification(self.owner,self.cid); before=self.status(self.cid)['items']
        self.store.cancel_open_by_user(self.owner)
        self.assertEqual(self.status(self.cid)['items'],before)
        with self.assertRaises(ValueError): self.store.apply_review(self.owner,self.cid,self.verdicts(self.cid),review_cycle=1)
        self.assertEqual(self.status(self.cid)['lifecycle'],'cancelled_by_user')

    def test_review_failure_status_allows_repairs_but_not_false_completion(self) -> None:
        self.review(self.cid,{'C1.2'})
        prompt=self.store.continuation_prompt(self.owner); self.assertIn('C1.2',prompt)
        self.assertIn('Current artifact failed',prompt); self.assertNotEqual(self.status(self.cid)['lifecycle'],'completed')

    def test_infrastructure_error_leaves_done_states_and_suppresses_auto_retry(self) -> None:
        cycle=self.store.prepare_verification(self.owner,self.cid)['review_cycle']
        velox._set_checklist_review_state(self.store,self.owner,self.cid,velox.REVIEW_ERROR,error='Endpoint failed',review_cycle=cycle)
        current=self.status(self.cid)
        self.assertTrue(all(i['state']=='done' for i in self.store.all_items(current)))
        self.assertEqual(current['review_error'],'Endpoint failed'); self.assertEqual(self.store.continuation_prompt(self.owner),'')
        self.assertEqual(self.store.prepare_verification(self.owner,self.cid)['review_cycle'],cycle+1)

    def test_export_contains_nested_review_failures_not_just_parent_counts(self) -> None:
        self.review(self.cid,{'C1.2'}); reports=self.store.history_reports(self.owner)
        text=velox.checklist_history_report_markdown('Review',reports)
        for value in ('C1.2','Exercise','Current artifact failed','acceptance withheld'):
            self.assertIn(value,text)

    def test_verdicts_cannot_be_replayed_after_completed_review(self) -> None:
        self.review(self.cid); before=self.raw()
        with self.assertRaises(ValueError): self.store.apply_review(self.owner,self.cid,self.verdicts(self.cid),review_cycle=1)
        self.assertEqual(self.raw(),before)

    def test_private_reasoning_is_not_promoted_to_review_evidence(self) -> None:
        messages=[{'role':'assistant','content':'Claimed success','reasoning_content':'PRIVATE_UNSUPPORTED_HYPOTHESIS'}, {'role':'tool','tool_call_id':'test-1','content':'{"returncode":1,"stderr":"Actual failure"}'}]
        facts='\n'.join(velox._extract_factual_tool_lines(messages))
        self.assertNotIn('PRIVATE_UNSUPPORTED',facts); self.assertNotIn('Claimed success',facts); self.assertIn('Actual failure',facts); self.assertIn('test-1',facts)


class ChecklistDurabilityTests(_NestedChecklistFixture):
    def test_restart_preserves_fixed_plan_and_progress(self) -> None:
        cid=self.create(); self.store.create_subitems(self.owner,cid,'C1',['Work','Test']); self.update(cid,'C1.1','done')
        expected=self.status(cid); actual=velox.ChecklistStore(velox.Storage(velox.AppPaths(self.paths.root_dir))).status(self.owner,cid,include_history=True)
        self.assertEqual(actual,expected)

    def test_chat_and_agent_and_task_run_each_have_one_independent_list(self) -> None:
        cid=self.create(); agents=velox.AgentStore(self.storage); agent=agents.create_agent(self.chat_id,'Bounded work'); owner=velox._agent_checklist_owner(agent)
        first=self.store.create(owner,name='Original acceptance',items=['Agent scope'])
        other=dict(owner,task_run_id=owner['task_run_id']+1); second=self.store.create(other,name='Original acceptance',items=['Later run'])
        self.assertEqual(self.store.active(self.owner)['id'],cid)
        self.assertEqual(self.store.active(owner)['id'],first['checklist_id']); self.assertEqual(self.store.active(other)['id'],second['checklist_id'])

    def test_another_chat_cannot_access_or_mutate_owner_checklist(self) -> None:
        cid=self.create(); before=self.raw(); other=velox._chat_checklist_owner(self.chats.create_chat('Other')['chat_id'])
        with self.assertRaises(ValueError): self.store.status(other,cid)
        with self.assertRaises(ValueError): self.store.update_items(other,cid,[{'item_id':'C1','state':'done','comment':'Wrong owner'}])
        self.assertEqual(self.raw(),before)

    def test_concurrent_first_creation_commits_exactly_one_active_checklist(self) -> None:
        import concurrent.futures
        barrier=threading.Barrier(6)
        def create(i: int) -> Any:
            barrier.wait(timeout=3)
            try: return self.create(name=f'Candidate {i}')
            except ValueError: return None
        with concurrent.futures.ThreadPoolExecutor(max_workers=6) as pool: outcomes=list(pool.map(create,range(6)))
        self.assertEqual(sum(i is not None for i in outcomes),1)
        self.assertEqual(len(self.store.list_checklists(self.owner)['checklists']),1)

    def test_concurrent_one_time_plans_cannot_merge_or_replace(self) -> None:
        import concurrent.futures
        cid=self.create(); barrier=threading.Barrier(4)
        def attach(i: int) -> bool:
            barrier.wait(timeout=3)
            try: self.store.create_subitems(self.owner,cid,'C1',[f'Plan {i}']); return True
            except ValueError: return False
        with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool: outcomes=list(pool.map(attach,range(4)))
        self.assertEqual(outcomes.count(True),1); self.assertEqual(len(self.status(cid)['items'][0]['subitems']),1)

    def test_rejected_plan_or_update_has_no_sidecar_history_changes(self) -> None:
        cid=self.create(); self.store.create_subitems(self.owner,cid,'C1',['Step']); path=self.store._history_path(self.owner); before=path.read_bytes()
        with self.assertRaises(ValueError): self.store.create_subitems(self.owner,cid,'C1',['Replacement'])
        with self.assertRaises(ValueError): self.update(cid,'C1','verified')
        self.assertEqual(path.read_bytes(),before)

    def test_history_sidecar_failure_does_not_undo_canonical_commit(self) -> None:
        cid=self.create()
        with mock.patch(f'{velox.__name__}._append_checklist_jsonl',side_effect=OSError('History disk unavailable')):
            self.update(cid,'C1','in_progress','Durable canonical evidence')
        item=self.status(cid)['items'][0]; self.assertEqual(item['state'],'in_progress')
        self.assertEqual(item['history'][-1]['comment'],'Durable canonical evidence')
        self.assertIn('Durable canonical evidence',velox.checklist_history_report_markdown('Task',self.store.history_reports(self.owner)))

    def test_atomic_snapshot_failure_leaves_previous_bytes_intact(self) -> None:
        cid=self.create(); before=self.raw()
        with mock.patch(f'{velox.__name__}._write_checklist_json',side_effect=OSError('Disk full')):
            with self.assertRaises(OSError): self.update(cid,'C1','done')
        self.assertEqual(self.raw(),before)

    def test_tampered_history_cannot_be_shortened_or_rewritten(self) -> None:
        cid=self.create(); self.update(cid,'C1','in_progress'); saved=self.store.load_collection(self.owner); before=self.raw()
        for mode in ('erase','rewrite'):
            altered=copy.deepcopy(saved); history=altered['checklists'][0]['items'][0]['history']
            if mode=='erase': history.pop()
            else: history[0]['comment']='Rewritten past'
            with self.assertRaises(ValueError): self.store._save(self.owner,altered)
        self.assertEqual(self.raw(),before)

    def test_old_schema_stack_and_parent_fields_are_rejected_not_migrated(self) -> None:
        self.create(); saved=self.store.load_collection(self.owner)
        for kind in ('schema','stack','parent','abandoned','second_open'):
            altered=copy.deepcopy(saved)
            if kind=='schema': altered['schema']='checklist_collection.v296'
            elif kind=='stack': altered['active_stack']=[altered['active_checklist_id']]
            elif kind=='parent': altered['checklists'][0]['parent_checklist_id']='OLD'
            elif kind=='abandoned': altered['checklists'][0]['lifecycle']='abandoned'
            else:
                other=copy.deepcopy(altered['checklists'][0]); other['id']='CL-second'; other['name']='Other'; altered['checklists'].append(other)
            with self.subTest(kind=kind), self.assertRaises(ValueError): self.store._validate(altered)

    def test_corrupt_canonical_snapshot_is_not_treated_as_inactive(self) -> None:
        self.create(); self.store._collection_path(self.owner).write_text('{broken',encoding='utf-8')
        with self.assertRaises(ValueError): self.store.active(self.owner)
        with self.assertRaises(ValueError): self.store.continuation_prompt(self.owner)

    def test_cancelled_tree_keeps_progress_and_no_automatic_continuation(self) -> None:
        cid=self.create(); self.store.create_subitems(self.owner,cid,'C1',['Work']); self.update(cid,'C1.1','done'); before=self.status(cid)['items']
        self.store.cancel_open_by_user(self.owner)
        self.assertEqual(self.status(cid)['items'],before); self.assertEqual(self.store.continuation_prompt(self.owner),'')
        self.assertIsNone(self.store.active(self.owner))

    def test_cancelled_names_remain_reserved_while_new_tasks_are_allowed(self) -> None:
        self.create(); self.store.cancel_open_by_user(self.owner)
        with self.assertRaises(ValueError): self.create()
        cid=self.create(name='New task'); self.assertEqual(self.store.active(self.owner)['id'],cid)

    def test_history_browsing_never_changes_active_execution(self) -> None:
        old=self.create(); self.done(old); self.review(old); active=self.create(name='New task'); before=self.raw()
        self.store.status(self.owner,old,include_history=True); self.store.history_reports(self.owner); self.store.list_checklists(self.owner,include_completed=True)
        self.assertEqual(self.raw(),before); self.assertEqual(self.store.active(self.owner)['id'],active)

    def test_ui_snapshot_carries_nested_state_and_separate_counts(self) -> None:
        cid=self.create(); self.store.create_subitems(self.owner,cid,'C1',['Work','Test']); self.update(cid,'C1.1','done')
        result=self.status(cid)
        self.assertEqual(result['counts']['total'],2); self.assertEqual(result['subitem_counts']['total'],2)
        self.assertEqual(result['subitem_counts']['done'],1); self.assertEqual(result['counts']['done'],0)

    def test_direct_claims_of_verified_state_cannot_be_imported_from_mirror(self) -> None:
        cid=self.create(); adapter=velox.ExpertModeStore.for_chat(self.storage,self.chat_id)
        adapter.path.write_text(json.dumps({'schema':'expert_mode_state.v303','requirements':[{'id':'R1','status':'verified'}]}),encoding='utf-8')
        self.assertEqual(adapter.load()['requirements'][0]['status'],'not_started')
        self.assertEqual(self.status(cid)['counts']['verified'],0)


class AgentRoleIsolationTests(_NestedChecklistFixture):
    def agent(self, subtype: str = 'general') -> dict[str, Any]:
        token=velox._PENDING_AGENT_ROLE.set({'subtype':subtype,'parent_objective':'Bounded owner objective','global_constraints':'Preserve public API'})
        try: return velox.AgentStore(self.storage).create_agent(self.chat_id,'Analyze or implement only the assigned scope.')
        finally: velox._PENDING_AGENT_ROLE.reset(token)

    def test_role_sidecar_roundtrips_only_current_fields(self) -> None:
        agent=self.agent('implementer'); role=velox.AgentRoleStore(self.storage).load(agent['agent_id'])
        self.assertEqual(role['subtype'],'implementer'); self.assertEqual(role['parent_objective'],'Bounded owner objective')
        self.assertEqual(set(role),{'schema','agent_id','subtype','parent_objective','global_constraints','created_at','updated_at'})

    def test_old_assignment_and_parent_metadata_are_rejected(self) -> None:
        agent=self.agent()
        for field in ('assigned_checklist_id','parent_checklist_id','parent_item_id'):
            with self.subTest(field=field), self.assertRaises(ValueError): velox.AgentRoleStore(self.storage).save(agent['agent_id'],{'subtype':'implementer',field:'OLD'})

    def test_default_agent_is_general_without_checklist_links(self) -> None:
        agent=velox.AgentStore(self.storage).create_agent(self.chat_id,'Ordinary task')
        role=velox.AgentRoleStore(self.storage).load(agent['agent_id'])
        self.assertEqual(role['subtype'],'general'); self.assertNotIn('assigned_checklist_id',role)

    def test_invalid_role_and_cross_agent_sidecar_are_rejected(self) -> None:
        agent=self.agent(); roles=velox.AgentRoleStore(self.storage); raw=roles.load(agent['agent_id'])
        with self.assertRaises(ValueError): roles.save(agent['agent_id'],{'subtype':'reviewer'})
        with self.assertRaises(ValueError): roles.validate(raw,agent_id='other-agent')
        raw['schema']='agent_role.v296'
        with self.assertRaises(ValueError): roles.validate(raw,agent_id=agent['agent_id'])

    def test_spawn_schema_no_longer_advertises_assigned_or_parent_ids(self) -> None:
        definition=self.registry.tools['agents_start']
        self.assertEqual(set(definition.parameters['properties']),{'task','agent_subtype','parent_objective','global_constraints'})
        self.assertEqual(tuple(i.name for i in definition.positional_arguments),('task','agent_subtype','parent_objective','global_constraints'))

    def test_native_spawn_arguments_preserve_role_and_objective(self) -> None:
        args=({'task':'Bounded work','agent_subtype':'implementer','parent_objective':'Acceptance','global_constraints':'Read-only input'},)
        clean,kwargs,role=velox._extract_role_arguments(args,{})
        self.assertEqual(clean,({'task':'Bounded work'},)); self.assertEqual(kwargs,{})
        self.assertEqual(role,{'subtype':'implementer','parent_objective':'Acceptance','global_constraints':'Read-only input'})

    def test_role_extraction_rejects_retired_links_in_all_carriers(self) -> None:
        for field in ('assigned_checklist_id','parent_checklist_id','parent_item_id'):
            with self.assertRaises(ValueError): velox._extract_role_arguments(({'task':'Work',field:''},),{})
            with self.assertRaises(ValueError): velox._extract_role_arguments((),{field:'OLD'})

    def test_planner_and_implementer_assignment_require_source_chat_not_source_list(self) -> None:
        for subtype in ('planner','implementer'):
            with self.assertRaises(ValueError): velox._validate_role_assignment(self.storage,(),{},{'subtype':subtype})
            velox._validate_role_assignment(self.storage,(velox.ToolContext(velox.APP_SCOPE_ID,chat_id=self.chat_id),),{},{'subtype':subtype})
        self.assertIsNone(self.store.active(self.owner))

    def test_planner_can_research_and_maintain_own_analysis_checklist(self) -> None:
        for name in ('fs_read','fs_grep','web_search','checklist_create','checklist_subitems_create','checklist_item_update','verify_checklist'):
            self.assertTrue(velox._role_allows_tool('planner',name),name)
        for name in ('fs_write','fs_edit','fs_delete','shell_exec','python_exec','agents_start','checklist_resume'):
            self.assertFalse(velox._role_allows_tool('planner',name),name)

    def test_implementer_can_build_and_review_but_not_spawn_or_resume_chat_history(self) -> None:
        for name in ('fs_read','fs_write','shell_exec','python_exec','checklist_create','checklist_subitems_create','verify_checklist'):
            self.assertTrue(velox._role_allows_tool('implementer',name),name)
        for name in ('agents_start','agents_list','agents_pause','checklist_resume'):
            self.assertFalse(velox._role_allows_tool('implementer',name),name)

    def test_reviewer_filter_excludes_all_checklist_and_agent_tools(self) -> None:
        tools=[{'type':'function','function':{'name':name}} for name in self.registry.tools]
        filtered=velox._filter_reviewer_tools(tools); names={velox._role_tool_name(i) for i in filtered}
        self.assertFalse(set(velox.CHECKLIST_TOOL_NAMES)&names); self.assertFalse(any(n.startswith('agents_') for n in names))
        self.assertIn('fs_read',names); self.assertNotIn('fs_write',names)

    def test_general_role_does_not_filter_normal_task_tools(self) -> None:
        tools=[{'type':'function','function':{'name':name}} for name in self.registry.tools]
        self.assertEqual(velox._filter_role_native_tools(tools,'general'),tools)

    def test_worker_creation_never_copies_or_changes_owner_checklist(self) -> None:
        cid=self.create(); before=self.raw(); agent=self.agent('implementer'); owner=velox._agent_checklist_owner(agent)
        self.assertIsNone(self.store.active(owner)); self.assertEqual(self.raw(),before)
        worker=self.store.create(owner,name='Worker acceptance',items=['Bounded outcome'])
        self.assertNotEqual(worker['checklist_id'],cid); self.assertEqual(self.raw(),before)

    def test_worker_success_does_not_verify_assigning_context(self) -> None:
        self.create(); before=self.raw(); agent=self.agent('implementer'); owner=velox._agent_checklist_owner(agent)
        cid=self.store.create(owner,name='Worker acceptance',items=['Bounded outcome'])['checklist_id']
        self.store.update_items(owner,cid,[{'item_id':'C1','state':'done','comment':'Observed worker result'}]); cycle=self.store.prepare_verification(owner,cid)['review_cycle']
        self.store.apply_review(owner,cid,[{'item_id':'C1','verdict':'pass','comment':'Worker result independently accepted'}],review_cycle=cycle)
        velox.AgentStore(self.storage).update_agent(agent['agent_id'],{'status':'succeeded'})
        self.assertEqual(self.raw(),before); self.assertEqual(self.store.active(self.owner)['items'][0]['state'],'not_started')

    def test_planner_owns_planning_acceptance_not_an_importable_child_list(self) -> None:
        self.create(); before=self.raw(); agent=self.agent('planner'); owner=velox._agent_checklist_owner(agent)
        cid=self.store.create(owner,name='Plan quality',items=['Research and explain the proposed implementation'])['checklist_id']
        self.assertEqual(velox.ExpertModeStore.for_agent(self.storage,agent).load(active_only=True)['checklist_id'],cid)
        self.assertEqual(self.raw(),before); self.assertNotIn('_import_planner_checklist',vars(velox))

    def test_parallel_workers_have_independent_lists_and_never_share_ids(self) -> None:
        self.create(); before=self.raw(); ids=[]
        for _ in range(2):
            agent=self.agent('implementer'); owner=velox._agent_checklist_owner(agent)
            ids.append(self.store.create(owner,name='Bounded work',items=['Deliver assigned file'])['checklist_id'])
        self.assertEqual(len(set(ids)),2); self.assertEqual(self.raw(),before)

    def test_assignment_prompt_contains_only_explicit_bounded_context(self) -> None:
        text=velox._agent_assignment_block({'subtype':'implementer','parent_objective':'Bounded objective','global_constraints':'Preserve API','unrelated_backlog':'SECRET_UNRELATED'})
        self.assertIn('Bounded objective',text); self.assertIn('Preserve API',text); self.assertNotIn('SECRET_UNRELATED',text)
        self.assertIn('owner alone updates',text)

    def test_roles_keep_exclusive_scopes_and_parent_acceptance_authority(self) -> None:
        for phrase in ('implementation source read-only','no list is imported automatically','planning-deliverable acceptance criteria'):
            self.assertIn(phrase,velox._PLANNER_PROMPT)
        for phrase in ('exclusive writable scope','No owner Checklist is shared or copied','same list','does not itself mark'):
            self.assertIn(phrase,velox._IMPLEMENTER_PROMPT)
        for phrase in ('non-overlapping writable','you alone inspect and integrate','complete original contract'):
            self.assertIn(phrase,velox._ORCHESTRATOR_PROMPT)


class NestedReviewerRuntimeTests(unittest.IsolatedAsyncioTestCase):
    asyncSetUp = ReviewerAgentLoopTests.asyncSetUp
    asyncTearDown = ReviewerAgentLoopTests.asyncTearDown
    _verify = ReviewerAgentLoopTests._verify

    def ready_tree(self) -> str:
        cid=self.checklists.create(self.owner,name='Nested acceptance',items=['Original parent'])['checklist_id']
        self.checklists.create_subitems(self.owner,cid,'C1',['First action','Second action'])
        self.checklists.update_items(self.owner,cid,[{'item_id':i,'state':'done','comment':'Current runtime behavior observed'} for i in ('C1','C1.1','C1.2')])
        return cid

    async def test_real_reviewer_receives_and_verifies_all_nested_ids_once(self) -> None:
        cid=self.ready_tree(); result=await self._verify(cid)
        self.assertEqual(result['review_result'],'passed'); self.assertEqual(result['lifecycle'],'completed')
        self.assertTrue(all(i['state']=='verified' for i in self.checklists.all_items(result)))
        self.assertEqual(len(self.llm.requests),1)
        text=json.dumps(self.llm.requests[0].messages)
        for marker in ('C1.1','C1.2','First action','Second action'): self.assertIn(marker,text)
        reviewers=[a for a in self.agents.list_agents(self.chat_id) if velox._is_reviewer_agent(a)]
        self.assertEqual(len(reviewers),1)

    async def test_nested_reviewer_missing_steps_cannot_complete_parent(self) -> None:
        class Endpoint(_ReviewerTestLLM):
            async def chat_completions_once_full(inner,request: LLMRequest) -> dict[str,Any]:
                inner.requests.append(request)
                return {'text':json.dumps({'verdicts':[{'requirement_id':'C1','verdict':'pass','summary':'Parent only','next_step':''}]})+'\n$$AGENT_PROGRESS: {"message":"Review finished","percent":100}', 'finish_reason':'stop'}
        self.runtime.llm=Endpoint(self.storage); cid=self.ready_tree(); result=await self._verify(cid)
        self.assertEqual(result['action'],'review_error')
        current=self.checklists.status(self.owner,cid)
        self.assertEqual(current['lifecycle'],'open'); self.assertTrue(all(i['state']=='done' for i in self.checklists.all_items(current)))

    async def test_failed_step_reopens_parent_and_review_card_names_both(self) -> None:
        class Endpoint(_ReviewerTestLLM):
            async def chat_completions_once_full(inner,request: LLMRequest) -> dict[str,Any]:
                inner.requests.append(request)
                verdicts=[{'requirement_id':i,'verdict':'fail' if i=='C1.2' else 'pass','summary':'Control maps backward' if i=='C1.2' else 'Observed result','next_step':'Repair actual mouse handler' if i=='C1.2' else ''} for i in ('C1','C1.1','C1.2')]
                return {'text':json.dumps({'verdicts':verdicts})+'\n$$AGENT_PROGRESS: {"message":"Review finished","percent":100}', 'finish_reason':'stop'}
        self.runtime.llm=Endpoint(self.storage); cid=self.ready_tree(); result=await self._verify(cid)
        self.assertEqual(result['review_result'],'failed'); self.assertEqual(result['items'][0]['state'],'in_progress')
        failed=json.dumps(result); self.assertIn('C1.2',failed); self.assertIn('Control maps backward',failed)
        self.assertIn('acceptance withheld',failed)

    async def test_real_review_runs_after_canonical_done_without_any_execution_mirror(self) -> None:
        cid=self.ready_tree(); path=velox.ExpertModeStore.for_chat(self.storage,self.chat_id).path
        self.assertFalse(path.exists()); result=await self._verify(cid)
        self.assertEqual(result['lifecycle'],'completed'); self.assertFalse(path.exists())

    async def test_owner_stop_cancels_nested_review_without_reactivating_tree(self) -> None:
        cid=self.ready_tree(); self.llm.mode='gate'; self.llm.entered=asyncio.Event(); self.llm.release=asyncio.Event()
        pending=asyncio.create_task(self._verify(cid)); await asyncio.wait_for(self.llm.entered.wait(),2)
        self.checklists.cancel_open_by_user(self.owner); self.llm.release.set()
        await asyncio.wait_for(pending,3)
        current=self.checklists.status(self.owner,cid)
        self.assertEqual(current['lifecycle'],'cancelled_by_user'); self.assertTrue(all(i['state']=='done' for i in self.checklists.all_items(current)))
        self.assertIsNone(self.checklists.active(self.owner))



class CachedUsageTests(unittest.TestCase):
    def test_chat_completions_and_responses_hit_fields(self) -> None:
        for total_key, detail_key in (("prompt_tokens", "prompt_tokens_details"), ("input_tokens", "input_tokens_details")):
            for hits in (0, 41, 100):
                with self.subTest(total_key=total_key, hits=hits):
                    usage = {total_key: 100, detail_key: {"cached_tokens": hits, "cache_write_tokens": 29}}
                    self.assertEqual(velox.cached_input_tokens_from_usage({"usage": usage}), hits)
                    self.assertEqual(velox.llm_cache_usage_summary(usage)["cache_reported_rounds"], 1)

    def test_deepseek_cache_hits_are_not_added_to_total_or_misses(self) -> None:
        u = {"prompt_tokens": 100, "prompt_cache_hit_tokens": 73, "prompt_cache_miss_tokens": 27}
        self.assertEqual(velox.cached_input_tokens_from_usage(u), 73)
        summary = velox.llm_cache_usage_summary(u)
        self.assertEqual(summary["cache_reported_input_tokens"], 100)
        self.assertEqual(summary["cached_input_tokens"], 73)

    def test_aliases_represent_one_count_not_multiple_caches(self) -> None:
        u = {"prompt_tokens": 100, "prompt_cache_hit_tokens": 60,
             "prompt_tokens_details": {"cached_tokens": 60}, "input_tokens_details": {"cached_tokens": 60}}
        self.assertEqual(velox.cached_input_tokens_from_usage({"usage": u, "raw": {"usage": u}}), 60)

    def test_absent_cache_and_cache_writes_are_not_zero_hit_reports(self) -> None:
        for u in ({}, {"prompt_tokens": 100}, {"prompt_tokens": 100, "cache_creation_input_tokens": 50},
                  {"input_tokens": 100, "input_tokens_details": {"cache_write_tokens": 50}},
                  {"prompt_tokens": 100, "output_tokens_details": {"cached_tokens": 50}}):
            with self.subTest(usage=u):
                self.assertIsNone(velox.cached_input_tokens_from_usage(u))
                self.assertEqual(velox.llm_cache_usage_summary(u)["cache_reported_rounds"], 0)

    def test_invalid_provider_counts_never_become_hits(self) -> None:
        for bad in (True, False, -1, 1.2, float("nan"), float("inf"), "1.5", "-1", "x", {}, [], None, 101):
            with self.subTest(value=bad):
                self.assertIsNone(velox.cached_input_tokens_from_usage({"prompt_tokens": 100, "prompt_tokens_details": {"cached_tokens": bad}}))

    def test_raw_usage_snapshot_merges_without_mutation_or_repetition(self) -> None:
        first = {"prompt_tokens": 100, "prompt_tokens_details": {"cached_tokens": 40}, "completion_tokens": 8}
        before = copy.deepcopy(first)
        merged = velox.update_llm_usage_snapshot(first, {"prompt_tokens_details": {"audio_tokens": 5}})
        merged = velox.update_llm_usage_snapshot(merged, {"prompt_tokens_details": {"cached_tokens": None}})
        merged = velox.update_llm_usage_snapshot(merged, {"usage": None})
        merged = velox.update_llm_usage_snapshot(merged, {})
        self.assertEqual(first, before)
        self.assertEqual(merged["prompt_tokens_details"], {"cached_tokens": 40, "audio_tokens": 5})
        self.assertEqual(velox.cached_input_tokens_from_usage(velox.update_llm_usage_snapshot(merged, merged)), 40)
        self.assertEqual(velox.cached_input_tokens_from_usage(velox.update_llm_usage_snapshot(merged, {"prompt_tokens_details": {"cached_tokens": 0}})), 0)

    def test_mixed_transport_rounds_sum_once_and_preserve_coverage(self) -> None:
        rounds = [
            {"prompt_tokens": 100, "completion_tokens": 10, "prompt_tokens_details": {"cached_tokens": 40}},
            {"input_tokens": 200, "output_tokens": 20, "input_tokens_details": {"cached_tokens": 160}},
            {"prompt_tokens": 50, "completion_tokens": 5},
            {"prompt_tokens": 20, "completion_tokens": 2, "prompt_cache_hit_tokens": 0},
        ]
        usage = {"_estimated_prompt_tokens": 1000, "_section_timing": []}
        for current in rounds:
            usage = velox.merge_llm_usage(usage, current)
        self.assertEqual(velox._request_usage_token_values(usage), (370, 37))
        self.assertEqual(velox.llm_cache_usage_summary(usage), {
            "cached_input_tokens": 200, "cache_reported_input_tokens": 320,
            "cache_reported_rounds": 3, "cache_total_rounds": 4})

    def test_pre_request_estimate_does_not_create_a_phantom_cache_round(self) -> None:
        usage = velox.merge_llm_usage({"_estimated_prompt_tokens": 500}, {"prompt_tokens": 100, "prompt_cache_hit_tokens": 100})
        self.assertEqual(velox.llm_cache_usage_summary(usage)["cache_total_rounds"], 1)
        self.assertNotIn("subset", velox.cached_input_label({"input_tokens": 100, **velox.llm_cache_usage_summary(usage)}))

    def test_zero_unknown_and_partial_labels_are_distinct(self) -> None:
        self.assertEqual(velox.cached_input_label({"input_tokens": 100}), "N/A")
        zero = {"input_tokens": 100, **velox.llm_cache_usage_summary({"prompt_tokens": 100, "prompt_cache_hit_tokens": 0})}
        self.assertEqual(velox.cached_input_label(zero), "0 [0.0%]")
        partial = {"input_tokens": 200, "cached_input_tokens": 50, "cache_reported_rounds": 1, "cache_total_rounds": 2}
        self.assertEqual("50 [25.0%]", velox.cached_input_label(partial))
        self.assertIn("lower bound", velox.cached_input_tooltip(partial))
        self.assertIn("no usable provider cache-hit count", velox.cached_input_tooltip({"input_tokens": 100}))

    def test_zero_input_does_not_divide_by_zero(self) -> None:
        metrics = {"input_tokens": 0, **velox.llm_cache_usage_summary({"prompt_tokens": 0, "prompt_cache_hit_tokens": 0})}
        self.assertEqual(velox.cached_input_label(metrics), "0 [0.0%]")

    def test_partial_details_wait_for_total_before_displaying_ratio(self) -> None:
        usage = {"prompt_tokens_details": {"cached_tokens": 100}}
        self.assertEqual(velox.cached_input_tokens_from_usage(usage), 100)
        self.assertEqual(velox.llm_cache_usage_summary(usage)["cache_reported_rounds"], 0)
        usage = velox.update_llm_usage_snapshot(usage, {"prompt_tokens": 150})
        self.assertEqual(velox.llm_cache_usage_summary(usage)["cached_input_tokens"], 100)


