class TokenDashboardTests(_StorageFixture):
    def task(self) -> str:
        return self.monitor.start(velox.APP_SCOPE_ID, "Test accounting", task_kind="chat")

    def test_live_estimate_reconciles_cached_input_by_delta(self) -> None:
        tid = self.task()
        self.monitor.set_inference_round_metrics(tid, "r", input_tokens=500, output_tokens=0, estimated=True)
        self.monitor.set_inference_round_metrics(tid, "r", input_tokens=100, output_tokens=10, cached_input_tokens=80)
        self.monitor.set_inference_round_metrics(tid, "r", input_tokens=120, output_tokens=12, cached_input_tokens=90, final=True)
        self.monitor.set_inference_round_metrics(tid, "r", input_tokens=120, output_tokens=12, cached_input_tokens=90, final=True)
        row = self.monitor.record_snapshot(tid)
        self.assertEqual((row["input_tokens"], row["output_tokens"], row["cached_input_tokens"]), (120, 12, 90))
        self.assertEqual((row["cache_reported_rounds"], row["cache_total_rounds"]), (1, 1))
        self.assertEqual(self.monitor.statistics()["total_tokens"], 132)

    def test_missing_late_cache_detail_preserves_previous_report(self) -> None:
        tid = self.task()
        self.monitor.set_inference_round_metrics(tid, "r", input_tokens=100, cached_input_tokens=60)
        self.monitor.set_inference_round_metrics(tid, "r", input_tokens=100, final=True)
        self.assertEqual(self.monitor.record_snapshot(tid)["cached_input_tokens"], 60)

    def test_reported_zero_corrects_earlier_count(self) -> None:
        tid = self.task()
        self.monitor.set_inference_round_metrics(tid, "r", input_tokens=100, cached_input_tokens=60)
        self.monitor.set_inference_round_metrics(tid, "r", input_tokens=100, cached_input_tokens=0, final=True)
        row = self.monitor.record_snapshot(tid)
        self.assertEqual(row["cached_input_tokens"], 0); self.assertEqual(row["cache_reported_rounds"], 1)

    def test_invalid_cache_count_cannot_exceed_total(self) -> None:
        tid = self.task()
        self.monitor.set_inference_round_metrics(tid, "r", input_tokens=10, cached_input_tokens=11, final=True)
        row = self.monitor.record_snapshot(tid)
        self.assertEqual(row["input_tokens"], 10); self.assertEqual(row["cache_reported_rounds"], 0)

    def test_task_coverage_isolated_and_statistics_include_all_requests(self) -> None:
        a, b = self.task(), self.task()
        self.monitor.add_inference_metrics(a, input_tokens=100, output_tokens=10, cached_input_tokens=80)
        self.monitor.add_inference_metrics(b, input_tokens=200, output_tokens=20)
        self.monitor.set_inference_round_metrics(a, "next", input_tokens=100, output_tokens=10, cached_input_tokens=0, final=True)
        totals = self.monitor.statistics()
        self.assertEqual((totals["input_tokens"], totals["cached_input_tokens"]), (400, 80))
        self.assertEqual((totals["cache_reported_rounds"], totals["cache_total_rounds"]), (2, 3))
        self.assertEqual(self.monitor.record_snapshot(b)["cache_reported_rounds"], 0)

    def test_input_cell_has_exact_count_and_percentage_without_changing_sort(self) -> None:
        tid = self.task(); self.monitor.add_inference_metrics(tid, input_tokens=2000, output_tokens=10, cached_input_tokens=1500)
        panel = object.__new__(velox.Panels); panel._dashboard_task_context_menu_items = lambda row: []
        row = panel._dashboard_live_task_row(self.monitor.record_snapshot(tid))
        self.assertEqual(row["input_tokens"]["label"], "2,000")
        self.assertEqual(row["input_tokens"]["sort"], 2000)
        self.assertIn("Cached Input: 1,500 [75.0%]", row["_tooltip"])
        self.assertTrue(row["_tooltip_all_cells"])

    def test_input_cell_unknown_is_not_a_false_zero(self) -> None:
        tid = self.task(); self.monitor.add_inference_metrics(tid, input_tokens=100)
        panel = object.__new__(velox.Panels); panel._dashboard_task_context_menu_items = lambda row: []
        row = panel._dashboard_live_task_row(self.monitor.record_snapshot(tid))
        self.assertIn("Cached Input: N/A", row["_tooltip"]); self.assertNotIn("0.0%", row["_tooltip"])

    def test_agent_current_schema_persists_cache_counters_and_rejects_inconsistent_counts(self) -> None:
        store = velox.AgentStore(self.storage); agent = store.create_agent(self.cid, "Count usage")
        patch = {"input_tokens": 100, "output_tokens": 10,
                 **velox.llm_cache_usage_summary({"prompt_tokens": 100, "prompt_tokens_details": {"cached_tokens": 75}})}
        store.update_agent(agent["agent_id"], patch)
        saved = velox.AgentStore(self.storage).load_agent(agent["agent_id"])
        self.assertEqual(saved["cached_input_tokens"], 75)
        broken = copy.deepcopy(saved); broken["cached_input_tokens"] = 101
        with self.assertRaisesRegex(ValueError, "Inconsistent cached input"):
            velox.validate_agent_record(broken)
        self.assertEqual(velox.agent_task_statistics(saved)["cached_input_tokens"], 75)

    def test_chat_turn_stats_and_aggregate_survive_storage_roundtrip(self) -> None:
        runtime = velox.ChatRuntime.__new__(velox.ChatRuntime)
        usage = velox.merge_llm_usage({}, {"input_tokens": 120, "output_tokens": 12, "input_tokens_details": {"cached_tokens": 100}})
        turn = velox.make_turn(self.cid, "assistant", "Result")
        turn["stats"] = runtime._make_stats(time.time()-1, time.time()-0.5, "Result", [], usage)
        self.chats.append_turn(velox.APP_SCOPE_ID, self.cid, turn)
        stored = velox.ChatStore(self.storage).load_turns(velox.APP_SCOPE_ID, self.cid)
        self.assertEqual(stored[-1]["stats"]["cached_input_tokens"], 100)
        aggregate = velox.chat_thread_runtime_stats(stored)
        self.assertEqual(aggregate["cached_input_tokens"], 100); self.assertEqual(aggregate["input_tokens"], 120)

    def test_summary_card_keeps_cached_input_out_of_token_ring_and_in_bounds(self) -> None:
        panel = object.__new__(velox.Panels); panel.widgets = ChecklistRenderingTests.widgets(); panel.state = panel.widgets.state
        panel.services = SimpleNamespace(monitor=self.monitor)
        seen = []; rings = []; cards = []
        original_card = panel._draw_agent_metric_card
        def card(rect: velox.Rect, title: str) -> velox.Rect:
            body = original_card(rect, title); cards.append((title, body)); return body
        panel._draw_agent_metric_card = card
        panel._draw_ring_chart = lambda rect, values, **kw: rings.append(values)
        panel.widgets.clipped_text = lambda rect, text, *args, **kw: seen.append((rect, text, kw))
        data = {"input_tokens": 1000, "output_tokens": 100, "total_tokens": 1100,
                "cached_input_tokens": 750, "cache_reported_rounds": 1, "cache_total_rounds": 1,
                "checklist_statistics": {"status": "ready", **dict.fromkeys(velox.ChecklistStatisticsCache.FIELDS, 0)}}
        for width in (500, 900, 1600, 2500):
            seen.clear(); rings.clear(); cards.clear()
            panel._draw_agent_summary_cards(velox.Rect(0, 0, width, 1400), data)
            self.assertEqual([v for v, _ in rings[0]], [1000, 100])
            body = next(rect for title, rect in cards if title == "Token usage")
            cache = next((rect, text) for rect, text, _ in seen if text.startswith("Cached Input"))
            self.assertIn("750 [75.0%]", " ".join(text for _rect, text, _kw in seen))
            self.assertTrue(body.y <= cache[0].y and cache[0].y + cache[0].h <= body.y + body.h)
            self.assertGreater(cache[0].x, body.x)
            self.assertLess(cache[0].w, body.w)
            self.assertIn("Checklist statistics", [title for title, _ in cards])
            self.assertNotIn("Inference throughput", [title for title, _ in cards])


class SkillModesTests(_AsyncRuntimeFixture):
    def store(self) -> SkillStore:
        return self.tools.skill_store

    def add_skill(self, name: str = "Quality fixture") -> None:
        self.store().create_skill(name)
        self.store().save_skill_text(name, "Fixture catalog description.\n\nUnique fixture instructions. Check observable results.")

    def test_default_modes_are_explicit_and_quality_skill_is_seeded(self) -> None:
        rows = self.store().list_skills(refresh=True)
        self.assertEqual(len(rows), 17)
        self.assertEqual({r["name"] for r in rows if r["mode"] == "always"}, set(velox.DEFAULT_ALWAYS_SKILL_NAMES))
        self.assertTrue(all(r["mode"] in velox.SKILL_MODES for r in rows))
        self.assertEqual(self.store().load_skill(velox.DEFAULT_HIGH_EFFORT_SKILL_NAME)["instructions"], velox.DEFAULT_HIGH_EFFORT_SKILL_MARKDOWN)

    def test_new_custom_skill_defaults_optional(self) -> None:
        self.add_skill(); row = self.store()._resolve_skill("Quality fixture")[0]
        self.assertEqual(row["mode"], "optional"); self.assertTrue(row["enabled"])

    def test_all_modes_persist_across_store_restart(self) -> None:
        self.add_skill()
        for mode in velox.SKILL_MODES:
            with self.subTest(mode=mode):
                self.store().set_mode("Quality fixture", mode)
                row = velox.SkillStore(self.storage)._resolve_skill("Quality fixture")[0]
                self.assertEqual(row["mode"], mode); self.assertEqual(row["enabled"], mode != "disable")
                payload = velox.read_json(Path(row["directory"]) / velox.SKILL_MODE_FILE_NAME)
                self.assertEqual(payload, {"schema": velox.SKILL_MODE_SCHEMA, "mode": mode})

    def test_invalid_modes_rejected_without_changing_existing_mode(self) -> None:
        self.add_skill()
        for mode in ("enabled", "disabled", "Always", "", None, True):
            with self.subTest(mode=mode), self.assertRaises(ValueError):
                self.store().set_mode("Quality fixture", mode)
        self.assertEqual(self.store()._resolve_skill("Quality fixture")[0]["mode"], "optional")

    def test_foreign_mode_schema_fails_instead_of_migrating(self) -> None:
        self.add_skill(); _, directory = self.store()._resolve_skill("Quality fixture")
        (directory/velox.SKILL_MODE_FILE_NAME).write_text(json.dumps({"schema": "velox_skill_mode.v297", "mode": "always"}), encoding="utf-8")
        with self.assertRaises(velox.UnsupportedDataVersionError): self.store().list_skills(refresh=True)

    def test_sidecar_is_not_exposed_as_a_supporting_file(self) -> None:
        self.add_skill(); self.store().set_mode("Quality fixture", "always")
        loaded = self.store().load_skill("Quality fixture")
        self.assertNotIn(velox.SKILL_MODE_FILE_NAME, loaded["supporting_files"])

    def test_always_is_loaded_once_in_initial_chat_prefix(self) -> None:
        self.add_skill(); self.store().set_mode("Quality fixture", "always"); self.user()
        messages = self.messages(); prompt = messages[0]["content"]
        self.assertEqual(prompt.count("===== Already loaded Task skill: Quality fixture ====="), 1)
        self.assertEqual(prompt.count("Unique fixture instructions."), 1)
        again = self.messages(); self.assertEqual(prompt, again[0]["content"])

    def test_optional_is_catalogued_without_its_body(self) -> None:
        self.add_skill(); self.user(); prompt = self.messages()[0]["content"]
        self.assertIn("* Quality fixture", prompt)
        self.assertNotIn("===== Already loaded Task skill: Quality fixture", prompt)
        # The concise first-line catalog is allowed; the body is absent.
        self.store().save_skill_text("Quality fixture", "Catalog description.\n\nPRIVATE_BODY_SENTINEL")
        new_chat = self.chats.create_chat("New optional")
        self.chats.append_turn(velox.APP_SCOPE_ID, new_chat["chat_id"], velox.make_turn(new_chat["chat_id"], "user", "Request"))
        self.assertNotIn("PRIVATE_BODY_SENTINEL", self.runtime._build_messages(velox.APP_SCOPE_ID, new_chat["chat_id"])[0]["content"])

    async def test_disabled_is_not_catalogued_or_loadable(self) -> None:
        self.add_skill(); self.store().set_mode("Quality fixture", "disable"); self.user()
        self.assertNotIn("Quality fixture", self.messages()[0]["content"])
        with self.assertRaises(PermissionError):
            await self.tools.tool_skills_load(velox.ToolContext(velox.APP_SCOPE_ID, chat_id=self.cid), {"names": ["Quality fixture"]})

    async def test_optional_loads_on_demand_with_actual_instructions(self) -> None:
        self.add_skill(); self.user(); self.messages()
        result = await self.tools.tool_skills_load(velox.ToolContext(velox.APP_SCOPE_ID, chat_id=self.cid), {"names": ["Quality fixture"]})
        self.assertEqual(result["loaded_count"], 1); self.assertIn("Unique fixture instructions", result["skills"][0]["instructions"])

    async def test_always_dedup_uses_frozen_prefix_not_later_settings(self) -> None:
        self.add_skill(); self.store().set_mode("Quality fixture", "always"); self.user(); initial = self.messages()[0]["content"]
        self.store().set_mode("Quality fixture", "optional")
        self.store().save_skill_text("Quality fixture", "CHANGED_AFTER_START")
        result = await self.tools.tool_skills_load(velox.ToolContext(velox.APP_SCOPE_ID, chat_id=self.cid), {"names": ["Quality fixture"]})
        self.assertEqual(result["loaded_count"], 0); self.assertEqual(result["already_loaded_names"], ["Quality fixture"])
        self.user("Follow-up"); self.assertEqual(self.messages()[0]["content"], initial)

    async def test_new_always_setting_does_not_falsely_claim_old_thread_loaded_it(self) -> None:
        self.add_skill(); self.user(); initial = self.messages()[0]["content"]
        self.store().set_mode("Quality fixture", "always")
        result = await self.tools.tool_skills_load(velox.ToolContext(velox.APP_SCOPE_ID, chat_id=self.cid), {"names": ["Quality fixture"]})
        self.assertEqual(result["loaded_count"], 1); self.assertFalse(result["already_loaded_names"])
        self.assertEqual(self.messages()[0]["content"], initial)

    async def test_duplicate_names_in_one_load_do_not_repeat_instructions(self) -> None:
        self.add_skill(); self.user(); self.messages()
        result = await self.tools.tool_skills_load(velox.ToolContext(velox.APP_SCOPE_ID, chat_id=self.cid), {"names": ["Quality fixture", "QUALITY FIXTURE"]})
        self.assertEqual(result["loaded_count"], 1)

    def test_always_body_loads_even_when_optional_tool_categories_are_off(self) -> None:
        self.add_skill(); self.store().set_mode("Quality fixture", "always")
        block = self.tools.build_skill_system_block(velox.APP_SCOPE_ID, self.cid, feature_overrides={k: False for k in velox.CHAT_TOOL_FEATURE_KEYS})
        self.assertIn("===== Already loaded Task skill: Quality fixture", block)
        self.assertIn("System tools are disabled", block)
        self.assertNotIn("Enabled skills:", block)

    def test_over_budget_always_skill_fails_new_prefix_not_old_context(self) -> None:
        self.add_skill(); self.user(); old = self.messages()[0]["content"]
        self.store().set_mode("Quality fixture", "always")
        config = self.storage.load_config(); config["tools"]["skill_combined_instruction_max_chars"] = 40; self.storage.write_config(config)
        self.assertEqual(self.messages()[0]["content"], old)
        with self.assertRaisesRegex(ValueError, "Always Skill"):
            self.tools.build_skill_system_block(velox.APP_SCOPE_ID, self.cid)

    def test_always_applies_to_new_general_agents_and_reviewers(self) -> None:
        self.add_skill(); self.store().set_mode("Quality fixture", "always")
        agent = self.agents.create_agent(self.cid, "Bounded work", endpoint_profile_id=self.eid)
        self.assertIn("===== Already loaded Task skill: Quality fixture", self.aruntime.build_system_prompt(agent))
        with mock.patch.dict(self.aruntime.build_standard_system_prompt.__func__.__globals__, {}):
            with mock.patch(velox.__name__ + "._is_reviewer_agent", return_value=True):
                prompt = self.aruntime.build_system_prompt(agent)
        self.assertIn("===== Already loaded Task skill: Quality fixture", prompt)
        self.assertIn(velox.REVIEW_EVIDENCE_GUIDANCE, prompt)
        self.assertIn("Keep project source read-only", prompt)

    def test_settings_uses_one_mode_dropdown_and_no_status_button(self) -> None:
        panel = object.__new__(velox.Panels); panel.widgets = ChecklistRenderingTests.widgets(); panel.state = panel.widgets.state
        panel.services = SimpleNamespace(storage=self.storage, tools=self.tools)
        with mock.patch.object(panel.widgets, "table_view", return_value=(None, None)) as table:
            panel._draw_skills_settings_content(velox.Rect(0, 0, 1100, 1400))
        columns, rows = table.call_args.args[2:4]
        self.assertIn("mode", [c["key"] for c in columns]); self.assertNotIn("status", [c["key"] for c in columns])
        self.assertNotIn("action", [c["key"] for c in columns])
        self.assertEqual(rows[0]["mode"]["options"], ["Disable", "Optional", "Always"])
        self.assertEqual(rows[0]["mode"]["type"], "dropdown")

    def test_settings_dropdown_selection_persists_mode(self) -> None:
        self.add_skill()
        panel = object.__new__(velox.Panels); panel.widgets = ChecklistRenderingTests.widgets(); panel.state = panel.widgets.state
        panel.services = SimpleNamespace(storage=self.storage, tools=self.tools)
        with mock.patch.object(panel.widgets, "table_view", return_value=("Quality fixture", ("Quality fixture", "mode:always"))):
            panel._draw_skills_settings_content(velox.Rect(0, 0, 1100, 1400))
        self.assertEqual(self.store()._resolve_skill("Quality fixture")[0]["mode"], "always")


class ChecklistStatisticsTests(_StorageFixture):
    def make_list(self, owner: dict[str, Any] | None = None, name: str = "Outcomes", count: int = 2) -> str:
        return self.store.create(owner or self.owner, name=name, items=[f"Outcome {i}" for i in range(count)])["checklist_id"]

    def test_empty_root_has_zero_counts_and_no_fabricated_averages(self) -> None:
        result = velox.ChecklistStatisticsCache(self.storage).read()
        self.assertEqual(result["status"], "ready"); self.assertEqual(result["checklists"], 0)
        for key in ("avg_requirements", "avg_subitems", "avg_subitems_per_requirement", "planned_percent"):
            self.assertIsNone(result[key])

    def test_exact_top_level_subitem_averages_include_trivial_zero_step_items(self) -> None:
        cid = self.make_list(count=3); self.store.create_subitems(self.owner, cid, "C1", ["Build", "Exercise", "Inspect"])
        result = velox.ChecklistStatisticsCache(self.storage).read()
        self.assertEqual((result["checklists"], result["requirements"], result["subitems"]), (1, 3, 3))
        self.assertEqual((result["avg_requirements"], result["avg_subitems"], result["avg_subitems_per_requirement"]), (3, 3, 1))
        self.assertAlmostEqual(result["planned_percent"], 100/3)

    def test_cancelled_history_and_new_active_list_are_counted_once(self) -> None:
        cid = self.make_list(count=2); self.store.create_subitems(self.owner, cid, "C1", ["Build", "Test"])
        self.store.cancel_open_by_user(self.owner)
        self.make_list(name="Repair", count=1)
        result = velox.ChecklistStatisticsCache(self.storage).read()
        self.assertEqual((result["checklists"], result["active"], result["cancelled"]), (2, 1, 1))
        self.assertEqual((result["avg_requirements"], result["avg_subitems"]), (1.5, 1.0))

    def test_completed_lists_remain_in_statistics(self) -> None:
        cid = self.make_list(count=1)
        self.store.update_items(self.owner, cid, [{"item_id": "C1", "state": "done", "comment": "Observed result"}])
        cycle = self.store.prepare_verification(self.owner, cid)["review_cycle"]
        self.store.apply_review(self.owner, cid, [{"item_id": "C1", "verdict": "pass", "comment": "Independently observed"}], review_cycle=cycle)
        result = velox.ChecklistStatisticsCache(self.storage).read()
        self.assertEqual((result["checklists"], result["active"], result["completed"]), (1, 0, 1))

    def test_chat_and_agent_owners_have_independent_list_counts(self) -> None:
        self.make_list(count=2)
        agent = velox.AgentStore(self.storage).create_agent(self.cid, "Worker")
        owner = velox._agent_checklist_owner(agent); cid = self.make_list(owner=owner, name="Worker", count=1)
        self.store.create_subitems(owner, cid, "C1", ["Action"])
        result = velox.ChecklistStatisticsCache(self.storage).read()
        self.assertEqual((result["checklists"], result["requirements"], result["subitems"]), (2, 3, 1))

    def test_unchanged_collection_reuses_counts_without_reparsing(self) -> None:
        self.make_list(); reader = velox.ChecklistStatisticsCache(self.storage); before = reader.read()
        with mock.patch.object(velox.ChecklistStore, "_validate", side_effect=AssertionError("unchanged file parsed again")):
            self.assertEqual(reader.read(), before)

    def test_changed_steps_invalidate_cached_counts(self) -> None:
        cid = self.make_list(); reader = velox.ChecklistStatisticsCache(self.storage); self.assertEqual(reader.read()["subitems"], 0)
        self.store.create_subitems(self.owner, cid, "C1", ["Action", "Validate"])
        self.assertEqual(reader.read()["subitems"], 2)

    def test_deleted_owner_disappears_from_statistics(self) -> None:
        self.make_list(); reader = velox.ChecklistStatisticsCache(self.storage); self.assertEqual(reader.read()["checklists"], 1)
        self.chats.delete_chat(velox.APP_SCOPE_ID, self.cid)
        self.assertEqual(reader.read()["checklists"], 0)

    def test_corrupt_collection_does_not_silently_become_partial_average(self) -> None:
        self.make_list(); reader = velox.ChecklistStatisticsCache(self.storage); reader.read()
        self.store._collection_path(self.owner).write_text('{"schema":"wrong"}', encoding="utf-8")
        with self.assertRaises((ValueError, velox.UnsupportedDataVersionError)): reader.read()

    def test_maximum_plan_counts_do_not_flatten_steps_into_requirements(self) -> None:
        items = [{"subitems": [{} for _ in range(100)]} for _ in range(100)]
        counts = velox.ChecklistStatisticsCache.collection_counts({"checklists": [{"lifecycle": "open", "items": items}]})
        self.assertEqual(counts["requirements"], 100); self.assertEqual(counts["subitems"], 10000)


class ChecklistStatsAsyncTests(_AsyncRuntimeFixture):
    def panel(self) -> Panels:
        panel = object.__new__(velox.Panels); panel.services = SimpleNamespace(storage=self.storage)
        panel._observe_background_task = lambda task: None
        return panel

    async def test_idle_frames_use_one_background_read(self) -> None:
        panel = self.panel(); entered = threading.Event(); release = threading.Event(); calls = []; main = threading.get_ident()
        def slow(reader: Any) -> dict[str, Any]:
            calls.append(threading.get_ident()); entered.set()
            if not release.wait(3): raise TimeoutError("stats fixture")
            return {"status": "ready", "checklists": 7}
        with mock.patch.object(velox.ChecklistStatisticsCache, "read", slow):
            self.assertEqual(panel._dashboard_checklist_statistics()["status"], "loading")
            try:
                self.assertTrue(await asyncio.to_thread(entered.wait, 2))
                for _ in range(100): self.assertEqual(panel._dashboard_checklist_statistics()["status"], "loading")
                self.assertEqual(len(calls), 1); self.assertNotEqual(calls[0], main)
            finally:
                release.set(); await panel._checklist_statistics_entry["task"]
            self.assertEqual(panel._dashboard_checklist_statistics()["checklists"], 7)
            for _ in range(100): panel._dashboard_checklist_statistics()
            self.assertEqual(len(calls), 1)

    async def test_background_read_error_is_visible_not_zero(self) -> None:
        panel = self.panel()
