class CacheHTTPTests(_AsyncRuntimeFixture):
    async def exercise(self, transport: str, stream: bool, hits: int | None = 75) -> None:
        import http.server
        errors = []; requests = []
        usage = ({"input_tokens": 100, "output_tokens": 4, "total_tokens": 104}
                 if transport == "responses" else {"prompt_tokens": 100, "completion_tokens": 4, "total_tokens": 104})
        if hits is not None:
            usage["input_tokens_details" if transport == "responses" else "prompt_tokens_details"] = {"cached_tokens": hits}
        response = ({"id": "r_cache", "object": "response", "status": "completed", "usage": usage,
                     "output": [{"id": "msg_cache", "type": "message", "role": "assistant", "content": [{"type": "output_text", "text": "Cache result."}]}]}
                    if transport == "responses" else {"id": "cc_cache", "object": "chat.completion", "usage": usage,
                     "choices": [{"index": 0, "message": {"role": "assistant", "content": "Cache result."}, "finish_reason": "stop"}]})
        if stream:
            event = ({"type": "response.completed", "response": response} if transport == "responses" else
                     {"id": "cc_cache", "usage": usage, "choices": [{"index": 0, "delta": {"content": "Cache result."}, "finish_reason": "stop"}]})
            body = b'data: ' + json.dumps(event).encode() + b'\n\ndata: [DONE]\n\n'
        else:
            body = json.dumps(response).encode()
        class Handler(http.server.BaseHTTPRequestHandler):
            def log_message(self, *args: Any) -> None: pass
            def do_POST(self) -> None:
                try:
                    requests.append(json.loads(self.rfile.read(int(self.headers["Content-Length"]))))
                    self.send_response(200); self.send_header("Content-Type", "text/event-stream" if stream else "application/json")
                    self.send_header("Content-Length", str(len(body))); self.end_headers()
                    self.wfile.write(body); self.wfile.flush()
                except Exception as exc: errors.append(str(exc))
        server = http.server.ThreadingHTTPServer(("127.0.0.1", 0), Handler); server.daemon_threads = True
        thread = threading.Thread(target=lambda: server.serve_forever(poll_interval=.01), daemon=True); thread.start()
        cfg = self.storage.load_config(); profile = velox.endpoint_profile_ref(cfg, self.eid)
        profile.update(api_transport=transport, provider="generic", base_url=f"http://127.0.0.1:{server.server_port}/v1",
                       api_key="", rate_limit_enabled=False, error_recovery_enabled=False, adaptive_token_estimation=False)
        self.storage.write_config(cfg)
        monitor = velox.LLMTaskMonitor(self.storage); scheduler = velox.EndpointInferenceScheduler(self.storage, self.llm.resolve_endpoint, monitor)
        self.llm.bind_request_scheduler(scheduler, monitor)
        tid = monitor.start(velox.APP_SCOPE_ID, "Cache HTTP", task_kind="chat")
        try:
            req = velox.LLMRequest(velox.APP_SCOPE_ID, self.eid, [{"role": "user", "content": "Verify accounting"}], stream=stream,
                             monitor_task_id=tid, task_kind="chat")
            method = self.llm.chat_completions_stream_full if stream else self.llm.chat_completions_once_full
            result = await asyncio.wait_for(method(req), 8)
            self.assertEqual(errors, []); self.assertEqual(len(requests), 1)
            self.assertIn("Cache result.", result["text"])
            row = monitor.record_snapshot(tid)
            self.assertEqual((row["input_tokens"], row["output_tokens"]), (100, 4))
            self.assertEqual(row["cached_input_tokens"], hits or 0)
            self.assertEqual(row["cache_reported_rounds"], int(hits is not None))
            self.assertEqual(row["cache_total_rounds"], 1)
            self.assertEqual(monitor.statistics()["total_tokens"], 104)
            self.assertEqual(velox.cached_input_tokens_from_usage(result), hits)
        finally:
            monitor.complete(tid); await scheduler.close()
            await asyncio.to_thread(server.shutdown); server.server_close(); await asyncio.to_thread(thread.join, 2)
            self.assertFalse(thread.is_alive())

    async def test_chat_completions_nonstream_real_http(self) -> None:
        await self.exercise("chat_completions", False)
    async def test_chat_completions_stream_real_http(self) -> None:
        await self.exercise("chat_completions", True)
    async def test_responses_nonstream_real_http(self) -> None:
        await self.exercise("responses", False)
    async def test_responses_stream_real_http(self) -> None:
        await self.exercise("responses", True)
