    def test_copies_and_branches_preserve_disabled_policy_instead_of_new_chat_defaults(self) -> None:
        self.chats.set_chat_feature(velox.APP_SCOPE_ID,self.cid,'checklists_enabled',False)
        self.chats.set_chat_feature(velox.APP_SCOPE_ID,self.cid,'system_tools_enabled',False)
