            self.assertTrue(self.chats.is_chat_endpoint_locked(copied['chat_id']))
            tools=velox.ToolRegistry(self.storage).build_openai_chat_completion_tools(velox.APP_SCOPE_ID,copied['chat_id'])
            self.assertFalse(set(velox.CHECKLIST_TOOL_NAMES).intersection({velox._role_tool_name(t) for t in tools}))

