    async def test_generation_runs_on_worker_and_duplicate_click_is_single_flight(self) -> None:
        panel = self.panel(); path = Path(self.temp.name) / 'worker.txt'
        entered = threading.Event(); release = threading.Event(); threads = []
        def lines(owner: dict[str, str]) -> Iterable[str]:
            threads.append(threading.get_ident()); entered.set(); release.wait(3)
            yield 'owner=' + owner['identity']; yield 'tail'
        panel._build_debug_export_lines = lines
        owner = {'kind': 'chat', 'identity': self.cid}; panel._request_debug_export_write(owner, path)
        self.assertTrue(await asyncio.to_thread(entered.wait, 3))
        panel._request_debug_export_write(owner, path); tasks = list(panel._debug_export_tasks.values())
        self.assertEqual(len(tasks), 1); owner['identity'] = 'changed'
        release.set(); await asyncio.wait_for(asyncio.gather(*tasks), 5)
        self.assertNotEqual(threads[0], threading.get_ident()); self.assertEqual(len(threads), 1)
        self.assertIn(self.cid, path.read_text()); self.assertNotIn('changed', path.read_text())
        self.assertEqual(panel._debug_export_tasks, {})

    async def test_cancelled_export_drains_worker_without_publishing(self) -> None:
        panel = self.panel(); path = Path(self.temp.name) / 'cancelled.txt'
        entered = threading.Event(); release = threading.Event()
        def lines(owner: dict[str, str]) -> Iterable[str]:
            yield 'head'; entered.set(); release.wait(3); yield 'tail'
        panel._build_debug_export_lines = lines
        panel._request_debug_export_write({'kind': 'chat', 'identity': self.cid}, path)
        self.assertTrue(await asyncio.to_thread(entered.wait, 3))
        task = next(iter(panel._debug_export_tasks.values())); task.cancel(); await asyncio.sleep(.01); release.set()
        with self.assertRaises(asyncio.CancelledError): await task
        self.assertFalse(path.exists()); self.assertEqual(list(Path(self.temp.name).glob('.velox-debug-*.tmp')), [])

