    async def test_cancel_after_publication_reports_committed_file_not_false_cancellation(self) -> None:
        panel = self.panel(); path = Path(self.temp.name) / 'committed.txt'
        entered = threading.Event(); release = threading.Event()
        writer = velox.write_debug_report_atomic
        def publish_then_wait(*args: Any, **kwargs: Any) -> dict[str, Any]:
            result = writer(*args, **kwargs)
            entered.set(); release.wait(5)
            return result
        key = ('chat', self.cid)
        with mock.patch.object(velox, 'write_debug_report_atomic', side_effect=publish_then_wait):
            panel._request_debug_export_write({'kind': key[0], 'identity': key[1]}, path)
            try:
                self.assertTrue(await asyncio.to_thread(entered.wait, 3))
                self.assertTrue(path.is_file())
                task = panel._debug_export_tasks[key]; task.cancel()
                await asyncio.sleep(.01)
            finally:
                release.set()
            with self.assertRaises(asyncio.CancelledError):
                await asyncio.wait_for(task, 3)
        status = panel._debug_export_status[key]
        self.assertEqual(status['state'], 'complete')
        self.assertEqual(status['sha256'], hashlib.sha256(path.read_bytes()).hexdigest())
        self.assertEqual(status['bytes'], path.stat().st_size)
        self.assertEqual(panel._debug_export_tasks, {})

    async def test_repeated_cancellation_keeps_export_registered_until_worker_drains(self) -> None:
        panel = self.panel(); path = Path(self.temp.name) / 'repeat-cancel.txt'
        entered = threading.Event(); release = threading.Event(); drained = threading.Event()
        def lines(owner: dict[str, str]) -> Iterable[str]:
            yield 'head'; entered.set()
            try:
                release.wait(5)
            finally:
                drained.set()
            yield 'tail'
        panel._build_debug_export_lines = lines
        key = ('chat', self.cid)
        panel._request_debug_export_write({'kind': key[0], 'identity': key[1]}, path)
        task = panel._debug_export_tasks[key]
        try:
            self.assertTrue(await asyncio.to_thread(entered.wait, 3))
            task.cancel(); await asyncio.sleep(.01)
            task.cancel(); await asyncio.sleep(.01)
            self.assertFalse(task.done(), 'Cancellation must not abandon a live file writer')
            self.assertIs(panel._debug_export_tasks.get(key), task)
            self.assertEqual(panel._debug_export_status[key]['state'], 'cancelling')
        finally:
            release.set()
            await asyncio.gather(task, return_exceptions=True)
        self.assertTrue(drained.is_set())
        self.assertFalse(path.exists())
        self.assertEqual(panel._debug_export_status[key]['state'], 'cancelled')
        self.assertEqual(panel._debug_export_tasks, {})
        self.assertEqual(list(Path(self.temp.name).glob('.velox-debug-*.tmp')), [])

    async def test_failure_during_cancellation_is_reported_and_worker_is_drained(self) -> None:
        panel = self.panel(); path = Path(self.temp.name) / 'failure-cancel.txt'
        panel.state.add_toast = mock.Mock()
        entered = threading.Event(); release = threading.Event()
        def lines(owner: dict[str, str]) -> Iterable[str]:
            yield 'head'; entered.set(); release.wait(5)
            raise OSError('storage read failed during cancellation')
        panel._build_debug_export_lines = lines
        key = ('chat', self.cid)
        panel._request_debug_export_write({'kind': key[0], 'identity': key[1]}, path)
        task = panel._debug_export_tasks[key]
        try:
            self.assertTrue(await asyncio.to_thread(entered.wait, 3))
            task.cancel(); await asyncio.sleep(.01)
        finally:
            release.set()
        with self.assertRaises(asyncio.CancelledError):
            await asyncio.wait_for(task, 3)
        self.assertEqual(panel._debug_export_status[key]['state'], 'failed')
        self.assertIn('storage read failed', panel._debug_export_status[key]['error'])
        panel.state.add_toast.assert_called_once()
        self.assertFalse(path.exists())
        self.assertEqual(list(Path(self.temp.name).glob('.velox-debug-*.tmp')), [])

    def test_cli_help_reports_current_release_and_strict_data_version(self) -> None:
        output = io.StringIO()
        with mock.patch('sys.stdout', output), self.assertRaises(SystemExit) as exited:
            velox.parse_args(['--help'])
