        self.assertTrue(self.chats.load_chat(self.cid)['agent_reports_suspended'])
        self.assertFalse(any(t.get('agent_report_response_for') for t in self.chats.load_turns(velox.APP_SCOPE_ID,self.cid)))
        fresh=velox.ChatRuntime(self.storage,self.chats,velox.ContextAssembler(self.paths),self.llm,self.tools)
