    async def test_result_arriving_during_candidate_commit_precedes_checklist_prompt(self) -> None:
        store=velox.ChecklistStore(self.storage);owner=velox._chat_checklist_owner(self.cid)
        checklist=store.create(owner,name='Integrate late delivery',items=['Use child evidence'])['checklist_id']
        original=self.runtime._update_turn_io;arrived=False;inside_injection=False
        inject=self.runtime._inject_chat_expert_mode_prompt
        async def injecting(*args: Any,**kwargs: Any) -> Any:
            nonlocal inside_injection
            inside_injection=True
            try:return await inject(*args,**kwargs)
            finally:inside_injection=False
        async def checkpoint(*args: Any,**kwargs: Any) -> Any:
            nonlocal arrived
            updates=args[3] if len(args)>3 else kwargs.get('updates',{})
            if inside_injection and not arrived and updates.get('status')=='complete':
                arrived=True
                self.complete_worker('RESULT ARRIVED DURING CANDIDATE COMMIT')
            return await original(*args,**kwargs)
        def first(_request: LLMRequest) -> list[LLMChunk]:
            return [velox.LLMChunk(text='Waiting on delegated work.',done=True,finish_reason='stop')]
        def second(request: LLMRequest) -> list[LLMChunk]:
            text=json.dumps(request.messages)
            self.assertIn('RESULT ARRIVED DURING CANDIDATE COMMIT',text)
            self.assertNotIn('CHECKLISTS - CONTINUE',text)
            store.update_items(owner,checklist,[{'item_id':'C1','state':'done','comment':'Integrated result'}])
            cycle=store.prepare_verification(owner,checklist)['review_cycle']
            store.apply_review(owner,checklist,[{'item_id':'C1','verdict':'pass','comment':'Checked the result'}],review_cycle=cycle)
            return [velox.LLMChunk(text='Integrated result.',done=True,finish_reason='stop')]
        with mock.patch.object(self.runtime,'_update_turn_io',side_effect=checkpoint), mock.patch.object(self.runtime,'_inject_chat_expert_mode_prompt',side_effect=injecting):
            await self.run_delivery(first,second)
        self.assertTrue(arrived)


