class HandoffIntegrationTests(_AsyncRuntimeFixture):
    def setUp(self) -> None:
        super().setUp()
        self.tools.bind_agent_runtime(self.aruntime)
        self.aruntime.chat_runtime = self.runtime

    async def run_delegation(self, *, fail_child: bool = False) -> tuple[dict[str, Any], list[LLMRequest]]:
        # Exercise actual parent -> native agents_start -> child execution ->
        # durable delivery -> parent integration, not a stubbed handoff method.
        self.chats.set_agent_reports_suspended(self.cid, True)
        parent = self.agents.create_agent(self.cid, 'Delegate a read-only calculation, then integrate its result.',
            title='PARENT', agent_kind=velox.AGENT_KIND_PERSONAL_ASSISTANT, endpoint_profile_id=self.eid)
        requests: list[LLMRequest] = []
        release = asyncio.Event()
        parent_rounds = 0
        original_llm = self.llm
        expected = 'CHILD FAILURE: unreadable input' if fail_child else 'CHILD EVIDENCE: the exact result is 144.'
        class Endpoint:
            def resolve_endpoint(inner, eid: str) -> dict[str, Any]:
                return original_llm.resolve_endpoint(eid)
            async def chat_completions_once_full(inner, request: LLMRequest) -> dict[str, Any]:
                nonlocal parent_rounds
                requests.append(copy.deepcopy(request))
                if request.task_title == 'PARENT':
                    parent_rounds += 1
                    if parent_rounds == 1:
                        return {'text': 'Delegating the bounded calculation.', 'tool_calls': [
                            _make_test_provider_call('launch-child', 'agents_start', {'task': 'Read-only CHILD calculation.'})],
                            'finish_reason': 'tool_calls', 'raw': {}}
                    if parent_rounds == 2:
                        self.assertNotIn(expected, json.dumps(request.messages))
                        asyncio.get_running_loop().call_later(.04, release.set)
                        return {'text': 'Waiting for the result.\n$$AGENT_PROGRESS: {"message":"Done","percent":100}',
                                'finish_reason': 'stop', 'raw': {}}
                    self.assertEqual(parent_rounds, 3, 'Unexpected extra parent inference')
                    self.assertEqual(json.dumps(request.messages).count(expected), 1)
                    return {'text': 'Integrated outcome: ' + expected + '\n$$AGENT_PROGRESS: {"message":"Completed","percent":100}',
                            'finish_reason': 'stop', 'raw': {}}
                await asyncio.wait_for(release.wait(), 2)
                progress = '{"message":"CHILD FAILURE: unreadable input","percent":0,"failed":true}' if fail_child else '{"message":"Completed","percent":100}'
                return {'text': expected + '\n$$AGENT_PROGRESS: ' + progress, 'finish_reason': 'stop', 'raw': {}}
        self.aruntime.llm = Endpoint()
        await asyncio.wait_for(self.aruntime._run_agent(parent['agent_id']), 8)
        await asyncio.sleep(0)
        saved = self.agents.load_agent(parent['agent_id'])
        self.assertEqual(saved['status'], 'succeeded', saved.get('failure_message'))
        self.assertIn(expected, saved['final_output'])
        children = [a for a in self.agents.list_agents(self.cid) if a['parent_agent_id'] == parent['agent_id']]
        self.assertEqual(len(children), 1)
        self.assertEqual(children[0]['status'], 'failed' if fail_child else 'succeeded')
        hidden = [t for t in self.chats.load_turns(velox.APP_SCOPE_ID, self.cid) if t.get('agent_report_id')]
        self.assertEqual(len(hidden), 1)
        self.assertEqual(hidden[0]['agent_report_agent_id'], parent['agent_id'])
        self.assertIn(expected, self.paths.pa_report_markdown(date.today().isoformat()).read_text())
        return saved, requests

    async def test_complete_native_parent_child_success_pipeline(self) -> None:
        _saved, requests = await self.run_delegation()
        self.assertEqual(len(requests), 4)  # three parent rounds, one child round

    async def test_complete_native_parent_child_failure_pipeline(self) -> None:
        _saved, requests = await self.run_delegation(fail_child=True)
        self.assertEqual(len(requests), 4)

    async def test_large_notification_is_explicitly_paged_not_silently_lost(self) -> None:
        agent = self.agent()
        answer = 'Evidence and exact source identifiers. ' * 5000 + 'FINAL TAIL'
        saved = self.agents.update_agent(agent['agent_id'], {'status': 'succeeded', 'final_output': answer, 'final_message': 'Completed'})
        report = self.runtime._agent_report_turn_payload(saved, 'terminal')
        self.assertTrue(report['result_truncated'])
        self.assertEqual(report['result_total_chars'], len(answer))
        self.assertEqual(report['result_next_offset'], 60000)
        self.assertLess(len(report['instruction']), 62000)
        self.assertIn('Do not treat this excerpt as the complete result', report['instruction'])
        ctx = velox.ToolContext(velox.APP_SCOPE_ID, chat_id=self.cid)
        pieces = [answer[:60000]]; offset = 60000
        while offset is not None:
            page = await self.tools.tool_agents_get_result(ctx, {'agent_id': agent['agent_id'], 'offset': offset, 'max_chars': 100000})
            pieces.append(page['result']); offset = page['next_offset']
        self.assertEqual(''.join(pieces), answer)

    def test_child_publication_rechecks_parent_after_concurrent_stop(self) -> None:
        parent = self.agents.create_agent(self.cid, 'Parent', agent_kind=velox.AGENT_KIND_PERSONAL_ASSISTANT)
        original = velox.TaskIdStore.allocate
        def stop_then_allocate(store: Any, key: str) -> int:
            self.agents.update_agent(parent['agent_id'], {'status': 'cancelled'})
