class CallbackBoundaryTests(_AsyncRuntimeFixture):
    async def test_delayed_cleanup_repairs_only_bound_turn_not_new_request(self) -> None:
        self.user()
        old = velox.make_turn(self.cid, 'assistant', 'OLD OWNER', status='streaming')
        self.chats.append_turn(velox.APP_SCOPE_ID, self.cid, old)
        task = asyncio.create_task(asyncio.Event().wait())
        setattr(task, '_velox_chat_stream_turn_ids', {self.cid: {old['turn_id']}})
        task.cancel()
        await asyncio.gather(task, return_exceptions=True)
        entered, release = threading.Event(), threading.Event()
        original = self.chats.load_turns
        def delayed(*args: Any, **kwargs: Any) -> Any:
            entered.set()
            if not release.wait(2):
                raise AssertionError('Orphan cleanup was not released')
            return original(*args, **kwargs)
        try:
            with mock.patch.object(self.chats, 'load_turns', side_effect=delayed):
                self.runtime._consume_running_task_exception(self.cid, task)
                await asyncio.wait_for(asyncio.to_thread(entered.wait), 2)
                fresh = velox.make_turn(self.cid, 'assistant', 'NEW OWNER', status='streaming')
                await asyncio.to_thread(self.chats.append_turn, velox.APP_SCOPE_ID, self.cid, fresh)
                release.set()
                await asyncio.gather(*list(self.runtime._orphan_cleanup_tasks))
            turns = {t['turn_id']: t for t in original(velox.APP_SCOPE_ID, self.cid)}
            self.assertEqual(turns[old['turn_id']]['status'], 'cancelled')
            self.assertEqual(turns[fresh['turn_id']]['status'], 'streaming')
            self.assertEqual(turns[fresh['turn_id']]['text'], 'NEW OWNER')
        finally:
            release.set()

