class ReplayBoundaryCoverageTests(_AsyncRuntimeFixture):
    def setUp(self) -> None:
        super().setUp()
        self.tools.bind_agent_runtime(self.aruntime)
        self.aruntime.chat_runtime = self.runtime

    async def asyncTearDown(self) -> None:
        # A directly invoked runtime uses this test task as the scheduling owner.
        if self.runtime.running.get(self.cid) is asyncio.current_task():
            self.runtime.running.pop(self.cid, None)
        await super().asyncTearDown()

    async def _run_pending_reports(self, count: int = 2) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
        user = self.user('Integrate all saved child reports.')
        assistant = velox.make_turn(self.cid, 'assistant', '', status='streaming', endpoint_profile_id=self.eid)
        self.chats.append_turn(velox.APP_SCOPE_ID, self.cid, assistant)
        self.runtime.running[self.cid] = asyncio.current_task()
        fake = _ScriptedLLM(self.storage, [[velox.LLMChunk(text='INTEGRATED ALL REPORTS', done=True, finish_reason='stop')]])
        self.runtime.llm = fake
        try:
            for index in range(count):
                child = self.agents.update_agent(self.agent()['agent_id'], {'status': 'succeeded', 'final_output': f'Exact child fact {index}'})
                self.runtime.enqueue_agent_report(child)
            await self.runtime._run_assistant_loop(velox.APP_SCOPE_ID, self.cid, assistant['turn_id'], self.eid, user['text'], 'Multiple reports')
            return fake.requests[0].messages, self.messages()
        finally:
            self.runtime.running.pop(self.cid, None)
            workers = list(self.runtime._agent_report_workers.values())
            for worker in workers:
                worker.cancel()
            if workers:
                await asyncio.gather(*workers, return_exceptions=True)

    async def test_multiple_reports_preserve_exact_sent_prefix_after_restart(self) -> None:
        sent, rebuilt = await self._run_pending_reports(3)
        fresh = velox.ChatRuntime(self.storage, velox.ChatStore(self.storage), velox.ContextAssembler(self.paths), self.llm, self.tools)
        replay = fresh._build_messages(velox.APP_SCOPE_ID, self.cid)
        self.assertPrefix(sent, replay)
        self.assertEqual(rebuilt, replay)
        self.assertEqual(sum(bool(m.get('_velox_agent_report_id')) for m in replay), 3)
        self.assertEqual([m['content'].split('Agent report:\n')[-1] for m in replay if m.get('_velox_agent_report_id')],
                         ['Exact child fact 0', 'Exact child fact 1', 'Exact child fact 2'])

    async def test_both_wire_transports_preserve_report_prefix_and_strip_local_markers(self) -> None:
        sent, rebuilt = await self._run_pending_reports(2)
        for prepare, key in ((self.llm._chat_payload_and_headers, 'messages'), (self.llm._responses_payload_and_headers, 'input')):
            before = json.loads(prepare(velox.LLMRequest(velox.APP_SCOPE_ID, self.eid, sent), stream=False)[2])
            after = json.loads(prepare(velox.LLMRequest(velox.APP_SCOPE_ID, self.eid, rebuilt), stream=False)[2])
            self.assertPrefix(before[key], after[key])
            self.assertNotIn('_velox_agent_report_id', json.dumps(after))
            self.assertNotIn('agent_report_delivery_before_turn_id', json.dumps(after))

    async def test_compaction_in_pinned_placeholder_does_not_duplicate_report(self) -> None:
        user = self.user()
        placeholder = velox.make_turn(self.cid, 'assistant', '', status='streaming', endpoint_profile_id=self.eid)
        self.chats.append_turn(velox.APP_SCOPE_ID, self.cid, placeholder)
        blocker = asyncio.create_task(asyncio.Event().wait())
        self.runtime.running[self.cid] = blocker
        child = self.agents.update_agent(self.agent()['agent_id'], {'status': 'succeeded', 'final_output': 'COMPACTION-PRESERVED EVIDENCE'})
        try:
            self.runtime.enqueue_agent_report(child)
            messages = self.messages()
            await self.runtime._consume_ready_agent_reports(velox.APP_SCOPE_ID, self.cid, messages, before_assistant_id=placeholder['turn_id'])
            self.chats.update_turn(velox.APP_SCOPE_ID, self.cid, placeholder['turn_id'], {
                'role': 'compaction', 'status': 'complete', 'compaction_messages': copy.deepcopy(messages),
                'compaction_summary': 'Valid task-memory checkpoint', 'text': 'Checkpoint',
            })
            self.chats.append_turn(velox.APP_SCOPE_ID, self.cid, velox.make_turn(self.cid, 'assistant', 'Continued from checkpoint'))
            rebuilt = self.messages()
            self.assertEqual(json.dumps(rebuilt).count('COMPACTION-PRESERVED EVIDENCE'), 1)
            self.assertPrefix(messages, rebuilt)
        finally:
            self.runtime.running.pop(self.cid, None)
            blocker.cancel()
            for worker in self.runtime._agent_report_workers.values():
                worker.cancel()
            await asyncio.gather(blocker, *list(self.runtime._agent_report_workers.values()), return_exceptions=True)

    def test_projection_is_nonmutating_and_missing_anchor_preserves_report(self) -> None:
        assistant = {'turn_id':'a','role':'assistant','text':'Response'}
        context = {'turn_id':'b','role':'system','text':'Context before inference'}
        report = {'turn_id':'r','role':'system','agent_report_id':'R', 'agent_report_delivered_at':'now',
                  'agent_report_delivery_before_turn_id':'a','text':'Result'}
        rows = [assistant, context, report]
        before = copy.deepcopy(rows)
        ordered = velox.chat_turns_in_inference_order(rows)
        self.assertEqual(rows, before)
        self.assertEqual([t['turn_id'] for t in ordered], ['b','r','a'])
        self.assertEqual(velox.chat_turns_in_inference_order([context,report]), [context,report])

    def test_undelivered_report_cannot_reorder_history(self) -> None:
        rows = [{'turn_id':'a','role':'assistant'}, {'turn_id':'r','role':'system', 'agent_report_id':'R',
                'agent_report_delivery_before_turn_id':'a'}]
        self.assertIs(velox.chat_turns_in_inference_order(rows), rows)


