class TestResultMarkerTests(unittest.TestCase):
    def test_completed_result_marker_matches_only_its_process_and_count(self) -> None:
        with tempfile.TemporaryDirectory() as root:
            path = Path(root) / 'result.json'
            result = unittest.TestResult(); result.testsRun = 3
            with mock.patch.dict(os.environ, {'VELOX_TEST_SUCCESS_MARKER':str(path)}):
                _publish_test_result(result, 3)
            self.assertTrue(_test_result_matches(path, os.getpid(), 3))
            self.assertFalse(_test_result_matches(path, os.getpid()+1, 3))
            self.assertFalse(_test_result_matches(path, os.getpid(), 4))

    def test_incomplete_or_failed_suite_never_publishes_success(self) -> None:
        with tempfile.TemporaryDirectory() as root:
            path = Path(root) / 'result.json'
            result = unittest.TestResult()
            result.testsRun = 1
            with mock.patch.dict(os.environ, {'VELOX_TEST_SUCCESS_MARKER':str(path)}):
                _publish_test_result(result, 2)
                self.assertFalse(path.exists())
                result.failures.append(('test', 'failure details'))
                _publish_test_result(result, 1)
                self.assertFalse(path.exists())

    def test_missing_corrupt_oversized_and_wrong_schema_markers_are_rejected(self) -> None:
        with tempfile.TemporaryDirectory() as root:
            path = Path(root) / 'result.json'
            self.assertFalse(_test_result_matches(path, os.getpid(), 1))
            for raw in (b'OK\n', b'{', b' ' * 5000, b'{"schema":"velox_test_result.v301"}', b'[]'):
                path.write_bytes(raw)
                self.assertFalse(_test_result_matches(path, os.getpid(), 1))

    def test_real_child_marker_cannot_acknowledge_its_parent_process(self) -> None:
        with tempfile.TemporaryDirectory() as root:
            path = Path(root) / 'child-result.json'
            token = uuid.uuid4().hex
            env = dict(os.environ, VELOX_TEST_SUCCESS_MARKER=str(path), VELOX_TEST_RUN_TOKEN=token)
            child = subprocess.Popen([sys.executable, str(Path(__file__).resolve()), '--test-class',
                                      'ChatScrollTests@0:1'], stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)
            output, error = child.communicate(timeout=30)
            self.assertEqual(child.returncode, 0, (output+error).decode(errors='replace'))
            # The completed result is bound to the actual interpreter that ran it,
            # not a Windows virtual-environment launcher pid.
            child_pid = _read_child_identity(path, token)
            self.assertGreater(child_pid, 0, (output + error).decode(errors='replace'))
            self.assertTrue(_test_result_matches(path, child_pid, 1))
            # It never acknowledges the parent or any other process.
            self.assertFalse(_test_result_matches(path, os.getpid(), 1))

    def test_nonzero_process_exit_is_failure_even_with_matching_marker(self) -> None:
        sentinel = unittest.FunctionTestCase(lambda: None)
        inventory = unittest.TestSuite([unittest.TestSuite([sentinel])])
        class Exited:
            pid = 1234567
            def poll(inner) -> int: return 7
        def launch(*_args: Any, **kwargs: Any) -> Any:
            path = Path(kwargs['env']['VELOX_TEST_SUCCESS_MARKER'])
            path.write_text(json.dumps({'schema':f'velox_test_result.v{velox.SOURCE_REVISION}', 'pid':Exited.pid,
                                       'tests':1, 'failures':0, 'errors':0, 'skipped':0, 'successful':True}))
            return Exited()
        with mock.patch.object(unittest.defaultTestLoader, 'loadTestsFromModule', return_value=inventory), \
             mock.patch.object(subprocess, 'Popen', side_effect=launch), \
             mock.patch(f'{__name__}._raw_test_status_write') as status:
            code = run_test_suite()
        self.assertEqual(code, 1)
        self.assertTrue(any('FAILED' in str(call) for call in status.call_args_list))
    class _FakeChild:
        def __init__(
            self,
            *,
            pid: int = 999999999,
            poll_seq: tuple[int, ...] = (0,),
            wait_result: int | None = None,
            wait_raises: BaseException | None = None,
        ) -> None:
            self.pid = pid
            self._poll_seq = list(poll_seq)
            self._wait_result = wait_result
            self._wait_raises = wait_raises
            self.terminated = False
            self.killed = False

        def poll(self) -> int | None:
            if self._poll_seq:
                return self._poll_seq.pop(0)
            return None

        def wait(self, timeout: float | None = None) -> int:
            if self._wait_raises is not None:
                raise self._wait_raises
            return int(self._wait_result if self._wait_result is not None else 0)

        def terminate(self) -> None:
            self.terminated = True

        def kill(self) -> None:
            self.killed = True

    @staticmethod
    def _suite(count: int = 1) -> unittest.TestSuite:
        sentinel = unittest.FunctionTestCase(lambda: None)
        return unittest.TestSuite([unittest.TestSuite([sentinel] * count)])

    @staticmethod
    def _valid_marker(pid: int, count: int, **overrides: Any) -> str:
        payload: dict[str, Any] = {
            "schema": f"velox_test_result.v{velox.SOURCE_REVISION}",
            "pid": pid, "tests": count, "failures": 0, "errors": 0,
            "skipped": 0, "successful": True,
        }
        payload.update(overrides)
        return json.dumps(payload)

    def test_parent_rejects_zero_exit_without_acknowledgement(self) -> None:
        inventory = self._suite()
        fake = self._FakeChild(poll_seq=(0,), wait_result=0)

        def launch(*_args: Any, **_kwargs: Any) -> Any:
            return fake

        with mock.patch.object(unittest.defaultTestLoader, 'loadTestsFromModule', return_value=inventory), \
             mock.patch.object(subprocess, 'Popen', side_effect=launch), \
             mock.patch(f'{__name__}._raw_test_status_write') as status:
            code = run_test_suite()
        self.assertEqual(code, 1)
        text = " ".join(str(call) for call in status.call_args_list)
        self.assertIn("no validated completed-result record", text)

    def test_parent_rejects_zero_exit_with_invalid_record_cases(self) -> None:
        pid = 999999999
        cases: dict[str, bytes | None] = {
            "missing": None,
            "corrupt": b"{",
            "oversized": b" " * 5000,
            "wrong_schema": self._valid_marker(pid, 1, schema="wrong").encode("utf-8"),
            "wrong_count": self._valid_marker(pid, 2).encode("utf-8"),
            "wrong_identity": self._valid_marker(pid + 1, 1).encode("utf-8"),
            "bool_tests": self._valid_marker(pid, 1, tests=True).encode("utf-8"),
            "bool_skipped": self._valid_marker(pid, 1, skipped=True).encode("utf-8"),
            "failures_bool": self._valid_marker(pid, 1, failures=False).encode("utf-8"),
        }
        for name, raw in cases.items():
            with self.subTest(name=name):
                inventory = self._suite()

                def launch(*_args: Any, **kwargs: Any) -> Any:
                    marker = Path(kwargs['env']['VELOX_TEST_SUCCESS_MARKER'])
                    if raw is not None:
                        marker.write_bytes(raw)
                    return self._FakeChild(pid=pid, poll_seq=(0,), wait_result=0)

                with mock.patch.object(unittest.defaultTestLoader, 'loadTestsFromModule', return_value=inventory), \
                     mock.patch.object(subprocess, 'Popen', side_effect=launch), \
                     mock.patch(f'{__name__}._raw_test_status_write') as status:
                    code = run_test_suite()
                self.assertEqual(code, 1, name)

    def test_parent_accepts_zero_exit_with_valid_record(self) -> None:
        pid = 999999999
        inventory = self._suite()

        def launch(*_args: Any, **kwargs: Any) -> Any:
            marker = Path(kwargs['env']['VELOX_TEST_SUCCESS_MARKER'])
            marker.write_text(self._valid_marker(pid, 1))
            return self._FakeChild(pid=pid, poll_seq=(0,), wait_result=0)

        with mock.patch.object(unittest.defaultTestLoader, 'loadTestsFromModule', return_value=inventory), \
             mock.patch.object(subprocess, 'Popen', side_effect=launch), \
             mock.patch(f'{__name__}._raw_test_status_write') as status:
            code = run_test_suite()
        self.assertEqual(code, 0)
        text = " ".join(str(call) for call in status.call_args_list)
        self.assertIn("Ran 1 tests in", text)
        self.assertIn("OK", text)

    def test_parent_accepts_valid_marker_then_finalizer_cleanup_is_distinct(self) -> None:
        pid = 999999999
        inventory = self._suite()

        def launch(*_args: Any, **kwargs: Any) -> Any:
            marker = Path(kwargs['env']['VELOX_TEST_SUCCESS_MARKER'])
            marker.write_text(self._valid_marker(pid, 1))
            return self._FakeChild(
                pid=pid, poll_seq=(), wait_result=0,
                wait_raises=subprocess.TimeoutExpired('child', 5),
            )

        with mock.patch.object(unittest.defaultTestLoader, 'loadTestsFromModule', return_value=inventory), \
             mock.patch.object(subprocess, 'Popen', side_effect=launch), \
             mock.patch(f'{__name__}._raw_test_status_write') as status:
            code = run_test_suite()
        self.assertEqual(code, 0)
        text = " ".join(str(call) for call in status.call_args_list)
        self.assertIn("finalizer cleanup ran", text)

    def test_parent_times_out_before_completed_result_and_reaps(self) -> None:
        pid = 999999999
        inventory = self._suite()
        clock = [0.0]

        def fake_monotonic() -> float:
            clock[0] += 1.0
            return clock[0]

        def launch(*_args: Any, **_kwargs: Any) -> Any:
            return self._FakeChild(pid=pid, poll_seq=(), wait_result=1)

        with mock.patch.object(unittest.defaultTestLoader, 'loadTestsFromModule', return_value=inventory), \
             mock.patch.object(subprocess, 'Popen', side_effect=launch), \
             mock.patch(f'{__name__}._raw_test_status_write') as status, \
             mock.patch('time.monotonic', side_effect=fake_monotonic), \
             mock.patch('time.sleep', side_effect=lambda *a, **k: None):
            code = run_test_suite()
        self.assertEqual(code, 1)
        text = " ".join(str(call) for call in status.call_args_list)
        self.assertIn("exceeded the 1800-second process timeout", text)

    def test_marker_publication_failure_leaves_no_acknowledgement(self) -> None:
        with tempfile.TemporaryDirectory() as root:
            path = Path(root) / 'result.json'
            result = unittest.TestResult()
            result.testsRun = 3
            with mock.patch.dict(os.environ, {'VELOX_TEST_SUCCESS_MARKER': str(path)}), \
                 mock.patch('os.replace', side_effect=OSError('no publication')):
                _publish_test_result(result, 3)
            self.assertFalse(path.exists())
            self.assertFalse(_test_result_matches(path, os.getpid(), 3))




class JsonlAppendHandleTests(unittest.TestCase):
    """Ownership and error handling for the Windows JSONL append handle."""

    @staticmethod
    def _kernel(create_result: Any, closed: list[int]) -> SimpleNamespace:
        def create(*_args: Any, **_kwargs: Any) -> Any:
            return create_result

        def close(handle: int) -> int:
            closed.append(handle)
            return 1

        kernel = SimpleNamespace()
        kernel.CreateFileW = create
        kernel.CloseHandle = close
        return kernel

    @unittest.skipUnless(os.name == "nt", "Windows native handle path")
    def test_create_file_failure_raises_winerror_and_closes_nothing(self) -> None:
        closed: list[int] = []
        kernel = self._kernel(None, closed)
        with tempfile.TemporaryDirectory() as td:
            path = Path(td) / "x.jsonl"
            with mock.patch.object(velox.ctypes, 'WinDLL', return_value=kernel), \
                 mock.patch.object(velox.ctypes, 'get_last_error', return_value=32), \
                 mock.patch('msvcrt.open_osfhandle') as adopt, \
                 mock.patch.object(velox.os, 'fdopen') as fdopen:
                with self.assertRaises(OSError) as cm:
                    velox._open_jsonl_append_handle(path)
        self.assertEqual(getattr(cm.exception, 'winerror', None), 32)
        self.assertEqual(closed, [])
        adopt.assert_not_called()
        fdopen.assert_not_called()

    @unittest.skipUnless(os.name == "nt", "Windows native handle path")
    def test_descriptor_adoption_failure_closes_raw_handle(self) -> None:
        closed: list[int] = []
        kernel = self._kernel(0x1234, closed)
        with tempfile.TemporaryDirectory() as td:
            path = Path(td) / "x.jsonl"
            with mock.patch.object(velox.ctypes, 'WinDLL', return_value=kernel), \
                 mock.patch('msvcrt.open_osfhandle', side_effect=OSError("adopt failed")), \
                 mock.patch.object(velox.os, 'fdopen') as fdopen:
                with self.assertRaises(OSError) as cm:
                    velox._open_jsonl_append_handle(path)
        self.assertIn("adopt failed", str(cm.exception))
        self.assertEqual(closed, [0x1234])
        fdopen.assert_not_called()

    @unittest.skipUnless(os.name == "nt", "Windows native handle path")
    def test_stream_construction_failure_closes_descriptor_not_raw_handle(self) -> None:
        closed: list[int] = []
        kernel = self._kernel(0x1234, closed)
        with tempfile.TemporaryDirectory() as td:
            path = Path(td) / "x.jsonl"
            with mock.patch.object(velox.ctypes, 'WinDLL', return_value=kernel), \
                 mock.patch('msvcrt.open_osfhandle', return_value=7), \
                 mock.patch.object(velox.os, 'fdopen', side_effect=OSError("stream failed")), \
                 mock.patch.object(velox.os, 'close') as close:
                with self.assertRaises(OSError) as cm:
                    velox._open_jsonl_append_handle(path)
        self.assertIn("stream failed", str(cm.exception))
        self.assertEqual(closed, [])
        close.assert_called_once_with(7)

    @unittest.skipUnless(os.name == "nt", "Windows native handle path")
    def test_normal_stream_closure_returns_stream_without_closing(self) -> None:
        closed: list[int] = []
        kernel = self._kernel(0x1234, closed)
        sentinel = object()
        with tempfile.TemporaryDirectory() as td:
            path = Path(td) / "x.jsonl"
            with mock.patch.object(velox.ctypes, 'WinDLL', return_value=kernel), \
                 mock.patch('msvcrt.open_osfhandle', return_value=7), \
                 mock.patch.object(velox.os, 'fdopen', return_value=sentinel), \
                 mock.patch.object(velox.os, 'close') as close:
                result = velox._open_jsonl_append_handle(path)
        self.assertIs(result, sentinel)
        self.assertEqual(closed, [])
        close.assert_not_called()

    @unittest.skipUnless(os.name == "nt", "Windows native handle path")
    def test_stream_construction_failure_secondary_close_failure_preserves_primary(self) -> None:
        closed: list[int] = []
        kernel = self._kernel(0x1234, closed)
        with tempfile.TemporaryDirectory() as td:
            path = Path(td) / "x.jsonl"
            with mock.patch.object(velox.ctypes, 'WinDLL', return_value=kernel), \
                 mock.patch('msvcrt.open_osfhandle', return_value=7), \
                 mock.patch.object(velox.os, 'fdopen', side_effect=OSError("stream failed")), \
                 mock.patch.object(velox.os, 'close', side_effect=OSError("close failed")):
                with self.assertRaises(OSError) as cm:
                    velox._open_jsonl_append_handle(path)
        self.assertIn("stream failed", str(cm.exception))
        self.assertNotIn("close failed", str(cm.exception))

    @unittest.skipUnless(os.name == "nt", "Windows native handle path")
    def test_native_handle_read_write_delete_share_final_close(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            path = Path(td) / "shared.jsonl"
            path.write_bytes(b"seed")
            handle = velox._open_jsonl_append_handle(path)
            try:
                self.assertTrue(handle.writable())
                handle.seek(0, os.SEEK_END)
                handle.write(b"tail")
                handle.flush()
                path.unlink()
                self.assertFalse(path.exists())
            finally:
                handle.close()

    @unittest.skipUnless(os.name == "nt", "Windows native handle path")
    def test_native_controlled_open_failure_retains_winerror_and_path(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            missing = Path(td) / "does-not-exist.jsonl"
            with self.assertRaises(OSError) as cm:
                velox._open_jsonl_append_handle(missing)
            self.assertEqual(getattr(cm.exception, 'winerror', None), 2)
            self.assertEqual(str(cm.exception.filename), str(missing))


class StorageLogDrainTests(unittest.TestCase):
    """Drain behavior for the app-log background writer helper."""

    @staticmethod
    def _fake_storage(log_path: Path) -> SimpleNamespace:
        return SimpleNamespace(log_path=lambda: str(log_path))

    def test_drain_immediate_success(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            log_path = Path(td) / "log.jsonl"
            storage = self._fake_storage(log_path)
            flush_calls: list[tuple[tuple[Any, ...], dict[str, Any]]] = []

            def flush(*args: Any, **kwargs: Any) -> bool:
                flush_calls.append((args, kwargs))
                return True

            writer = mock.Mock()
            writer.flush.side_effect = flush
            with mock.patch.object(velox, 'APP_LOG_WRITER', writer), \
                 mock.patch.object(velox.DATA_ROOTS, 'clear_for_tests') as clear:
                _drain_storage_log_writer(storage)
            self.assertEqual(len(flush_calls), 1)
            self.assertEqual(flush_calls[0][0], ((log_path,),))
            clear.assert_called_once()

    def test_drain_path_scoped_failure_then_global_success(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            log_path = Path(td) / "log.jsonl"
            storage = self._fake_storage(log_path)
            flush_calls: list[tuple[tuple[Any, ...], dict[str, Any]]] = []

            def flush(*args: Any, **kwargs: Any) -> bool:
                flush_calls.append((args, kwargs))
                return len(flush_calls) == 2

            writer = mock.Mock()
            writer.flush.side_effect = flush
            with mock.patch.object(velox, 'APP_LOG_WRITER', writer), \
                 mock.patch.object(velox.DATA_ROOTS, 'clear_for_tests') as clear:
                _drain_storage_log_writer(storage)
            self.assertEqual(len(flush_calls), 2)
            self.assertEqual(flush_calls[0][0], ((log_path,),))
            self.assertEqual(flush_calls[1][0], ())
            clear.assert_called_once()

    def test_drain_exhausted_attempts_fails_without_clear(self) -> None:
        with tempfile.TemporaryDirectory() as td:
            log_path = Path(td) / "log.jsonl"
            storage = self._fake_storage(log_path)

            def flush(*args: Any, **kwargs: Any) -> bool:
                return False

            writer = mock.Mock()
            writer.flush.side_effect = flush
            with mock.patch.object(velox, 'APP_LOG_WRITER', writer), \
                 mock.patch.object(velox.DATA_ROOTS, 'clear_for_tests') as clear:
                with self.assertRaises(RuntimeError):
                    _drain_storage_log_writer(storage)
            clear.assert_not_called()


class ReleaseSchemaTests(_WriterDataRootsIsolatedTestMixin, unittest.TestCase):
    def test_chat_agent_and_turn_models_are_rejected(self) -> None:
        with tempfile.TemporaryDirectory() as root:
            paths, storage, chats = _make_test_chat_stack(Path(root))
            chat = chats.create_chat('Current schema')
            agent = velox.AgentStore(storage).create_agent(chat['chat_id'], 'Current task')
            turn = velox.make_turn(chat['chat_id'], 'user', 'Current request')
            for record, validator in (
                (dict(chat, schema='chat.v301', data_version='v301'), velox.validate_chat_record),
                (dict(agent, schema='agent.v301', data_version='v301'), velox.validate_agent_record),
            ):
                with self.subTest(schema=record['schema']), self.assertRaises(velox.UnsupportedDataVersionError):
                    validator(record)
            turn['schema'] = 'chat_turn.v301'
            with self.assertRaises(velox.UnsupportedDataVersionError):
                velox.validate_chat_turn_record(turn, chat['chat_id'])
            self.assertEqual(velox.APP_SCHEMA, 'velox_app.v303')
            self.assertEqual(velox.AGENT_SCHEMA, 'agent.v303')
            self.assertEqual(velox.SOURCE_REVISION, '303')



